  # --- Galaxy EP banks 5–8 (more of the bank already on disk) ---
  synth_patch(:galaxy_ep3, role: :ep, program: 4, bank: 5, sf2: :galaxy, weight: 2.1, mix: 1.1, fs_gain: 1.55,
