  def dossiers!(audio_root: nil)
    rows = catalog_rows
    tracks = rows.map do |row|
      id = slug(row[:artist], row[:title])
      audio = resolve_local_path(row, audio_root:)
      measured = audio ? DeepAudio.analyze(audio) : nil
      reference = dossier_for(id)
      entry = {
        id:, artist: row[:artist], title: row[:title], source: row[:source],
        youtube_id: row[:youtube_id], audio_file: audio, analysis: measured,
        production_dossier: reference,
        engine_recommendation: reference&.dig(:dilla_engine) || {
          track: "warm_minor_vamp", performer: "yancey", groove_dna: "donuts",
          kicks: "1", speak: "1", mix: "akmd_lofi_mastering"
        }
      }
      if measured && reference && measured[:bpm_estimate] && reference[:bpm]
        delta = (measured[:bpm_estimate] - reference[:bpm]).abs
        if delta > 4
          entry[:calibration_notes] = ["BPM delta #{delta.round(1)} (#{measured[:bpm_estimate]} measured vs #{reference[:bpm]} curated)"]
        end
        entry[:calibration_notes] ||= []
        entry[:calibration_notes] << "Swing: #{measured.dig(:dynamics, :swing_hint)}" if measured.dig(:dynamics, :swing_hint)
      end
      entry
    end
    {
      "meta" => {
        "generated_at" => Time.now.utc.iso8601,
        "manifest" => RADIO_BERGEN_MANIFEST_PATH,
        "tracks" => tracks.length,
        "measured_local" => tracks.count { |t| t[:analysis]&.dig(:measured) },
        "reference_curated" => tracks.count { |t| t[:production_dossier] },
      },
      "cross_track_learnings" => cross_track_learnings,
      "tracks" => tracks,
    }
  end

  def write_dossiers!(audio_root: nil, path: DOSSIERS_PATH)
    data = stringify_keys(dossiers!(audio_root:))
    FileUtils.mkdir_p(File.dirname(path))
    File.write(path, data.to_yaml)
    path
  end

  def stringify_keys(obj)
    case obj
    when Hash then obj.to_h { |k, v| [k.to_s, stringify_keys(v)] }
    when Array then obj.map { |v| stringify_keys(v) }
    else obj
    end
  end

  def write!(audio_root: nil, path: RADIO_BERGEN_SONIC_PATH)
    data = stringify_keys(study!(audio_root:))
    File.write(path, data.to_yaml)
    path
  end
end

# --------------------------------------------------------------------------
# engine part: resolve_config
# --------------------------------------------------------------------------
#
# Style family, BPM, swing and track preset resolution.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def load_radio_bergen_learnings
  return @radio_bergen_learnings if defined?(@radio_bergen_learnings)
  base = Marshal.load(Marshal.dump(INLINE_RADIO_BERGEN_LEARNINGS))
  if File.file?(RADIO_BERGEN_SONIC_PATH)
    file_data = YAML.safe_load(File.read(RADIO_BERGEN_SONIC_PATH), permitted_classes: [Symbol], aliases: true)
    base = merge_sonic_profile_hashes(base, file_data) if file_data.is_a?(Hash)
  end
  if File.file?(PROMOTED_PROFILES_PATH)
    promoted = JSON.parse(File.read(PROMOTED_PROFILES_PATH))
    weights = (base["stream_rotation_weights"] || {}).dup
    promoted.each do |track, count|
      next if track.start_with?("_")
      weights[track.to_s] = (weights[track.to_s] || 0) + count.to_i.clamp(1, 8)
    end
    base["stream_rotation_weights"] = weights
  end
  @radio_bergen_learnings = base
rescue StandardError => e
  warn "radio bergen learnings: #{e.message}"
  @radio_bergen_learnings = Marshal.load(Marshal.dump(INLINE_RADIO_BERGEN_LEARNINGS))
end

def merge_sonic_profile_hashes(base, extra)
  return extra if base.nil?
  return base if extra.nil?
  base.merge(extra) do |_k, left, right|
    left.is_a?(Hash) && right.is_a?(Hash) ? merge_sonic_profile_hashes(left, right) : right
  end
end

def load_sonic_profiles
  return @sonic_profiles if defined?(@sonic_profiles) && @sonic_profiles
  merged = INLINE_SONIC_PROFILES.transform_keys(&:to_sym).transform_values(&:dup)
  extras = load_radio_bergen_learnings["sonic_profiles"]
  if extras.is_a?(Hash)
    extras.each do |key, profile|
      sym = key.to_sym
      merged[sym] = merge_sonic_profile_hashes(merged[sym], profile)
    end
  end
  @sonic_profiles = merged.freeze
end

def radio_bergen_stream_enabled?
  ENV.fetch("RADIO_BERGEN", "1") != "0" && ENV["DILLA_STREAMING"] == "1"
end

def pick_radio_bergen_stream_track!
  return unless radio_bergen_stream_enabled?
  weights = load_radio_bergen_learnings["stream_rotation_weights"]
  return unless weights.is_a?(Hash) && weights.any?
  pool = weights.flat_map { |track, count| Array.new(count.to_i.clamp(1, 12), track.to_s) }
  return if pool.empty?
  picked = render_pick(pool, "stream_track_weight")
  ENV["TRACK"] = picked
  defaults = load_radio_bergen_learnings["stream_env_defaults"]
  if defaults.is_a?(Hash)
    defaults.each do |key, value|
      ENV[key] = value.to_s if ENV[key].nil? || ENV[key].empty?
    end
  end
  RadioBergenStudy.apply_engine_track_dossier!(picked)
  picked
end

def sonic_profile_for(track)
  sym = track.to_sym
  key = TRACK_SONIC_MAP.fetch(sym, nil)
  base = key ? load_sonic_profiles[key] : nil
  return base unless DillaLofiMachine.harmony_profile?(sym)
  synth = (base&.dig("synth") || {}).merge(DillaLofiMachine.lofi_sonic_overlay(sym))
  { "synth" => synth, "harmonic" => base&.dig("harmonic") || {} }
end

def style_family(track, feel: nil)
  if (entry = DillaLofiMachine.profile_entry(track))
    return :wonky if entry[:producer] == :wonky
    return :madlib if entry[:producer] == :madlib
    return :dilla
  end
  return :wonky if WONKY_TRACKS.include?(track.to_sym) || feel == :loose_pocket
  return :dilla if DILLA_TRACKS.include?(track.to_sym) ||
                   %i[timeless organic chromatic_planing syncopated_slash_ninth
                      dilla_slight dilla_drunk madlib_dusty wonky_abstract mpc3000 sp303 sp1200].include?(feel)
  return :madlib if track.to_s.include?("madlib")
  :default
end

# A global tempo trim, so "slow the beats down" scales the whole table rather than
# pinning one number.
#
# Every profile carries its own tempo -- 86 on the Wonky transcriptions, 91 on the
# Slum Village ones, 96 on the harder pockets -- and the distances between them are
# the point. BPM=88 would flatten all of them into one tempo and lose what separates
# a Camel from a Players, so the trim multiplies whatever each track already asked
# for and the relationships survive.
#
# The check is USER_PINNED_ENV, not ENV: the defaults tables write ENV["BPM"]
# themselves, so gating on that would mean the trim silently stopped applying the
# moment any style preset ran. An operator who names a tempo still gets it exactly.
BPM_SCALE_DEFAULT = "0.96"

def bpm_scale
  return 1.0 if USER_PINNED_ENV["BPM"].to_s.strip.match?(/\A\d/)

  scale = (ENV["BPM_SCALE"] || BPM_SCALE_DEFAULT).to_f
  scale.positive? ? scale.clamp(0.5, 1.5) : 1.0
end

# The record sets the tempo, not the other way round.
#
# Every chop was being dragged to one render tempo, and because varispeed is on
# (correctly -- see build_sample_loop_filter) tempo and pitch move together. The
# eight ubrukte_samples chops sit at 73.6 to 122.4 BPM natively; against a fixed
# 92 that is ratio 1.25 down to 0.75, which is +3.9 to -4.9 SEMITONES of
# transposition applied purely as a side effect of a number nobody chose per
# track. It flattens what separates the chops and smears the transients of
# exactly the ones that were most distinct -- eight records rendered as one.
#
# Rendering at the chop's own tempo makes the ratio 1.0: no stretch, no
# transposition, and the tempo variety that was in the source material comes
# back for free. Folded into a single octave first, because a detector reports a
# period and a period reads as half or double its true value -- the same trap
# acapella.rb's BPM_RANGE fell into. 70-140 has no hole in it.
#
# BPM= and a sonic preset still win: an operator naming a tempo means it.
SAMPLE_BPM_FLOOR = 70.0
SAMPLE_BPM_CEILING = 140.0

def fold_to_octave(bpm)
  value = bpm.to_f
  return unless value.positive?

  value *= 2.0 while value < SAMPLE_BPM_FLOOR
  value /= 2.0 while value >= SAMPLE_BPM_CEILING
  value
end

def sample_native_bpm(track)
  return unless ENV.fetch("SAMPLE_NATIVE_BPM", "1") != "0"

  entry = sample_loop_entry(track) or return
  return unless File.file?(entry[:path].to_s)

  fold_to_octave(entry[:bpm])
rescue StandardError => e
  dmesg("native bpm unavailable: #{e.class}", unit: "smpl0", parent: "dilla0")
  nil
end

def resolve_bpm(preset, track, sonic)
  env_bpm = ENV["BPM"]&.to_f
  sonic_bpm = sonic&.dig("synth", "bpm")&.to_f

  # USER_PINNED_ENV, not ENV -- the same distinction bpm_scale draws, and for
  # the same reason. The style tables write ENV["BPM"] themselves, so gating on
  # ENV would mean the record's own tempo never won against a default nobody
  # typed. Only a tempo the operator actually named outranks the record.
  pinned = USER_PINNED_ENV["BPM"].to_s.strip.match?(/\A\d/)
  native = (sample_native_bpm(track) unless pinned)

  base = if pinned
           env_bpm
         elsif native
           dmesg(format("tempo from the record: %.1f bpm (no stretch)", native), unit: "smpl0", parent: "dilla0")
           native
         elsif sonic_bpm&.positive?
           sonic_bpm
         elsif env_bpm&.positive?
           env_bpm
         else
           preset.fetch(:bpm, DEFAULT_BPM).to_f
         end
  (base * bpm_scale).round(2)
end

def resolve_swing(preset, sonic, time_offset)
  return 62.5 if ENV["GOLDEN_SWING"] == "1"
  return ENV["SWING"].to_f if ENV["SWING"]
  sonic_swing = sonic&.dig("synth", "swing")&.to_f
  if DillaLofiMachine.harmony_profile?((ENV["TRACK"] || DillaLofiMachine::DEFAULT_PROFILE).to_s.downcase.tr("-", "_").to_sym)
    return preset.fetch(:swing, 54).to_f + time_offset
  end
  base = if sonic_swing && sonic_swing < 1.0
           DillaLofiMachine.mpc_swing_from_sonic_fraction(sonic_swing) + time_offset
         else
           preset.fetch(:swing, 54).to_f + time_offset
         end
  # Back to 66. This was raised to 72 on the strength of a forum assertion that
  # MPC swing "goes to about 70% on 16ths". Better sources disagree and are more
  # specific: the Dilla swing sits around 53-56%, applied to EIGHTH notes, and
  # the off-kilter quality comes from quantise being off entirely and hits
  # nudged by hand rather than from a high swing percentage. A ceiling of 72
  # permits a value no source supports and invites chasing the wrong parameter.
  #
  # What those sources describe instead is varying degrees of swing across
  # different voices, which is SWING_ROLE_SCALE below. That is the
  # near-polyrhythmic quality; one large global swing is not the same thing and
  # does not sound like it.
  base.clamp(50.0, 66.0)
end

def track_preset(track)
  prod = DillaLofiMachine.profile_preset(track)
  return prod if prod
  return TRACK_PRESETS[track] if TRACK_PRESETS.key?(track)
  base = TRACK_PRESETS[:timeless].dup
  base[:progression] = track if CHORD_PROGRESSIONS.key?(track)
  base
end

def curated_progression?(cfg)
  # A documented transcription is curated by definition.
  #
  # This predicate decides whether a progression loops as written or falls to
  # arrange_fugue_progression, which develops it into exposition/development/
  # recapitulation over a pedal. The four entries from dilla_reference.yml were
  # on neither the local nor the DillaLofiMachine list, so asking for
  # slum_village_players_documented rendered a fugue: the log read
  # "TRACK=slum_village_players_documented BPM=91.0 (fugue)" and the chords that
  # played were D/E, Db/E, C/E, Bm/E, Bbm/E -- a chromatic descent over an E
  # pedal, with no Cm9, Fm9, Bb13 or Ebmaj7 anywhere in it.
  #
  # Developing a transcription defeats the point of transcribing it. Every entry
  # in that file is suffixed _documented, which is the marker used here.
  CURATED_PROGRESSIONS.include?(cfg[:progression].to_sym) ||
    DillaLofiMachine::CURATED_PROGRESSIONS.include?(cfg[:progression].to_sym)
end

def enhanced_resolve_config
  track = (ENV["TRACK"] || DillaLofiMachine::DEFAULT_PROFILE).to_s.downcase.tr("-", "_").to_sym
  preset = track_preset(track)
  prog = (ENV["PROGRESSION"] || preset.fetch(:progression, track)).to_s.downcase.tr("-", "_").to_sym
  sonic = sonic_profile_for(track)
  # DRUM_FEEL names the drum PATTERN vocabulary — DRUM_PATTERN_SETS — and it had
  # no way in. The value came only from the track preset, so a set no preset
  # declared could not be reached at all: dilla_canon, wonky_canon and one_drop
  # were written, commented, and selected by nothing. dilla_canon is the one
  # carrying Dilla's own kick anchors (0/3/10), the ghosts and the displaced
  # snares, in an engine named after him.
  #
  # Not to be confused with GROOVE_FEEL, which is the microtiming TICK table in
  # DillaGroove::GROOVE_FEELS (boom_bap/dilla_drag/camel). The two share the word
  # "feel", have disjoint vocabularies, and feed different code paths — setting
  # GROOVE_FEEL=dilla_canon silently gives you dilla_drag timing and whatever
  # patterns the track already had, which reads as the knob working.
  #
  # Default is unchanged, so no existing render moves.
  feel = (ENV["DRUM_FEEL"].to_s.strip.empty? ? nil : ENV["DRUM_FEEL"].downcase.tr("-", "_").to_sym) ||
         preset[:feel] || :default
  family = style_family(track, feel:)
  {
    track:,
    bpm: resolve_bpm(preset, track, sonic),
    progression: prog,
    chord_bars: resolve_chord_bars(preset),
    phrase_bars: preset[:phrase_bars],
    swing: resolve_swing(preset, sonic, time_of_day_swing_offset),
    feel:,
    stereo_pan: preset[:stereo_pan] || false,
    timing: preset[:timing],
    quintuplet: ENV["QUINTUPLET"] ? ENV["QUINTUPLET"] != "0" : (preset[:quintuplet] || false),
    sonic:,
    style_family: family,
    sidechain: ENV["SIDECHAIN"] != "0" && (family == :wonky || preset[:sidechain] || sonic&.dig("synth", "sidechain_pump")),
    no_quantize: ENV["NO_QUANTIZE"] == "1" || (family == :wonky && ENV["NO_QUANTIZE"] != "0"),
    golden_swing: ENV["GOLDEN_SWING"] == "1",
    voicing: (ENV["VOICING"] || preset[:voicing] || (family == :wonky ? :quartal : :spread)).to_sym,
    engine_progression: sonic&.dig("harmonic", "engine_progression")&.to_sym,
    half_time_bars: preset[:half_time_bars],
    # INTRO_BARS overrides the preset. There was no way to say "start on the
    # one" — the value came only from the track preset, and SECTION_LAYER_GAIN
    # mutes drums outright for the whole intro (drums: 0.0, sample: 0.55). On a
    # 16-bar beat the default 4 bars is a quarter of the render with no drums
    # under it, and the rap vocal is not section-gated, so it plays alone for
    # ten seconds at 96 BPM before anything joins it.
    #
    # That is the right default for a full track and the wrong one for a loop.
    # INTRO_BARS=0 starts everything on bar one; the default is unchanged.
    intro_bars: (ENV["INTRO_BARS"].to_s.strip.empty? ? nil : ENV["INTRO_BARS"].to_i) ||
                preset.fetch(:intro_bars, family == :wonky ? 8 : 4),
    master_lufs: resolve_master_lufs(family, sonic),
    master_lra: resolve_master_lra(family, sonic),
    # Full darken (1.0) on Wonky was muting kick beater + snare air under pads.
    mood_darken_strength: if family == :dilla
                            deep_render? ? 0.36 : 0.55
                          elsif family == :wonky || camel_mode?
                            0.42
                          else
                            0.75
                          end,
  }
end

# The pad EQ's low-mid gain, in dB.
#
# warm_dilla_pad_post boosted 260 Hz by 2.0 dB and 520 Hz by 1.8 dB (1.2 dB at
# 260 on the fluidsynth branch). That is the middle of the 200-500 Hz band every
# hip-hop mixing source names as "mud" and says to cut -- so the pad was lifted
# exactly where a mix gets congested, and then rolled off at 3.4 kHz where its
# definition lives. Muddy and dull from the same chain.
#
# Measured on an instrumental render, relative to full band: 125 Hz -3.1 dB,
# 250 Hz -5.1, 500 Hz -10.0, 1 kHz -15.1, 2 kHz -21.2, 4 kHz -27.5, 8 kHz -32.8.
# A steady ~6 dB/octave slide with 125 Hz the loudest band. Nothing was clipping
# (crest 12.0 dB, flat factor 0.0), so the "overdrive" was this tilt rather than
# level -- which is why chasing it through the saturation stages found nothing.
#
# Default 0.0: the boosts are removed, not inverted. Operator chose "cut the mud
# boosts" on 2026-08-09; turning them negative would be a tone decision made by
# measurement rather than by ear, which is his call and not this function's.
# PAD_MUD_DB takes a negative number when he wants the actual dip.
#
# The scale argument keeps the three bands' RELATIVE weighting: 520 Hz was 0.9x
# the 260 Hz boost and the fluidsynth branch 0.6x, so a single knob moves all
# three together in the proportion they were tuned in.
def pad_mud_db(scale = 1.0)
  ((ENV["PAD_MUD_DB"] || "0.0").to_f * scale).round(2)
end

# Where render_singers_chop_pads high-passes its pad stem.
#
# Scope note, because the first version of this comment claimed more: this is
# ONE pad path, not the pad bus. The main chain is warm_dilla_pad_post, which
# has no high-pass at all -- so a render that never calls the singers-chop
# renderer is untouched by this, and measuring one proved it (80-140 Hz band
# identical before and after, null residual -41 dB, i.e. render noise).
#
# It is still a real fix, a latent one: the literal 140 was correct while
# build_voicing folded every chord into MIDI 50..62 (147..247 Hz), where the
# filter sat below the lowest root and only removed rumble.
#
# Lowering the chord register to 43..55 (98..196 Hz) for "slower deeper chords"
# broke that relationship silently. Measured: a 98 Hz root through highpass
# f=140 comes out 7.1 dB down (-28.2 dB against -21.1 dB unfiltered). The root
# becomes the QUIETEST note in the chord, so the voicing is heard through its
# upper partials -- thinner and more strident, not deeper. Chasing that as a
# saturation problem is chasing the wrong stage.
#
# Derived from the register rather than pinned, so the two cannot drift apart
# again: whatever CHORD_REGISTER_LOW says, this stays a little below it.
#
# 0.85 of the lowest root, capped at the historical 140 so this can only ever
# open the filter DOWN from where it was, never up into the chords. At the
# default register that is 83 Hz -- still above the sub bus (32..64 Hz) and the
# kick fundamental, so the pads keep out of the low end while keeping their own
# roots.
#
# General mixing practice is to high-pass pads at 150-200 Hz and leave the
# bottom to kick and bass. That advice assumes pads voiced above it. Here the
# operator has deliberately voiced them lower, so the filter follows the music
# rather than the rule of thumb. PAD_HP pins it if that turns out wrong.
def pad_highpass_hz
  pinned = ENV["PAD_HP"].to_s.strip
  return pinned.to_f.clamp(20.0, 400.0).round if pinned =~ /\A[\d.]+\z/

  lowest_root = 440.0 * (2.0**((DillaProducerDNA::CHORD_REGISTER_LOW - 69.0) / 12.0))
  [(lowest_root * 0.85), 140.0].min.clamp(20.0, 140.0).round
end

# How many bars each chord is held for.
#
# Operator direction on 2026-08-09 was "slower deeper chords always". This is
# the "slower" half; CHORD_REGISTER_LOW/HIGH in producer_dna.rb is the "deeper".
#
# The preset value is MULTIPLIED rather than replaced, so the relative shape of
# the catalogue survives: a preset that moved twice as fast as its neighbour
# still does. Measured over TRACK_PRESETS, the distribution was 10 presets at 1
# bar per chord, 55 at 2 and 6 at 4 -- so most of the catalogue changed chord
# every two bars, which at 88 BPM is about 5.5 seconds.
#
# There was no override at all before this: chord_bars came only from the preset
# literal, so there was no way to slow the harmony down short of editing 71
# presets by hand.
#
# CHORD_BARS pins an absolute value, CHORD_SLOWDOWN scales the preset's.
def resolve_chord_bars(preset)
  pinned = ENV["CHORD_BARS"].to_s.strip
  return pinned.to_i.clamp(1, 32) unless pinned.empty? || pinned.to_i.zero?

  base = preset.fetch(:chord_bars, 4)
  factor = (ENV["CHORD_SLOWDOWN"] || "2").to_f
  factor = 1.0 unless factor.positive?
  # Ceil, so a fractional factor still moves a 1-bar preset rather than
  # rounding back down to where it started.
  (base * factor).ceil.clamp(1, 32)
end

def resolve_master_lufs(family, sonic)
  texture = sonic&.dig("synth", "texture").to_s
  return -20.0 if family == :dilla && texture.include?("donuts")
  MASTER_LUFS_BY_STYLE.fetch(family, MASTER_LUFS_BY_STYLE[:default])
end

def resolve_master_lra(family, sonic)
  texture = sonic&.dig("synth", "texture").to_s
  return 14.5 if family == :dilla && texture.include?("donuts")
  LRA_BY_STYLE.fetch(family, LRA_BY_STYLE[:default])
end

# --------------------------------------------------------------------------
# engine part: ringtone_layer
# --------------------------------------------------------------------------

# RINGTONE_LAYER=1 — the ringtone.tools devices, as one decision.
#
# lib/devices.rb carries four primitives ported from ringtone.tools: Copy Machine
# (one source played n times at once, the copies drifting in pitch and time), the
# Low Pass Gate (a note device whose decay darkens), wav_Map (an image read as a
# wavetable) and P_4L's voice stack (seven Plaits models under one macro knob).
# Each is measured and each is documented, and each was reachable only through its
# own off-by-default ENV knob -- COPY_MACHINE, LPG, WAV_MAP, VOICE_STACK. Four
# switches nobody flips together is four devices nobody hears together, which is
# how a whole shelf of built work stayed inaudible.
#
# This is the one switch. It sets the individual knobs as DEFAULTS, so an explicit
# COPY_MACHINE=0 or LPG_BLEND=0.4 still wins -- the layer is a starting position,
# not an override.
#
# wav_Map is deliberately NOT turned on here. It needs an image, and there is no
# sensible default picture; pass WAV_MAP=<path> and it joins the layer.
#
# The layer sits where the operator asked for it: audible as an effect, not as
# texture. Copy Machine runs the six copies its own default suggests, the LPG
# blends fully with a longer and droopier decay, and the voice stack doubles.
#
# It was conservative before -- three copies, 0.7 blend -- on the reasoning that
# Copy Machine replaces the bed and the bed is the loudest sampled thing in a
# render. That reasoning is sound and the numbers were still too quiet to hear.
#
# Wrapped in RingtoneLayer: dilla_resolve_config is the only external caller and
# it runs long after every part has loaded, so the qualified name costs nothing
# there. module_function keeps ringtone_layer_apply_env! callable bare from
# inside this module, which is what the load-time call at the bottom needs.
module RingtoneLayer
  module_function

  RINGTONE_LAYER_DEFAULTS = {
    "COPY_MACHINE" => "6",
    "COPY_MACHINE_FAMILY" => "harmonic",
    "COPY_MACHINE_REVERSE" => "0.35",
    "COPY_MACHINE_WIDTH" => "1.0",
    "COPY_MACHINE_DRIFT" => "320",
    "LPG" => "1",
    "LPG_BLEND" => "1.0",
    "LPG_DEPTH" => "1.0",
    "LPG_DECAY_MS" => "360",
    "LPG_DROOP" => "3.0",
    "VOICE_STACK" => "6",
  }.freeze

  # On by default: the ringtone.tools foley — the bleeps, bloops and space-echoed
  # texture — is part of the signature, not a flag someone has to remember.
  def ringtone_layer_enabled? = ENV.fetch("RINGTONE_LAYER", "1") != "0"

  # Applied from dilla_resolve_config so every entry point gets it -- a render, the
  # demo, the stream -- rather than only the one that remembered to call it.
  def ringtone_layer_apply_env!
    return false unless ringtone_layer_enabled?
    return false if @ringtone_layer_applied

    @ringtone_layer_applied = true
    RINGTONE_LAYER_DEFAULTS.each { |k, v| ENV[k] ||= v }
    true
  end

  def ringtone_layer_describe
    return "ringtone layer: off" unless ringtone_layer_enabled?

    on = RINGTONE_LAYER_DEFAULTS.keys.map { |k| "#{k}=#{ENV[k]}" }
    on << "WAV_MAP=#{File.basename(ENV['WAV_MAP'].to_s)}" if File.file?(ENV["WAV_MAP"].to_s)
    "ringtone layer: #{on.join(' ')}"
  end

  # Applied at load rather than from dilla_resolve_config, because the render does
  # not go through that function -- wiring it there set the knobs in a process the
  # render never asked, and the devices ran on their own fallbacks while the log
  # said the layer was on. Load time is the only point every entry share.
  ringtone_layer_apply_env!
end

# --------------------------------------------------------------------------
# engine part: progression_build
# --------------------------------------------------------------------------
#
# Progression generators: Coltrane changes, tritone subs, backdoors, modal interchange.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def chord_from_quality(root_hz, quality, voices: 5)
  intervals = CHORD_TEMPLATES.fetch(quality)
  hz = intervals.map { |iv| (root_hz * (2**(iv / 12.0))).round(2) }
  extra = intervals.max + 2
  hz << (root_hz * (2**(extra / 12.0))).round(2) while hz.length < voices
  hz.sort.first(voices)
end

def chord_intervals_from_hz(hz)
  midis = hz.map { |h| hz_to_midi(h) }.sort
  root = midis.first
  midis.map { |m| ((m - root) % 12).round }.uniq
end

# mode: is accepted and ignored. route_generated_style passes the same four
# keywords to every generator, and this was the one signature that did not take
# it — so the major_third_cycle_full track raised "unknown keyword: :mode" on every render,
# failed its retry, and demo-all substituted a silence placeholder. It shipped
# 33 seconds of silence into the middle of the demo at -70 LUFS.
#
# Ignoring it is correct rather than lazy: Coltrane changes are a fixed cycle of
# major thirds, which is the point of them. They do not vary by mode. The other
# four routes all accept the keyword.
def generate_coltrane_changes(root_hz:, mode: nil, length: 8, seed: nil)
  rng = seed ? Random.new(seed) : Random.new
  offsets = [0, 4, 8] # major thirds
  start = offsets.sample(random: rng)
  Array.new(length) do |i|
    semitone = start + offsets[i % 3]
    root = root_hz * (2**(semitone / 12.0))
    q = %w[maj9 m9 7].sample(random: rng)
    { name: "major_third_cycle_full#{semitone}#{q}", hz: chord_from_quality(root, q) }
  end
end

# Tritone substitution: a dominant (V7) shares its tritone (3rd+7th) with
# the dominant chord a tritone (6 semitones) away, so replacing one for the
# other keeps the same pull toward resolution while the bass moves
# chromatically into the tonic instead of by a 4th/5th. Real, well-defined
# jazz theory (not a producer's signature move) -- substitutes at degree 5
# with sub_chance, same functional-motion engine as generate_progression.
def generate_tritone_sub_progression(root_hz:, mode: :minor, length: 8, seed: nil, sub_chance: 0.45)
  rng = seed ? Random.new(seed) : Random.new
  semitones = SCALE_SEMITONES.fetch(mode)
  quality_for = SCALE_DEGREE_QUALITY.fetch(mode)
  degree = 1
  Array.new(length) do
    substituted = degree == 5 && rng.rand < sub_chance
    chord_root = if substituted
                   root_hz * (2**((semitones[(degree - 1) % 7] + 6) / 12.0))
                 else
                   root_hz * (2**(semitones[(degree - 1) % 7] / 12.0))
                 end
    quality = substituted ? "7" : quality_for.fetch(degree, "m9")
    label = substituted ? "trisub#{degree}7" : "deg#{degree}#{quality}"
    chord = { name: label, hz: chord_from_quality(chord_root, quality) }
    degree = weighted_pick(rng, DEGREE_TRANSITIONS.fetch(degree, { 1 => 1 }))
    chord
  end
end

def generate_backdoor_progression(root_hz:, mode: :minor, length: 8, seed: nil)
  rng = seed ? Random.new(seed) : Random.new
  semitones = SCALE_SEMITONES.fetch(mode)
  degree = 1
  transitions = DEGREE_TRANSITIONS.merge(5 => { 1 => 2, 6 => 4, 4 => 1, 3 => 3 })
  quality_for = SCALE_DEGREE_QUALITY.fetch(mode).merge(4 => "7alt", 7 => "7#11")
  Array.new(length) do
    quality = quality_for.fetch(degree, "m9")
    quality = "7alt" if degree == 5 && rng.rand < 0.35
    chord_root = root_hz * (2**(semitones[(degree - 1) % 7] / 12.0))
    chord = { name: "bk#{degree}#{quality}", hz: chord_from_quality(chord_root, quality) }
    degree = weighted_pick(rng, transitions.fetch(degree, { 1 => 1 }))
    chord
  end
end

def generate_slash_progression(root_hz:, mode: :minor, length: 8, seed: nil)
  rng = seed ? Random.new(seed) : Random.new
  pedal = root_hz
  semitones = SCALE_SEMITONES.fetch(mode)
  degree = 0
  Array.new(length) do
    step = semitones[degree % semitones.length] + (degree / semitones.length) * 12
    upper_root = root_hz * (2**(step / 12.0))
    q = rng.rand < 0.5 ? "maj9" : "m9"
    hz = chord_from_quality(upper_root, q, voices: 4)
    hz[0] = pedal
    degree += weighted_pick(rng, PLANING_STEP_WEIGHTS)
    { name: "slash#{step}#{q}", hz: hz.sort }
  end
end

def generate_modal_interchange(root_hz:, mode: :minor, length: 8, seed: nil)
  rng = seed ? Random.new(seed) : Random.new
  pool = mode == :minor ? [1, 4, 5, 6, 3, 2, 7, 4, 6] : [1, 2, 3, 4, 5, 6, 7, 6, 4]
  semitones = SCALE_SEMITONES.fetch(mode)
  borrow = { 4 => "maj9", 6 => "maj9", 3 => "aug", 7 => "dim" }
  Array.new(length) do |i|
    degree = pool[i % pool.length]
    q = borrow[degree] || SCALE_DEGREE_QUALITY.fetch(mode).fetch(degree, "m9")
    q = PLANING_QUALITIES.sample(random: rng) if rng.rand < 0.2
    root = root_hz * (2**(semitones[(degree - 1) % 7] / 12.0))
    { name: "mod#{degree}#{q}", hz: chord_from_quality(root, q) }
  end
end

# Delegates to DillaHarmony (harmony_engine.rb) so this and hz_to_midi/midi_to_hz
# below can't drift into different rounding, the way theory_runtime.rb's copies
# once did (see its comment) before being fixed the same way.
def root_motion_semitones(a, b)
  DillaHarmony.root_motion_semitones(a, b)
end

# A fugue's recapitulation restating the exposition note-for-note in the
# same voicing reads as static — real recaps land the same material in a
# different register/spacing so the return feels like arrival, not replay.
CONTRAST_VOICINGS = {
  quartal: :drop2, drop2: :cluster, cluster: :spread,
  spread: :quartal, drop3: :spread
}.freeze

def enrich_progression(pads, cfg, phases: [])
  DillaHarmony.enrich_progression(pads, cfg, phases:)
end

def progression_from_engine(sonic, _fallback_mode)
  chord_names = sonic&.dig("harmonic", "engine_chords")
  if chord_names&.any?
    return chord_names.map do |n|
    end.compact
  end
  name = sonic&.dig("harmonic", "engine_progression")&.to_sym
  return unless name && CHORD_PROGRESSIONS.key?(name)
  CHORD_PROGRESSIONS.fetch(name).map do |n|
    PAD_CHORD_LOOKUP[n] || MODAL_MINOR_CHORDS.find { |c| c[:name] == n }
  end.compact
end

def arrange_fugue_progression(pads, needed_chords, cfg)
  return pads if pads.empty?
  hook = pads
  exposition = [(needed_chords * 0.25 / hook.length).ceil, 2].max
  development_len = [(needed_chords * 0.35).round, 2].max
  recapitulation = [(needed_chords * 0.25).round, hook.length].max
  coda = [needed_chords - (exposition * hook.length) - development_len - recapitulation, 0].max

  dev_root = hook.last[:hz].min * (cfg[:style_family] == :wonky ? (2**(3.0 / 12.0)) : 1.0)
  dev_style = case cfg[:progression]
              when :planing then :planing
              when :chromatic_mediant then :chromatic_mediant
              else :functional
              end
  development = case dev_style
                when :planing
                  generate_planing_progression(root_hz: dev_root, length: development_len, seed: stable_hash(cfg[:track]))
                when :chromatic_mediant
                  generate_chromatic_mediant_progression(root_hz: dev_root, length: development_len, seed: stable_hash(cfg[:track]))
                else
                  generate_progression(root_hz: dev_root, mode: :minor, length: development_len, seed: stable_hash(cfg[:track]))
                end

  intro_hook = Array.new(exposition) { hook }.flatten
  recap = hook.first(recapitulation)
  outro = coda.positive? ? (hook * (coda / hook.length.to_f).ceil).first(coda) : []
  arranged = intro_hook + development + recap + outro

  phases = []
  intro_hook.length.times { phases << :exposition }
  development.length.times { phases << :development }
  recap.length.times { phases << :recapitulation }
  outro.length.times { phases << :coda }

  [arranged.first(needed_chords), phases.first(needed_chords)]
end

LA_BEAT_SECTION_STYLES = %i[hook functional chromatic_mediant neo_soul quartal].freeze
# No :planing — generate_planing_progression names like planing0m9 sound random/ugly.
CAMEL_LA_BEAT_STYLES = %i[hook chromatic_mediant functional bridge].freeze
CAMEL_BRIDGE_SYMS = %w[Gm7 Cm11nc Fm9 Bbm9 Eb7 AbMaj13s11 Dmaj9nc DMaj7overG].freeze
CAMEL_FUNCTIONAL_SYMS = %w[Dm9 Gm9 Cm9 Fmaj9 Bbm9 Ebmaj9 Abmaj9 Dbmaj9].freeze
LA_BEAT_MIDI_FX_ROTATE = [
  { cc: 1, rate_hz: 0.22, depth: 52, base: 38, curve: :sine },
  { cc: 74, rate_hz: 0.16, depth: 42, base: 28, curve: :swell },
  { cc: 91, rate_hz: 0.12, depth: 30, base: 22, curve: :sine },
  { cc: 5, rate_hz: 0.18, depth: 24, base: 48, curve: :sine },
  { bend: true, rate_hz: 0.14, depth_cents: 18 },
].freeze

# True when the canonical dilla DNA path is active (RENDER_MODE dilla).
# Historical name camel_mode? kept as alias — camel was merged into dilla.
def dilla_style?
  normalize_render_mode!
  ENV["RENDER_MODE"].to_s.downcase == "dilla"
end
alias camel_mode? dilla_style?

# Single engine mode. Empty RENDER_MODE → dilla. Optional knobs stay as ENV
# (STREAM_COMFORT, RENDER_MODE=warp|long_soul|…), not command aliases.
def normalize_render_mode!
  ENV["RENDER_MODE"] = DEFAULT_RENDER_MODE if ENV["RENDER_MODE"].to_s.strip.empty?
end

def camel_drum_entry_bar
  ENV.fetch("CAMEL_DRUM_ENTRY_BAR", "0").to_i
end

def camel_keep_wonky_on_breakdown?
  ENV.fetch("CAMEL_KEEP_WONKY", camel_mode? ? "1" : "0") != "0"
end

def la_beat_progression_enabled?
  # Do NOT force LA-beat on Camel — that injected random planing0m9-style
  # chords and made streams sound broken. Opt in: LA_BEAT_PROGRESSION=1.
  ENV.fetch("LA_BEAT_PROGRESSION", "0") != "0"
end

def soul_progression_locked?
  ENV["STREAM_SOUL"] == "1" && ENV.fetch("STREAM_LOCK", "0") == "1"
end

# The progression follows the track unless the caller pinned one.
#
# This stays out of stream(), where it read
# `unless user_pad_locked && ENV["PROGRESSION"] && !ENV["PROGRESSION"].empty?`,
# which skipped the assignment whenever PAD_VOICE or PAD_ARP_MODE was set — and
# PROGRESSION is never empty, because apply_best_defaults! fills it with
# pedal_e_descent. So asking for a specific pad voice silently froze the harmony
# on the default track: `STREAM_TRACK=slum_village_players_documented
# PAD_VOICE=prophet` rendered, and logged, the documented transcription's name
# at its documented 91 BPM while playing pedal_e_descent's chords — D/E, Db/E,
# C/E, Bm/E, Bbm/E, Am/E. curated_progression? was true and the loop arranger
# ran; it looped the wrong six chords faithfully, which is why the render looked
# correct in every log line except the chords themselves.
#
# Same shape as the two failures already recorded in this file (track presets
# overwriting RAP_VOCAL=0, the lead guard inferring intent from LEAD_VOICE
# alone): a guard reading an unrelated key instead of what was actually asked
# for. USER_PINNED_ENV is the thing that knows.
def sync_progression_to_track!(track)
  pinned = USER_PINNED_ENV["PROGRESSION"].to_s
  dmesg("sync progression #{ENV['PROGRESSION'].inspect}→#{pinned.empty? ? track : "(pinned #{pinned})"}",
        unit: "harm0", parent: "dilla0")
  return unless pinned.empty?

  ENV["PROGRESSION"] = track.to_s
end

# LA beat / Wonky stream — stitch random long sections with variable bar lengths
# instead of looping the first four bars forever.
def arrange_la_beat_progression(pads, needed_chords, cfg)
  return arrange_loop_progression(pads, needed_chords, cfg) + [nil] if pads.empty?

  rng = Random.new(patch_cycle_seed(needed_chords + stable_hash(cfg[:track].to_s)))
  hook = pads
  out = []
  phases = []
  chord_lens = []

  while out.length < needed_chords
    style = LA_BEAT_SECTION_STYLES[rng.rand(LA_BEAT_SECTION_STYLES.length)]
    take = rng.rand(3..8)
    root_hz = (out.last || hook.first)[:hz].min
    section = case style
              when :hook
                hook
              when :functional
                generate_progression(root_hz:, mode: :minor, length: take, seed: rng.rand(1..99_999))
              when :planing
                generate_planing_progression(root_hz:, length: take, seed: rng.rand(1..99_999))
              when :chromatic_mediant
                generate_chromatic_mediant_progression(root_hz:, length: take, seed: rng.rand(1..99_999))
              when :neo_soul, :quartal
                voice_lead_chords(generate_progression(root_hz:, mode: :minor, length: take,
                                                       seed: rng.rand(1..99_999)))
              else
                hook
              end
    section.each do |ch|
      break if out.length >= needed_chords
      out << ch
      phases << %i[exposition main development recapitulation].sample(random: rng)
      chord_lens << rng.rand(1..4)
    end
  end
  [out.first(needed_chords), phases.first(needed_chords), chord_lens.first(needed_chords)]
end

def camel_section_pads(style, hook, root_hz, take, rng)
  case style
  when :hook
    hook
  when :bridge
    bridge = CAMEL_BRIDGE_SYMS.filter_map { |n| learned_chord_pad(n) }
    bridge.length >= 2 ? bridge : hook
  when :chromatic_mediant
    generate_chromatic_mediant_progression(root_hz:, length: take, seed: rng.rand(1..99_999))
  when :functional
    base = CAMEL_FUNCTIONAL_SYMS.filter_map { |n| learned_chord_pad(n) }
    base = curated_progression_pads(:timeless_authentic) if base.length < 4
    base = curated_progression_pads(:maj7_minor_cycle) if base.length < 4
    if base&.length.to_i >= 2
      base.cycle.take(take).to_a
    else
      generate_progression(root_hz:, mode: :minor, length: take, seed: rng.rand(1..99_999))
    end
  when :planing
    generate_planing_progression(root_hz:, length: take, seed: rng.rand(1..99_999))
  else
    hook
  end
end

# Camel stream — chromatic mediant hook + D-minor functional/planing bridges (never 4-bar loop lock).
def arrange_camel_beat_progression(pads, needed_chords, cfg)
  hook = if pads.empty?
           curated_progression_pads(:chromatic_mediant_drift) || []
         else
           pads
         end
  return arrange_loop_progression(hook, needed_chords, cfg) + [nil] if hook.length < 2

  rng = Random.new(patch_cycle_seed(needed_chords + stable_hash(cfg[:track].to_s) + 86))
  out = []
  phases = []
  chord_lens = []
  styles = CAMEL_LA_BEAT_STYLES

  while out.length < needed_chords
    style = styles[rng.rand(styles.length)]
    style = :hook if out.empty?
    take = rng.rand(4..10)
    root_hz = (out.last || hook.first)[:hz].min
    section = camel_section_pads(style, hook, root_hz, take, rng)
    section.each do |ch|
      break if out.length >= needed_chords
      out << ch
      phases << case style
                when :hook then :exposition
                when :bridge then :turn
                when :chromatic_mediant then :development
                when :planing then :build
                else :main
                end
      chord_lens << rng.rand(1..4)
    end
  end
  [out.first(needed_chords), phases.first(needed_chords), chord_lens.first(needed_chords)]
end

# Curated hooks loop as written — no random generative development section
# wedged into the middle of a Donuts/Slum transcription.
def arrange_loop_progression(pads, needed_chords, _cfg)
  return [pads, []] if pads.empty?
  hook = pads
  looped = (hook * (needed_chords.to_f / hook.length).ceil).first(needed_chords)
  total_cycles = (needed_chords.to_f / hook.length).ceil
  phases = looped.each_with_index.map do |_chord, i|
    cycle = i / hook.length
    pos = i % hook.length
    if cycle.zero?
      :exposition
    elsif cycle >= total_cycles - 1 && pos >= [hook.length - 2, 0].max
      :recapitulation
    else
      :main
    end
  end
  [looped, phases]
end

# The pool the loop rotates through instead of repeating one progression eight
# times. All four documented transcriptions are centred on C — Slum Village in C
# minor, Flying Lotus in C major — so the movement between them is parallel
# major/minor, the modal interchange both producers actually used, not a key
# jump. A render that stays on one four-chord loop for two minutes is the exact
# "sounds the same the whole way through" the operator heard; rotating whole
# progressions across the sections is what fixes it. Off with PROG_ROTATE=0,
# which falls straight back to arrange_loop_progression.
PROG_ROTATION_POOL = %i[
  slum_village_intro_documented flylo_camel_documented
  slum_village_players_documented flylo_beginners_falafel_documented
].freeze

def prog_rotation_enabled? = ENV.fetch("PROG_ROTATE", "1") != "0"

# Concatenate whole progressions from the pool, one after another, until the
# section length is filled, then trim. Each progression keeps its own chords, so
# the harmony genuinely changes section to section rather than looping. Returns
# nil when fewer than two of the pool resolve (e.g. ARTIST_VERIFIED_ONLY hides
# them), so the caller falls back to the single-progression loop.
def arrange_rotating_progressions(needed_chords, _cfg)
  # Resolve each pool name to its OWN chords. dilla_progression is wrong here: it
  # reads ENV["PROGRESSION"] first and would hand back the default track for every
  # name. safe_producer_progression takes the name directly, and voice-leading it
  # matches the pad shape arrange_loop_progression would have produced.
  pool = PROG_ROTATION_POOL.filter_map do |name|
    pads = safe_producer_progression(name)
    pads && pads.length >= 2 ? [name, voice_led_pad_progression(pads)] : nil
  end
  return nil if pool.length < 2

  out = []
  phases = []
  cycle = 0
  while out.length < needed_chords
    _name, pads = pool[cycle % pool.length]
    pads.each do |chord|
      out << chord
      phases << (cycle.zero? ? :exposition : :main)
    end
    cycle += 1
  end
  out = out.first(needed_chords)
  phases = phases.first(needed_chords)
  (1..[2, phases.length].min).each { |k| phases[-k] = :recapitulation }
  dmesg("prog rotation: #{pool.map { |n, _| n }.join(' → ')} over #{out.length} chords",
        unit: "harm0", parent: "dilla0")
  [out, phases]
end

def log_progression_phases!(track, bpm, pads, phases)
  log_progression!(track, bpm, pads, phases)
end

# --------------------------------------------------------------------------
# engine part: groove_timing
# --------------------------------------------------------------------------
#
# Per-role swing offsets, cyclic timing drift and section density.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Different degrees of swing on different voices -- the near-polyrhythmic
# quality described in accounts of both producers, and the thing a single
# global swing figure cannot produce however large it is set.
#
# The kick is 0: locked to the grid, which is what everything else is heard as
# leaning against. Take that reference away and the leaning stops reading as
# feel and starts reading as an unsteady tempo. Percussion is furthest behind
# at 1.45 -- shakers and maracas played deliberately late are named repeatedly
# as the source of the push and pull against kick and snare.
# The melodic roles were missing entirely, and they are the busiest roles in the
# engine: lead appears 90 times, warm 75, ep 50, texture 28. With no entry they
# fell through `SWING_ROLE_SCALE[role] || 1.0` and were swung at exactly the
# hi-hat rate — the most exaggerated lean in the kit — while bass sat at 0.3 and
# pad at 0.5 because someone had already decided sustained material should lean
# less than the hats.
#
# That is backwards for this feel. The records this engine is named after put the
# keys and the lead behind or across the drums, not locked to the hat; a Rhodes
# chord swung as hard as a shaker is the sound of a sequencer, which is the one
# thing the pocket exists to avoid. Sustained voices take the pad's 0.5, leads
# sit a little further back at 0.6 — enough to be heard leaning, short of the
# ghost-note 1.2 that would make a held note sound late rather than lazy.
#
# `kick` was the other one, and it is a plain defect: kick_anchor is 0.0 because
# it is the grid reference everything else leans against, and a bare `:kick`
# role — three call sites — was swinging at 1.0. Same drum, opposite treatment,
# decided by which name the call site happened to use.
SWING_ROLE_SCALE = {
  kick_anchor: 0.0, kick: 0.0, kick_sync: 0.15,
  snare: 0.85, clap: 0.85,
  hat_down: 1.0, hat_up: 1.1, hat: 1.0, open: 1.0,
  ghost: 1.2,
  perc: 1.45,
  bass: 0.3, pad: 0.5,
  ep: 0.5, warm: 0.5, texture: 0.4, native: 0.5,
  lead: 0.6, xlead: 0.6, scale_lead: 0.6, creative_lead: 0.6,
}.freeze
SWING_ROLE_SPREAD = ENV.fetch("SWING_ROLE_SPREAD", "1").to_f.clamp(0.0, 3.0)

# Swing above 50 expressed as milliseconds of lean for this role.
def swing_role_offset_ms(role, beat_p)
  return 0.0 if SWING_ROLE_SPREAD.zero? || beat_p.nil?

  # resolve_swing needs a preset and sonic that this call site does not have, so
  # read the pinned value and fall back to the researched figure rather than to
  # whatever the preset happens to carry. 54 sits inside the 53-56 those sources
  # give for the Dilla swing.
  swing = (ENV["SWING"] || 54).to_f
  return 0.0 unless swing > 50.0

  scale = SWING_ROLE_SCALE[role] || 1.0
  # An eighth is half a beat; a swing of 66 pushes the off-eighth by 16% of it.
  ((swing - 50.0) / 100.0) * (beat_p * 500.0) * scale * SWING_ROLE_SPREAD
end

def cyclic_timing_offset(role, bar_index, step_index, timing, beat_p, cycle: 4)
  range = timing&.fetch(role, nil) || MICROTIMING_MS.fetch(role)
  cyclic_bar = bar_index % cycle
  seed = (cyclic_bar * 97) + (step_index * 31) + stable_hash(role)
  raw = range.begin + (seed % (range.end - range.begin + 1))
  return raw unless beat_p

  # Per-role swing lean, added to every path below that has a beat period.
  sw = swing_role_offset_ms(role, beat_p)
  tick_ms = (beat_p * 1000.0) / 96.0
  quantized = ((raw / tick_ms).round * tick_ms).round(3)
  if ENV["NO_QUANTIZE"] == "1"
    jitter = Random.new(seed).rand(-2.0..2.0)
    return (quantized + jitter + sw).round(3)
  end
  track = (ENV["TRACK"] || DillaLofiMachine::DEFAULT_PROFILE).to_s.downcase.tr("-", "_").to_sym
  ticks = DillaLofiMachine.humanize_ticks_for(track)
  if ticks.positive?
    bpm = 60.0 / beat_p
    h_ms = DillaLofiMachine.humanize_ms(bpm, ticks)
    jitter = Random.new(seed + 17).rand(-h_ms..h_ms)
    return (quantized + jitter + sw).round(3)
  end
  (quantized + sw).round(3)
end

def phase_gain_multiplier(phase)
  case phase
  when :exposition then 0.94
  when :development then 0.78
  when :recapitulation then 1.0
  when :coda then 0.68
  else 1.0
  end
end

def chord_phase_at(bar, pad_chords, chord_phases, chord_bars:, phrase_bars: nil)
  return if pad_chords.nil? || pad_chords.empty? || chord_phases.nil? || chord_phases.empty?
  idx = dilla_chord_index(bar, pad_chords, chord_bars:, phrase_bars:)
  chord_phases[idx]
end

def section_density(bar, n_bars, chord_phases: nil, pad_chords: nil, chord_bars: 2, phrase_bars: nil)
  base = if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
           prof = @composition_session.profile_at(bar)
           tension = @composition_session.tension_at(bar)
           (prof[:drums] * 0.5 + tension * 0.5).clamp(0.2, 1.0)
         else
           sec = dilla_section_legacy(bar, n_bars)
           case sec
           when :intro then 0.55
           when :breakdown then 0.45
           when :build
             build_start = (n_bars * 0.82).to_i
             0.72 + 0.28 * ((bar - build_start).to_f / [n_bars * 0.18, 1].max).clamp(0.0, 1.0)
           when :outro then 0.5
           else 1.0
           end
         end
  phase = chord_phase_at(bar, pad_chords, chord_phases, chord_bars:, phrase_bars:)
  base * (phase ? phase_gain_multiplier(phase) : 1.0)
end

# --------------------------------------------------------------------------
# engine part: percussion
# --------------------------------------------------------------------------
#
# Synthesised percussion one-shots: rim, clap, tabla, tambourine, woodblock, agogo.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Percussion belongs to the idiom, not to every track alike.
#
# woodblock and agogo fired OUTSIDE the family check, at a flat probability, on
# every step of every track in the catalogue. A Detroit kit, an LA kit and a
# techno kit all got the same woodblock-and-agogo sprinkle laid over them, and
# the operator heard exactly that -- "the redundant drum beat with agogo, not
# the new ones we designed". The feels were driving kicks, snares, hats and
# ghosts correctly; this layer was painting over the difference.
#
# Each feel names its own vocabulary and rate. 0 means the instrument is not
# part of that idiom: techno has no agogo, Detroit has no glitch stab. A feel
# with no entry keeps the old rates, so nothing that already sounded right
# changes.
# The vocabulary is what these producers actually played, and it is short.
#
# A Dilla or Slum Village kit is kick, snare, rimshot, clap, closed and open
# hat, and ghost snares. That is the whole list. Tambourine, agogo, woodblock
# and tabla are general-MIDI world percussion; neither Dilla nor the LA beat
# scene used them, and sprinkling them over a Detroit pattern is what made a
# demo full of new drum designs still sound like the old one.
#
# A first pass removed agogo and woodblock and left tambourine at 0.055, which
# was the same mistake wearing a different instrument. Everything outside the
# list is 0 now.
#
# rim stays because a rimshot is a hiphop sound and Dilla used one constantly.
# glitch stays on the LA and techno feels only, where a stab is idiomatic;
# Detroit gets none.
# Kick, snare/clap, hi-hat, ghost. That is the kit.
#
# Operator direction, and it is what the records are: a Dilla or Slum Village
# bar has a kick, a snare or clap, closed and open hats, and ghost snares
# underneath. Nothing else. Tambourine, agogo, woodblock and tabla are
# general-MIDI world percussion nobody in this lineage played, and rim and
# glitch are the same argument one step quieter -- an ornament arriving on top
# of a groove that should be carrying itself.
#
# Every rate is 0 for these three feels, so the eclectic layer contributes
# nothing and the drums are the drums. Drive and groove come from the kit and
# the microtiming, not from adding instruments. Any feel not listed keeps the
# old rates, so nothing else in the catalogue changes.
PERC_VOCAB = {
  detroit_stumble:   { rim: 0.0, glitch: 0.0, tabla: 0.0, tambourine: 0.0, woodblock: 0.0, agogo: 0.0 },
  la_beat_scene:     { rim: 0.0, glitch: 0.0, tabla: 0.0, tambourine: 0.0, woodblock: 0.0, agogo: 0.0 },
  techno_drive: { rim: 0.0, glitch: 0.0, tabla: 0.0, tambourine: 0.0, woodblock: 0.0, agogo: 0.0 }
}.freeze

# The fallbacks are 0, not the old rates.
#
# Scoping this to the new feels only was too narrow: every other track in the
# catalogue -- which is most of them, since the morph is opt-in -- kept getting
# agogo, woodblock, tambourine and tabla sprinkled over it. The instruction was
# not "use fewer of these on the new patterns", it was that Dilla and the LA beat
# scene never played them. So they are off everywhere, and a feel would have to
# name a rate explicitly in PERC_VOCAB to get one back.

# The morph changes the feel per bar, so the ornaments have to follow it or the
# kit arrives in techno while the percussion is still in Detroit.
def perc_rate(feel, bar, instrument, fallback)
  active = (drum_morph_feel(bar, :perc) || feel)
  table = PERC_VOCAB[active&.to_sym]
  return fallback unless table

  table.fetch(instrument, 0.0)
end

# Kick, snare/clap, hi-hat, ghost. The whole function sits out.
#
# Zeroing instruments one at a time kept missing some. agogo, woodblock,
# tambourine and tabla went to 0 and the operator still heard ornaments,
# because rim and glitch were still firing and poly5 -- a 5-against-4
# polyrhythm mapped to a rim sound in drum_bus_mapping -- was ticking once a
# bar underneath everything. Sixteen metallic hits in sixteen bars reads as
# exactly the world percussion that was supposed to be gone.
#
# "Nothing else" is a statement about the whole layer, not a list of rates to
# turn down, so these feels return before any of it runs. Any feel not named
# here is untouched.
KIT_ONLY_FEELS = %i[timeless organic syncopated_slash_ninth loose_pocket
                    detroit_stumble la_beat_scene techno_drive default].freeze

def schedule_eclectic_percussion!(events, duration, beat_p, bar_p, cfg, n_bars)
  return if KIT_ONLY_FEELS.include?(cfg[:feel]&.to_sym)

  rng = Random.new(stable_hash(cfg[:track].to_s) + 909)
  step_p = beat_p / 4.0
  family = cfg[:style_family]
  feel = cfg[:feel]

  # Polyrhythm 5:4 layer
  poly5 = bar_p / 5.0
  (0...(duration / poly5).floor).each do |i|
    next if family != :wonky && i % 5 != 0
    t = (i * poly5).round(6)
    events[:poly5] ||= []
    events[:poly5] << [t, (0.12 + 0.06 * Math.sin(i * 0.9)).clamp(0.06, 0.28), :rim]
  end

  # Clap on 2&4 is scheduled in dilla_schedule (snare unison) when BACKBEAT_CLAP=1.
  unless backbeat_clap_enabled?
    (0...(duration / bar_p).floor).each do |bar|
      base = bar * bar_p
      density = section_density(bar, n_bars, chord_phases: @chord_phases, pad_chords: @progression_chords,
                                chord_bars: @render_chord_bars, phrase_bars: @render_phrase_bars)
      next if density < 0.5
      [1, 3].each do |beat|
        t = (base + beat * beat_p).round(6)
        events[:clap] ||= []
        events[:clap] << [t, dilla_velocity(0.42 * density, bar, beat, spread: 0.08), :clap]
      end
    end
  end

  # Rim / brush / woodblock / agogo / glitch / tabla / tambourine — both
  # style families now get the eclectic layer (was Wonky-only, which left
  # :dilla-family tracks — most of STREAM_TRACKS — with almost nothing
  # here beyond sparse woodblock/agogo; real critique was "not intricate
  # or dynamic"). :dilla family gets a calmer rate, not zero.
  (0...(duration / step_p).floor).each do |i|
    bar = (i / 16).floor
    density = section_density(bar, n_bars, chord_phases: @chord_phases, pad_chords: @progression_chords,
                              chord_bars: @render_chord_bars, phrase_bars: @render_phrase_bars)
    t = (i * step_p).round(6)
    r = rng.rand
    if family == :wonky || family == :dilla
      wild = family == :wonky ? 1.0 : 0.6
      events[:rim] ||= []
      events[:rim] << [t, dilla_velocity(0.28, bar, i % 16, spread: 0.1), 0.35] if r < perc_rate(feel, bar, :rim, 0.04) * density * wild
      events[:glitch] ||= []
      events[:glitch] << [t + rng.rand * step_p * 0.5, dilla_velocity(0.35, bar, i, spread: 0.12), :ind_stab] if r < 0.02 * wild
      events[:tabla] ||= []
      events[:tabla] << [t, dilla_velocity(0.32, bar, i, spread: 0.15)] if r < perc_rate(feel, bar, :tabla, 0.0) * density * wild
      events[:tambourine] ||= []
      events[:tambourine] << [t, dilla_velocity(0.22, bar, i, spread: 0.1)] if i.even? && r < perc_rate(feel, bar, :tambourine, 0.0) * density * wild
    end
    events[:woodblock] ||= []
    events[:woodblock] << [t, dilla_velocity(0.2, bar, i, spread: 0.06)] if r < perc_rate(feel, bar, :woodblock, 0.0)
    events[:agogo] ||= []
    events[:agogo] << [t, dilla_velocity(0.18, bar, i, spread: 0.05)] if r < perc_rate(feel, bar, :agogo, 0.0)
  end

  # Wall-of-noise bar every 32
  (0...(duration / bar_p).floor).each do |bar|
    next unless bar.positive? && bar % 32 == 31
    base = bar * bar_p
    16.times do |step|
      t = (base + step * step_p).round(6)
      events[:glitch] ||= []
      events[:glitch] << [t, dilla_velocity(0.55, bar, step, spread: 0.05), :ind_clap]
    end
  end

  # Trigger-finger miss (intentional dropout)
  %i[kick snare hat].each do |key|
    next unless events[key]
    events[key] = events[key].reject { |hit| rng.rand < 0.04 } if family == :wonky
  end

  events
end

# Struck objects, built the way struck objects actually behave.
#
# Every voice below used to be white noise or plain sines under one exponential
# decay, and that is audibly not what a drum is. Three things separate a
# synthesised hit from a sampled one, and all three are cheap to fix:
#
#   BAND LIMITING. Raw noise and raw squares carry energy past Nyquist, which
#   folds back down as inharmonic aliasing. It is the single most "cheap
#   digital" artefact there is. Everything here is filtered.
#
#   INHARMONICITY. A struck bar or bell rings at ratios that are NOT integers --
#   a real cowbell is nothing like 1:1.5, and an agogo at exactly 3:2 reads as
#   two oscillators rather than one object. The ratio tables below are
#   stretched deliberately, and higher modes decay faster, which is the physics:
#   short wavelengths lose energy to the mounting first.
#
#   A STRIKE. Every real percussion hit begins with a broadband contact noise
#   before the body speaks. Without it a modal ring sounds like a synth pad
#   with a fast attack, because that is exactly what it is.
#
# Deterministic per voice: the seeds are fixed, so a kit is the same kit twice.

# Two-pole resonant bandpass, transposed direct form II. Used to band-limit
# noise into a formant rather than letting it alias across the whole spectrum.
def perc_bandpass(sig, freq, q)
  w = 2.0 * Math::PI * freq / SAMPLE_RATE
  alpha = Math.sin(w) / (2.0 * q)
  b0 = alpha
  b2 = -alpha
  a0 = 1.0 + alpha
  a1 = -2.0 * Math.cos(w)
  a2 = 1.0 - alpha
  x1 = x2 = y1 = y2 = 0.0
  sig.map do |x|
    y = (b0 / a0) * x + (b2 / a0) * x2 - (a1 / a0) * y1 - (a2 / a0) * y2
    x2 = x1
    x1 = x
    y2 = y1
    y1 = y
    y
  end
end

# A struck body: partials at inharmonic ratios, each with its own decay.
def perc_modes(len, base, ratios, decays, amps)
  out = Array.new(len, 0.0)
  ratios.each_with_index do |r, m|
    f = base * r
    next if f >= SAMPLE_RATE * 0.45          # never place a partial past Nyquist
    d = decays[m]
    a = amps[m]
    len.times do |i|
      t = i.to_f / SAMPLE_RATE
      out[i] += a * Math.exp(-t * d) * Math.sin(2.0 * Math::PI * f * t)
    end
  end
  out
end

# Contact noise: the moment before the body speaks.
def perc_strike(len, seed, freq, q, decay, gain)
  rng = Random.new(seed)
  raw = Array.new(len) { rng.rand * 2.0 - 1.0 }
  perc_bandpass(raw, freq, q).each_with_index.map do |v, i|
    v * Math.exp(-(i.to_f / SAMPLE_RATE) * decay) * gain
  end
end

def perc_normalize(out, peak)
  m = out.map(&:abs).max || 1.0
  out.map { |s| s / [m, 1.0e-6].max * peak }
end

# Rimshot: stick on the rim, plus the shell speaking underneath it. The old
# version was noise alone, which is the "tss" half without the "tok" half --
# the pitched shell mode is what makes it read as a drum being hit.
def synth_rim_sample
  len = (0.07 * SAMPLE_RATE).round
  shell = perc_modes(len, 430.0, [1.0, 2.61, 4.19], [58.0, 96.0, 150.0], [0.60, 0.26, 0.12])
  stick = perc_strike(len, 42, 2600.0, 1.1, 130.0, 0.75)
  perc_normalize(shell.each_with_index.map { |v, i| v + stick[i] }, 0.78)
end

# Hand clap: several pairs of hands, not one.
#
# The old version fired three noise bursts 3 ms apart, which is inside the ear's
# fusion window -- they arrive as a single transient, so it sounded like a snare
# with no tone rather than a clap. Real claps in a room are 15-30 ms apart,
# unevenly, and the last one is followed by the room. That spacing IS the sound.
# Band-limited around 1.6 kHz because that is where hands live; white noise
# reads as static.
def synth_clap_sample
  len = (0.34 * SAMPLE_RATE).round
  rng = Random.new(17)
  out = Array.new(len, 0.0)
  # four hits, unevenly spaced, each slightly quieter and duller than the last
  [[0.0, 1.0, 1750.0], [0.017, 0.86, 1650.0], [0.036, 0.72, 1520.0], [0.058, 0.55, 1400.0]]
    .each_with_index do |(delay, amp, fc), n|
    off = (delay * SAMPLE_RATE).round
    burst_len = len - off
    next if burst_len <= 0
    raw = Array.new(burst_len) { rng.rand * 2.0 - 1.0 }
    perc_bandpass(raw, fc, 1.5).each_with_index do |v, i|
      out[off + i] += v * Math.exp(-(i.to_f / SAMPLE_RATE) * (68.0 + n * 6.0)) * amp
    end
  end
  # the room the hands are in: a slower, darker tail under all of it
  tail_raw = Array.new(len) { rng.rand * 2.0 - 1.0 }
  perc_bandpass(tail_raw, 1150.0, 0.8).each_with_index do |v, i|
    out[i] += v * Math.exp(-(i.to_f / SAMPLE_RATE) * 13.0) * 0.22
  end
  perc_normalize(out, 0.85)
end

# Tabla. Nearly the only drum with a definite pitch, because the black tuning
# paste loads the centre of the head so its modes fall close to whole-number
# ratios instead of the inharmonic mess an undamped membrane produces. Close,
# not exact -- the slight stretch below is the difference between a tabla and a
# sine with a pitch envelope, which is what this was. The pitch drop stays: that
# is the palm on the head.
def synth_tabla_sample
  len = (0.30 * SAMPLE_RATE).round
  out = Array.new(len, 0.0)
  ratios = [1.0, 2.01, 3.04, 4.09]
  decays = [13.0, 20.0, 30.0, 44.0]
  amps = [0.60, 0.30, 0.16, 0.08]
  len.times do |i|
    t = i.to_f / SAMPLE_RATE
    bend = 1.0 + 0.55 * Math.exp(-t * 45.0)      # palm pressure releasing
    attack = 1.0 - Math.exp(-t * 160.0)
    ratios.each_with_index do |r, m|
      f = 186.0 * r * bend
      next if f >= SAMPLE_RATE * 0.45
      out[i] += amps[m] * Math.exp(-t * decays[m]) * attack * Math.sin(2.0 * Math::PI * f * t)
    end
  end
  strike = perc_strike(len, 71, 1900.0, 1.3, 190.0, 0.30)
  perc_normalize(out.each_with_index.map { |v, i| v + strike[i] }, 0.72)
end

# No voice below is one exp(-t*k) shape at a different rate. That shape is
# correct that a rim, a woodblock and an agogo bell decay at different
# SPEEDS, and wrong that they decay the same SHAPE. Real struck objects
# don't share one physical behavior; each gets the envelope its actual
# physical characteristics: a woodblock has ~zero ring (transient click,
# then silence), a tambourine's metal jingles shimmer well after the
# hand-hit decays (two-stage, not one), a bell's higher partials lose
# energy faster than its fundamental (independent per-partial decay).
def synth_tambourine_sample
  len = (0.16 * SAMPLE_RATE).round
  rng = Random.new(88)
  out = Array.new(len, 0.0)
  len.times do |i|
    t = i.to_f / SAMPLE_RATE
    hit = Math.exp(-t * 60.0)
    shimmer = Math.exp(-t * 9.0) * 0.35
    out[i] = (rng.rand * 2.0 - 1.0) * (hit * 0.5 + shimmer)
  end
  out
end

def synth_woodblock_sample
  len = (0.04 * SAMPLE_RATE).round
  out = Array.new(len, 0.0)
  len.times do |i|
    t = i.to_f / SAMPLE_RATE
    click = t < 0.0015 ? 1.0 : 0.0
    body = Math.exp(-t * 140.0) * Math.sin(2 * Math::PI * 1200.0 * t)
    out[i] = click * 0.4 + body * 0.55
  end
  out
end

def synth_agogo_sample
  len = (0.12 * SAMPLE_RATE).round
  out = Array.new(len, 0.0)
  len.times do |i|
    t = i.to_f / SAMPLE_RATE
    fundamental = Math.exp(-t * 16.0) * Math.sin(2 * Math::PI * 660.0 * t)
    overtone = Math.exp(-t * 34.0) * Math.sin(2 * Math::PI * 990.0 * t)
    out[i] = (fundamental * 0.5 + overtone * 0.5) * 0.45
  end
  out
end

# --------------------------------------------------------------------------
# engine part: drum_policy
# --------------------------------------------------------------------------
#
# Which drums play at all: kick gates, halftime, Wonky overlays and grids.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def extended_drum_kit(base_kit)
  base_kit.merge(
    rim: synth_rim_sample,
    clap: synth_clap_sample,
    tabla: synth_tabla_sample,
    tambourine: synth_tambourine_sample,
    woodblock: synth_woodblock_sample,
    agogo: synth_agogo_sample,
    ind_kick: load_mono_sample(drum_sample_path("ind_kick.wav")),
    ind_clap: load_mono_sample(drum_sample_path("ind_clap.wav")),
    ind_hat: load_mono_sample(drum_sample_path("ind_hat.wav")),
    ind_stab: load_mono_sample(drum_sample_path("ind_stab.wav")),
  )
rescue StandardError
  base_kit
end

# The whole drum bus, one switch.
#
# Off by default, operator instruction 2026-08-27: "kill all the drums". The
# custom kit carries exactly one snare and it landed on every track of a
# 451-track demo, which is what that instruction was about. DRUMS=1 brings
# them back with nothing else changed.
#
# Gated here rather than at the kit, because a kit swap still plays drums.
def drums_enabled?
  ENV.fetch("DRUMS", "0") != "0"
end

def wonky_primary_drums?
  return false unless drums_enabled?

  camel_mode? && wonky_drum_overlay_enabled?
end

# Under Camel/Wonky primary, default to Wonky grid ONLY.
# Hybrid pocket+overlay doubled kicks/snares (~10 kicks + ~9 snares/bar) and
# sounded like broken machine-gun drums — set WONKY_DRUMS_ONLY=0 to re-enable pocket.
def wonky_drums_only?
  # Default OFF — hybrid double-kit was the #1 "drums suck" failure mode.
  wonky_primary_drums? && ENV.fetch("WONKY_DRUMS_ONLY", "0") == "1"
end

def dilla_pocket_drums_enabled?
  drums_enabled? && !wonky_drums_only?
end

def kicks_enabled?
  return false unless drums_enabled?

  # Pocket kit kicks when overlay-only is off. Prefer POCKET_KICKS;
  # KICKS=1 alone does not force pocket when WONKY_DRUMS_ONLY=1.
  return false if wonky_drums_only?
  return ENV.fetch("POCKET_KICKS", "1") != "0" if ENV.key?("POCKET_KICKS")
  ENV.fetch("KICKS", "1") != "0"
end

def kick_velocity_scale
  # Non-wonky default was cut from ~0.9 to 0.68 chasing a Wonky-only
  # "drums too hard" complaint, but this default is shared by every
  # non-wonky track (pedal_e_descent included) and compounds with
  # dilla_role_velocity's already-lower kick_anchor/kick_sync bases --
  # real listening feedback was "absent proper kick drums." Restored
  # toward the pre-cut value; wonky's own 0.78 is untouched.
  default = wonky_primary_drums? ? "0.78" : "0.88"
  ENV.fetch("KICK_GAIN", default).to_f.clamp(0.08, 1.35)
end

def wonky_kick_velocity_scale
  ENV.fetch("WONKY_KICK_GAIN", wonky_primary_drums? ? "1.15" : "0.85").to_f.clamp(0.2, 2.0)
end

def halftime?
  ENV.fetch("HALFTIME", "0") == "1"
end

# A semitone either side, as ratios. Approaching from below is the default
# because a leading tone rising into the root is the stronger pull; from above
# when the next chord is lower, so the line keeps descending rather than
# doubling back to climb into it.
APPROACH_BELOW = 0.9438743126816935   # 2 ** (-1/12.0)
APPROACH_ABOVE = 1.0594630943592953   # 2 ** ( 1/12.0)

# The bass stays low. A fifth above a root already near the top of the register
# lands in the pads' territory and stops reading as bass at all.
BASS_REGISTER_TOP = 130.0

def bass_line_enabled? = ENV.fetch("BASS_LINE", "1") != "0"

def bass_slide_enabled?
  ENV.fetch("BASS_SLIDE", "1") != "0"
end

def backbeat_clap_enabled?
  ENV.fetch("BACKBEAT_CLAP", "1") != "0"
end

def wonky_drum_overlay_enabled?
  ENV.fetch("WONKY_DRUM_OVERLAY", ENV["STREAM_SOUL"] == "1" ? "1" : "0") != "0"
end

def wonky_overlay_rotate_steps(steps, rot)
  Array(steps).map { |s| (s + rot) % 16 }.uniq.sort
end

def wonky_overlay_grids_for(section)
  @wonky_overlay_grid_cache ||= {}
  bias = ENV.fetch("WONKY_GRID_BIAS", section.to_s).to_sym
  cache_key = [section, bias, @render_seed || 0]
  return @wonky_overlay_grid_cache[cache_key] if @wonky_overlay_grid_cache.key?(cache_key)
  base = DillaLofiMachine::DRUM_PRESETS[:wonky_abstract]
  shift = WONKY_OVERLAY_SECTION_SHIFT.fetch(section, 2)
  grids = WONKY_OVERLAY_GRID_COUNT.times.map do |variant|
    rot = shift + variant
    {
      kicks: wonky_overlay_rotate_steps(base[:kicks], rot),
      snares: wonky_overlay_rotate_steps(base[:snares], rot * 2),
      hats: wonky_overlay_rotate_steps(base[:hats], rot + variant),
      perc: wonky_overlay_rotate_steps(base[:perc], rot + 1),
    }
  end
  @wonky_overlay_grid_cache[cache_key] = grids
end

def wonky_overlay_grid_pick(bar, section, role)
  grids = wonky_overlay_grids_for(section)
  seed = (@render_seed || 0) + stable_hash(section)
  idx = (bar + seed + (bar / 4)) % grids.length
  Array(grids[idx].fetch(role, [])).dup
end

def wonky_drum_grid_for(track)
  t = track.to_s
  return if t.empty?
  eng = load_learned_engine
  alias_key = eng.dig("track_aliases", t)
  eng.dig("drum_grids", t) ||
    (alias_key && eng.dig("drum_grids", alias_key)) ||
    BUILTIN_LEARNED_ENGINE.dig("drum_grids", t) ||
    (alias_key && BUILTIN_LEARNED_ENGINE.dig("drum_grids", alias_key))
end

def wonky_overlay_grid_hash
  # Camel/dilla style always uses the hip-hop pocket reduction of the Camel stem.
  # Project JSON may supply per-track grids when not in camel/dilla mode.
  grid = if camel_mode?
           POLY_TEMPORAL_DRUM_GRID
         else
           wonky_drum_grid_for(ENV["TRACK"] || "")
         end
  grid = POLY_TEMPORAL_DRUM_GRID if (grid.nil? || !grid.is_a?(Hash)) && wonky_drum_overlay_enabled?
  grid.is_a?(Hash) ? grid : nil
end

# Learned grids on disk predate the rename and still key their steps flylo_*.
# Renaming the reader without accepting the old spelling does not fail -- it
# falls through to the bare key, finds nothing, and plays an empty grid, so a
# learned pattern silently becomes silence. Read both, write only the new one.
WONKY_GRID_LEGACY_PREFIX = "flylo_"
def wonky_grid_steps(grid, name)
  Array(grid["wonky_#{name}"] ||
        grid["#{WONKY_GRID_LEGACY_PREFIX}#{name}"] ||
        grid[name] || grid[name.to_sym] || [])
end

def learned_wonky_overlay_steps(role)
  grid = wonky_overlay_grid_hash
  return unless grid
  case role
  when :kicks then wonky_grid_steps(grid, "kicks")
  when :snares then wonky_grid_steps(grid, "snares")
  when :ghost_snares then wonky_grid_steps(grid, "ghost_snares")
  when :hats then wonky_grid_steps(grid, "hats")
  when :hat_ghosts then wonky_grid_steps(grid, "hat_ghosts")
  when :perc then wonky_grid_steps(grid, "perc")
  when :claps then wonky_grid_steps(grid, "claps")
  end
end

def wonky_chord_change_duck(bar, chord_bars)
  return 1.0 unless bar.positive? && chord_bars.positive? && (bar % chord_bars).zero?
  ENV.fetch("WONKY_CHORD_DUCK", "0.72").to_f.clamp(0.45, 1.0)
end

def camel_drum_lock?
  camel_mode? && ENV.fetch("CAMEL_DRUM_LOCK", "1") != "0"
end

def wonky_overlay_density(bar, n_bars, chord_bars:, pad_chords: nil, chord_phases: nil, phrase_bars: nil)
  # Camel lock: always full kit — section density (intro 0.42 × form 0.55 ≈ 0.23)
  # was the main reason the grid felt "missing" / wrong vs Camel.
  return ENV.fetch("WONKY_OVERLAY_GAIN", "1.2").to_f.clamp(0.9, 1.45) if camel_drum_lock?

  section = dilla_section(bar, n_bars)
  form = form_section_at(bar, n_bars)
  base = WONKY_OVERLAY_SECTION_DENSITY.fetch(section, 0.85)
  form_mul = form ? WONKY_OVERLAY_FORM_MUL.fetch(form, 1.0) : 1.0
  phase = chord_phase_at(bar, pad_chords, chord_phases, chord_bars:, phrase_bars:)
  phase_mul = phase ? phase_gain_multiplier(phase) : 1.0
  duck = wonky_chord_change_duck(bar, chord_bars)
  gain = ENV.fetch("WONKY_OVERLAY_GAIN", wonky_primary_drums? ? "1.12" : "0.55").to_f
  (base * form_mul * phase_mul * duck * gain).clamp(0.12, 1.45)
end

# Split roles — snare was on BOTH buses and hit twice (muddy / flammed).
def wonky_sub_bus_mapping
  { wonky_kick: :kick, wonky_perc: :cowbell }
end

def wonky_top_bus_mapping
  { wonky_hat: :hat, wonky_quint: :hat, wonky_snare: :snare, wonky_rim: :rim, wonky_glitch: :ind_stab }
end

# --------------------------------------------------------------------------
# engine part: render_scratch
# --------------------------------------------------------------------------
#
# Render scratch directory and the stream lock.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def dilla_render_tmp(tag)
  File.join(SCRATCH_DIR, "dilla_#{tag}.#{Process.pid}.wav")
end

# PID-scoped temp files (drums/harmonic/wonky_*/pads.wav.L0/.smf.mid/etc.)
# are reused across every track iteration within one long-running stream
# process, not just within a single render. If a write is ever interrupted
# (disk full, a signal mid-write) a stale/corrupt derived file can silently
# survive and poison a later, otherwise-unrelated track's render — a
# multi-minute stream then starts failing its final ffmpeg mixdown on every
# track. Wiping this process's own scratch files at the top of every render
# makes each track start from a guaranteed-clean slate instead of trusting
# leftovers from whatever the last track did.
def cleanup_render_scratch!
  Dir.glob(File.join(SCRATCH_DIR, "dilla_*.#{Process.pid}.*")).each { |f| FileUtils.rm_f(f) } # scan: intentional — this process's own scratch files, pid-scoped
end

STREAM_LOCK_PATH = scratch_path("dilla_stream.lock").freeze

def acquire_stream_lock!
  if File.exist?(STREAM_LOCK_PATH)
    holder = File.read(STREAM_LOCK_PATH).strip.to_i
    if holder.positive?
      begin
        Process.kill(0, holder)
        dmesg_warn("stream lock held by pid #{holder} — exit")
        exit 0
      rescue Errno::ESRCH
        FileUtils.rm_f(STREAM_LOCK_PATH)
      end
    end
  end
  File.write(STREAM_LOCK_PATH, Process.pid.to_s)
  at_exit do
    FileUtils.rm_f(STREAM_LOCK_PATH) if File.exist?(STREAM_LOCK_PATH) &&
                                        File.read(STREAM_LOCK_PATH).strip.to_i == Process.pid
  rescue StandardError
    nil
  end
end

# --------------------------------------------------------------------------
# engine part: drum_bus
# --------------------------------------------------------------------------
#
# Drum bus routing: Wonky dual bus, ducking, field layer, drop bars.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# "All his drums are dirty as fuck, sans the kick" -- and the cymbals in
# particular are swished through phaser and flanger until they are soupy rather
# than crisp.
#
# The dual-bus split already separates exactly the right things: the sub bus is
# the kick, the top bus is hats, snare and cymbals. So the dirt goes on the top
# branch and the kick stays untouched, which is the distinction being described
# rather than an approximation of it. Applying this to the whole kit would
# smear the one element that has to stay solid.
#
# Order matters: modulation BEFORE the EQ, so the phaser's own notches get
# shaped by the top-end lift rather than fighting it, and light saturation last
# so it thickens what the modulation produced.
WONKY_TOP_DIRT = (ENV["WONKY_TOP_DIRT"] || 0).to_f.clamp(0.0, 1.0)

def wonky_top_dirt
  return "" if WONKY_TOP_DIRT <= 0.0

  d = WONKY_TOP_DIRT
  "aphaser=in_gain=0.6:out_gain=0.8:delay=#{(2.5 + (2.0 * d)).round(2)}:" \
    "decay=#{(0.3 * d).round(3)}:speed=#{(0.35 + (0.5 * d)).round(3)}," \
    "flanger=delay=#{(3.0 + (4.0 * d)).round(2)}:depth=#{(2.0 * d).round(2)}:" \
    "regen=#{(12.0 * d).round(1)}:speed=#{(0.28 + (0.4 * d)).round(3)}," \
    "acrusher=bits=#{(16 - (5 * d)).round}:mode=log:aa=1," \
    "asoftclip=type=tanh:threshold=#{(1.0 - (0.35 * d)).round(3)}:oversample=4,"
end

# Duck the hats and cymbals out of the kick's way.
#
# Named twice in the same discussion for a reason: when a hat lands on the same
# 16th as the kick, both fight for the same moment and the kick loses definition
# even though nothing overlaps in frequency. Ducking the top bus for a few tens
# of milliseconds lets the kick through cleanly and is inaudible as an effect --
# the hat is still there, it arrives a fraction behind.
#
# The dual-bus split makes this exact rather than approximate: the sub bus IS
# the kick, so it can key the compressor directly instead of using the whole kit
# as a trigger and ducking on every snare too.
WONKY_HAT_DUCK = (ENV["WONKY_HAT_DUCK"] || 0).to_f.clamp(0.0, 1.0)

def wonky_duck_split
  WONKY_HAT_DUCK.positive? ? ",asplit=2[sub][subkey]" : "[sub]"
end

def wonky_duck_apply
  return "[top]" unless WONKY_HAT_DUCK.positive?

  d = WONKY_HAT_DUCK
  # Threshold high, release short. At 0.056 this triggered on anything in the
  # kick bus above about -25 dBFS, which is most of the time, so it behaved as a
  # general compressor on the top bus rather than as a duck -- measured, cymbals
  # lost 2.3 dB in the gaps BETWEEN kicks, where a sidechain should do nothing
  # whatsoever. A duck has to be deaf to everything except the transient.
  #
  # Release also has to finish inside a 16th (183ms at 82 BPM) or the recovery
  # from one kick is still in progress when the next 16th arrives, which is the
  # same fault by a slower route.
  "[topraw];[topraw][subkey]sidechaincompress=" \
    "threshold=#{(0.35 - (0.12 * d)).round(4)}:ratio=#{(2.0 + (6.0 * d)).round(1)}:" \
    "attack=#{(4.0 - (2.5 * d)).round(1)}:release=#{(90 - (40 * d)).round}:" \
    "makeup=1[top]"
end

# A bed of room noise under the kit, ducked by the kit itself.
#
# The point is not that the noise is audible -- it should not be, on its own.
# It is that continuous low-level room behind the drums removes the silence
# between hits, and silence between hits is what makes programmed drums sound
# programmed. Ducking it by the kit keeps it from crowding the transients it is
# there to support.
#
# Sources come from the synthesised crate, so this needs no field recording and
# no external file. `ruby dilla.rb crate` builds them.
DRUM_FIELD_LAYER = ENV["DRUM_FIELD_LAYER"].to_s
DRUM_FIELD_MIX = (ENV["DRUM_FIELD_MIX"] || 0.18).to_f.clamp(0.0, 1.0)

def drum_field_layer!(drum_path, duration:)
  return drum_path if DRUM_FIELD_LAYER.empty? || !File.file?(drum_path)

  src = File.join(CRATE_DIR, "texture_#{DRUM_FIELD_LAYER}.wav")
  unless File.file?(src)
    warn "drum field: no texture_#{DRUM_FIELD_LAYER}.wav in the crate — run `ruby dilla.rb crate`"
    return drum_path
  end

  out = "#{drum_path}.field.wav"
  begin
    sh! "ffmpeg", "-y", "-i", drum_path, "-stream_loop", "-1", "-i", src,
        "-filter_complex",
        "[0:a]asplit=2[dry][key];" \
        "[1:a]volume=#{DRUM_FIELD_MIX},atrim=0:#{duration.round(3)}," \
        "apad=whole_dur=#{duration.round(3)}[bed];" \
        "[bed][key]sidechaincompress=threshold=0.25:ratio=6:attack=3:release=110:makeup=1[ducked];" \
        "[dry][ducked]amix=inputs=2:duration=first:normalize=0[out]",
        "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
        "-c:a", "pcm_s16le", out
    FileUtils.mv(out, drum_path)
    dmesg("drum field: #{DRUM_FIELD_LAYER} under the kit at #{DRUM_FIELD_MIX}, ducked",
          unit: "drum0", parent: "dilla0")
    drum_path
  rescue StandardError => e
    warn "drum field: #{e.message}"
    FileUtils.rm_f(out)
    drum_path
  end
end

def merge_wonky_dual_bus!(drum_path, sub_path, top_path)
  unless File.file?(drum_path)
    warn "wonky merge: missing drum bus — skipping overlay"
    return
  end
  unless File.file?(sub_path) && File.file?(top_path)
    warn "wonky merge: overlay bus missing (sub=#{File.file?(sub_path)} top=#{File.file?(top_path)}) — skipping"
    return
  end
  merged = "#{drum_path}.merged.#{Process.pid}.wav"
  boost = ENV.fetch("WONKY_MERGE_BOOST", wonky_primary_drums? ? "1.85" : "1.22").to_f
  sub_vol = (ENV.fetch("WONKY_SUB_MIX", wonky_primary_drums? ? "1.05" : "0.38").to_f * boost).round(3)
  top_vol = (ENV.fetch("WONKY_TOP_MIX", wonky_primary_drums? ? "0.88" : "0.32").to_f * boost).round(3)
  # Empty pocket base under Wonky-only — don't pad-mix silence that dilutes the kit.
  base_vol = ENV.fetch("WONKY_BASE_DRUM_VOL", wonky_primary_drums? ? "0.15" : "1.0").to_f.round(3)
  # Sub bus used to lowpass @ 220Hz and kill kick click/body (150Hz+beater).
  # Keep boom + mid punch so kicks read on laptop speakers.
  sh! "ffmpeg", "-y", "-i", drum_path, "-i", sub_path, "-i", top_path,
      "-filter_complex",
      "[0:a]volume=#{base_vol}[base];" \
      "[1:a]highpass=f=28,lowpass=f=520,equalizer=f=55:t=o:w=0.75:g=6.5," \
      "equalizer=f=110:t=o:w=1.0:g=4.0,equalizer=f=180:t=o:w=1.1:g=3.0," \
      "volume=#{sub_vol}#{wonky_duck_split};" \
      "[2:a]#{wonky_top_dirt}highpass=f=700,equalizer=f=3500:t=o:w=1.3:g=5.5," \
  "equalizer=f=6500:t=o:w=1.4:g=6.5,equalizer=f=9000:t=h:w=1.2:g=4.0," \
  "volume=#{top_vol}#{wonky_duck_apply};" \
      "[base][sub][top]amix=inputs=3:duration=first:normalize=0," \
      "alimiter=limit=0.97:level_out=0.98",
      "-c:a", "pcm_s16le", merged
  FileUtils.mv(merged, drum_path)
end

# DRUM_VOL looks like the kit fader and is what stream_iterate / composition
# mutate. The main render reads DRUM_MIX_WEIGHT. Treat an explicit DRUM_VOL as
# the mix weight when DRUM_MIX_WEIGHT was not pinned, so those writers move
# the bus they think they are moving.
def resolved_drum_mix_weight
  mix = ENV["DRUM_MIX_WEIGHT"]
  vol = ENV["DRUM_VOL"]
  pinned_mix = USER_PINNED_ENV["DRUM_MIX_WEIGHT"]
  pinned_vol = USER_PINNED_ENV["DRUM_VOL"]
  return pinned_vol.to_f if pinned_vol && pinned_mix.to_s.empty?
  return mix.to_f if mix && !mix.empty?

  (vol.nil? || vol.empty? ? 0.88 : vol).to_f
end

def apply_drum_vol!(value)
  s = value.to_f.round(2).to_s
  ENV["DRUM_VOL"] = s
  ENV["DRUM_MIX_WEIGHT"] = s
  s
end

# Off by default: the drums play continuously.
#
# drum_drop_bar? silences the kit on the last bar of every 32-bar block and
# every 8th bar of a breakdown. Operator direction is that the groove should be
# continuous and change idiom instead of stopping, so the default moved rather
# than being passed as DRUM_DROP=0 on every single render -- which is how it
# was being used, and a default nobody wants is not a default.
#
# DRUM_DROP=1 restores the drops.
def drum_drop_enabled?
  ENV.fetch("DRUM_DROP", "0") != "0"
end

def drum_drop_bar?(bar, section)
  return false unless drum_drop_enabled?
  return true if section == :breakdown && bar % 8 == 0
  bar.positive? && bar % 32 == 31
end

def drum_bus_mapping
  # The one place every drum voice becomes audio: render_dilla renders the
  # drum bus from this map, and it is the only caller. An empty map is a
  # silent bus whatever the schedulers produced.
  #
  # Gating the schedulers is not enough on its own -- seven of them place
  # drum events (dilla_schedule, schedule_drum_fills!, schedule_hat_roll!,
  # schedule_wonky_drum_overlay!, schedule_eclectic_percussion!,
  # analog_schedule, industrial_techno_schedule) and a new one would arrive
  # ungated. The snare fill and the 32nd hat roll on every eighth bar were
  # ungated for exactly that reason.
  return {} unless drums_enabled?
  # Bass/sub stay on the harmonic bus only — routing them here too doubled
  # the low end on every kick and buried the pad chords in the mix.
  map = {
    snare: :snare, ghost: :ghost, hat: :hat, open: :open_hat,
    poly: :ghost, shaker: :shaker, cowbell: :cowbell,
    poly5: :rim, clap: :clap, rim: :rim, glitch: :ind_stab, tabla: :tabla,
    tambourine: :tambourine, woodblock: :woodblock, agogo: :agogo,
  }
  map[:kick] = :kick if kicks_enabled?
  map
end

# Where the pad bus rolls off.
#
# 3400 Hz had no override of any kind -- it came from the sonic profile or that
# literal, so there was no way to test a brighter pad without editing profiles.
#
# Measured against three J Dilla records (Time: The Donut of the Heart, Slum
# Village's World Full of Sadness, Jay Dee's La La La), octave-band energy
# relative to each file's own full-band level:
#
#            125Hz  250   500    1k    2k    4k    8k    tilt 125->4k
#   Time      -5.8  -8.1 -10.5 -11.9 -11.4 -15.1 -20.7   -1.86 dB/oct
#   Sadness   -3.5  -8.9 -12.7 -14.7 -15.9 -17.1 -19.6   -2.72
#   La La La  -2.2  -9.0 -14.4 -15.7 -16.1 -15.2 -17.5   -2.60
#   engine    -3.1  -5.1 -10.0 -15.1 -21.2 -27.5 -32.8   -4.88
#
# The engine falls roughly twice as fast: 12 dB darker at 4 kHz and 12-15 dB at
# 8 kHz than any of the three. It also carries 3-4 dB MORE at 250 Hz. Dark and
# congested at once, which is what "overdrive sound, pads not nice" describes.
#
# Caveat kept deliberately: the engine figure is an instrumental 8-bar sketch
# and the records are full mastered tracks with vocals and leads that carry
# their own top end. A render WITH a rap vocal measures -3.66 dB/oct -- closer,
# still steeper than all three. So content explains part of the gap and not all
# of it.
#
# The default is unchanged at 3400. PAD_LP exists so the number can be tested
# against those references instead of argued about; moving the default is a tone
# decision and belongs to the operator.
#
# A/B'd immediately after adding it, and the answer was NOT what the comment
# above would lead you to expect: PAD_LP=3400 against PAD_LP=7000 produces
# different files (different checksums, the override is definitely read) whose
# octave-band energy is identical to 0.1 dB at every band. The pad bus
# does not carry enough of the mix's top end for its bandwidth to register.
#
# So the darkness is not here. What the same measurement did find: every sampled
# bed is lowpassed between 5200 and 6000 Hz by its TRACK_SAMPLE_LOOPS entry,
# while all three reference records hold real energy at 8 kHz (-17.5 to -20.7
# relative). And the source material can carry it -- kembara_rindu's own loop.wav
# measures -2.54 dB/oct with 4 kHz at -17.8, which is La La La's -2.60 and -15.2
# almost exactly. The crates are not the limit; the per-loop lp is.
def sonic_pad_lowpass(sonic)
  pinned = ENV["PAD_LP"].to_s.strip
  return pinned.to_i.clamp(800, 18_000) if pinned =~ /\A\d+\z/

  sonic&.dig("synth", "pad_lowpass_hz")&.to_i || 3400
end

def sonic_vinyl_level(sonic)
  # VINYL=0 disables the pink-noise bed. VINYL=1..100 scales intensity (default ~35 → mild).
  if ENV.key?("VINYL")
    v = ENV["VINYL"].to_f
    return 0.0 if v <= 0
    return (v / 100.0 * 0.18).clamp(0.0, 0.12).round(3)
  end
  sonic&.dig("synth", "vinyl_noise")&.to_f || 0.08
end

# --------------------------------------------------------------------------
# engine part: sample_loops
# --------------------------------------------------------------------------
#
# Sampled beds: the loop catalogue, chopping, cross-sampling and excitation.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Audio loops that play UNDERNEATH the synth arrangement. Deliberately not the
# stems path (use_stem_harmony), which REPLACES the harmonic bus wholesale --
# that swaps the engine's harmony out for the sample rather than putting the
# two together, which is the opposite of what a sampled bed is for. This is its
# own bus, mixed alongside drums/harm/bass like any other.
#
# Split in two since `chop` started producing entries of the same shape: the
# literal below is the hand-cut rack, every value in it argued for in the note
# above it, and TRACK_SAMPLE_LOOPS is that plus whatever the chopper has
# registered. Keeping the hand-cut set its own frozen constant means a bad
# ingest can never overwrite a measurement somebody reasoned their way to.
TRACK_SAMPLE_LOOPS_BUILTIN = {
  # The frozen 4-bar loop from the 92 BPM Ableton set recreated as :four_seven.
  # hp/sub_db are per-loop because the loops differ, and a global setting is
  # wrong for one of them whichever value it takes. Measured low-versus-mid,
  # untreated: four_seven -4.9 dB, nightbus -10.3 dB. The Malay loop has a kick
  # and bass baked into the record; nightbus does not, and highpassing it at 90
  # would take out low end it needs rather than low end that is in the way.
  kembara_rindu: { path: File.join(SAMPLE_DIR, "kembara_rindu", "loop.wav"), bpm: 92.0,
                   hp: 90, sub_db: -7.0, lp: 5600 },
  # 0:36 to 0:46. The operator gave 0:35-0:45 and then asked for the noise at
  # the front taken out; measured, the first second of that window is a thin
  # lead-in -- -27 dB overall and -41 dB below 500 Hz, against -16 once the
  # passage proper enters at 1.0s. Moving the window one second later starts at
  # full energy and reads slightly cleaner harmonically too (G minor fit 0.836
  # against 0.813). Still 10 seconds, still 4 bars at 96.
  #
  # Note for the next time this comes up: the complaint was "screaming", but
  # nothing in this window is bright -- the band above 3 kHz never rises above
  # -38 dB anywhere in it. What was audible as harsh was a quiet, thin entry,
  # not a loud one, so looking for high-frequency energy would have found
  # nothing and concluded there was no problem.
  #
  # Original note, still true of the boundary: the detector had picked
  # 13.88s off an energy step and was wrong: it found where the spoken
  # intro stopped, which is not the same thing as where the passage worth
  # sampling starts. The measurements side with the operator -- this section
  # reads G minor at a Krumhansl fit of 0.813, against 0.27 for the detector's
  # cut, on a clean chroma (G, then Bb / Ab / Eb / D / F, a G minor scale).
  #
  # 10 seconds is 4 bars at 96 BPM. It contains no onsets at all -- a sustained
  # melodic passage rather than a rhythmic loop -- which is why onset-based
  # tempo detection reports nothing for it, and why bar arithmetic against a
  # known-good boundary is the only honest way to get a tempo here.
  #
  # Low end left flat: see the note above, this one does not need correcting.
  # carries_own_harmony: Anuar Zain's record states its chords with voices, and
  # the first ten seconds are those voices and their backing and nothing else --
  # separated, only the vocals and `other` stems carry signal there, the rest
  # measuring -78 dB or lower. A generated progression on top is a second piece
  # of music in the same bar.
  #
  # render_dilla.rb's harmonic guard already argues exactly this ("there is no
  # case where you lay pads over a record and want a different key") but decides
  # it from whether the loop's key is READABLE. This loop reads Eb major at fit
  # 0.79 -- legible, so the guard concluded it could transpose the pads to match
  # and play them. Legibility is the wrong question for a record that has already
  # stated the chords; the right one is whether anything needs adding, and only
  # the crate knows that.
  #
  # Per record, not a mode. The other loops here want their progressions.
  semua_untuk_mu: { path: File.join(SAMPLE_DIR, "semua_untuk_mu", "loop.wav"), bpm: 96.0,
                    hp: 45, sub_db: 0.0, lp: 5200, carries_own_harmony: true },

  # 4 bars from 0.32s, where the music starts. The cleanest-looping source of
  # the three by a distance: self-similarity 0.654 against 0.300 for the next
  # best, tempo 114 at 61% on-grid against a 20% baseline, D major at 0.697.
  #
  # 114 rather than 120, decided by measurement rather than by preference. The
  # self-similarity peak sat at exactly 2.00s, which is one bar at 120 and not
  # at 114, so the two analyses disagreed. Looping each candidate and comparing
  # the last 100ms against the first settles it: 8.421s (114) rejoins itself at
  # -1.1 dB, 8.000s (120) at -8.6 dB. The 2.00s peak was a sub-bar repeat inside
  # the material, not the bar length -- worth remembering, because
  # self-similarity finds the shortest thing that repeats, which is not
  # necessarily the musical unit.
  #
  # hp/sub_db are provisional. Raw-loop measurement puts this at -6.6 dB
  # low-versus-mid, close to kembara_rindu's -5.9, which did need clearing --
  # but raw-loop numbers have already proved a poor predictor of render
  # behaviour here (semua_untuk_mu measures +1.7 raw and was the LEAST
  # problematic in a mix), so this is a starting point to check in a render
  # rather than a tuned value.
  lo_borges: { path: File.join(SAMPLE_DIR, "lo_borges", "loop.wav"), bpm: 114.0,
               hp: 60, sub_db: -3.0, lp: 6000 },

  # 2 bars at 92 BPM from one of the operator's own recordings, restored from
  # git history. Self-similarity picks 5.22s at 0.509, the clearest loop in
  # their own catalogue, and 92 is the tempo kembara_rindu already sits at.
  # C# minor at a Krumhansl fit of 0.70 -- the strongest reading of any of
  # their own tracks -- so it clears the harmonic guard comfortably.
  rauingar: { path: File.join(SAMPLE_DIR, "rauingar", "loop.wav"), bpm: 92.0,
              hp: 60, sub_db: -3.0, lp: 6200 },

  # Arat Swost Wolet, Ethiopian. 4 bars from 11.430s of the slowed copy.
  #
  # The de-vocaled stem, not the record: samples/arat_swost_wolet_slow.wav is
  # demucs's no_vocals output played at 0.8x, which the commit that added it does
  # not say and the audio does. Measured against the separated stems, on the
  # frames where the vocal sings the mix sits +4.90 dB above no_vocals and this
  # file sits -1.09 dB; on the frames where it is silent this file matches
  # no_vocals to +0.10 dB. So the singer is out, which is what makes it usable
  # as a bed under the engine's own harmony rather than a second tune.
  #
  # 84 BPM, decided by self-similarity rather than by onset spacing, which
  # disagreed. Onset gaps put it at 86.1; the repeat structure puts the bar at
  # 2.8575s and finds it again at 1, 2, 3, 4 and 5 bars -- five multiples of one
  # grid, which onset spacing cannot fake. 11.43s is 4 bars at 84. Its
  # self-repetition is 0.969, the cleanest in the rack by a distance (lo_borges,
  # previously the best, reads 0.654).
  #
  # A minor at a Krumhansl fit of 0.687, the strongest reading of anything here
  # except semua_untuk_mu.
  #
  # Known and not fixed: the loop does not rejoin cleanly. Its tail is about
  # 12 dB below its head, at EVERY candidate window on the grid, so it is the
  # phrase and not the cut -- the figure ends quiet. Expect an audible dip at
  # the seam and reach for LOOP_DELAY_BEATS or a crossfade if it matters. The
  # window at 11.430s was chosen because it has the best self-repetition and the
  # equal-best rejoin of the thirteen tried; bar 0 is within noise of it.
  #
  # hp/sub_db/lp are PROVISIONAL, in the same sense lo_borges's are and for the
  # same reason. Raw-loop bands, relative to the loudest: sub -0.7, low 0.0,
  # lomid -0.4, mid -8.0, hi -19.0, air -36.7. Low-versus-mid is +8.0 dB, which
  # is far more bass-forward than anything else in the rack (four_seven -4.9,
  # nightbus -10.3, lo_borges -6.6) -- this record brings a lot of its own low
  # end. But raw numbers have already proved a poor predictor of render
  # behaviour here, so these are a starting point to check in a render and not a
  # tuned value. The air figure is a cliff like four_seven's: there is nothing
  # above 8 kHz to recover with EQ, so SAMPLE_EXCITE is the knob for it.
  arat_swost_wolet: { path: File.join(SAMPLE_DIR, "arat_swost_wolet", "loop.wav"), bpm: 84.0,
                      hp: 90, sub_db: -6.0, lp: 6000 },
}.freeze

# The chopper's rack, merged in under the hand-cut one. Same shape, same bus,
# same per-loop hp/sub_db/lp fields -- a registered chop is a sample loop in
# every sense that matters here, selectable by name like any other:
#
#   ruby dilla.rb chop                       ingest samples/ubrukte_samples.mp3
#   TRACK=ubrukte_samples_03 ruby dilla.rb    render over that bed
#   CHOP_BED=1 ruby dilla.rb                  let the engine pick one by key
#
# BUILTIN wins a slug collision. Nothing generated should be able to take a name
# out from under an entry that was measured by hand.
TRACK_SAMPLE_LOOPS = RadioChop.registered_loops.merge(TRACK_SAMPLE_LOOPS_BUILTIN).freeze

# Hand-cut loops kept in the rack but deliberately kept OUT of the medley and
# the stream rotation. Still selectable by name (TRACK=rauingar), never
# chosen for you.
#
# This list exists so "no preset" can mean a decision rather than an oversight.
# Three of the four builtin loops had no preset and appeared in nothing the
# engine rendered on its own; that was an oversight, and nothing failed to say
# so. test_every_hand_cut_sample_loop_is_reachable_as_a_track_preset now holds
# the line, and reads this constant for the exceptions -- so leaving a loop out
# is one line here, and forgetting one is a test failure.
#
# rauingar: operator's call, 2026-08-07.
SAMPLE_LOOPS_OUT_OF_ROTATION = %i[rauingar].freeze

# The working names these two were ingested under, kept pointing at the same
# entries so anything already written against them keeps working. The song
# titles are the operator's; the old names were placeholders invented by the
# ingest (four_seven came off an Ableton set filename, nightbus was made up
# outright). kembara_rindu is the operator's best recollection rather than a
# verified title, so it is recorded as their attribution and not as fact.
TRACK_SAMPLE_LOOP_ALIASES = {
  four_seven: :kembara_rindu,
  nightbus: :semua_untuk_mu,
  # dmaj_open was a placeholder for a sample the operator had not yet named.
  dmaj_open: :lo_borges,
  # Sheger. The chopper slugs its output after the source FILE, and the file
  # was called ubrukte_samples.mp3 -- "unused samples", a working name for a
  # crate, not the name of the record. Eight chops came out of it and all eight
  # were carrying the filename. Same correction as four_seven -> kembara_rindu
  # above, and the reason is the same: the ingest invents a slug, the operator
  # knows what the record is.
  sheger_01: :ubrukte_samples_01,
  sheger_02: :ubrukte_samples_02,
  sheger_03: :ubrukte_samples_03,
  sheger_04: :ubrukte_samples_04,
  sheger_05: :ubrukte_samples_05,
  sheger_06: :ubrukte_samples_06,
  sheger_07: :ubrukte_samples_07,
  sheger_08: :ubrukte_samples_08,
}.freeze

# --- cross-sample processing ---------------------------------------------------
#
# Two records treated as one instrument. Both of these produce something neither
# loop can give on its own, which is the reason to prefer them over another
# effect applied to a single source.
#
#   DILLA_XCONVOLVE=1  one loop becomes the room the other is played in
#   DILLA_XGATE=1      one loop's harmony, the other's rhythm
#
# DILLA_XSAMPLE names the partner track (any key of TRACK_SAMPLE_LOOPS).
DILLA_XCONVOLVE = ENV["DILLA_XCONVOLVE"] == "1"
DILLA_XGATE = ENV["DILLA_XGATE"] == "1"
# Kept short on purpose. A long impulse convolves the partner's whole melody
# into the source and the result is mush; ~1s reads as a space rather than as a
# second tune.
XCONV_IR_SEC = (ENV["DILLA_XCONV_IR_SEC"] || 1.0).to_f.clamp(0.1, 4.0)
XCONV_WET = (ENV["DILLA_XCONV_WET"] || 0.62).to_f.clamp(0.0, 1.0)
# The envelope follower's smoothing. Too fast and it transfers individual
# waveform cycles, which is ring modulation, not gating.
XGATE_SMOOTH_HZ = (ENV["DILLA_XGATE_SMOOTH_HZ"] || 24).to_i
XGATE_FLOOR = (ENV["DILLA_XGATE_FLOOR"] || 0.18).to_f.clamp(0.0, 1.0)

def cross_sample_partner_path(self_track)
  name = ENV["DILLA_XSAMPLE"].to_s.strip
  return nil if name.empty?

  key = name.downcase.tr("-", "_").to_sym
  return nil if key.to_s == self_track.to_s.downcase.tr("-", "_")

  path = TRACK_SAMPLE_LOOPS.dig(key, :path)
  path if path && File.file?(path)
end

# Builds a short impulse response from the partner: trimmed, banded, and decayed
# so it does not ring forever. Deliberately NOT loudnorm'd -- afir's own irnorm
# then fights it, and the level is fixed by measurement after the convolution
# instead, where it can be matched to the actual source.
def cross_sample_impulse!(partner, dest)
  sh! "ffmpeg", "-y", "-t", XCONV_IR_SEC.to_s, "-i", partner,
      "-af", "highpass=f=90,lowpass=f=9000," \
             "afade=t=out:st=#{(XCONV_IR_SEC * 0.35).round(3)}:d=#{(XCONV_IR_SEC * 0.65).round(3)}",
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", dest
  dest
end

# Convolution output level depends entirely on the impulse's energy, which
# varies per sample pair, so no fixed gain is right. Measured on this pair:
# irnorm=1 landed at -62 dB against a -20 dB source (inaudible) and irnorm=0 at
# -0.2 dB (clipping). So convolve unnormalised, which is at least predictable,
# then match the source by measurement -- the same measure-then-gain the vocal
# cleaner uses for the same reason.
def cross_sample_convolve!(loop_path, partner, dest)
  ir = "#{dest}.ir.wav"
  cross_sample_impulse!(partner, ir)
  raw = "#{dest}.raw.wav"
  sh! "ffmpeg", "-y", "-i", loop_path, "-i", ir,
      "-filter_complex",
      "[0:a][1:a]afir=dry=#{(1.0 - XCONV_WET).round(3)}:wet=#{XCONV_WET}:" \
      "maxir=#{XCONV_IR_SEC}:irnorm=0[c];" \
      "[c]highpass=f=45[out]",
      "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
      "-c:a", "pcm_s16le", raw

  want = band_rms(loop_path, highpass: 20, lowpass: 20_000) rescue nil
  got = band_rms(raw, highpass: 20, lowpass: 20_000) rescue nil
  trim = if want&.finite? && got&.finite?
           (want - got).clamp(-48.0, 24.0)
         else
           0.0
         end
  sh! "ffmpeg", "-y", "-i", raw,
      "-af", "volume=#{trim.round(2)}dB,alimiter=limit=0.95:level_out=0.96",
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", dest
  dmesg("cross-sample convolve: matched #{got&.round(1)}dB → #{want&.round(1)}dB (#{trim.round(1)}dB)",
        unit: "xsmp0", parent: "dilla0")
  FileUtils.rm_f([ir, raw])
  dest
end

# The source's harmony driven by the partner's rhythm. amultiply rather than
# sidechaingate: a gate is a switch and leaves the source's own attacks intact
# between openings, while multiplying by a rectified, smoothed envelope makes
# the partner's shape the ONLY amplitude contour the result has.
def cross_sample_gate!(loop_path, partner, dest, duration:)
  env_path = "#{dest}.env.wav"
  # Rectify and smooth into a control signal, floored so the source never fully
  # disappears in the partner's gaps.
  sh! "ffmpeg", "-y", "-i", partner,
      "-af", "highpass=f=60,lowpass=f=8000,aeval=abs(val(0))|abs(val(1))," \
             "lowpass=f=#{XGATE_SMOOTH_HZ}," \
             "volume=#{(1.0 - XGATE_FLOOR).round(3)}," \
             "aeval=val(0)+#{XGATE_FLOOR}|val(1)+#{XGATE_FLOOR}," \
             "atrim=0:#{duration},apad=whole_dur=#{duration}",
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", env_path
  sh! "ffmpeg", "-y", "-i", loop_path, "-i", env_path,
      "-filter_complex",
      "[0:a]atrim=0:#{duration},apad=whole_dur=#{duration}[src];" \
      "[src][1:a]amultiply,alimiter=limit=0.95:level_out=0.96[out]",
      "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
      "-c:a", "pcm_s16le", dest
  FileUtils.rm_f(env_path)
  dest
end

def cross_sample_process(track, loop_path)
  # Morph first, cross-sample second: convolving a loop that has already been
  # turned into a chord gives the partner's room to the whole chord, which is
  # what you want; doing it the other way convolves the room itself into every
  # transposed copy and smears twice.
  if SAMPLE_FM || SAMPLE_SCALE
    morphed = sample_morph!(loop_path, File.join(Dir.tmpdir, "dilla_morph_#{Process.pid}.wav"))
    loop_path = morphed if morphed && File.file?(morphed)
  end
  return loop_path unless DILLA_XCONVOLVE || DILLA_XGATE

  partner = cross_sample_partner_path(track)
  unless partner
    warn "cross-sample: DILLA_XSAMPLE=#{ENV['DILLA_XSAMPLE'].inspect} is not another track's loop — skipping"
    return loop_path
  end

  out = loop_path
  begin
    if DILLA_XCONVOLVE
      dest = File.join(Dir.tmpdir, "dilla_xconv_#{Process.pid}.wav")
      out = cross_sample_convolve!(out, partner, dest)
      puts "cross-sample: convolved with #{File.basename(File.dirname(partner))} " \
           "(#{XCONV_IR_SEC}s impulse, wet #{XCONV_WET})"
    end
    if DILLA_XGATE
      dest = File.join(Dir.tmpdir, "dilla_xgate_#{Process.pid}.wav")
      len = audio_duration_sec(out).to_f
      out = cross_sample_gate!(out, partner, dest, duration: len.positive? ? len.round(3) : 8.0)
      puts "cross-sample: amplitude taken from #{File.basename(File.dirname(partner))} " \
           "(floor #{XGATE_FLOOR})"
    end
    out
  rescue StandardError => e
    warn "cross-sample: #{e.class} — #{e.message}; using the plain loop"
    loop_path
  end
end

# Is the sample bed itself short of low end, rather than the mix that used it?
#
# Measured on the raw SAMPLE_LOOP file, not on the processed bed: the question
# is what the source had, and cross_sample_process is both expensive and beside
# the point. Memoised per path — the quality gate asks once per take.
#
# Returns false when there is no sample bed at all, so an ordinary render is
# judged exactly as before.
def sample_bed_band_limited?(threshold = -9.0)
  raw = ENV["SAMPLE_LOOP"].to_s
  return false if raw.empty? || raw == "0" || !File.file?(raw)

  @sample_bed_delta ||= {}
  delta = @sample_bed_delta[raw] ||= begin
    DillaMaster.sub_kick_balance(render_spectrum(raw))[:low_mid_delta].to_f
  rescue StandardError => e
    warn "sample bed probe: #{e.class} — treating bed as full-range"
    0.0
  end

  limited = delta < threshold
  if limited && !@sample_bed_warned
    @sample_bed_warned = true
    warn "quality gate: sample bed #{File.basename(raw)} is band-limited " \
         "(low-mid #{delta.round(2)} dB) — sub deficit attributed to the source, not the mix"
  end
  limited
end

# SAMPLE_LOOP is a PATH, and "1" is not one.
#
# The variable names a specific file to use as the bed; empty means "look one up
# for this track". It reads like a switch, so it gets set like a switch, and
# SAMPLE_LOOP=1 sends it looking for a file called "1". That file does not
# exist, File.file? says so, and the method returns nil -- no bed, no warning,
# a track that renders perfectly and contains no sample at all.
#
# Thirteen beats were rendered that way before anyone noticed, every one of them
# with the flag set to turn samples ON.
#
# The truthy words now mean what everybody assumes they mean.
SAMPLE_LOOP_ON = %w[1 true yes on].freeze

# Which loop a track would use, WITHOUT processing it.
#
# Split out of sample_loop_for so the tempo can ask which record is going under
# the beat before deciding what tempo the beat is. sample_loop_for morphs and
# convolves on the way out, which is far too expensive to run from resolve_bpm
# and would recurse besides.
def sample_loop_entry(track)
  raw = ENV["SAMPLE_LOOP"].to_s.strip
  return if raw == "0"

  raw = "" if SAMPLE_LOOP_ON.include?(raw.downcase)
  unless raw.empty?
    # A slug, not only a path. SAMPLE_LOOP took a bare filename, so choosing a
    # known bed by hand meant passing its path and silently losing the hp/sub_db/
    # lp that TRACK_SAMPLE_LOOPS records for it -- and those are measured per
    # loop precisely because a global value is wrong for one of them whichever
    # way it goes (four_seven -4.9 dB against nightbus -10.3 dB, per that table).
    #
    # This is what lets a bed and a progression be chosen independently:
    # SAMPLE_LOOP picks the sample, TRACK still picks the chords. Before, both
    # came off TRACK, so a Dilla progression under the semua bed was not
    # expressible.
    slug = raw.downcase.tr("-", "_").to_sym
    named = TRACK_SAMPLE_LOOPS[TRACK_SAMPLE_LOOP_ALIASES.fetch(slug, slug)]
    return named if named

    return { path: raw, bpm: ENV.fetch("SAMPLE_LOOP_BPM", "0").to_f }
  end

  key = track.to_s.downcase.tr("-", "_").to_sym
  TRACK_SAMPLE_LOOPS[TRACK_SAMPLE_LOOP_ALIASES.fetch(key, key)] || chopped_bed_for(track)
end

def sample_loop_for(track)
  entry = sample_loop_entry(track)
  return unless entry && File.file?(entry[:path].to_s)

  # Memoised: sample_loop_for is called from several places in one render, and
  # each call would otherwise re-run the morph and the convolution.
  @cross_sample_cache ||= {}
  key = [track.to_s, entry[:path]]
  @cross_sample_cache[key] ||= cross_sample_process(track, entry[:path])
  entry.merge(path: @cross_sample_cache[key])
end

# The chopper's rack as a fallback bed for tracks that have no loop of their own.
#
# Off by default (CHOP_BED=1). Most of the rotation was written without a sampled
# bed under it, and switching one on for every track that lacks one is a change
# to the sound of the whole catalogue, not a feature.
#
# Chosen by key rather than at random, which is the only way this is any use.
# KEY_LOCK already transposes every progression to one tonic -- Bb by default --
# so the pads land in a known key on every render, and a bed in a different one
# is a bed fighting the arrangement. Loops carry their measured pitch class from
# ingest, so the match is a lookup rather than another analysis pass.
#
# Deterministic on the track name, not on rand: the same track has to get the
# same bed twice in a row or nothing downstream is reproducible.
def chopped_bed_for(track)
  return if ENV.fetch("CHOP_BED", "0") == "0"

  # Memoised per track for the same reason sample_loop_for memoises its own
  # processing: it is called from several places in one render, and without this
  # the pick is re-derived and re-announced four times a take.
  @chopped_bed_cache ||= {}
  return @chopped_bed_cache[track.to_s] if @chopped_bed_cache.key?(track.to_s)

  @chopped_bed_cache[track.to_s] = chopped_bed_pick(track)
end

def chopped_bed_pick(track)
  rack = RadioChop.registered_loops
  return if rack.empty?

  meta = Array(RadioChop.registry["loops"]).select { |l| rack.key?(l["slug"].to_s.to_sym) }
  wanted = KeyLock.enabled? ? KeyLock.pitch_class(KeyLock.target) : nil
  in_key = wanted ? meta.select { |l| l["key_pc"] == wanted } : []
  # Falling back to every loop rather than to none: an out-of-key bed is a
  # compromise, no bed at all when CHOP_BED was asked for is a dead switch.
  pool = in_key.empty? ? meta : in_key
  return if pool.empty?

  pool = pool.sort_by { |l| [-l["score"].to_f, l["slug"].to_s] }
  pick = pool[track.to_s.sum % pool.length]
  entry = rack[pick["slug"].to_s.to_sym]
  return unless entry

  dmesg("chop bed: #{pick['slug']} #{pick['key'] || '?'} @#{pick['bpm']} " \
        "#{in_key.empty? ? '(no key match)' : '(key-locked)'}", unit: "chop0", parent: "dilla0")
  entry
end

# --- sample loop excitation ---------------------------------------------------
#
# Measured on the two registered loops (mono, 44.1k, banded against each one's
# own loudest band):
#
#   four_seven   sub -4.0  low +0.0  lomid -6.9  mid -15.6  hi -39.9  air -52.7
#   semua 35-45  sub -7.3  low +0.0  lomid -9.5  mid -20.0  hi -32.6  air -33.7
#
# four_seven's -39.9/-52.7 is a cliff, not a rolloff: there is essentially no
# content above 3 kHz. That matters because the only high-frequency stage in
# this filter is a LOWPASS at 11 kHz -- it has nothing to remove, and no stage
# anywhere in the sample path puts anything back. An EQ shelf cannot help
# either; you cannot boost what is not there.
#
# The content has to be synthesised from the harmonics of what IS present,
# which is what an exciter does: split the signal, drive one copy into a
# non-linearity, high-pass the result so only the newly generated harmonics
# survive, and blend that under the dry. (Aural Exciter / parallel saturation;
# see Sound On Sound on restoring HF in pitch-shifted samples.)
#
# Character picks which harmonics get generated, and it is the "older or more
# modern" dial:
#   even  x + k*x*|x|   2nd/3rd order, tube and transformer bloom -- rounder,
#                       sits behind the beat, reads as older.
#   odd   tanh(d*x)     odd-order, console and transistor clipping -- harder
#                       and more present, reads as modern.
#
# Off by default: it changes the sound of every registered loop, and the right
# amount is per-sample. SAMPLE_EXCITE=0.3 is a sensible starting point for
# four_seven; a sample that already has air needs far less or none.
SAMPLE_EXCITE_MIX = (ENV["SAMPLE_EXCITE"] || "0").to_f.clamp(0.0, 1.0)
SAMPLE_EXCITE_HZ = (ENV["SAMPLE_EXCITE_HZ"] || "2200").to_f
SAMPLE_EXCITE_DRIVE = (ENV["SAMPLE_EXCITE_DRIVE"] || "1.0").to_f.clamp(1.0, 20.0)
SAMPLE_EXCITE_CHARACTER = (ENV["SAMPLE_EXCITE_CHARACTER"] || "even").to_s.downcase

def sample_excite_shaper
  unless SAMPLE_EXCITE_CHARACTER.start_with?("odd")
    k = (SAMPLE_EXCITE_DRIVE * 0.06).round(4)
    return "aeval=exprs='val(0)+#{k}*val(0)*abs(val(0))|val(1)+#{k}*val(1)*abs(val(1))'"
  end

  n = Math.tanh(SAMPLE_EXCITE_DRIVE).round(6)
  "aeval=exprs='tanh(#{SAMPLE_EXCITE_DRIVE}*val(0))/#{n}|tanh(#{SAMPLE_EXCITE_DRIVE}*val(1))/#{n}'"
end

def build_sample_loop_filter(idx, duration, loop_bpm, target_bpm)
  # Looked up first because the per-loop defaults below all read from it. It was
  # assigned further down and referenced up here, which in Ruby is nil rather
  # than an error -- so the per-loop settings would have been silently ignored
  # instead of failing loudly.
  entry = sample_loop_for(ENV["TRACK"]) || {}

  # Tempo-match rather than resample: the loop was warped in the DAW at its own
  # BPM, so play it at the render's tempo instead of letting it drift.
  ratio = loop_bpm.to_f.positive? ? (target_bpm / loop_bpm).clamp(0.5, 2.0) : 1.0

  # Varispeed: pitch follows speed, the way a record does.
  #
  # atempo holds pitch while changing tempo, which is the modern, correct-sounding
  # option and is not what these records did. Slowing a sample on an MPC or a
  # turntable drops its pitch with it -- that is where the thickness comes from,
  # and why a sped-up sample sounds thin no matter how it is EQ'd. asetrate then
  # aresample reproduces it exactly, and the bar grid still lines up, because
  # playing a 4-bar loop at ratio r gives 4 bars at r times the tempo either way.
  #
  # SAMPLE_LOOP_SEMITONES pitches further WITHOUT changing tempo, for when the
  # tempo is already where it should be and only the weight is missing. It is
  # applied as an extra resample and undone with atempo, so the two controls stay
  # independent: one moves both, the other moves only pitch.
  # Varispeed on by default. Holding a sample's pitch while slowing it is the
  # modern-sounding choice and the wrong one here: these records were slowed on
  # a sampler, pitch fell with speed, and that fall is where the weight is.
  varispeed = ENV.fetch("SAMPLE_LOOP_VARISPEED", entry[:varispeed] == false ? "0" : "1") != "0"
  extra_semis = ENV.fetch("SAMPLE_LOOP_SEMITONES", "0").to_f.clamp(-12.0, 12.0)

  tempo = if (ratio - 1.0).abs < 0.001
            ""
          elsif varispeed
            # Say how far the pitch actually moved. BPM_SCALE defaults to 0.96,
            # which pulls samples down about 0.71 semitones — a real transposition
            # that nothing in the output ever mentioned, so it read as "the tracks
            # sound lower" without a number attached to it. It also means a key
            # lock cannot be checked by ear against a sampled bed unless you know
            # this figure. Reported, not changed: pitch falling with speed is the
            # point, per the note above.
            semis = 12.0 * Math.log2(ratio)
            if semis.abs > 0.05
              dmesg(format("varispeed: samples %+.2f semitones (ratio %.4f)", semis, ratio),
                    unit: "smpl0", parent: "dilla0")
            end
            "asetrate=#{(SAMPLE_RATE * ratio).round},aresample=#{SAMPLE_RATE},"
          else
            "atempo=#{ratio.round(5)},"
          end

  unless extra_semis.zero?
    shift = 2.0**(extra_semis / 12.0)
    # Resample moves pitch and length together; atempo puts the length back.
    comp = 1.0 / shift
    stages = []
    stages << 2.0 while comp / stages.inject(1.0, :*) > 2.0
    stages << 0.5 while comp / stages.inject(1.0, :*) < 0.5
    stages << (comp / stages.inject(1.0, :*))
    tempo += "asetrate=#{(SAMPLE_RATE * shift).round},aresample=#{SAMPLE_RATE}," +
             stages.map { |s| "atempo=#{s.round(6)}" }.join(",") + ","
  end
  vol = ENV.fetch("SAMPLE_LOOP_VOL", "0.8").to_f
  # A sampled record arrives with its own kick and bass already in it, and until
  # now nothing here could reach them: the highpass was a hardcoded 45 and there
  # was no shelf. Measured on four_seven with normalisation off, muting the
  # engine's kick moved the 40-100 Hz band by 0.0 dB and muting the synth bass
  # by 0.0 dB, while muting the loop moved it by -4.0 dB. The loop was the whole
  # low end -- which is why turning KICK_GAIN down never fixed a low end that
  # was too loud, across three attempts.
  # Per-loop defaults from TRACK_SAMPLE_LOOPS; env still wins when pinned.
  hp = (ENV["SAMPLE_LOOP_HP"] || entry[:hp] || 45).to_i
  sub_db = (ENV["SAMPLE_LOOP_SUB_DB"] || entry[:sub_db] || 0).to_f
  sub_eq = sub_db.zero? ? "" : "equalizer=f=90:t=o:w=1.1:g=#{sub_db},"
  # Wow on the LOOP only, never the kit. A sampled record has tape or vinyl
  # instability in it and a drum machine does not; modulating both together
  # sounds like the whole mix is unstable, while modulating only the sample
  # sounds like the sample came off a record. Two slow rates rather than one so
  # it does not tick.
# LOOP_WOW is disabled here rather than left in place looking functional.
#
# It was built on vibrato, which is transparent in this ffmpeg build: depths
# of 0.1, 0.5 and 0.9 all produce output identical to the input. A switch that
# reports a value and changes nothing is worse than one that is absent,
# because it silently absorbs the attempt to use it.
#
# A working implementation already exists in lib/tape_hysteresis.rb --
# Ornstein-Uhlenbeck drift driving a fractional-delay read, in Ruby, verified.
# Reach for TAPE_WOW_MS instead, which applies it to the master.
wow = ""
if ENV["LOOP_WOW_CENTS"].to_f.positive?
  warn "LOOP_WOW_CENTS: vibrato is transparent in this ffmpeg build — use TAPE_WOW_MS"
end

  # Tempo-synced delay on the loop. Dotted-8th is 3/16 of a bar and is the
  # figure that reads as hip-hop rather than as an effect: at 92 BPM that is
  # 489ms. Feedback stays low because the loop is already repeating -- a long
  # tail on a repeating source turns into mud within two bars.
  echo_beats = ENV.fetch("LOOP_DELAY_BEATS", "0").to_f
  echo = if echo_beats.positive? && target_bpm.to_f.positive?
           ms = ((60.0 / target_bpm) * echo_beats * 1000).round
           "aecho=0.8:#{ENV.fetch('LOOP_DELAY_MIX', '0.32')}:#{ms}:" \
             "#{ENV.fetch('LOOP_DELAY_FEEDBACK', '0.28')},"
         else
           ""
         end

  # sample_modern_chain is the addition that matches sonitex_enabled? turning
  # Sonitex off for a sampled bed: denoise / air / sub / width on the LOOP,
  # not the master. SAMPLE_MODERN=0 keeps the old subtraction-only path.
  modern = sample_modern_chain
  modern_s = modern && !modern.empty? ? "#{modern}," : ""
  # The sampled bed gets the shaping the pad bus gets, or it stays a bed.
  #
  # build_harm_bus_filter lifts body, mid, presence and air into the chords --
  # four additive stages plus a sub cut -- and the loop chain had none of them.
  # Everything above this line is subtractive: a highpass, a mud cut and a
  # lowpass. A sample run through only those cannot sit beside a pad that has
  # been lifted in four bands; it reads as something playing behind the track
  # rather than an instrument in it, which is the whole difference between a
  # loop and a voice.
  #
  # Every default here is 0.0, so a render that does not ask for them is the
  # render it was before. SAMPLE_LOOP_VOL (0.8 against the harm bus's 1.68) and
  # SAMPLE_LOOP_WEIGHT (0.9 against 1.52) are the other half of the gap and are
  # already knobs; these are the half that had no control at all.
  #
  # Centres match the harm bus rather than being picked fresh: 220 Hz body,
  # 900 Hz mid, 2.8 kHz presence, 6 kHz air. Sharing centres is what lets the
  # two buses be balanced against each other by ear instead of fighting in
  # different bands.
  body_g = ENV.fetch("SAMPLE_LOOP_BODY_DB", "0").to_f
  mid_g = ENV.fetch("SAMPLE_LOOP_MID_DB", "0").to_f
  pres_g = ENV.fetch("SAMPLE_LOOP_PRESENCE_DB", "0").to_f
  air_g = ENV.fetch("SAMPLE_LOOP_AIR_DB", "0").to_f
  shape = +""
  shape << "equalizer=f=220:t=o:w=1.2:g=#{body_g}," unless body_g.zero?
  shape << "equalizer=f=900:t=o:w=1.4:g=#{mid_g}," unless mid_g.zero?
  shape << "equalizer=f=2800:t=h:w=1800:g=#{pres_g}," unless pres_g.zero?
  shape << "equalizer=f=6000:t=h:w=2800:g=#{air_g}," unless air_g.zero?

  common = "aformat=channel_layouts=stereo,#{tempo}volume=#{vol}," \
           "#{wow}#{echo}#{modern_s}" \
           "highpass=f=#{hp}," \
           "#{sub_eq}" \
           "equalizer=f=300:t=o:w=1.4:g=#{ENV.fetch('SAMPLE_LOOP_MUD_DB', '-2.0')}," \
           "#{shape}" \
           "lowpass=f=#{(ENV['SAMPLE_LOOP_LP'] || entry[:lp] || 11_000).to_i}"
  tail = "atrim=0:#{duration},apad=whole_dur=#{duration},asetpts=PTS-STARTPTS"

  return "[#{idx}:a]#{common},#{tail}[loopbed]" if SAMPLE_EXCITE_MIX <= 0.0

  # The high-pass on the wet branch is the whole trick: it discards the band
  # the dry signal already covers and keeps only the harmonics the shaper
  # invented above it, so this adds air instead of adding distortion.
  #
  # The blend level rides on the wet branch as a `volume`, NOT as amix
  # `weights`: the weights value is space-separated ("1 0.3") and a bare space
  # inside a filtergraph does not survive parsing, so the weights were dropped
  # and both branches summed at unity. Measured, that raised the low band by
  # the same 2.4 dB as the air band -- a broadband level increase wearing an
  # exciter's clothes. With the gain on the branch instead, the low band moves
  # 0.0 dB and only 3 kHz upward changes, which is the entire point.
  #
  # normalize=0 stops amix halving the dry level to make headroom.
  "[#{idx}:a]#{common},asplit=2[lpdry#{idx}][lpwet#{idx}];" \
    "[lpwet#{idx}]#{sample_excite_shaper},highpass=f=#{SAMPLE_EXCITE_HZ.round}:poles=2," \
    "volume=#{SAMPLE_EXCITE_MIX.round(3)}[lpexc#{idx}];" \
    "[lpdry#{idx}][lpexc#{idx}]amix=inputs=2:normalize=0," \
    "#{tail}[loopbed]"
end

# --------------------------------------------------------------------------
# engine part: bus_filters
# --------------------------------------------------------------------------
#
# Bus filter chains: analog colour, bass, harmony, sidechain and bridges.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# The bass gets its own bus rather than riding the harmonic one. It used to be
# mixed into the harmonic render, which is high-passed to keep pad mud out of
# the kick's way -- and that corner sits ABOVE the bass fundamental (roots land
# at 82-116 Hz), so the bass was filtered out of the mix it was supposed to
# anchor. That is also why the earlier attempts to fix it by raising BASS_VOL
# and lowering the harm corner never moved the master: the level was never the
# problem, the routing was. The engine's own quality gate had been rejecting
# every take on "sub=boost_sub (low-mid -9.51 dB)" because of it.
# Per-channel analog treatment, applied BEFORE the buses are summed.
#
# The master already runs sonitex tape and an analog chain, but that stage only
# ever sees the sum. A desk does not work that way: every channel saturates on
# the way in, so each source generates its own harmonics first and those
# harmonics then intermodulate in the bus. One saturator on the sum cannot
# produce that, because by the time it runs the sources no longer exist
# separately.
#
# Character differs per bus because the sources do. Drums take the hardest
# drive -- transients are what saturation flatters. Bass takes the least: it is
# already the loudest thing in the low end and driving it turns definition into
# mud. Harmony sits between, where a little bloom thickens pads without
# blurring their attacks.
# 0.18. Per-bus colour plus the small phase offsets below, so the buses do not
# sum perfectly coherently. Off by default meant every bus summed like maths.
BUS_ANALOG = (ENV["BUS_ANALOG"] || 0.18).to_f.clamp(0.0, 1.0)

BUS_ANALOG_CHARACTER = {
  drums: { drive: 1.0, tilt: 2.2, hz: 3200 },
  bass:  { drive: 0.45, tilt: 0.8, hz: 900 },
  harm:  { drive: 0.7, tilt: 1.4, hz: 2400 },
}.freeze

# Small per-bus phase offsets so the buses do not sum perfectly coherently.
# Real summing is never phase-aligned -- each channel takes a slightly different
# path -- and that incoherence is most of what "phasy summing" means. The
# offsets are tiny and fixed: large ones comb-filter, and random ones make a
# render unreproducible.
BUS_PHASE_MS = { drums: 0.0, bass: 0.35, harm: 0.62 }.freeze

def bus_analog_filter(bus)
  return "" if BUS_ANALOG <= 0.0

  c = BUS_ANALOG_CHARACTER.fetch(bus)
  d = BUS_ANALOG * c[:drive]
  phase = BUS_PHASE_MS.fetch(bus) * BUS_ANALOG
  parts = []
  # Drive hard, clip low, then take the level back out.
  #
  # The first version drove by 1.44x into a threshold of 0.76 and measured as
  # doing nothing at all -- because an individual bus peaks far below the summed
  # mix, so a threshold set for master levels is never reached and the clipper
  # never engages. A saturator that never saturates is a gain stage with a
  # misleading name. Threshold now scales DOWN with drive so the harder it is
  # pushed the sooner it bites, which is what the control is supposed to mean.
  # alimiter, not asoftclip. Tested on a clean 200 Hz sine, where any energy
  # above 500 Hz can only be harmonics the stage invented: asoftclip produced
  # -40.8 dB against -40.1 dB clean, which is nothing, at any threshold tried.
  # acrusher likewise. Drive into a low limiter ceiling gives -19.1 dB, i.e. 21
  # dB of genuine harmonic content. Two earlier attempts here failed because
  # they tuned the parameters of a filter that was transparent to begin with --
  # the primitive was wrong, not the settings.
  drive = 1.0 + (2.2 * d)
  parts << "volume=#{drive.round(3)}"
  parts << "alimiter=limit=#{(0.45 - (0.28 * d)).round(3)}:level_out=1:attack=1:release=20"
  parts << "volume=#{(1.0 / (1.0 + (2.2 * d))).round(3)}"
  # Tape tilt: a little lift where the source lives, gentle roll above it.
  parts << "equalizer=f=#{c[:hz]}:t=o:w=1.4:g=#{(c[:tilt] * d).round(2)}"
  parts << "adelay=#{(phase * 1000).round}|#{((phase * 1000) * 1.3).round}" if phase.positive?
  "#{parts.join(',')},"
end

def build_bass_bus_filter(idx, duration)
  vol = ENV.fetch("BASS_BUS_VOL", "1.4").to_f
  sub_g = ENV.fetch("BASS_BUS_SUB_DB", "3.0").to_f
  mud_g = ENV.fetch("BASS_BUS_MUD_DB", "-1.5").to_f
  "[#{idx}:a]aformat=channel_layouts=stereo,#{bus_analog_filter(:bass)}volume=#{vol}," \
    "highpass=f=26," \
    "equalizer=f=70:t=o:w=1.1:g=#{sub_g}," \
    "equalizer=f=180:t=o:w=1.2:g=#{mud_g}," \
    # The Pultec move on top of the two bands above: a broad lift under 100 Hz
    # and a narrower dip near 280 -- the shape no single control produces, and
    # the reason a fifty-year-old passive equaliser is still on every low end.
    # Measured at +3.7 dB and -1.9 dB, flat again by a kilohertz.
    "#{Outboard.pultec_low}," \
    "lowpass=f=1400," \
    "acompressor=threshold=-20dB:ratio=2.4:attack=14:release=150:makeup=1.5," \
    "atrim=0:#{duration},apad=whole_dur=#{duration}," \
    "alimiter=limit=0.95:level_out=0.97[bassbus]"
end

# The Space Echo on the pads.
#
# Two of them sit in Flying Lotus's studio and it is on a great deal of what he
# has made. On a chord bed it does something no reverb does: the repeats are
# darker and less steady than the source, so the pad trails off into something
# that is recognisably the same chord and recognisably older than it. That is
# the depth in his records, and it is a delay rather than a reverb doing it.
#
# On the pads only. Through the drums it smears the transients the kit exists
# for, and on the bass it muddies the octave the Pultec was cleaning.
def harm_space_echo
  return nil unless ENV.fetch("SPACE_ECHO", "1") != "0"

  Outboard.space_echo(time_ms: ENV.fetch("SPACE_ECHO_MS", "260").to_f,
                      feedback: ENV.fetch("SPACE_ECHO_FB", "0.55").to_f,
                      mix: ENV.fetch("SPACE_ECHO_MIX", "0.4").to_f)
end

def build_harm_bus_filter(idx, duration, _cfg, sonic, harm_fade_start, harm_fade_dur, beat_p, _n_bars)
  lp = sonic_pad_lowpass(sonic)
  build_start = (duration * 0.82).round(2)
  # 16 beats, but never longer than the render itself — short (preview/smoke)
  # renders would otherwise produce a negative afade start, which ffmpeg
  # rejects as out of range.
  outro_fade = [(beat_p * 4.0 * 4).round(2), duration].min
  # Pads are the character of the stream — keep them warm and present.
  # Kick space is a gentle HP + sidechain, not stripping pad body (165 Hz HP
  # + −5.5 dB sub cut made progressions inaudible).
  default_vol = if wonky_primary_drums?
                  "1.72"
                elsif deep_render?
                  "1.82"
                else
                  "1.68"
                end
  harm_vol = ENV["DEBUG_HARM_WEIGHT"] || ENV.fetch("HARM_BUS_VOL", default_vol)
  deep = deep_render?
  sub_cut = ENV.fetch("HARM_SUB_CUT_DB", if deep
"-1.8"
else
(wonky_primary_drums? ? "-2.4" : "-2.2")
end)
  body_boost = ENV.fetch("HARM_BODY_DB", if deep
"3.2"
else
(wonky_primary_drums? ? "2.6" : "2.8")
end)
  mid_boost = ENV.fetch("HARM_MID_DB", if deep
"2.9"
else
(wonky_primary_drums? ? "2.4" : "2.6")
end)
  # Chord presence: body + gentle silk shelf (progressions read on small speakers).
  # HARM_PRESENCE_DB / HARM_AIR_DB are crit cherry-pick knobs (defaults keep prior character).
  presence = ENV.fetch("HARM_PRESENCE_DB", wonky_primary_drums? ? "2.2" : "2.4").to_f
  air_g = ENV.fetch("HARM_AIR_DB", wonky_primary_drums? ? "1.6" : "1.2").to_f
  silk_g = wonky_primary_drums? ? [presence * 0.9, 2.0].min : [presence * 0.55, 1.2].min
  air = if wonky_primary_drums?
          "equalizer=f=2400:t=h:w=1800:g=#{silk_g.round(1)},equalizer=f=5200:t=h:w=2800:g=#{air_g.round(1)},"
        else
          "equalizer=f=2800:t=h:w=1800:g=#{air_g.round(1)},"
        end
  # The synthesised bass rides this bus, and its roots land at 82-116 Hz
  # (E2 for the Get Dis Money pedal). A 110 Hz corner cut the bass fundamental
  # straight out of the mix, which is why the track had no low end -- and why
  # the old hz.min bass bug went unnoticed for so long: playing the wrong note
  # up at 165-208 Hz was the only way the bass got past this filter at all.
  # Pads cannot be hurt by opening it up: measured across every track, the
  # lowest voiced pad tone is 164-247 Hz, so nothing pad-side lives below the
  # old corner. Kept high enough to still shed sub rumble.
  harm_hp = ENV.fetch("HARM_HP_HZ", if deep
"66"
else
(wonky_primary_drums? ? "68" : "70")
end).to_i
  sub_shelf = ENV.fetch("HARM_SUB_SHELF_DB", if deep
"2.2"
else
(wonky_primary_drums? ? "1.8" : "1.0")
end).to_f
  # Longer, smoother pad bloom (qsin) so chords arrive as wash, not a gate.
  fade_in = wonky_primary_drums? ? (harm_fade_dur * 1.35).round(2) : harm_fade_dur
  fade_curve = wonky_primary_drums? ? ":curve=qsin" : ""
  build_cut = wonky_primary_drums? ? -0.8 : -2
  "[#{idx}:a]aformat=channel_layouts=stereo,volume=#{harm_vol}," \
    "highpass=f=#{harm_hp},equalizer=f=72:t=o:w=1.2:g=#{sub_shelf}," \
    "equalizer=f=95:t=h:w=120:g=#{sub_cut}," \
    "equalizer=f=420:t=o:w=1.1:g=#{body_boost},equalizer=f=680:t=h:w=900:g=#{mid_boost}," \
    "equalizer=f=1400:t=h:w=1200:g=#{presence}," \
    "#{air}equalizer=f=#{lp}:t=o:w=1.0:g=0.8," \
    "#{pad_wow_stage}" \
    "afade=t=in:st=#{harm_fade_start}:d=#{fade_in}#{fade_curve}," \
    "afade=t=out:st=#{(duration - outro_fade).round(2)}:d=#{outro_fade}#{fade_curve}," \
    "equalizer=f=800:t=h:w=600:g=#{build_cut}:enable='between(t,#{build_start},#{duration})'" \
    "#{harm_space_echo ? "[harm_pre];[harm_pre]#{harm_space_echo}[harm]" : '[harm]'}"
end

# Tape wow on the pad, and nothing else.
#
# The harmony bus had no modulation anywhere in it: EQ, two fades and a
# build-side cut, all static. A chord that holds perfectly still for four bars
# is the one thing a sampled record never does, and it is why a synthesised pad
# reads as synthetic however good the voicing is -- the ear hears the absence
# of drift before it hears the notes.
#
# vibrato, not chorus. Chorus adds delayed copies, which thickens and blurs;
# wow is the tape transport running fractionally uneven, so it is a slow shift
# in pitch of the ONE signal. 0.32 Hz is about three seconds a cycle, slower
# than any note lasts, so it is felt as breathing rather than heard as an
# effect. Depth 0.045 measured as +-1.5 Hz on a 440 Hz tone, about 6 cents --
# under the ~15 cent threshold where a held chord stops sounding alive and
# starts sounding out of tune.
#
# PAD_WOW=0 turns it off; PAD_WOW=<0..1> scales rate and depth together.
def pad_wow_stage
  amt = ENV.fetch("PAD_WOW", "1.0").to_f.clamp(0.0, 1.0)
  return "" if amt <= 0.0

  "vibrato=f=#{(0.32 * (0.7 + 0.3 * amt)).round(3)}:d=#{(0.045 * amt).round(4)},"
end

def sidechain_amix_weights
  # Camel: pads duck under kicks but stay the main body (not 2.05:0.78 — that
  # erased chord progressions). Kit still leads the transient.
  d = ENV.fetch("SIDECHAIN_DRUM_WEIGHT", wonky_primary_drums? ? "1.48" : "1.0").to_f
  h = ENV.fetch("SIDECHAIN_HARM_WEIGHT", wonky_primary_drums? ? "1.32" : "1.55").to_f
  [d.round(3), h.round(3)]
end

def wonky_sidechain_filters(drum_label: "[drums]", harm_label: "[harm]")
  dw, hw = sidechain_amix_weights
  # Musical duck: soft attack + longer release so pads bloom back between kicks
  # (was attack=1/release=28 — choppy, made progressions feel gated).
  atk = wonky_primary_drums? ? 8 : 1
  rel = wonky_primary_drums? ? 140 : 28
  ratio = wonky_primary_drums? ? 3.2 : 5
  thr = wonky_primary_drums? ? -22 : -20
  [
    "#{drum_label}asplit=2[dr_dry][dr_sc]",
    "#{harm_label}[dr_sc]sidechaincompress=threshold=#{thr}dB:ratio=#{ratio}:attack=#{atk}:release=#{rel}:level_sc=0.9[harm_sc]",
    "[dr_dry][harm_sc]amix=inputs=2:weights=#{dw} #{hw}:duration=first:normalize=0[sc_mix]",
  ]
end

# Tight kick-triggered duck — short attack/release for MPC pocket, not wash.
def dilla_sidechain_filters(drum_label: "[drums]", harm_label: "[harm]")
  dw, hw = sidechain_amix_weights
  [
    "#{drum_label}asplit=2[dr_dry][dr_sc]",
    "#{harm_label}[dr_sc]sidechaincompress=threshold=-24dB:ratio=5:attack=0.3:release=90:level_sc=0.88[harm_sc]",
    "[dr_dry][harm_sc]amix=inputs=2:weights=#{dw} #{hw}:duration=first:normalize=0[sc_mix]",
  ]
end

# Puts the kit in front by moving the sample out of its way, band by band.
#
# The sampled bed joined the master mix undicked, at full bandwidth, while the
# kit sat behind it. A record and a drum kit occupy the same frequencies -- the
# record HAS drums in it, or had them until demucs took them out, and it still
# has the room they were played in. Two full-range signals in one place is what
# a muddy mix is.
#
# Turning the kit up is the wrong repair: it makes a loud muddy mix. Instead the
# bed is split into three bands and only two of them move.
#
#   below 180 Hz   ducks hard when the kick lands. Nothing else may be there.
#   180 Hz - 3 kHz untouched. This is the body of the record, the reason the
#                  track exists, and it is not where drums need clarity.
#   above 3 kHz    ducks lightly on the snare and hats, which is what "crisp"
#                  actually means -- room at the top for the transient.
#
# Each band is keyed by the drums filtered to that same band, so the low band
# responds to kicks and not to hats. The result is a kit that reads clearly
# through a bed that still sounds whole.
DRUM_FORWARD_SPLIT = [180, 3000].freeze

def drum_forward_filters(bed: "[loopbed]", key: "[dr_key]", out: "[bedcarved]")
  low_thr = ENV.fetch("DRUM_FORWARD_LOW_DB", "-30")
  air_thr = ENV.fetch("DRUM_FORWARD_AIR_DB", "-26")
  [
    # One key signal per band that ducks, filtered to hear only its own drums.
    "#{key}asplit=2[dk_lo][dk_hi]",
    "[dk_lo]lowpass=f=#{DRUM_FORWARD_SPLIT[0]}[dkl]",
    "[dk_hi]highpass=f=#{DRUM_FORWARD_SPLIT[1]}[dkh]",
    "#{bed}acrossover=split=#{DRUM_FORWARD_SPLIT.join(' ')}:order=4th[bd_lo][bd_mid][bd_hi]",
    # Fast attack on the low band: the kick's first cycle is the whole point, and
    # a slow attack lets the bed's own bass through underneath it.
    "[bd_lo][dkl]sidechaincompress=threshold=#{low_thr}dB:ratio=8:attack=1:release=120:level_sc=1.0[bd_lo_sc]",
    # Gentler and quicker up top: this is opening a window for a transient, not
    # pumping. A long release here would breathe audibly on every hat.
    "[bd_hi][dkh]sidechaincompress=threshold=#{air_thr}dB:ratio=4:attack=0.4:release=55:level_sc=1.0[bd_hi_sc]",
    "[bd_lo_sc][bd_mid][bd_hi_sc]amix=inputs=3:weights=1 1 1:duration=first:normalize=0#{out}",
  ]
end

# Sharpens the kit without raising it.
#
# A compressor with a SLOW attack is the transient shaper nobody names as one:
# by the time it clamps down, the stick hit has already passed through
# untouched, and what it compresses is the body behind it. The attack therefore
# stands further above its own tail than it did going in. That is "crisper", and
# it costs no headroom, unlike turning the drums up.
#
# The shelf above 7 kHz is the stick and the hat sizzle. Small: this is a lo-fi
# engine and 3 dB of air is the difference between dull and modern, while 8 dB
# is the difference between modern and cheap.
def drum_crisp_chain
  return nil if ENV["DRUM_CRISP"] == "0"

  attack = ENV.fetch("DRUM_CRISP_ATTACK", "22")
  air = ENV.fetch("DRUM_CRISP_AIR_DB", "3")
  "acompressor=threshold=-18dB:ratio=4:attack=#{attack}:release=70:makeup=1.6," \
    "treble=g=#{air}:f=7000:width_type=q:width=0.7"
end

# Joins one section of the record to the next the way a producer would.
#
# A looped sample restated every four bars announces itself as a loop. What
# stops it is a gesture in the last beat before the turnover -- something that
# takes the ear off the seam. Dilla's records are full of these and they are not
# subtle when you look for them: the filter shuts for half a beat and snaps
# open on the one; everything drops out and the record plays naked; the whole
# thing swells up from nothing into the downbeat.
#
# Three treatments, chosen per boundary from the track name so a given track
# always bridges the same way:
#
#   :sweep    the lowpass closes over the last beat and opens on the downbeat.
#             The most common of the three because it is the least tiring.
#   :dropout  the bed cuts for the back half of the last beat. Silence is a
#             transition. This is the one that makes the return feel like an
#             arrival.
#   :swell    the bed rises from near nothing across the last bar, so the
#             downbeat is the top of a ramp rather than a restart.
#
# Sweeps run through asendcmd rather than an expression because lowpass takes
# its cutoff as a runtime command, not a per-frame formula -- twelve stepped
# commands per boundary, geometrically spaced, which the ear reads as a glide.
BRIDGE_KINDS = %i[sweep dropout swell sweep].freeze
BRIDGE_SWEEP_STEPS = 12
BRIDGE_OPEN_HZ = 16_000
BRIDGE_CLOSED_HZ = 320

def bridge_plan(n_bars, bar_sec, track, every_bars)
  return [] if every_bars < 1 || n_bars <= every_bars

  rng = Random.new(stable_hash("bridge:#{track}"))
  # Boundaries are the downbeats between sections. The final bar has no section
  # after it, so it gets no bridge -- a gesture into silence is a fade.
  (every_bars...n_bars).step(every_bars).map do |bar|
    { at: (bar * bar_sec).round(4), kind: BRIDGE_KINDS[rng.rand(BRIDGE_KINDS.length)] }
  end
end

def bridge_filters(input:, output:, n_bars:, bar_sec:, track:, every_bars: 4)
  plan = bridge_plan(n_bars, bar_sec, track, every_bars)
  return ["#{input}anull#{output}"] if plan.empty?

  beat = bar_sec / 4.0
  cmds = []
  gates = []
  plan.each do |b|
    case b[:kind]
    when :sweep
      # Close across the last beat, then reopen exactly on the downbeat. The
      # reopen is a single command, not a ramp: the snap is the effect.
      BRIDGE_SWEEP_STEPS.times do |i|
        frac = (i + 1).to_f / BRIDGE_SWEEP_STEPS
        hz = (BRIDGE_OPEN_HZ * ((BRIDGE_CLOSED_HZ.to_f / BRIDGE_OPEN_HZ)**frac)).round
        cmds << "#{(b[:at] - beat + (beat * frac)).round(4)} lowpass frequency #{hz}"
      end
      cmds << "#{b[:at].round(4)} lowpass frequency #{BRIDGE_OPEN_HZ}"
    when :dropout
      gates << "between(t,#{(b[:at] - (beat * 0.5)).round(4)},#{b[:at].round(4)})*1"
    when :swell
      # A quarter-power curve rather than a straight line: linear ramps in
      # amplitude are heard as back-loaded, since loudness follows the log.
      gates << "between(t,#{(b[:at] - bar_sec).round(4)},#{b[:at].round(4)})*" \
               "(1-pow((t-#{(b[:at] - bar_sec).round(4)})/#{bar_sec.round(4)},0.25))"
    end
  end

  # One volume expression for every dip in the track. Each term is zero outside
  # its own window, so summing them and subtracting from 1 gives full level
  # everywhere a bridge is not happening.
  duck = gates.empty? ? nil : "volume='max(0,1-(#{gates.join('+')}))':eval=frame"
  stages = ["lowpass=f=#{BRIDGE_OPEN_HZ}"]
  stages.unshift("asendcmd='#{cmds.join('; ')}'") unless cmds.empty?
  stages << duck if duck
  ["#{input}#{stages.join(',')}#{output}"]
end

# --------------------------------------------------------------------------
# engine part: render_helpers
# --------------------------------------------------------------------------
#
# Small render helpers shared across the engines.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Hands the record and this track's chords to SampleFlip, and returns a loop
# entry pointing at what comes back.
#
# The returned entry claims the render's own tempo. That is not a fib: the flip
# was assembled beat by beat at that tempo, so the varispeed stage downstream
# has nothing left to correct and correctly does nothing.
# Off by default, and the reason matters more than the switch.
#
# A flip cuts a record into pieces and plays a new line from them. That is
# Dilla's method and it is right for the records he used, where a piece was
# itself a musical unit -- a chord stab, a bass note, a horn hit. Cut those up
# and reorder them and you get a new tune out of old parts.
#
# These chops are not that. They are flowing melodic passages off an Ethiopian
# broadcast, and the reason they are worth having is the melody running through
# them. Cutting a melody into sixteen fragments and reordering by pitch destroys
# the one thing that made it beautiful; what comes back has the right notes in
# the wrong order. Played straight, the loop is better, and the operator's
# judgement on hearing both was blunt about it.
#
# So the loop plays, as it did. FLIP=1 for records where chopping is the point.
def flip_loop_entry(entry, cfg, pads, n_bars)
  return entry unless ENV["FLIP"] == "1"
  return entry if entry.nil? || !File.file?(entry[:path].to_s)

  tones = chord_pitch_classes(pads)
  return entry if tones.empty?

  dest = dilla_render_tmp("flip")
  records = flip_sources(entry, cfg)
  # Voices from whichever of those records had any. Three of the eight chops do;
  # the rest are instrumental passages, which is what the chop scorer was
  # looking for in the first place.
  voices = ENV["VOCAL_CHOPS"] == "0" ? [] : records.filter_map { |p| VocalChop.for_loop(p) }
  result = SampleFlip.build!(
    loop_path: records, vocal_path: voices, dest:, bpm: cfg[:bpm].to_f,
    bars: n_bars, chord_tones: tones,
    seed: stable_hash("flip:#{cfg[:track]}")
  )
  unless result
    dmesg("flip: #{File.basename(entry[:path])} yielded too few usable pieces — looping instead",
          unit: "harm0", parent: "dilla0")
    return entry
  end

  # Name the records, not "loop.wav" -- every chop is called loop.wav, so the old
  # line said the same thing for all eight tracks and said nothing about the
  # second record at all.
  crate = records.map { |p| File.basename(File.dirname(p)) }
  vocal_note = result[:vocal_events].to_i.positive? ? ", #{result[:vocal_events]} vocal" : ""
  dmesg("flip: #{result[:slices]} pieces off #{crate.join(' + ')}, " \
        "#{result[:events]} notes over #{tones.length} chords, " \
        "#{result[:reversed]} reversed#{vocal_note}",
        unit: "harm0", parent: "dilla0")
  entry.merge(path: result[:path], bpm: cfg[:bpm].to_f, flipped: true)
end

# Plays a chord on every built-in synth patch, one file each.
#
# The point is to be able to hear what the oscillators and the filter actually
# do, without a whole track around them. `PATCH=acid` for one; `HZ=` to move the
# chord.
def synth_audition!
  wanted = ENV["PATCH"].to_s.strip
  patches = wanted.empty? ? AnalogSynth::PATCHES.keys : [wanted.to_sym]
  root = (ENV["HZ"] || 130.81).to_f
  # A minor seventh, which shows a filter's character better than a single note:
  # four voices beating against each other is where detune becomes audible.
  chord = [1.0, 1.1892, 1.4983, 1.7818].map { |r| root * r }
  dir = File.join(ROOT, "scratch", "synth")

  patches.each do |patch|
    unless AnalogSynth::PATCHES.key?(patch)
      warn "no patch #{patch.inspect} — have: #{AnalogSynth::PATCHES.keys.join(', ')}"
      next
    end

    notes = chord.map { |hz| { hz:, at: 0.05, held: 1.8, gain: 0.7 } }
    out = AnalogSynth.render!(notes, dest: File.join(dir, "#{patch}.wav"), patch:,
                              duration: 3.4, seed: stable_hash(patch.to_s))
    puts out ? "  #{patch.to_s.ljust(14)} #{out.sub("#{ROOT}/", '')}" : "  #{patch}: produced silence"
  end
end

# The progression played on real oscillators.
#
# Every other pad in this engine is FluidSynth reading a soundfont: a recording
# of a sound somebody else made, which can be equalised afterwards and not much
# else. lib/analog_synth.rb is the other thing -- oscillators, a four-pole
# resonant ladder, and envelopes, which is what an analogue synthesiser is. It
# was built and measured and then left unwired, because connecting it as THE pad
# source means touching every patch table in the engine.
#
# This is the smaller version of that, and it is the version worth having: it
# renders the same chords as a SECOND pad, underneath the sampled one. Two
# instruments playing the same harmony is not a compromise, it is how a record
# gets depth -- the soundfont has the detail of a real instrument and this has
# the movement a recording cannot have, because its filter opens on every chord.
#
# warm_pad is the patch: two detuned saws and a square an octave down, filter
# opening over a second and a half, so the chord arrives rather than starts.
def analog_pad_file(pads, cfg, n_bars, beat_p)
  return nil if pads.nil? || pads.empty? || ENV["ANALOG_PAD"] == "0"

  bar = beat_p * 4.0
  chord_bars = [cfg[:chord_bars] || 2, 1].max
  # Held for its full length plus a little, so consecutive chords overlap the
  # way a hand does not lift between them.
  hold = (bar * chord_bars) * 1.04
  notes = []
  n_bars.times do |b|
    next unless (b % chord_bars).zero?

    chord = pads[(b / chord_bars) % pads.length]
    Array(chord[:hz]).each do |hz|
      next unless hz.to_f.positive?

      notes << { hz: hz.to_f, at: (b * bar).round(4), held: hold.round(4), gain: 0.55 }
    end
  end
  return nil if notes.empty?

  AnalogSynth.render!(notes, dest: dilla_render_tmp("analogpad"),
                      patch: ENV.fetch("ANALOG_PAD_PATCH", "warm_pad").to_sym,
                      duration: (n_bars * bar) + 2.0,
                      seed: stable_hash("analogpad:#{cfg[:track]}"))
end

# The records this flip may cut from: its own, plus one other.
#
# A track built from a single record can only say one thing. The second is
# chosen by the track name rather than at random, so a given track always digs
# in the same crate -- and it is deliberately NOT the neighbouring chop, which
# would come from the same few minutes of the same broadcast and sound like more
# of the first record rather than like a second one.
#
# The arranging step does not care which record a piece came from. It asks only
# what pitch the piece is, so pieces from two records sort themselves into one
# line: a horn from one answers a piano from the other because they are a third
# apart, not because anyone planned it.
def flip_sources(entry, cfg)
  return [entry[:path]] if ENV["FLIP_RECORDS"].to_s == "1"

  others = chopped_bed_paths.reject { |p| p == entry[:path] }
  return [entry[:path]] if others.empty?

  [entry[:path], others[stable_hash("crate:#{cfg[:track]}") % others.length]]
end

def chopped_bed_paths
  @chopped_bed_paths ||= Dir[File.join(ROOT, "samples", "chopped", "*", "loop.wav")].sort
end

# The progression as bare note-classes -- C is 0, C sharp is 1, and so on.
#
# The flip does not need to know a chord's name, its voicing, or which octave
# it sits in. It needs to know which notes are in it, so it can pick a piece of
# record whose pitch is one of them.
def chord_pitch_classes(pads)
  return [] if pads.nil? || pads.empty?

  pads.filter_map do |chord|
    classes = Array(chord[:hz]).filter_map { |hz| hz.to_f.positive? ? hz_to_pitch_class(hz) : nil }.uniq
    classes.empty? ? nil : classes
  end
end

def sidechain_filter_chain(cfg, drum_label: "[drums]")
  return wonky_sidechain_filters(drum_label:) unless cfg[:style_family] == :dilla

  if ENV.fetch("SIDECHAIN_STYLE", "dilla").to_s == "wonky"
    wonky_sidechain_filters(drum_label:)
  else
    dilla_sidechain_filters(drum_label:)
  end
end

DILLA_ROLE_VELOCITY_BASE = {
  kick_anchor: 0.56, kick_sync: 0.44, snare_back: 0.66, snare_off: 0.48,
  ghost: 0.30, hat_down: 0.50, hat_up: 0.40, open: 0.32, clap: 0.42
}.freeze

def dilla_role_velocity(role, bar, step, sec_gain: 1.0, backbeat: false)
  base = case role
         when :kick_anchor then DILLA_ROLE_VELOCITY_BASE[:kick_anchor]
         when :kick_sync then DILLA_ROLE_VELOCITY_BASE[:kick_sync]
         when :snare then backbeat ? DILLA_ROLE_VELOCITY_BASE[:snare_back] : DILLA_ROLE_VELOCITY_BASE[:snare_off]
         when :ghost then DILLA_ROLE_VELOCITY_BASE[:ghost]
         when :hat_down then DILLA_ROLE_VELOCITY_BASE[:hat_down]
         when :hat_up then DILLA_ROLE_VELOCITY_BASE[:hat_up]
         when :open then DILLA_ROLE_VELOCITY_BASE[:open]
         when :clap then DILLA_ROLE_VELOCITY_BASE[:clap]
         else 0.4
         end
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    perf = @composition_session.performer_profile
    if role == :ghost
      nudge = (ENV["GHOST_BOOST_NUDGE"] || "0").to_f
      base *= (perf[:ghost_boost] + nudge).clamp(0.75, 1.65)
    end
  end
  # Ghost notes were narrower than every other role (0.06 vs 0.08) --
  # backwards from real finger-drumming, where ghost hits are the LEAST
  # consistent dynamically (near-inaudible to clearly-present within the
  # same phrase), not the most locked-in.
  spread = role == :ghost ? 0.22 : 0.08
  vel = dilla_velocity(base, bar, step, spread:) * sec_gain
  # Wonky primary: kick-forward; snares/hats sit under kick (tops were piercing).
  if wonky_primary_drums?
    mul = case role
          when :kick_anchor, :kick_sync then 1.4
          when :snare, :clap then 1.05
          when :hat_down, :hat_up, :open then 0.88
          when :rim, :ghost then 0.75
          else 1.0
          end
    vel = (vel * mul).clamp(0.05, 0.95)
  end
  vel
end

def spectral_arp_chop_bar?(bar, chord_bars, drums_only, section)
  ENV["SPECTRAL_ARP"] == "1" && !drums_only && (bar % [chord_bars, 4].max).zero? &&
    !%i[breakdown intro].include?(section)
end

# --------------------------------------------------------------------------
# engine part: drum_bus_filter
# --------------------------------------------------------------------------
#
# The drum bus filter: smooth vs hard kits, width, build-ups.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def build_drum_bus_filter(cfg, sonic, duration: nil)
  crush_mix = sonic&.dig("synth", "crush_mix")&.to_f
  # DRUM_CRUSH_MIX overrides the sonic profile's grit.
  #
  # crush_mix was reachable only by editing a sonic profile, so the amount of
  # sampler grit on the kit could not be tried against a render -- and grit is
  # most of what separates a kit that sounds sampled from one that sounds
  # synthesised. A hit that has been through a 12-bit sampler carries
  # quantisation noise riding its own envelope, which is a texture no EQ
  # produces. The dilla family default of 0.22 is a light dusting; a kit meant
  # to sound lifted off a record wants considerably more.
  env_mix = ENV["DRUM_CRUSH_MIX"].to_s.strip
  crush_mix = env_mix.to_f if env_mix =~ /\A[\d.]+\z/
  base = if crush_mix&.positive?
           { bits: (ENV["DRUM_CRUSH_BITS"] || 12).to_i.clamp(4, 16),
             samples: 1.69, mix: crush_mix.clamp(0.08, 0.85) }
         elsif cfg[:style_family] == :dilla
           { bits: 11, samples: 1.5, mix: 0.22 }
         else
           { bits: 8, samples: 1.2, mix: 0.12 }
         end
  haas = cfg[:style_family] == :wonky ? ",adelay=0|12" : ""
  # Grit as a per-track compositional choice, not a fixed mix-bus setting
  # — cleaner through the exposition, dirtiest through the development
  # section, pulled back as the build lands. A producer varying the dirt
  # on purpose, not one static crush knob for the whole record.
  crush =
    if duration && duration > 20
      third = (duration / 3.0).round(2)
      [
        "acrusher=bits=#{base[:bits] + 2}:samples=#{base[:samples]}:mix=#{(base[:mix] * 0.5).round(2)}:enable='lt(t,#{third})'",
        "acrusher=bits=#{base[:bits]}:samples=#{base[:samples]}:mix=#{(base[:mix] * 1.4).clamp(0.0, 0.6).round(2)}:enable='between(t,#{third},#{(third * 2).round(2)})'",
        "acrusher=bits=#{base[:bits] + 1}:samples=#{base[:samples]}:mix=#{base[:mix]}:enable='gte(t,#{(third * 2).round(2)})'",
      ].join(",") + ","
    else
      "acrusher=bits=#{base[:bits]}:samples=#{base[:samples]}:mix=#{base[:mix]},"
    end
  kick_boost = if wonky_primary_drums?
                 6.5
               elsif cfg[:style_family] == :dilla
                 3.5
               else
                 0.58
               end
  # Bus fader. Comfort / explicit DRUM_BUS_VOL wins over the old hot Wonky path.
  base_vol = if ENV["DRUM_BUS_VOL"] && !ENV["DRUM_BUS_VOL"].empty?
               ENV["DRUM_BUS_VOL"].to_f.round(3)
             elsif wonky_primary_drums?
               1.35
             else
               (0.24 * kick_velocity_scale + 0.1).round(2)
             end
  # 1.26 is +2 dB on the whole drum bus, raised from 1.0 on operator instruction
  # 2026-08-10 ("make drums louder"). One multiplier, so it lifts kit and
  # sample-kick together and does not re-balance anything inside the bus.
  #
  # The Wonky path keeps 1.4: it is already the hot branch and stacking a raise
  # on top of it is how the drums got called "too hard" before.
  #
  # Tune with DRUM_BUS_GAIN rather than editing this — the env var wins, and
  # every preset hash below carries its own value that this does not touch.
  bus_gain = ENV.fetch("DRUM_BUS_GAIN", wonky_primary_drums? ? "1.4" : "1.26").to_f
  drum_vol = (ENV["DEBUG_DRUM_WEIGHT"] || (base_vol * bus_gain).round(3)).to_s
  drum_air = ENV.fetch("DRUM_AIR_DB", "2.5").to_f
  drum_pres = ENV.fetch("DRUM_PRESENCE_DB", "2.5").to_f
  kick_boost = comfort_mode? ? [kick_boost, 1.2].min : kick_boost
  wonky_eq = if wonky_drum_overlay_enabled? && !comfort_mode?
               # Was stacking +5/+2.5/+4.9/+3.5dB across bass, low-mid, presence,
               # and air all at once -- direct feedback that the drums sound
               # "too hard" pointed at this chain. Presence/air were the biggest
               # offenders (harsh hat/snare crack); eased all four back.
               "equalizer=f=70:t=o:w=0.9:g=3.2,equalizer=f=200:t=o:w=1:g=1.6," \
                 "equalizer=f=4200:t=o:w=1.2:g=#{(2.2 + drum_pres * 0.25).round(1)}," \
                 "equalizer=f=6500:t=o:w=1.5:g=#{(1.3 + drum_air * 0.25).round(1)},"
             elsif drum_air.positive? || drum_pres.positive?
               "equalizer=f=3500:t=h:w=1600:g=#{drum_pres.round(1)}," \
                 "equalizer=f=7000:t=h:w=2200:g=#{drum_air.round(1)},"
             else
               ""
             end
  # The drum bus had no fade of any kind, so every render opened on a full-level
  # kit at t=0 while the harm bus waited until bar 2 to fade in
  # (harm_fade_start in the mix assembly). Direct feedback that "the beginning
  # is abrupt" points here: the first thing you hear is a cold hit at full
  # gain, with nothing under it. One bar of qsin is enough to read as a
  # downbeat arriving rather than a tape splice, and it stays out of the way of
  # the harm fade that follows it.
  #
  # Skipped on short renders (the 8-bar probe/preview path) where a whole bar of
  # fade would be an eighth of the render. DRUM_FADE_IN=0 disables it.
  bar_sec = 4.0 * 60.0 / (cfg[:bpm] || DEFAULT_BPM).to_f
  drum_fade = if ENV["DRUM_FADE_IN"] == "0" || duration.to_f <= 20
                ""
              else
                "afade=t=in:st=0:d=#{bar_sec.round(2)}:curve=qsin,"
              end
  head = "[0:a]aformat=channel_layouts=stereo,#{bus_analog_filter(:drums)}volume=#{drum_vol}," \
         "#{drum_fade}equalizer=f=480:t=h:w=420:g=-1.5,#{wonky_eq}"
  # chomp the comma first: head ends comma-terminated so the next filter can be
  # appended, and pinning a label straight onto it yields ",[d_pre]" -- which
  # ffmpeg parses as an empty filter name and rejects the whole graph.
  head = "#{head.chomp(',')}[d_pre];#{drum_width_stage('d_pre', 'd_wide')}[d_wide]" if drum_width.positive?
  tail = "equalizer=f=55:t=o:w=0.7:g=#{kick_boost},highpass=f=25#{haas}"
  return smooth_drum_bus_filter(head, tail) if smooth_drums?

  # Tube: even harmonics, which the drum bus had none of.
  #
  # The crusher above adds quantisation noise and the compressor adds level, but
  # neither adds harmonics, and a kit that has been through a preamp has them.
  # A symmetric clipper would add ODD harmonics and read as distortion; the DC
  # offset here makes the transfer curve asymmetric, which produces EVEN
  # harmonics -- second and fourth -- and those read as weight and warmth on a
  # drum rather than as damage. The offset is removed immediately after, and the
  # oversampling keeps the harmonics it generates from folding back as aliases.
  #
  # DRUM_TUBE_DB is off by default, so a render that does not ask for it is
  # unchanged.
  tube_db = ENV.fetch("DRUM_TUBE_DB", "0").to_f.clamp(0.0, 12.0)
  tube = if tube_db.positive?
           off = (0.02 + 0.006 * tube_db).round(4)
           "dcshift=#{off},asoftclip=type=tanh:oversample=4,dcshift=-#{off}," \
             "highpass=f=22,volume=#{(tube_db * 0.5).round(2)}dB,"
         else
           ""
         end
  "#{head}#{crush}#{tube}" \
    "acompressor=threshold=-14dB:ratio=2.2:attack=3:release=60" \
    "#{hard_drums? ? "[d_soft];#{hard_drum_stage('d_soft', 'd_hard')}[d_hard]" : ','}" \
    "#{tail}[drums]"
end

def smooth_drums?
  ENV.fetch("SMOOTH_DRUMS", "0") != "0"
end

def hard_drums?
  ENV.fetch("HARD_DRUMS", "0") != "0"
end

# Harder is not the opposite of smoother, and this composes with SMOOTH_DRUMS
# rather than fighting it.
#
# Smooth meant no grit: the bit-crusher gone, its harmonic density replaced by
# parallel compression. Hard means more impact, which is a transient question,
# not a distortion one. The two ask for different things and both can hold --
# what you cannot have is grit and impact at once, because quantisation noise
# sits on top of the attack and masks it.
#
# The click band is high-passed before it is compressed, so the fast attack
# works on stick and beater noise instead of being triggered by kick
# fundamental -- a full-band fast compressor ducks the whole kit every time the
# kick lands, which reads as pumping rather than punch. Blended under, so the
# body of the hit is untouched.
#
# 55 Hz is weight and 3.2 kHz is where a snare reads as crack. Both narrow, so
# they add impact at the two frequencies that carry it rather than making the
# whole kit louder, which the master stage would only take back out.
HARD_DRUM_CLICK_HP = 1800

# Measured on a finished take: the drum bus is 36 dB down side-to-mid, which is
# nearly a point source, and it is 9.5 dB louder than the harmonic bus.
# So the loudest thing in the mix is mono, and the stereo thing is underneath
# it -- which is why the finished master reads as mono (-46 to -65 dB side/mid)
# while the harmonic stem on its own is a healthy -7, and real records sit at
# -3 to -6.
#
# Widening above 250 Hz only. The kick and the low body stay where they are,
# because low-frequency stereo is what mono_bass exists to undo and moving it
# would fight the last stage of every rack.
DRUM_WIDTH_HZ = 250

# On by default now, at a third of the available range.
#
# The stage below is careful, measured work -- haas rather than stereowiden
# because every sample in the kit is mono, above 250 Hz only so the kick keeps
# its attack -- and it defaulted to 0, which made all of it an anull. The kit
# rendered dead centre and the operator heard exactly that: a mix that wants
# each sound brought out into a field instead of stacked on one point.
#
# 0.35 rather than more: at that setting the haas delay is 4.1 ms left against
# 1.1 ms right, well inside the ~30 ms fusion limit where the ear reads
# direction rather than echo, and the side gain lifts 1.21x. Wider starts to
# hollow the centre, and mono_bass folds the low end back at the end of the
# rack anyway, so the width that survives is all in the kit's top half.
def drum_width
  ENV.fetch("DRUM_WIDTH", "0.35").to_f.clamp(0.0, 1.0)
end

def drum_width_stage(input, output)
  amt = drum_width
  return "[#{input}]anull[#{output}];" if amt <= 0.0

  # haas, not stereowiden. Every sample in the kit is a mono file -- measured,
  # all of kick/snare/hat/clap/ghost are single-channel -- so the drum bus has
  # no left-right difference at all and stereowiden has nothing to widen. It
  # moved the bus 0.4 dB and I mistook that for a tuning problem.
  #
  # haas synthesises an image instead of enlarging one: a few milliseconds of
  # delay on one channel, which the ear reads as direction rather than as echo
  # below the ~30 ms fusion limit. That is the only thing that makes a stereo
  # field out of a mono source.
  #
  # Still above 250 Hz only. A Haas delay on the kick would smear its attack and
  # then be folded back by mono_bass at the end of every rack anyway.
  "[#{input}]asplit=2[dw_lo][dw_hi];" \
  "[dw_lo]lowpass=f=#{DRUM_WIDTH_HZ}[dw_low];" \
  "[dw_hi]highpass=f=#{DRUM_WIDTH_HZ}," \
  "haas=left_delay=#{(2.0 + 6.0 * amt).round(2)}:right_delay=#{(0.6 + 1.4 * amt).round(2)}:" \
  "left_balance=-#{(0.3 * amt).round(2)}:right_balance=#{(0.3 * amt).round(2)}:" \
  "side_gain=#{(1.0 + 0.6 * amt).round(2)}[dw_wide];" \
  "[dw_low][dw_wide]amix=inputs=2:weights=1 1:duration=first:normalize=0[#{output}];"
end

def hard_drum_stage(input, output)
  "[#{input}]asplit=2[hd_body][hd_click];" \
  "[hd_click]highpass=f=#{HARD_DRUM_CLICK_HP},acompressor=threshold=-34dB:ratio=6:attack=0.3:release=45," \
  "volume=2.5dB[hd_tick];" \
  "[hd_body][hd_tick]amix=inputs=2:weights=1 0.5:duration=first:normalize=0," \
  "equalizer=f=55:t=o:w=0.8:g=2.2," \
  "equalizer=f=3200:t=o:w=1.6:g=2.0[#{output}];"
end

# Weight without grit.
#
# The crusher above is doing two jobs at once: it adds harmonic density, which
# is what makes the kit feel dense and present, and it adds quantisation noise,
# which is the audible grit. Asking for EQ'd drums with no crushing means
# keeping the first job and dropping the second, so removing the crusher alone
# would leave the kit thinner than before rather than smoother.
#
# Parallel compression is the documented way to get the density back: a hard-
# compressed copy blended under the untouched one raises the body and the tail
# while the dry path keeps its transients. Standard practice on this genre's
# drum bus, and it is why the split exists here rather than a single heavier
# compressor, which would flatten the attack the crusher was never touching.
#
# The tonal moves are the "EQ'd" half: 300 clears the boxiness the crusher used
# to mask, 3k is held down because parallel compression pushes presence forward,
# and the shelf above 9k opens the top the removed bit-reduction was dulling.
def smooth_drum_bus_filter(head, tail)
  "#{head}asplit=2[d_dry][d_par];" \
  "[d_par]acompressor=threshold=-30dB:ratio=8:attack=1:release=120," \
  "equalizer=f=180:t=o:w=1.1:g=2.0,lowpass=f=7000[d_pc];" \
  "[d_dry][d_pc]amix=inputs=2:weights=1 0.42:duration=first:normalize=0," \
  "equalizer=f=300:t=o:w=1.2:g=-2.2," \
  "equalizer=f=3000:t=o:w=1.4:g=-1.6," \
  "equalizer=f=9000:t=h:w=6000:g=1.4," \
  "acompressor=threshold=-14dB:ratio=2.2:attack=6:release=90" \
  "#{hard_drums? ? "[d_soft];#{hard_drum_stage('d_soft', 'd_hard')}[d_hard]" : ','}" \
  "#{tail}[drums]"
end

def build_up_filter_enhanced(input_tag, duration, out_tag: "built")
  start_t = (duration * 0.82).round(2)
  "[#{input_tag}]" \
    "equalizer=f=4500:t=h:w=5000:g=3.5:enable='gte(t,#{start_t})'," \
    "equalizer=f=220:t=o:w=1.8:g=2.5:enable='gte(t,#{start_t})'[#{out_tag}]"
end

# --------------------------------------------------------------------------
# engine part: master_chain
# --------------------------------------------------------------------------
#
# The master bus: console emulation, width, true-peak guard, loudness.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# The console and the mastering desk, in that order, before the loudness stage.
#
# The master bus ran loudnorm into a limiter and nothing else: correct levels,
# no character. Everything below is copied from documented practice rather than
# invented, and each stage names its source.
#
# 1. TRANSFORMER BUMP. Seventies Neve desks mixed at roughly microphone level
#    and brought the signal back up through output transformers. Transformers
#    are not flat: the core adds a small lift in the low bass and rolls away the
#    top. Both are reproduced here, gently, because the effect on a real
#    desk is small and the temptation to overdo it is what makes emulations
#    sound like emulations.
#
# 2. VOLTAGE-MIXING NONLINEARITY. The "harmonic magic" of the 80-series is
#    discrete class-A stages departing slightly from linear as they are pushed.
#    A soft clipper at low drive is the honest version. Oversampled four times,
#    or the harmonics it creates fold back down the spectrum as aliasing, which
#    is the one artefact analog cannot produce.
#
# 3. TRIODE HARMONICS. Crane Song's HEDD offers triode, pentode and tape.
#    Triode adds the even-order harmonics of a single-ended tube stage -- the
#    octave, which the ear hears as warmth rather than distortion. aexciter's
#    blend control sets the balance between second and third harmonic, so a
#    negative blend is the triode setting and a positive one the pentode.
#
# 4. THE STC-8, TEMPO-LOCKED. This is the specific thing Dave Cooley did to
#    Donuts: he timed the compressor's release to each track's tempo, to keep
#    the pump disorienting instead of smoothing it out. Release here is an
#    eighth note at the track's own BPM, so the bus recovers exactly as the next
#    off-beat lands and the pump becomes part of the rhythm.
#
# 5. MATTE TOP. Cooley used a GML equalizer for top end and said he was not
#    after a slick top at the time -- a "matte" finish. A matte top is a WIDE,
#    low shelf placed high, which lifts air without putting an edge on any one
#    band. A narrow boost is the slick sound he was avoiding.
#
# All five are built in outboard.rb and reached through Outboard.chain below.
# Two constants naming the transformer's corner frequencies lived here until
# 2026-08-12, left behind when the stage moved into the rack; the rack carries
# its own, so these described the sound rather than setting it.

def console_master_chain(cfg)
  return nil if ENV["CONSOLE"] == "0"

  rack = ENV.fetch("RACK", Outboard::DEFAULT_RACK).to_sym
  unless Outboard::RACKS.key?(rack)
    warn "rack: no such rack #{rack.inspect} — using #{Outboard::DEFAULT_RACK}. " \
         "Choices: #{Outboard::RACKS.keys.join(', ')}"
    rack = Outboard::DEFAULT_RACK
  end
  # A unit named in a rack but not built would vanish silently and the rack
  # would quietly become a shorter rack. Say so instead.
  Outboard.chain(rack, bpm: cfg[:bpm].to_f,
                       missing: ->(unit) { warn "rack #{rack}: no unit named #{unit.inspect} — skipped" })
end

# No loudnorm in the graph. This is the fix for a track whose level wanders.
#
# ffmpeg's loudnorm has two modes and picks between them silently. Given
# measured values from a first pass it applies ONE static gain -- transparent,
# which is what mastering means. Given none, as here, it falls back to DYNAMIC
# normalisation: it rides the gain continuously through the track, pushing quiet
# passages up and pulling loud ones down, second by second. It hits the target
# LUFS beautifully and it destroys the arrangement, because every decision about
# what should be loud gets overruled by a meter.
#
# That is what "the overall volume changes all the time" was. Every loudnorm in
# this engine was the single-pass kind.
#
# So the graph now ends at the limiter, and the levelling happens afterwards in
# normalise_master!, which measures the finished file and applies one number.
def true_peak_guard_for_style(input_tag, cfg, out_tag: "out")
  # Console before the limiter. Saturation changes both peak and loudness, so
  # colouring after measuring would hand back a track that no longer hits the
  # target it was measured against.
  console = console_master_chain(cfg)
  head = "[#{input_tag}]#{console ? "#{console}," : ''}"
  "#{head}aresample=#{SAMPLE_RATE}," \
    "alimiter=limit=#{TRUE_PEAK_CEILING_LINEAR}:attack=1:release=40:level=disabled[#{out_tag}]"
end

# Measures the finished track and applies a single gain to it.
#
# This is the second pass that loudnorm needed and never got. Nothing here moves
# during the track: one measurement, one number, one limiter to catch whatever
# the gain pushes over the ceiling. A section that was written quiet stays quiet
# relative to the rest, which is the whole point of writing it quiet.
# Width at the master, because that is the only place it can be verified.
#
# Measured: finished tracks sit at -45 to -65 dB side-to-mid where real records
# are -3 to -6. The harmonic bus is not the cause -- it measures -6.8 on its own,
# with or without a stereo sample bed under it. The drum bus is mono because
# every one-shot in the kit is a single-channel file, and it is 27 dB louder
# than the harmonic bus, so it dominates the sum.
#
# Two fixes were tried at the source and neither survived into a render. Widening
# the drum bus moved the finished file 0.3 dB (-48.3 to -48.6 with the switch on
# and off, which is nothing). Lifting the harmonic bus 20.6 dB moved it 2.2 dB.
# Both worked in isolation and neither worked in place, which means the loss is
# somewhere in the summing I have not found.
#
# So this runs last, on the file itself, where the number can be checked against
# the file that ships rather than against a stage in the middle. Above 300 Hz
# only, so the kick and bass stay centred and mono_bass has nothing to undo.
MASTER_WIDTH_HZ = 300

def master_width
  ENV.fetch("MASTER_WIDTH", "0").to_f.clamp(0.0, 1.0)
end

def widen_master!(path)
  amt = master_width
  return path unless amt.positive? && File.file?(path)

  # Phase-coherent widening, not Haas. Measured 2026-08-13.
  #
  # This used haas=left_delay=(2.0+5.0*amt):right_delay=(0.5+1.2*amt). At the
  # MASTER_WIDTH=0.5 these renders were made with, that is 4.5 ms against 1.1 ms
  # — a 3.4 ms inter-channel delay, which is a comb filter with nulls at roughly
  # 147, 441 and 735 Hz. The finished tracks measured a SIDE channel LOUDER than
  # their MID (dilla_semua_96 at +1.7 dB) and lost 7.5 dB summing to mono, with
  # the loss concentrated in 150-800 Hz. Predicted nulls and measured band agree.
  #
  # Source material is not the cause: samples/semua_untuk_mu/loop.wav measures a
  # healthy -6.2 dB side/mid, and the render turned that into +1.7.
  #
  # stereotools slev scales the side channel without delaying either one. It
  # widens; it cannot comb. The cost is honest and small: a mono fold loses the
  # boosted side rather than combing the mids, which is the trade every mastering
  # widener makes.
  #
  # SIDE_CEILING keeps the result under unity — a master bus that can put more
  # energy in the difference signal than the sum is not wide, it is broken.
  slev = [1.0 + 0.5 * amt, 1.45].min.round(2)
  out = "#{path}.wide#{File.extname(path)}"
  chain = "[0:a]asplit=2[mw_lo][mw_hi];" \
          "[mw_lo]lowpass=f=#{MASTER_WIDTH_HZ}[mw_low];" \
          "[mw_hi]highpass=f=#{MASTER_WIDTH_HZ}," \
          "stereotools=mlev=1:slev=#{slev}[mw_wide];" \
          "[mw_low][mw_wide]amix=inputs=2:weights=1 1:duration=first:normalize=0," \
          "alimiter=limit=0.97[mwout]"
  begin
    sh! "ffmpeg", "-y", "-v", "error", "-i", path, "-filter_complex", chain,
        "-map", "[mwout]", "-ar", SAMPLE_RATE.to_s, *codec_for(out), out
    FileUtils.mv(out, path)
    dmesg("master width: #{amt} above #{MASTER_WIDTH_HZ} Hz", unit: "mix0", parent: "dilla0")
  rescue StandardError => e
    warn "master width skipped: #{e.message}"
    FileUtils.rm_f(out)
  end
  path
end

# Wet-dominant parallel layering of the finished track against itself.
#
# Summing a processed copy with an unprocessed one is comb filtering, and how
# audible that is depends entirely on the level difference -- which is why the
# wet-strong/dry-weak direction is the safe one and a 50/50 blend is not. A dry
# layer 14 dB down puts comb notches at +-1.6 dB, below the point where it reads
# as filtering, while still returning the original attack transient underneath a
# wet path that has smeared it. At 0 dB the same sum notches +-6 dB and hollows
# out the midrange.
#
# MASTER_LAYER is the wet/dry balance, 0 (off, and the default) to 1.
# MASTER_LAYER_DRY_DB moves the dry layer; the default is the -14 dB above.
MASTER_LAYER_DRY_DB = -14.0

def master_layer_amount = ENV.fetch("MASTER_LAYER", "0").to_f.clamp(0.0, 1.0)

# A fraction of a Hz of frequency shift on the wet layer only.
#
# Frequency shifting is not pitch shifting: afreqshift displaces every partial
# by a constant number of Hz, so harmonic ratios do not survive it. That is
# ruinous at musical depths and is exactly why the value here is tiny. At 0.1 Hz
# no partial moves audibly, but the wet layer's phase rotates continuously
# against the dry with a 1/shift second beat period -- 10 seconds at the default
# -- so the two layers drift in and out of alignment forever without repeating
# and without an LFO. Above ~2 Hz it stops being drift and becomes ring
# modulation, which is where the clamp is.
def master_drift_hz = ENV.fetch("MASTER_DRIFT_HZ", "0").to_f.clamp(0.0, 2.0)

def layer_master!(path)
  amt = master_layer_amount
  return path unless amt.positive? && File.file?(path)

  dry_db = ENV.fetch("MASTER_LAYER_DRY_DB", MASTER_LAYER_DRY_DB.to_s).to_f.clamp(-40.0, 0.0)
  drift = master_drift_hz
  # asoftclip is not gain-compensated -- oversample=4 measures 4.2 dB down on
  # this bus -- so the wet path would arrive quieter than the balance asks for
  # and the dry would dominate a mix that is meant to be wet-led.
  wet = +""
  wet << "afreqshift=shift=#{drift}:level=1," if drift.positive?
  wet << "aecho=0.9:0.75:37|53|71:0.28|0.20|0.14," \
         "asoftclip=type=tanh:oversample=4,volume=4.2dB,treble=g=1.2:f=5500"
  out = "#{path}.layer#{File.extname(path)}"
  chain = "[0:a]asplit=2[ml_dry][ml_wet];" \
          "[ml_wet]#{wet}[ml_w];" \
          "[ml_dry]volume=#{(dry_db + (1.0 - amt) * -dry_db).round(2)}dB[ml_d];" \
          "[ml_w][ml_d]amix=inputs=2:weights=#{amt.round(3)} 1:duration=first:normalize=0," \
          "alimiter=limit=0.97[mlout]"
  begin
    sh! "ffmpeg", "-y", "-v", "error", "-i", path, "-filter_complex", chain,
        "-map", "[mlout]", "-ar", SAMPLE_RATE.to_s, *codec_for(out), out
    FileUtils.mv(out, path)
    dmesg("master layer: wet #{amt}, dry #{dry_db} dB#{drift.positive? ? ", drift #{drift} Hz" : ''}",
          unit: "mix0", parent: "dilla0")
  rescue StandardError => e
    warn "master layer skipped: #{e.message}"
    FileUtils.rm_f(out)
  end
  path
end

# Tape varispeed on the finished master: pitch and tempo together, by resampling.
#
# This is deliberately not a pitch shifter. Holding tempo while moving pitch
# needs a phase vocoder, which smears exactly the transients a drum record is
# made of. Resampling has no artefact to trade away at all -- it is the file
# read at a different rate, which is what a tape machine running slow does, and
# the high end comes down with everything else. That descending top end is most
# of what the effect actually sounds like.
#
# MASTER_VARISPEED is in semitones, negative for slower and lower. -1 is a 5.6%
# move and lands 92 BPM at 86.8; a lot of records that read as subtly slow are
# nearer 1-3%, so -0.2 to -0.5 is the subtle end of this knob.
#
# It runs after normalise_master!, so the loudness target is measured on the
# unshifted file. Resampling does not change level, but it does change duration:
# a track slowed a semitone is 5.9% longer than the bar count implies.
def master_varispeed_semitones = ENV.fetch("MASTER_VARISPEED", "0").to_f.clamp(-4.0, 4.0)

def varispeed_master!(path)
  semis = master_varispeed_semitones
  return path if semis.zero? || !File.file?(path)

  ratio = 2.0**(semis / 12.0)
  out = "#{path}.vari#{File.extname(path)}"
  begin
    sh! "ffmpeg", "-y", "-v", "error", "-i", path,
        "-af", "asetrate=#{(SAMPLE_RATE * ratio).round},aresample=#{SAMPLE_RATE}",
        "-ar", SAMPLE_RATE.to_s, *codec_for(out), out
    FileUtils.mv(out, path)
    dmesg("master varispeed: #{semis} st (x#{ratio.round(5)})", unit: "mix0", parent: "dilla0")
  rescue StandardError => e
    warn "master varispeed skipped: #{e.message}"
    FileUtils.rm_f(out)
  end
  path
end

# The album's sonic signature: one treatment every beat carries.
#
# A record is recognisable as a record because its tracks were finished the same
# way. Everything upstream of here varies on purpose -- progression, kit, patch,
# tape preset -- so this is the one stage that must not, and it is deliberately
# a single named identity rather than a knob per render.
#
# Four stages, each aimed at a different cause of "harsh", because they are
# different problems and one filter cannot fix them all:
#
#   DE-HARSH. Resonances between 1.8 and 5.2 kHz are what the ear calls harsh,
#   and they are intermittent -- a static EQ cut there dulls the whole track to
#   fix moments. So the band is split out and compressed on its own, hard and
#   fast, and left alone when it is not ringing. Everything outside the band is
#   untouched and re-summed.
#
#   EVEN HARMONICS. Symmetric clipping -- which every tanh stage in this engine
#   is, and there are fifty of them -- generates ODD harmonics, and odd harmonics
#   are what "overdrive" sounds like. A DC offset before the nonlinearity makes
#   it asymmetric, which generates EVEN harmonics instead: the same saturation
#   density read as warmth rather than distortion. The offset is removed after.
#
#   OVERSAMPLING. A nonlinearity at 44.1 kHz folds everything it generates above
#   Nyquist back down as inharmonic aliases, and inharmonic content is the most
#   fatiguing thing a mix can contain. asoftclip's own oversample does the whole
#   job here; it is the cheapest real win available and costs nothing but CPU.
#
#   GLUE. Slow attack, low ratio, wide knee. Not level control -- it lets
#   transients through untouched and only moves the sustain, which is what makes
#   separate parts read as one performance rather than a stack.
#
# asoftclip is not gain-compensated (4.2 dB down on this bus, measured), so the
# makeup below is a measured constant and not a guess.
MELT_MAKEUP_DB = 4.2

def melt_amount = ENV.fetch("MELT", "0").to_f.clamp(0.0, 1.0)

def melt_master!(path)
  amt = melt_amount
  return path unless amt.positive? && File.file?(path)

  drive = (0.03 + 0.05 * amt).round(4)          # DC offset -> asymmetry -> even harmonics
  ratio = (2.0 + 2.0 * amt).round(2)            # de-harsh band only
  thr = (-22.0 - 6.0 * amt).round(1)
  out = "#{path}.melt#{File.extname(path)}"
  chain = "[0:a]asplit=3[mlow][mmid][mhigh];" \
          "[mlow]lowpass=f=1800[ml];" \
          "[mmid]highpass=f=1800,lowpass=f=5200," \
          "acompressor=threshold=#{thr}dB:ratio=#{ratio}:attack=3:release=80:knee=6[mm];" \
          "[mhigh]highpass=f=5200[mh];" \
          "[ml][mm][mh]amix=inputs=3:duration=first:normalize=0," \
          "dcshift=#{drive},asoftclip=type=tanh:oversample=8,dcshift=-#{drive},highpass=f=20," \
          "volume=#{MELT_MAKEUP_DB}dB," \
          "acompressor=threshold=-20dB:ratio=1.5:attack=150:release=450:knee=8," \
          "equalizer=f=8000:t=h:w=4000:g=#{(-0.8 * amt).round(2)}," \
          "alimiter=limit=0.97[mout]"
  begin
    sh! "ffmpeg", "-y", "-v", "error", "-i", path, "-filter_complex", chain,
        "-map", "[mout]", "-ar", SAMPLE_RATE.to_s, *codec_for(out), out
    FileUtils.mv(out, path)
    dmesg("melt: de-harsh #{ratio}:1 @1.8-5.2k, even-harmonic drive #{drive}, 8x oversampled",
          unit: "mix0", parent: "dilla0")
  rescue StandardError => e
    warn "melt skipped: #{e.message}"
    FileUtils.rm_f(out)
  end
  path
end

def normalise_master!(path, cfg)
  return path if ENV["MASTER_NORMALISE"] == "0" || !File.file?(path)

  widen_master!(path)

  # MASTER_LUFS outranks the style table. The per-style targets are a texture
  # decision made by ear and stay that way, but they are set for the Dilla-
  # leaning material this engine started as -- techno rendered through a dilla
  # family lands near -19, which is roughly 5 dB under where the genre sits and
  # 9 under a club master. It does not sound thin, it sounds small next to
  # anything else, and there was no way to say so per render short of editing
  # the table and moving every other track with it.
  env_lufs = ENV["MASTER_LUFS"].to_s.strip
  target = if env_lufs.empty?
             (cfg[:master_lufs] || MASTER_TARGET_LUFS).to_f
           else
             env_lufs.to_f
           end
  out, err, status = capture("ffmpeg", "-nostdin", "-hide_banner", "-i", path,
                             "-af", "loudnorm=I=#{target}:TP=#{TRUE_PEAK_CEILING_DB}:print_format=json",
                             "-f", "null", "-")
  unless status.success?
    warn "master normalise: measurement failed, leaving level as rendered"
    return path
  end

  json = (out + err)[/\{\s*"input_i".*?\}/m]
  measured = json ? (JSON.parse(json)["input_i"].to_f rescue nil) : nil
  if measured.nil? || measured <= -70.0
    warn "master normalise: no usable reading#{measured ? " (#{measured} LUFS)" : ''} — leaving level as rendered"
    return path
  end

  # Bounded, so a mis-measurement cannot swing a track 30 dB. Anything needing
  # more than twelve is wrong somewhere earlier and should be found there.
  gain = (target - measured).clamp(-12.0, 12.0)
  tmp = "#{path}.norm#{File.extname(path)}"
  ok = system("ffmpeg", "-nostdin", "-y", "-v", "error", "-i", path,
              "-af", "volume=#{gain.round(2)}dB," \
                     "alimiter=limit=#{TRUE_PEAK_CEILING_LINEAR}:attack=1:release=40:level=disabled",
              # codec_for, not a hardcoded 192k. Every renderer writes mp3 at 320k
              # and this pass re-encoded the finished file at 192k on the way to
              # setting its level -- a silent quality drop on every mp3 render,
              # applied by the one stage whose job was supposed to be a gain.
              *codec_for(path),
              tmp, out: File::NULL, err: File::NULL)
  if ok && File.file?(tmp) && File.size(tmp).positive?
    FileUtils.mv(tmp, path)
    dmesg("master: #{measured.round(1)} LUFS -> #{target} (#{format('%+.1f', gain)} dB, one static gain)",
          unit: "mix0", parent: "dilla0")
  else
    FileUtils.rm_f(tmp)
    warn "master normalise: re-encode failed, leaving level as rendered"
  end
  path
end

# The genre renderers' way in to the master bus.
#
# render_dilla measures its finished file and applies one gain (normalise_master!
# at the tail of its finaliser, the only call site there has ever been).
# render_hate_techno, render_industrial and render_analog each hand-rolled a
# master -- a console chain and a limiter -- and then stopped. A limiter caps a
# peak; it does not set a loudness. So those three had no integrated-loudness
# target at all, and it showed the moment they shared a playlist with a Dilla
# render: measured across a 26-track demo, the 8 parts that hashed into a techno
# slot came out at -12.3 LUFS against -18.7 for the other 18. A 6.5 dB step
# between adjacent tracks, from a stage that was never wired rather than a level
# anyone chose.
#
# This is the same fork the harmony work closed one layer up. Giving those
# renderers the progression fixed what notes they played; it did not give them
# the master, because the master lives in a finaliser only render_dilla runs.
#
# Takes a family symbol rather than a cfg: the genre renderers do not build the
# render_config hash that carries :master_lufs, and inventing a partial one to
# satisfy this call would be a worse lie than looking the number up here.
def normalise_genre_master!(destination, family)
  target = MASTER_LUFS_BY_STYLE.fetch(family, MASTER_LUFS_BY_STYLE[:default])
  normalise_master!(destination, { master_lufs: target })
end

# The AKMD / Radio Bergen chain, reproduced stage for stage. It came from
# STUDIO/radio-bergen/akmd_mastering_chain.rb, which was a description of this
# chain and nothing else — no caller, no runtime role — so it went with the rest
# of that directory rather than being carried along as a duplicate of a comment. It is a broadcast chain: band-limited, forward in
# the low mids, soft-clipped rather than brick-walled. Offered as an alternative
# to master_bus_filters_enhanced because that one stacks parallel compression, a
# sub-150Hz sidechain duck keyed off the harm bus, per-bus RMS matching,
# convolution reverb and loudnorm -- the comment on the mix assembly already
# records that the elaborate chain, not the balance numbers, was what failed
# listening tests. Nine stages, no dynamics keyed off anything else.
# MASTER_CHAIN=akmd selects it.
# Saturation rather than overdrive. The stages are the same nine; what changed
# is how hard the clipper is driven and whether its harmonics alias.
#
# It used to run makeup=4 into a bare `asoftclip=type=tanh` and then volume=1.5
# on top — about +7.5 dB pushed into a clipper with threshold at its default of
# 1, so it only engaged at full scale and engaged hard. That is an overdrive
# pedal, not a mastering chain.
#
# oversample is the change that matters most. It defaults to 1, meaning none:
# clipping generates harmonics above Nyquist and, with nowhere to go, they fold
# back down as inharmonic aliasing. That folded content is what makes digital
# clipping sound fizzy and brittle where analog sounds warm — real saturation
# has no Nyquist to fold against, its harmonics extend and roll off. At
# 4x the harmonics are generated with headroom and filtered before decimation,
# so what survives is harmonically related to the signal.
#
# The rest is gain staging: less level into the clipper, threshold lowered so it
# engages gradually across the range instead of slamming at the ceiling, and the
# level made back up after the non-linearity rather than before it. atan over
# tanh for a wider knee — it compresses the approach to clipping over more of
# the range, which reads as compression rather than distortion.
AKMD_MASTER_FILTERS = [
  # Tape rolls off; it does not cut. A highpass at 60 was taking body out of the
  # low end that the head bump then tried to put back, so both moved: 30 Hz, and
  # the bump halved to 1.5 dB. The top is a shelf now rather than a brickwall —
  # a lowpass at 11.5k sounds like a filter, a shelf sounds like tape.
  "highpass=f=30",
  "equalizer=f=55:t=q:w=1.1:g=1.5",
  "equalizer=f=9000:t=h:w=5000:g=-2.5",
  "lowpass=f=13500",
  # Tape compression is slow and shallow. 3:1 at a 10 ms attack was catching
  # every transient and flattening the record; 1.8:1 at 30 ms with a soft knee
  # lets hits through and only leans on sustained level. Measured on a raw stem
  # this is what moves total harmonic distortion from 0.166% to 0.057%.
  "acompressor=threshold=-18dB:ratio=1.8:attack=30:release=320:makeup=1.5:knee=6",
  # A symmetric curve cannot produce even harmonics. tanh and atan are both
  # odd-symmetric — f(-x) = -f(x) — so only odd orders exist. Measured on a
  # 220 Hz sine: 2nd harmonic at -131 dB, which is the numerical noise floor,
  # against a 3rd at -81. Odd orders dominating by 51 dB is the transistor edge;
  # the tube warmth people reach for is the 2nd.
  #
  # Crane Song's HEDD exposes exactly this split as triode vs pentode. The route
  # to it is asymmetry — historically a DC bias into the non-linearity, so the
  # curve treats the two halves of the wave differently.
  #
  # Bias dropped from 0.15 to 0.06 and the clipper backed off with it. The point
  # of the asymmetry was never maximum even-order content, it was which orders
  # dominate — and 0.06 still puts even on top. Threshold 0.92 with unity output
  # means the stage only touches peaks instead of rounding the whole waveform,
  # which is what it was doing at 0.72 into 1.28.
  #
  # The highpass after is not optional: biasing leaves DC on the output and
  # asymmetric clipping leaves more. Measured offset after it is 0.000002.
  "dcshift=shift=0.06",
  "asoftclip=type=atan:threshold=0.92:output=1.0:oversample=4",
  "highpass=f=22",
  # This chain used to end with +6.4 dB into a limiter set 0.7 dB from full
  # scale, on top of 9 dB already staged ahead of it. That is what "overdrive"
  # was. The limiter is a safety net here, not a loudness tool: high ceiling,
  # slow release, and it should mostly not engage at all.
  "volume=1.5",
  "alimiter=limit=0.95:attack=8:release=220",
].freeze

def akmd_master_chain?
  ENV["MASTER_CHAIN"].to_s.downcase == "akmd"
end

def akmd_master_filters(input_tag, out_tag: "out")
  ["[#{input_tag}]#{AKMD_MASTER_FILTERS.join(',')},aresample=#{SAMPLE_RATE}[#{out_tag}]"]
end

def master_bus_filters_enhanced(input_tag, cfg:, duration: nil, ir_input_idx: nil)
  return akmd_master_filters(input_tag) if akmd_master_chain?

  unless sonitex_enabled?
    filt = ["[#{input_tag}]acompressor=threshold=-20dB:ratio=2:attack=25:release=120:makeup=1.5[premaster0]"]
    filt << mix_bass_chord_balance_filter("premaster0", out_tag: "premaster")
    filt << sub_bass_mono_filter("premaster", out_tag: "monobassed")
    filt << analog_drift_filter("monobassed", out_tag: "drifted")
    darken = cfg.fetch(:mood_darken_strength, 1.0)
    filt << mood_darken_filter("drifted", out_tag: "darkened", strength: darken)
    reverb_out = "darkened"
    if ir_input_idx
      filt << convolution_reverb_filter("darkened", ir_input_idx, mix: cfg[:style_family] == :wonky ? 0.22 : 0.16, out_tag: "reverbed")
      reverb_out = "reverbed"
    end
    if analog_smooth_enabled?
      filt << analog_smooth_filter(reverb_out, out_tag: "smoothed")
      reverb_out = "smoothed"
    end
  if duration && !(camel_mode? && ENV.fetch("CAMEL_NO_BREAK", "1") != "0")
    filt << break_filter(reverb_out, duration, out_tag: "broke")
    filt << build_up_filter_enhanced("broke", duration, out_tag: "built")
    filt << true_peak_guard_for_style("built", cfg)
  else
    filt << true_peak_guard_for_style(reverb_out, cfg)
  end
  return filt
  end
  s = sonitex_config(track: cfg[:track].to_s)
  variant = analog_resolve_variant(track: cfg[:track].to_s)
  filt = []
  filt.concat(sonitex_tape_filters(input_tag, out_tag: "snx_out"))
  filt.concat(analog_emulation_filters("snx_out", variant, out_tag: "ana_out"))
  filt << "[ana_out]alimiter=limit=#{s[:limit]}:level_out=#{s[:level_out]}[premaster0]"
  filt << mix_bass_chord_balance_filter("premaster0", out_tag: "premaster")
  filt << sub_bass_mono_filter("premaster", out_tag: "monobassed")
  # Camel: skip wow drift + heavy darken — they smear the kit and delete HF.
  if camel_mode? && ENV.fetch("CAMEL_CLEAN_MASTER", "1") != "0"
    reverb_out = "monobassed"
  else
    filt << analog_drift_filter("monobassed", out_tag: "drifted")
    darken = cfg.fetch(:mood_darken_strength, 1.0)
    filt << mood_darken_filter("drifted", out_tag: "darkened", strength: darken)
    reverb_out = "darkened"
  end
  if ir_input_idx && !(camel_mode? && ENV.fetch("CAMEL_NO_REVERB", "1") != "0")
    filt << convolution_reverb_filter(reverb_out, ir_input_idx, mix: 0.12, out_tag: "reverbed")
    reverb_out = "reverbed"
  end
  if analog_smooth_enabled?
    # After the tape and analog-emulation stages, not instead of them: those
    # colour the mix, this one takes the edges off whatever they produced.
    filt << analog_smooth_filter(reverb_out, out_tag: "smoothed")
    reverb_out = "smoothed"
  end
  # break_filter bitcrushes + silences mid-track — kills pads/leads. Off on Camel.
  if duration && !(camel_mode? && ENV.fetch("CAMEL_NO_BREAK", "1") != "0")
    filt << break_filter(reverb_out, duration, out_tag: "broke")
    filt << build_up_filter_enhanced("broke", duration, out_tag: "built")
    filt << true_peak_guard_for_style("built", cfg)
  else
    filt << true_peak_guard_for_style(reverb_out, cfg)
  end
  filt
end

# --------------------------------------------------------------------------
# engine part: form_map
# --------------------------------------------------------------------------
#
# Song form: section maps, motifs per chord.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def motif_from_chord(chord)
  return [0, 1, 2, 1] unless chord && chord[:hz]&.any?
  tones = chord[:hz].sort
  [0, 1, 2, tones.length > 3 ? 3 : 1]
end

def chord_symbol_key(chord)
  chord[:name].to_s.sub(/_pedal\z/, "").sub(/_t\d+\z/, "")
end

# Phrase-locked recall — same 4-note figure whenever the same chord symbol returns.
def chord_motif_for(chord)
  sym = chord_symbol_key(chord)
  @chord_motif_cache ||= {}
  return @chord_motif_cache[sym] if motif_recall_enabled? && @chord_motif_cache.key?(sym)
  motif = motif_from_chord(chord)
  @chord_motif_cache[sym] = motif if motif_recall_enabled?
  motif
end

def parse_section_map!(raw)
  raw.split(",").filter_map do |pair|
    name, len = pair.strip.split(":", 2)
    next unless name && len
    kind = SECTION_KIND_ALIASES.fetch(name.downcase, name.downcase.to_sym)
    [kind, len.to_i]
  end
end

def resolve_form_map
  return @resolve_form_map if defined?(@resolve_form_map) && @resolve_form_map
  if ENV["SECTION_MAP"] && !ENV["SECTION_MAP"].empty?
    @resolve_form_map = parse_section_map!(ENV["SECTION_MAP"])
  elsif ENV["FORM"] && !ENV["FORM"].empty?
    preset = FORM_PRESETS[ENV["FORM"].to_sym]
    @resolve_form_map = preset&.fetch(:map, nil)
  end
  @resolve_form_map
end

# FORM_FIT — stretch the form across the track instead of repeating it.
#
# A form is a CYCLE here: form_section_at takes `bar % cycle_len`, so a 32-bar
# map over a 128-bar render is four copies of itself -- four intros, four outros,
# an "intro" arriving at bars 32, 64 and 96. An intro that happens four times is
# not an intro, and a form that repeats is a loop of a form rather than the shape
# of a piece.
#
# That matters for what this engine is being asked to do. The records it is
# measured against have one or two section boundaries across four or five
# minutes -- a whole-song arc, each part happening once. dilla could not express
# that at any length: the only way to get a single pass was to hand-write a
# SECTION_MAP whose lengths happen to sum to the exact bar count, which is a
# different map for every render length.
#
# So: scale the map's proportions to the track. intro:4,main:8,build:8,turn:8,
# outro:4 over 128 bars becomes 16/32/32/32/16 rather than four passes of
# 4/8/8/8/4. The shape is the operator's; only its size follows the render.
#
# ON BY DEFAULT PAST 64 BARS. Below about two passes a repeated form reads as a
# repeated form, which is a legitimate thing to want on a beat. Past it, it stops
# being a form at all: nothing is unique and "intro" stops meaning anything a
# listener can hear. soul_32 and camel_32 are 32-bar maps, so 64 is exactly two
# passes -- the last length at which a repeat is still a structure rather than a
# loop of one.
#
# FORM_FIT=0 forces cycling at any length and FORM_FIT=1 forces fitting; only the
# unset case consults the bar count. A render that sets no FORM is untouched
# either way, because form_section_at is never reached without one -- so this
# changes nothing for the default render path and everything for a long one that
# asked for a shape.
FORM_FIT_DEFAULT_BARS = 64

def form_fit_enabled?(n_bars = nil)
  case ENV["FORM_FIT"]
  when "1" then true
  when "0" then false
  else n_bars.to_i > FORM_FIT_DEFAULT_BARS
  end
end

def form_section_at(bar, n_bars)
  map = resolve_form_map
  return unless map&.any?
  cycle_len = map.sum { |_, len| len }
  return if cycle_len <= 0

  if form_fit_enabled?(n_bars) && n_bars.to_i.positive?
    # Proportional, in bars, with the last section absorbing the rounding so the
    # map always covers the track exactly. Rounding each section independently
    # leaves a gap or an overlap at the end, and a bar belonging to no section
    # falls through to the legacy map -- which would put a stray `main` after the
    # outro and be hard to see.
    scaled = 0.0
    map.each_with_index do |(kind, len), i|
      return kind if i == map.length - 1

      scaled += len.to_f * n_bars / cycle_len
      return kind if bar < scaled.round
    end
  end

  pos = bar % cycle_len
  cumulative = 0
  map.each do |kind, len|
    return kind if pos < cumulative + len
    cumulative += len
  end
  map.last.first
end

def apply_form_to_cfg!(cfg)
  form = ENV["FORM"]&.to_sym
  preset = FORM_PRESETS[form] if form && FORM_PRESETS.key?(form)
  preset ||= FORM_PRESETS[:camel_32] if %w[camel dilla].include?(ENV["RENDER_MODE"].to_s.downcase)
  preset ||= FORM_PRESETS[:soul_16] if ENV["RENDER_MODE"] == "long_soul" || ENV["RENDER_MODE"] == "golden"
  return cfg unless preset
  cfg.merge(
    intro_bars: preset[:intro_bars] || cfg[:intro_bars],
    phrase_bars: preset[:phrase_bars] || cfg[:phrase_bars],
    form: form || :soul_16,
  )
end

# --------------------------------------------------------------------------
# engine part: lead_arp
# --------------------------------------------------------------------------
#
# Scale-locked leads and arpeggios.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def harmony_lead_enabled?
  # Dilla/camel style DNA enables harmony lead (DILLA_STYLE_DEFAULTS /
  # DILLA_BEST_DEFAULTS). long_soul/golden same. Explicit HARMONY_LEAD=0 wins.
  default = if camel_mode? || %w[long_soul golden warp].include?(ENV["RENDER_MODE"].to_s.downcase)
              "1"
            else
              "0"
            end
  ENV.fetch("HARMONY_LEAD", default) != "0"
end

def harmony_lead_mode
  raw = (ENV["HARMONY_LEP_MODE"] || "hybrid").to_sym
  %i[chord scale hybrid].include?(raw) ? raw : :hybrid
end

def harmony_lead_cfg_for(patch = nil)
  style = (ENV["HARMONY_ARP_STYLE"] || "major_third_cycle_full").to_sym
  {
    style:,
    subdiv: 8,
    gate: 0.68,
    vel: 0.42,
    arp_styles: patch&.dig(:arp_styles) || %i[major_third_cycle_full quint_spread call motif updown],
  }
end

def harmony_lead_events(pad_events, cfg, arp_cfg, progression_insight: nil)
  return [] if pad_events.empty? || arp_cfg.nil?
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  lead_patch = @render_scale_lead_patch || @render_lead_patch
  octave_mul = 2.0**((lead_patch&.fetch(:octave, 2) || 2) - 1)
  n_bars_est = pad_events.empty? ? 32 : ((pad_events.last[0] / bar_p).ceil + 1)
  events = []
  prev_chord = nil
  pad_events.each_with_index do |(time, velocity, chord, sustain), i|
    next unless chord && chord[:hz]&.any?
    bar_approx = (time / bar_p).floor.clamp(0, [n_bars_est - 1, 0].max)
    section = dilla_section(bar_approx, n_bars_est)
    next if section == :intro && bar_approx < 2
    progress = i.to_f / [pad_events.length - 1, 1].max
    density = DillaHarmonyLead.section_density(section, progress)
    style_hint = DillaHarmonyLead.arp_style_for_change(prev_chord, chord, insight: progression_insight)
    variation = arp_variation_for_chord(i, chord, cfg, arp_cfg, patch: lead_patch, role: :lead)
    variation[:style] = style_hint if style_hint
    variation[:pattern_mode] = :motif if style_hint == :motif
    variation[:pattern_mode] = :call if style_hint == :call
    subdiv = variation[:subdiv]
    step_p = beat_p / subdiv.to_f
    gate = variation[:gate]
    rng = chord_variation_rng(cfg, i, chord, salt: 12_007)
    swing = cfg[:swing].to_f / 100.0 * step_p * 0.28
    tones = DillaHarmonyLead.harmonic_arp_tones_for_chord(chord, prev_chord:, mode: harmony_lead_mode)
    tones = tones.map { |hz| hz * octave_mul }.select { |hz| hz < 2500.0 }
    next if tones.empty?
    pattern = arp_pattern_for_chord(chord, variation, tones.length, rng)
    pattern = chord_motif_for(chord).map { |d| d % tones.length } if variation[:pattern_mode] == :motif
    n_steps = [((sustain / step_p).floor * variation[:n_steps_mul] * density).to_i, 3].max
    step_dur = step_p * gate
    n_steps.times do |step|
      next if arp_rest_step?(step, variation[:rest_prob], i)
      hz = if harmony_lead_mode == :hybrid && step.odd? && (pass = DillaHarmonyLead.passing_tone_hz(chord, step, rng))
             pass
           else
             tones[pattern[step % pattern.length] % tones.length]
           end
      t = arp_step_time(time, step, step_p, swing, variation[:step_jitter], variation)
      break if t >= time + sustain - step_dur * 0.35
      accent = step.zero? || (step % 4).zero?
      vel = (velocity * variation[:vel] * (accent ? 0.92 : 0.78) * density).clamp(0.18, 0.62)
      events << [t, vel, { name: "harmony_lead", hz: [hz] }, step_dur]
    end
    prev_chord = chord
  end
  events.sort_by { |e| e[0] }
end

# Parse root letter from chord name (handles slash chords: D/E → D, not E pedal).
def chord_root_pc(chord)
  raw = chord[:name].to_s.sub(/_pedal\z/, "").sub(/_t\d+\z/, "").sub(/low\z/, "")
  # Upper structure before slash is the harmony root for lead scale.
  head = raw.split("/").first.to_s
  m = head.match(/\A([A-Ga-g])([#b]?)/)
  return unless m
  names = %w[C C# D D# E F F# G G# A A# B]
  letter = m[1].upcase
  acc = m[2]
  base = { "C" => 0, "D" => 2, "E" => 4, "F" => 5, "G" => 7, "A" => 9, "B" => 11 }[letter]
  return unless base
  pc = base
  pc += 1 if acc == "#"
  pc -= 1 if acc == "b"
  pc % 12
end

# Infer scale mode from chord quality — lead must stay diatonic to this scale.
def chord_scale_mode(chord)
  return :minor unless chord && chord[:hz]&.any?
  name = chord[:name].to_s.downcase
  # Slash chords: quality is on the upper symbol (D/E → major triad on D).
  head = name.split("/").first.to_s
  return :major if head.include?("lyd") || head.include?("maj13") || head.include?("maj9") || head.include?("maj7")
  return :minor if head.include?("dor") || head.include?("m11") || head.include?("m9") || head.include?("m7")
  return :minor if head.match?(/(?:^|[^a-z])m[0-9#b]?/) || head.match?(/[a-g][#b]?m\z/)
  return :major if head.include?("maj") || head.include?("add9") || head.include?("sus")
  # Bare letter or letter+accidental (D, Db, F#) → major triad default.
  return :major if head.match?(/\A[a-g][#b]?\z/)
  # Dominant / mixolydian flavor still uses major scale degrees with b7 via chord tones.
  return :major if head.match?(/7\z/) || head.include?("dom") || head.include?("mix")
  # Interval check from harmonic root (not pedal bass).
  root_pc = chord_root_pc(chord)
  midis = chord[:hz].map { |h| hz_to_midi(h).round }
  if root_pc
    ivs = midis.map { |m| (m - root_pc) % 12 }.uniq
  else
    ivs = chord_intervals_from_hz(chord[:hz])
  end
  return :minor if ivs.include?(3) && !ivs.include?(4)
  return :major if ivs.include?(4) && !ivs.include?(3)
  return :minor if ivs.include?(10) && !ivs.include?(11)
  :major
end

# Semitone degrees for the chord's parent scale (0–11 relative to harmonic root).
def chord_scale_semitones(chord)
  # Prefer richer quality-aware set from harmony-lead heuristics when available.
  if defined?(DillaHarmonyLead) && DillaHarmonyLead.respond_to?(:chord_scale_semitones)
    return DillaHarmonyLead.chord_scale_semitones(chord)
  end
  SCALE_SEMITONES.fetch(chord_scale_mode(chord), SCALE_SEMITONES[:major])
end

def scale_tones_for_chord(chord, lead_low: 58, lead_high: 88)
  return [] unless chord && chord[:hz]&.any?
  root_pc = chord_root_pc(chord)
  root_midi = if root_pc
                # Place root near mid register from chord's center of mass.
                center = chord[:hz].map { |h| hz_to_midi(h) }.sum / chord[:hz].length
                base = center.floor - (center.floor % 12) + root_pc
                base -= 12 while base > center + 6
                base += 12 while base < center - 6
                base
              else
                hz_to_midi(chord[:hz].min).floor
              end
  scale = chord_scale_semitones(chord)
  tones = []
  (-1..3).each do |oct|
    scale.each do |semi|
      midi = root_midi + semi + oct * 12
      tones << midi_to_hz(midi) if midi.between?(lead_low, lead_high)
    end
  end
  tones = tones.uniq.sort
  return tones unless tones.empty?
  chord[:hz].sort.map { |hz| hz * 2.0 }.uniq.sort
end

# Lead tone set: chord tones first (in-register), then scale tones of THIS chord only.
# Guarantees arps/melodies never leave the pad harmony's scale.
def lead_scale_locked_tones_hz(chord, lead_patch: nil, lead_low: 58, lead_high: 84)
  return [] unless chord && chord[:hz]&.any?
  scale_hz = scale_tones_for_chord(chord, lead_low:, lead_high:)
  scale_pcs = scale_hz.map { |h| hz_to_midi(h).round % 12 }.uniq
  chord_midis = chord[:hz].map { |h| hz_to_midi(h) }.sort
  # Drop pedal/bass if multi-voice so lead sits above pads.
  chord_midis = chord_midis.drop(1) if chord_midis.length >= 4
  chord_in_scale = chord_midis.filter_map do |m|
    m += 12 while m < lead_low
    m -= 12 while m > lead_high
    next unless scale_pcs.include?(m.round % 12)
    next unless m.between?(lead_low, lead_high)
    midi_to_hz(m)
  end.uniq
  # Prefer chord tones; fill with scale for arpeggio motion.
  ordered = (chord_in_scale + scale_hz).uniq
  return ordered unless ordered.empty?
  # Fallback: force chord tones into lead register (still better than chromatic).
  chord_midis.map do |m|
    m += 12 while m < lead_low
    m -= 12 while m > lead_high
    midi_to_hz(m)
  end.uniq.sort
end

def scale_arp_section_density(section, progress)
  base = case section
         when :intro then 0.38
         when :breakdown then 0.48
         when :build then 0.88
         when :outro then 0.58
         else 0.74
         end
  base * (progress < 0.1 ? 0.7 : 1.0)
end

def pad_midi_events_for_layer(pad_events, cfg, _patch, role:, duration:)
  return pad_events if pad_events.length < 2
  return pad_events unless la_beat_progression_enabled? || ENV["PAD_LEGATO_VAR"] == "1"
  rng = Random.new(patch_cycle_seed(stable_hash(role) + pad_events.length))
  beat_p = 60.0 / cfg[:bpm]
  pad_events.map.with_index do |parts, i|
    time, vel, chord, sustain = parts
    legato = rng.rand(0.74..1.14)
    stagger = rng.rand(-0.03..0.06) * beat_p
    [time + stagger, vel * rng.rand(0.9..1.02), chord, sustain * legato]
  end
end

def resolve_midi_fx_for(patch, role:)
  midi_fx_specs_for_role(role, patch)
end

def lead_arp_enabled?
  # Explicit off always wins — was: pad_arp_mode != :held forced leads on even
  # when LEAD_ARP=0, so "pads only" streams still rendered wonky lead soup.
  return false if ENV["LEAD_ARP"] == "0"
  return true if pad_arp_mode != :held
  ENV.fetch("LEAD_ARP", "1") != "0"
end

# When true, lead uses subdiv arps (spiral/skip/…); when false, slow melodic phrases.
def lead_true_arp_mode?
  # NO_ARP covers leads, not just pads. It only ever reached pad_arp_mode, so
  # "stop using arpeggiators" silenced the pad arps and left the leads running
  # theirs — and both STREAM_STYLE_SAFE and stream_iterate set LEAD_FORCE_ARP=1
  # on every track, so the forced flag won every time. This has to be checked
  # before that flag rather than after it.
  #
  # False here does not silence the lead; it routes it to slow melodic phrases
  # instead of subdiv arp figures, which is what was being asked for.
  return false if no_arp?

  return false if ENV["MELODIC_LEAD"] == "1" && ENV["LEAD_FORCE_ARP"] != "1"
  return true if ENV["LEAD_FORCE_ARP"] == "1" || ENV["MELODIC_LEAD"] == "0"
  mode = (ENV["LEAD_ARP_MODE"] || lead_arp_mode || "").to_s
  !%w[melodic_soul melodic soul_wash ballad_bloom donuts_shimmer].include?(mode)
end

# Lead arp figure — LEAD_ARP_MODE preset, experimental pool, PAD fallback, or patch midi_arp.
def lead_arp_cfg_for(patch)
  return unless lead_arp_enabled?
  key = lead_arp_preset_key
  base = if key && LEAD_ARP_PRESETS[key]
           LEAD_ARP_PRESETS[key].dup
         elsif key && EXPERIMENTAL_LEAD_ARP_PRESETS[key]
           EXPERIMENTAL_LEAD_ARP_PRESETS[key].dup
         elsif key && PAD_ARP_PRESETS[key]
           PAD_ARP_PRESETS[key].dup.tap { |h| h[:vel] = (h[:vel] * 1.85).clamp(0.38, 0.58) }
         end
  if base
    styles = (base[:arp_styles] || []) | Array(patch&.dig(:arp_styles)) | ARP_PATTERN_BUILDERS.keys.first(8)
    merged = base.merge(patch&.dig(:midi_arp) || {})
                 .merge(arp_styles: styles.uniq)
    # melodic_soul, the default lead mode, sits at gate 0.92 — each note holds
    # 92% of its slot, so one runs into the next and the line reads as legato
    # even before portamento is applied. Capping it detaches the notes.
    merged[:gate] = [merged[:gate] || LEAD_SIMPLE_GATE_MAX, LEAD_SIMPLE_GATE_MAX].min if lead_simple?
    merged
  else
    patch&.dig(:midi_arp) || {
      style: @render_arp_style || :spiral,
      subdiv: 8,
      gate: (patch&.fetch(:gate, 0.72) || 0.72) * 0.88,
      vel: 0.55,
      arp_styles: %i[spiral skip_up euclidean wonky_wobble pingpong],
    }
  end
end

def lead_arp_section_density(section, progress)
  base = case section
         when :intro then 0.55
         when :breakdown then 0.65
         when :build then 1.0
         when :outro then 0.72
         else 0.85
         end
  base * (progress < 0.08 ? 0.75 : 1.0)
end

def xlead_arp_section_density(section, progress)
  base = case section
         when :intro then 0.78
         when :breakdown then 0.88
         when :build then 1.0
         when :outro then 0.82
         else 0.94
         end
  base * (progress < 0.05 ? 0.88 : 1.0)
end

def melodic_lead_mode?
  # NO_ARP has to win here, above the MELODIC_LEAD=0 check, or it does nothing.
  #
  # stream_rotate_voices_and_arps! sets MELODIC_LEAD=0 on every stream and
  # demo-all slot. Turning off lead_true_arp_mode? therefore left the lead in
  # neither state — not a true arp, but blocked from melodic — so it fell
  # through to lead_arp_events with the preset config still attached, which is
  # style=skip_up at subdiv 8. Arps were "off" and the lead was still running
  # eight notes a chord.
  return true if no_arp?

  return false if lead_true_arp_mode?
  return false if ENV["MELODIC_LEAD"] == "0"
  return true if ENV.fetch("MELODIC_LEAD", "0") != "0"
  mode = (ENV["LEAD_ARP_MODE"] || lead_arp_mode || "").to_s
  %w[soul_wash melodic_soul melodic donuts_shimmer ballad_bloom].include?(mode)
end

# Melodic phrase: 1 note/beat, motif 0-2-1-3, voice-led from previous phrase.
# Tones are scale-locked to the current pad chord.
# Let the chord go before the next one arrives.
#
# Measured on an 8-bar render: the harmonic stem sounds 100.0% of the track,
# against 88.6% for drums and 73.1% for bass. Chords hold 97% of their slot and
# then overlap into the next, so the harmony never stops — there is no moment
# where the drums are alone and the next chord has to arrive.
#
# That is the one thing every writeup of Ahmad Jamal's playing puts first, and
# it is the reason his records sample so well: the space was already in them.
# Space is not the absence of an arrangement decision, it is one.
#
# Applied to every fourth chord change, and only in the main sections — an intro
# is already sparse and a breakdown is already the space. HARMONIC_SPACE=0
# restores the continuous hold; HARMONIC_SPACE_MUL tunes how much is given back.
def harmonic_space_mul(chord_change_i, section, phase)
  return 1.0 if ENV["HARMONIC_SPACE"] == "0"
  return 1.0 unless %i[main recapitulation].include?(section) || phase == :recapitulation
  return 1.0 unless (chord_change_i % 4).zero?

  (ENV["HARMONIC_SPACE_MUL"] || "0.62").to_f.clamp(0.3, 1.0)
end

def lead_melodic_phrase_for_chord(time, velocity, chord, sustain, chord_i, cfg, lead_patch,
                                  role: :lead, prev_end_hz: nil)
  tones = lead_scale_locked_tones_hz(chord, lead_patch:)
  return [] if tones.empty?
  beat_p = 60.0 / cfg[:bpm]
  # The lead sits behind the keys, which already sit behind the drums. `time`
  # arrives carrying the pad's offset, so only the remainder is added here.
  time += DillaGroove.role_timing_offset(:lead_extra, beat_p, 0, 0)
  # Quarter notes (subdiv 1 per beat) — readable top line, not arp soup.
  step_p = beat_p
  # Was a hardcoded 0.9, which is legato regardless of LEAD_SIMPLE. The cap has
  # to apply here too, since this is the path NO_ARP now routes every lead into.
  gate = lead_simple? ? LEAD_SIMPLE_GATE_MAX : 0.9
  step_dur = step_p * gate
  n_steps = [(sustain / step_p).floor, 2].max
  n_steps = [n_steps, 6].min
  # Motif over chord tones; rotate per chord so the line breathes.
  base = [0, 2, 1, 3, 1, 0]
  rot = chord_i % [tones.length, 3].max
  pattern = base.map { |d| (d + rot) % tones.length }
  # Voice-lead start: pick tone nearest previous phrase end.
  if prev_end_hz
    start_i = tones.each_with_index.min_by { |hz, _| (hz - prev_end_hz).abs }&.last || 0
    pattern = [start_i] + pattern.reject.with_index { |_, i| i.zero? }
  end
  vel_base = (velocity * 0.62).clamp(0.38, 0.78)
  events = []
  n_steps.times do |step|
    # Leave air every other chord on the last beat.
    next if step == n_steps - 1 && (chord_i % 2).zero? && n_steps > 2
    idx = pattern[step % pattern.length] % tones.length
    hz = tones[idx]
    t = time + step * step_p
    break if t >= time + sustain - step_dur * 0.25
    accent = step.zero?
    vel = (vel_base * (accent ? 1.05 : 0.88)).clamp(0.34, 0.82)
    tag = role == :xlead ? "xlead" : "lead_arp"
    events << [t, vel, { name: tag, hz: [hz] }, step_dur]
  end
  events
end

def lead_arp_events_for_chord(time, velocity, chord, sustain, chord_i, cfg, arp_cfg, lead_patch,
                              role: :lead, n_bars_est: nil, skip_intro: false, progress: nil,
                              prev_end_hz: nil)
  return [] unless chord && chord[:hz]&.any? && arp_cfg
  if role != :xlead && melodic_lead_mode?
    return lead_melodic_phrase_for_chord(time, velocity, chord, sustain, chord_i, cfg, lead_patch,
                                         role:, prev_end_hz:)
  end
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  n_bars_est ||= ((time / bar_p).ceil + 4)
  bar_approx = (time / bar_p).floor.clamp(0, [n_bars_est - 1, 0].max)
  section = dilla_section(bar_approx, n_bars_est)
  # Keep lead present from bar 0 so streams always have a top line.
  if skip_intro && section == :intro && bar_approx < 1 && role != :xlead
    return []
  end
  progress ||= chord_i.to_f / [n_bars_est, 1].max
  density = role == :xlead ? xlead_arp_section_density(section, progress) : lead_arp_section_density(section, progress)
  density = [density, 0.75].max if role != :xlead
  variation = arp_variation_for_chord(chord_i, chord, cfg, arp_cfg, patch: lead_patch, role:)
  # Melodic (slow phrase) only when melodic_lead_mode? — otherwise full subdiv arps.
  if role != :xlead && melodic_lead_mode?
    variation = variation.merge(
      style: arp_cfg[:style] || :updown,
      subdiv: [arp_cfg.fetch(:subdiv, 2), 4].min,
      rest_prob: [variation[:rest_prob].to_f, 0.22].max,
      pattern_mode: :motif,
      n_steps_mul: 0.55,
      step_jitter: [variation[:step_jitter].to_f, 0.008].min,
    )
  elsif role != :xlead
    # True arp: denser 8ths/16ths, rotate styles from preset pool.
    styles = Array(arp_cfg[:arp_styles])
    styles = %i[spiral skip_up euclidean wonky_wobble] if styles.empty?
    style = styles[chord_i % styles.length] || arp_cfg[:style] || :spiral
    variation = variation.merge(
      style:,
      subdiv: [arp_cfg.fetch(:subdiv, 8), 6].max.clamp(4, 12),
      rest_prob: [variation[:rest_prob].to_f, 0.12].min,
      pattern_mode: :arp,
      n_steps_mul: 1.0,
      step_jitter: [variation[:step_jitter].to_f, 0.012].min,
    )
  end
  subdiv = variation[:subdiv]
  step_p = beat_p / subdiv.to_f
  gate = variation[:gate]
  vel_scale = (variation[:vel] * 1.25).clamp(0.42, 0.72)
  rng = chord_variation_rng(cfg, chord_i, chord, salt: role == :xlead ? 12_007 : 9907)
  swing = cfg[:swing].to_f / 100.0 * step_p * (role == :xlead ? 0.42 : 0.28)
  # Strict: only pitches from this chord's parent scale (+ chord tones).
  tones = lead_scale_locked_tones_hz(chord, lead_patch:)
  tones = scale_tones_for_chord(chord) if tones.empty?
  return [] if tones.empty?
  pattern = arp_pattern_for_chord(chord, variation, tones.length, rng)
  n_steps = [((sustain / step_p).floor * variation[:n_steps_mul]).to_i, role == :xlead ? 3 : 4].max
  n_steps = [n_steps, melodic_lead_mode? ? 8 : 16].min if role != :xlead
  step_dur = step_p * gate
  vel_lo = role == :xlead ? 0.32 : 0.34
  vel_hi = role == :xlead ? 0.9 : 0.85
  events = []
  n_steps.times do |step|
    rest_p = role == :xlead ? [variation[:rest_prob].to_f * 0.35, 0.08].min : [variation[:rest_prob].to_f, 0.18].max
    next if arp_rest_step?(step, rest_p, chord_i)
    hz = tones[pattern[step % pattern.length] % tones.length]
    t = arp_step_time(time, step, step_p, swing, variation[:step_jitter], variation)
    break if t >= time + sustain - step_dur * 0.3
    accent = step.zero? || (step % 4).zero?
    vel = (velocity * vel_scale * (accent ? 1.08 : 0.9) * density).clamp(vel_lo, vel_hi)
    tag = role == :xlead ? "xlead" : "lead_arp"
    events << [t, vel, { name: tag, hz: [hz] }, step_dur]
  end
  events
end

# Continuous lead arpeggiator — chord-tone figures on the lead voice (8th/16th
# subdivisions, patch-specific pattern + MIDI FX). Rendered on its own FluidSynth
# stem (lead_arp.wav); distinct from scale_lead and creative-lead bursts.
def lead_arp_events(pad_events, cfg, arp_cfg)
  return [] if pad_events.empty? || arp_cfg.nil?
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  lead_patch = @render_lead_patch
  n_bars_est = pad_events.empty? ? 32 : ((pad_events.last[0] / bar_p).ceil + 1)
  prev_end = nil
  events = []
  pad_events.each_with_index do |(time, velocity, chord, sustain), i|
    progress = i.to_f / [pad_events.length - 1, 1].max
    chunk = lead_arp_events_for_chord(time, velocity, chord, sustain, i, cfg, arp_cfg, lead_patch,
                                      role: :lead, n_bars_est:, progress:,
                                      prev_end_hz: prev_end).to_a
    prev_end = chunk.last&.dig(2, :hz)&.first if chunk.any?
    events.concat(chunk)
  end
  events.sort_by { |e| e[0] }
end

# Continuous scale-locked arp on every pad chord — same root/mode as the pad,
# stepping 16ths through scale degrees for the full chord sustain.
def lead_events_scale_arp(pad_events, cfg, duration: nil, n_bars: nil)
  return [] if pad_events.empty?
  # A third arp path. NO_ARP reached pad_arp_mode, then lead_true_arp_mode?, and
  # this one still ran 16ths over every chord underneath both — which is why the
  # render banner kept naming an arp style after the other two were silenced.
  # Returning empty drops a voice rather than muting the track: the melodic lead
  # and the pads both still play.
  return [] if no_arp?
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  n_bars ||= duration ? (duration / bar_p).ceil : 32
  scale_patch = @render_scale_lead_patch
  base_gate = scale_patch&.fetch(:gate, 0.62) || 0.62
  base_cfg = { style: @render_scale_arp_style || :updown, subdiv: 4, gate: base_gate, vel: 0.38 }
  events = []
  pad_events.each_with_index do |(time, velocity, chord, sustain), i|
    next unless chord && chord[:hz]&.any?
    bar_approx = (time / bar_p).floor.clamp(0, n_bars - 1)
    section = dilla_section(bar_approx, n_bars)
    next if section == :intro && bar_approx < 2
    progress = i.to_f / [pad_events.length - 1, 1].max
    density = scale_arp_section_density(section, progress)
    scale_tones = lead_scale_locked_tones_hz(chord, lead_patch: scale_patch)
    scale_tones = scale_tones_for_chord(chord) if scale_tones.empty?
    next if scale_tones.empty?
    variation = arp_variation_for_chord(i, chord, cfg, base_cfg, patch: scale_patch, role: :scale_lead)
    subdiv = variation[:subdiv]
    step_p = beat_p / subdiv.to_f
    gate = variation[:gate]
    rng = chord_variation_rng(cfg, i, chord, salt: 4423)
    pattern = arp_pattern_for_chord(chord, variation, scale_tones.length, rng)
    n_steps = [((sustain / step_p).floor * variation[:n_steps_mul]).to_i, 4].max
    n_steps = [n_steps, (sustain / step_p).ceil].min
    step_dur = step_p * gate * 0.9
    swing = cfg[:swing].to_f / 100.0 * step_p * 0.35
    n_steps.times do |step|
      next if arp_rest_step?(step, variation[:rest_prob] * 0.65, i)
      hz = scale_tones[pattern[step % pattern.length] % scale_tones.length]
      t = arp_step_time(time, step, step_p, swing, variation[:step_jitter], variation)
      break if t >= time + sustain - step_dur * 0.4
      accent = step.zero? || (step % 4).zero?
      vel = (velocity * (accent ? 0.44 : 0.34) * density * variation[:vel]).clamp(0.14, 0.58)
      events << [t, vel, { name: "scale_arp", hz: [hz] }, step_dur]
    end
  end
  events
end

def arp_degrees_for(style, tone_count, rng)
  return [] if tone_count.to_i <= 0

  builder = ARP_PATTERN_BUILDERS[style] || ARP_PATTERN_BUILDERS[:updown]
  raw = builder.arity >= 2 ? builder.call(tone_count, rng) : builder.call(tone_count)
  raw.map { |d| d % tone_count }
end

# Per-chord RNG — same progression, different figure/timing every change.
def chord_variation_rng(cfg, chord_i, chord, salt: 0)
  seed = (stable_hash(cfg[:track].to_s) % 100_000) + (@render_seed || 0) + chord_i * 131 +
         (stable_hash(chord[:name].to_s) % 5000) + salt
  Random.new(seed)
end

def arp_styles_for_patch(patch, fallback_style)
  patch&.dig(:arp_styles) || [fallback_style || :updown]
end

# Euclidean/ratchet/random_walk/stutter/burst already exist in
# ARP_PATTERN_BUILDERS but every patch's own arp_styles list sticks to the
# safe up/down/updown/pingpong shapes — this is the IDM/Warp-leaning
# opt-in that reaches for the shapes that are already built but unused.
ARP_IDM_STYLES = %i[euclidean ratchet random_walk stutter burst].freeze

# The same opt-in for the shape-based figures. They are already reachable --
# the xlead and lead paths below sample the whole builder table -- but only by
# chance, and a figure you can only get by luck is one you cannot A/B. This is
# the switch that asks for them on purpose. ARP_SHAPE_BIAS=1.
ARP_SHAPE_STYLES = %i[
  plain_hunt golden_rotation tide pendulum cascade
  swallow_dive undertow call_answer rosary murmuration
].freeze

# Each pad/lead chord gets its own arp style, subdiv, gate, swing, and pattern shape.
def arp_variation_for_chord(chord_i, chord, cfg, base_arp_cfg, patch: nil, role: :lead)
  rng = chord_variation_rng(cfg, chord_i, chord, salt: stable_hash(role))
  styles = base_arp_cfg[:arp_styles] || arp_styles_for_patch(patch, base_arp_cfg[:style])
  style = styles[chord_i % styles.length]
  style = ARP_IDM_STYLES.sample(random: rng) if ENV["ARP_IDM_BIAS"] == "1" && rng.rand < 0.65
  style = ARP_SHAPE_STYLES.sample(random: rng) if ENV["ARP_SHAPE_BIAS"] == "1" && rng.rand < 0.65
  if role == :pad
    subdiv_pool = [base_arp_cfg.fetch(:subdiv, 8), 4, 6, 8].uniq
    pattern_modes = %i[style motif sparse stagger call]
    return {
      style:,
      subdiv: subdiv_pool[chord_i % subdiv_pool.length],
      gate: base_arp_cfg.fetch(:gate, 0.75) * rng.rand(0.92..1.06),
      vel: base_arp_cfg.fetch(:vel, 0.22) * rng.rand(0.88..1.1),
      time_offset: rng.rand(-0.02..0.05),
      step_jitter: rng.rand(0.0..0.012),
      rest_prob: rng.rand(0.0..0.06),
      pattern_mode: pattern_modes[chord_i % pattern_modes.length],
      swing_mul: rng.rand(0.75..1.15),
      n_steps_mul: rng.rand(0.72..1.0),
    }
  end
  if role == :xlead
    style = ARP_PATTERN_BUILDERS.keys.sample(random: rng) if rng.rand < 0.55
    subdiv_pool = [3, 4, 6, 8, 12, 16].uniq
    return {
      style:,
      subdiv: subdiv_pool[rng.rand(subdiv_pool.length)],
      gate: base_arp_cfg.fetch(:gate, 0.5) * rng.rand(0.7..1.28),
      vel: base_arp_cfg.fetch(:vel, 0.58) * rng.rand(0.82..1.38),
      time_offset: rng.rand(-0.05..0.12),
      step_jitter: rng.rand(0.0..0.035),
      rest_prob: rng.rand(0.0..0.1),
      pattern_mode: %i[style motif retrograde sparse call stagger burst stutter].sample(random: rng),
      swing_mul: rng.rand(0.5..1.55),
      n_steps_mul: rng.rand(0.55..1.15),
    }
  end
  style = ARP_PATTERN_BUILDERS.keys.sample(random: rng) if rng.rand < 0.3
  subdiv_pool = [base_arp_cfg.fetch(:subdiv, 8), 3, 4, 6, 8, 12].uniq
  # Operator, 2026-08-11: leads at half rate. subdiv is steps per bar, so
  # halving it halves the note rate — the figure is the same, played twice as
  # slow. Floor of 2 so a pool entry of 3 cannot round to a subdivision that
  # produces no steps.
  {
    style:,
    subdiv: [subdiv_pool[rng.rand(subdiv_pool.length)] / 2, 2].max,
    gate: base_arp_cfg.fetch(:gate, 0.62) * rng.rand(0.82..1.14),
    vel: base_arp_cfg.fetch(:vel, 0.5) * rng.rand(0.75..1.2),
    time_offset: rng.rand(-0.035..0.09),
    step_jitter: rng.rand(0.0..0.022),
    rest_prob: rng.rand(0.0..0.14),
    pattern_mode: lead_pattern_mode(chord_i, cfg, rng),
    swing_mul: rng.rand(0.6..1.4),
    n_steps_mul: rng.rand(0.5..1.0),
  }
end

# Every arp pattern was picked fresh per chord with no thread between phrases
# — a melody that never restates or develops an idea, cycles shapes.
# chord_motif_for already gives a stable, chord-symbol-consistent figure and
# :motif already exists as a pattern_mode; this deliberately reaches for
# it at phrase openings (not every chord — variation still matters) so a
# phrase can actually be recognized as "the same idea" when it returns.
def phrase_start_chord?(chord_i, cfg)
  chord_bars = cfg[:chord_bars]
  phrase_bars = cfg[:phrase_bars]
  return chord_i.zero? unless chord_bars && phrase_bars && chord_bars.positive?
  chords_per_phrase = (phrase_bars / chord_bars.to_f).round
  return chord_i.zero? if chords_per_phrase <= 0
  (chord_i % chords_per_phrase).zero?
end

def lead_pattern_mode(chord_i, cfg, rng)
  modes = %i[style motif retrograde sparse call stagger]
  return modes.sample(random: rng) unless motif_recall_enabled?
  return :motif if phrase_start_chord?(chord_i, cfg) && rng.rand < 0.7
  modes.sample(random: rng)
end

def arp_pattern_for_chord(chord, variation, tone_count, rng)
  return [] if tone_count.to_i <= 0 || chord.nil?

  case variation[:pattern_mode]
  when :motif
    chord_motif_for(chord).map { |d| d % tone_count }
  when :retrograde
    arp_degrees_for(variation[:style], tone_count, rng).reverse
  when :sparse
    arp_degrees_for(variation[:style], tone_count, rng).each_with_index.filter_map { |d, i| (i.even? || rng.rand < 0.42) ? d : nil }
  when :call
    chord_motif_for(chord).map { |d| d % tone_count } +
      arp_degrees_for(variation[:style], tone_count, rng).first(4)
  when :stagger
    base = arp_degrees_for(variation[:style], tone_count, rng)
    base.flat_map.with_index { |d, i| i.even? ? [d, d] : [d] }
  else
    arp_degrees_for(variation[:style], tone_count, rng)
  end
end

def arp_rest_step?(step, rest_prob, chord_i)
  return false if rest_prob < 0.02
  Random.new(chord_i * 97 + step * 13).rand < rest_prob
end

def arp_step_time(time, step, step_p, swing, jitter, variation)
  t = time + variation[:time_offset] + step * step_p
  t += (step.odd? ? swing * variation[:swing_mul] : 0.0)
  t += jitter * ((step % 3) - 1)
  t
end

# Pad chord entry + chop placement — not locked to bar%4 templates.
def dilla_chord_change_variation(chord_i, bar, section, feel, step_p, chord)
  cfg = dilla_resolve_config
  rng = chord_variation_rng(cfg, chord_i, chord, salt: 7711)
  base_pad_offset = DillaHarmony.pad_entry_late(cfg, feel, step_p)
  sustain_mul = DillaHarmony.pad_sustain_mul(cfg, section, rng)
  chop_density = DillaHarmony.chop_density(cfg, section)
  chop_templates = [
    [1, 5, 9, 13], [2, 6, 10, 14], [1, 9, 13], [3, 7, 11, 15],
    [0, 4, 8, 12], [1, 3, 7, 11], [2, 5, 9, 14], [4, 8, 12, 15],
    [1, 7, 13], [2, 8, 10, 14], [5, 9, 13], [0, 6, 10, 14], [3, 9, 15]
  ]
  chop_steps = chop_templates[(chord_i + bar) % chop_templates.length].dup
  chop_steps.delete_at(rng.rand(chop_steps.length)) if rng.rand < 0.38 && chop_steps.length > 2
  chop_steps << [0, 3, 6, 10, 14].sample(random: rng) if rng.rand < 0.28 && chop_density > 0.3
  if chop_density < 0.35
    keep = (chop_steps.length * chop_density * 2.5).ceil.clamp(1, chop_steps.length)
    chop_steps = chop_steps.sort_by { |s| rng.rand }.first(keep).sort
  end
  {
    pad_offset: base_pad_offset + rng.rand(-step_p * 0.4..step_p * 0.9),
    sustain_mul:,
    chop_steps: chop_steps.uniq.sort,
    chop_jitter: rng.rand(-0.028..0.028),
    pad_vel_mul: rng.rand(0.86..1.1),
    double_pad: rng.rand < 0.2 && section == :main,
    double_pad_delay: step_p * rng.rand(0.2..0.85),
    double_pad_vel: rng.rand(0.18..0.32),
  }
end

def dilla_anchor_chop_step(chop_step, drum_steps, rng)
  return chop_step if ENV.fetch("CHOP_ANCHOR_DRUMS", "1") == "0"
  anchors = Array(drum_steps).map(&:to_i).uniq
  return chop_step if anchors.empty?
  nearest = anchors.min_by { |s| (s - chop_step).abs }
  return chop_step unless nearest && (nearest - chop_step).abs <= 2

  # Dilla-style chops often feel performed with the kit: close to the transient,
  # but not machine-locked to it. Keep a small MPC-tick drift around the anchor.
  drift_ticks = ENV.fetch("CHOP_DRIFT_TICKS", "3").to_i.clamp(0, 8)
  drift = drift_ticks.positive? ? rng.rand(-drift_ticks..drift_ticks) / 24.0 : 0.0
  (nearest + drift).clamp(0.0, 15.75)
end

def lead_section_chance(section, progress)
  case section
  when :intro then 0.06
  when :breakdown then 0.12
  when :build then 0.48
  when :outro then 0.18
  else progress > 0.78 ? 0.42 : 0.26
  end
end

# --------------------------------------------------------------------------
# engine part: lead_melodic
# --------------------------------------------------------------------------
#
# Melodic lead writing: voice leading, phrase shape, parallel-interval rejection.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Occasional lead bursts — not every chord gets an arp. When they fire, use
# intricate patterns (euclidean, fibonacci, wonky wobble, etc.) with
# call-and-response and patch-specific gate lengths.
# --- The counter-line -------------------------------------------------------
#
# A second tune that answers the chords, instead of a busier copy of them.
#
# What was wrong. Every other lead in this file is built by walking the list of
# pad events -- the chords. For each chord it takes that chord's notes, starts
# when the chord starts, and stops when the chord stops. So the lead played the
# same notes as the backing, at the same moment, only faster. That is not a
# second part. It is the first part again with more notes in it, and it buried
# the chords rather than answering them.
#
# What this does instead. It asks the chords only one question -- "what notes
# are allowed right now?" -- and decides everything else itself: when to come
# in, how long to hold, which way to move, and how far behind the beat to sit.
#
# The rules below are borrowed, not invented. Sources are named where they
# apply. Nothing here is a matter of taste that could not be checked.

# A step is a tone or less. Anything past a fifth is a jump too far to sing.
LEAD_STEP_SEMITONES = 2
LEAD_LEAP_MAX = 7

# Where the line sits. Roughly a singer's range, centred near middle C, which
# is the neutral register string and vocal arrangers write pads in -- high
# enough to be heard over the chords, low enough not to shriek.
LEAD_RANGE_HZ = (220.0..880.0).freeze
LEAD_CENTRE_HZ = 330.0

# Beats within a bar where a note may start. Never the downbeat: the chord lands
# there, and the answer should arrive after the question.
LEAD_ONSET_BEATS = [1.0, 2.5, 3.0].freeze

# How far behind the beat the line sits, in MPC ticks at 96 PPQ.
#
# The whole engine is built on the idea that a part which lands exactly on the
# grid sounds like a machine, and lo-fi guidance says the same thing in plainer
# words: do not quantize everything, the moments that sit slightly off are where
# the feel comes from. The first version of this generator ignored all of that
# and placed every note on an exact grid position, in a file named after the
# producer whose entire signature is that his parts do not.
#
# Sung and bowed lines drag: a voice takes time to speak and a bow takes time to
# bite, so they arrive after the note they are answering. Hence a base lag,
# plus a small per-note wobble so no two entries are identical.
#
# Ticks rather than milliseconds, matching GROOVE_FEELS: the MPC3000 nudge tool
# could only land on tick boundaries, and a fractional offset is one the machine
# this models could never have produced.
LEAD_LAG_TICKS = 5
LEAD_LAG_JITTER_TICKS = 3
MPC_PPQ = 96

def melodic_lead_enabled? = ENV.fetch("MELODIC_LEAD", "1") != "0"

# How far apart two pitches are, in semitones. Positive means the second is
# higher.
def semitones_between(from_hz, to_hz)
  return 0.0 unless from_hz&.positive? && to_hz&.positive?

  12.0 * Math.log2(to_hz / from_hz)
end

# Are these the same note, ignoring which octave it lands in?
def same_pitch_class?(a_hz, b_hz)
  offset = semitones_between(a_hz, b_hz).abs % 12
  offset < 0.25 || offset > 11.75
end

# Which chord is sounding at this moment. The events are in time order, so the
# answer is the last one to have started.
def pad_chord_at(pad_events, time)
  pad_events
    .take_while { |(start, *)| start <= time + 1e-6 }
    .reverse_each
    .find { |(_, _, chord, _)| chord.is_a?(Hash) && chord[:hz]&.any? }
    &.fetch(2)
end

# The gap between the counter-line and the chord under it, folded into one
# octave. 0 is a unison or octave, 7 a perfect fifth.
def harmonic_interval(lead_hz, pad_hz)
  return unless lead_hz&.positive? && pad_hz&.positive?

  semitones_between(pad_hz, lead_hz).round % 12
end

PERFECT_INTERVALS = [0, 7].freeze

# The oldest rule in counterpoint, and the half I left out the first time.
#
# Two voices a fifth apart that both move and are still a fifth apart have, to
# the ear, stopped being two voices -- the interval is so consonant that the
# upper one is heard as an overtone of the lower. Octaves do it worse. Every
# species-counterpoint text forbids it and every generator that encodes those
# rules penalises it outright.
#
# The first version of this scorer rewarded contrary motion and stopped there,
# which catches only the case where both voices move the same way. Two voices
# CAN move in opposite directions and still arrive at consecutive fifths, and
# nothing here would have noticed.
def parallel_perfect?(prev_lead, lead, prev_pad, pad)
  return false unless prev_lead && prev_pad && lead && pad
  return false if prev_lead == lead || prev_pad == pad   # nothing moved

  before = harmonic_interval(prev_lead, prev_pad)
  after = harmonic_interval(lead, pad)
  return false unless before && after

  before == after && PERFECT_INTERVALS.include?(after)
end

# Per-phrase ceilings, from the same generators the motion rules come from.
#
# Each rule below is a cost, not a ban, so a single note can break one when
# every alternative is worse. Left at that, a whole phrase can be nothing but
# leaps, because each leap won its own comparison. These are the caps that stop
# a local decision becoming a global habit.
LEAD_PARALLEL_SHARE_MAX = 0.5
LEAD_LEAP_SHARE_MAX = 0.3
LEAD_REPEAT_SHARE_MAX = 0.5

# Rate one candidate note. Higher is better.
def lead_note_score(hz, prev_hz, pad_direction, chord, tally: nil, prev_pad_top: nil, pad_top: nil)
  return 0.0 unless hz&.positive?
  return 1.0 unless prev_hz&.positive?

  move = semitones_between(prev_hz, hz)
  distance = move.abs
  score = 0.0

  score += case distance
           when 0 then -0.6                        # standing still says nothing
           when ..LEAD_STEP_SEMITONES then 1.0     # a step: how tunes move
           when ..4 then 0.35                      # a small skip, still singable
           when ..LEAD_LEAP_MAX then -0.2          # a real jump, needs a reason
           else -1.0                               # further than anyone sings
           end

  # The rule that makes this a second voice rather than a thicker first one.
  unless pad_direction.zero? || move.zero?
    score += move.positive? == pad_direction.positive? ? -0.5 : 0.8
  end

  # Consecutive fifths and octaves, refused hard enough that only an empty
  # alternative set can let one through.
  score -= 3.0 if parallel_perfect?(prev_hz, hz, prev_pad_top, pad_top)

  # Notes already in the chord settle; the rest of the scale passes through.
  score += 0.3 if chord[:hz].any? { |chord_hz| same_pitch_class?(hz, chord_hz) }

  # Drift back toward the middle of the range, so a run of good local choices
  # cannot walk the line off the top or bottom of its register.
  score -= (semitones_between(LEAD_CENTRE_HZ, hz).abs / 24.0)

  score + phrase_cap_penalty(tally, move, pad_direction)
end

# Once a phrase has spent its allowance of leaps, repeats or parallel motion,
# more of the same gets expensive.
def phrase_cap_penalty(tally, move, pad_direction)
  return 0.0 unless tally && tally[:notes].positive?

  n = tally[:notes].to_f
  penalty = 0.0
  distance = move.abs
  parallel = !pad_direction.zero? && !move.zero? && (move.positive? == pad_direction.positive?)

  penalty -= 1.5 if parallel && (tally[:parallel] / n) >= LEAD_PARALLEL_SHARE_MAX
  penalty -= 1.5 if distance > 4 && (tally[:leaps] / n) >= LEAD_LEAP_SHARE_MAX
  penalty -= 1.5 if distance.zero? && (tally[:repeats] / n) >= LEAD_REPEAT_SHARE_MAX
  penalty
end

# Which way the chords have just moved: up, down, or nowhere.
def pad_direction(previous_top, current_top)
  return 0 unless previous_top && current_top

  current_top <=> previous_top
end

# Pick the moments in one phrase where the line may speak.
#
# The first bar is left alone on purpose -- the chords need a bar to say
# something before anything answers. The rest are spread evenly rather than
# chosen at random, because random picks clump and the gaps are the point.
def lead_onsets_for_phrase(phrase_start, phrase_bars, bar_p, beat_p, wanted, ceiling)
  candidates = (1...phrase_bars).flat_map do |bar|
    LEAD_ONSET_BEATS.map { |beat| phrase_start + (bar * bar_p) + (beat * beat_p) }
  end
  candidates.select! { |t| t < ceiling - beat_p }
  return [] if candidates.empty?

  stride = [candidates.length / wanted, 1].max
  candidates.each_slice(stride).map(&:first).first(wanted)
end

# A shape the line returns to.
#
# Without one, every phrase is decided note by note and nothing ever comes back,
# so a listener has nothing to recognise -- which is half of why a whole demo
# reads as repetitive without ever repeating anything memorable. Sample chopping
# is described as letting a producer shift the focus onto particular themes and
# motifs, and a motif is exactly what this engine had none of.
#
# The motif is stored as CONTOUR -- how many scale steps to move, not which
# notes -- so it survives being played over a different chord. Each phrase takes
# a transformation of it, in the order a composer would: state it, state it
# again, invert it, reverse it. That is repetition with variation, which is what
# holds attention, rather than either novelty or literal repeat.
LEAD_MOTIF_TRANSFORMS = %i[plain plain inverted retrograde].freeze

# Phrases where the line says nothing at all.
#
# A part that plays in every phrase stops being an answer and becomes a texture.
# The whole Detroit end of this lineage treats space as the instrument -- few
# elements, worked hard, with room around them -- and the arranging guidance
# says the same thing about counter-melodies: they go BETWEEN the phrases, and
# between means there are phrases they are not in.
#
# The third phrase of every four, and never the first.
#
# The shape has to be stated before its absence can be felt, and it has to come
# back afterwards or the silence reads as the piece ending rather than as
# breathing. Third of four gives state / state / gone / back.
#
# Not `phrase % 4 == 0`, which was the first attempt: over a 16-bar piece there
# are exactly four phrases, numbered 0 to 3, and none of 1, 2 or 3 is divisible
# by four -- so the rest never once happened at the length these actually render
# at. It measured as 4 phrases out of 4 playing.
LEAD_REST_EVERY = 4
LEAD_REST_PHASE = 2

def lead_phrase_rests?(phrase)
  return false if phrase.zero?
  return false if ENV.fetch("LEAD_PHRASE_RESTS", "1") == "0"

  (phrase % LEAD_REST_EVERY) == LEAD_REST_PHASE
end

# Ghost notes.
#
# The quiet, half-struck note just before the one that lands. On the drums it is
# the ghost snare that makes a Dilla pattern breathe instead of march, and it is
# the single most recognisable thing about the drum programming this engine is
# named for. There is no reason it should belong only to drums -- a singer
# scoops into a note and a bowed string speaks before it sounds.
#
# A sixteenth early, a third of the velocity, and a step below: quiet enough to
# be felt rather than heard, which is the point of a ghost.
LEAD_GHOST_VELOCITY = 0.34
LEAD_GHOST_LEAD_IN_BEATS = 0.25

def lead_ghost_for(time, velocity, hz, tones, beat_p, rng)
  return unless ENV.fetch("LEAD_GHOSTS", "1") != "0"
  return unless rng.rand < 0.35

  below = tones.select { |t| t < hz && semitones_between(t, hz) <= 3 }.max
  return unless below

  start = time - (LEAD_GHOST_LEAD_IN_BEATS * beat_p)
  return if start <= 0

  [start, velocity * LEAD_GHOST_VELOCITY, { name: "counter_ghost", hz: [below * counter_lead_detune] },
   LEAD_GHOST_LEAD_IN_BEATS * beat_p * 0.8]
end

def lead_motif(rng, length)
  # Small steps, mostly, with the occasional skip: a singable shape.
  Array.new(length) { [-2, -1, -1, 1, 1, 2, 3].sample(random: rng) }
end

def lead_motif_step(motif, transform, index)
  return 0 if motif.empty?

  case transform
  when :inverted then -motif[index % motif.length]
  when :retrograde then motif[(motif.length - 1 - (index % motif.length))]
  else motif[index % motif.length]
  end
end

def lead_events_melodic(pad_events, cfg, duration: nil, n_bars: nil)
  return [] if pad_events.empty? || !melodic_lead_enabled?

  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  tick_p = beat_p / MPC_PPQ
  total = duration || pad_events.map { |event| event[0].to_f + event[3].to_f }.max
  return [] unless total.to_f.positive?

  phrase_bars = ENV.fetch("LEAD_PHRASE_BARS", "4").to_i.clamp(1, 16)
  per_phrase = ENV.fetch("LEAD_NOTES_PER_PHRASE", "4").to_i.clamp(1, 12)
  answer_chords = ENV.fetch("LEAD_CONTRARY", "1") != "0"
  humanize = ENV.fetch("LEAD_HUMANIZE", "1") != "0"
  lag_ticks = ENV.fetch("LEAD_LAG_TICKS", LEAD_LAG_TICKS.to_s).to_i
  rng = Random.new(stable_hash(cfg[:track].to_s) + (@render_seed || 0) + 5501)

  motif = lead_motif(rng, per_phrase)
  phrase_p = bar_p * phrase_bars
  previous_hz = nil
  previous_top = nil

  (total / phrase_p).ceil.times.flat_map do |phrase|
    next [] if lead_phrase_rests?(phrase)

    onsets = lead_onsets_for_phrase(phrase * phrase_p, phrase_bars, bar_p, beat_p, per_phrase, total)
    transform = LEAD_MOTIF_TRANSFORMS[phrase % LEAD_MOTIF_TRANSFORMS.length]
    tally = { notes: 0, parallel: 0, leaps: 0, repeats: 0 }

    onsets.each_with_index.filter_map do |time, index|
      chord = pad_chord_at(pad_events, time)
      next unless chord

      tones = scale_tones_for_chord(chord)
      next if tones.empty?

      top = chord[:hz].max
      direction = answer_chords ? pad_direction(previous_top, top) : 0

      reachable = tones.select { |hz| LEAD_RANGE_HZ.cover?(hz) }
      reachable = tones if reachable.empty?
      if previous_hz
        near = reachable.select { |hz| semitones_between(previous_hz, hz).abs <= LEAD_LEAP_MAX }
        reachable = near unless near.empty?
      end

      # The motif proposes, the rules dispose. Where the motif's next step lands
      # is scored like any other candidate, so a shape that would cause parallel
      # fifths or walk off the register loses to one that does not -- the theme
      # survives, the mistakes do not.
      wanted = lead_motif_step(motif, transform, index)
      chosen = reachable.max_by do |hz|
        base = lead_note_score(hz, previous_hz, direction, chord,
                               tally:, prev_pad_top: previous_top, pad_top: top)
        steps = previous_hz ? (semitones_between(previous_hz, hz) / 2.0).round : 0
        base + (steps == wanted ? 0.9 : 0.0) + (rng.rand * 0.15)
      end
      next unless chosen

      next_time = onsets[index + 1] || (phrase * phrase_p) + phrase_p
      sustain = [[(next_time - time) * 0.82, beat_p * 0.75].max, total - time].min
      next if sustain <= 0.05

      # Sit behind the beat, and never twice by the same amount.
      offset = humanize ? (lag_ticks + rng.rand(-LEAD_LAG_JITTER_TICKS..LEAD_LAG_JITTER_TICKS)) * tick_p : 0.0
      start = (time + offset).clamp(0.0, total - sustain)

      if previous_hz
        move = semitones_between(previous_hz, chosen)
        tally[:leaps] += 1 if move.abs > 4
        tally[:repeats] += 1 if move.zero?
        tally[:parallel] += 1 if !direction.zero? && !move.zero? && (move.positive? == direction.positive?)
      end
      tally[:notes] += 1

      previous_hz = chosen
      previous_top = top
      velocity = (0.30 + (rng.rand * 0.06)) * (index.zero? ? 1.0 : 0.92)
      # Detuned in the note, not by varispeeding the finished layer -- see
      # counter_lead_space_chain for what that cost in timing.
      note = [start, velocity, { name: "counter_lead", hz: [chosen * counter_lead_detune] }, sustain]
      ghost = lead_ghost_for(start, velocity, chosen, reachable, beat_p, rng)
      ghost ? [ghost, note] : [note]
    end.flatten(1)
  end
end

def lead_events_creative(pad_events, cfg, duration: nil, n_bars: nil)
  return [] if pad_events.empty?
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  n_bars ||= duration ? (duration / bar_p).ceil : 32
  seed = (stable_hash(cfg[:track].to_s) % 100_000) + (@render_seed || 0) + 8801
  rng = Random.new(seed)
  leitmotif = leitmotif_for(pad_events)
  arp_style = @render_arp_style || :updown
  lead_patch = @render_lead_patch
  gate_mul = (lead_patch&.fetch(:gate, 0.82) || 0.82)
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    gate_mul *= @composition_session.performer_profile[:gate_mul]
  end
  octave_mul = 2.0 ** ((lead_patch&.fetch(:octave, 2) || 2) - 2)
  events = []
  burst_remaining = 0
  pad_events.each_with_index do |(time, velocity, chord, sustain), i|
    next unless chord && chord[:hz]&.any?
    bar_approx = (time / bar_p).floor.clamp(0, n_bars - 1)
    section = dilla_section(bar_approx, n_bars)
    progress = i.to_f / [pad_events.length - 1, 1].max
    motif_cell = if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
                   @composition_session.motif_for_bar(bar_approx)
                 end
    leitmotif = motif_cell.degrees_for_playback if motif_cell
    if burst_remaining.positive?
      burst_remaining -= 1
    else
      chance = if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
                 prof = @composition_session.profile_at(bar_approx)
                 (prof[:lead] * prof[:melodic_density]).clamp(0.05, 0.92)
               else
                 lead_section_chance(section, progress)
               end
      chance += 0.15 if i % 11 == 5
      next unless rng.rand < chance
      burst_remaining = rng.rand(1..3)
    end
    # Scale-locked only — no chromatic approach tones off the pad harmony.
    tones = lead_scale_locked_tones_hz(chord, lead_patch:)
    tones = scale_tones_for_chord(chord) if tones.empty?
    next if tones.empty?
    if octave_mul != 1.0
      tones = tones.map { |hz| hz * octave_mul }.select do |hz|
        m = hz_to_midi(hz)
        m.between?(55, 90)
      end
      tones = lead_scale_locked_tones_hz(chord, lead_patch:) if tones.empty?
    end
    burst_cfg = { style: arp_style, subdiv: 2, gate: gate_mul, vel: 0.72 }
    variation = arp_variation_for_chord(i, chord, cfg, burst_cfg, patch: lead_patch, role: :creative_lead)
    pattern = case variation[:pattern_mode]
              when :motif then motif_from_chord(chord).map { |d| d % tones.length }
              when :retrograde then invert_motif(leitmotif)
              when :call then leitmotif + invert_motif(leitmotif)
              when :sparse then leitmotif.each_with_index.filter_map { |d, si| (si.even? || rng.rand < 0.5) ? d : nil }
              else [leitmotif, invert_motif(leitmotif), leitmotif.reverse,
                    arp_degrees_for(variation[:style], tones.length, rng),
                    leitmotif + invert_motif(leitmotif)][i % 5]
              end
    pattern = arp_pattern_for_chord(chord, variation, tones.length, rng) if rng.rand < 0.38
    subdiv = variation[:subdiv]
    step_dur = [(sustain || 1.0) / (pattern.length * subdiv.to_f), 0.045].max
    step_dur *= 1.35 if section == :build
    step_dur *= variation[:n_steps_mul].clamp(0.55, 1.0)
    swing_push = (cfg[:quintuplet] ? step_dur * 0.04 : 0.0) * variation[:swing_mul]
    pattern.each_with_index do |degree, step|
      next if arp_rest_step?(step, variation[:rest_prob], i + 500)
      hz = tones[degree % tones.length]
      # Diatonic approach: previous scale degree, never chromatic half-step.
      if step.zero? && i.positive? && tones.length > 1
        idx = tones.index(hz) || 0
        approach = tones[(idx - 1) % tones.length]
      else
        approach = hz
      end
      t = time + variation[:time_offset] + 0.04 + step * step_dur + (step.odd? ? swing_push : 0.0) +
          variation[:step_jitter] * ((step % 3) - 1) +
          DillaGroove.melody_time_offset(bar_approx, step, beat_p)
      vel = (velocity * (0.88 - step * 0.04)).clamp(0.18, 0.95)
      vel *= 1.12 if section == :build
      pan = if cfg[:stereo_pan]
step.even? ? -0.45 : 0.45
else
(step.even? ? -0.12 : 0.12)
end
      events << [t, vel, { name: "lead", hz: [approach] }, step_dur * gate_mul, pan]
    end
    next unless rng.rand < 0.55 && i.positive?
    answer_style = ARP_PATTERN_BUILDERS.keys.sample(random: rng)
    answer_pat = arp_degrees_for(answer_style, tones.length, rng)
    conv_offset = if composition_enabled?
                    DillaComposition::Conversation.answer_offset(:lead, beat_p)
                  else
                    0.0
                  end
    answer_offset = conv_offset + pattern.length * step_dur * 0.45
    answer_oct = 1.0
    answer_pat.each_with_index do |degree, step|
      hz = tones[degree % tones.length] * answer_oct
      t = time + 0.04 + answer_offset + step * step_dur * 1.1
      vel = (velocity * 0.42 * (1.0 - step * 0.03)).clamp(0.1, 0.55)
      pan = if cfg[:stereo_pan]
step.even? ? 0.55 : -0.55
else
(step.even? ? 0.18 : -0.18)
end
      events << [t, vel, { name: "lead_answer", hz: [hz] }, step_dur * gate_mul * 0.75, pan]
    end
  end
  events
end

def warm_dilla_pad_post(path, cfg: nil, sonic: nil)
  cfg ||= dilla_resolve_config
  sonic ||= cfg[:sonic]
  return path unless tool_available?("ffmpeg")
  lp = sonic_pad_lowpass(sonic)
  tmp = "#{path}.pad_tmp.wav"
  fluidsynth = defined?(@render_used_fluidsynth_pad) && @render_used_fluidsynth_pad
  filt = if fluidsynth
           [
             "aformat=channel_layouts=stereo",
             "lowpass=f=#{lp}:width_type=q:width=0.82",
             "equalizer=f=260:t=o:w=1.0:g=#{pad_mud_db(0.6)}",
             "equalizer=f=900:t=h:w=800:g=0.8",
             "equalizer=f=3200:t=h:w=1400:g=0.6",
             # aecho/chorus take in_gain:out_gain, NOT a wet/dry mix -- both
             # scale the whole signal. 0.34:0.44 is 0.15x (-16.7 dB) and
             # 0.34:0.54 another 0.18x (-12.4 dB); stacked they buried the
             # entire harmonic bus ~29 dB, which is why the chords were
             # inaudible under the drums. Effect depth lives in the decays
             # and depths args, so keep those and run the gains near unity.
             "aecho=0.9:0.85:90|180:0.2|0.1",
             "chorus=0.9:0.85:30|40:0.14|0.1:0.18|0.14:0.92|1.15",
             "acompressor=threshold=-22dB:ratio=1.5:attack=65:release=280:makeup=1.5",
             "volume=1.1",
             "alimiter=limit=0.96:level_out=0.98",
           ]
         else
           patch_fx = @render_warm_patch&.dig(:fx) || @render_ep_patch&.dig(:fx)
           [
             "aformat=channel_layouts=stereo",
             "lowpass=f=#{lp}:width_type=q:width=0.88",
             "equalizer=f=260:t=o:w=1.0:g=#{pad_mud_db}",
             "equalizer=f=520:t=h:w=700:g=#{pad_mud_db(0.9)}",
             "equalizer=f=1100:t=o:w=0.9:g=-0.6",
             "equalizer=f=3200:t=h:w=1600:g=1.0",
             ("tremolo=f=3.2:d=0.06" if cfg[:style_family] == :dilla),
             # Same in_gain:out_gain fix as the fluidsynth branch above.
             "aecho=0.9:0.85:100|180:0.2|0.1",
             "chorus=0.9:0.85:30|40:0.16|0.12:0.2|0.18:0.95|1.2",
             patch_fx,
             "acompressor=threshold=-24dB:ratio=1.6:attack=60:release=260:makeup=1.6",
             "volume=1.12",
             "alimiter=limit=0.96:level_out=0.98",
           ]
         end
  sh! "ffmpeg", "-y", "-i", path, "-af", filt.compact.join(","), "-c:a", "pcm_s16le", tmp
  FileUtils.mv(tmp, path)
  path
end

# --------------------------------------------------------------------------
# engine part: engine_defaults
# --------------------------------------------------------------------------
#
# Engine-wide defaults: tempos, chords, stocks, grades, Sonitex and analog chains.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

GENERATED_STYLE_ROUTES = {
  major_third_cycle_full: :generate_coltrane_changes,
  backdoor: :generate_backdoor_progression,
  slash: :generate_slash_progression,
  modal_interchange: :generate_modal_interchange,
  tritone_sub: :generate_tritone_sub_progression,
}.freeze

def route_generated_style(style, root_hz:, mode:, length:, seed:)
  meth = GENERATED_STYLE_ROUTES[style]
  return send(meth, root_hz:, mode:, length:, seed:) if meth
  nil
end

