    kicks: [[0, 8], [0, 6, 8, 14], [0, 8, 11], [3, 8, 11], [0, 8, 10, 14]],
    snares: [[4, 12], [4, 10, 12], [2, 6, 10, 14], [4, 12, 14]],
    ghosts: [
