# Which defaults table last touched each ENV key, and how (fill vs force) —
# multiple tables (DILLA_BEST_DEFAULTS, RENDER_MODE_DEFAULTS,
# DILLA_STYLE_DEFAULTS, STREAM_EXTRA_DEFAULTS/STREAM_CREATIVE_MAX) apply in
# sequence, soft-fill only wins races when nothing set the key first, and
# that ordering has caused real, silent bugs (a style table's setting
# permanently losing to an earlier table because apply_render_mode! hadn't
# run yet). See "config-provenance" command.
def config_provenance
  @config_provenance ||= {}
end

def record_config_provenance!(key, label, verb)
  return unless label
  config_provenance[key] = "#{label} (#{verb})"
end

def comfort_mode?
  return false if ENV["STREAM_PUNCH"] == "1"
  return false if ENV["STREAM_COMFORT"] == "0" || ENV["DILLA_COMFORT"] == "0"
  return true if ENV["STREAM_COMFORT"] == "1" || ENV["DILLA_COMFORT"] == "1"
  return true if ENV["RENDER_MODE"].to_s.downcase == "comfort"

  false
end

def apply_comfort_style!(force: true)
  return unless comfort_mode?

  DILLA_COMFORT_DEFAULTS.each do |key, value|
    style_env_write!(key, value, force:, label: "DILLA_COMFORT_DEFAULTS")
  end
end

def soft_fill_env!(table, label: nil)
  table.each { |key, value| style_env_write!(key, value, force: false, label:) }
end

# Overwrite ENV keys (stream creative layer after style force-locks).
# One writer for every defaults/profile table, so the user-pin rule lives in one
# place instead of being re-implemented per loop.
#
# force_env! got the rule when USER_PINNED_ENV was introduced. Four other loops
# did not, and each kept its own bare `ENV[k] = v`: apply_dilla_style!'s
# DILLA_STYLE_DEFAULTS pass, reassert_dilla_style_locks!,
# apply_track_soul_profile!'s pad/lead profiles, and apply_track_layer_profile!.
# Every stream boot runs all four through apply_dilla_style!(force: true), so a
# pinned PAD_VOICE/LEAD_ARP/SYNTH_CYCLE was reverted before the first render and
# the documented environment variables were, again, advisory.
def style_env_write!(key, value, force:, label: nil)
  k = key.to_s
  return false if value.nil?
  return false unless force || ENV[k].to_s.empty?

  if USER_PINNED_ENV.key?(k) && ENV[k] == USER_PINNED_ENV[k]
    record_config_provenance!(k, label, "user-pinned")
    return false
  end

  ENV[k] = value.to_s
  record_config_provenance!(k, label, force ? "force" : "fill")
  true
end

def force_env!(table, label: nil)
  table.each { |key, value| style_env_write!(key, value, force: true, label:) }
end

def print_config_provenance
  if config_provenance.empty?
    puts "config-provenance: empty — run a render first (soft_fill_env!/force_env! haven't been called with labels yet)"
    return
  end
  width = config_provenance.keys.map(&:length).max
  config_provenance.sort.each { |key, source| puts "#{key.ljust(width)}  #{source}  = #{ENV[key].inspect}" }
end

def soft_fill_iterate!(tuning, locked_keys: [])
  locked = locked_keys.map(&:to_s)
  tuning.each do |key, value|
    next if value.nil?
    next if locked.include?(key.to_s)
    next if ENV[key] && !ENV[key].empty?
    ENV[key] = value.to_s
  end
end

def reassert_pad_lead_locks!
  return unless dilla_style?
  DILLA_PAD_LEAD_LOCK_KEYS.each do |key|
    next unless DILLA_STYLE_DEFAULTS.key?(key)

    style_env_write!(key, DILLA_STYLE_DEFAULTS[key], force: true, label: "DILLA_PAD_LEAD_LOCK")
  end
end

def reassert_dilla_style_locks!
  return unless dilla_style?
  # Same bypass as apply_dilla_style!'s loop: this reasserts on every track when
  # STREAM_LOCK=1, so a pin that survived boot was reverted one track later.
  DILLA_STYLE_LOCK_KEYS.each do |key|
    next unless DILLA_STYLE_DEFAULTS.key?(key)

    style_env_write!(key, DILLA_STYLE_DEFAULTS[key], force: true, label: "DILLA_STYLE_LOCK")
  end
  # A ceiling, not just a floor.
  #
  # These two lines took the LARGER of the setting and the style default, so the
  # pad envelope could only ever get slower. Progression presets asking for a
  # 1400 ms attack won every time, and the style that is supposed to sound like
  # a played Rhodes chord came out as a swell -- nine tenths of a second to
  # speak, three seconds to die away. Held stacked chords swelling like that is
  # a church organ, which is what the tracks sounded like.
  #
  # A struck electric piano speaks in a few milliseconds and is gone inside a
  # bar. The floor still applies, so nothing gets unnaturally clicky, but the
  # ceiling now stops a preset from turning the kit's own style into ambient
  # music.
  atk = [ENV["PAD_ATTACK"].to_i, DILLA_STYLE_DEFAULTS["PAD_ATTACK"].to_i].max
  rel = [ENV["PAD_RELEASE"].to_i, DILLA_STYLE_DEFAULTS["PAD_RELEASE"].to_i].max
  ENV["PAD_ATTACK"] = [atk, DILLA_PAD_ATTACK_CEILING].min.to_s
  ENV["PAD_RELEASE"] = [rel, DILLA_PAD_RELEASE_CEILING].min.to_s
end
alias reassert_camel_beauty_locks! reassert_dilla_style_locks!

# --------------------------------------------------------------------------
# engine part: stream_iterate
# --------------------------------------------------------------------------
#
# Iterating a stream track: measure the render, evolve, render again.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Loss-gate report for stream promote — RadioBergenStudy#analyze_audio is
# module-private; DeepAudio has the dynamics block gates need.
def stream_analyze_for_gates(path)
  RadioBergenStudy::DeepAudio.analyze(path)
rescue StandardError
  RadioBergenStudy.analyze_audio(path) if RadioBergenStudy.respond_to?(:analyze_audio)
rescue StandardError
  nil
end

def stream_iterate_after_render!(path)
  return unless File.file?(path)
  @stream_iterate_count = (@stream_iterate_count || 0) + 1
  beauty = DillaHarmony.score_beauty(DillaHarmony.last_progression_chords)
  spectrum = render_spectrum(path)
  harsh = DillaMaster.analyze_harshness(spectrum)
  sk = DillaMaster.sub_kick_balance(spectrum, beauty)
  notes = []
  # Dilla-style stream: soft mix nudges only — no morph / grid rewrite / analog roulette.
  if camel_mode?
    if sk[:recommendation] == "boost_sub"
      notes << "sub_ok"
    end
    if harsh[:needs_notch]
      notes << "harsh_soft"
    end
    promote_progression_hook!(ENV["TRACK"].to_s, beauty,
                               report: (stream_analyze_for_gates(path) if DillaMaster.loss_gates.any?),
                               path:)
    notes.concat(stream_iterate_evolve_harmony!) if (@stream_iterate_count % 4).zero?
    reassert_camel_beauty_locks!
    line = "[#{Time.now.utc.iso8601}] ##{@stream_iterate_count} track=#{ENV['TRACK']} beauty=#{beauty} " \
           "camel_beauty #{notes.join(' ')}"
    File.open(STREAM_ITERATE_LOG, "a") { |f| f.puts(line) }
    puts "stream iterate: beauty=#{beauty} camel_lock #{notes.join(', ')}"
    return
  end
  if refine_deep_mix_env!(path)
    notes << "kick=#{ENV['KICK_GAIN']} harm=#{ENV['DEBUG_HARM_WEIGHT']}"
  end
  if harsh[:needs_notch]
    dv = [(resolved_drum_mix_weight - 0.03), 0.22].max
    notes << "drum_vol=#{apply_drum_vol!(dv)}"
  end
  if sk[:recommendation] == "boost_sub" && (ENV["PAD_VOL"] || "52").to_i < 58
    ENV["PAD_VOL"] = ((ENV["PAD_VOL"] || "52").to_i + 2).to_s
    notes << "pad_vol=#{ENV['PAD_VOL']}"
  end
  groove_score = nil
  if instance_variable_defined?(:@last_drum_events) && @last_drum_events
    groove_score = DillaGrooveScore.analyze(@last_drum_events)[:score]
    @last_groove_score = groove_score
    notes << "groove=#{groove_score}"
  end
  promote_progression_hook!(ENV["TRACK"].to_s, beauty,
                             report: (stream_analyze_for_gates(path) if DillaMaster.loss_gates.any?),
                             path:)
  every = [(ENV["EVOLVE_EVERY"] || "3").to_i, 1].max
  evolve_due = composition_enabled? && (@stream_iterate_count % every).zero?
  groove_low = groove_score && groove_score < (ENV["GROOVE_SCORE_MIN"] || "75").to_f
  if evolve_due
    stream_evolve_composition!
    stream_evolve_pocket!
    notes << "evolved"
  elsif groove_low
    stream_evolve_pocket!
    notes << "pocket_nudge"
  end
  if stream_creative_freedom_enabled?
    notes.concat(stream_iterate_creative_freedom!)
  end
  notes.concat(stream_iterate_evolve_harmony!)
  notes.concat(stream_iterate_evolve_wonky_drums!)
  notes.concat(stream_iterate_analog_emulation!)
  line = "[#{Time.now.utc.iso8601}] ##{@stream_iterate_count} track=#{ENV['TRACK']} beauty=#{beauty} " \
         "sub=#{sk[:recommendation]} harsh=#{harsh[:harshness]} #{notes.join(' ')}"
  File.open(STREAM_ITERATE_LOG, "a") { |f| f.puts(line) }
  puts "stream iterate: beauty=#{beauty} #{notes.join(', ')}"
end

def stream_evolve_composition!
  return unless composition_enabled?
  bars = (ENV["BARS"] || STREAM_BARS_COUNT).to_i
  track = ENV["TRACK"].to_s
  sess = composition_session!(n_bars: bars, track:)
  keep_performer = ENV["PERFORMER"]
  keep_groove = ENV["GROOVE_DNA"]
  rng = render_rng("stream_evolve_0", drift: (@stream_iterate_count || 0) + 0)
  sess.motifs.each { |m| m.evolve! if rng.rand < 0.35 }
  if ENV.fetch("STREAM_EVOLVE_PERFORMER", "0") == "1"
    sess.mutate!
    ENV["PERFORMER"] = sess.performer.to_s
    ENV["GROOVE_DNA"] = sess.groove_dna.to_s
  else
    ENV["PERFORMER"] = keep_performer if keep_performer && !keep_performer.empty?
    ENV["GROOVE_DNA"] = keep_groove if keep_groove && !keep_groove.empty?
    sess.instance_variable_set(:@generation, sess.generation + 1)
  end
  cfg = dilla_resolve_config
  ENV["SWING"] = cfg[:swing].round(1).to_s if cfg[:swing]
  sess.save!
  puts "stream evolve gen=#{sess.generation} performer=#{ENV['PERFORMER']} groove=#{ENV['GROOVE_DNA']}"
end

def stream_evolve_pocket!(groove_analysis: nil)
  return unless stream_iterate_enabled?
  cfg = dilla_resolve_config
  return unless DillaComposition::Evolution.dilla_pocket_style?(cfg)
  rng = render_rng("stream_evolve_17", drift: (@stream_iterate_count || 0) + 17)
  events = groove_analysis || (instance_variable_defined?(:@last_drum_events) ? @last_drum_events : nil)
  recs = events ? DillaGrooveScore.evolve_recommendations(DillaGrooveScore.analyze(events)) : {}
  @last_groove_score = recs[:score]

  ENV["SNARE_EARLY"] = recs[:snare_early] == false ? "0" : "1"
  ENV["HATS_LATE"] = recs[:hats_late] == false ? "0" : "1"
  ENV["GROOVE_LOCK"] = "kick"
  ENV["FLAM"] = "1"
  ENV["MARKOV_DRUMS"] = "1" if recs[:markov_ghosts]
  ENV["GHOST_TIER"] = recs[:ghost_tier].to_s if recs[:ghost_tier]

  delta = recs[:swing_delta] || rng.rand(-1.5..1.5)
  swing = (cfg[:swing] || 57).to_f + delta + rng.rand(-0.8..0.8)
  ENV["SWING"] = swing.clamp(52, 62).round(1).to_s
  ENV["SWING_JITTER_TICKS"] = (recs[:jitter_ticks] || 3).to_s

  if rng.rand < 0.45 || recs[:groove_pool]
    pool = recs[:groove_pool] || %w[donuts fantastic_vol2 endtroducing madvillainy]
    ENV["GROOVE_DNA"] = pool.sample(random: rng)
  end

  ENV["GHOST_BOOST_NUDGE"] = recs[:ghost_boost_nudge].round(3).to_s if recs[:ghost_boost_nudge]
  ENV["VELOCITY_SPREAD_NUDGE"] = recs[:velocity_spread_nudge].round(3).to_s if recs[:velocity_spread_nudge]

  ENV["SIDECHAIN_STYLE"] = "dilla" if cfg[:sidechain]
  score_note = @last_groove_score ? " groove_score=#{@last_groove_score}" : ""
  puts "stream pocket: swing=#{ENV['SWING']} groove=#{ENV['GROOVE_DNA']} tier=#{ENV['GHOST_TIER']}#{score_note}"
end

def load_promoted_track_bias
  return unless File.file?(PROMOTED_PROFILES_PATH)
  data = JSON.parse(File.read(PROMOTED_PROFILES_PATH))
  counts = data.reject { |k, _| k.start_with?("_") }
  top = counts.max_by { |_, v| v.to_i }
  top ? top.first.to_sym : nil
rescue StandardError
  nil
end

# Auto-iterate soul harmony: rotate voicing + Donuts-family tracks; bias promoted/learned profiles.
def stream_iterate_evolve_harmony!
  return [] unless stream_iterate_enabled?
  every = [(ENV["STREAM_HARMONY_EVERY"] || ENV["EVOLVE_EVERY"] || "2").to_i, 1].max
  return [] unless (@stream_iterate_count % every).zero?

  rng = render_rng("stream_evolve_31", drift: (@stream_iterate_count || 0) + 31)
  notes = []

  soul_locked = ENV["STREAM_SOUL"] == "1" && ENV["STREAM_LOCK"] == "1"
  if ENV.fetch("STREAM_LEARN_BIAS", "0") != "0"
    if (hint = learn_catalog_top_hint)
      DillaSourceLearn.apply_hints_to_env!(hint)
      notes << "catalog_bias=#{hint[:track] || hint['track']}"
    end
    report = DillaSourceLearn.load_last_report
    if report && report[:engine_hints]
      DillaSourceLearn.apply_hints_to_env!(report[:engine_hints])
      notes << "learn_bias=#{report[:engine_hints][:track]}"
    end
  end

  promoted = load_promoted_track_bias
  if soul_locked
    apply_track_soul_profile!(ENV["TRACK"], force: false)
    notes << "soul_lock=#{ENV['TRACK']}"
  elsif promoted && SOUL_TRACK_FAMILY.include?(promoted) && rng.rand < 0.35
    ENV["TRACK"] = promoted.to_s
    apply_track_soul_profile!(ENV["TRACK"], force: false)
    notes << "promoted=#{promoted}"
  elsif rng.rand < 0.55
    pick = if promoted && SOUL_TRACK_FAMILY.include?(promoted) && rng.rand < 0.4
             promoted
           else
             SOUL_TRACK_FAMILY.sample(random: rng)
           end
    ENV["TRACK"] = pick.to_s
    apply_track_soul_profile!(ENV["TRACK"], force: false)
    notes << "track=#{pick}"
  end

  voicings = DillaHarmony::VOICING_STYLES
  voicing = voicings[(@stream_iterate_count + rng.rand(0..2)) % voicings.length]
  ENV["VOICING"] = voicing.to_s
  notes << "voicing=#{voicing}"

  w = (ENV["EVOLVE_HARMONY_W"] || "0.18").to_f
  ENV["EVOLVE_HARMONY_W"] = (w + rng.rand(-0.04..0.06)).clamp(0.08, 0.35).round(3).to_s
  notes << "harm_w=#{ENV['EVOLVE_HARMONY_W']}"

  notes
end

# Evolve Wonky overlay density, grid bias, quint hats, and dual-bus mix across stream iterations.
def stream_iterate_evolve_wonky_drums!
  return [] unless wonky_drum_overlay_enabled? && stream_iterate_enabled?
  every = [(ENV["STREAM_WONKY_EVERY"] || ENV["EVOLVE_EVERY"] || "2").to_i, 1].max
  return [] unless (@stream_iterate_count % every).zero?

  rng = render_rng("stream_evolve_67", drift: (@stream_iterate_count || 0) + 67)
  notes = []
  remove_instance_variable(:@wonky_overlay_grid_cache) if instance_variable_defined?(:@wonky_overlay_grid_cache)

  ENV["WONKY_OVERLAY_GAIN"] = rng.rand(0.62..0.88).round(2).to_s
  ENV["WONKY_CHORD_DUCK"] = rng.rand(0.72..0.9).round(2).to_s
  ENV["WONKY_SUB_MIX"] = rng.rand(0.42..0.58).round(2).to_s
  ENV["WONKY_TOP_MIX"] = rng.rand(0.38..0.54).round(2).to_s
  ENV["WONKY_GRID_BIAS"] = %i[intro main build turn breakdown outro].sample(random: rng).to_s
  ENV["SIDECHAIN_STYLE"] = "wonky" if rng.rand < 0.4

  if ENV.fetch("STREAM_LEARN_BIAS", "0") != "0" && rng.rand < 0.45
    if (hint = learn_catalog_top_hint)
      DillaSourceLearn.apply_hints_to_env!(hint)
      notes << "wonky_learn=#{hint[:track] || hint['track']}"
    end
  end

  notes << "wonky_gain=#{ENV['WONKY_OVERLAY_GAIN']}"
  notes << "wonky_grid=#{ENV['WONKY_GRID_BIAS']}"
  notes << "drum_gain=#{ENV['DRUM_BUS_GAIN']}" if ENV["DRUM_BUS_GAIN"]
  notes << "rap_vocal=#{ENV['RAP_VOCAL']}" if rap_vocal_stream_slug
  notes
end

# Rotate Sonitex + analog grade stacks; wild random FX mashups for authentic chaos.
def stream_iterate_analog_emulation!
  return [] unless stream_iterate_enabled?
  # Camel “full sound” locks donuts_soul + summing_phasy; rotating to acetate/scuzz
  # re-introduces wall-of-noise and killed the pad character people liked.
  return [] if camel_mode? && ENV.fetch("CAMEL_LOCK_COLOR", "1") != "0"
  every = (ENV["STREAM_ANALOG_EVERY"] || "0").to_i
  return [] if every <= 0
  return [] unless (@stream_iterate_count % every).zero?

  rng = render_rng("stream_evolve_53", drift: (@stream_iterate_count || 0) + 53)
  notes = []

  if ENV.fetch("STREAM_ANALOG_WILD", "1") != "0" && rng.rand < 0.35
    wild_name = build_random_wild_analog_chain!(rng)
    ENV["ANALOG_CHAIN"] = wild_name.to_s
    notes << "analog=#{wild_name}(#{@stream_wild_analog_chain[:fx].length}fx)"
  else
    pool = ANALOG_CHAIN_ROTATE + ANALOG_CHAIN_WILD_ROTATE
    pick = pool[(@stream_iterate_count + rng.rand(0..3)) % pool.length]
    ENV["ANALOG_CHAIN"] = pick.to_s
    @stream_wild_analog_chain = nil
    notes << "analog=#{pick}"
  end

  if rng.rand < 0.5
    sonitex = SONITEX_ROTATE_STREAM[(@stream_iterate_count + rng.rand(0..2)) % SONITEX_ROTATE_STREAM.length]
    ENV["SONITEX_PRESET"] = sonitex.to_s
    ENV["SONITEX"] = sonitex.to_s
    notes << "sonitex=#{sonitex}"
  end

  if rng.rand < 0.4
    cr = CONV_REVERB_ROTATE[(@stream_iterate_count + rng.rand(0..1)) % CONV_REVERB_ROTATE.length]
    ENV["CONV_REVERB"] = cr
    notes << "conv=#{cr}"
  end

  if rng.rand < 0.35
    vinyl = rng.rand(22..48).round
    ENV["VINYL"] = vinyl.to_s
    notes << "vinyl=#{vinyl}"
  end

  notes
end

# Rotate PAD_VOICE + fresh Rhodes/Prophet/Moog pool picks each stream iteration.
def stream_iterate_morph_synth!
  return [] unless synth_morph_enabled?
  voices = PAD_VOICE_MORPH_VOICES
  unless instance_variable_defined?(:@stream_user_pad_locked) && @stream_user_pad_locked
    ENV["PAD_VOICE"] = voices[(@stream_iterate_count || 0) % voices.length].to_s
  end
  reset_render_patches!
  if lead_morph_enabled?
    unless instance_variable_defined?(:@stream_user_lead_locked) && @stream_user_lead_locked
      ENV["LEAD_MORPH_VOICE"] = LEAD_MORPH_VOICES[(@stream_iterate_count || 0) % LEAD_MORPH_VOICES.length].to_s
      arp_key = MORPH_LEAD_ARP_CYCLE[(@stream_iterate_count || 0) % MORPH_LEAD_ARP_CYCLE.length]
      ENV["LEAD_ARP_MODE"] = arp_key.to_s
    end
  end
  cfg = dilla_resolve_config
  pick_synth_patches!(cfg, bar: (@stream_iterate_count || 0) * 4)
  notes = [
    "morph_pad=#{ENV['PAD_VOICE']}",
    "ep=#{@render_ep_patch&.dig(:id)}",
    "warm=#{@render_warm_patch&.dig(:id)}",
  ]
  if lead_morph_enabled?
    notes << "morph_lead=#{ENV['LEAD_MORPH_VOICE'] || ENV['LEAD_VOICE']}"
    notes << "xlead_arp=#{ENV['LEAD_ARP_MODE']}"
    notes << "lead=#{@render_lead_patch&.dig(:id)}"
    notes << "fm_native=1" if fm_native_enabled?
  end
  notes
end

# Per-track creative rotation: new lead/scale patches, arp figures, stem balance.
def stream_iterate_creative_freedom!
  return [] unless stream_creative_freedom_enabled?
  pick_render_seed! # clears the patch cache
  notes = stream_iterate_morph_synth!
  unless notes.any?
    reset_render_patches!
    cfg = dilla_resolve_config
    pick_synth_patches!(cfg, bar: (@stream_iterate_count || 0) * 4)
  end
  rng = render_rng("arp_style", drift: (@stream_iterate_count || 0) + (@render_seed || 0))
  styles = (@render_lead_patch&.dig(:arp_styles) || ARP_PATTERN_BUILDERS.keys).to_a
  @render_arp_style = styles.sample(random: rng)
  scale_styles = (@render_scale_lead_patch&.dig(:arp_styles) || styles).to_a
  @render_scale_arp_style = scale_styles.sample(random: rng)
  nudge = ->(key, field, delta) {
    base = harmonic_stem_mix_value(key, field)
    lo, hi = field == :weight ? [0.08, 1.6] : [0.4, 1.4]
    ENV["HARMONIC_#{key.to_s.upcase}_#{field.to_s.upcase}"] = (base + delta).clamp(lo, hi).round(3).to_s
  }
  nudge.call(:lead_arp, :weight, rng.rand(-0.06..0.08))
  nudge.call(:xlead, :weight, rng.rand(-0.04..0.1)) if lead_morph_enabled?
  nudge.call(:xlead, :volume, rng.rand(-0.06..0.08)) if lead_morph_enabled?
  nudge.call(:lead, :weight, rng.rand(-0.05..0.07))
  nudge.call(:scale_lead, :weight, rng.rand(-0.05..0.06))
  lead_id = @render_lead_patch&.dig(:id) || "lead"
  scale_id = @render_scale_lead_patch&.dig(:id) || "scale"
  notes + [
    "creative=#{@render_arp_style}/#{@render_scale_arp_style}",
    "leads=#{scale_id}+#{lead_id}",
    "stem_w=#{ENV['HARMONIC_LEAD_ARP_WEIGHT']}/#{ENV['HARMONIC_LEAD_WEIGHT']}",
  ]
end

def phone_preview_gate_enabled?
  ENV["PHONE_PREVIEW_GATE"] == "1"
end

# --------------------------------------------------------------------------
# engine part: apply_profiles
# --------------------------------------------------------------------------
#
# Applying a genre, track or soul profile to the environment.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.
require_relative "lib/frozen_state"

# One word for genre.
#
# Genre was spread across RENDER_MODE, a preset's feel:, GROOVE_DNA, PERFORMER,
# SONITEX, ANALOG_CHAIN, POCKET_SET, VOICING and five separate CLI commands, so
# "make this one sound like jazz" meant knowing which six knobs to move and in
# which order. GENRE names the bundle.
#
# What this is NOT: a renderer switch. GENRE=techno colours a render and turns
# on the harmonic path; it does not route to render_hate_techno. Routing on a
# genre name would rebuild the fork this whole direction exists to remove,
# through a new door -- `dilla.rb hate` is still how you ask for that engine,
# and it now shares the progression with everything else.
#
# Soft-filled, so every value here loses to anything the operator set. That is
# the point of a bundle: a starting position, not a lock. Only knobs whose valid
# values are enumerable in this file are included -- GROOVE_DNA and PERFORMER
# are deliberately absent because their pools are assembled at runtime and a
# wrong constant here would fall back silently, which is the exact failure this
# tree keeps producing.
GENRE_DEFAULTS = {
  # The house lean. Named so it can be asked for explicitly rather than only
  # being what you get by not asking.
  hiphop: { "POCKET_SET" => "neo_soul", "SONITEX" => "donuts_warm",
            "SONITEX_PRESET" => "donuts_warm", "ANALOG_CHAIN" => "vinyl_hot",
            "VOICING" => "rootless" },
  soul: { "POCKET_SET" => "neo_soul", "SONITEX" => "hi_fi_soul",
          "SONITEX_PRESET" => "hi_fi_soul", "ANALOG_CHAIN" => "cassette",
          "VOICING" => "bill_evans" },
  jazz: { "POCKET_SET" => "classic", "SONITEX" => "subtle",
          "SONITEX_PRESET" => "subtle", "ANALOG_CHAIN" => "broadcast",
          "VOICING" => "kenny_barron" },
  # GENRE_HARMONY on, because a techno colour over a progression is the whole
  # reason this axis exists.
  techno: { "POCKET_SET" => "industrial", "SONITEX" => "heavy",
            "SONITEX_PRESET" => "heavy", "ANALOG_CHAIN" => "lo_fi",
            "VOICING" => "quartal", "GENRE_HARMONY" => "1" },
  lofi: { "POCKET_SET" => "dusty", "SONITEX" => "sp1200",
          "SONITEX_PRESET" => "sp1200", "ANALOG_CHAIN" => "cassette",
          "VOICING" => "drop2" },
}.freeze

def apply_genre!
  raw = ENV["GENRE"].to_s.strip.downcase
  return if raw.empty?

  table = GENRE_DEFAULTS[raw.to_sym]
  # Aborts rather than falling through. An unknown genre that quietly renders
  # the default is the failure mode this file is full of: the operator asks for
  # something, gets something else, and nothing says so.
  abort "unknown GENRE=#{raw} — known: #{GENRE_DEFAULTS.keys.join(', ')}" unless table

  soft_fill_env!(table, label: "GENRE_DEFAULTS[#{raw}]")
  DillaDmesg.style!("genre=#{raw}") if ENV["DILLA_STREAMING"] != "1"
end

def apply_render_mode!
  apply_genre!
  normalize_render_mode!
  mode = ENV["RENDER_MODE"]&.downcase&.to_sym
  return unless mode
  table = if mode == :dilla
            DILLA_STYLE_DEFAULTS
          else
            RENDER_MODE_DEFAULTS[mode]
          end
  return unless table
  soft_fill_env!(table, label: table.equal?(DILLA_STYLE_DEFAULTS) ? "DILLA_STYLE_DEFAULTS" : "RENDER_MODE_DEFAULTS[#{mode}]")
  DillaDmesg.style!("mode=#{mode}") if ENV["DILLA_STREAMING"] != "1"
end

def motif_recall_enabled?
  ENV.fetch("MOTIF_RECALL", composition_enabled? ? "1" : "0") != "0"
end

def apply_motif_recall!(bar)
  return unless motif_recall_enabled?
  return unless composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
  return unless bar.positive? && (bar % 16).zero?
  sess = @composition_session
  cb = sess.callbacks.select { |c| c[:motif_id] == "hook" }.max_by { |c| c[:bar] }
  state = cb ? cb[:state] : :A
  sess.record_callback!(bar, "hook", state)
end

def promote_progression_hook!(track, beauty, report: nil, path: nil)
  return if track.to_s.empty?
  min = (ENV["PROMOTION_BEAUTY_MIN"] || "85").to_f
  return unless beauty >= min
  gate = DillaMaster.passes_loss_gates?(report, path:)
  unless gate[:pass]
    warn "progression promotion blocked (loss gates): #{gate[:failures].join('; ')}"
    return
  end
  chords = DillaHarmony.last_progression_chords
  distinct = chords ? chords.map { |c| c[:name].to_s.sub(/_pedal\z/, "").sub(/_t\d+\z/, "") }.uniq.length : 0
  return unless distinct >= 6
  FileUtils.mkdir_p(DillaComposition::PROJECT_DIR)
  promoted = begin
    File.exist?(PROMOTED_PROFILES_PATH) ? JSON.parse(File.read(PROMOTED_PROFILES_PATH)) : {}
  rescue JSON::ParserError => e
    # A corrupt file used to hit the blanket `rescue StandardError` below and
    # return without ever rewriting it -- permanently disabling promotion
    # learning from that point on. Reset and self-repair on the next write
    # instead of staying wedged forever.
    warn "promoted_profiles.json corrupt (#{e.message}), resetting"
    {}
  end
  key = track.to_s.downcase.tr("-", "_")
  promoted[key] = (promoted[key] || 0) + 1
  promoted["_last"] = { "track" => key, "beauty" => beauty.round(1), "at" => Time.now.utc.iso8601 }
  DillaFrozen.write_json(PROMOTED_PROFILES_PATH, promoted)
  remove_instance_variable(:@radio_bergen_learnings) if instance_variable_defined?(:@radio_bergen_learnings)
rescue StandardError => e
  warn "progression promotion failed: #{e.message}"
end

def apply_profile_mash!(cfg)
  mash = ENV["PROFILE_MASH"]
  return cfg unless mash&.include?("+")
  harm_key, drum_key = mash.split("+", 2).map { |s| s.strip.downcase.tr("-", "_").to_sym }
  harm_preset = track_preset(harm_key)
  drum_preset = track_preset(drum_key)
  return cfg unless harm_preset && drum_preset
  harm_sonic = sonic_profile_for(harm_key)
  feel = drum_preset[:feel] || cfg[:feel]
  cfg.merge(
    track: :"#{harm_key}_x_#{drum_key}",
    progression: (ENV["PROGRESSION"] || harm_preset.fetch(:progression, harm_key)).to_s.downcase.tr("-", "_").to_sym,
    bpm: resolve_bpm(harm_preset, harm_key, harm_sonic),
    feel:,
    timing: drum_preset[:timing] || cfg[:timing],
    style_family: style_family(drum_key, feel:),
    mashed: { harmony: harm_key, drums: drum_key },
  )
end

def slash_bass_enabled?(cfg)
  ENV["SLASH_BASS"] == "1" ||
    SLASH_BASS_PROFILES.include?(cfg[:progression].to_sym) ||
    cfg[:track].to_s.include?("slash")
end

def slash_bass_pads_for(pads, cfg)
  return if pads.empty?
  root = pads.first[:hz].min * 0.5
  generate_slash_progression(root_hz: root, length: pads.length, seed: stable_hash(cfg[:track].to_s))
end

def ghost_tier_for(bar, section)
  forced = ENV["GHOST_TIER"]&.to_sym
  return forced if forced && GHOST_TIERS.key?(forced)
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    sect = @composition_session.section_at(bar)
    prof = @composition_session.profile_at(bar)
    case sect
    when :intro, :breakdown then :whisper
    when :hook, :solo then :accent
    else prof[:fill_rate].to_f > 0.4 ? :accent : :pocket
    end
  else
    case section
    when :intro, :breakdown then :whisper
    when :build then :accent
    else :pocket
    end
  end
end

def apply_ghost_tier_vel(vel, tier)
  (vel * GHOST_TIERS.fetch(tier, GHOST_TIERS[:pocket])[:mul]).clamp(0.03, 0.72).round(3)
end

# Stems are written unless STEM_EXPORT=0 or KEEP_STEMS=0.
#
# It was opt-in, so the default was that a render you might want to remix
# arrived flattened and the parts were gone. Nothing here changes what the
# mix sounds like — it writes files beside it — which is why this one can be
# turned on without an ear on it. The cost is disk, and the crate is the
# place that has been expensive rather than this.
def export_render_stems!(destination, drum_tmp, harmonic_tmp, events, duration, cfg, use_stem_harmony:)
  return unless ENV["STEM_EXPORT"] != "0" || ENV["KEEP_STEMS"] != "0"
  stem_dir = File.join(File.dirname(destination), "#{File.basename(destination, '.*')}_stems")
  FileUtils.mkdir_p(stem_dir)
  FileUtils.cp(drum_tmp, File.join(stem_dir, "drums.wav")) if File.exist?(drum_tmp)
  unless use_stem_harmony
    FileUtils.cp(harmonic_tmp, File.join(stem_dir, "harmonic.wav")) if File.exist?(harmonic_tmp)
    bass_tmp = File.join(stem_dir, ".bass_layer.wav")
    render_harmonic_wav(bass_tmp, [], [], events[:bass] || [], duration, cfg:)
    FileUtils.cp(bass_tmp, File.join(stem_dir, "bass.wav")) if File.exist?(bass_tmp)
    FileUtils.rm_f(bass_tmp)
    if events[:melody]&.any?
      mel_tmp = File.join(stem_dir, ".melody_layer.wav")
      render_harmonic_wav(mel_tmp, [], [], [], duration, melody_events: events[:melody], cfg:)
      FileUtils.cp(mel_tmp, File.join(stem_dir, "melody.wav")) if File.exist?(mel_tmp)
      FileUtils.rm_f(mel_tmp)
    end
  end
  FileUtils.cp(destination, File.join(stem_dir, "master#{File.extname(destination)}")) if File.exist?(destination)
  FileUtils.cp(DillaComposition::SESSION_PATH, File.join(stem_dir, "session.json")) if File.exist?(DillaComposition::SESSION_PATH)
  FileUtils.cp(DillaComposition::MOTIFS_PATH, File.join(stem_dir, "motifs.json")) if File.exist?(DillaComposition::MOTIFS_PATH)
  puts "stems: #{stem_dir}"
end

# How many voices a track is allowed to put in the air. dilla's default stack is
# pads + texture + EP + warm + scale lead + lead arp + harmony lead + xlead +
# granular cloud + choir + melody + chops, and everything after the first few is
# fighting the rest for the same space -- audibly "too much going on", and the
# reason a sample bed could not be pushed forward no matter what weight it was
# given: the master limiter was already flattening a crowded mix.
#
# A recreation should carry only what the source has. The 92 BPM Ableton set
# behind :four_seven is four elements -- a sampled loop, an FM bass, a kick and
# a clap -- so everything dilla would otherwise pile on top is turned off, and
# the loop is left to be the harmony, which is its job in the original.
#
# Twelve tracks carry a sampled bed; two had a profile. The other ten got
# dilla's full stack on top of the record, and in the 34-track demo those ten
# held the bottom of the measured enjoyment ranking -- ubrukte_samples_01 last
# of thirty-three. dmaj_open and sheger_01 below are four_seven's shape applied
# to two of them. MASTER_CHAIN is deliberately not copied: that is a mastering
# change, not an arrangement one.
#
# Measured caveat, so nobody reads more into these than is there: with only the
# twelve knobs that survive into demo-all (see apply_track_layer_profile!'s
# caller), adding this profile moved nothing -- lo_borges -0.08, sheger_01
# +0.04 on audiobox-aesthetics content-enjoyment, against a within-arm spread
# of 0.05-0.09 over three seeds. The nine layer-stripping knobs were untestable
# until the re-assert in demo_all landed alongside this.
TRACK_LAYER_PROFILES = {
  four_seven: {
    "PAD_TEXTURE" => "0", "PAD_GRANULAR" => "0", "CHOIR_VOX" => "0",
    "LEAD_ARP" => "0", "SCALE_LEAD" => "0", "HARMONY_LEAD" => "0",
    "CREATIVE_LEAD" => "0", "MELODIC_LEAD" => "0", "EXPERIMENTAL_LEADS" => "0",
    "LEAD_MORPH" => "0", "SYNTH_MORPH" => "0", "PAD_LAYERS" => "0",
    "DRUM_CHOPS" => "0", "ECLECTIC_PERC" => "0", "SELF_SAMPLE" => "0",
    # SPEAK stays off — the source set has no speech in it. RAP_VOCAL does not:
    # the point of this track now is gunnhild over the sampled loop, and a
    # profile default that silently discarded an explicit RAP_VOCAL on the
    # command line made the render look like it had ignored the request.
    "SPEAK" => "0",
    # The loop carries the chords; the synth pad only shades under it.
    "PAD_VOL" => "34", "HARM_MIX_WEIGHT" => "0.55",
    "SAMPLE_LOOP_VOL" => "1.25", "SAMPLE_LOOP_WEIGHT" => "1.6",
    "MASTER_CHAIN" => "akmd",
  },
  # Same shape as four_seven -- the loop carries the harmony, the synths shade
  # under it -- but this source is denser and sits higher, so the pad is pulled
  # further back and the loop is not pushed as hard.
  nightbus: {
    "PAD_TEXTURE" => "0", "CHOIR_VOX" => "0", "SPEAK" => "0",
    "LEAD_ARP" => "0", "SCALE_LEAD" => "0", "HARMONY_LEAD" => "0",
    "CREATIVE_LEAD" => "0", "MELODIC_LEAD" => "0", "EXPERIMENTAL_LEADS" => "0",
    "LEAD_MORPH" => "0", "SYNTH_MORPH" => "0", "PAD_LAYERS" => "0",
    "DRUM_CHOPS" => "0", "ECLECTIC_PERC" => "0", "SELF_SAMPLE" => "0",
    "PAD_VOL" => "26", "HARM_MIX_WEIGHT" => "0.45",
    "SAMPLE_LOOP_VOL" => "1.1", "SAMPLE_LOOP_WEIGHT" => "1.45",
    "MASTER_CHAIN" => "akmd",
  },
  # lo_borges -- a hand-cut record, so the loop is the harmony here too.
  dmaj_open: {
    "PAD_TEXTURE" => "0", "PAD_GRANULAR" => "0", "CHOIR_VOX" => "0",
    "LEAD_ARP" => "0", "SCALE_LEAD" => "0", "HARMONY_LEAD" => "0",
    "CREATIVE_LEAD" => "0", "MELODIC_LEAD" => "0", "EXPERIMENTAL_LEADS" => "0",
    "LEAD_MORPH" => "0", "SYNTH_MORPH" => "0", "PAD_LAYERS" => "0",
    "DRUM_CHOPS" => "0", "ECLECTIC_PERC" => "0", "SELF_SAMPLE" => "0",
    "SPEAK" => "0",
    "PAD_VOL" => "34", "HARM_MIX_WEIGHT" => "0.55",
    "SAMPLE_LOOP_VOL" => "1.25", "SAMPLE_LOOP_WEIGHT" => "1.6",
  },
  # ubrukte_samples_01 -- cut from the Sheger broadcast by `chop`.
  sheger_01: {
    "PAD_TEXTURE" => "0", "PAD_GRANULAR" => "0", "CHOIR_VOX" => "0",
    "LEAD_ARP" => "0", "SCALE_LEAD" => "0", "HARMONY_LEAD" => "0",
    "CREATIVE_LEAD" => "0", "MELODIC_LEAD" => "0", "EXPERIMENTAL_LEADS" => "0",
    "LEAD_MORPH" => "0", "SYNTH_MORPH" => "0", "PAD_LAYERS" => "0",
    "DRUM_CHOPS" => "0", "ECLECTIC_PERC" => "0", "SELF_SAMPLE" => "0",
    "SPEAK" => "0",
    "PAD_VOL" => "34", "HARM_MIX_WEIGHT" => "0.55",
    "SAMPLE_LOOP_VOL" => "1.25", "SAMPLE_LOOP_WEIGHT" => "1.6",
  },
}.freeze

def apply_track_layer_profile!(track, force: true)
  # Same aliasing as the loop registry: the profiles are still keyed by the
  # names these were ingested under, so a render asked for by song title has to
  # resolve to them or it silently loses its layer settings.
  key = track.to_s.downcase.tr("-", "_").to_sym
  key = TRACK_SAMPLE_LOOP_ALIASES.key(key) || key unless TRACK_LAYER_PROFILES.key?(key)
  profile = TRACK_LAYER_PROFILES[key] or return []
  applied = []
  profile.each do |env_key, value|
    applied << env_key if style_env_write!(env_key, value, force:, label: "TRACK_LAYER_PROFILE")
  end
  dmesg("layer profile #{track}: #{applied.size} knobs (strip to source arrangement)",
        unit: "style0", parent: "dilla0") if applied.any?
  applied
end

def apply_track_soul_profile!(track, force: false)
  key = track.to_s.downcase.tr("-", "_").to_sym
  apply_track_layer_profile!(key, force:)
  [TRACK_SOUL_PAD_PROFILES[key], TRACK_SOUL_LEAD_PROFILES[key]].compact.each do |profile|
    profile.each do |env_key, value|
      # Never demote multi-layer stacks to single-voice presets mid-stream.
      next if env_key == "PAD_VOICE" && ENV["PAD_VOICE"].to_s.start_with?("stack_")

      style_env_write!(env_key, value, force:, label: "TRACK_SOUL_PROFILE")
    end
  end
end

def apply_dilla_style!(force: false)
  normalize_render_mode!
  ENV["RENDER_MODE"] = DEFAULT_RENDER_MODE if ENV["RENDER_MODE"].to_s.empty?
  apply_render_mode!
  # Full style DNA only on the dilla path. warp/long_soul/golden/… already
  # soft-filled their own RENDER_MODE_DEFAULTS tables above.
  return unless dilla_style?

  # Every stream boot calls this with force: true via
  # apply_stream_listenability_defaults!, and this loop used to write ENV
  # directly. Measured: launching with `PAD_VOICE=prophet LEAD_ARP=0
  # SYNTH_CYCLE=0 SYNTH_MORPH=0 STREAM_ROTATE_SYNTH=0` came out of one pass as
  # `stack_soul / 1 / 1 / 1 / 1` — five pins reverted. The re-enabled rotation
  # then moved the pad to `blend` and the re-enabled patch cycle picked
  # rhodes_bleeding_edge/jp8_brass_arp: harsh voices nobody asked for, chosen
  # because the request had been discarded. style_env_write! holds the pin rule.
  DILLA_STYLE_DEFAULTS.each do |key, value|
    style_env_write!(key, value, force:, label: "DILLA_STYLE_DEFAULTS")
  end
  track = ENV["TRACK"].to_s
  track = "pedal_e_descent" if track.empty?
  apply_track_soul_profile!(track, force:)
  apply_concrete_soul_mix!(track)
  reassert_dilla_style_locks! if force
  reassert_pad_lead_locks!
  ensure_learned_engine_seeded!
  apply_learned_env_for_track!(track)
  apply_comfort_style!(force:)
end
alias apply_camel_profile! apply_dilla_style!

def pick_default_track!
  return if ENV["TRACK"] && !ENV["TRACK"].empty?
  mode = ENV["RENDER_MODE"].to_s.downcase
  # Leave TRACK empty for dilla/camel/comfort/empty so DILLA_STYLE_DEFAULTS
  # soft-fill can supply pedal_e_descent. Random deep rotation is for stream
  # after style force, or non-style modes only.
  return if mode.empty? || %w[dilla camel comfort].include?(mode)

  if deep_render?
    pool = stream_track_pool
    seed = Time.now.to_i + Process.pid + (@render_seed || 0)
    ENV["TRACK"] = pool[Random.new(seed).rand(pool.length)]
  else
    ENV["TRACK"] = DillaLofiMachine::DEFAULT_PROFILE.to_s
  end
end

def apply_best_defaults!
  return if ENV["DILLA_RAW"] == "1"
  apply_render_mode!
  soft_fill_env!(DILLA_BEST_DEFAULTS, label: "DILLA_BEST_DEFAULTS")
  soft_fill_env!(DILLA_DEEP_DEFAULTS, label: "DILLA_DEEP_DEFAULTS") if deep_render?
  pick_default_track!
end

def apply_stream_listenability_defaults!
  apply_best_defaults!
  # One engine DNA. Optional mix knobs only (STREAM_COMFORT / RENDER_MODE=warp).
  soft_fill_env!(STREAM_EXTRA_DEFAULTS, label: "STREAM_EXTRA_DEFAULTS")
  if stream_deep?
    ENV["DILLA_DEEP"] = "1" if ENV["DILLA_DEEP"].to_s.empty?
    soft_fill_env!(DILLA_DEEP_DEFAULTS, label: "DILLA_DEEP_DEFAULTS")
  else
    fast = STREAM_FAST_DEFAULTS.dup
    STREAM_ITERATE_OVERRIDE_KEYS.each { |key| fast.delete(key) } if stream_iterate_enabled?
    soft_fill_env!(fast, label: "STREAM_FAST_DEFAULTS")
  end
  soft_fill_iterate!(STREAM_ITERATE_TUNING, locked_keys: DILLA_STYLE_LOCK_KEYS) if stream_iterate_enabled?
  if ENV.fetch("STREAM_SOUL", "1") != "0"
    soft_fill_env!(STREAM_SOUL_DEFAULTS, label: "STREAM_SOUL_DEFAULTS")
  end
  ensure_learned_engine_seeded!
  apply_learned_env_for_track!(ENV["TRACK"]) if ENV["TRACK"] && !ENV["TRACK"].empty?
  normalize_render_mode!
  ENV["RENDER_MODE"] = DEFAULT_RENDER_MODE if ENV["RENDER_MODE"].to_s.empty?
  apply_dilla_style!(force: true)
  # Optional sofa mix knob — not a separate "style".
  force_env!(DILLA_COMFORT_DEFAULTS.reject { |k, _| k.start_with?("SPEAK") }, label: "DILLA_COMFORT_DEFAULTS") if comfort_mode?
  unless comfort_mode?
    # Default: style DNA wins. Creative max only when STREAM_CREATIVE=1 or STREAM_PUNCH=1.
    force_env!(STREAM_STYLE_SAFE, label: "STREAM_STYLE_SAFE")
    if stream_creative_mode?
      force_env!(STREAM_CREATIVE_MAX, label: "STREAM_CREATIVE_MAX")
      force_env!(STREAM_ITERATE_TUNING, label: "STREAM_ITERATE_TUNING") if stream_iterate_enabled?
    elsif stream_iterate_enabled?
      # Mild iterate without wild LUFS/vinyl/LA-beat overrides.
      force_env!(
        STREAM_ITERATE_TUNING.reject do |k, _|
          %w[STREAM_ANALOG_WILD STREAM_ANALOG_EVERY].include?(k)
        end,
        label: "STREAM_ITERATE_TUNING",
      )
    end
  end
  ENV["PLAY_VOL"] = "1" if ENV["PLAY_VOL"].to_s.empty?
  ENV["DILLA_STREAMING"] = "1"
  record_config_provenance!("DILLA_STREAMING", "apply_stream_listenability_defaults!", "force")
end

# --------------------------------------------------------------------------
# engine part: mix_metrics
# --------------------------------------------------------------------------
#
# Mix measurement and the default render path.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# low/mid/high stay at their historical edges so sub_kick_balance and old
# quality sidecars keep the same numbers. body/presence/air are the three
# bands analyze_harshness actually needs (2 kHz and 4 kHz splits).
RENDER_SPECTRUM_BANDS = {
  low: [28, 180],
  body: [180, 2_000],
  mid: [180, 3_500],
  presence: [2_000, 4_000],
  high: [3_500, 16_000],
  air: [4_000, 16_000],
}.freeze

def render_spectrum(path)
  RENDER_SPECTRUM_BANDS.transform_values { |lo, hi| band_rms(path, highpass: lo, lowpass: hi) }
end

# Objective mix meters for piping into MASTER council (not a parallel critique stack).
# Persona panel, multi-solution ideation, and cherry-pick:
#   MASTER /dilla crit [path]  or  /dilla-critique  or  /sound-critique
MIX_METRIC_BANDS = {
  sub_db: [40, 100],
  pad_body_db: [100, 300],
  mids_db: [300, 1200],
  presence_db: [1200, 4000],
  air_db: [4000, 12_000],
}.freeze

# Analysis window, in seconds. Bounded on purpose, and the bound is reported
# back as analysed_sec rather than applied silently: three minutes is a fair
# sample of a mix's band balance, and a 47-minute set is not more truthful,
# only six full decodes more expensive. duration_sec still carries the real
# length so a reader can see both.
MIX_METRIC_WINDOW_SEC = Integer(ENV.fetch("DILLA_MIX_WINDOW_SEC", "180"))

# One asplit, six volumedetects, one decode — overall level plus every band.
# Six separate ffmpeg runs over demo.wav cost 29s; this costs 1.3s.
def mix_metric_command(path, window_sec)
  outlets = (0..MIX_METRIC_BANDS.size).map { |index| "[b#{index}]" }
  chains = ["[b0]#{BAND_FILTER_PREFIX},volumedetect[o0]"]
  MIX_METRIC_BANDS.each_value.with_index(1) do |(low, high), index|
    chains << "[b#{index}]highpass=f=#{low},lowpass=f=#{high},#{BAND_FILTER_PREFIX},volumedetect[o#{index}]"
  end
  maps = (0..MIX_METRIC_BANDS.size).flat_map { |index| ["-map", "[o#{index}]", "-f", "null", "-"] }
  ["ffmpeg", "-hide_banner", "-nostats", "-t", window_sec.to_s, "-i", path,
   "-filter_complex", "[0:a]asplit=#{outlets.size}#{outlets.join};#{chains.join(';')}", *maps]
end

# ffmpeg tags each filter instance with its position in the graph
# (`[Parsed_volumedetect_4 @ 0x…] mean_volume: -31.6 dB`) and prints the
# summaries in reverse order at teardown, so sort by that index rather than
# trusting the order of the lines.
def parse_volumedetect(log)
  readings = {}
  log.scan(/\[Parsed_volumedetect_(\d+)[^\]]*\]\s+(mean|max)_volume:\s*(-?[\d.]+)/) do |index, kind, value|
    (readings[index.to_i] ||= {})[kind.to_sym] = value.to_f
  end
  readings.keys.sort.map { |index| readings[index] }
end

# Objective mix meters for piping into MASTER council (not a parallel critique stack).
# Persona panel, multi-solution ideation, and cherry-pick:
#   MASTER /dilla crit [path]  or  /dilla-critique  or  /sound-critique
def mix_metrics(path)
  return unless path && File.file?(path)
  return unless tool_available?("ffmpeg")

  _out, error, status = capture(*mix_metric_command(path, MIX_METRIC_WINDOW_SEC))
  overall, *bands = status.success? ? parse_volumedetect(error.to_s) : []
  overall ||= {}
  peak_db = overall.fetch(:max, -90.0)
  rms_db = overall.fetch(:mean, -90.0)
  duration = audio_duration_sec(path)
  {
    peak_db:, rms_db:,
    crest: (peak_db > -80 && rms_db > -80) ? (10**((peak_db - rms_db) / 20.0)).round(3) : 0.0,
    duration_sec: duration.round(2),
    analysed_sec: (duration.positive? ? [duration, MIX_METRIC_WINDOW_SEC.to_f].min : MIX_METRIC_WINDOW_SEC.to_f).round(2),
    **MIX_METRIC_BANDS.keys.zip(bands.map { |band| band&.fetch(:mean, nil) || -Float::INFINITY }).to_h,
  }
end

def crit_session_cli!(path = nil)
  path ||= File.join(OUTPUT_DIR, "demo.wav")
  path = File.join(ROOT, "demo.wav") unless File.file?(path)
  abort "crit: missing #{path} — render first, then perfect via MASTER" unless File.file?(path)
  DillaDmesg.boot!(cmd: "crit")
  DillaDmesg.read!(path)
  m = mix_metrics(path)
  DillaDmesg.metrics!(m)
  puts JSON.pretty_generate(m)
  dmesg("meters only — multi-persona cherry-pick via master /dilla crit", unit: "meter0", parent: "dilla0")
  dmesg("master: /dilla crit #{File.basename(path)} or /dilla-critique", unit: "meter0", parent: "dilla0")
  abort "crit: unusable levels" if m[:peak_db].to_f > -0.2 || (m[:rms_db] && m[:rms_db] < -40)
  dmesg("meters ok — run master council to perfect", unit: "meter0", parent: "dilla0")
end

def render_quality_acceptable?(path)
  return true unless quality_gate_enabled?
  return true unless File.file?(path)
  chords = DillaHarmony.last_progression_chords
  beauty = DillaHarmony.score_beauty(chords)
  spectrum = render_spectrum(path)
  harsh = DillaMaster.analyze_harshness(spectrum)
  sk = DillaMaster.sub_kick_balance(spectrum, beauty)
  min_beauty = if ENV["DILLA_STREAMING"] == "1"
                 STREAM_BEAUTY_MIN
               else
                 (ENV["RENDER_BEAUTY_MIN"] || "70").to_f
               end
  beauty_ok = beauty >= min_beauty && !harsh[:needs_notch]
  # A band-limited source cannot be re-rendered into having low end.
  #
  # sub_kick_balance measures low-band minus mid-band dB, and a 78rpm transfer
  # sits about twelve down by construction — there was nothing below 200Hz on
  # the shellac to begin with. Feeding one in as SAMPLE_LOOP therefore failed
  # this gate on every take, and each retry re-rendered a mix whose deficiency
  # came from the source rather than from the mix, so the loop could not
  # converge: measured -12.67 dB, three retries a track, no audio for twenty
  # minutes. Retrying a render to fix the record it sampled is not a gate doing
  # its job, it is a gate asking the wrong question.
  #
  # So the deficit is attributed. If the bed is already past the threshold on
  # its own, the render did not cause it and cannot cure it; the gate says so
  # once and stops blocking. The engine's own bass still carries the low end,
  # and refine_deep_mix_env! still nudges PAD_VOL upward as it always did.
  sub_ok = !(deep_render? && sk[:recommendation] == "boost_sub" &&
             sk[:low_mid_delta].to_f < -9.0 && !sample_bed_band_limited?)
  ok = beauty_ok && sub_ok
  if ok && phone_preview_gate_enabled?
    phone_path = DillaMaster.apply_phone_preview!(path)
    phone_spec = render_spectrum(phone_path)
    phone = DillaMaster.phone_preview_acceptable?(phone_spec)
    unless phone[:ok]
      warn "phone preview gate: mid=#{phone[:mid_db]} dB, low-mid=#{phone[:low_mid_delta]} dB, " \
           "harsh=#{phone[:harshness]} — retrying"
      ok = false
    end
    FileUtils.rm_f(phone_path) if phone_path != path && phone_path.end_with?(".phone.wav")
  end
  unless ok
    unless beauty_ok
      warn "quality gate: beauty=#{beauty} (min #{min_beauty}), harsh=#{harsh[:harshness]} — retrying"
    end
    unless sub_ok
      warn "quality gate: sub=#{sk[:recommendation]} (low-mid #{sk[:low_mid_delta]} dB) — retrying"
    end
  end
  ok
end

def refine_deep_mix_env!(path)
  return unless File.file?(path)
  spectrum = render_spectrum(path)
  beauty = DillaHarmony.score_beauty(DillaHarmony.last_progression_chords)
  sk = DillaMaster.sub_kick_balance(spectrum, beauty)
  changed = false
  if sk[:recommendation] == "boost_sub"
    kg = [(ENV["KICK_GAIN"] || "0.34").to_f + 0.05, 0.48].min
    ENV["KICK_GAIN"] = kg.round(2).to_s
    changed = true
  elsif sk[:recommendation] == "reduce_sub"
    kg = [(ENV["KICK_GAIN"] || "0.34").to_f - 0.04, 0.12].max
    ENV["KICK_GAIN"] = kg.round(2).to_s
    changed = true
  end
  harm_w = (ENV["DEBUG_HARM_WEIGHT"] || "1.68").to_f
  if beauty < 72 && harm_w < 2.0
    ENV["DEBUG_HARM_WEIGHT"] = (harm_w + 0.12).round(2).to_s
    changed = true
  end
  changed
end

def log_render_meta(path)
  chords = DillaHarmony.last_progression_chords
  beauty = DillaHarmony.score_beauty(chords)
  patches = [@render_ep_patch&.dig(:id), @render_warm_patch&.dig(:id)].compact.join("/")
  # Same rule as the "wrote" line: don't name lead patches a silent render never used.
  leads = if lead_arp_enabled?
            [@render_scale_lead_patch&.dig(:id), @render_lead_patch&.dig(:id)].compact.join("+")
          else
            "off"
          end
  prog = chords&.map { |c| c[:name] }&.join(" → ")
  depth = deep_render? ? "deep" : "standard"
  puts "track=#{ENV['TRACK']} mode=#{depth} patches=#{patches || 'native'} pad_arp=#{pad_arp_mode} " \
       "leads=#{leads} beauty=#{beauty}"
  puts "progression: #{prog}" if prog
  puts "quality: ruby dilla.rb beauty #{path}" if File.file?(path)
end

def deep_default_render!(dest, n_bars)
  ensure_external_assets_lazy!
  retries = [(ENV["RENDER_RETRIES"] || "2").to_i, 0].max
  listen_passes = [(ENV["LISTEN_PASSES"] || "0").to_i, 0].max
  (retries + 1).times do |try|
    pick_render_seed! if try.positive?
    render_dilla(dest, n_bars)
    break if render_quality_acceptable?(dest)
    warn "deep render retry #{try + 1}/#{retries + 1}"
  end
  listen_passes.times do |pass|
    break unless refine_deep_mix_env!(dest)
    warn "deep mix refine pass #{pass + 1}/#{listen_passes}"
    pick_render_seed!
    render_dilla(dest, n_bars)
  end
  log_render_meta(dest)
  # Reported unless QUALITY_REPORT=0. Read-only: it measures the file that
  # was written and prints. A measurement nobody asked for is how a
  # drift gets noticed.
  dilla_quality(dest) if ENV["QUALITY_REPORT"] != "0" && File.file?(dest)
end

def default_render!(argv = ARGV)
  dest = if argv[0] && argv[0] =~ /\.(wav|mp3|flac|ogg|m4a|aiff?)\z/i
           argv.shift
         else
           DEFAULT_RENDER_OUTPUT
         end
  n_bars = argv[0]&.match?(/\A\d+\z/) ? argv.shift.to_i : nil
  FileUtils.mkdir_p(File.dirname(dest))
  if deep_render?
    deep_default_render!(dest, n_bars)
  else
    render_dilla(dest, n_bars)
  end
end

# --------------------------------------------------------------------------
# engine part: showcase
# --------------------------------------------------------------------------
#
# The showcase demo and single-track stream playback.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Bare `ruby dilla.rb` (no args, no options) used to mean "continuous live
# stream" -- a `stream()` infinite loop needing afplay/ffplay to real
# speakers, which never terminates and can't run headless/over SSH. Sensible
# default instead: render a short demo.wav that actually showcases the
# engine's range (every named TRACK_PRESETS style, a few bars each,
# concatenated), matching "convention over configuration" -- no ENV knobs
# required to get a real, finite result. `ruby dilla.rb stream` still gives
# the old continuous behavior explicitly for anyone at a machine with speakers.
MEDLEY_DEFAULT_BARS = 4

def medley_styles
  list = if ENV["MEDLEY_STYLES"] && !ENV["MEDLEY_STYLES"].to_s.strip.empty?
           ENV["MEDLEY_STYLES"].split(",").map(&:strip).reject(&:empty?)
         else
           TRACK_PRESETS.keys.map(&:to_s)
         end
  limit = ENV["MEDLEY_LIMIT"]&.to_i
  limit && limit.positive? ? list.first(limit) : list
end

# Each style renders in its own subprocess (mirrors .all_tracks_demo/fill_holes.rb
# and stream()'s own exec-per-track pattern) -- dilla.rb mutates a lot of
# process-global ENV/state per render that isn't guaranteed to reset cleanly
# for a second render in the same process; a fresh interpreter per style sidesteps
# that entirely instead of auditing every mutation site for safety.
def showcase_demo!(dest = File.join(ROOT, "demo.wav"))
  bars = (ENV["MEDLEY_BARS"] || MEDLEY_DEFAULT_BARS.to_s).to_i.clamp(1, 64)
  styles = medley_styles
  dmesg("showcase: #{styles.length} styles x #{bars} bars -> #{File.basename(dest)}", unit: "demo0", parent: "dilla0")
  parts = []
  Dir.mktmpdir("dilla_medley") do |tmp|
    styles.each_with_index do |style, i|
      part = File.join(tmp, format("%03d_%s.wav", i, style))
      env = {
        "PATH" => ENV["PATH"], "HOME" => ENV["HOME"],
        "TMPDIR" => ENV["TMPDIR"], "TMP" => ENV["TMP"], "TEMP" => ENV["TEMP"],
        "GEM_HOME" => ENV["GEM_HOME"], "GEM_PATH" => ENV["GEM_PATH"],
        "BUNDLE_GEMFILE" => ENV["BUNDLE_GEMFILE"], "BUNDLE_PATH" => ENV["BUNDLE_PATH"],
        "RUBYOPT" => ENV["RUBYOPT"], "SSL_CERT_FILE" => ENV["SSL_CERT_FILE"],
        "SPEAK" => "0", "RAP_VOCAL" => "0", "CHOIR_VOX" => "0", "SELF_SAMPLE" => "0",
        "STREAM_CONTINUOUS" => "0", "DILLA_STREAMING" => "0",
        "TRACK" => style, "PROGRESSION" => style, "BARS" => bars.to_s,
      }.compact
      dmesg("showcase [#{i + 1}/#{styles.length}] #{style}", unit: "demo0", parent: "dilla0")
      rendered = false
      timed_out = false
      begin
        Timeout.timeout(ENV.fetch("MEDLEY_TRACK_TIMEOUT", "180").to_i) do
          # unsetenv_others: true -- without it Process.spawn (which Open3
          # delegates to) MERGES env onto the parent's inherited environment
          # rather than replacing it, so anything set for the outer showcase
          # invocation itself (BEAUTY_REPORT, MEDLEY_*, whatever a caller's
          # shell exported) leaks into what's supposed to be an isolated
          # child render. Same class of bug MASTER's own tts-worker spawn
          # path was hardened against.
          _out, status = Open3.capture2e(env, Gem.ruby, ENGINE_FILE, "dilla", part, bars.to_s,
                                          unsetenv_others: true)
          rendered = status.success? && File.file?(part) && File.size(part) > 50_000
        end
      rescue Timeout::Error
        timed_out = true
        dmesg_warn("showcase: #{style} timed out, skipping")
        system("pkill", "-9", "-f", "dilla.rb dilla .*#{Regexp.escape(part)}", out: File::NULL, err: File::NULL)
      end
      if rendered
        parts << part
      elsif !timed_out
        dmesg_warn("showcase: #{style} produced no usable audio, skipping")
      end
    end

    if parts.empty?
      dmesg_warn("showcase: no styles rendered successfully")
      return false
    end

    list_file = File.join(tmp, "concat.txt")
    File.write(list_file, parts.map { |p| "file #{Shellwords.escape(p)}" }.join("\n"))
    FileUtils.mkdir_p(File.dirname(dest))
    system("ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list_file, "-c", "copy", dest,
           out: File::NULL, err: File::NULL)
  end
  ok = File.file?(dest) && File.size(dest) > 0
  dmesg(ok ? "showcase: wrote #{dest} (#{parts.length}/#{styles.length} styles)" : "showcase: failed", unit: "demo0", parent: "dilla0")
  ok
end

# A continuous techno set instead of the hip-hop rotation.
#
# The stream loop renders one track, plays it, moves to the next, forever. That
# is the right shape for a catalogue of progressions and the wrong one for a
# techno set, where the whole point is that it does not stop between pieces.
#
# STREAM_STYLE=techno routes each iteration through render_hate_techno instead,
# and advances a block counter across iterations so the set keeps evolving
# rather than restarting its arrangement every few minutes. Each pass renders a
# few minutes, plays them, and the next pass picks up further along the shape --
# the layer schedule reads a position from 0 to 1, so a stream that has been
# running for an hour is deep into the set rather than back at the intro.
#
# Blocks are rendered a few minutes at a time rather than in one long file so
# playback starts quickly and edits to the engine take effect within one block.
def stream_techno_enabled? = ENV["STREAM_STYLE"].to_s.downcase == "techno"

def stream_techno_block!(index)
  minutes = ENV.fetch("STREAM_TECHNO_MIN", "3").to_f.clamp(0.5, 20.0)
  # Walk the set: each block starts where the previous one left off, wrapping
  # after a full arc so an all-night stream keeps arriving somewhere.
  arc = ENV.fetch("STREAM_TECHNO_ARC", "6").to_i.clamp(2, 40)
  phase = index % arc
  dest = scratch_path("stream_techno_#{index % 2}.mp3")
  prev = ENV["HATE_PHASE"]
  ENV["HATE_PHASE"] = phase.to_s
  ENV["HATE_MIN"] = minutes.to_s
  begin
    dmesg("techno block #{index} — phase #{phase}/#{arc}, #{minutes} min @ #{HATE_BPM.round} BPM",
          unit: "stream0", parent: "dilla0")
    render_hate_techno(dest)
    play_audio(dest)
  ensure
    prev ? ENV["HATE_PHASE"] = prev : ENV.delete("HATE_PHASE")
  end
end

def stream_play_track!(bars_count)
  return stream_techno_block!(@stream_techno_index = (@stream_techno_index || -1) + 1) if stream_techno_enabled?

  timeout = stream_track_timeout_sec
  if timeout
    # play() renders, gates, iterates AND THEN blocks on play_audio for the full
    # length of the track, so wrapping all of it in the render budget meant the
    # budget was being spent on listening as well as working: a 32-bar track is
    # ~81s of playback on top of ~102s of render plus analysis, which overran
    # the 300s budget and killed the track mid-playback -- the stream would
    # start a track, cut it off partway, and log "timed out ... skipping".
    # Playback duration is known and is not work, so add it back; the budget
    # then means what its name says.
    cfg = dilla_resolve_config
    track_sec = (60.0 / cfg[:bpm].to_f) * 4.0 * bars_count.to_i
    Timeout.timeout(timeout + track_sec) { play("dilla", bars_count) }
  else
    play("dilla", bars_count)
  end
end

# --------------------------------------------------------------------------
# engine part: stream_rotation
# --------------------------------------------------------------------------
#
# What the stream plays next: track, drum, voice and arp rotation.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Non-stop: one engine (dilla.rb DNA). Rotates progressions + drums only.
# Ctrl-C to stop. Pin one track: STREAM_LOCK=1 + STREAM_TRACK=…

DILLA_STREAM_PRIORITY = %w[
  pedal_e_descent db_major_minor_fall eb_minor_two_chord e_major_third_rise d_add9_soul_arc
  maj7_minor_cycle alternating_minor7_pair syncopated_slash_ninth
  neo_soul neo_soul_pocket warm_minor_vamp
].freeze

STREAM_HEAD_TRACKS = %w[
  pedal_e_descent
  d_add9_soul_arc
  neo_soul
  neo_soul_pocket
  chromatic_mediant_drift
  baroque
  minor_two_five_chain
].freeze

def stream_progression_order
  all = stream_track_pool.map(&:to_s).uniq
  # Head/priority lists may name tracks outside the active pool (e.g. with
  # DILLA_PROGRESSIONS_ONLY) — never let them reintroduce filtered tracks.
  head = STREAM_HEAD_TRACKS.map(&:to_s).select { |t| all.include?(t) }
  priority = DILLA_STREAM_PRIORITY.select { |t| all.include?(t) && !head.include?(t) }
  rest = all.reject { |t| head.include?(t) || priority.include?(t) }
  head + priority + rest
end

def stream_track_order
  lock = ENV["STREAM_TRACK"] || (ENV["STREAM_LOCK"] == "1" ? ENV["TRACK"] : nil)
  if lock && !lock.to_s.empty? && ENV["STREAM_LOCK"] == "1"
    key = lock.to_s.downcase.tr("-", "_").to_sym
    known = STREAM_TRACKS.include?(key) || DillaLofiMachine.harmony_profile?(key) ||
            TRACK_PRESETS.key?(key)
    return [key] if known
    dmesg_warn("stream unknown lock #{lock} — full rotation")
  end
  stream_progression_order.map(&:to_sym)
end

def stream_drum_rotate_enabled?
  ENV.fetch("STREAM_DRUM_ROTATE", "1") != "0"
end

# Rotate drum grid / pocket / kit after DNA force so beats actually change.
# The curated rotation, then every other kit.
#
# STREAM_DRUM_ROTATION is hand-built combinations of preset, pocket and kit, and
# hand-built for a reason: the pairings matter, and a busy grid under a drunk
# pocket is two kinds of drunk at once. But 62 drum presets exist and the table
# names ten, so 52 never played -- dilla_donuts, dilla_fantastic,
# dilla_lopsided, questlove_pocket, knxwledge_haze, every euclid_* and push_*.
#
# The curated pairings stay first and in order, so a demo of eight still opens
# on the house sound. The tail follows with a pocket chosen from each preset's
# own declared mode rather than at random -- that pairing knowledge is exactly
# what the curated table encodes, and the reason not to shuffle everything.
def drum_rotation_full
  @drum_rotation_full ||= begin
    named = STREAM_DRUM_ROTATION.map { |d| d[:preset] }
    tail = DillaLofiMachine::DRUM_PRESETS.keys.map(&:to_s).sort - named
    STREAM_DRUM_ROTATION + tail.filter_map do |preset|
      spec = DillaLofiMachine::DRUM_PRESETS[preset.to_sym] or next
      pocket = case spec[:mode].to_s
               when /dilla/ then "neo_soul"
               when /straight/ then "classic"
               else "dusty"
               end
      { preset:, pocket:, kit: "03-soulful-vintage",
        wonky: preset.start_with?("wonky") ? "1" : "0" }
    end
  end
end

def stream_rotate_drums!(index)
  return unless stream_drum_rotate_enabled?

  # DRUM_ROTATE_CURATED is separate from DEMO_CURATED_ONLY on purpose: that one
  # also narrows the TRACK list, so asking for the house kit meant giving up
  # most of the catalogue.
  #
  # Why a demo wants it. drum_rotation_full is the 13 hand-built pairings
  # followed by every other preset SORTED BY NAME, and the index walks it
  # straight through. Measured on a 34-slot demo: 31 different presets in 34
  # slots, nothing repeating, and past slot 13 the running order is alphabetical
  # -- afro_clave, boom_808, dembow_lite, then the whole euclid_* and wonky_*
  # runs. Five euclidean grids, a reggaeton dembow and an afro-cuban clave in a
  # hiphop demo, each heard once. Operator verdict: "the drums seem to go
  # without rhythm or purpose", which is what a kit that never repeats sounds
  # like -- no groove survives one encounter.
  #
  # The curated table is 13 entries and deliberately repeats dilla_slight,
  # mpc3000 and dilla_drunk, so over 34 slots a listener hears each pocket
  # several times and it registers as the record's groove.
  curated = ENV["DEMO_CURATED_ONLY"] == "1" || ENV.fetch("DRUM_ROTATE_CURATED", "0") == "1"
  table = curated ? STREAM_DRUM_ROTATION : drum_rotation_full
  d = table[index % table.length]
  ENV["DRUM_PRESET"] = d[:preset]
  ENV["POCKET_SET"] = d[:pocket]
  ENV["EXTERNAL_KIT"] = d[:kit] if d[:kit] && !d[:kit].empty?
  ENV["FM_DRUMS"] = d[:fm] if d[:fm] == "1" && !USER_PINNED_ENV.key?("FM_DRUMS")
  ENV["WONKY_DRUM_OVERLAY"] = d[:wonky] || "0"
  ENV["DRUM_CHOPS"] = "0" unless ENV["FORCE_DRUM_CHOPS"] == "1"
  ENV["ECLECTIC_PERC"] ||= "0"
  ENV["RAW_KICK"] = "1"
  ENV["DRUM_SAMPLE_RAW"] = "1"
  preset = DillaLofiMachine::DRUM_PRESETS[d[:preset].to_sym]
  ENV["SWING"] = preset[:swing].to_s if ENV["STREAM_DRUM_SWING"] == "1" && preset && !USER_PINNED_ENV.key?("SWING")
  ENV["BPM"] = preset[:bpm].to_s if ENV["STREAM_DRUM_BPM"] == "1" && preset&.dig(:bpm)
  @current_external_kit = nil
  record_config_provenance!("DRUM_PRESET", "stream_rotate_drums![#{index}]", "force")
  d
end

# Per-track variety: rotate lead arp mode, lead/pad voice, force true arps + synth cycle.
# Switches the operator set on the command line, captured before any rotation
# or profile runs.
#
# stream_rotate_voices_and_arps! force-sets LEAD_VOICE, LEAD_ARP, SCALE_LEAD,
# HARMONY_LEAD, CREATIVE_LEAD, EXPERIMENTAL_LEADS, LEAD_MORPH and MELODIC_LEAD
# every track. It is guarded by user_lead_locked, but that only becomes true
# when LEAD_VOICE or LEAD_ARP_MODE is set -- so launching with
# `HARMONY_LEAD=0 SCALE_LEAD=0 CREATIVE_LEAD=0 LEAD_ARP=0` and no LEAD_VOICE
# left the guard false and every one of those zeroes was overwritten with a 1
# on the first track. Asking for pads with no leads produced full arps.
#
# Same failure as the track presets overwriting RAP_VOCAL=0: a guard that
# infers intent from one key instead of reading what was actually asked for.
#
# Read from USER_PINNED_ENV rather than re-reading ENV: that constant already
# answers "what did the operator actually ask for", and in a supervisor child it
# answers it correctly. A second raw ENV capture treats the parent's own
# apply_best_defaults! values as operator intent and re-pins them after every
# rotation -- the same laundering the DILLA_USER_PINNED_KEYS declaration exists
# to stop.
STREAM_EXPLICIT_ENV = USER_PINNED_ENV.slice(
  *%w[
    PAD_VOICE PAD_ARP_MODE PAD_LAYERS PAD_VOL
    LEAD_VOICE LEAD_ARP_MODE LEAD_ARP LEAD_FORCE_ARP LEAD_MORPH MELODIC_LEAD
    SCALE_LEAD HARMONY_LEAD CREATIVE_LEAD EXPERIMENTAL_LEADS
    ANALOG_PAD_DETUNE_CENTS
  ]
).reject { |_, v| v.to_s.empty? }.freeze

# What this process tells a child process is genuinely pinned.
#
# Both relaunch paths (the supervisor loop and the mtime exec-restart) declare
# this, and they used to spell it differently -- the supervisor dropped
# DILLA_STREAM* keys, the restart did not -- so a bug could reproduce on one
# restart route and not the other. DILLA_STREAM_LAUNCHED / _SUPERVISOR are this
# file's own plumbing, never operator intent, so they never belong in the pin set.
def dilla_pinned_keys_decl
  USER_PINNED_ENV.keys.reject { |k| k.start_with?("DILLA_STREAM") }.join(",")
end

# One demo slot's pad identity. Two call sites wrote these four keys inline, so
# the rotation and the key list had to be kept in step by hand.
#
# PAD_LAYERS was `ENV["PAD_VOICE"].start_with?("stack_") ? "1" : "1"` -- both arms
# the same value, so the condition never meant anything.
# The outboard chain each demo slot is printed through.
#
# lib/outboard.rb holds seven racks of measured emulations and demo-all was using
# exactly one of them, 86 times -- the same signal path on every track in a demo
# whose entire job is to show range. The pads, arps and voicings already rotate
# per slot (right below); the analog stage did not, so every slot's character
# came from the front of the chain and none from the back.
#
# Rotated on a different modulus to the pad rotation so the two do not lock into
# a repeating pair. 7 racks against DEMO_PAD_ROTATION's length share no factor
# unless that length is a multiple of 7, so the combination walks rather than
# cycles.
#
# RACK is read by the render at dilla.rb's rack resolution and falls back to
# Outboard::DEFAULT_RACK on an unknown name, so a rack removed from the table
# degrades to the default rather than failing the slot.
DEMO_RACK_ROTATION = Outboard::RACKS.keys.map(&:to_s).freeze

def demo_slot_rack(idx)
  DEMO_RACK_ROTATION[idx % DEMO_RACK_ROTATION.length]
end

def demo_slot_pad_env(idx)
  {
    "PAD_VOICE" => DEMO_PAD_ROTATION[idx % DEMO_PAD_ROTATION.length],
    "PAD_ARP_MODE" => DEMO_PAD_ARP_ROTATION[idx % DEMO_PAD_ARP_ROTATION.length],
    "VOICING" => DEMO_VOICING_ROTATION[idx % DEMO_VOICING_ROTATION.length],
    "PAD_LAYERS" => "1",
    "RACK" => demo_slot_rack(idx),
  }
end

# Put the operator's values back after anything that rewrites them.
def restore_explicit_stream_env!
  STREAM_EXPLICIT_ENV.each { |k, v| ENV[k] = v }
end

def stream_rotate_voices_and_arps!(track_index)
  stream_rotate_macros!(track_index)
  return if ENV["STREAM_ROTATE_LEAD"] == "0" && ENV["STREAM_ROTATE_SYNTH"] == "0"
  @stream_iterate_count = (@stream_iterate_count || 0)
  i = track_index + @stream_iterate_count
  if ENV.fetch("STREAM_ROTATE_LEAD", "1") != "0"
    ENV["LEAD_ARP_MODE"] = STREAM_LEAD_ARP_ROTATION[i % STREAM_LEAD_ARP_ROTATION.length].to_s
    ENV["LEAD_VOICE"] = STREAM_LEAD_VOICE_ROTATION[i % STREAM_LEAD_VOICE_ROTATION.length]
    ENV["SCALE_LEAD"] = "1"
    ENV["HARMONY_LEAD"] = "1"
    ENV["CREATIVE_LEAD"] = (i % 2).zero? ? "1" : "0"
    ENV["EXPERIMENTAL_LEADS"] = "1"
    ENV["LEAD_MORPH"] = "1"
    ENV["STREAM_LEAD_MIDI_RICH"] = "1"
    # Louder lead stems so arps cut through pads.
    ENV["HARMONIC_LEAD_ARP_WEIGHT"] = format("%.2f", 1.65 + (i % 5) * 0.05)
    ENV["HARMONIC_LEAD_ARP_VOLUME"] = "1.95"
    ENV["HARMONIC_SCALE_LEAD_WEIGHT"] = "1.25"
    ENV["HARMONIC_SCALE_LEAD_VOLUME"] = "1.55"
  end
  if ENV.fetch("STREAM_ROTATE_SYNTH", "1") != "0"
    ENV["SYNTH_CYCLE"] = "1"
    ENV["SYNTH_MORPH"] = "1"
    ENV["PAD_TEXTURE"] = "1"
    # Mostly held pads; occasional pad figure for variety.
    ENV["PAD_ARP_MODE"] = (i % 5).zero? ? "figure" : "held"
    ENV["PAD_VOICE"] = STREAM_PAD_VOICE_ROTATION[i % STREAM_PAD_VOICE_ROTATION.length]
    # Cycle analog color + sonitex when wild mode on.
    if ENV["STREAM_ANALOG_WILD"] == "1"
      chains = %w[broadcast acetate cassette vinyl_hot summing_phasy lo_fi sp1200]
      ENV["ANALOG_CHAIN"] = chains[i % chains.length]
      soni = %w[donuts_soul donuts_warm vinyl_lab sp1200_crunch]
      ENV["SONITEX"] = soni[i % soni.length]
      ENV["SONITEX_PRESET"] = ENV["SONITEX"]
    end
  end
  # Rotation writes ENV directly. Operator pins captured in STREAM_EXPLICIT_ENV
  # have to win after that, or `LEAD_ARP=0` on the command line still produces
  # full arps — the guard above only looks at STREAM_ROTATE_LEAD, not at what
  # was asked for.
  restore_explicit_stream_env!
  # Clears the patch cache too, so pick_synth_patches! re-rolls for this track.
  pick_render_seed!
end

# Integrated loudness match so every stream track (and vocals) lands at the same level.
def normalize_track_loudness!(path, lufs: nil)
  return path unless path && File.file?(path)
  return path if ENV["DEBUG_NO_LOUDNORM"] == "1"

  # Single-pass loudnorm is a dynamic ride. Measure then apply a static
  # volume= the way normalise_master! already does on the main bus.
  target = (lufs || ENV["STREAM_LUFS"] || ENV["MASTER_LUFS"] || "-16.5").to_f
  previous = ENV["MASTER_LUFS"]
  ENV["MASTER_LUFS"] = target.to_s
  begin
    # Both, and neither is redundant. normalise_master! reads ENV["MASTER_LUFS"]
    # ahead of cfg, so the assignment above is what actually carries the stream
    # target through — but the second argument is not optional, and calling with
    # one raised ArgumentError on every render that reached this line, which is
    # every render: render_dilla:761 -> here -> master_chain:164. The engine
    # could not finish a single track.
    normalise_master!(path, { master_lufs: target })
  ensure
    if previous.nil?
      ENV.delete("MASTER_LUFS")
    else
      ENV["MASTER_LUFS"] = previous
    end
  end
  path
end

# STREAM_MACROS=1 — vary a stream slot by a WORD rather than by six numbers.
#
# Everything else in this file rotates knobs: LEAD_VOICE, LEAD_ARP_MODE,
# HARMONIC_LEAD_ARP_WEIGHT, DRUM_PRESET. That works and it is why the rotation
# reads as a list of assignments -- each slot differs from the last by a handful
# of numbers nobody can hear individually.
#
# DillaMacros exists to say those in musical terms: `dust`, `drift`, `air`,
# `weight`. This walks a small cycle of them so consecutive slots differ by an
# idea instead of by arithmetic, and so the difference is one a listener can
# name. Off by default; the rotation's current behaviour is unchanged without it.
#
# apply! does not overwrite a knob the operator set by hand -- macros are the
# coarse control and an explicit export is the fine one -- so a pinned stream
# stays pinned.
STREAM_MACRO_CYCLE = [
  { dust: 0.25, air: 0.55 },
  { drift: 0.45, density: 0.4 },
  { weight: 0.65, glue: 0.7 },
  { dust: 0.6, drift: 0.3 },
  { density: 0.7, air: 0.35 },
  { chaos: 0.3, drift: 0.55 },
].freeze

def stream_rotate_macros!(track_index)
  return unless ENV["STREAM_MACROS"] == "1"

  settings = STREAM_MACRO_CYCLE[track_index % STREAM_MACRO_CYCLE.length]
  result = DillaMacros.apply!(settings)
  return if result[:applied].empty?

  dmesg("macros: #{settings.map { |k, v| "#{k}=#{v}" }.join(' ')} -> #{result[:applied].join(' ')}",
        unit: "style0", parent: "dilla0")
end

# --------------------------------------------------------------------------
# engine part: demo_catalog
# --------------------------------------------------------------------------
#
# Building the demo catalogue: ordering, titles, and rejecting dead parts.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Pad / arp / voicing pools for demo-all — distinct sonic identity per slot
# (stream DNA alone keeps stack_soul+held+jonas_v and reads as "one song").
# Rhodes / Prophet first — glass/vapor/neon are spice, not the main course.
# The pad voices the demo draws from.
#
# This was fourteen slots naming nine voices, and three of them -- stack_rhodes,
# stack_prophet, stack_soul -- filled more than half. Measured across all 86
# tracks, 13 of the 37 defined pad voices were ever selected and 24 never were,
# including every one of pad_dilla, pad_wonky and pad_royksopp: voices named for
# the producers this engine models, which had never been rendered once.
#
# Widened to reach all of them. The repeats that remain are deliberate -- the
# Rhodes and Prophet stacks are the house sound and should still come up most
# often -- but a catalogue of 86 pieces now draws on 37 voices rather than
# leaning on three.
#
# stack_world, stack_giga, stack_yamaha and stack_vintage are layer stacks
# rather than single voices, so they arrive with their own internal blend; they
# are spaced out rather than clustered, because two thick stacks in consecutive
# slots read as one long stack.
DEMO_PAD_ROTATION = %w[
  stack_rhodes stack_prophet pad_dilla stack_soul rhodes
  pad_wonky prophet stack_glass rhodes_solo stack_vapor
  stack_rhodes pad_madlib moog stack_prophet vintage
  stack_soul pad_royksopp blend stack_yamaha glass
  stack_rhodes fm stack_vintage prophet nylon_soul
  stack_prophet vapor stack_giga crystal stack_fm_epiano
  stack_soul yamaha stack_world ice giga_fm
  stack_rhodes neon supersaw_bed stack_prophet orchestral
  pulse stack_soul vintage_choir stack_rhodes
  harmonica stack_vapor accordion stack_glass yamaha_solo
  stack_soul giga_stack stack_prophet texture
].freeze
DEMO_PAD_ARP_ROTATION = %w[held held wash shimmer held wash figure held].freeze
DEMO_VOICING_ROTATION = %w[
  rootless spread drop2 quartal bill_evans kenny_barron so_what cluster rootless
].freeze

# Every named piece dilla can render, not just the broadcast rotation.
#
# STREAM_ROTATION is the 69-track stream order. It misses two catalogues:
# GENERATED_STYLES (11 generative modes — major_third_cycle_full, negative_harmony,
# tritone_sub … resolved by dilla_progression rather than a CHORD_PROGRESSIONS
# lookup) and four ARTIST_VERIFIED_PROGRESSIONS turnarounds the rotation never
# reaches. Union is 84, and that is what the demo should represent — a demo of
# the stream order alone understates what the engine knows.
#
# DEMO_CATALOG=stream narrows back to the broadcast rotation.
# Every table that decides what the engine can reach, and what it leaves out.
#
# A capability nothing selects is a capability nothing tests, which is how a pad
# patch carried an out-of-range filter value for months without anyone hearing
# it: the voice was defined, no rotation named it, and the broken chain never
# ran. The audit lists what is defined against what is reachable, so that gap is
# a number somebody sees rather than something discovered by ear.
#
# Deliberately reports rather than enforces. A few entries SHOULD be
# unreachable -- a hard-trap kit has no place in this catalogue -- and a check
# that fails the build on those would get switched off. A number that moves
# in the wrong direction is the useful signal.
def capability_surfaces
  {
    "drum presets" => [DillaLofiMachine::DRUM_PRESETS.keys, drum_rotation_full.map { |d| d[:preset] }],
    "pad voices" => [PAD_VOICE_PRESETS.keys + PAD_LAYER_STACKS.keys,
                     DEMO_PAD_ROTATION + STREAM_PAD_VOICE_ROTATION],
    "chord progressions" => [CHORD_PROGRESSIONS.keys, demo_all_order],
    "lead voices" => [(defined?(LEAD_VOICE_PRESETS) ? LEAD_VOICE_PRESETS.keys : []),
                      STREAM_LEAD_VOICE_ROTATION],
    # LEAD_ARP_PRESETS, not ARP_PATTERN_BUILDERS. The rotation holds arp *modes*
    # (wonky_spiral, soul_wash) and the builders are the low-level figures those
    # modes draw from (up, euclidean, rosary) -- two vocabularies that share no
    # key, so the old pairing reported 29 of 29 unreachable no matter what was
    # rotated. The builders are reached at render time by arp_styles unions and
    # rng sampling, which no rotation list can show.
    "lead arp modes" => [(defined?(LEAD_ARP_PRESETS) ? LEAD_ARP_PRESETS.keys : []),
                         STREAM_LEAD_ARP_ROTATION],
    "external kits" => [(defined?(EXTERNAL_DRUM_KITS) ? EXTERNAL_DRUM_KITS : []),
                        drum_rotation_full.map { |d| d[:kit] }],
    "sample loops" => [TRACK_SAMPLE_LOOPS.keys, demo_all_order],
  }
end

def capability_audit!
  total_missing = 0
  puts format("  %-22s %8s %10s %6s", "surface", "defined", "reachable", "gap")
  capability_surfaces.each do |label, (defined_keys, reachable_keys)|
    d = defined_keys.map(&:to_s).uniq
    r = reachable_keys.map(&:to_s).uniq
    missing = (d - r).sort
    total_missing += missing.length
    puts format("  %-22s %8d %10d %6d", label, d.length, d.length - missing.length, missing.length)
    puts "      #{missing.first(24).join(' ')}#{missing.length > 24 ? " …+#{missing.length - 24}" : ''}" unless missing.empty?
  end
  puts
  puts total_missing.zero? ? "  every defined capability is reachable" : "  #{total_missing} unreachable"
  true
end

def demo_all_order
  # An explicit list wins over every other rule here — it is how demo-quick asks
  # for a sample of the catalogue, and an operator naming tracks means it.
  named = ENV["DEMO_TRACKS"].to_s.split(",").map(&:strip).reject(&:empty?)
  return named.map(&:to_sym) unless named.empty?

  locked = stream_track_order
  # STREAM_LOCK pinned a single track — honour it rather than expanding.
  return locked if locked.length <= 1
  # DEMO_CATALOG=stream reproduces what the broadcast would actually play,
  # including any DILLA_PROGRESSIONS_ONLY filtering.
  return locked if ENV["DEMO_CATALOG"].to_s.strip.downcase == "stream"

  # Deliberately STREAM_TRACKS and not stream_track_order: the latter runs
  # through stream_track_pool, which DILLA_PROGRESSIONS_ONLY narrows to the
  # Dilla-produced handful. That is right for a broadcast and wrong for a
  # catalogue demo, which should show everything the engine knows regardless
  # of what the stream is currently filtered to.
  curated = demo_curated_order

  # ...and then everything else, which is most of it.
  #
  # The note above says this list "should show everything the engine knows", and
  # it did not. Those three sources union to 86 entries. CHORD_PROGRESSIONS holds
  # 250. Measured, 209 progressions could never appear in a catalogue demo --
  # gospel_walk_up, neapolitan_door, lament_ground, hexatonic_pole_shiver, every
  # eight_bar_* arc, both whole_tone entries. The engine knew them and no demo
  # ever played one, which is a large part of why eight tracks drawn from the
  # same 41 sounded like each other.
  #
  # Curated first, so the order of the front of the catalogue is unchanged and
  # DEMO_TRACKS/demo-quick still sample the good stuff first. The tail is sorted
  # rather than shuffled: a catalogue should be in a stable order so a track you
  # heard yesterday is in the same place today.
  #
  # DEMO_CURATED_ONLY=1 restores the old 86 for anyone who wants those.
  return curated if ENV["DEMO_CURATED_ONLY"] == "1"

  # The sampled beds go in too, and they are the reason this matters.
  #
  # TRACK_SAMPLE_LOOPS entries are track names: name one as TRACK and the loop
  # plays underneath the arrangement on its own bus. All twelve were unreachable
  # from any demo -- the four hand-cut records and the eight cut from the Sheger
  # broadcast by `chop`, which was built this session precisely so the engine
  # could make beats out of them. It could, and no demo ever did.
  loops = TRACK_SAMPLE_LOOPS.keys.map(&:to_sym).sort
  tail = (CHORD_PROGRESSIONS.keys.map(&:to_sym).sort - curated - loops)
  (curated + loops + tail).uniq
end

# The crate opens the demo. Its three sources below union to 86 entries and
# not one of them is a sampled track, so a demo of what this engine does
# played 86 synthesised pieces and never put on a record -- the one thing it
# does that a synthesiser cannot.
#
# Only records whose loop is on disk. TRACK_SAMPLE_LOOPS names five and four
# of them are currently missing their audio; listing a record with no file
# buys a failed slot or a silence placeholder in the middle of a demo. This
# reads the disk so restoring a loop is the whole of putting it back in.
def demo_sampled_order
  lead = :semua_untuk_mu
  present = TRACK_SAMPLE_LOOPS.select { |_, spec| File.file?(spec[:path].to_s) }.keys
  ([lead] & present) + (present - [lead])
end

# The curated head of the catalogue, on its own. Named because three places want
# it: demo_all_order builds from it, DEMO_CURATED_ONLY returns it, and the help
# text has to be able to say how big it is without guessing.
def demo_curated_order
  base = STREAM_TRACKS.map(&:to_sym)
  extra = GENERATED_STYLES.map(&:to_sym) + ARTIST_VERIFIED_PROGRESSIONS.keys.map(&:to_sym)
  (demo_sampled_order + base + extra).uniq
end

# Catalogue sizes, derived rather than written down.
#
# Both counts in the help text were stale, and not by a little: it advertised
# "84 named pieces" for a default catalogue that had grown to 307, and a
# "69-track stream rotation" that was 205. The numbers were right when they were
# typed and nothing recomputed them when the pools grew -- the same shape as
# every other hardcoded count in this tree.
#
# It is worth deriving because the number IS the cost. demo-all at 70s a track is
# 1.7 hours at 86 and 6 hours at 307, and an operator choosing between them off
# the help text was choosing off numbers four times wrong.
#
# The :all and :curated counts read no ENV, deliberately. demo_all_order honours
# DEMO_TRACKS/DEMO_CATALOG/DEMO_CURATED_ONLY, which is right for a render and
# wrong for a help screen -- `DEMO_CATALOG=stream ruby dilla.rb help` should
# still report what the default catalogue costs. :stream goes through
# stream_track_order and therefore does follow STREAM_LOCK and any progression
# filter, because that is the honest answer to "what would DEMO_CATALOG=stream
# render for me", which is the question the help line is answering.
def demo_catalog_sizes
  curated = demo_curated_order
  loops = TRACK_SAMPLE_LOOPS.keys.map(&:to_sym)
  tail = CHORD_PROGRESSIONS.keys.map(&:to_sym) - curated - loops
  {
    all: (curated + loops + tail).uniq.length,
    curated: curated.length,
    stream: stream_track_order.length,
  }
end

# The mp3 is the artifact worth tracking. A full-catalogue WAV runs to hundreds
# of megabytes and git keeps it forever; at 192kbps the same audio is a few
# megabytes and still reviewable. The WAV stays on disk as the working master
# and is not tracked.
#
# DEMO_MP3=0 skips the encode; DEMO_MP3_BITRATE overrides 128k.
def demo_encode_mp3(wav)
  return nil if ENV.fetch("DEMO_MP3", "1") == "0"
  return nil unless File.file?(wav)

  mp3 = wav.sub(/\.wav\z/i, "") + ".mp3"
  # 128k, not 192k, because demo.mp3 is committed and GitHub's hard per-file push
  # limit is 100 MB with no LFS available here. The curated 86-track catalogue is
  # 71 minutes, which is 102 MB at 192k -- over the limit, rejected at push, and
  # discovered only after an hour of rendering. It is 68 MB at 128k.
  #
  # This is the one encode setting in the file chosen by a constraint outside the
  # audio. Raise it for a WAV you are keeping locally, not for the tracked demo,
  # and re-measure if the catalogue or the bar count grows.
  bitrate = ENV.fetch("DEMO_MP3_BITRATE", "128k")
  begin
    sh! "ffmpeg", "-y", "-i", wav, "-codec:a", "libmp3lame", "-b:a", bitrate, mp3
  rescue StandardError => e
    dmesg_warn("demo mp3 encode failed: #{e.message}")
    return nil
  end
  return nil unless File.file?(mp3) && File.size(mp3) > 10_000

  mp3
end

# Render every catalogue progression into one demo.wav (resumable), then encode
# the tracked demo.mp3 beside it.
# Usage: ruby dilla.rb demo-all [bars] [out.wav]
#   DEMO_FORCE=1 re-render even if part exists
#   DEMO_CREATIVE=1 (default) rotate pads/leads/MIDI/analog + sparse rap so chords read
#   DEMO_TRACK_TIMEOUT=300 max seconds per track (creative stacks need headroom)
#   DEMO_RAP_EVERY=4 rap only every Nth track (0 = never; 1 = always)
#   DEMO_CATALOG=stream restrict to the stream rotation; DEMO_CURATED_ONLY=1 the
#     curated head only. Sizes are in demo_catalog_sizes -- do not write them here,
#     the two that used to live in this file drifted to 4x wrong.
#   DEMO_MP3=0 skip the mp3; DEMO_MP3_BITRATE=192k
# One file per track instead of one 48-minute concat.
#
# The parts already existed -- demo_all has always rendered each track separately
# and then glued them together -- but they landed in scratch/ under a name nobody
# would look for, as WAV, and DEMO_FORCE deleted them. Culling a catalogue means
# playing a track, deciding, and deleting the file, and that needs the files to
# be findable, small, and named after the track.
#
# So: demos/NN_slug.mp3, kept, resumable, no concat. Delete the ones that miss
# and re-run -- the survivors are skipped and only the gaps re-render.
def demo_each? = ENV["DEMO_EACH"] == "1"

# The dilla root, beside dilla.rb, not a subfolder. Same argument the scratch/
# note in .gitignore already makes: generated audio should be findable by anyone
# looking at the tree. Only the mp3s land here -- order.txt, catalog.txt and the
# run log stay in scratch, because those are bookkeeping and this directory is
# meant to be a listening queue.
DEMO_EACH_DIR = ROOT
DEMO_EACH_MANIFEST = File.join(ROOT, "demo_manifest.tsv")

# Each track gets its own pinned seed, written into the manifest beside it.
#
# This is what makes "weed out the bad seeds" a real operation rather than a
# figure of speech: a track you like has a number next to it, and a track you
# do not can be re-rolled by bumping only that number. DEMO_SEED sets the base.
#
# Read the caveat in the manifest header before trusting a recorded seed to
# reproduce a take. Pinning is necessary here and is not yet sufficient: two
# renders with RENDER_SEED fixed are still not bit-identical, so a seed narrows
# a take down rather than reconstructing it.
def demo_each_seed(idx) = (ENV["DEMO_SEED"] || "4242").to_i + idx

# Our own titles.
#
# The internal names describe the harmony -- two_chord_hypnosis, dorian_iv_loop
# -- and a fair few were taken from the records the progression was studied
# from. Those are somebody else's titles on our tracks, so the files that come
# out of here get names of their own.
#
# Deterministic, not random at render time: the same track gets the same title
# every run, so a file you kept still matches its row in the manifest after a
# re-render. The manifest carries both names, because the internal slug is still
# how you render the thing again.
DEMO_TITLE_FIRST = %w[
  amber ash blue brass cedar clay copper dusk ember fern flint glass grain
  gravel harbour hollow indigo iron ivory lantern linen marrow mercury moss
  nickel ochre onyx paper pewter quartz river rust saffron salt shale silt
  slate smoke solder stone tallow tide tin umber velvet vellum willow
].freeze
DEMO_TITLE_SECOND = %w[
  arc bloom braid channel circuit corridor current drift ferry field figure
  gate ghost harvest hinge hour ladder lantern letter margin meridian mile
  motion orbit parlour passage pattern pier quarter relay ribbon room season
  shelf signal span station stitch switch table thread tower turn valley
  wander watch weather window
].freeze

# Is this slot a techno track or a hip-hop one?
#
# The engine has two renderers now and a demo that only ever shows one of them
# is only half a demo. Which slot gets which is decided by a coin flip -- but a
# SEEDED one, keyed on the track name and the demo seed, so the same catalogue
# comes out the same way twice and a file you kept still matches its manifest
# row. Random at render time would mean re-running the demo silently reshuffled
# what you had already listened to.
#
# DEMO_TECHNO_SHARE is the proportion, defaulting to a third: enough that a run
# of eight lands two or three of them, few enough that the demo still reads as a
# catalogue of the progressions rather than a techno set with interruptions.
# 0 renders everything as hip-hop, 1 as techno.
def demo_techno_share = ENV.fetch("DEMO_TECHNO_SHARE", "0.34").to_f.clamp(0.0, 1.0)

# Does slot idx carry a rapper?
#
# DEMO_RAP_EVERY only reaches "every slot" (1) or "every other" (2) and has
# nothing between them, so a demo that wants a rapper on most tracks and the
# harmony naked on a few could not be asked for at all.
# DEMO_INSTRUMENTAL_EVERY holds every Nth slot back on top of whatever
# rap_every decided.
#
# Off by default (0), so no existing demo changes. The instrumental lands at the
# END of each group of N, not the start, so slot 0 still opens with a voice.
def demo_rap_slot?(idx, rap_every)
  return false unless rap_every.positive?
  return false unless (idx % rap_every).zero?

  every = ENV.fetch("DEMO_INSTRUMENTAL_EVERY", "0").to_i
  return true unless every.positive?

  (idx % every) != every - 1
end

def demo_techno_slot?(idx, slug)
  share = demo_techno_share
  return false if share <= 0.0

  # A track carrying a sampled bed is a techno slot only when techno can carry
  # the bed.
  #
  # render_hate_techno used to build its arrangement from scratch and never call
  # sample_loop_for, so reassigning one of these handed back a techno piece with
  # the record silently absent -- at the 0.34 default, a third of every hand-cut
  # and chopped loop, with nothing in the log to distinguish a dropped sample
  # from a played one. It now takes the bed as a layer under TECHNO_HARMONY, so
  # the exemption is scoped to the case that still loses it rather than left
  # standing as a permanent rule. That is the whole point: a sampled record
  # SHOULD be able to become a techno track.
  #
  # Checked before the share >= 1.0 shortcut, so DEMO_TECHNO_SHARE=1 still means
  # "every slot that CAN be techno", not "lose every sample".
  unless techno_harmony_enabled?
    key = slug.to_s.downcase.tr("-", "_").to_sym
    return false if TRACK_SAMPLE_LOOPS.key?(TRACK_SAMPLE_LOOP_ALIASES.fetch(key, key))
  end

  return true if share >= 1.0

  seed = stable_hash("techno:#{slug}") + (ENV["DEMO_SEED"] || "4242").to_i + idx
  (seed % 1000) < (share * 1000).round
end

def demo_title(slug, idx)
  # Two independently salted hashes, not one hash divided.
  #
  # Taking the second word from `seed / FIRST.length` ties it to the first: djb2
  # over near-identical inputs returns near-identical values, so a run of slugs
  # that differ by one character lands in the same quotient bucket. Rendering
  # the eight Sheger chops produced shale_mile, slate_mile, solder_mile,
  # tallow_mile, tin_mile, velvet_mile, willow_mile -- seven titles, one word.
  # Salting the two draws differently decorrelates them.
  base = "#{slug}:#{ENV['DEMO_SEED'] || '4242'}:#{idx}"
  first = DEMO_TITLE_FIRST[stable_hash("first:#{base}") % DEMO_TITLE_FIRST.length]
  second = DEMO_TITLE_SECOND[stable_hash("second:#{base}") % DEMO_TITLE_SECOND.length]
  "#{first}_#{second}"
end

# True when every part carries the same codec, which is the one thing the concat
# demuxer requires and the one thing it will not check. It probes the FIRST input
# only and assumes the rest match, so a single odd part is copied through as if it
# were the format of part 1.
# Level every part to one target before the demo is assembled. On by default.
#
# The demo was not loud in the wrong places, it was TWO RECORDS. Measured across
# 42 rendered parts: the hip-hop slots sit at -18.7 LUFS with about 9 LU of range
# and -8 dBFS peaks, and the techno slots at -12.5 LUFS with 24 LU of range and
# -2.2 dBFS peaks. 6.2 dB apart, alternating, for 71 minutes. The hip-hop tracks
# were already tightly levelled against each other -- the entire spread was that
# one seam.
#
# DEMO_ALBUM_NORM does not fix this and cannot. It normalises the finished
# concatenation, which moves the whole thing together and preserves every gap
# inside it. That is the right behaviour for an album, where the quiet track is
# quiet on purpose, and the wrong layer entirely for a catalogue demo where the
# difference between two tracks is an artefact of which renderer drew them.
# Levelling has to happen per part, before they are joined.
#
# normalize_track_loudness! is reused rather than reinvented: its LRA=11 ceiling
# is the half that matters most here, because the techno slots' problem is as
# much the 24 LU range as the level, and a gain change alone would leave that.
def demo_level_parts?
  ENV.fetch("DEMO_LEVEL", "1") != "0"
end

# Normalised copies, in a temp directory -- the cached parts in out_dir are never
# touched. Two reasons, and the second is the one that bites: demo-all is
# resumable, so mutating parts in place would re-level an already-levelled part
# on every resume, and levelling is not quite idempotent (each pass re-measures
# and re-limits). Copies also mean a failed run leaves the expensive renders
# intact.
#
# Decoding each part separately is what makes this safe for mixed codecs too, so
# this path needs no uniformity check -- it IS the uniformity fix.
# Measure what "ok" never looked at: is there audio in the file, and is it as
# long as its neighbours. Returns the suspects; the caller decides.
#
# Both thresholds are relative to the median of the parts themselves. An absolute
# floor would be wrong twice over -- it would fire on a demo that is quiet by
# choice, and it would miss a whole render that came out uniformly thin. What is
# never intentional is one track sitting 25 dB under the ones beside it.
#
# Median and not mean, because the failure this exists to catch put 28 silent
# parts into 86. A mean would have been dragged down toward them; the median of
# that set was still a healthy -21 dB.
def demo_suspect_parts(parts)
  measured = parts.filter_map do |p|
    next unless File.file?(p)
    out = Open3.capture2e("ffmpeg", "-hide_banner", "-i", p, "-af",
                          "astats=metadata=1:reset=0", "-f", "null", "-").first
    # astats prints "-inf" for a digitally silent file, and the obvious
    # /(-?[\d.]+)/ does not match it -- so the first version of this returned nil
    # there and `next if rms.nil?` dropped the file from the set entirely. A
    # check for silence that skips anything perfectly silent. Caught by feeding
    # it an anullsrc probe, which it passed clean.
    raw = out[/RMS level dB:\s*(-?(?:[\d.]+|inf))/, 1]
    next if raw.nil?
    rms = raw == "-inf" ? -120.0 : raw.to_f
    dur = Open3.capture2e("ffprobe", "-v", "error", "-show_entries", "format=duration",
                          "-of", "default=nw=1:nk=1", p).first.to_f
    { path: p, rms: rms, dur: dur }
  end
  return [] if measured.length < 3

  mid = lambda { |vals| s = vals.sort; s[s.length / 2] }
  med_rms = mid.call(measured.map { |m| m[:rms] })
  med_dur = mid.call(measured.map { |m| m[:dur] })
  measured.filter_map do |m|
    quiet = m[:rms] < med_rms - 20
    short = med_dur.positive? && m[:dur] < med_dur * 0.4
    next unless quiet || short
    reason = [quiet ? "#{m[:rms].round(1)}dB vs median #{med_rms.round(1)}" : nil,
              short ? "#{m[:dur].round(1)}s vs median #{med_dur.round(1)}" : nil].compact.join(", ")
    { path: m[:path], reason: reason }
  end
end

# Absolute, not relative: a file whose peak never leaves the noise floor carries
# no signal at any playback level, so no demo can want it. -70 dBFS peak is two
# orders of magnitude below the quietest real part measured here (-7.5 dB peak
# on a retry-minimal render) and comfortably above a true digital zero's -91.0,
# so it separates dead from merely quiet without judgement.
DEAD_PART_PEAK_DBFS = -70.0

def demo_part_dead?(path)
  out, status = Open3.capture2e("ffmpeg", "-hide_banner", "-nostats", "-i", path,
                                "-af", "volumedetect", "-f", "null", "-")
  # A file ffmpeg cannot measure is not provably dead, and this runs after hours
  # of rendering: keep it and let demo_report_suspect_parts name it instead.
  return false unless status.success?

  peak = out[/max_volume:\s*(-?\d+(?:\.\d+)?)\s*dB/, 1]
  return false if peak.nil?

  peak.to_f <= DEAD_PART_PEAK_DBFS
end

def demo_reject_dead_parts(parts)
  dead, alive = parts.partition { |p| demo_part_dead?(p) }
  return parts if dead.empty?

  dmesg_warn("join: dropping #{dead.length} dead part(s) — no signal above #{DEAD_PART_PEAK_DBFS} dBFS")
  dead.each { |p| dmesg_warn("  #{File.basename(p)}") }
  # Never hand back an empty list: joining nothing writes a zero-length file that
  # every downstream step accepts. If they are all dead, that is the fault, and
  # the caller should fail loudly on the join rather than silently on the output.
  alive.empty? ? parts : alive
end

# Name them in the log and in the closing summary. Deliberately a warning and not
# an abort: this runs after hours of rendering, and killing the run would throw
# away 80 good parts to punish six bad ones. Deleting the named files and
# re-running fills exactly those gaps, which is what the resume is for.
def demo_report_suspect_parts(parts)
  suspects = demo_suspect_parts(parts)
  return suspects if suspects.empty?

  dmesg_warn("verify: #{suspects.length}/#{parts.length} parts look wrong — delete these and re-run to refill")
  suspects.each { |s| dmesg_warn("  #{File.basename(s[:path])}: #{s[:reason]}") }
  suspects
end

def demo_parts_uniform?(parts)
  codecs = parts.map do |p|
    out, status = Open3.capture2e("ffprobe", "-v", "error", "-select_streams", "a:0",
                                  "-show_entries", "stream=codec_name",
                                  "-of", "default=nw=1:nk=1", p)
    status.success? ? out.strip : "unknown"
  end
  codecs.uniq.length <= 1
end

# Join the parts into one wav. `-c copy` is worth keeping -- it is near-instant on
# 84 tracks where a re-encode is minutes -- but it cannot be trusted on its own,
# because on a codec mismatch it does not fail. It writes the wrong stream into a
# WAV container and exits 0, so the rescue that used to guard this never fired and
# the demo shipped a file that opens nowhere. Check the parts first, then copy.
# Crossfade the parts into one piece rather than butting them together.
#
# The concat demuxer joins sample to sample. That is right for one recording cut
# into parts and wrong for eighty-six separate pieces in eighty-six keys: every
# join is a hard edge, and a demo meant to be listened through end to end reads
# as a folder of clips instead.
#
# This is album_stitch's graph applied to the demo's parts -- the same 1.5s
# tri/tri curves and the same limiter ceiling, for the same reason. A crossfade
# sums two tracks, so the overlap peaks above whatever either part reached alone.
#
# DEMO_CROSSFADE=0 restores the butt-splice.
def demo_crossfade_parts!(parts, out, seconds)
  graph = +""
  previous = "[0:a]"
  (1...parts.length).each do |i|
    label = i == parts.length - 1 ? "[x]" : "[a#{i}]"
    graph << "#{previous}[#{i}:a]acrossfade=d=#{seconds}:c1=tri:c2=tri#{label};"
    previous = label
  end
  ceiling = 10**((ALBUM_TARGET_TP - ALBUM_ENCODER_HEADROOM) / 20.0)
  graph << "[x]alimiter=limit=#{ceiling}:level=disabled[out]"

  # A script file, not an argument: eighty-five chained filters is tens of
  # kilobytes of graph, and it is the one argument that grows with the catalogue.
  script = File.join(Dir.tmpdir, "demo_graph_#{Process.pid}.txt")
  File.write(script, graph)
  begin
    sh! "ffmpeg", "-y", "-loglevel", "error", *parts.flat_map { |p| ["-i", p] },
        "-filter_complex_script", script, "-map", "[out]",
        "-c:a", "pcm_s16le", "-ar", SAMPLE_RATE.to_s, "-ac", "2", out
  ensure
    FileUtils.rm_f(script)
  end
  dmesg("join: #{parts.length} parts, #{seconds}s crossfades", unit: "demo0", parent: "dilla0")
  DillaProvenance.record_assembly!(
    out, parts:,
    how: "#{seconds}s tri crossfades, limited to #{(ALBUM_TARGET_TP - ALBUM_ENCODER_HEADROOM).round(2)} dBTP",
  )
  out
end

def demo_join_parts!(parts, list, out)
  level = demo_level_parts?
  xfade = ENV.fetch("DEMO_CROSSFADE", ALBUM_XFADE.to_s).to_f
  return demo_crossfade_parts!(parts, out, xfade) if xfade.positive? && parts.length > 1

  # The fast path, and the only one that avoids touching 86 files: hand the
  # caller's list straight to the concat demuxer and copy. It is legal only when
  # nothing needs per-part work AND the parts already agree on a codec, because
  # the demuxer probes part 1 and applies that decoder to every later part --
  # one mp3 among the wavs and it copies mp3 packets into a WAV container and
  # exits 0. Both conditions, or decode each part on its own below.
  if !level && demo_parts_uniform?(parts)
    sh! "ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list, "-c", "copy", out
    DillaProvenance.record_assembly!(out, parts:, how: "concat demuxer, stream copy, no levelling")
    return out
  end

  # One body for both remaining reasons to walk the parts -- levelling them, and
  # rescuing a codec mismatch -- because they were the same fifteen lines twice,
  # differing by the normalize call. Re-encoding through the concat demuxer does
  # NOT rescue a mismatch, which is the trap worth naming: the demuxer still
  # probes part 1, so a pcm part read as mp3 yields "Header missing" per packet
  # and silence where the audio was. Measured, not assumed.
  target = ENV.fetch("DEMO_LEVEL_LUFS", "-16.5").to_f
  if level
    dmesg("level: #{parts.length} parts -> #{target} LUFS", unit: "demo0", parent: "dilla0")
  else
    dmesg_warn("concat: parts are not one codec, decoding #{parts.length} before joining")
  end
  Dir.mktmpdir("dilla_join") do |tmp_dir|
    prepared = parts.each_with_index.map do |p, i|
      dst = File.join(tmp_dir, format("%03d.wav", i))
      sh! "ffmpeg", "-y", "-loglevel", "error", "-i", p,
          "-c:a", "pcm_s16le", "-ar", SAMPLE_RATE.to_s, "-ac", "2", dst
      normalize_track_loudness!(dst, lufs: target) if level
      dst
    end
    joined = File.join(tmp_dir, "concat.txt")
    File.write(joined, prepared.map { |p| "file '#{p}'" }.join("\n") + "\n")
    sh! "ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", joined, "-c", "copy", out
  end
  # The ORIGINAL parts, not the levelled temporaries -- those live in a tmpdir
  # that is gone by the time anyone reads this, and naming them would record a
  # tracklist of paths that never existed outside one process. The levelling is
  # in `how` instead, which is the part worth knowing.
  DillaProvenance.record_assembly!(
    out, parts:,
    how: level ? "decoded per part, levelled to #{target} LUFS, then concat" : "decoded per part, then concat"
  )
  out
end

# --------------------------------------------------------------------------
# engine part: album_signature
# --------------------------------------------------------------------------
# The record, not the beat.
#
# Operator direction: "every single beat should carry the same sonic texture so
# everybody knows its part of our own planned debut album", explained as
# parametric architecture -- buildings with different shapes that still read as
# one superstructure. So the album is two tables and not one.
#
# ALBUM_SIGNATURE is the superstructure: the kit, the saturation, the lead
# weight and the master chain that every beat on the record shares. It is
# FORCED, per slot, immediately before the render. A soft fill is not enough
# here and the reason is mechanical: stream_rotate_drums! writes EXTERNAL_KIT,
# RAW_KICK and DRUM_SAMPLE_RAW on every single iteration, and the lead rotation
# writes nine more keys after that. Anything filled once at the top of demo_all
# is taken straight back off before the first part renders -- the same silent
# no-op demo_all's own steady-mode comment describes.
#
# album_slot_env is the shape. The grade changes on every beat, the device layer
# and the sampled bed on their own periods, so no two beats pair the same grade
# with the same bed and the same devices.
#
# The tone values are not repeated here. They live in RENDER_MODE_DEFAULTS
# [:album] in style_defaults.rb, which is what `RENDER_MODE=album` fills for a
# single render, and this reads that same table. One source: a beat rendered by
# hand with RENDER_MODE=album and a beat rendered as part of the record carry
# the same signature by construction rather than by two tables agreeing.

# What RENDER_MODE=album says about the run rather than about the sound. Bars,
# stems and whether a composition session drives the arrangement belong to
# whoever started the render -- demo_all is already passing its own bars count
# down, and forcing the table's 16 over it would silently ignore the argument.
ALBUM_RUN_SHAPE_KEYS = %w[BARS COMPOSITION KEEP_STEMS STEM_EXPORT].freeze

# The sampled bed the record opens on. A slug, resolved through
# TRACK_SAMPLE_LOOPS, so it keeps the measured hp/sub_db/lp for that loop.
ALBUM_BED = ENV.fetch("ALBUM_BED", "semua_untuk_mu")

# One period per dimension. Three, four and thirteen share no factor, so the
# bed, the devices and the grade come back into phase only every 156 beats --
# longer than any record -- and a listener never hears the same three together
# twice.
ALBUM_BED_EVERY = 3
ALBUM_DEVICE_EVERY = 4

def album_enabled? = ENV.fetch("ALBUM", "1") != "0"

# The knobs that make it this record.
def album_signature_env
  table = RENDER_MODE_DEFAULTS[:album] or return {}
  table.reject { |key, _| ALBUM_RUN_SHAPE_KEYS.include?(key) }
end

# A grade per beat, which is the whole of the operator's "completely change
# sonitex preset for each new chord progression".
#
# Both spellings are written. SONITEX_PRESET is the internal key the style
# tables use and sonitex_resolve_preset reads it first; SONITEX alone would lose
# to whichever preset a style had already forced, and a grade that silently does
# not change is indistinguishable from one that does not exist.
def album_grade_for(idx)
  presets = SONITEX_PRESETS.keys
  return {} if presets.empty?

  name = presets[idx % presets.length].to_s
  { "SONITEX_PRESET" => name, "SONITEX" => name }
end

# The wav-map needs a real image on disk.
#
# wav_map_layer! returns nil unless File.file? holds for WAV_MAP, so a knob set
# to a shape name -- which is what WAV_MAP_PATH takes -- produces no layer, no
# error and a beat that is missing a stage the log said it had. The record
# carries its own source image instead of depending on one that may not be
# checked out, generated once per run into scratch.
def album_wav_map_image
  dest = File.join(SCRATCH_DIR, "album_wavmap.png")
  return dest if File.file?(dest) && File.size(dest) > 1024

  FileUtils.mkdir_p(SCRATCH_DIR)
  sh! "ffmpeg", "-y", "-loglevel", "error", "-f", "lavfi",
      "-i", "mandelbrot=size=512x512:maxiter=400", "-frames:v", "1", dest
  File.file?(dest) ? dest : nil
rescue StandardError => e
  dmesg_warn("album wav-map image: #{e.message}")
  nil
end

# What varies, per beat.
#
# Every key this can set is set on every call, including to its off value. ENV
# is one table for the whole of a demo run, so a bed switched on at slot 3 is
# still on at slot 4 unless slot 4 says otherwise, and "every third beat carries
# the record" would render as "every beat from the third onward does".
#
# The bed's off value is "" and not "0": empty means the track picks its own bed
# from TRACK_SAMPLE_LOOPS, which several progressions do, and "0" would take
# those away as well.
def album_slot_env(idx)
  env = album_grade_for(idx)

  bed = ((idx + 1) % ALBUM_BED_EVERY).zero? && album_bed_available?
  env["SAMPLE_LOOP"] = bed ? ALBUM_BED : ""

  devices = ((idx + 1) % ALBUM_DEVICE_EVERY).zero?
  image = devices ? album_wav_map_image : nil
  if image
    env.merge!("COPY_MACHINE" => "6", "WAV_MAP" => image, "WAV_MAP_PATH" => "spiral",
               "DILLA_MIX_BUSES" => "1", "BUS_MOD_SYNC" => "1/8")
  else
    env.merge!("COPY_MACHINE" => "0", "WAV_MAP" => "", "DILLA_MIX_BUSES" => "0")
  end

  env
end

# The bed is audio, and audio is not in git. A record that names a loop nobody
# has checked out fails the asset check and renders nothing at all, so the beat
# keeps its own bed instead.
def album_bed_available?
  slug = ALBUM_BED.to_s.strip
  return false if slug.empty? || slug == "0"

  dir = File.join(ROOT, "samples", slug)
  Dir.exist?(dir) && !Dir.glob(File.join(dir, "*.{wav,mp3,flac,aiff,aif}")).empty?
end

# Everything the record imposes on one beat, in the order the two tables are
# meant to land: the signature first, then what varies over it.
def apply_album_slot!(idx, label: "album[#{idx}]")
  return unless album_enabled?

  force_env!(album_signature_env, label: "#{label} signature")
  force_env!(album_slot_env(idx), label: label)
end

# --------------------------------------------------------------------------
# engine part: demo_all
# --------------------------------------------------------------------------
#
# demo-all: render every style and join the parts.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# One demo-all at a time, for the same reason stream() takes a lock.
#
# Two of them share scratch/all_tracks_demo and they do not share it politely.
# Each part is written through an intermediate and renamed into place, so while
# one run is rewriting a part the other sees that path not exist -- and the join
# reads all 86 paths at once, so it only has to lose the race on one of them to
# die after hours of rendering. That happened twice tonight. It presents as a
# file that "vanished": ffmpeg reports no such file, and by the time anyone looks
# the part is back, because the other process finished its rename.
#
# It also produces the subtler version. A part read while it is half-written is a
# valid, playable, TRUNCATED wav -- one came out at 20.9s against its neighbours'
# 53.0s and passed every check, because `ok` only asks whether the file is bigger
# than 50 kB.
#
# Same shape as acquire_stream_lock!, and mirrored deliberately rather than
# generalised: the two locks guard different directories and there is no third
# caller to justify the abstraction yet.
DEMO_LOCK_PATH = scratch_path("dilla_demo.lock").freeze

def acquire_demo_lock!
  if File.exist?(DEMO_LOCK_PATH)
    holder = File.read(DEMO_LOCK_PATH).strip.to_i
    if holder.positive?
      begin
        Process.kill(0, holder)
        dmesg_warn("demo-all already running as pid #{holder} — exit (DEMO_NO_LOCK=1 to override)")
        exit 0
      rescue Errno::ESRCH
        FileUtils.rm_f(DEMO_LOCK_PATH)
      end
    end
  end
  File.write(DEMO_LOCK_PATH, Process.pid.to_s)
  at_exit do
    FileUtils.rm_f(DEMO_LOCK_PATH) if File.exist?(DEMO_LOCK_PATH) &&
                                      File.read(DEMO_LOCK_PATH).strip.to_i == Process.pid
  rescue StandardError
    nil
  end
end

# Did this part come out as music, rather than merely as a file?
#
# The test was File.size(part) > 50_000, and silence is not small: four bars of
# stereo PCM is megabytes whether or not anything is playing. So a silent part
# passed, the retry below -- which re-renders minimal with vocals, morphs and
# self-sampling off, and exists for exactly this -- never ran, and the silence
# survived until join, where dropping it was the only option left. Four of
# twelve tracks were lost that way in one demo.
#
# Same detector the join uses, so the two cannot disagree about what is dead.
def demo_part_rendered?(part)
  return false unless File.file?(part) && File.size(part) > 50_000

  !demo_part_dead?(part)
end

def demo_all(bars_count = 12, destination = nil)
  acquire_demo_lock! unless ENV["DEMO_NO_LOCK"] == "1"
  bars_count = bars_count.to_i
  bars_count = 12 unless bars_count.positive?
  dest = destination.to_s
  dest = File.join(ROOT, "demo.wav") if dest.empty?
  # each-mode writes its mp3s to the dilla root and its transient wav straight
  # into SCRATCH_DIR, so it creates no directory of its own.
  out_dir = demo_each? ? SCRATCH_DIR : File.join(SCRATCH_DIR, "all_tracks_demo")
  FileUtils.mkdir_p(out_dir)
  # From scratch, every time.
  #
  # The demo's job is to be what the code currently sounds like. Reusing parts
  # broke that in the most confusing way available: the render succeeded, the log
  # said so, and the audio was from before the change. A whole day of drum work
  # was judged against a file that predated all of it.
  #
  # A staleness check against engine_mtime fixes the common case, but it still
  # answers "is this part old enough to replace" -- a question that should not be
  # asked when the point is correspondence between source and sound. The parts
  # directory is emptied first and everything is rendered again.
  #
  # DEMO_KEEP_PARTS=1 keeps them, for iterating on one track when the other 450
  # have not changed.
  unless ENV["DEMO_KEEP_PARTS"] == "1"
    stale = Dir.glob(File.join(out_dir, "*.{wav,mp3}"))
    unless stale.empty?
      dmesg("clearing #{stale.length} part(s) — the demo renders from scratch",
            unit: "demo0", parent: "dilla0")
      FileUtils.rm_f(stale)
    end
  end
  log_path = File.join(out_dir, "demo_all.log")
  catalog_path = File.join(out_dir, "catalog.txt")
  track_timeout = (ENV["DEMO_TRACK_TIMEOUT"] || ENV["STREAM_TRACK_TIMEOUT"] || "300").to_i
  track_timeout = 300 unless track_timeout.positive?
  force = ENV["DEMO_FORCE"] == "1"
  creative = ENV.fetch("DEMO_CREATIVE", "1") != "0"
  # No vocals in the demo. The demo exists to show the engine's harmony, groove
  # and tone across 84 pieces; a voice on top is the loudest thing in the mix and
  # it masks exactly what is being demonstrated. Set DEMO_RAP_EVERY=4 to put the
  # old every-fourth-track rap back.
  # Every other slot carries a rapper, by default.
  #
  # This defaulted to 0 -- no vocals anywhere -- on the reasoning that a voice is
  # the loudest thing in the mix and masks the harmony the demo exists to show.
  # That is true of a demo for an engine and wrong for a demo of a hiphop
  # engine: the tool makes records for rappers, and a beat tape with no rapper
  # on it does not demonstrate the thing it is for. Operator direction
  # 2026-08-09: "make it include rap vocals".
  #
  # 2, not 1: alternating slots still leave every other track instrumental, so
  # the harmony is audible on its own somewhere in the run.
  rap_every = (ENV["DEMO_RAP_EVERY"] || "2").to_i

# The lead stack is a sprinkle, not a layer.
#
# VOICE_STACK renders every lead twice, and on a 451-part demo that measured
# 0.54 parts/min against 2.31 without it -- 4.3x, or thirteen hours against
# three. Paying that on every single track also misrepresents the feature:
# the operator's word for it was "sprinkled on top", and a doubling that is
# always present is not a sprinkle, it is the sound.
#
# Every third track, so it is heard as a colour that comes and goes and the
# demo still finishes overnight. DEMO_VOICE_STACK_EVERY=1 puts it on all of
# them, 0 turns it off entirely.
voice_stack_every = (ENV["DEMO_VOICE_STACK_EVERY"] || "3").to_i

  # Captured ONCE, before the loop, because the loop assigns ENV["RAP_VOCAL"]
  # on every iteration -- reading it inside would return the previous slot's
  # value ("0" on most of them) instead of what the operator asked for.
  #
  # Comma-separated, so a demo can rotate rappers. A single voice repeated over
  # twenty-six slots is its own kind of monotony, and the catalogue has six.
  demo_rap_slugs = ENV["RAP_VOCAL"].to_s.split(",").map(&:strip)
                                    .reject { |s| s.empty? || s == "0" }
  demo_rap_slugs = DEMO_RAP_ROTATION.dup if demo_rap_slugs.empty?
  # Never ship a slug the catalogue cannot resolve: rap_vocal_resolve returns
  # nil and the slot renders instrumental while the log still says rap=<slug>,
  # which reads as the vocal having played.
  demo_rap_slugs = demo_rap_slugs.select { |s| rap_vocal_resolve(s) }
  demo_rap_slugs = [RAP_VOCAL_SOURCE] if demo_rap_slugs.empty?

  # A demo shows the house sound, not the whole kit shelf. Set
  # DRUM_ROTATE_CURATED=0 to walk all 62 presets again.
  ENV["DRUM_ROTATE_CURATED"] ||= "1"
  ENV["SPEAK"] ||= "0"
  ENV["STREAM_CONTINUOUS"] = "0"
  ENV["DILLA_STREAMING"] = "1"
  ENV["STREAM_LEAD_MIDI_RICH"] = "1"

  # Steady mode: hold the synthesis still so the WRITING is what varies.
  #
  # demo-all was built to show range, and it does that by moving every knob it
  # has: STREAM_ROTATE_LEAD and STREAM_ROTATE_SYNTH give each track a different
  # lead voice and arp mode, then SYNTH_MORPH / LEAD_MORPH / SYNTH_CYCLE move
  # the voice again WITHIN the track, and creative mode adds EXPERIMENTAL_LEADS,
  # STREAM_CREATIVE_FREEDOM and STREAM_ANALOG_WILD on top. Five consecutive
  # tracks came out as
  #
  #   lead=soul_prophet/wonky_spiral  lead=wonky/neo_quartal  lead=moog/soul_wash
  #   lead=prophet/moog_funk          lead=neo_pluck/prophet_glass
  #
  # -- a different instrument playing a different arp every time, each morphing
  # as it goes. That is a showcase of the synthesis, and it is the wrong
  # instrument for judging material: everything sounds restless, and a
  # progression cannot be blamed or credited for what the randomiser did over
  # it. The tempo was not the problem -- those takes measured 82-89 BPM, inside
  # the idiom -- the note motion was.
  #
  # So demo-each defaults to steady and demo-all keeps its old behaviour. Set
  # DEMO_STEADY=0 to get the showcase back, DEMO_STEADY=1 to hold demo-all still.
  steady = ENV.fetch("DEMO_STEADY", demo_each? ? "1" : "0") != "0"
  unless steady
    ENV["STREAM_ROTATE_LEAD"] = "1"
    ENV["STREAM_ROTATE_SYNTH"] = "1"
    ENV["SYNTH_MORPH"] = "1"
    ENV["LEAD_MORPH"] = "1"
    ENV["SYNTH_CYCLE"] = "1"
    if creative
      ENV["STREAM_ANALOG_WILD"] = "1"
      ENV["STREAM_CREATIVE_FREEDOM"] = "1"
      ENV["EXPERIMENTAL_LEADS"] = "1"
      ENV["FM_NATIVE"] = "1"
    end
  end
  # Named before the defaults tables run, so every part sidecar records the mode
  # it was rendered in and a beat pulled back out of the record reproduces with
  # the same table. The forcing that actually holds the signature down happens
  # per slot, below -- this only makes the run honest about what it is.
  ENV["RENDER_MODE"] = "album" if album_enabled? && ENV["RENDER_MODE"].to_s.empty?
  apply_best_defaults!
  apply_dilla_style!(force: true)
  force_env!(STREAM_STYLE_SAFE, label: "STREAM_STYLE_SAFE")

  # Steady has to be applied HERE, after the three calls above, not before them.
  #
  # It was written above them and did nothing at all. apply_best_defaults! sets
  # MELODIC_LEAD=0 and STREAM_STYLE_SAFE sets STREAM_ROTATE_LEAD=1, so every key
  # steady had just cleared was put straight back, and eight tracks rendered
  # with the old rotating arps while the log said steady mode was on. The
  # operator heard it immediately -- "they all sound the same as the old demo"
  # -- which is what a silent no-op sounds like.
  #
  # MELODIC_LEAD=1 is set explicitly rather than left to its default, because
  # the default is only reached when nothing else has written the key, and by
  # this point something always has.
  if steady
    %w[STREAM_ROTATE_LEAD STREAM_ROTATE_SYNTH SYNTH_MORPH LEAD_MORPH SYNTH_CYCLE
       EXPERIMENTAL_LEADS STREAM_CREATIVE_FREEDOM STREAM_ANALOG_WILD
       LEAD_FORCE_ARP SCALE_LEAD CREATIVE_LEAD].each { |k| ENV[k] = "0" }
    ENV["MELODIC_LEAD"] = "1"
  end

  # Unlock pad/lead so per-slot rotation is not pinned back to stack_soul/held.
  %w[PAD_VOICE PAD_ARP_MODE LEAD_VOICE LEAD_ARP_MODE TRACK PROGRESSION].each { |k| ENV.delete(k) }

  order = demo_all_order
  # order.txt and catalog.txt record what the manifest already records, so
  # each-mode writes neither.
  unless demo_each?
    File.write(File.join(out_dir, "order.txt"), order.map(&:to_s).join("\n") + "\n")
    # Truncate only when there is nothing to lose. The catalogue is appended one
    # line per track from inside the render loop, and a resumed track takes the
    # `next` above that line -- so a run that resumes every part writes no lines
    # at all. Truncating unconditionally then meant the join run, which is
    # exactly the run that resumes everything, erased the record of the demo it
    # was assembling: 86 pieces joined and a 0-byte catalogue saying which pad,
    # lead, voicing and drum preset each one used.
    #
    # Same rule the manifest below already follows: the file is a ledger across
    # runs, not an artifact of the last one, so only --force starts it over.
    File.write(catalog_path, "") if force || !File.file?(catalog_path)
  end
  if demo_each?
    manifest = DEMO_EACH_MANIFEST
    unless File.file?(manifest) && !force
      File.write(manifest, <<~HEAD)
        # idx  title  slug  seed  bars  pad  lead  drums  pocket  kb
        # title is ours and names the file. slug is the engine's internal name
        # for the progression -- pass it to TRACK= to render that piece again.
        # seed is the RENDER_SEED this take was rendered with. Re-roll a track by
        # deleting its mp3 and re-running with a different DEMO_SEED.
        #
        # CAVEAT: a recorded seed narrows a take down, it does not reconstruct it.
        # Two renders with RENDER_SEED pinned are still not bit-identical -- see
        # the note above noise_seed. Treat this column as a lead, not a guarantee.
      HEAD
    end
  end
  dmesg("demo-all tracks=#{order.length} bars=#{bars_count} creative=#{creative ? 1 : 0} → #{dest}",
        unit: "demo0", parent: "dilla0")

  parts = []
  order.each_with_index do |track, idx|
    slug = track.to_s
    part = File.join(out_dir, format("%02d_%s.wav", idx, slug))
    # Our title on the file; the engine's slug lives in the manifest, since that
    # is what you pass back to TRACK= to render it again.
    keep_mp3 = File.join(DEMO_EACH_DIR, format("%02d_%s.mp3", idx, demo_title(slug, idx)))
    # In each-mode the mp3 is the artifact, so that is what resume looks for.
    # Checking the wav instead would re-render every track that had already been
    # encoded and cleaned up, which is every track.
    if demo_each? && !force && File.file?(keep_mp3) && File.size(keep_mp3) > 20_000
      dmesg("keep #{File.basename(keep_mp3)}", unit: "demo0", parent: "dilla0")
      parts << keep_mp3
      next
    end
    # A part is reusable only if it is NEWER than the engine that made it.
    #
    # This used to skip any part that merely existed and was over 100 kB, so once
    # scratch/ held a full set, every later run reused all of it and the demo
    # stopped reflecting the code. That is not hypothetical: after a day of
    # changes to the groove, the vocal, the stereo field and the drum feels, a
    # freshly "rendered" demo was still the old one, and the only way to get the
    # new sound was to know about DEMO_FORCE and remember to say it.
    #
    # engine_mtime is the newest mtime across every file the engine is made of, so
    # comparing against it means any edit anywhere invalidates the cache
    # automatically. Nobody has to remember a flag, and a stale demo cannot be
    # mistaken for a new one.
    if !demo_each? && !force && File.file?(part) && File.size(part) > 100_000 && File.mtime(part) >= engine_mtime && !part.end_with?("_SILENCE.wav")
      # Reject silence leftovers from prior failed runs.
      dmesg("skip #{File.basename(part)}", unit: "demo0", parent: "dilla0")
      parts << part
      next
    end
    # Per-track pin, set before any of the rotation helpers below run so they
    # draw from it too.
    ENV["RENDER_SEED"] = demo_each_seed(idx).to_s if demo_each?
    FileUtils.rm_f(part)
    FileUtils.rm_f(File.join(out_dir, format("%02d_%s_SILENCE.wav", idx, slug)))

    ENV["TRACK"] = slug
    ENV["PROGRESSION"] = slug
    ENV["BARS"] = bars_count.to_s
    ENV["LINEAR_CHORD_INDEX"] = "1"
    ENV["LA_BEAT_PROGRESSION"] = "0"
    ENV["STREAM_LOCK"] = "0"
    # Distinct kit + pocket per slot. Kept in steady mode: the drums changing
    # per track is idiom, not restlessness, and it does not move under the
    # progression the way a rotating lead does.
    stream_rotate_drums!(idx)
    # Distinct leads / MIDI arps / synth morph per slot (clears patch cache).
    # Skipped in steady mode -- this and the second call below are what give
    # every track its own instrument, which is the thing being held still.
    stream_rotate_voices_and_arps!(idx) unless steady
    # Stronger pad identity than stream defaults (avoid every slot = stack_soul
    # held), written through the pin rule instead of straight into ENV.
    #
    # A restore_explicit_stream_env! call used to sit above these lines, and the
    # lines then overwrote the very keys it exists to protect on the next
    # statement -- so `PAD_VOICE=prophet ruby dilla.rb demo_all` rendered the
    # rotation's voice in every slot and the restore bought nothing. force_env!
    # goes through style_env_write!, which beats the defaults and loses to an
    # operator pin: the order that was intended.
    force_env!(demo_slot_pad_env(idx), label: "demo_all[#{idx}]")
    # Track-specific soul pad/lead overlays (force so they win).
    apply_track_soul_profile!(slug, force: true)
    # Re-apply rotation after soul profile so lead/pad keep moving.
    stream_rotate_voices_and_arps!(idx) unless steady
    force_env!(demo_slot_pad_env(idx), label: "demo_all[#{idx}]") unless steady
    # The rotation above writes ENV directly and turns nine layers back ON:
    # LEAD_ARP, SCALE_LEAD, HARMONY_LEAD, CREATIVE_LEAD, MELODIC_LEAD,
    # EXPERIMENTAL_LEADS, LEAD_MORPH, SYNTH_MORPH, PAD_TEXTURE -- exactly nine
    # of the twenty-one knobs a TRACK_LAYER_PROFILES entry set to "0" two lines
    # earlier. So a sampled bed whose profile exists to let the record carry the
    # harmony gets every stripped layer back before it renders, and only the
    # twelve mix-balance knobs (PAD_VOL, HARM_MIX_WEIGHT, SAMPLE_LOOP_VOL and
    # WEIGHT, ...) survive into a demo. kembara_rindu and semua_untuk_mu have
    # carried profiles all along and have never once rendered lean here.
    #
    # That was tried and reverted. An apply_track_layer_profile!(slug,
    # force: true) here does work -- production complexity drops 4.04 -> 3.81 on
    # kembara_rindu and 3.92 -> 3.67 on lo_borges, so the layers do come
    # off -- but content enjoyment goes DOWN by 0.09 on both tracks, three seeds
    # each (audiobox-aesthetics; control sd 0.01-0.18). Neither delta clears its
    # own error bar alone, but they agree in sign and to two decimals, and
    # nothing measured got better. It changed rendered sound on four tracks and
    # bought nothing, so it is not carried.
    #
    # Do not re-add it without a number. The obvious next question is whether
    # the profile's own values are wrong for a demo rather than the ordering.
    # Sparse rap so chord cycles are audible (a vocal on every slot masked
    # variety). gunnhild is the only vocal source now.
    # One branch, not three. The rap_every > 1 branch used to hardcode
    # "gunnhild" and so discarded an explicit RAP_VOCAL entirely: asking for
    # store_p with DEMO_RAP_EVERY=3 rendered gunnhild on every third slot and
    # said so in the log, which reads as the request having been honoured.
    if rap_every <= 0
      ENV["RAP_VOCAL"] = "0"
    else
      on = demo_rap_slot?(idx, rap_every)
      # Index by how many vocal slots have gone by, not by idx, or a rotation
      # of 2 voices at rap_every 2 would land on the same voice every time.
      ENV["RAP_VOCAL"] = on ? demo_rap_slugs[(idx / rap_every) % demo_rap_slugs.length] : "0"
    end
    # Same slot arithmetic as the vocal above, offset so the two do not always
    # coincide: a track carrying both a rapper and a doubled lead every time
    # would make the pair sound like one feature.
    ENV["VOICE_STACK"] = if voice_stack_every.positive? && ((idx + 1) % voice_stack_every).zero?
                           "2"
                         else
                           "1"
                         end

    # Per-slot pocket, opt-in.
    #
    # performer and groove_dna drive the microtiming offsets in dilla_timing_ms,
    # so they ARE the pocket. Left alone the whole demo inherits one identity
    # from project/session.json -- measured, 18 of 18 non-techno parts came out
    # questlove/cosmogramma, and questlove is the tightest profile in the table
    # (kick_lag 2ms, hat_late 6ms) while yancey, the Dilla one, is 8 and 22.
    # A Dilla engine demonstrated itself in the least Dilla pocket it owns.
    #
    # On by default as of 2026-08-09, on operator direction to codify it. Set
    # DEMO_VARY_POCKET=0 for the old single-pocket behaviour.
    if ENV.fetch("DEMO_VARY_POCKET", "1") == "1"
      performers = DillaComposition::PERFORMERS.keys
      grooves = DillaComposition::GROOVE_DNA.keys
      # Indexed off the slug, not idx, so a track keeps its pocket when the
      # running order changes and two demos stay comparable.
      h = slug.to_s.each_char.sum(&:ord)
      force_env!({ "PERFORMER" => performers[h % performers.length].to_s,
                   "GROOVE_DNA" => grooves[(h / 7) % grooves.length].to_s },
                 label: "demo_all[#{idx}] pocket")
    end
    # This read as "choir on every third creative slot", but the fallback was
    # "1" — so the other two thirds got a choir too, and the condition only
    # decided which branch turned it on. Choir is a vocal; the demo has none.
    ENV["CHOIR_VOX"] = ENV.fetch("CHOIR_VOX", "0")

    # The record. Last, because everything above it writes keys the album owns --
    # stream_rotate_drums! sets EXTERNAL_KIT and RAW_KICK on every iteration and
    # the lead rotation follows it -- so a signature applied any earlier is
    # overwritten before the part renders and the demo comes out sounding like the
    # rotation rather than like the album. ALBUM=0 renders the catalogue without
    # it, which is the right instrument for judging a progression on its own.
    apply_album_slot!(idx)

    dmesg(
      "render #{idx + 1}/#{order.length} #{slug} " \
      "pad=#{ENV['PAD_VOICE']}/#{ENV['PAD_ARP_MODE']} " \
      "lead=#{ENV['LEAD_VOICE']}/#{ENV['LEAD_ARP_MODE']} " \
      "vox=#{ENV['VOICING']} drums=#{ENV['DRUM_PRESET']}/#{ENV['POCKET_SET']} " \
      "rap=#{ENV['RAP_VOCAL']}",
      unit: "demo0", parent: "dilla0",
    )
    unless demo_each?
      File.open(catalog_path, "a") do |f|
        f.puts format(
          "%02d %s pad=%s/%s lead=%s/%s voicing=%s drums=%s/%s rap=%s",
          idx, slug, ENV["PAD_VOICE"], ENV["PAD_ARP_MODE"],
          ENV["LEAD_VOICE"], ENV["LEAD_ARP_MODE"], ENV["VOICING"],
          ENV["DRUM_PRESET"], ENV["POCKET_SET"], ENV["RAP_VOCAL"]
        )
      end
    end

    ok = false
    begin
      Timeout.timeout(track_timeout) do
        if demo_techno_slot?(idx, slug)
          # Techno slots go through the industrial renderer instead. Length is
          # matched to what the hip-hop track would have run to, so the two
          # sit side by side in a demo rather than one being twice the other.
          prev = ENV["HATE_MIN"]
          prev_blocks = ENV["HATE_MIN_BLOCKS"]
          prev_arrived = ENV["HATE_ARRIVED"]
          ENV["HATE_MIN"] = ((bars_count * 4 * (60.0 / HATE_BPM)) / 60.0).round(2).to_s
          # A demo slot is a sample, not a set: one block is a legitimate length
          # here even though it is not one for a standalone techno render. Without
          # this the renderer's own floor doubles the slot back and the length
          # matching on the line above is discarded a second time.
          ENV["HATE_MIN_BLOCKS"] = "1"
          # ...and a sample is of the music, not of the way in to it. The arc's
          # only resolution is the block, so a slot short enough to be two blocks
          # puts the listener at position 0.0 for the whole first half -- three of
          # eighteen layers, -50.5 dB against the second half's -14.3. Every
          # techno slot in the demo had that shape, identical to 0.1 dB across all
          # 27, because a dead block carries no progression to tell them apart.
          ENV["HATE_ARRIVED"] = "1"
          begin
            dmesg("slot #{idx} -> techno", unit: "demo0", parent: "dilla0")
            techno_mp3 = part.sub(/\.wav\z/, ".mp3")
            render_hate_techno(techno_mp3)
            # Decode, do not rename. The techno renderer writes an mp3, and
            # moving it onto the .wav path gave the part an extension that lied
            # about its contents -- every other slot here is pcm_s16le. That
            # matters at the end of this method, where the parts are joined with
            # `-c copy`: the concat demuxer probes only the FIRST input and
            # applies that codec to all of them, so one mp3 in slot 1 makes
            # ffmpeg copy mp3 packets into a WAV container and exit 0. Nothing
            # raises, so the re-encode rescue below never fires; the file
            # does not open (afplay: "AudioFileOpen failed ('dta?')") and
            # ffprobe reports a duration read from a header that does not
            # describe the data -- 14.2 minutes for 5.3 minutes of audio.
            sh! "ffmpeg", "-y", "-loglevel", "error", "-i", techno_mp3,
                "-c:a", "pcm_s16le", "-ar", SAMPLE_RATE.to_s, "-ac", "2", part
            FileUtils.rm_f(techno_mp3)
          ensure
            prev ? ENV["HATE_MIN"] = prev : ENV.delete("HATE_MIN")
            prev_blocks ? ENV["HATE_MIN_BLOCKS"] = prev_blocks : ENV.delete("HATE_MIN_BLOCKS")
            prev_arrived ? ENV["HATE_ARRIVED"] = prev_arrived : ENV.delete("HATE_ARRIVED")
          end
        else
          render_dilla(part, bars_count)
        end
      end
      ok = demo_part_rendered?(part)
    rescue Timeout::Error
      dmesg_warn("timeout #{slug} after #{track_timeout}s")
      FileUtils.rm_f(part)
    rescue StandardError => e
      dmesg_warn("fail #{slug}: #{e.message}")
      File.open(log_path, "a") { |f| f.puts "#{Time.now.utc.iso8601} FAIL #{slug}: #{e.message}" }
      FileUtils.rm_f(part)
    end

    unless ok
      dmesg("retry minimal #{slug}", unit: "demo0", parent: "dilla0")
      saved = %w[RAP_VOCAL CHOIR_VOX LEAD_MORPH SYNTH_MORPH SELF_SAMPLE VINYL
                 LEAD_ARP HARMONY_LEAD SCALE_LEAD CREATIVE_LEAD].to_h { |k| [k, ENV[k]] }
      ENV["RAP_VOCAL"] = "0"
      ENV["CHOIR_VOX"] = "0"
      ENV["LEAD_MORPH"] = "0"
      ENV["SYNTH_MORPH"] = "0"
      ENV["SELF_SAMPLE"] = "0"
      ENV["VINYL"] = "0"
      ENV["LEAD_ARP"] = "1"
      ENV["HARMONY_LEAD"] = "0"
      ENV["SCALE_LEAD"] = "0"
      ENV["CREATIVE_LEAD"] = "0"
      begin
        Timeout.timeout(track_timeout) do
          render_dilla(part, [bars_count, 8].min)
        end
        ok = demo_part_rendered?(part)
      rescue StandardError, Timeout::Error => e
        dmesg_warn("retry fail #{slug}: #{e.message}")
        FileUtils.rm_f(part)
      ensure
        saved.each { |k, v| v.nil? ? ENV.delete(k) : ENV[k] = v }
      end
    end

    if ok && demo_each?
      # Encode and drop the wav. 86 WAVs is ~500 MB of a directory meant to be
      # browsed and pruned; the same catalogue as mp3 is a few tens of MB.
      # demo_encode_mp3 derives its output path from the wav's, so the mp3 lands
      # beside the wav in scratch and has to be moved. Encoding to scratch and
      # moving, rather than encoding straight to the root, means a half-written
      # mp3 from an interrupted run never appears in the listening queue where it
      # would look like a finished take.
      mp3 = demo_encode_mp3(part)
      if mp3
        FileUtils.mv(mp3, keep_mp3)
        mp3 = keep_mp3
        FileUtils.rm_f(part)
        parts << mp3
        File.open(DEMO_EACH_MANIFEST, "a") do |f|
          f.puts [format("%02d", idx), demo_title(slug, idx), slug, demo_each_seed(idx), bars_count,
                  ENV["PAD_VOICE"], ENV["LEAD_VOICE"], ENV["DRUM_PRESET"],
                  ENV["POCKET_SET"], (File.size(mp3) / 1024)].join("\t")
        end
        dmesg("ok #{slug} seed=#{demo_each_seed(idx)} #{(File.size(mp3) / 1_000_000.0).round(2)}MB",
              unit: "demo0", parent: "dilla0")
      else
        parts << part
        dmesg_warn("mp3 encode failed #{slug} — keeping wav")
      end
    elsif ok
      parts << part
      dmesg("ok #{slug} #{(File.size(part) / 1_000_000.0).round(2)}MB", unit: "demo0", parent: "dilla0")
    else
      sil = File.join(out_dir, format("%02d_%s_SILENCE.wav", idx, slug))
      beat_p = 60.0 / (ENV["BPM"] || "92").to_f
      sec = ([bars_count, 8].min * 4 * beat_p).round(3)
      begin
        sh! "ffmpeg", "-y", "-f", "lavfi", "-i", "anullsrc=r=#{SAMPLE_RATE}:cl=stereo",
            "-t", sec.to_s, "-c:a", "pcm_s16le", sil
        parts << sil if File.file?(sil)
        dmesg_warn("silence placeholder #{slug}")
      rescue StandardError
        dmesg_warn("skip #{slug} (no audio)")
      end
    end
    # PID-scoped, via the helper that already exists for exactly this. The glob
    # here was ".dilla_*" with no pid in it, so a demo-all run deleted the
    # scratch files of every OTHER dilla process in the directory, once per
    # track. A concurrent render then fails in a way that looks like anything
    # but this: its layer files pass File.exist? in mix_harmonic_wav_stems and
    # are gone by the time ffmpeg opens them, so the render dies on "No such
    # file or directory" for a file it just checked for. Every render in this
    # working copy failed for the ~40 minutes a catalogue demo was running.
    cleanup_render_scratch!
  end

  abort "demo-all: no parts rendered" if parts.empty?

  # Look inside the parts before joining them.
  #
  # 28 of the 86 tracks in the demo committed at c0d00f488 were silence -- the
  # techno slots, at -47.7 dB overall with no low end at all -- and every check
  # between rendering them and publishing them passed. `ok` gates on
  # File.size > 50_000, which a silent WAV satisfies easily. The lengths were
  # measured and matched the arithmetic exactly. The concat succeeded. The
  # loudness of the FINISHED record looked correct, because 58 healthy tracks
  # carry an integrated figure past 28 quiet ones. It was rendered, joined,
  # encoded, committed and played twice before anyone measured a part.
  #
  # So this measures the two things that were not being measured, per part, and
  # says so out loud. Silence and truncation are the two failures this engine
  # produces without raising -- a stage that emits nothing still writes a valid
  # file, and a render cut short still writes a playable one.
  #
  # Thresholds are relative to the parts themselves, not absolutes: a demo that
  # is quiet on purpose should not trip this, but one track 25 dB under its
  # neighbours is never intentional. Median, not mean, so a handful of bad parts
  # cannot drag the reference down to meet them.
  demo_report_suspect_parts(parts)

  if demo_each?
    dmesg("demo-each: #{parts.length} files in the dilla root", unit: "demo0", parent: "dilla0")
    puts "#{parts.length} tracks -> #{DEMO_EACH_DIR.sub("#{File.dirname(ROOT)}/", '')}/"
    puts "delete the ones that miss, then re-run: the survivors are skipped and only the gaps re-render"
    puts "re-roll one: DEMO_SEED=<n> ruby dilla.rb demo-each   (or delete just that file first)"
    return parts
  end

  # Drop parts that are digitally dead before joining, not after.
  #
  # demo_report_suspect_parts below already names quiet and short parts, and it
  # is deliberately a warning -- one bad part should not throw away eighty good
  # ones. But it runs AFTER this join, so a part carrying nothing was warned
  # about only once it was already inside demo.wav and demo.mp3. Measured twice
  # now: a *_SILENCE placeholder at -91.0 dB joined into a shipped demo, and the
  # log line that mentioned it read as a note rather than a fault.
  #
  # This is narrower than the suspect heuristic on purpose. It does not touch
  # "quiet relative to its neighbours", which can be a legitimate take; it drops
  # only files with no signal at all, which never can be. The part stays on
  # disk, so deleting nothing and re-running still refills the gap.
  parts = demo_reject_dead_parts(parts)
  list = File.join(out_dir, "concat.txt")
  File.write(list, parts.map { |p| "file '#{p}'" }.join("\n") + "\n")
  tmp = "#{dest}.concat.wav"
  demo_join_parts!(parts, list, tmp)
  FileUtils.mv(tmp, dest)
  # Optional album-level loudnorm (off by default — long concats exceed sh timeout).
  if ENV.fetch("DEMO_ALBUM_NORM", "0") == "1"
    prev_to = ENV["DILLA_SH_TIMEOUT"]
    ENV["DILLA_SH_TIMEOUT"] = (ENV["DEMO_NORM_TIMEOUT"] || "600").to_s
    begin
      normalize_track_loudness!(dest)
    ensure
      prev_to ? ENV["DILLA_SH_TIMEOUT"] = prev_to : ENV.delete("DILLA_SH_TIMEOUT")
    end
  end
  # Re-recorded against `dest`, because demo_join_parts! wrote its manifest
  # beside the temporary and the mv above left it there. Working out what was in
  # a 44-minute master by fingerprinting every file still on disk is what this
  # exists to prevent; a tracklist filed under a filename that no longer exists
  # would prevent nothing.
  DillaProvenance.record_assembly!(
    dest, parts:,
    how: "demo concat of #{parts.length} part(s)" +
         (ENV.fetch("DEMO_ALBUM_NORM", "0") == "1" ? ", then album loudnorm" : "")
  )
  FileUtils.rm_f("#{tmp}#{DillaProvenance::MANIFEST_EXT}")
  dur = 0.0
  begin
    out, = Open3.capture3("ffprobe", "-v", "error", "-show_entries", "format=duration",
                          "-of", "default=noprint_wrappers=1:nokey=1", dest)
    dur = out.to_s.strip.to_f
  rescue StandardError
    nil
  end
  mp3 = demo_encode_mp3(dest)
  # The mp3 gets its own sidecar, not just the wav.
  #
  # record_assembly! above files the tracklist under `dest`, which is demo.wav —
  # and demo.wav, demo.wav.dilla and demo.mp3 are all gitignored, so the only
  # one of the three that reliably survives on disk is the mp3. It is the file
  # this code calls the tracked artifact two lines down, it is the one that gets
  # played and sent to people, and it was the one with no record of how it was
  # made. On 2026-08-27 a 36:57 master finished with its provenance filed under a
  # wav that no longer existed and a session.json five hours older than the
  # render, so what made it could not be recovered at all. Seeds rotate per run;
  # an unreproducible master with no manifest is simply lost.
  if mp3
    DillaProvenance.record_assembly!(
      mp3, parts:,
      how: "demo concat of #{parts.length} part(s), encoded to mp3" +
           (ENV.fetch("DEMO_ALBUM_NORM", "0") == "1" ? ", after album loudnorm" : "")
    )
  end
  dmesg("wrote #{dest} parts=#{parts.length}/#{order.length} #{(File.size(dest) / 1_000_000.0).round(1)}MB #{dur.round(1)}s",
        unit: "demo0", parent: "dilla0")
  puts "ok: #{dest} (#{parts.length}/#{order.length} tracks, #{dur.round(1)}s)"
  if mp3
    dmesg("wrote #{mp3} #{(File.size(mp3) / 1_000_000.0).round(1)}MB", unit: "demo0", parent: "dilla0")
    puts "ok: #{mp3} (#{(File.size(mp3) / 1_000_000.0).round(1)}MB, tracked artifact)"
  end
  dest
end

# --------------------------------------------------------------------------
# engine part: stream
# --------------------------------------------------------------------------
#
# The stream loop itself.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def stream(bars_count = STREAM_BARS_COUNT)
  require_playback_tool!
  # Non-stop outer supervisor: any exit except Ctrl-C restarts stream (agent + interactive).
  if ENV.fetch("STREAM_CONTINUOUS", "1") != "0" && ENV["DILLA_STREAM_SUPERVISOR"] != "1"
    stream_log = File.join(SCRATCH_DIR, "stream.log")
    # Read from USER_PINNED_ENV, not ENV.
    #
    # This list is built after apply_best_defaults! has already run, so every
    # key it names is populated whether or not the caller asked for it. Passing
    # ENV's value forwarded the engine's own defaults to the child as if the
    # user had typed them — and in the child they land in USER_PINNED_ENV, where
    # force_env! and the per-track sync both treat them as untouchable. That is
    # how `STREAM_TRACK=slum_village_players_documented` ended up locked to
    # pedal_e_descent's chords: PROGRESSION was "pinned" to a default nobody
    # chose. USER_PINNED_ENV holds what the command line actually said.
    #
    # PAD_VOICE / PAD_LAYERS / LEAD_* are here because a pinned pad or lead was
    # silently dropped at the supervisor boundary before: PAD_VOL made the list
    # but PAD_VOICE did not, so `PAD_VOICE=prophet ruby dilla.rb stream` played
    # whatever the soul profile chose.
    env_pass = %w[
      RENDER_MODE STREAM_SOUL STREAM_COMFORT STREAM_PUNCH DILLA_COMFORT SPEAK RAP_VOCAL
      STREAM_DEMO STREAM_TRACK STREAM_LOCK
      WONKY_TOP_MIX WONKY_SUB_MIX WONKY_MERGE_BOOST WONKY_OVERLAY_GAIN WONKY_DRUM_OVERLAY
      DRUM_BUS_VOL DRUM_BUS_GAIN DRUM_MIX_WEIGHT DRUM_AIR_DB DRUM_PRESENCE_DB
      KICK_GAIN WONKY_KICK_GAIN POCKET_KICKS WONKY_DRUMS_ONLY PAD_VOL STREAM_LUFS
      STREAM_ROTATE_LEAD STREAM_ROTATE_SYNTH STREAM_DRUM_ROTATE THEORY_RUNTIME THEORY_BACH
      PAD_VOICE PAD_ARP_MODE PAD_LAYERS LEAD_VOICE LEAD_ARP_MODE PROGRESSION SECTION_CYCLE
      DRUM_PRESET FM_DRUMS SWING BPM DRUM_FADE_IN
      LEAD_ARP SCALE_LEAD HARMONY_LEAD CREATIVE_LEAD EXPERIMENTAL_LEADS
      SYNTH_CYCLE SYNTH_MORPH LEAD_MORPH ANALOG_CHAIN SONITEX VINYL
    ].filter_map do |k|
      v = USER_PINNED_ENV[k]
      v.nil? || v.empty? ? nil : "#{k}=#{Shellwords.escape(v)}"
    end.join(" ")
    # The env_pass prefix above is additive, not exclusive: this command runs
    # through a shell that inherits this process's whole environment, including
    # everything apply_best_defaults! wrote. Naming only the pinned keys in the
    # prefix therefore did nothing to stop PROGRESSION=pedal_e_descent reaching
    # the child, where it read as a user pin and became unoverridable. The child
    # needs to be told which keys are real, so declare them.
    pinned_keys = dilla_pinned_keys_decl
    cmd = "cd #{Shellwords.escape(ROOT)} && while true; do " \
          "DILLA_STREAM_LAUNCHED=1 DILLA_STREAM_SUPERVISOR=1 " \
          "DILLA_USER_PINNED_KEYS=#{Shellwords.escape(pinned_keys)} #{env_pass} " \
          "ruby #{Shellwords.escape(ENGINE_FILE)} stream #{bars_count.to_i} 2>&1 | tee -a #{Shellwords.escape(stream_log)}; " \
          "c=$?; [ $c -eq 130 ] && break; " \
          "echo \"$(date -u +%Y-%m-%dT%H:%M:%SZ) stream exited $c — restart in 2s\" | tee -a #{Shellwords.escape(stream_log)}; " \
          "sleep 2; done"
    if darwin? && ENV["DILLA_STREAM_LAUNCHED"] != "1" &&
       (ENV["GROK_AGENT"] == "1" || !$stdout.tty? || ENV["DILLA_FORCE_TERMINAL"] == "1")
      dmesg("agent shell — open terminal for continuous stream", unit: "stream0", parent: "dilla0")
      DillaDmesg.emit("exec0", "osascript terminal stream", parent: "dilla0") if DillaDmesg.verbose?
      system("osascript", "-e", %(tell application "Terminal" to do script "#{cmd.gsub('"', '\\"')}"))
      system("osascript", "-e", 'tell application "Terminal" to activate')
      return
    end
    # In-process continuous loop (agent already has a shell / non-Terminal path).
    exec("zsh", "-c", cmd)
  end
  $stdout.sync = true
  $stderr.sync = true
  acquire_stream_lock!
  prev_track = ENV["TRACK"]
  # USER_PINNED_ENV, not ENV. This is the last of the guards that inferred the
  # operator's intent from "is the key set", and it is the one that cost the most.
  #
  # In a supervisor child every one of these keys arrives populated -- PAD_VOICE
  # and LEAD_VOICE come from DILLA_BEST_DEFAULTS before the first render -- so both
  # flags were true whether or not anybody asked for a pad or a lead. That made
  # apply_track_soul_profile! run with force: false, where style_env_write!
  # refuses to overwrite a key that already has a value, so no track's
  # TRACK_SOUL_PAD/LEAD profile ever landed; and it skipped
  # stream_rotate_voices_and_arps! outright. Measured over one stream's log: 126
  # consecutive renders on pad=stack_soul/held lead=soul_prophet/wonky_spiral,
  # every track in the cycle, which is what "it all sounds like one song" is.
  #
  # Same fix as sync_progression_to_track! got for PROGRESSION, on the pad/lead
  # half of the same guard.
  user_pad_locked = %w[PAD_VOICE PAD_ARP_MODE].any? { |k| !USER_PINNED_ENV[k].to_s.empty? }
  user_lead_locked = %w[LEAD_VOICE LEAD_ARP_MODE].any? { |k| !USER_PINNED_ENV[k].to_s.empty? }
  @stream_user_pad_locked = user_pad_locked
  @stream_user_lead_locked = user_lead_locked
  apply_stream_listenability_defaults!
  order = stream_track_order
  # Ruby can't safely reload this file in-process (the CLI dispatch at the
  # bottom runs unconditionally, so a mid-run `load` would re-trigger it —
  # risk of recursion). exec-ing a fresh process instead is safe: it fully
  # replaces this process with a new one that reads the file from disk
  # again, so edits since the last track take effect automatically between
  # tracks without needing a manual kill+relaunch.
  #
  # The newest of ALL the engine's sources, not dilla.rb's own: since the split
  # nearly every edit lands in lib/engine/, and watching only the entry script
  # would mean a stream that never picks up a change while looking like it does.
  self_mtime = engine_mtime
  mode = if stream_deep?
           "deep+QC"
         elsif stream_iterate_enabled?
           "fast+iterate"
         else
           "fast"
         end
  DillaDmesg.boot!(mode: ENV["RENDER_MODE"] || DEFAULT_RENDER_MODE, cmd: "stream")
  DillaDmesg.stream!(mode:, bars: bars_count, order_n: order.length)
  dmesg("cycle #{order.first(8).join(',')}#{order.length > 8 ? '…' : ''} (ctrl-c stop)", unit: "stream0", parent: "dilla0")
  dmesg("iterate log #{File.basename(STREAM_ITERATE_LOG.to_s)}", unit: "stream0", parent: "dilla0") if stream_iterate_enabled?
  loop do
    order.each_with_index do |item, idx|
      if engine_mtime > self_mtime
        dmesg("engine mtime changed — exec restart", unit: "stream0", parent: "dilla0")
        ENV["DILLA_STREAM_SUPERVISOR"] = "1"
        ENV["DILLA_STREAM_LAUNCHED"] = "1"
        # Carry the real pin set across the restart. Without this the child
        # reads the defaults this process wrote as user intent — see
        # USER_PINNED_ENV's comment.
        ENV["DILLA_USER_PINNED_KEYS"] = dilla_pinned_keys_decl
        exec(Gem.ruby, ENGINE_FILE, "stream", bars_count.to_s)
      end
      track = item.to_s
      apply_track_soul_profile!(track, force: !user_pad_locked && !user_lead_locked)
      stream_rotate_voices_and_arps!(idx) unless user_lead_locked
      restore_explicit_stream_env!
      reassert_pad_lead_locks! unless user_pad_locked
      ENV["TRACK"] = track
      sync_progression_to_track!(track)
      stream_rotate_drums!(idx)
      reassert_dilla_style_locks! if dilla_style? && ENV["STREAM_LOCK"] == "1"
      if radio_bergen_stream_enabled? && rand < 0.38 && (rb = pick_radio_bergen_stream_track!)
        track = rb
        apply_track_soul_profile!(track, force: !user_pad_locked && !user_lead_locked)
        stream_rotate_voices_and_arps!(idx) unless user_lead_locked
        restore_explicit_stream_env!
        reassert_pad_lead_locks! unless user_pad_locked
        ENV["TRACK"] = track
        sync_progression_to_track!(track)
        stream_rotate_drums!(idx)
        stream_track_banner("← playlist.brgen.no")
      else
        stream_track_banner
      end
      begin
        stream_play_track!(bars_count)
      rescue SystemExit, Interrupt
        raise
      rescue Timeout::Error
        warn "stream: #{ENV['TRACK'] || track} timed out after #{stream_track_timeout_sec}s — skipping"
        sleep 1.0
      rescue Exception => e # scan: intentional — track supervisor; SystemExit and Interrupt re-raised above
        warn "stream: #{ENV['TRACK'] || track} failed (#{e.class}) — #{e.message}"
        sleep 1.0
      end
      gap = (ENV["STREAM_GAP"] || "0.55").to_f
      xfade = (ENV["STREAM_CROSSFADE"] || "0.12").to_f
      # Soft silence between tracks (crossfade is intentional gap, not sample morph).
      sleep DillaSeeds.drift_sleep([gap + xfade, 0.05].max) if gap.positive? || xfade.positive?
    end
  end
ensure
  prev_track ? ENV["TRACK"] = prev_track : ENV.delete("TRACK")
end

# Instantly play a modulating bass tone — good for local audio system check.
def bass(root_hz = 55.0)
  require_tools! "ffplay"
  # Warbling sub bass: fundamental + slow pitch LFO + low harmonic content.
  # Models J Dilla's low-end: not a clean sine, has movement and weight.
  lfo_hz = 0.18
  lfo_amt = root_hz * 0.04
  expr_l = "0.45*sin(2*PI*(#{root_hz}+#{lfo_amt}*sin(2*PI*#{lfo_hz}*t))*t)" \
             "+0.08*sin(2*PI*#{(root_hz * 2).round(2)}*t)" \
             "+0.03*sin(2*PI*#{(root_hz * 3).round(2)}*t)"
  filter = "aeval=exprs='#{expr_l}:#{expr_l}',equalizer=f=80:width_type=o:width=2:g=4,lowpass=f=200"
  puts "playing bass #{root_hz}Hz (Ctrl-C to stop)"
  exec "ffplay", "-f", "lavfi", "-i", "aevalsrc=0", "-nodisp", "-af", filter
rescue SystemCallError => e
  abort "ffplay failed: #{e.message}"
end

# --------------------------------------------------------------------------
# engine part: composition_glue
# --------------------------------------------------------------------------
#
# Composition session state and the resolved per-render config.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- J Dilla Time beat engine (MPC3000 cyclic microtiming) ---

COMPOSITION_SECTION_KIND = {
  intro: :intro, verse: :main, hook: :build, bridge: :main,
  solo: :build, breakdown: :breakdown, outro: :outro
}.freeze

def composition_enabled?
  ENV["COMPOSITION"] != "0"
end

def composition_session!(n_bars: nil, track: nil, force_new: false)
  if force_new
    remove_instance_variable(:@composition_session) if instance_variable_defined?(:@composition_session)
  end
  return @composition_session if !force_new && instance_variable_defined?(:@composition_session) && @composition_session && !n_bars
  # What was actually ASKED for, before the "yancey"/"donuts" fallbacks below
  # flatten "unset" and "set to the default" into the same value. Session.load!
  # needs that distinction: a nil means "keep what the file has", and without it
  # every render would overwrite the evolved session's performer with a default
  # nobody chose.
  asked = ->(key) {
    v = ENV[key].to_s.strip
    v.empty? ? nil : v.downcase.tr("-", "_").to_sym
  }
  asked_performer = asked.call("PERFORMER")
  asked_groove = asked.call("GROOVE_DNA")
  asked_track = track || (ENV["TRACK"].to_s.strip.empty? ? nil : ENV["TRACK"].to_s.strip)

  track ||= (ENV["TRACK"] || "timeless").to_s
  n_bars ||= bars
  performer = asked_performer || :yancey
  groove = asked_groove || :donuts
  apply_learned_env_for_track!(track.to_s) if track
  @composition_session = if composition_enabled? && !force_new && File.exist?(DillaComposition::SESSION_PATH)
                           DillaComposition::Session.load!(default_track: track, n_bars:,
                                                           performer: asked_performer,
                                                           groove_dna: asked_groove,
                                                           track: asked_track)
                         else
                           DillaComposition::Session.new(track:, performer:,
                                                         groove_dna: groove, n_bars:)
                         end
  composition_feed_from_learn!(@composition_session)
  @composition_session
end

def reset_composition_session!
  remove_instance_variable(:@composition_session) if instance_variable_defined?(:@composition_session)
end

def dilla_timing_ms(role, bar_index, step_index, timing = nil, beat_p = nil)
  base = cyclic_timing_offset(role, bar_index, step_index, timing, beat_p, cycle: 4)
  return base unless composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
  perf = @composition_session.performer_profile
  groove = @composition_session.groove_profile
  extra = case role
          when :kick_anchor, :kick_sync then perf[:kick_lag_ms]
          when :snare then perf[:snare_early_ms]
          when :hat_down, :hat_up then perf[:hat_late_ms]
          when :bass then (perf[:kick_lag_ms] * 1.6).round(1)
          when :ghost then (perf[:ghost_boost] * 4 - 4).round(1)
          else 0
          end
  dna = if %i[kick_anchor kick_sync].include?(role)
          groove[:kick_offset_ms][step_index % groove[:kick_offset_ms].length]
        elsif %i[hat_down hat_up].include?(role)
          groove[:hat_offset_ms][step_index % groove[:hat_offset_ms].length]
        else
          0
        end
  (base + extra + dna).round(3)
end

def time_of_day_swing_offset
  hour = Time.now.hour
  # Peaks around 2-4am (loosest/latest feel), tightest around 2pm.
  distance_from_3am = [((hour - 3) % 24), (24 - ((hour - 3) % 24))].min
  (4.0 - distance_from_3am * (4.0 / 12.0)).round(1)
end

def dilla_resolve_config
  RingtoneLayer.ringtone_layer_apply_env!
  cfg = enhanced_resolve_config
  cfg = apply_profile_mash!(cfg)
  cfg = apply_form_to_cfg!(cfg)
  prog_override = ENV["PROGRESSION"]
  if prog_override
    cfg = cfg.merge(progression: prog_override.to_s.downcase.tr("-", "_").to_sym)
  end
  cfg
end

def dilla_chord_index(bar, pad_chords, chord_bars:, phrase_bars: nil, chord_bar_lens: nil)
  return 0 if pad_chords.nil? || pad_chords.empty?
  if chord_bar_lens&.any?
    cum = 0
    chord_bar_lens.each_with_index do |len, idx|
      cum += [len, 1].max
      return idx % pad_chords.length if bar < cum
    end
    return (pad_chords.length - 1) % pad_chords.length
  end
  slot = bar / [chord_bars, 1].max
  if la_beat_progression_enabled? || ENV.fetch("LINEAR_CHORD_INDEX", "0") != "0"
    return slot % pad_chords.length
  end
  if phrase_bars
    slots_per_phrase = [phrase_bars / [chord_bars, 1].max, 1].max
    slot % [slots_per_phrase, pad_chords.length].min
  else
    slot % pad_chords.length
  end
end

def dilla_swing_offset(step_index, step_p, swing, quintuplet: false, bar: 0, bpm: 90)
  return 0.0 if swing.to_f <= 0.0 || step_index.even?
  amount = swing.clamp(0.0, 100.0) / 100.0
  tick_sec = step_p / 24.0 # 96 ticks/beat, step_p is a 16th (1/4 beat) -> 24 ticks/step
  # NOTE: swing_jitter_ms is intentionally NOT added here -- every caller of
  # this function separately routes the same (bpm, step, bar) through
  # DillaGroove.apply_event_timing!/apply_pocket_place right after, which
  # already adds swing_jitter_ms itself. Adding it here too silently doubled
  # the jitter magnitude on every single scheduled hit in the whole engine.
  unless quintuplet
    base = (step_p * amount * 0.5)
    ticks = tick_sec.positive? ? (base / tick_sec).round : 0
    return ticks * tick_sec
  end
  # Real Dilla technique (Charnas/Hein analysis): the beat divides into 5
  # equal parts, not the standard 4 (16ths) or 6 (triplets) — the "and"
  # lands at the 3rd of 5 divisions, a 3:2 ratio rather than 2:1. That's a
  # different rhythmic subdivision, not just a different swing percentage.
  beat_p = step_p * 4.0
  quintuplet_pos = beat_p * 3.0 / 5.0
  straight_pos = step_p * 2.0
  base = (quintuplet_pos - straight_pos) * amount
  ticks = tick_sec.positive? ? (base / tick_sec).round : 0
  ticks * tick_sec
end

def dilla_velocity(base, bar_index, step_index, spread: 0.10)
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    spread = @composition_session.performer_profile[:velocity_spread]
    spread += (ENV["VELOCITY_SPREAD_NUDGE"] || "0").to_f
    groove = @composition_session.groove_profile
    curve = groove[:velocity_curve]
    base *= curve[step_index % curve.length] if curve
  end
  track = (ENV["TRACK"] || DillaLofiMachine::DEFAULT_PROFILE).to_s.downcase.tr("-", "_").to_sym
  spread += DillaLofiMachine.humanize_ticks_for(track) * 0.012 if DillaLofiMachine.harmony_profile?(track)
  seed = (bar_index * 1_009) + (step_index * 313) + (base * 10_000).to_i
  rng = Random.new(seed)
  gaussian = Math.sqrt(-2.0 * Math.log([rng.rand, 1e-9].max)) * Math.cos(2.0 * Math::PI * rng.rand)
  [[base * (1.0 + gaussian * spread), 0.03].max, 1.0].min.round(3)
end

GENERATED_STYLES = %i[
  functional planing chromatic_mediant polytonal negative_harmony neapolitan
  major_third_cycle_full backdoor slash modal_interchange tritone_sub
].freeze

def resolve_pad_chord_symbol(n)
  PAD_CHORD_LOOKUP[n] || MODAL_MINOR_CHORDS.find { |c| c[:name] == n } ||
    begin
      DillaLofiMachine.chord_from_symbol(n)
    rescue StandardError
      nil
    end
end

def curated_progression_pads(key)
  sym = key&.to_sym
  return unless sym
  if artist_verified_only? && !ARTIST_VERIFIED_PROGRESSIONS.key?(sym)
    return
  end
  names = artist_verified_chords(sym) || CHORD_PROGRESSIONS[sym]
  return unless names.is_a?(Array) && names.length >= 2
  pads = names.filter_map { |n| resolve_pad_chord_symbol(n) }
  pads.length >= 2 ? pads : nil
end

