    "quartal_west_coast" => "chromatic_mediant_drift",
  },
  "top_track" => nil,
  "promoted_at" => nil,
}.freeze

def deep_merge_learned_engine!(base, overlay)
  overlay.each do |key, val|
    if val.is_a?(Hash) && base[key].is_a?(Hash)
      val.each { |k, v| base[key][k] = v }
    elsif !base.key?(key)
      base[key] = val
    else
      base[key] = val unless val.nil?
    end
  end
  base
end

def load_learned_engine(refresh: false)
  remove_instance_variable(:@learned_engine_cache) if refresh && instance_variable_defined?(:@learned_engine_cache)
  return @learned_engine_cache if instance_variable_defined?(:@learned_engine_cache) && @learned_engine_cache
  base = JSON.parse(JSON.generate(BUILTIN_LEARNED_ENGINE))
  if File.file?(DillaSourceLearn::LEARNED_ENGINE_PATH)
    file_data = JSON.parse(File.read(DillaSourceLearn::LEARNED_ENGINE_PATH))
    deep_merge_learned_engine!(base, file_data)
  end
  @learned_engine_cache = base
rescue StandardError
  @learned_engine_cache = JSON.parse(JSON.generate(BUILTIN_LEARNED_ENGINE))
end

def ensure_learned_engine_seeded!
  return if File.file?(DillaSourceLearn::LEARNED_ENGINE_PATH)
  DillaSourceLearn.ensure_dir!
  save_learned_engine!(JSON.parse(JSON.generate(load_learned_engine)))
end

def save_learned_engine!(data)
  DillaSourceLearn.ensure_dir!
  data["promoted_at"] = Time.now.utc.iso8601
  DillaFrozen.write_json(DillaSourceLearn::LEARNED_ENGINE_PATH, data)
  @learned_engine_cache = data
  data
end

def learned_chord_pad(sym)
  PAD_CHORD_LOOKUP[sym] || MODAL_MINOR_CHORDS.find { |c| c[:name] == sym } ||
    (DillaLofiMachine.chord_from_symbol(sym) rescue nil)
end

def learned_progression_pads(key)
  syms = load_learned_engine.dig("progressions", key.to_s)
  return unless syms.is_a?(Array) && syms.length >= 2
  syms.filter_map { |n| learned_chord_pad(n) }
end

def learned_drum_steps(role)
  track = (ENV["TRACK"] || "").to_s
  eng = load_learned_engine
  grid = eng.dig("drum_grids", track) || eng.dig("drum_grids", eng.dig("track_aliases", track))
  return unless grid.is_a?(Hash)
  case role
  when :kicks then Array(grid["kicks"] || grid["wonky_kicks"] || grid["flylo_kicks"] || grid[:kicks])
  when :snares then Array(grid["snares"] || grid["wonky_snares"] || grid["flylo_snares"] || grid[:snares])
  when :hats then Array(grid["hats"] || grid["wonky_hats"] || grid["flylo_hats"] || grid[:hats])
  end
end

def apply_learned_env_for_track!(track)
  return unless track && !track.to_s.empty?
  eng = load_learned_engine
  t = track.to_s
  alias_key = eng.dig("track_aliases", t)
  # Never remap a curated catalog TRACK onto a learned promo progression.
  # Opt in with LEARNED_PROGRESSION=1 when you want that behavior.
  allow_learned_prog = ENV.fetch("LEARNED_PROGRESSION", "0") != "0"
  has_catalog = CHORD_PROGRESSIONS.key?(t.to_sym) ||
                DillaLofiMachine.harmony_profile?(t.to_sym) ||
                CHORD_PROGRESSIONS.key?(ENV["PROGRESSION"].to_s.downcase.tr("-", "_").to_sym)
  if allow_learned_prog && !has_catalog
    prog_keys = [alias_key, t, eng["top_track"]].compact.uniq
    prog_keys.each do |pk|
      next unless eng.dig("progressions", pk.to_s)&.length.to_i >= 2
      ENV["PROGRESSION"] = pk.to_s if ENV["PROGRESSION"].nil? || ENV["PROGRESSION"].empty?
      break
    end
  end
  grid = eng.dig("drum_grids", t) || (alias_key && eng.dig("drum_grids", alias_key))
  if grid.is_a?(Hash)
    ENV["BPM"] = grid["bpm"].to_s if grid["bpm"] && (ENV["BPM"].nil? || ENV["BPM"].empty?)
  end
  cal = eng.dig("calibrations", "global")
  return unless cal.is_a?(Hash)
    ENV["SWING"] = cal["swing"].to_s if cal["swing"] && (ENV["SWING"].nil? || ENV["SWING"].empty?)
    ENV["BPM"] = cal["bpm"].to_s if cal["bpm"] && (ENV["BPM"].nil? || ENV["BPM"].empty?)

end

def learn_catalog_top_hint
  eng = load_learned_engine
  if eng["top_track"]
    return { track: eng["top_track"], voicing: :kenny_barron, performer: "yancey", groove_dna: "donuts" }
  end
  cat = DillaSourceLearn.load_playlist_catalog
  tally = Hash.new(0)
  Array(cat["tracks"]).each do |row|
    eh = row["engine_hints"]
    cd = row["copyable_dna"]
    hint = (eh.is_a?(Hash) ? (eh["track"] || eh[:track]) : nil) ||
           (cd.is_a?(Hash) && cd["engine"].is_a?(Hash) ? (cd["engine"]["track"] || cd["engine"][:track]) : nil)
    tally[hint.to_s] += 1 if hint && !hint.to_s.empty?
  end
  top = tally.max_by { |_, c| c }&.first
  top ? { track: top.to_sym, performer: "yancey", groove_dna: "donuts" } : nil
end

def playlist_row_key(row)
  id = row[:youtube_id].to_s.strip
  id.empty? ? RadioBergenStudy.slug(row[:artist], row[:title]) : id
end

def learn_promote!(min_chords: 4)
  DillaSourceLearn.ensure_dir!
  catalog = DillaSourceLearn.load_playlist_catalog
  eng = load_learned_engine(refresh: true)
  promoted = 0
  Array(catalog["tracks"]).each do |raw|
    t = raw.transform_keys(&:to_s)
    next if t["id"] == "test_slug"
    dna = t["copyable_dna"] || {}
    harm = (dna["harmony"].is_a?(Hash) ? dna["harmony"]["progression"] : nil) || t["progression_symbols"]
    harm = Array(harm).map(&:to_s).reject(&:empty?)
    next unless harm.length >= min_chords
    slug = t["id"].to_s
    prog_key = "learned_#{slug}"
    eng["progressions"][prog_key] = harm
    eh = t["engine_hints"]
    engine_track = (eh.is_a?(Hash) ? (eh["track"] || eh[:track]) : nil) ||
                   (dna["engine"].is_a?(Hash) ? (dna["engine"]["track"] || dna["engine"][:track]) : nil) || slug
    eng["track_aliases"][engine_track.to_s] = prog_key
    eng["track_aliases"][slug] = prog_key
    drums = dna["drums"]
    if drums.is_a?(Hash) && (drums["kicks"] || drums["snares"])
      eng["drum_grids"][engine_track.to_s] = drums
      eng["drum_grids"][slug] = drums
    end
    promoted += 1
  end
  eng["top_track"] = learn_catalog_top_hint&.dig(:track)&.to_s || eng["top_track"]
  save_learned_engine!(eng)
  warn "learn-promote: #{promoted} progression(s) → #{DillaSourceLearn::LEARNED_ENGINE_PATH}" unless ENV["DILLA_QUIET"] == "1"
  { promoted:, path: DillaSourceLearn::LEARNED_ENGINE_PATH }
end

def learn_calibrate!(audio_root: nil)
  data = RadioBergenStudy.dossiers!(audio_root:)
  eng = load_learned_engine(refresh: true)
  bpms = []
  swings = Hash.new(0)
  Array(data[:tracks]).each do |row|
    measured = row[:analysis]
    ref = row[:production_dossier]
    next unless measured&.dig(:measured)
    id = row[:id].to_s
    eng["calibrations"][id] = {
      bpm_measured: measured[:bpm_estimate],
      bpm_curated: ref&.dig(:bpm),
      swing_hint: measured.dig(:dynamics, :swing_hint),
    }.compact
    bpms << measured[:bpm_estimate] if measured[:bpm_estimate]
    sh = measured.dig(:dynamics, :swing_hint)
    swings[sh] += 1 if sh
  end
  if bpms.any?
    eng["calibrations"]["global"] = {
      "bpm" => (bpms.sum / bpms.length).round,
      "swing" => (DillaLofiMachine::DRUM_PRESETS[:dilla_slight][:swing] + (swings["laid_back"] || 0) * 2 -
                  (swings["pushed"] || 0)).clamp(52, 62),
    }
  end
  save_learned_engine!(eng)
  puts "learn-calibrate: #{eng['calibrations'].length} entries (global bpm=#{eng.dig('calibrations', 'global', 'bpm')})"
  eng
end

def learn_diff_dossiers!(audio_root: nil)
  dossiers = RadioBergenStudy.dossiers!(audio_root:)
  catalog = DillaSourceLearn.load_playlist_catalog
  cat_by_id = Array(catalog["tracks"]).to_h { |t| [t["id"], t] }
  diffs = []
  Array(dossiers[:tracks]).each do |row|
    id = row[:id].to_s
    ref = row[:production_dossier]
    measured = row[:analysis]
    learned = cat_by_id[id]
    entry = {
      id:, artist: row[:artist], title: row[:title],
      curated_bpm: ref&.dig(:bpm), measured_bpm: measured&.dig(:bpm_estimate),
      curated_harmony: ref&.dig(:harmony), curated_drums: ref&.dig(:drums),
      measured_swing: measured&.dig(:dynamics, :swing_hint),
      learned_progression: (lp = learned&.[]("copyable_dna")) && lp["harmony"].is_a?(Hash) ? lp["harmony"]["progression"] : nil,
      learned_drums: (lp = learned&.[]("copyable_dna")) ? lp["drums"] : nil,
      calibration_notes: row[:calibration_notes]
    }
    if ref && measured&.dig(:bpm_estimate) && ref[:bpm]
      entry[:bpm_delta] = (measured[:bpm_estimate] - ref[:bpm]).round(1)
    end
    diffs << entry
  end
  payload = { generated_at: Time.now.utc.iso8601, tracks: diffs }
  DillaSourceLearn.ensure_dir!
  DillaFrozen.write_json(DillaSourceLearn::DOSSIER_DIFF_PATH, payload)
  puts "learn-diff: #{diffs.length} tracks → #{DillaSourceLearn::DOSSIER_DIFF_PATH}"
  payload
end

def composition_feed_from_learn!(sess)
  return unless sess
  apply_learned_env_for_track!(sess.track.to_s)
  eng = load_learned_engine
  prog_key = eng.dig("track_aliases", sess.track.to_s) || sess.track.to_s
  syms = eng.dig("progressions", prog_key)
  return unless syms.is_a?(Array) && syms.length >= 2
  sess.instance_variable_set(:@learned_progression, syms)
end

# --------------------------------------------------------------------------
# engine part: dilla_progression
# --------------------------------------------------------------------------
#
# Choosing and voice-leading the progression for a render.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def safe_producer_progression(track)
  DillaLofiMachine.progression_for(track)
rescue StandardError => e
  warn "progression_for(#{track}): #{e.message}"
  nil
end

def dilla_progression(mode = :maj7_minor_cycle)
  track = (ENV["TRACK"] || DillaLofiMachine::DEFAULT_PROFILE).to_s.downcase.tr("-", "_").to_sym
  mode_sym = mode.to_sym
  prog_env = ENV["PROGRESSION"].to_s.downcase.tr("-", "_")
  prog_sym = prog_env.empty? ? nil : prog_env.to_sym
  # Catalog first. Learned aliases were collapsing every TRACK into a truncated
  # 6-chord promo loop (Dbmaj9…Abmaj9low) — theory and sound both suffered.
  prefer_learned = ENV.fetch("LEARNED_PROGRESSION", "0") != "0"
  catalog_keys = [prog_sym, mode_sym, track].compact.uniq
  unless prefer_learned
    catalog_keys.each do |key|
      pads = curated_progression_pads(key)
      return voice_led_pad_progression(pads) if pads&.length.to_i >= 2
      pads = safe_producer_progression(key)
      return voice_led_pad_progression(pads) if pads&.length.to_i >= 2
    end
  end
  eng = load_learned_engine
  learned_keys = [eng.dig("track_aliases", track.to_s), track.to_s, mode_sym.to_s, prog_env].compact.uniq
  learned_keys.each do |key|
    next if key.to_s.empty?
    pads = learned_progression_pads(key)
    return voice_led_pad_progression(pads) if pads&.length.to_i >= 2
  end
  if prefer_learned
    catalog_keys.each do |key|
      pads = curated_progression_pads(key)
      return voice_led_pad_progression(pads) if pads&.length.to_i >= 2
      pads = safe_producer_progression(key)
      return voice_led_pad_progression(pads) if pads&.length.to_i >= 2
    end
  end
  if (producer_pads = safe_producer_progression(track))&.length.to_i >= 2
    return voice_led_pad_progression(producer_pads)
  end
  sonic = sonic_profile_for(track)
  engine_pads = progression_from_engine(sonic, mode)
  return voice_led_pad_progression(engine_pads) if engine_pads&.any?

  if GENERATED_STYLES.include?(mode.to_sym) || mode.to_sym == :generated
    root_hz = (ENV["GEN_ROOT"] || 130.81).to_f
    gen_mode = (ENV["GEN_MODE"] || "minor").to_sym
    length = (ENV["GEN_LENGTH"] || 8).to_i
    seed = ENV["GEN_SEED"]&.to_i
    style = mode.to_sym == :generated ? (ENV["GEN_STYLE"] || "functional").to_sym : mode.to_sym
    style = :functional if DillaHarmony.block_generated?(track, style)
    routed = route_generated_style(style, root_hz:, mode: gen_mode, length:, seed:)
    return voice_led_pad_progression(routed) if routed
    case style
    when :planing then return voice_led_pad_progression(generate_planing_progression(root_hz:, mode: gen_mode, length:, seed:))
    when :chromatic_mediant then return voice_led_pad_progression(generate_chromatic_mediant_progression(root_hz:, length:, seed:))
    when :polytonal then return voice_led_pad_progression(generate_polytonal_progression(root_hz:, mode: gen_mode, length:, seed:))
    when :negative_harmony then return voice_led_pad_progression(generate_negative_harmony_progression(root_hz:, mode: gen_mode, length:, seed:))
    when :neapolitan then return voice_led_pad_progression(generate_neapolitan_progression(root_hz:, length:, seed:))
    else return voice_led_pad_progression(generate_progression(root_hz:, mode: gen_mode, length:, seed:))
    end
  end
  names = CHORD_PROGRESSIONS.fetch(mode.to_sym, CHORD_PROGRESSIONS.fetch(:soul))
  voice_led_pad_progression(names.filter_map { |n| resolve_pad_chord_symbol(n) })
end

# Closest-tone voice leading + close jazz voicing so pads don't thrash register.
# Not every chord should bloom.
#
# 68% of the 1366 chords in the catalogue are ninths — m9 at 35%, maj9 at 33% —
# against 0.9% maj7 and 2.6% m7. Voiced literally, every chord is as lush as
# every other, so none of them arrive: an extension only reads as colour when
# something plainer sits next to it. This is why the harmony felt uniform rather
# than thin.
#
# Rather than rewrite 248 curated progressions, the extension is thinned at
# voicing time on passing chords — which is what a keys player does. The first
# and last chord keep their full voicing, because those are the arrival and the
# turnaround; interior chords lose their topmost tone on an alternating basis.
# Deterministic by position, so a progression voices the same way every render.
#
# HARMONIC_VARIETY=0 voices every chord in full, as before.
def harmonic_variety? = ENV.fetch("HARMONIC_VARIETY", "1") != "0"

def thin_passing_extensions(pads)
  return pads unless harmonic_variety? && pads.length >= 4

  pads.map.with_index do |ch, i|
    next ch unless ch.is_a?(Hash)
    next ch if i.zero? || i == pads.length - 1 || i.odd?

    hz = Array(ch[:hz])
    # Four voices is already a seventh chord; thinning below that removes chord
    # tones rather than colour, so leave those alone.
    next ch if hz.length <= 4

    ch.merge(hz: hz.sort.first(hz.length - 1))
  end
end

def voice_led_pad_progression(pads)
  return pads if pads.nil? || pads.length < 2
  return pads if ENV.fetch("VOICE_LEAD_PADS", "1") == "0"

  pads = thin_passing_extensions(pads)
  style = (ENV["VOICING"] || "rootless").to_s.downcase.tr("-", "_").to_sym
  style = :rootless unless DillaHarmony::VOICING_STYLES.include?(style)
  # `style` has to reach more than the `!= :cluster` test. Computed and consulted
  # only there, VOICING and the per-track VOICING_ROTATION select nothing: every render gets
  # the default spread shape on chord one and raw template stacks after it. The
  # style has to reach the voicing engine for the rotation to be audible.
  led = DillaHarmony.voice_lead_chords(pads, rootless: style != :cluster, voicing: style)
  return pads if led.nil? || led.empty?
  led.map.with_index do |ch, i|
    src = pads[i] || pads.last
    name = ch.is_a?(Hash) ? (ch[:name] || src[:name]) : src[:name]
    hz = ch.is_a?(Hash) ? ch[:hz] : ch
    { name:, hz:, bass_hz: src[:bass_hz] || src[:hz]&.min }
  end
rescue StandardError
  pads
end

def dilla_chord_bass_hz(chord)
  return 43.65 unless chord.is_a?(Hash)
  # Prefer the chord's declared bass over the lowest voiced tone. Slash chords
  # (D/E, Db/E, … — the whole Get Dis Money cycle) carry their pedal in
  # :bass_hz, and voice_led_pad_progression deliberately collapses :hz into a
  # narrow mid register for smooth pad motion. Taking hz.min there meant the
  # bass followed a voiced upper tone instead of the root: for D/E it played
  # G#3 (207.7 Hz) rather than E2 (82.4 Hz) — wrong note, and over an octave
  # above bass register, so the pedal that defines the progression vanished
  # and the track had no low end. Rootless pads over a real bass is the
  # correct division of labour; :bass_hz is what makes it work.
  bass = chord[:bass_hz] || (chord[:hz]&.any? ? chord[:hz].min : nil)
  bass || 43.65
end

def hz_to_midi(hz)
  DillaHarmony.hz_to_midi(hz)
end

def midi_to_hz(midi)
  DillaHarmony.midi_to_hz(midi)
end

def voice_lead_chords(chords)
  DillaHarmony.voice_lead_chords(chords)
end

# --------------------------------------------------------------------------
# engine part: dilla_drums
# --------------------------------------------------------------------------
#
# The Dilla drum part: patterns, fills, ghosts, sections.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def drum_feel_key(feel)
  feel = feel.to_sym
  return feel if DRUM_PATTERN_SETS.key?(feel)
  :default
end

# Morphing the kit across a track: Detroit, then the LA beat scene, then
# industrial techno.
#
# A track has exactly one feel. Patterns rotate inside it bar to bar, but the
# vocabulary never changes, so a long piece states one idea for its whole
# length. The operator asked for the drums to travel between the three
# families "smoothly", which is a thing this had no way to express.
#
# The voices hand over one at a time, and that is the whole trick. Switching
# every voice on the same bar is a cut -- the listener hears a new song. A
# producer moves the hats first, because the hats are the least load-bearing
# part of the bar and the ear forgives them changing; then the snare, which is
# the reference the bar is counted against; and the kick last, because the kick
# is what makes it the same piece of music. By the time the kick moves, the
# rest of the kit has already been in the new idiom for a while and the change
# lands as arrival rather than as edit.
#
# DRUM_MORPH=0 turns it off and every voice takes the track's own feel, which
# is the previous behaviour exactly.
DRUM_MORPH_PATH = %i[detroit_stumble la_beat_scene techno_drive].freeze

# Fractions of the track at which each voice has completed its move. Hats are
# a third of the way ahead of the kick throughout.
# A bigger lead means this voice is further along the path, so it changes
# EARLIER. The hats therefore carry the largest number and the kick zero --
# written the other way round first, which put the kick in the new idiom four
# bars in while the hats were still in the old one. That is the handover
# backwards: the load-bearing voice moved first and the change read as a cut.
DRUM_MORPH_LEAD = { hats: 0.30, opens: 0.30, ghosts: 0.20, snares: 0.12, kicks: 0.0 }.freeze

# OFF by default, and defaulting it on was a regression.
#
# The morph overrides the feel the preset chose. On one long piece that is the
# point; across a 451-track showcase it means every track wears the same
# Detroit -> LA -> techno journey regardless of what it is, and every one of
# them ends in the same techno. The catalogue exists to show variety and this
# homogenised it -- the progressions were all still there, playing under
# identical drums, which is why the demo sounded like it was repeating itself.
#
# A default that overrides a per-track decision is not a default, it is an
# override. DRUM_MORPH=1 asks for it.
def drum_morph_enabled?
  ENV.fetch("DRUM_MORPH", "0") != "0"
end

def drum_morph_feel(bar, role)
  return nil unless drum_morph_enabled?

  n_bars = @render_total_bars.to_i
  return nil unless n_bars.positive?

  path = DRUM_MORPH_PATH
  # Where this voice is in its own journey: its lead pulls it forward, so at
  # any moment the hats are further along the path than the kick.
  lead = DRUM_MORPH_LEAD.fetch(role.to_sym, 0.15)
  t = ((bar.to_f / n_bars) + lead).clamp(0.0, 0.999)
  path[(t * path.length).floor.clamp(0, path.length - 1)]
end

def drum_pattern_seed(feel)
  (stable_hash(feel) + (@render_seed || 0)) % 10_000
end

def drum_pattern_pick(bar, feel, role)
  if (learned = learned_drum_steps(role))&.any?
    return learned.dup
  end
  # A morph overrides the track's feel for THIS voice only, which is what makes
  # the handover staggered rather than simultaneous.
  feel = drum_morph_feel(bar, role) || feel
  sets = DRUM_PATTERN_SETS.fetch(drum_feel_key(feel))
  # fetch(role) raised KeyError when a feel has no entry for this voice, and the
  # morph made that reachable: callers guard on the TRACK's feel
  # (`if sets[:perc]` in dilla_ghost_steps) while this method had already swapped
  # in the morphed one, so the guard checked a different hash from the fetch.
  # 94 KeyErrors across ~47 tracks in one run. A missing voice is a legitimate
  # thing for a feel to say -- it means "this idiom has no percussion" -- so it
  # returns nothing instead of raising.
  pool = sets[role]
  return [] if pool.nil? || pool.empty?
  seed = drum_pattern_seed(feel)
  phrase = bar % 4
  idx = (phrase + seed + (bar / 8)) % pool.length
  steps = Array(pool[idx]).dup
  # Fill bar: extra kick cluster on the & of 4 (step 15) for Dilla-style turns.
  if role == :kicks && bar.positive? && (bar % 8) == 7
    steps << 15 unless steps.include?(15)
  end
  steps.uniq.sort
end

def dilla_kick_pattern(bar, _n_bars, feel)
  drum_pattern_pick(bar, feel, :kicks)
end

def dilla_snare_steps(bar, feel, section:)
  return [] if section == :breakdown
  steps = if DillaGroove.kick_snare_swap?
            drum_pattern_pick(bar, feel, :kicks)
          else
            drum_pattern_pick(bar, feel, :snares)
          end
  pool = DRUM_PATTERN_SETS.fetch(drum_feel_key(feel), DRUM_PATTERN_SETS[:default])[:snares]&.flatten || steps
  steps = DillaGroove.markov_steps(bar, :snare, steps + pool) if steps.any?
  if halftime?
    steps = steps.map { |s| s == 4 ? 8 : s }.reject { |s| s == 12 && bar.even? }
    steps = [8] if steps.empty?
  end
  steps -= [10, 14] if section == :intro
  steps.uniq.sort
end

def dilla_fill_bar?(bar, section)
  return false if %i[intro breakdown].include?(section)
  tier = ghost_tier_for(bar, section)
  fill_mul = GHOST_TIERS.fetch(tier, GHOST_TIERS[:pocket])[:fill_mul]
  return false if tier == :whisper && bar % 16 != 15
  on_phrase = bar % 8 == 7 || (bar.positive? && bar % 16 == 15)
  return false unless on_phrase
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    prof = @composition_session.profile_at(bar)
    rate = prof[:fill_rate].to_f * fill_mul
    return Random.new(bar * 31 + @composition_session.generation).rand < rate.clamp(0.05, 0.95)
  end
  tier == :accent || bar % 8 == 7 || (bar.positive? && bar % 16 == 15)
end

def schedule_drum_fills!(events, bar, base, step_p, swing, quintuplet, timing, beat_p, sec_gain, feel, section)
  return unless dilla_fill_bar?(bar, section)
  seed = drum_pattern_seed(feel) + bar
  bpm = (60.0 / beat_p)
  DRUM_FILL_SETS[:snare][(bar / 8 + seed) % DRUM_FILL_SETS[:snare].length].each do |step|
    t = [base + step * step_p +
         dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm:) +
         dilla_timing_ms(:snare, bar, step, timing, beat_p) / 1000.0, 0.0].max
    t = DillaGroove.apply_event_timing!(t, role: :snare, beat_p:, bar:, step:,
                                        bpm:, section:)
    vel = step >= 10 ? 0.54 : 0.46
    events[:snare] << [t.round(6), dilla_velocity(vel, bar, step, spread: 0.06) * sec_gain]
  end
  if kicks_enabled?
    DRUM_FILL_SETS[:kicks][(bar / 8 + seed) % DRUM_FILL_SETS[:kicks].length].each do |step|
      t = [base + step * step_p +
           dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm:) +
           dilla_timing_ms(:kick_sync, bar, step, timing, beat_p) / 1000.0, 0.0].max
      t = DillaGroove.apply_event_timing!(t, role: :kick, beat_p:, bar:, step:,
                                          bpm:, section:)
      events[:kick] << [t.round(6), dilla_velocity(0.4, bar, step, spread: 0.05) * sec_gain * kick_velocity_scale]
    end
  end
  tier = ghost_tier_for(bar, section)
  DRUM_FILL_SETS[:ghosts][(bar / 8 + seed) % DRUM_FILL_SETS[:ghosts].length].each do |step|
    t = [base + step * step_p +
         dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm:) +
         dilla_timing_ms(:ghost, bar, step, timing, beat_p) / 1000.0, 0.0].max
    t = DillaGroove.apply_event_timing!(t, role: :ghost, beat_p:, bar:, step:,
                                        bpm:, section:)
    vel = apply_ghost_tier_vel(dilla_velocity(0.32, bar, step, spread: 0.07) * sec_gain, tier)
    events[:ghost] << [t.round(6), vel]
  end
end

def schedule_hat_roll!(events, bar, base, step_p, swing, quintuplet, timing, beat_p, sec_gain, section)
  return unless bar % 8 == 7 && !%i[intro breakdown].include?(section)
  bpm = (60.0 / beat_p)
  # 32nd-note roll on the last beat of every 8-bar phrase (steps 12–15.75).
  16.times do |sub|
    step = 12.0 + sub * 0.25
    t = [base + step * step_p +
         dilla_swing_offset(step.floor, step_p, swing, quintuplet:, bar:, bpm:) +
         dilla_timing_ms(:hat_up, bar, step.floor, timing, beat_p) / 1000.0, 0.0].max
    t = DillaGroove.apply_event_timing!(t, role: :hat_up, beat_p:, bar:, step: step.floor,
                                        bpm:, section:)
    accel = 0.34 + (sub / 15.0) * 0.22
    events[:hat] << [t.round(6), dilla_velocity(accel, bar, step.floor, spread: 0.1) * sec_gain]
  end
end

def dilla_ghost_steps(bar, feel, section: :main)
  steps = drum_pattern_pick(bar, feel, :ghosts)
  sets = DRUM_PATTERN_SETS.fetch(drum_feel_key(feel))
  steps += drum_pattern_pick(bar, feel, :perc) if sets[:perc]
  pool = sets[:ghosts]&.flatten || steps
  steps = DillaGroove.markov_steps(bar, :ghost, steps + pool) if steps.any? && ENV["MARKOV_DRUMS"] != "0"
  tier = ghost_tier_for(bar, section)
  scale = GHOST_TIERS.fetch(tier, GHOST_TIERS[:pocket])[:steps_scale]
  if scale < 1.0
    steps = steps.select.with_index { |_, i| i.even? || bar.odd? }
  elsif scale > 1.0
    extras = [2, 6, 14].select { |s| !steps.include?(s) && Random.new(bar * 71 + stable_hash(feel)).rand < 0.38 }
    steps += extras
  end
  steps.uniq.sort
end

def dilla_open_steps(bar, feel, section:)
  return [] if section == :breakdown
  opens = DRUM_PATTERN_SETS.fetch(drum_feel_key(feel))[:opens]
  return [] unless opens
  return opens if feel == :loose_pocket && bar % 8 == 5
  return [opens[(bar / 2) % opens.length]] if [1, 3].include?(bar % 4)
  []
end

def dilla_section_bounds(n_bars)
  intro = [[(n_bars * 0.12).round, 4].max, (n_bars * 0.22).round].min
  outro = [[(n_bars * 0.10).round, 4].max, (n_bars * 0.18).round].min
  body = [n_bars - intro - outro, 8].max
  # A phrase length, never longer than the body. Both halves of that matter, and
  # each was learned from a render that sounded broken.
  #
  # Never longer than the body: with the old floor of 16, a 16-bar render had a
  # 9-bar body against a 16-bar cycle, so `pos` never exceeded 8 while breakdown
  # began at 12 and build at 14 -- both unreachable. Every render up to about 21
  # bars was intro, main, outro and nothing else, which is exactly what "loops
  # over and over with no variation" sounds like. The arrangement was never
  # missing; it was unreachable at the lengths anyone actually renders.
  #
  # But a phrase length, not the whole body: letting the cycle equal the body
  # meant a 32-bar render had a 24-bar cycle -- eighteen consecutive bars of
  # :main with a single breakdown near the end. The loudness envelope measured
  # 3.1 dB of range against 8.6 dB on demo29, one of the two tracks kept on
  # merit, whose envelope dips every four or five bars. Flat arrangement, not
  # flat compression: the same render measures LRA 1.8 with loudnorm disabled.
  #
  # SECTION_CYCLE overrides it; 16 is two breakdowns across 32 bars, 8 is four.
  #
  # Floor of 5, not 4. At 4 the two thresholds collide -- brk = (4*0.75).floor = 3
  # and bld = (4*0.875).floor = 3 -- so `pos >= brk && pos < bld` is never true and
  # :breakdown becomes unreachable, every one of those bars landing on :build
  # instead. That is the opposite of what a shorter cycle is asked for. 5 is the
  # shortest cycle that can express both (brk 3, bld 4), and an unparseable value
  # reaches the floor the same way, since "".to_i is 0.
  cycle = [(ENV["SECTION_CYCLE"] || 8).to_i, body].min.clamp(5, 32)
  { intro:, outro:, cycle:, body_start: intro }
end

def dilla_section_legacy(bar, n_bars)
  b = dilla_section_bounds(n_bars)
  return :outro if bar >= n_bars - b[:outro]
  return :intro if bar < b[:intro]
  pos = (bar - b[:body_start]) % b[:cycle]
  brk = (b[:cycle] * 0.75).floor
  bld = (b[:cycle] * 0.875).floor
  return :breakdown if pos >= brk && pos < bld
  return :build if pos >= bld
  :main
end

# --- Parts entering and leaving --------------------------------------------
#
# The engine has known about sections for a long time -- intro, main, breakdown,
# build, outro, with twenty-six places in this file that branch on which one is
# playing. What none of them did was change WHICH INSTRUMENTS are sounding. Every
# layer started at bar one, played to the end, and stopped. Bar 1 and bar 16 had
# the same parts at the same density, which is what "it loops over and over" and
# "most were repetitive trash" describe: not a lack of ideas, a lack of anything
# arriving or leaving.
#
# An arrangement is mostly subtraction. The intro states the chords with almost
# nothing under them; the drums arrive and that arrival is the event; the
# breakdown takes them away again so their return means something; the outro
# removes one thing at a time. None of that needs new material -- it is the
# material already rendered, gated in time.
#
# Gains rather than mutes, mostly. A layer dropping to zero and back is a hard
# edit and sounds like one; dropping to a third leaves the part audible as a
# memory of itself. Zero is reserved for the places a hard entrance is the point.
#
# :harm is here with no reductions on purpose. render_dilla asks for a :harm
# envelope on the analog pad and always has, and because the table never
# mentioned :harm that call has been a silent no-op for its whole life --
# section_layer_windows returns an empty list for an unknown layer and
# apply_section_envelope returns the chain untouched. Declaring it empty makes
# the two lists agree without changing a single sample: the pad stays at full
# level in every section, exactly as it does today. What it buys is that
# SECTION_LAYERS_DECLARED and SECTION_LAYERS_APPLIED can now be compared, so the
# next layer wired to nothing fails a test instead of looking like a feature.
#
# Giving the pads an actual section shape is a musical decision and belongs to
# the operator, not to the commit that noticed the wiring was dead.
SECTION_LAYER_GAIN = {
  intro:     { drums: 0.0,  bass: 0.30, lead: 0.0,  chops: 0.0,  sample: 0.55, harm: 1.0 },
  main:      { harm: 1.0 },
  breakdown: { drums: 0.0,  bass: 0.55, chops: 0.0, harm: 1.0 },
  build:     { lead: 0.0,   sample: 0.7, harm: 1.0 },
  turn:      { lead: 0.0,   harm: 1.0 },
  outro:     { drums: 0.45, bass: 0.5,  lead: 0.0,  chops: 0.0, harm: 1.0 },
}.freeze

# The arrangement the table above declines to make, offered rather than imposed.
#
# The note above is right that giving the pads a section shape is the operator's
# decision, and it stays the operator's: nothing here is reached unless
# SECTION_LAYERS=full, and the default table is untouched. What was missing is
# that the decision could not be TAKEN -- there was no shape to switch on, so
# "belongs to the operator" meant "belongs to nobody".
#
# Why it is worth having something to switch on. Measured on a default 32-bar
# render: full-band RMS across eight four-bar sections came out -19.9, -20.7,
# -21.0, -20.9, -20.9, -21.3, -20.8, -20.6. A 1.4 dB spread over the whole track,
# and flat inside 0.7 dB after bar 8. The drums, bass and sample DO follow the
# table -- their envelopes are in the graph and they work; the exact clause was
# tested in isolation and mutes by 80 dB. But that render's six channels were
# drums, harm, bass, analogpad, vinyl and rumble at weights 0.95, 1.12, 1.15,
# 0.62, 0.35 and 0.25, and four of the six -- carrying more than half the
# weight, including the loudest single channel -- had no section shape at all.
# An arrangement that moves the quiet half of a mix is not audible as one.
#
# The numbers below are gains, and the first version of this table used them as
# gains: pads at 0.72 through the intro, 1.12 in a breakdown, texture up to 1.85.
# It measured as nothing, and the reason turned out to be worth more than the
# table.
#
# An arrangement is a change in WHAT IS PLAYING, not in how loud it is. Measured
# on a 5.8-minute render, altering it at a known second and asking a spectral
# boundary detector what it can see:
#
#   a timbre change (lowpass to 800 Hz)   novelty peak 0.0044 -> 0.0624, found
#                                         at 173.9 s against an actual 174.0
#   a 6 dB level drop at the same second  0.0044 -> 0.0066, and nine spurious
#                                         boundaries rather than one real one
#
# Fourteen times against one and a half. And the two records this engine is
# measured against reach peaks of 0.0131 and 0.0252 with two to four boundaries
# each, while dilla reached 0.0044 with none -- at 32 bars and, unchanged, at
# 128. Four times the material and the same structure, because every lever the
# engine had (this table, FORM, FORM_FIT, the grain settings) moves a level.
#
# So the layers that carry an arrangement LEAVE. A gain of 0.0 is a part not
# playing, which is the one thing in this table that produces a boundary, and it
# is now what the intro and the breakdown do to the harmonic bus -- the loudest
# channel in the mix and, until this, the one that never stopped.
#
# Texture is the exception and stays a gain: vinyl noise and turntable rumble
# come UP when the band drops out, because a record's surface is what is audible
# when nothing else is, and that is the difference between a breakdown and a
# hole. It is not carrying the boundary; the parts that stop are.
SECTION_LAYER_GAIN_ARRANGED = {
# harm ducks here rather than stopping, and that is a deliberate half-measure.
#
# The measurements above argue for stopping: a timbre change reads 14x against
# a level change's 1.5x. What is missing is evidence that a removal here
# SOUNDS better, as opposed to measuring better -- and the harmony bus is the
# loudest channel in the mix, so taking it out for a whole section is a large
# musical decision to make on a detector's behalf.
#
# The mechanism is not in doubt. Section envelopes were verified end to end,
# against a reference render with the kit turned off entirely: over a 16.4 s
# intro where the table mutes the drums, kick-band RMS reads -29.0 dB against
# -29.6 for a take with no kit at all and -25.4 for one with the envelope
# disabled. It lands on the no-kit reference. In a control window where the
# same take plays its kit, it reads -25.6 against -25.8. The envelope does
# exactly what it says.
#
# What that reference also shows is why this is easy to get wrong: the kit's
# ENTIRE contribution to that band is 4.2 dB, because it is 21% of the mix
# weight sitting under a bass at 1.15. A perfect mute looks like 3.6 dB here,
# not 40, and without a no-kit arm to compare against it reads as a failure.
# Two days of hypotheses were built on exactly that misreading.
#
# So: the removal is available (set 0.0) and is not the default. See the note
# on FORM_FIT for the other half -- a section only reads as one if it also
# lasts longer than a bar.
  # harm STOPS in the intro and the breakdown, and the duration rule below is
  # what makes that safe.
  #
  # The measurements say a section boundary needs a change in what is PLAYING,
  # not in how loud it is: on a real render a timbre change at a known second
  # moved the novelty detector 14x and a 6 dB level change 1.5x. So the loudest
  # channel in the mix leaves, rather than ducking.
  #
  # The reason this was a duck until now was a misreading, and it is worth
  # keeping. A 128-bar take with the harmony muted for 43 seconds measured
  # 1.6 dB LOUDER across 250-2000 Hz than one without the envelope, which read as
  # "the envelope does nothing". It was not: the arms were not matched -- one
  # cycled its form and the other did not -- and a later three-arm test with a
  # no-kit reference showed the envelopes land exactly on the reference. The
  # mechanism was never broken; the comparison was.
  #
  # What the same reference showed is why this is easy to get wrong: a channel's
  # entire contribution to a band can be 4 dB, so a perfect mute looks like 3.6
  # and reads as a failure unless something with the channel genuinely absent is
  # measured beside it.
  intro:     { drums: 0.0,  bass: 0.30, lead: 0.0,  chops: 0.0,  sample: 0.55,
               harm: 0.0,  pad: 0.85, texture: 1.60 },
  main:      { harm: 1.0,  pad: 1.0,  texture: 1.0 },
  breakdown: { drums: 0.0,  bass: 0.55, chops: 0.0,
               harm: 0.0,  pad: 1.20, texture: 1.85 },
  build:     { lead: 0.0,   sample: 0.7,
               harm: 1.06, pad: 0.90, texture: 1.25 },
  turn:      { lead: 0.0,   harm: 1.0, pad: 1.08, texture: 1.15 },
  outro:     { drums: 0.45, bass: 0.5,  lead: 0.0,  chops: 0.0,
               harm: 0.85, pad: 1.10, texture: 1.70 },
}.freeze

def section_layers_enabled? = ENV.fetch("SECTION_LAYERS", "1") != "0"

# Which table is in force. Two tables rather than one with a flag inside it,
# because the default one is what every existing render was made with and the
# cheapest way to keep that true is to leave it alone.
def section_layer_table = section_layers_full? ? SECTION_LAYER_GAIN_ARRANGED : SECTION_LAYER_GAIN

# Every layer either table has an opinion about. Both, because the pairing below
# is what catches a layer wired to nothing, and a layer declared only under
# SECTION_LAYERS=full is exactly as capable of being wired to nothing.
SECTION_LAYERS_DECLARED = (SECTION_LAYER_GAIN.values.flat_map(&:keys) +
                           SECTION_LAYER_GAIN_ARRANGED.values.flat_map(&:keys)).uniq.freeze

# Layers whose envelope is actually asked for somewhere. Two of the five were
# not, and that is what this pair of constants exists to stop happening again.
#
# :lead and :chops carried gains in the table above -- lead silent through the
# intro, the breakdown, the build and the outro; chops silent through three of
# them -- and nothing ever called apply_section_envelope for either. The most
# dramatic instruction in the arrangement, on the layer a listener notices
# first, was a hash entry nobody read. Meanwhile :harm WAS applied, to the
# analog pad, and the table says nothing about :harm, so section_layer_windows
# returned an empty list and that call has always been a no-op too.
#
# Neither failed. Both are the shape of defect this repository keeps finding:
# a declaration with no reader, indistinguishable from a working feature until
# somebody diffs the two lists. So they get diffed, in a test.
SECTION_LAYERS_APPLIED = %i[drums bass sample lead chops harm pad texture].freeze

# The time windows, in seconds, where this layer is not at full level.
#
# Contiguous bars sharing a gain are merged into one window: a 16-bar track
# yields three or four windows rather than sixteen, and ffmpeg is being handed a
# filter string, not a score.
def section_layer_windows(layer, n_bars, bar_p)
  return [] unless section_layers_enabled? && n_bars.to_i.positive?

  spans = []
  (0...n_bars).each do |bar|
    gain = section_layer_table.dig(dilla_section(bar, n_bars), layer)
    next if gain.nil?

    if spans.last && spans.last[:gain] == gain && spans.last[:to] == bar
      spans.last[:to] = bar + 1
    else
      spans << { from: bar, to: bar + 1, gain: }
    end
  end
  spans.map { |s| [(s[:from] * bar_p).round(3), (s[:to] * bar_p).round(3), s[:gain]] }
       .map { |from, to, gain| [from, to, survivable_gain(gain, to - from)] }
end

# A removal too short to read as a section becomes a duck instead.
#
# Both halves of this come from the same measurement. A boundary needs a change
# in WHAT IS PLAYING -- 14x against a level change's 1.5x -- and it needs to last
# long enough to be heard as a section rather than as a fault. The novelty
# detector's kernel is twelve seconds either side, and a listener is not much
# more generous.
#
# The legacy form's breakdowns are ONE BAR: 2.7 seconds at 88 BPM, three times in
# thirty-two. Taking the loudest channel in the mix out for 2.7 seconds is a beat
# drop, which is a real gesture -- but three of them in ninety seconds is a
# stutter, and it is not what the table means by "breakdown". So a full removal
# survives only in a section long enough to be one, and anywhere shorter it
# becomes a duck that still moves the balance without punching a hole.
#
# Eight seconds is roughly three bars at these tempos: long enough that the ear
# settles into the new instrumentation, short enough that a four-bar breakdown
# still qualifies. Nothing else in the table is affected -- this only ever
# softens a 0.0, and never touches a gain that was already a level change.
SECTION_REMOVAL_MIN_SEC = 8.0
SECTION_SHORT_REMOVAL_DUCK = 0.45

def survivable_gain(gain, seconds)
  return gain unless gain.to_f.zero?
  return gain if seconds >= SECTION_REMOVAL_MIN_SEC

  SECTION_SHORT_REMOVAL_DUCK
end

# volume with `enable` rather than one expression: each window is its own stage,
# which reads as what it is and lets ffmpeg do the timeline arithmetic. An empty
# result is an empty string, so a layer with nothing to say costs nothing.
#
# A short fade at each edge, because a gain change on a sustained pad is a click
# otherwise. 40ms is under a thirty-second note at any tempo here and inaudible
# as a fade, which is the point -- it should sound like the part left, not like
# somebody turned it down.
SECTION_EDGE_FADE = 0.04

def section_layer_filter(layer, n_bars, bar_p)
  windows = section_layer_windows(layer, n_bars, bar_p)
  return "" if windows.empty?

  windows.map do |from, to, gain|
    a = (from + SECTION_EDGE_FADE).round(3)
    b = (to - SECTION_EDGE_FADE).round(3)
    next "" if b <= a

    "volume=#{gain}:enable='between(t,#{a},#{b})'"
  end.reject(&:empty?).join(",")
end

# Prefix a layer's own chain with its section envelope.
#
# The envelope goes immediately after the input label -- "[0:a]" and friends --
# because a filtergraph stage is "[in]filters[out]" and the volume has to be
# inside that, not in front of the label. Inserted at the front of the whole
# string it produces "volume=...,[0:a]..." which ffmpeg rejects outright.
#
# Returns the chain untouched when the layer has no windows, so a track whose
# sections all want everything at full level pays nothing for this.
def apply_section_envelope(chain, layer, n_bars, bar_p)
  env = section_layer_filter(layer, n_bars, bar_p)
  return chain if env.empty? || chain.to_s.empty?

  chain.sub(/\A(\[[^\]]+\])/) { "#{Regexp.last_match(1)}#{env}," }
end

# The same envelope, for a layer that has no bus to hang it on.
#
# The lead is synthesised into the harmonic render rather than mixed as its own
# stream, so there is no filtergraph label to prefix and its section gain has to
# be applied to the notes. Events are [time, velocity, chord, sustain]; a gain
# of zero drops the note rather than playing it at zero, because a MIDI note-on
# at velocity 0 is a note-off in some synths and a quiet note in others.
#
# Off by default under SECTION_LAYERS=1, which is what every existing render was
# made with. SECTION_LAYERS=full turns on the layers the table has always
# declared. Wiring them silently would change the sound of every take with a
# lead in it, and that is not a checker's call to make -- see
# WIRING_DEAD_METHOD_BASELINE's note, which says the same thing about the two
# sound stages nobody connected.
def section_layers_full? = ENV["SECTION_LAYERS"].to_s.downcase == "full"

def apply_section_envelope_to_events(events, layer, n_bars, bar_p)
  return events unless section_layers_full? && events.is_a?(Array) && events.any?

  windows = section_layer_windows(layer, n_bars, bar_p)
  return events if windows.empty?

  kept = events.filter_map do |event|
    at = event[0].to_f
    _from, _to, gain = windows.find { |from, to, _| at >= from && at < to }
    next event if gain.nil?
    next nil if gain.zero?

    scaled = event.dup
    scaled[1] = (event[1].to_f * gain).round(4)
    scaled
  end
  dropped = events.length - kept.length
  if dropped.positive?
    dmesg("section: #{layer} drops #{dropped} of #{events.length} note(s) outside its sections",
          unit: "harm0", parent: "dilla0")
  end
  kept
end

def dilla_section(bar, n_bars)
  fs = form_section_at(bar, n_bars)
  return fs if fs
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    return COMPOSITION_SECTION_KIND.fetch(@composition_session.section_at(bar), :main)
  end
  dilla_section_legacy(bar, n_bars)
end

def dilla_section_gain(bar, n_bars, chord_phases: nil, pad_chords: nil, chord_bars: 2, phrase_bars: nil)
  sec_gain = if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
               prof = @composition_session.profile_at(bar)
               tension = @composition_session.tension_at(bar)
               (prof[:drums] * 0.35 + prof[:harmony] * 0.35 + tension * 0.3).clamp(0.28, 1.0)
             else
               case dilla_section_legacy(bar, n_bars)
               when :intro then 0.72
               when :breakdown then 0.58
               when :build then 0.88
               when :outro then 0.62
               else 1.0
               end
             end
  phase = chord_phase_at(bar, pad_chords, chord_phases, chord_bars:, phrase_bars:)
  sec_gain * (phase ? phase_gain_multiplier(phase) : 1.0)
end

# --------------------------------------------------------------------------
# engine part: dilla_schedule
# --------------------------------------------------------------------------
#
# Scheduling every event in a Dilla render.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def melody_pitch_from_chord(chord, bar, mel_step)
  return unless chord && chord[:hz]&.any?
  tones = chord[:hz].sort
  midis = tones.map { |h| hz_to_midi(h) }.sort
  # Rotate through upper chord tones (3rd, 5th, 7th, 9th) — not always the root.
  color_idx = [1, 2, 3, 0, 2, 1][(bar + mel_step) % 6] % midis.length
  base_midi = midis[color_idx]
  rng = Random.new((bar * 97) + (mel_step * 41) + stable_hash(chord[:name].to_s))
  approach = if composition_enabled? && rng.rand < 0.22
               neighbor = DillaComposition::Counterpoint.neighbor_tone(midi_to_hz(base_midi + 12),
                                                                     direction: rng.rand < 0.5 ? :up : :down)
               hz_to_midi(neighbor)
             elsif rng.rand < 0.28
               base_midi - (rng.rand < 0.5 ? 1 : 2)
             else
               base_midi
             end
  voiced = DillaComposition::Counterpoint.adjust_voices([midi_to_hz(approach + 12)])
  voiced.first || midi_to_hz(approach + 12)
end

def schedule_dfam_events!(events, n_bars, beat_p, swing, quintuplet, timing)
  return unless DfamEngine.enabled?
  step_p = beat_p / 4.0
  bar_p = beat_p * 4.0
  track = (ENV["TRACK"] || DillaLofiMachine::DEFAULT_PROFILE).to_s
  pattern = DfamEngine.resolve_pattern(seed: (@render_seed || 0) + stable_hash(track))
  patch = DfamEngine.resolve_patch
  ticks = DillaLofiMachine.humanize_ticks_for(track)
  n_bars.times do |bar|
    16.times do |step|
      idx = (bar * 16 + step) % DfamEngine::STEPS
      pitch = pattern[:pitch][idx] / 100.0
      vel = pattern[:velocity][idx] / 100.0
      t = bar * bar_p + step * step_p +
          dilla_swing_offset(step, step_p, swing, quintuplet:) +
          dilla_timing_ms(:hat_down, bar, step, timing, beat_p) / 1000.0
      if ticks.positive?
        h_ms = DillaLofiMachine.humanize_ms(60.0 / beat_p, ticks)
        t += Random.new(bar * 97 + step * 31 + idx).rand(-h_ms..h_ms) / 1000.0
      end
      events[:dfam] << [[t, 0.0].max.round(6), vel, pitch, idx, patch]
    end
  end
end

def render_dfam_wav(path, events, duration)
  return unless events&.any?
  write_stereo_chunks(path, duration) do |chunk_start, chunk_frames, left, right|
    DfamEngine.mix_events!(left, right, events, chunk_start, chunk_frames, sample_rate: SAMPLE_RATE)
  end
  patch = DfamEngine.resolve_patch
  tmp = "#{path}.fx.wav"
  q = (patch[:res_pct] / 100.0 * 6.0 + 0.5).round(2)
  sh! "ffmpeg", "-y", "-i", path, "-af",
      "lowpass=f=#{patch[:filter_hz]}:width_type=q:width=#{q},volume=0.62",
      "-c:a", "pcm_s16le", tmp
  FileUtils.mv(tmp, path)
  path
end

def dilla_hat_steps(bar, feel, n_bars: nil)
  steps = drum_pattern_pick(bar, feel, :hats)
  steps = DillaGroove.euclidean(5, 16, rotation: bar % 16) if ENV["EUCLIDEAN_HATS"] == "1"
  # Replaces rather than adds, and has to stay replaced through the markov line
  # below. Assigning `steps` here is not enough on its own: `steps + pool` unions
  # the preset's own bar-locked hat list back in two lines later, which puts the
  # downbeat under every bar again -- measured, POLYMETER_HATS=3 came back as
  # [0,2,3,5,6,8,9,11,12,14,15] on bar 1, the precessed cycle OR'd with the
  # [0,3,6,9,12,15] it was supposed to displace. That is the exact failure this
  # switch exists to avoid, so the pool is dropped while it is on.
  poly = DillaGroove.polymeter_hat_steps(bar)
  steps = poly if poly.any?
  steps += DillaGroove.prime_poly_steps(bar) if ENV["PRIME_GRID"] == "1"
  pool = if poly.any?
           []
         else
           DRUM_PATTERN_SETS.fetch(drum_feel_key(feel), DRUM_PATTERN_SETS[:default])[:hats]&.flatten || steps
         end
  steps = DillaGroove.markov_steps(bar, :hat, steps + pool)
  steps = DillaGroove.trap_morph_hat_density(bar, n_bars || 16, steps) if n_bars
  steps = DillaRhythm.subdivision_density_steps(steps, bar) if defined?(DillaRhythm)
  if n_bars && bar >= (n_bars * 0.82).to_i
    progress = 1.0 - ((n_bars - 1 - bar).to_f / [n_bars * 0.18, 1].max)
    steps += (0..15).select { |i| i.odd? && Random.new(bar * 421).rand < (0.25 + 0.45 * progress) }
  elsif n_bars && bar >= n_bars - 2
    progress = 1.0 - ((n_bars - 1 - bar).to_f / 2)
    steps += (0..15).select { |i| i.odd? && Random.new(bar * 421 + 7).rand < (0.35 + 0.5 * progress) }
  end
  steps.uniq.sort
end

def wonky_overlay_steps(bar, section, role)
  if (learned = learned_wonky_overlay_steps(role))&.any?
    return learned.dup
  end
  wonky_overlay_grid_pick(bar, section, role)
end

def schedule_wonky_drum_overlay!(events, bar, n_bars, base, step_p, _bar_p, beat_p, swing, _quintuplet, timing,
                                 sec_gain, section, pad_chords, chord_bars:, phrase_bars:, chord_phases:)
  return unless wonky_drum_overlay_enabled?
  return if camel_mode? && bar < camel_drum_entry_bar
  return if !camel_drum_lock? && drum_drop_bar?(bar, section)

  density = wonky_overlay_density(bar, n_bars, chord_bars:, pad_chords:,
                                  chord_phases:, phrase_bars:)
  density = density.clamp(wonky_primary_drums? ? 0.7 : 0.2, 1.35)
  bar_bpm = DillaRhythm.bar_bpm(bar)
  overlay_gain = camel_drum_lock? ? density : (sec_gain * density)
  timing_use = timing || DillaLofiMachine::DILLA_TIMING
  swing_use = [swing.to_f, 60.0].max

  # --- Simplicity: sparse rotating phrases (not dense onset dumps) ---
  if DillaGroove.pocket_dna?
    kicks = DillaGroove.pocket_kicks(bar)
    hard_snares = DillaGroove.pocket_snares_hard(bar, section:)
    ghost_snares = DillaGroove.pocket_snares_ghost(bar)
    hat_steps = DillaGroove.pocket_hats(bar)
  else
    kicks = wonky_overlay_steps(bar, section, :kicks)
    hard_snares = wonky_overlay_steps(bar, section, :snares)
    ghost_snares = Array(learned_wonky_overlay_steps(:ghost_snares)).map(&:to_i)
    hat_steps = wonky_overlay_steps(bar, section, :hats)
  end

  # --- Micro-timing: swing + snare-early / kick-late / hats-late + freehand kick ---
  place = lambda do |step, role_timing|
    t = base + step * step_p
    t += dilla_swing_offset(step, step_p, swing_use, quintuplet: false, bar:, bpm: bar_bpm)
    t += dilla_timing_ms(role_timing, bar, step, timing_use, beat_p) / 1000.0
    t = DillaGroove.apply_pocket_place(t, role: role_timing, beat_p:, bar:, step:, bpm: bar_bpm, section:)
    [t, 0.0].max
  end

  kicks.each do |step|
    role = step.zero? ? :kick_anchor : :kick_sync
    t = place.call(step, role)
    base_vel = step.zero? ? 0.98 : 0.78
    vel = dilla_velocity(base_vel, bar, step, spread: 0.03) *
          overlay_gain * wonky_kick_velocity_scale
    vel *= 0.75 unless step.zero? || step == 10
    sk = DillaGroove.kick_sample_key(bar, step)
    events[:wonky_kick] << [t.round(6), vel.clamp(0.55, 0.99), sk]
  end

  return if section == :breakdown && !camel_keep_wonky_on_breakdown? && !camel_drum_lock?

  (hard_snares | ghost_snares).each do |step|
    ghost = ghost_snares.include?(step) && !hard_snares.include?(step)
    t = place.call(step, ghost ? :ghost : :snare)
    base_vel = ghost ? 0.22 : 0.9
    vel = dilla_velocity(base_vel, bar, step, spread: 0.04) *
          overlay_gain * (ghost ? 1.0 : 1.75)
    sk = DillaGroove.snare_sample_key(ghost:)
    events[:wonky_snare] << [t.round(6), vel.clamp(ghost ? 0.1 : 0.6, ghost ? 0.32 : 0.98), sk]
  end

  if backbeat_clap_enabled?
    hard_snares.each do |step|
      t = place.call(step, :clap)
      vel = dilla_velocity(0.32, bar, step, spread: 0.03) * overlay_gain
      events[:clap] << [t.round(6), vel.clamp(0.14, 0.48), :clap]
    end
  end

  hat_steps.each do |step|
    role = step.even? ? :hat_down : :hat_up
    t = place.call(step, role)
    base_vel = step.even? ? 0.46 : 0.32
    vel = dilla_velocity(base_vel, bar, step, spread: 0.06) * overlay_gain
    events[:wonky_hat] << [t.round(6), vel.clamp(0.16, 0.68), :hat]
  end

  return unless DillaGroove.pocket_open_hat?(bar)
    t = place.call(14, :open)
    vel = dilla_velocity(0.38, bar, 14, spread: 0.04) * overlay_gain
    events[:wonky_hat] << [t.round(6), vel.clamp(0.18, 0.5), :open_hat]

  # No perc / quint / rim spam — simplicity is the trick.
end

def dilla_schedule(n_bars, beat_p, pad_chords, chord_bars: 4, phrase_bars: nil, drums_only: false,
                   swing: 58.0, feel: :default, timing: nil, quintuplet: false, bass_pads: nil,
                   chord_phases: nil)
  bar_p = (beat_p * 4.0).round(6)
  step_p = (beat_p / 4.0).round(6)
  # Published once here so drum_morph_feel can read it without n_bars being
  # threaded through seven call sites. Same idiom as @render_seed, and the
  # alternative was a morph that silently never engaged because its callers
  # passed nil -- the shape this engine keeps producing.
  @render_total_bars = n_bars
  events = Hash.new { |h, k| h[k] = [] }
  groove_meta = { snare_early_ms: [], hat_late_ms: [], ghost_vel: [] }
  # Odd-meter/hemiola nod (Aydin Esen's Turkish-modal odd meters, without a
  # full rewrite of the 16-step grid): every 16th bar loses its last 2
  # steps — a real short bar, not a fake accent. Cumulative bar starts
  # since bar durations are no longer uniform.
  drop_beat_bar = ->(b) { b.positive? && b % 16 == 15 }
  bar_starts = [0.0]
  (1..n_bars).each { |b| bar_starts << bar_starts.last + (drop_beat_bar.call(b - 1) ? bar_p * 0.875 : bar_p) }
  chord_change_i = -1
  prev_bass_root = nil
  prev_pad_chord = nil
  cfg_sched = dilla_resolve_config
  bpm_base = cfg_sched[:bpm]
  # Loop-invariant: cfg_sched[:progression] does not change inside the bar loop.
  curated_sched = curated_progression?(cfg_sched)

  if DillaRhythm.macro_enabled? && %w[1].intersect?([ENV["TEMPO_RAMP"], ENV["BPM_STAIRCASE"], ENV["TEMPO_ACCEL"]])
    bar_starts = [0.0]
    (1...n_bars).each { |b| bar_starts << bar_starts.last + DillaRhythm.bar_duration_sec(b - 1, beat_p) }
  end

  # feel gets reassigned per-phrase below (alternating_drum_feel) when
  # DRUM_STYLE_ALTERNATE is on; original_feel keeps the preset's own value
  # so alternation toggles base<->techno_house every phrase instead of
  # drifting once it flips (feel itself would otherwise become the "base"
  # for the next comparison).
  original_feel = feel

  n_bars.times do |bar|
    base = bar_starts[bar]
    bar_bpm = DillaRhythm.bar_bpm(bar)
    beat_p_bar = 60.0 / bar_bpm
    section = dilla_section(bar, n_bars)
    apply_motif_recall!(bar)
    apply_drum_archetype!(bar, phrase_bars)
    feel = alternating_drum_feel(bar, phrase_bars, original_feel)
    ghost_tier = ghost_tier_for(bar, section)
    sec_gain = dilla_section_gain(bar, n_bars, chord_phases:, pad_chords:,
                                  chord_bars:, phrase_bars:)
    sec_gain *= DillaRhythm.stripdown_gain(bar, section)
    sec_gain *= DillaRhythm.element_strip_gain(base)
    sec_gain *= DillaRhythm.periodic_layer_drop_gain(bar)
    phase = chord_phase_at(bar, pad_chords, chord_phases, chord_bars:, phrase_bars:)
    chop_entry = spectral_arp_chop_bar?(bar, chord_bars, drums_only, section)
    pattern = if DillaGroove.kick_snare_swap?
                dilla_snare_steps(bar, feel, section:)
              else
                dilla_kick_pattern(bar, n_bars, feel)
              end
    pattern = (pattern + [0, 15]).uniq.sort if chop_entry && kicks_enabled?
    pattern = [7, 14] if section == :breakdown
    intro_drum_cutoff = camel_mode? ? camel_drum_entry_bar : 4
    pattern = [0, 10] if section == :intro && bar < intro_drum_cutoff
    pattern = pattern.select { |s| s < 14 } if drop_beat_bar.call(bar)

    chord_lens_sched = instance_variable_defined?(:@render_chord_bar_lens) ? @render_chord_bar_lens : nil
    cur_chord = if drums_only || pad_chords.empty?
                  nil
                else
                  pad_chords[dilla_chord_index(bar, pad_chords, chord_bars:, phrase_bars:,
                                                 chord_bar_lens: chord_lens_sched)]
                end
    # Real bitonal composition, not just chord-following: when bass_pads is
    # given, the bass tracks its own independent progression instead of
    # always echoing the pad chord's root — the bass and the chords can
    # genuinely disagree, on purpose.
    bass_chord = if bass_pads && !bass_pads.empty?
                   bass_pads[dilla_chord_index(bar, bass_pads, chord_bars:, phrase_bars:)]
                 else
                   cur_chord
                 end
    bass_root = dilla_chord_bass_hz(bass_chord)
    unless drums_only || section == :breakdown || bass_root.nil?
      slide_from = bass_slide_enabled? && prev_bass_root && (prev_bass_root - bass_root).abs > 0.5 ? prev_bass_root : nil
      # Was a fixed 0.012s pickup offset, not the tick-authentic system used
      # everywhere else -- 12ms at 90 BPM is ~1.73 ticks, a value no real
      # 96-PPQ nudge could produce. Rounded to the nearest whole tick.
      bass_tick = beat_p / 96.0
      bass_pickup = bass_tick.positive? ? (0.012 / bass_tick).round * bass_tick : 0.012
      bar_bass = [base + bass_pickup, dilla_velocity(0.52, bar, 99, spread: 0.04) * sec_gain, bass_root, bar_p * 0.92]
      bar_bass << slide_from if slide_from
      events[:bass] << bar_bass

      # A line, not a root held for the whole bar.
      #
      # The bass was one note per bar: the chord's root, sounded on the downbeat
      # and sustained for 92% of the bar. That is a bass PART only in the sense
      # that something low is present. It states the harmony the pads are already
      # stating, at the moment they state it, which is the same fault the lead
      # had -- and with the drums and the counter-line both now moving, it was
      # the last layer standing still.
      #
      # Two additions, and no more, because a busy bass under this idiom stops
      # being a pocket and starts being a solo:
      #
      #   Beat 3 gets the fifth, or the octave when the fifth would drop below
      #   the register. That is the oldest move in bass playing and it is what
      #   makes a bar feel like it has two halves.
      #
      #   The last eighth approaches the NEXT bar's root by a semitone, from
      #   whichever side is closer. A chromatic approach is how a walking line
      #   gets somewhere, and it turns a bar line from a seam into a hand-off.
      #
      # Both go through dilla_timing_ms like everything else, so they sit in the
      # same pocket as the note they follow rather than landing on the grid.
      if bass_line_enabled?
        fifth = bass_root * 1.5
        fifth /= 2.0 while fifth > BASS_REGISTER_TOP
        events[:bass] << [
          (base + (beat_p * 2) + (dilla_timing_ms(:bass, bar, 8, timing, beat_p) / 1000.0)).round(6),
          dilla_velocity(0.38, bar, 8, spread: 0.05) * sec_gain, fifth, beat_p * 0.7
        ]

        nxt = bass_pads && !bass_pads.empty? ? bass_pads[dilla_chord_index(bar + 1, bass_pads, chord_bars:, phrase_bars:)] : nil
        target = dilla_chord_bass_hz(nxt) || bass_root
        approach = target * (target >= bass_root ? APPROACH_BELOW : APPROACH_ABOVE)
        events[:bass] << [
          (base + (beat_p * 3.5) + (dilla_timing_ms(:bass, bar, 14, timing, beat_p) / 1000.0)).round(6),
          dilla_velocity(0.32, bar, 14, spread: 0.05) * sec_gain, approach, beat_p * 0.42
        ]
      end
      prev_bass_root = bass_root
    end
    if feel == :chromatic_planing
      pickup = base - step_p * 2
      if kicks_enabled?
        events[:kick] << [[pickup + dilla_timing_ms(:kick_sync, bar, 0, timing, beat_p) / 1000.0, 0.0].max.round(6),
                          dilla_velocity(0.88, bar, 0)]
      end
      events[:bass] << [[pickup + dilla_timing_ms(:bass, bar, 0, timing, beat_p) / 1000.0, 0.0].max.round(6),
                        dilla_velocity(0.50, bar, 0, spread: 0.05), bass_root]
    end

    drop_bar = drum_drop_bar?(bar, section)

    if dilla_pocket_drums_enabled? && kicks_enabled? && !drop_bar
      pattern.each_with_index do |step, i|
        next if DillaGroove.kick_should_drop?(bar, step)
        role = (feel == :syncopated_slash_ninth || step.nonzero?) ? :kick_sync : :kick_anchor
        t = [base + step * step_p +
             dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm: bar_bpm) +
             dilla_timing_ms(role, bar, step, timing, beat_p) / 1000.0, 0.0].max
        t = DillaGroove.apply_event_timing!(t, role: :kick, beat_p:, bar:, step:, bpm: bar_bpm, section:)
        ks = kick_velocity_scale
        kick_role = step.zero? ? :kick_anchor : :kick_sync
        kick_vel = dilla_role_velocity(kick_role, bar, step, sec_gain: sec_gain * ks)
        events[:kick] << [t.round(6), kick_vel]
        double_ticks = DillaGroove.kick_double_offset_ticks(bar, step)
        if double_ticks
          dbl_t = (t + double_ticks * (beat_p / 96.0)).round(6)
          events[:kick] << [dbl_t, (kick_vel * 0.55).clamp(0.05, 0.95)]
        end
        if step.zero?
          events[:sub_osc] ||= []
          events[:sub_osc] << [t.round(6), dilla_velocity(0.06, bar, step, spread: 0.04) * sec_gain * ks, 40.0]
        end
        bass_skip = drums_only ||
                    (feel == :syncopated_slash_ninth && bar.zero? && step < 7) ||
                    (feel != :syncopated_slash_ninth && bar.zero?) ||
                    (section == :breakdown && step < 8)
        next if bass_skip
        bass_lag = feel == :syncopated_slash_ninth ? step_p * 0.12 : 0.0
        events[:bass] << [[t + dilla_timing_ms(:bass, bar, step, timing, beat_p) / 1000.0 + bass_lag, 0.0].max.round(6),
                          dilla_velocity(0.28, bar, step, spread: 0.06) * sec_gain, bass_root, step_p * 0.55]
      end
    end

    if dilla_pocket_drums_enabled? && !(section == :intro && bar < intro_drum_cutoff)
      dilla_snare_steps(bar, feel, section:).each_with_index do |step, si|
        next if drop_bar
        next if section == :breakdown
        t = [base + step * step_p +
             dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm: bar_bpm) +
             dilla_timing_ms(:snare, bar, step, timing, beat_p) / 1000.0 +
             DillaGroove.flam_offset_sec(beat_p), 0.0].max
        t = DillaGroove.apply_event_timing!(t, role: :snare, beat_p:, bar:, step:, bpm: bar_bpm, section:)
        backbeat = halftime? ? [8].include?(step) : [4, 12].include?(step)
        groove_meta[:snare_early_ms] << dilla_timing_ms(:snare, bar, step, timing, beat_p) if backbeat
        snare_vel = dilla_role_velocity(:snare, bar, step, sec_gain:, backbeat:)
        events[:snare] << [t.round(6), snare_vel]
        if backbeat && backbeat_clap_enabled? && %i[main build].include?(section)
          events[:clap] ||= []
          events[:clap] << [t.round(6), dilla_role_velocity(:clap, bar, step, sec_gain:), :clap]
        end
        if backbeat && si.zero? && DillaGroove.snare_prehit_ghost?(bar, step)
          ghost_vel = apply_ghost_tier_vel(dilla_role_velocity(:ghost, bar, step, sec_gain:) * 0.72, ghost_tier)
          groove_meta[:ghost_vel] << ghost_vel
          prehit_t = (t - 3 * (beat_p / 96.0)).round(6).clamp(0.0, Float::INFINITY)
          events[:ghost] << [prehit_t, ghost_vel]
        end
      end
    end

    if dilla_pocket_drums_enabled?
      ghost_steps = dilla_ghost_steps(bar, feel, section:)
      ghost_steps += [1, 9] if feel == :loose_pocket && bar.odd?
      ghost_steps += [5] if feel == :loose_pocket && bar.even?
      ghost_steps += fugue_ghost_answer_steps(pattern, phase)
      ghost_steps.uniq.each do |step|
        next if drop_bar
        t = [base + step * step_p +
             dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm: bar_bpm) +
             dilla_timing_ms(:ghost, bar, step, timing, beat_p) / 1000.0, 0.0].max
        # Ghosts must share pocket place + section jitter — previously skipped
        # apply_event_timing! so they sat on a dead grid while kick/snare breathed.
        t = DillaGroove.apply_event_timing!(t, role: :ghost, beat_p:, bar:, step:,
                                            bpm: bar_bpm, section:)
        ghost_vel = apply_ghost_tier_vel(dilla_role_velocity(:ghost, bar, step, sec_gain:), ghost_tier)
        ghost_vel = (ghost_vel * 1.12).clamp(0.03, 0.72).round(3) if feel == :loose_pocket
        groove_meta[:ghost_vel] << ghost_vel
        events[:ghost] << [t.round(6), ghost_vel]
      end

      hat_steps = dilla_hat_steps(bar, feel, n_bars:)
      # Breakdowns should thin closer to silence, not just half-density --
      # real Dilla breakdowns often drop hats almost entirely rather than
      # keeping a steady (if sparser) pulse.
      hat_steps = if section == :breakdown
                    hat_steps.select.with_index { |_, i| (i % 4).zero? }
                  elsif chop_entry
                    hat_steps.select.with_index { |_, i| i.even? }
                  else
                    hat_steps
                  end
      hat_steps.each_with_index do |step, i|
        next if drop_bar
        next if DillaGroove.hat_should_drop?(bar, step, section:)
        role = if [3, 11].include?(step) && feel == :syncopated_slash_ninth
                 :hat_up
               elsif feel == :loose_pocket && step.odd?
                 :hat_up
               else
                 i.even? ? :hat_down : :hat_up
               end
        t = [base + step * step_p +
             dilla_swing_offset(step, step_p, swing, quintuplet:, bar:, bpm: bar_bpm) +
             dilla_timing_ms(role, bar, step, timing, beat_p) / 1000.0, 0.0].max
        t = DillaGroove.apply_event_timing!(t, role:, beat_p:, bar:, step:, bpm: bar_bpm, section:)
        hat_role = role == :hat_up ? :hat_up : :hat_down
        groove_meta[:hat_late_ms] << dilla_timing_ms(hat_role, bar, step, timing, beat_p)
        events[:hat] << [t.round(6), dilla_role_velocity(hat_role, bar, step, sec_gain:)]
      end

      dilla_open_steps(bar, feel, section:).each do |open_step|
        t = [base + open_step * step_p +
             dilla_swing_offset(open_step, step_p, swing, quintuplet:, bar:, bpm: bar_bpm) +
             0.008, 0.0].max
        t = DillaGroove.apply_event_timing!(t, role: :open, beat_p:, bar:, step: open_step,
                                            bpm: bar_bpm, section:)
        events[:open] << [t.round(6), dilla_role_velocity(:open, bar, open_step, sec_gain:)]
      end
      if feel == :loose_pocket && section == :main && bar % 6 == 4
        t = [base + 10 * step_p +
             dilla_swing_offset(10, step_p, swing, quintuplet:, bar:, bpm: bar_bpm), 0.0].max
        t = DillaGroove.apply_event_timing!(t, role: :ghost, beat_p:, bar:, step: 10,
                                            bpm: bar_bpm, section:)
        events[:ghost] << [t.round(6), dilla_velocity(0.22, bar, 10, spread: 0.04) * sec_gain]
      end

      schedule_hat_roll!(events, bar, base, step_p, swing, quintuplet, timing, beat_p, sec_gain, section) unless drop_bar
      schedule_drum_fills!(events, bar, base, step_p, swing, quintuplet, timing, beat_p, sec_gain, feel, section) unless drop_bar
    end
    schedule_wonky_drum_overlay!(events, bar, n_bars, base, step_p, bar_p, beat_p, swing, quintuplet, timing,
                                 sec_gain, section, pad_chords, chord_bars:, phrase_bars:,
                                 chord_phases:)

    next if drums_only
    next if section == :intro && bar < 2

    chord_lens = instance_variable_defined?(:@render_chord_bar_lens) ? @render_chord_bar_lens : nil
    cur_idx = dilla_chord_index(bar, pad_chords, chord_bars:, phrase_bars:,
                                chord_bar_lens: chord_lens)
    prev_idx = bar.positive? ? dilla_chord_index(bar - 1, pad_chords, chord_bars:,
                                                 phrase_bars:, chord_bar_lens: chord_lens) : -1
    if chord_lens&.any?
      next unless bar.zero? || cur_idx != prev_idx
    else
      next unless (bar % chord_bars).zero?
    end

    chord_change_i += 1
    chord = pad_chords[cur_idx]
    pad_chord = if section == :breakdown && DillaHarmony.soul_profile?(cfg_sched[:track])
                  DillaHarmony.strip_voices(chord, count: 2)
                else
                  chord
                end
    pad_chord = DillaHarmony.fix_chord_for_schedule(pad_chord, prev_pad_chord, curated: curated_sched)
    cvar = dilla_chord_change_variation(chord_change_i, bar, section, feel, step_p, pad_chord)
    pad_t = base + cvar[:pad_offset] + dilla_timing_ms(:pad, bar, 0, timing, beat_p) / 1000.0
    if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
      lead_role = DillaComposition::Conversation.turn_order(bar).first
      pad_t += DillaComposition::Conversation.answer_offset(lead_role, beat_p) * 0.12
    end
    hold_bars = chord_lens&.dig(cur_idx) || chord_bars
    legato_mul = if la_beat_progression_enabled?
                   rng_leg = Random.new(patch_cycle_seed(cur_idx + bar))
                   rng_leg.rand(0.78..1.12)
                 else
                   1.0
                 end
    sustain = (hold_bars * bar_p * 0.97 * cvar[:sustain_mul] * legato_mul *
               DillaHarmony.pad_overlap_mul(prev_pad_chord, pad_chord) *
               harmonic_space_mul(chord_change_i, section, phase)).round(4)
    prev_pad_chord = pad_chord
    pad_vel = dilla_velocity(phase == :recapitulation ? 0.96 : 0.92, bar, 0, spread: 0.03) * sec_gain
    pad_vel *= 0.88 if phase == :development
    pad_vel *= cvar[:pad_vel_mul]
    events[:pad] << [[pad_t, 0.0].max.round(6), pad_vel, pad_chord, sustain]
    if cvar[:double_pad]
      events[:pad] << [[pad_t + cvar[:double_pad_delay], 0.0].max.round(6),
                       dilla_velocity(cvar[:double_pad_vel], bar, 1, spread: 0.05) * sec_gain, pad_chord, sustain * 0.68]
    elsif (feel == :timeless || LOFI_DRUM_FEELS.include?(feel)) && section == :main && bar % 4 == 1 && phase != :development
      events[:pad] << [[pad_t + step_p * 0.5, 0.0].max.round(6),
                       dilla_velocity(0.22, bar, 1, spread: 0.05) * sec_gain, pad_chord, sustain * 0.72]
    end
    unless section == :breakdown || phase == :development
      chop_steps = cvar[:chop_steps]
      chop_steps = chop_steps.select { |s| s < 12 } if phase != :recapitulation && chop_steps.length > 4
      chop_steps << 15 if phase == :recapitulation && chord_change_i % 3 == 1
      chop_chord = if DillaSpectral.breath_mode?
                     { name: "breath", hz: DillaSpectral.breath_perc_hz }
                   elsif DillaHarmony.soul_profile?(cfg_sched[:track])
                     DillaHarmony.chop_tones(pad_chord)
                   else
                     pad_chord
                   end
      chop_steps.uniq.sort.each do |chop_step|
        chop_rng = chord_variation_rng(cfg_sched, chord_change_i, pad_chord, salt: 8819 + chop_step.to_i)
        anchored_step = dilla_anchor_chop_step(chop_step, pattern + dilla_snare_steps(bar, feel, section:), chop_rng)
        chop_t = [base + anchored_step * step_p +
                  dilla_swing_offset(anchored_step.floor, step_p, swing, quintuplet:, bar:, bpm: bar_bpm) +
                  cvar[:chop_jitter], 0.0].max
        chop_t = DillaGroove.apply_event_timing!(chop_t, role: :hat_up, beat_p:, bar:, step: anchored_step.floor,
                                                 bpm: bar_bpm, section:)
        chop_vel = phase == :recapitulation ? 0.58 : 0.52
        events[:chop] << [chop_t.round(6), dilla_velocity(chop_vel, bar, anchored_step.floor, spread: 0.04) * sec_gain, chop_chord]
      end
    end
    mel_allowed = !drums_only && section == :main && phase != :coda &&
                  (phase == :recapitulation || (bar % 4 == 2 && phase != :development))
    if mel_allowed
      mel_step = [2, 6, 10][bar % 3]
      mel_hz = melody_pitch_from_chord(chord, bar, mel_step)
      if mel_hz
        mel_t = [base + mel_step * step_p + dilla_swing_offset(mel_step, step_p, swing, quintuplet:) + 0.006, 0.0].max
        mel_vel = phase == :recapitulation ? 0.44 : 0.38
        events[:melody] << [mel_t.round(6), dilla_velocity(mel_vel, bar, mel_step, spread: 0.06) * sec_gain, mel_hz]
      end
    end
  end
  schedule_dfam_events!(events, n_bars, beat_p, swing, quintuplet, timing)
  events[:_groove_meta] = groove_meta
  events
end

# --- Sample-based drum engine (MPC one-shots + Ruby mixer) ---

def drum_kit_ready?
  %w[kick.wav snare.wav ghost.wav hat.wav open_hat.wav bass_43.wav
     ind_kick.wav ind_clap.wav ind_hat.wav ind_bass_e.wav ind_bass_bb.wav ind_stab.wav].all? do |name|
    File.exist?(File.join(DRUM_DIR, name))
  end
end

# --------------------------------------------------------------------------
# engine part: drum_kit
# --------------------------------------------------------------------------
#
# Drum kits: generating them, external kits, chopping them.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# kick.wav deliberately excluded: it's a 4-layer synthesis (sample + sub
# drop + body punch + click transient via layered_kick_sample) tuned
# across many iterations — swapping its base sample for a random external
# one-shot and re-layering synthesis on top produced an unpredictable,
# bad-sounding result ("that stupid kickdrum sound" — direct feedback).
DRUM_SAMPLE_SUBDIR = {
  "snare.wav" => "snares", "hat.wav" => "hi-hats",
  "open_hat.wav" => "open-hats", "ghost.wav" => "claps", "bass_43.wav" => "808s",
}.freeze
EXTERNAL_DRUM_KITS = %w[01-hard-trap 02-bounce 03-soulful-vintage].freeze

# One choice per render (called once at the top of render_dilla, not per
# sample), matching how EP/warm-pad/lead voices already vary per render
# rather than per hit — a real drum kit doesn't swap character mid-hit.
# pick_synth_patches! caches its choices in @render_*_patch and guards them
# with `||=` / `&& !@render_*`, so nothing re-rolls a voice while the cache is
# populated. That invariant used to live in the callers: stream_rotate_voices_
# and_arps! cleared the cache by hand, but play's quality-gate retry loop and
# default_render!'s retry did not -- so a rejected render was retried with a new
# seed but the *same* synth patches, i.e. the largest timbral lever was the one
# thing that couldn't change. Clearing here ties "new render identity" to "new
# voices" in one place, so no future caller has to remember.
def reset_render_patches!
  @render_ep_patch = @render_warm_patch = @render_lead_patch = nil
  @render_scale_lead_patch = @render_texture_patch = @render_native_patch = nil
  @render_arp_style = @render_scale_arp_style = nil
end

def pick_render_seed!
  DillaSeeds.apply!
  @render_seed = DillaSeeds.render_seed
  reset_render_patches!
  # Bridge into ENV so lib modules (DillaGroove) that don't share this
  # top-level instance variable can still vary their per-bar phrase/pattern
  # choices by render instead of being purely a function of bar number.
  ENV["DILLA_RENDER_SEED"] = @render_seed.to_s
end

def pick_external_drum_kit!
  @current_external_kit = nil
  return unless ensure_external_assets_lazy!
  if (kit = ENV["EXTERNAL_KIT"]) && !kit.empty?
    kit_dir = File.join(EXTERNAL_DRUM_KIT_CACHE, "drum-samples", kit)
    if Dir.exist?(kit_dir)
      @current_external_kit = kit
      return
    end
  end
  track = (ENV["TRACK"] || "").to_s
  soul = DillaHarmony.soul_profile?(track) || ENV["DILLA_STREAMING"] == "1"
  roll = render_rand("external_kit_roll")
  @current_external_kit = if soul
                            if roll < 0.72
                              "03-soulful-vintage"
                            elsif roll < 0.88
                              "02-bounce"
                            else
                              render_pick(EXTERNAL_DRUM_KITS, "external_kit_soul")
                            end
                          elsif roll < 0.35
                            render_pick(EXTERNAL_DRUM_KITS, "external_kit_plain")
                          end
end

# Hats/snares/claps synthesized from a bandpassed noise burst (generate_drum_kit!)
# are thin/harsh by construction — pure noise decaying in ~20ms has no body.
# pick_external_drum_kit! rolls a real-sample kit only 35-88% of the time
# (track-dependent); these three roles matter enough to the drum sound that
# they should reach for real samples whenever the (already-fetched) kit
# cache exists, not just when the roll happened to land on it.
ALWAYS_SAMPLED_DRUM_ROLES = %w[hat.wav open_hat.wav snare.wav ghost.wav].freeze

def drum_sample_path(name)
  # Explicit opt-in beats the passive custom-dir cache -- FM_DRUMS=1 is a
  # deliberate whole-kit choice, not a per-role override.
  if fm_drums_enabled?
    fm = File.join(FM_DRUM_DIR, name)
    return fm if File.exist?(fm)
  end

  custom = File.join(CUSTOM_DRUM_DIR, name)
  return custom if File.exist?(custom)

  subdir = DRUM_SAMPLE_SUBDIR[name]
  if subdir
    kit = @current_external_kit
    kit ||= "03-soulful-vintage" if ALWAYS_SAMPLED_DRUM_ROLES.include?(name) && Dir.exist?(EXTERNAL_DRUM_KIT_CACHE)
    if kit
      kit_dir = File.join(EXTERNAL_DRUM_KIT_CACHE, "drum-samples", kit, subdir)
      # .sort first: Dir.glob order is not guaranteed across filesystems, so an
      # index into an unsorted list is only stable on the machine that made it.
      picked = render_pick(Dir.glob(File.join(kit_dir, "*.wav")).sort, "kit:#{kit}:#{name}")
      return picked if picked
    end
  end

  File.join(DRUM_DIR, name)
end

def generate_drum_kit!
  require_tools! "ffmpeg"
  FileUtils.mkdir_p(DRUM_DIR)
  FileUtils.mkdir_p(CUSTOM_DRUM_DIR)
  force = ENV["FORCE_KIT"] == "1"
  sr = SAMPLE_RATE
  recipes = [
    ["kick.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.9*exp(-t*7.5)*sin(2*PI*(48+210*exp(-t*28))*t)+0.55*exp(-t*95)*sin(2*PI*3200*t)*between(t,0,0.006)':d=0.55:s=#{sr}"],
     "lowpass=f=180,acrusher=bits=12:samples=2:mix=0.42,equalizer=f=55:t=o:w=0.8:g=4,acompressor=threshold=-20dB:ratio=3:attack=3:release=50"],
    ["snare.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.32:color=white:amplitude=0.95:seed=#{noise_seed(2)}", "-f", "lavfi", "-i", "sine=f=195:d=0.32"],
     "[0:a]asplit=2[n][n2];[n]highpass=f=1200,lowpass=f=7000,aeval=exprs='val(0)*exp(-t*32)'[crack];" \
     "[n2]bandpass=f=350:w=500,aeval=exprs='val(0)*exp(-t*18)'[rattle];[1:a]aeval=exprs='val(0)*exp(-t*22)'[body];" \
     "[crack][rattle][body]amix=inputs=3:weights=0.75 0.35 0.45,acrusher=bits=10:samples=2:mix=0.38"],
    ["ghost.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.14:color=pink:amplitude=0.7:seed=#{noise_seed(3)}"],
     "highpass=f=900,lowpass=f=5500,aeval=exprs='val(0)*exp(-t*48)',volume=0.55"],
    ["hat.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.07:color=white:amplitude=1:seed=#{noise_seed(4)}"],
     "highpass=f=7500,lowpass=f=15000,aeval=exprs='val(0)*exp(-t*140)',acrusher=bits=8:samples=1:mix=0.55"],
    ["open_hat.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.42:color=white:amplitude=0.85:seed=#{noise_seed(5)}"],
     "highpass=f=6000,bandpass=f=9000:w=5000,aeval=exprs='val(0)*exp(-t*9)'"],
    ["bass_43.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.75*exp(-t*1.1)*sin(2*PI*(43+5*sin(2*PI*0.28*t))*t)':d=1.35:s=#{sr}"],
     "lowpass=f=120,equalizer=f=50:t=o:w=1:g=6"],
    ["ind_kick.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.95*exp(-t*5.5)*sin(2*PI*(50+520*exp(-t*45))*t)':d=0.65:s=#{sr}"],
     "aeval=exprs='tanh(5.5*val(0))/tanh(5.5)',lowpass=f=140,equalizer=f=52:t=o:w=0.6:g=9,acompressor=threshold=-16dB:ratio=10:attack=1:release=35"],
    ["ind_clap.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.22:color=white:amplitude=1:seed=#{noise_seed(6)}"],
     "[0:a]asplit=3[a][b][c];[a]adelay=0|3,highpass=f=1400,aeval=exprs='val(0)*exp(-t*24)'[c1];" \
     "[b]adelay=12|15,highpass=f=1800,aeval=exprs='val(0)*exp(-(t-0.012)*30)'[c2];[c]bandpass=f=900:w=1800,aeval=exprs='val(0)*exp(-t*20)'[c3];" \
     "[c1][c2][c3]amix=inputs=3,acompressor=threshold=-14dB:ratio=6:attack=1:release=25"],
    ["ind_hat.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.05:color=white:amplitude=1:seed=#{noise_seed(7)}"],
     "highpass=f=9000,aeval=exprs='val(0)*exp(-t*160)',equalizer=f=12000:t=o:w=2:g=4"],
    ["ind_bass_e.wav",
     ["-f", "lavfi", "-i", "aevalsrc='(2*mod(41.2*t,1)-1)*exp(-t*7)*0.8':d=0.24:s=#{sr}"],
     "lowpass=f=420,aeval=exprs='tanh(2.8*val(0))/tanh(2.8)'"],
    ["ind_bass_bb.wav",
     ["-f", "lavfi", "-i", "aevalsrc='(2*mod(58.27*t,1)-1)*exp(-t*7)*0.8':d=0.24:s=#{sr}"],
     "lowpass=f=420,aeval=exprs='tanh(2.8*val(0))/tanh(2.8)'"],
    ["ind_stab.wav",
     ["-f", "lavfi", "-i", "anoisesrc=d=0.35:color=white:amplitude=0.9:seed=#{noise_seed(8)}", "-f", "lavfi", "-i", "sine=f=164.81:d=0.35"],
     "[0:a]bandpass=f=280:w=900,aeval=exprs='val(0)*exp(-t*14)'[m];[1:a]aeval=exprs='val(0)*exp(-t*11)'[t];" \
     "[m][t]amix=inputs=2:weights=0.7 0.35,lowpass=f=2800"],
  ]
  recipes.each do |name, inputs, chain|
    dest = File.join(DRUM_DIR, name)
    next if File.exist?(dest) && !force
    if chain.include?("[") || chain.include?(";")
      sh! "ffmpeg", "-y", *inputs, "-filter_complex", chain, "-ar", SAMPLE_RATE.to_s, dest
    else
      sh! "ffmpeg", "-y", *inputs, "-af", chain, "-ar", SAMPLE_RATE.to_s, dest
    end
    puts "kit: #{name}"
  end
end

# True FM (operator modulates operator's frequency at audio rate), not the
# default kit's pitch-swept-sine/filtered-noise approach. Near-1:1 carrier
# ratio on the kick keeps it punchy/tonal; inharmonic (non-integer) ratios
# on hat/open_hat are the classic FM technique for bell/cymbal-like metallic
# timbre. A decaying mod index (index * exp(-t*k)) gives the bright-transient-
# collapsing-to-pure-tone character distinctive of FM percussion.
def generate_fm_drum_kit!
  require_tools! "ffmpeg"
  FileUtils.mkdir_p(FM_DRUM_DIR)
  force = ENV["FORCE_KIT"] == "1"
  sr = SAMPLE_RATE
  recipes = [
    ["kick.wav",
     # FM operator for the punch/click transient, plus a plain sub sine
     # (42Hz, slower decay) for body -- the FM element alone decays too
     # fast to carry real low-end weight now that this is the sole kick,
     # not a niche alternate. Gentle tanh saturation adds analog warmth.
     # A low-level noise floor under the whole hit (not a burst)
     # keeps it from sounding too digitally clean for a kit modeled on
     # dusty analog hardware.
     ["-f", "lavfi", "-i", "aevalsrc='0.85*exp(-t*6)*sin(2*PI*55*t+6*exp(-t*30)*sin(2*PI*58*t))+0.35*exp(-t*9)*sin(2*PI*42*t)':d=0.6:s=#{sr}",
      "-f", "lavfi", "-i", "anoisesrc=d=0.6:color=pink:amplitude=0.02:seed=#{noise_seed(9)}"],
     "[0:a]aeval=exprs='tanh(1.8*val(0))/tanh(1.8)',lowpass=f=240[voice];" \
     "[1:a]lowpass=f=2500[floor];" \
     "[voice][floor]amix=inputs=2:duration=first,acompressor=threshold=-18dB:ratio=3:attack=2:release=45"],
    # Alternate kick voice for the kick/ind_kick alternation cycle
    # (KICK_SAMPLE_CYCLE) -- this was missing for the FM kit entirely, so
    # 1 in 4 kicks silently fell back to the old analog kit's ind_kick.wav
    # even with FM_DRUMS=1. Different carrier:modulator ratio (60:46 vs
    # 55:58) and slightly punchier decay for real per-alternation contrast.
    ["ind_kick.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.85*exp(-t*7)*sin(2*PI*60*t+7*exp(-t*34)*sin(2*PI*46*t))+0.32*exp(-t*10)*sin(2*PI*44*t)':d=0.55:s=#{sr}",
      "-f", "lavfi", "-i", "anoisesrc=d=0.55:color=pink:amplitude=0.02:seed=#{noise_seed(10)}"],
     "[0:a]aeval=exprs='tanh(2.0*val(0))/tanh(2.0)',lowpass=f=250[voice];" \
     "[1:a]lowpass=f=2500[floor];" \
     "[voice][floor]amix=inputs=2:duration=first,acompressor=threshold=-17dB:ratio=3.5:attack=2:release=40"],
    ["snare.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.8*exp(-t*18)*sin(2*PI*200*t+7*exp(-t*35)*sin(2*PI*330*t))':d=0.3:s=#{sr}",
      "-f", "lavfi", "-i", "anoisesrc=d=0.3:color=white:amplitude=0.9:seed=#{noise_seed(11)}",
      "-f", "lavfi", "-i", "anoisesrc=d=0.3:color=pink:amplitude=0.015:seed=#{noise_seed(12)}"],
     "[1:a]highpass=f=1500,lowpass=f=8000,aeval=exprs='val(0)*exp(-t*30)'[crack];" \
     "[2:a]lowpass=f=3000[floor];" \
     "[0:a][crack][floor]amix=inputs=3:weights=0.65 0.68 1,acompressor=threshold=-16dB:ratio=4:attack=2:release=40"],
    # Genuinely distinct voice, not just a quieter snare -- lower mod
    # index (more sine-pure, less metallic "ring") and no crack noise at
    # all, since real ghost notes are soft finger-taps, not scaled-down
    # backbeat hits.
    ["ghost.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.4*exp(-t*40)*sin(2*PI*190*t+2.5*exp(-t*45)*sin(2*PI*260*t))':d=0.13:s=#{sr}"],
     "highpass=f=600,lowpass=f=3500"],
    ["hat.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.85*exp(-t*90)*sin(2*PI*900*t+5*sin(2*PI*3150*t))':d=0.12:s=#{sr}"],
     "highpass=f=4000"],
    ["open_hat.wav",
     ["-f", "lavfi", "-i", "aevalsrc='0.75*exp(-t*10)*sin(2*PI*900*t+5*sin(2*PI*3150*t))':d=0.42:s=#{sr}"],
     "highpass=f=3500"],
  ]
  recipes.each do |name, inputs, chain|
    dest = File.join(FM_DRUM_DIR, name)
    next if File.exist?(dest) && !force
    if chain.include?("[") || chain.include?(";")
      sh! "ffmpeg", "-y", *inputs, "-filter_complex", chain, "-ar", SAMPLE_RATE.to_s, dest
    else
      sh! "ffmpeg", "-y", *inputs, "-af", chain, "-ar", SAMPLE_RATE.to_s, dest
    end
    puts "fm kit: #{name}"
  end
end

def fm_drums_enabled?
  ENV.fetch("FM_DRUMS", "1") != "0"
end

def ensure_fm_drum_kit!
  needed = %w[kick.wav snare.wav hat.wav ghost.wav open_hat.wav ind_kick.wav]
  generate_fm_drum_kit! unless needed.all? { |n| File.exist?(File.join(FM_DRUM_DIR, n)) }
end

def ensure_drum_kit!
  generate_drum_kit! unless drum_kit_ready?
  ensure_fm_drum_kit! if fm_drums_enabled?
end

# Optional one-shots sliced from demucs drums (path under samples/) for DRUM_CHOPS=1.
DRUM_CHOP_SOURCE = "samples/demux/htdemucs_6s/wonky_camel_source/drums.wav"
DRUM_CHOP_DIR = "samples/drums/custom/grid_chops"
DRUM_CHOP_BPM = 86.0

def ensure_drum_chops!
  dest = File.join(ROOT, DRUM_CHOP_DIR)
  return dest if %w[kick.wav snare.wav hat.wav].all? { |n| File.file?(File.join(dest, n)) }
  src = File.join(ROOT, DRUM_CHOP_SOURCE)
  return unless File.file?(src)
  FileUtils.mkdir_p(dest)
  step = 60.0 / DRUM_CHOP_BPM / 4.0
  bar8 = 8 * 4 * step
  { "kick.wav" => 0, "snare.wav" => 4, "hat.wav" => 2 }.each do |name, step_i|
    # A real chop rarely lands exactly on the transient -- a few ms of
    # deterministic slop (seeded by name, not random-per-run, so the same
    # source always chops the same way) instead of an always-exact cut
    # point is closer to how sample-chopping actually sounds.
    slop = (Random.new(stable_hash(name)).rand(-0.012..0.012)).round(4)
    t0 = (bar8 + step_i * step + 0.5 + slop).clamp(0.0, Float::INFINITY).round(3)
    dur = if name.start_with?("kick")
0.28
else
(name.start_with?("snare") ? 0.22 : 0.12)
end
    out = File.join(dest, name)
    ok = system("ffmpeg", "-y", "-ss", t0.to_s, "-t", dur.to_s, "-i", src,
                "-af", "aformat=sample_rates=44100:channel_layouts=mono,highpass=f=30,alimiter=limit=0.95",
                "-c:a", "pcm_s16le", out, out: File::NULL, err: File::NULL)
    FileUtils.rm_f(out) unless ok
  end
  File.file?(File.join(dest, "kick.wav")) ? dest : nil
end

def wav_sample_rate(path)
  out, = Open3.capture2("ffprobe", "-v", "error", "-show_entries", "stream=sample_rate",
                        "-of", "default=noprint_wrappers=1:nokey=1", path)
  out.to_s.strip.to_i
rescue StandardError
  0
end

def load_kit_wav(path)
  return unless path && File.file?(path)
  # DillaMusicGems.read_mono_wav (wavefile gem) decodes raw samples with NO
  # resample — fine for our own kit (already SAMPLE_RATE-native), wrong for
  # external samples at a different native rate (free-drum-samples ships
  # 22050Hz). Loaded at the wrong rate, a hit plays back half-speed and an
  # octave low — this was making the whole external-kit drum sound "horrible".
  # ffprobe first; only take the no-resample fast path when the rate already
  # matches, otherwise force the ffmpeg fallback below which does resample.
  if defined?(DillaMusicGems) && DillaMusicGems.respond_to?(:read_mono_wav) && wav_sample_rate(path) == SAMPLE_RATE
    samples = DillaMusicGems.read_mono_wav(path)
    return samples if samples && !samples.empty?
  end
  # ffmpeg fallback — resamples to SAMPLE_RATE, no wavefile gem required
  raw, = Open3.capture2("ffmpeg", "-v", "error", "-i", path,
                        "-f", "f32le", "-ac", "1", "-ar", SAMPLE_RATE.to_s, "pipe:1")
  return if raw.nil? || raw.empty?
  raw.unpack("e*")
rescue StandardError
  nil
end

# True if drum_sample_path(name) resolved to a real sample (custom dir,
# the external free-drum-samples kit, or the FM kit) rather than the plain
# synthesized fallback directly in DRUM_DIR -- used to stop the camel/grid
# one-shot chops below from silently clobbering a better sample that
# already won. FM_DRUM_DIR is a DRUM_DIR subdirectory, so it needs its own
# check -- a plain start_with?(DRUM_DIR) would treat it as unresolved and
# let the chops overwrite it, the same bug fixed earlier for external kits.
def external_sample_used?(name)
  path = drum_sample_path(name)
  return true if path.start_with?(FM_DRUM_DIR)

  !path.start_with?(DRUM_DIR)
end

def apply_drum_chops_to_kit!(kit)
  # Prefer pre-cut Camel oneshots, then grid_chops from demucs stem — but
  # only for roles that didn't already resolve to a real external-kit
  # sample. These one-shots are all sliced from a single Wonky Camel
  # render (camel_chops and grid_chops are literally byte-identical files),
  # so they were unconditionally overwriting the hat/snare fix above with
  # the same narrow, zero-variety source every render.
  dirs = [
    File.join(CUSTOM_DRUM_DIR, "camel_chops"),
    File.join(ROOT, DRUM_CHOP_DIR),
    ensure_drum_chops!,
  ].compact.uniq
  roles = { kick: "kick.wav", snare: "snare.wav", hat: "hat.wav" }
           .reject { |_, file| external_sample_used?(file) }
  return kit if roles.empty?
  dirs.each do |dest|
    next unless dest && Dir.exist?(dest)
    roles.each do |role, file|
      path = File.join(dest, file)
      samples = load_kit_wav(path)
      kit[role] = samples if samples && !samples.empty?
    end
    # Keep a second kick body for alternation (MPC two-kick habit).
    if roles.key?(:kick)
      alt = load_kit_wav(File.join(dest, "kick.wav"))
      kit[:ind_kick] = alt if alt && !alt.empty? && kit[:ind_kick].nil?
    end
    break if (!roles.key?(:kick) || kit[:kick]) && (!roles.key?(:snare) || kit[:snare])
  end
  kit
end

# --------------------------------------------------------------------------
# engine part: assets
# --------------------------------------------------------------------------
#
# Fetching external soundfonts and kits, and digging the crate.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Explicit, opt-in external asset fetch (never runs on its own — the whole
# engine is otherwise pure-Ruby/ffmpeg synthesis with zero external assets).
# Caches into the same ~/.cache/dilla-soundfonts dir GeneralUser-GS already
# uses, plus a sibling ~/.cache/dilla-samples for one-shot drum WAVs.
EXTERNAL_SOUNDFONTS = {
  "galaxy-electric-pianos.sf2" => "https://smpldsnds.github.io/soundfonts/soundfonts/galaxy-electric-pianos.sf2",
  "supersaw-collection.sf2" => "https://smpldsnds.github.io/soundfonts/soundfonts/supersaw-collection.sf2",
  "giga-hq-fm-gm.sf2" => "https://smpldsnds.github.io/soundfonts/soundfonts/giga-hq-fm-gm.sf2",
  # Yamaha C grand (lite) — acoustic piano body the GM bank never quite nails.
  "yamaha-grand-lite.sf2" => "https://smpldsnds.github.io/soundfonts/soundfonts/yamaha-grand-lite.sf2",
}.freeze
EXTERNAL_DRUM_KIT_REPO = "https://github.com/Boochi44/free-drum-samples"
EXTERNAL_DRUM_KIT_CACHE = File.expand_path("~/.cache/dilla-samples/free-drum-samples")

# Fetched assets are pinned by content: the first fetch records each file's
# SHA256 (and the drum-kit repo's HEAD commit) into checksums.json next to
# the cache; later runs verify and warn on drift instead of silently
# rendering with different-sounding assets. Warn, not abort — upstream may
# have legitimately updated, and the fix is deleting the manifest entry.
def assets_verify_or_record!(manifest_path, key, actual)
  require "digest" # cheap, but only needed on this path
  manifest = File.exist?(manifest_path) ? JSON.parse(File.read(manifest_path)) : {}
  if manifest.key?(key)
    return if manifest[key] == actual
    warn "warn: #{key} changed since first fetch (#{manifest[key][0, 12]}… -> #{actual[0, 12]}…) — " \
         "renders may sound different; delete its entry in #{manifest_path} to accept the new version"
  else
    manifest[key] = actual
    File.write(manifest_path, JSON.pretty_generate(manifest))
  end
end

def fetch_assets!
  require_tools! "curl"
  require "digest"
  sf_dir = File.expand_path("~/.cache/dilla-soundfonts")
  FileUtils.mkdir_p(sf_dir)
  manifest_path = File.join(sf_dir, "checksums.json")
  EXTERNAL_SOUNDFONTS.each do |name, url|
    dest = File.join(sf_dir, name)
    if File.exist?(dest)
      puts "have: #{name}"
    else
      puts "fetching #{name}..."
      sh! "curl", "-sL", "--fail", "-o", dest, url
    end
    assets_verify_or_record!(manifest_path, name, Digest::SHA256.file(dest).hexdigest)
  end

  # VintageDreamsWaves ships with fluid-synth — copy into the cache so
  # patch_sf2_path(:vintage_dreams) is stable and checksummed like the rest.
  vintage_dest = File.join(sf_dir, "VintageDreamsWaves-v2.sf2")
  unless File.exist?(vintage_dest)
    src = Dir.glob("/opt/homebrew/Cellar/fluid-synth/*/share/fluid-synth/sf2/VintageDreamsWaves-v2.sf2").first ||
          Dir.glob("/usr/local/Cellar/fluid-synth/*/share/fluid-synth/sf2/VintageDreamsWaves-v2.sf2").first
    if src && File.exist?(src)
      FileUtils.cp(src, vintage_dest)
      puts "have: VintageDreamsWaves-v2.sf2 (from fluid-synth)"
    end
  end
  if File.exist?(vintage_dest)
    assets_verify_or_record!(manifest_path, "VintageDreamsWaves-v2.sf2",
                             Digest::SHA256.file(vintage_dest).hexdigest)
  end

  if Dir.exist?(EXTERNAL_DRUM_KIT_CACHE)
    puts "have: free-drum-samples"
  else
    require_tools! "git"
    puts "fetching free-drum-samples (CC0)..."
    FileUtils.mkdir_p(File.dirname(EXTERNAL_DRUM_KIT_CACHE))
    sh! "git", "clone", "--depth", "1", EXTERNAL_DRUM_KIT_REPO, EXTERNAL_DRUM_KIT_CACHE
  end
  head, _err, status = capture("git", "-C", EXTERNAL_DRUM_KIT_CACHE, "rev-parse", "HEAD")
  assets_verify_or_record!(manifest_path, "free-drum-samples@HEAD", head.strip) if status.success?
  puts "assets cached. Use DILLA_SOUNDFONT=#{sf_dir}/<file>.sf2, or `ruby dilla.rb use-external-kit <01-hard-trap|02-bounce|03-soulful-vintage>`."
end

# Copies one kit's one-shots into CUSTOM_DRUM_DIR, which drum_sample_path
# already prefers over the synthesized kit — no synthesis code changes
# needed, this populates the existing override hook.
# Dig one seam into samples/dug/, recording provenance per side.
#
# Filtered to the public domain before anything is fetched -- see
# CrateDig.pd_year_ceiling. The engine already refuses to write lyrics from real
# songs because those are copyrighted; this is the same rule applied to audio,
# and it is why this exists instead of another yt-dlp call.
def crate_dig!(seam, count)
  unless seam && CrateDig::SEAMS.key?(seam)
    abort "usage: dig <seam> [n]  — seams: #{CrateDig::SEAMS.keys.join(', ')}"
  end

  puts "digging #{seam} (public domain through #{CrateDig.pd_year_ceiling})..."
  # Over-fetch: some sides are already held and some carry no usable transfer.
  docs = CrateDig.search(collection: "great78", seam: seam, rows: count * 3)
  taken = 0

  docs.each do |doc|
    break if taken >= count

    id = doc["identifier"]
    if CrateDig.have?(id)
      puts "  have: #{id}"
      next
    end

    begin
      file = CrateDig.best_file(id)
      next unless file

      dest = File.join(CrateDig::DUG, seam, "#{id}#{File.extname(file['name'])}")
      print "  #{doc['year']}  #{doc['title'].to_s[0, 44]} ... "
      CrateDig.download(file["url"], dest)
      CrateDig.record!(
        "identifier" => id, "seam" => seam, "year" => doc["year"],
        "title" => doc["title"], "creator" => Array(doc["creator"]).first,
        "source" => "https://archive.org/details/#{id}", "collection" => "great78",
        "basis" => "US public domain — published #{doc['year']}, MMA 100-year term expired",
        "rights" => file["rights"], "licenseurl" => file["licenseurl"],
        "path" => dest.sub("#{ROOT}/", ""),
        "sha256" => Digest::SHA256.file(dest).hexdigest, "bytes" => File.size(dest)
      )
      puts "#{(File.size(dest) / 1024.0 / 1024).round(1)}MB"
      taken += 1
    rescue StandardError => e
      puts "skip (#{e.class}: #{e.message.to_s[0, 60]})"
    end
  end

  puts "dug #{taken} side(s) into #{CrateDig::DUG.sub("#{ROOT}/", '')}/#{seam}/"
  puts "provenance: #{CrateDig::MANIFEST.sub("#{ROOT}/", '')}"
end

# Dig a ccMixter seam — the only legitimate route to reggae, dub and modern
# breaks, because those idioms postdate the public domain entirely.
#
# Everything fetched is CC-BY or freer: commercial use permitted, credit
# required. The credit obligation is real, so `dug --credits` prints it from the
# provenance rather than leaving it to memory.
def cc_dig!(seam, count)
  unless seam && CrateDig::CC_SEAMS.key?(seam)
    abort "usage: dig-cc <seam> [n]  — seams: #{CrateDig::CC_SEAMS.keys.join(', ')}"
  end

  puts "digging ccMixter #{seam} (CC-BY or freer; NC excluded)..."
  rows = CrateDig.ccmixter_search(seam: seam, rows: count * 3)
  taken = 0

  rows.each do |row|
    break if taken >= count

    id = "ccmixter-#{row['upload_id']}"
    if CrateDig.have?(id)
      puts "  have: #{id}"
      next
    end

    begin
      file = Array(row["files"]).find { |f| f["file_name"].to_s =~ /\.(mp3|flac|wav|ogg)\z/i }
      next unless file

      url = file["download_url"] || file["file_url"] ||
            "https://ccmixter.org/content/#{row['user_name']}/#{file['file_name']}"
      dest = File.join(CrateDig::DUG, seam, "#{id}#{File.extname(file['file_name'])}")
      print "  #{row['upload_name'].to_s[0, 40]} — #{row['user_name']} ... "
      CrateDig.download(url, dest)
      sha = Digest::SHA256.file(dest).hexdigest
      # file_name is the file actually downloaded. ccmixter_entry used to record
      # files.first while this picks the first *audio* file, so any upload whose
      # first file is a zip recorded a name that did not match its own sha256.
      CrateDig.record!(CrateDig.ccmixter_entry(row, seam, dest.sub("#{ROOT}/", ""), sha,
                                               file_name: file["file_name"])
                         .merge("bytes" => File.size(dest)))
      puts "#{(File.size(dest) / 1024.0 / 1024).round(1)}MB [#{row['license_name']}]"
      taken += 1
    rescue StandardError => e
      puts "skip (#{e.class}: #{e.message.to_s[0, 60]})"
    end
  end

  puts "dug #{taken} from ccMixter into #{CrateDig::DUG.sub("#{ROOT}/", '')}/#{seam}/"
  puts "these require credit — `ruby dilla.rb credits` prints it" if taken.positive?
end

# CC-BY is free to use and not free of obligation. This is the list you owe.
def crate_credits
  rows = CrateDig.manifest["items"].select { |i| i["attribution"] }
  if rows.empty?
    puts "no attribution owed — everything dug so far is public domain."
    return
  end
  puts "Credits owed (CC-BY material in the crate):"
  rows.each { |i| puts "  #{i['attribution']}" }
  puts
  puts "#{rows.size} item(s). Public-domain sides carry no obligation and are not listed."
end

def crate_seams
  puts "seams (archive.org Great 78, filtered to the public domain):"
  CrateDig::SEAMS.each { |name, q| puts format("  %-12s %s", name, q) }
  puts
  puts "public domain through #{CrateDig.pd_year_ceiling}; widens by one year each January."
end

def dug_list
  items = CrateDig.manifest["items"]
  if items.empty?
    puts "nothing dug yet — try: ruby dilla.rb dig jazz_small 8"
    return
  end
  items.group_by { |i| i["seam"] }.each do |seam, rows|
    puts "#{seam} (#{rows.size})"
    rows.each { |i| puts format("  %s  %-42s %s", i["year"], i["title"].to_s[0, 42], i["creator"]) }
  end
  puts
  # Was "all US public domain", printed over a manifest that by then held six
  # CC-BY items. Public domain carries no obligation and CC-BY carries credit;
  # a summary that flattens them tells the reader they owe nothing.
  pd = items.count { |i| i["collection"] != "ccmixter" }
  cc = items.size - pd
  parts = ["#{pd} public-domain side(s)"]
  parts << "#{cc} CC-licensed (credit owed — run `ruby dilla.rb credits`)" if cc.positive?
  puts "#{parts.join(', ')}. Source URL, licence and SHA-256 per side in " \
       "#{File.basename(CrateDig::MANIFEST)}."
end

def use_external_kit!(kit_name)
  src_dir = File.join(EXTERNAL_DRUM_KIT_CACHE, "drum-samples", kit_name)
  abort "kit '#{kit_name}' not found — run `ruby dilla.rb fetch-assets` first" unless Dir.exist?(src_dir)
  FileUtils.mkdir_p(CUSTOM_DRUM_DIR)
  {
    "kick.wav" => "kicks", "snare.wav" => "snares", "hat.wav" => "hi-hats",
    "open_hat.wav" => "open-hats", "ghost.wav" => "claps", "bass_43.wav" => "808s"
  }.each do |dest_name, subdir|
    src = Dir.glob(File.join(src_dir, subdir, "*.wav")).min_by { |f| File.size(f) }
    next unless src
    FileUtils.cp(src, File.join(CUSTOM_DRUM_DIR, dest_name))
    puts "installed #{dest_name} <- #{kit_name}/#{subdir}/#{File.basename(src)}"
  end
  puts "custom kit installed — clear #{CUSTOM_DRUM_DIR} to go back to synthesized drums."
end

# --------------------------------------------------------------------------
# engine part: synth_samples
# --------------------------------------------------------------------------
#
# Synthesised samples: shakers, cowbells, Karplus-Strong plucks, layered kicks.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def load_mono_sample(path)
  floats = DillaMusicGems.read_mono_wav(path) if defined?(DillaMusicGems)
  return floats if floats&.any?
  pipe_floats(path, "aformat=channel_layouts=mono:sample_fmts=flt")
end

# Abstract-kit kicks are never one thin
# sample — they stack a pitch-dropping sub body for weight, a short
# broadband click for attack/definition, and mild saturation for character.
# Layers on top of the existing sample rather than replacing it.
# Synthesized since no shaker/cowbell samples exist in the kit — filtered
# noise burst for the shaker (broadband "shhh" with a fast-then-slow
# double-envelope, real shaker physics: an initial hit then beads settling)
def synth_shaker_sample(seed: 11)
  len = (0.09 * SAMPLE_RATE).round
  rng = Random.new(seed)
  out = Array.new(len, 0.0)
  len.times do |i|
    t = i.to_f / SAMPLE_RATE
    env = Math.exp(-t * 24.0) + 0.3 * Math.exp(-t * 60.0)
    out[i] = 0.5 * env * (rng.rand * 2.0 - 1.0)
  end
  peak = out.map(&:abs).max || 1.0
  out.map { |s| s / [peak, 0.01].max * 0.8 }
end

# Classic two-oscillator 808/909 cowbell: two square-ish tones (540Hz and
# 800Hz, the real ratio used in analog cowbell circuits) with a fast decay.
def synth_cowbell_sample
  len = (0.18 * SAMPLE_RATE).round
  out = Array.new(len, 0.0)
  len.times do |i|
    t = i.to_f / SAMPLE_RATE
    env = Math.exp(-t * 14.0)
    tone1 = Math.sin(2 * Math::PI * 540.0 * t) > 0 ? 1.0 : -1.0
    tone2 = Math.sin(2 * Math::PI * 800.0 * t) > 0 ? 1.0 : -1.0
    out[i] = 0.42 * env * (0.6 * tone1 + 0.4 * tone2)
  end
  out
end

# Karplus-Strong plucked-string synthesis (Stanford/CCRMA algorithm,
# exact) — a genuinely new instrument timbre, not another oscillator/
# soundfont voice. Fill a ring buffer of noise, then average adjacent
# samples with a stretch factor for decay/damping control.
def karplus_strong_pluck(freq, duration_sec, seed: nil, stretch: 0.996, damping: 0.5)
  n = (SAMPLE_RATE / freq).round.clamp(2, SAMPLE_RATE)
  rng = seed ? Random.new(seed) : Random.new
  buf = Array.new(n) { rng.rand * 2.0 - 1.0 }
  total = (duration_sec * SAMPLE_RATE).round
  out = Array.new(total, 0.0)
  total.times do |i|
    idx = i % n
    if i < n
      out[i] = buf[idx]
    else
      prev = out[i - n]
      prev2 = out[i - n - 1] || prev
      averaged = damping * prev + (1.0 - damping) * prev2
      out[i] = stretch * averaged
    end
  end
  out
end

def raw_kick_samples?
  # LAYER_KICK=1 asks for the layered kick explicitly, and outranks every reason
  # below to use the sample as it is.
  #
  # An external kit turns layering off (line below) so a chosen kick arrives
  # unaltered rather than re-coated with the same synth every time -- correct as
  # a default. But the LA beat-scene kick IS a layered one: a sampled top for the
  # click and attack, a synthesised sub underneath it for the weight, which is
  # what a single sampled one-shot cannot do at that depth. Wanting a real kit
  # and a layered kick at once was unreachable, since choosing the kit silently
  # decided the other question too.
  return false if ENV["LAYER_KICK"] == "1"
  return true if ENV["RAW_KICK"] == "1" || ENV["DRUM_SAMPLE_RAW"] == "1"
  return true if comfort_mode?
  return true if ENV["EXTERNAL_KIT"] && !ENV["EXTERNAL_KIT"].empty?

  path = drum_sample_path("kick.wav")
  path&.start_with?(CUSTOM_DRUM_DIR)
end

def normalize_drum_sample(samples, peak: 0.7)
  return samples if samples.nil? || samples.empty?

  max = samples.map(&:abs).max || 1.0
  return samples if max < 1.0e-6

  mul = peak / max
  samples.map { |s| s * mul }
end

# EXTERNAL_KIT names that are built from oneshots already in samples/drums/
# rather than pulled from the download cache. The asset check has to know them
# too: it refuses a kit that is not in the cache, and refusing one that never
# needed to be there stops a render that would have worked.
BUILTIN_EXTERNAL_KITS = %w[industrial industrial_techno].freeze

# The one oneshot a builtin kit cannot be assembled without: the marker below
# is only trusted alongside custom/kick.wav, so a missing ind_kick.wav means
# the install produced nothing usable.
BUILTIN_EXTERNAL_KIT_PROBE = "ind_kick.wav"

# Can this EXTERNAL_KIT be installed on this machine?
#
# One predicate for both readers. "industrial is a builtin name" and "industrial
# resolves here" are different claims, and only the second is worth refusing a
# render over. samples/ is gitignored, so the ind_* oneshots are machine-local:
# a machine without them passes a name check, copies nothing, writes the marker
# and renders the synthesized kit — a finished beat that is not the one the
# recipe asked for.
#
# Two sources today. A third belongs here, not in a second list.
def external_kit_resolvable?(kit)
  kit = kit.to_s
  return false if kit.empty?
  return File.file?(File.join(DRUM_DIR, BUILTIN_EXTERNAL_KIT_PROBE)) if BUILTIN_EXTERNAL_KITS.include?(kit)

  Dir.exist?(File.join(EXTERNAL_DRUM_KIT_CACHE, "drum-samples", kit))
end

# Install EXTERNAL_KIT oneshots into samples/drums/custom/ once so
# drum_sample_path prefers them over synthesized DRUM_DIR files.
def ensure_external_kit_installed!
  kit = ENV["EXTERNAL_KIT"].to_s
  return if kit.empty?

  marker = File.join(CUSTOM_DRUM_DIR, ".external_kit")
  if File.file?(marker) && File.read(marker).strip == kit && File.file?(File.join(CUSTOM_DRUM_DIR, "kick.wav"))
    return
  end

  FileUtils.mkdir_p(CUSTOM_DRUM_DIR)

  if BUILTIN_EXTERNAL_KITS.include?(kit)
    # Built-in industrial one-shots under samples/drums/ind_*.
    mapping = {
      "kick.wav" => "ind_kick.wav",
      "snare.wav" => "ind_clap.wav",
      "ghost.wav" => "ind_clap.wav",
      "hat.wav" => "ind_hat.wav",
      "open_hat.wav" => "ind_hat.wav",
      "bass_43.wav" => "ind_bass_e.wav",
    }
    mapping.each do |dest_name, src_name|
      src = File.join(DRUM_DIR, src_name)
      next unless File.file?(src)

      FileUtils.cp(src, File.join(CUSTOM_DRUM_DIR, dest_name))
    end
    File.write(marker, kit)
    dmesg("industrial kit → custom/", unit: "drums0", parent: "dilla0") if respond_to?(:dmesg)
    return
  end

  src_dir = File.join(EXTERNAL_DRUM_KIT_CACHE, "drum-samples", kit)
  return unless Dir.exist?(src_dir)

  {
    "kick.wav" => "kicks", "snare.wav" => "snares", "hat.wav" => "hi-hats",
    "open_hat.wav" => "open-hats", "ghost.wav" => "claps", "bass_43.wav" => "808s"
  }.each do |dest_name, subdir|
    candidates = Dir.glob(File.join(src_dir, subdir, "*.wav")).sort_by { |f| File.size(f) }
    src = candidates[candidates.length / 2] || candidates.first
    next unless src

    FileUtils.cp(src, File.join(CUSTOM_DRUM_DIR, dest_name))
  end
  File.write(marker, kit)
  dmesg("external kit #{kit} → custom/", unit: "drums0", parent: "dilla0") if respond_to?(:dmesg)
rescue StandardError => e
  warn "ensure_external_kit_installed!: #{e.message}"
end

def layered_kick_sample(base_sample, seed: 7)
  # True 808-style envelope, not a short punch: a fast pitch drop (150Hz ->
  # 42Hz over ~55ms, the "pluck") into a genuinely sustained low tone
  # (~350ms total, slow decay) — the long boom is the whole point of an
  # 808, not an incidental side effect of layering.
  sub_len = (0.35 * SAMPLE_RATE).round
  click_len = (0.009 * SAMPLE_RATE).round
  out = base_sample.dup
  out.concat(Array.new(sub_len - out.length, 0.0)) if out.length < sub_len
  sub_len.times do |i|
    t = i.to_f / SAMPLE_RATE
    pitch = 42.0 + 108.0 * Math.exp(-t * 55.0)
    env = Math.exp(-t * 9.0)
    out[i] += 0.34 * env * Math.sin(2 * Math::PI * pitch * t)
  end
  rng = Random.new(seed)
  click_len.times do |i|
    t = i.to_f / SAMPLE_RATE
    env = Math.exp(-t * 380.0)
    out[i] += 0.14 * env * (rng.rand * 2.0 - 1.0)
  end
  # Body layer: a short mid-punch (~150Hz) between the sub and the click —
  # definition that survives on small speakers where the 42Hz fundamental
  # barely reproduces at all.
  body_len = (0.05 * SAMPLE_RATE).round
  body_len.times do |i|
    t = i.to_f / SAMPLE_RATE
    env = Math.exp(-t * 55.0)
    out[i] += 0.18 * env * Math.sin(2 * Math::PI * 150.0 * t)
  end
  peak = out.map(&:abs).max || 1.0
  gain = peak > 0.95 ? 0.95 / peak : 1.0
  # A single gentle saturation pass, not stacked with anything downstream —
  # double saturation (this plus a second stage on the whole drum bus) is
  # what made it sound bad, not the layering itself.
  drive = 1.1
  ceiling = Math.tanh(drive)
  # Old formula (0.16*KICK_GAIN+0.06) crushed kicks to ~0.2 peak before the bus —
  # inaudible under pads. Camel/Wonky needs near-unity sample level.
  sample_mul = if wonky_primary_drums?
                 ENV.fetch("KICK_SAMPLE_GAIN", "0.95").to_f.clamp(0.4, 1.2)
               else
                 (0.16 * kick_velocity_scale + 0.06).clamp(0.08, 0.55)
               end
  out.map { |s| (Math.tanh(s * gain * drive) / ceiling) * sample_mul }
end

def mix_sine!(left, right, frame, frames_n, hz, amp, decay: 2.6, mod_hz: 0.23, chorus: false,
              source_offset: 0)
  voices = if chorus
             [{ cents: 0.0, pan: 0.0, gain: 0.55 }, { cents: 5.5, pan: -0.42, gain: 0.28 },
              { cents: -5.5, pan: 0.42, gain: 0.28 }, { cents: 11.0, pan: -0.18, gain: 0.12 }]
           else
             [{ cents: 0.0, pan: 0.0, gain: 1.0 }]
           end
  frames_n.times do |i|
    idx = frame + i
    break if idx >= left.length
    t = (source_offset + i).to_f / SAMPLE_RATE
    env = Math.exp(-t * decay) * (0.78 + 0.22 * Math.sin(2 * Math::PI * mod_hz * t))
    voices.each do |voice|
      fh = hz * (2 ** (voice[:cents] / 1200.0))
      s = amp * voice[:gain] * env * Math.sin(2 * Math::PI * fh * t)
      pan = voice[:pan]
      left[idx] += s * (0.5 - pan * 0.5)
      right[idx] += s * (0.5 + pan * 0.5)
    end
  end
end

# --------------------------------------------------------------------------
# engine part: native_synth
# --------------------------------------------------------------------------
#
# The native Ruby synthesiser: waveforms, FM, pad rendering.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

STREAM_CHUNK_SECONDS = 4
PAD_RENDER_SAMPLE_RATE = 22_050

def soft_clip_sample(sample, knee: 0.85)
  magnitude = sample.abs
  return sample if magnitude <= knee

  sample.negative? ? -(knee + (1.0 - knee) * Math.tanh((magnitude - knee) / (1.0 - knee))) :
                     knee + (1.0 - knee) * Math.tanh((magnitude - knee) / (1.0 - knee))
end

def soft_clip_stereo_chunk!(left, right)
  left.map! { |sample| soft_clip_sample(sample) }
  right.map! { |sample| soft_clip_sample(sample) }
end

# Write long buses incrementally. At 44.1 kHz a five-minute stereo Float array
# can exceed a gigabyte in Ruby; fixed-size chunks keep the render bounded while
# preserving oscillator phase and one-shot tails across chunk boundaries.
def write_stereo_chunks(path, duration, chunk_seconds: STREAM_CHUNK_SECONDS)
  total_frames = (duration * SAMPLE_RATE).ceil
  chunk_frames = [(chunk_seconds * SAMPLE_RATE).to_i, 1].max
  stdin, stdout, stderr, wait = Open3.popen3(
    "ffmpeg", "-v", "error", "-y", "-f", "f32le", "-ar", SAMPLE_RATE.to_s,
    "-ac", "2", "-i", "-", "-c:a", "pcm_s16le", path
  )
  out_reader = Thread.new { stdout.read }
  err_reader = Thread.new { stderr.read }
  chunk_start = 0
  while chunk_start < total_frames
    count = [chunk_frames, total_frames - chunk_start].min
    left = Array.new(count, 0.0)
    right = Array.new(count, 0.0)
    yield chunk_start, count, left, right
    # A fixed transfer curve is invariant across chunk boundaries; per-chunk
    # normalization would audibly pump a sustained pad every four seconds.
    soft_clip_stereo_chunk!(left, right)
    interleaved = Array.new(count * 2)
    count.times do |i|
      interleaved[i * 2] = left[i]
      interleaved[i * 2 + 1] = right[i]
    end
    stdin.write(interleaved.pack("e*"))
    chunk_start += count
  end
  stdin.close
  status = wait.value
  out_reader.value
  error = err_reader.value
  abort "wav stream failed: #{error}" unless status.success?
  path
ensure
  stdin&.close unless stdin&.closed?
end

def overlap_window(event_frame, event_frames, chunk_start, chunk_frames)
  overlap_start = [event_frame, chunk_start].max
  overlap_end = [event_frame + event_frames, chunk_start + chunk_frames].min
  return if overlap_end <= overlap_start

  [overlap_start - chunk_start, overlap_start - event_frame, overlap_end - overlap_start]
end

def fm_native_enabled?
  return false if ENV["FM_NATIVE"] == "0"
  return true if ENV["FM_NATIVE"] == "1"
  synth_morph_enabled? || lead_morph_enabled?
end

def fm_ratio_for_chord(event_idx)
  FM_RATIO_POOL[event_idx % FM_RATIO_POOL.length]
end

def fm_mod_ratio_expr(m_start, m_end, sustain, irrational:)
  return m_start.round(4).to_s unless irrational && m_start != m_end
  s = [sustain, 0.01].max.round(4)
  ms = m_start.round(4)
  me = m_end.round(4)
  "#{ms}+(#{me}-#{ms})*min(1,t/#{s})"
end

def fm_index_from_velocity(velocity, base_index:, role: :pad)
  vel = velocity.to_f.clamp(0.05, 1.0)
  scale = role == :xlead ? FM_INDEX_VEL_SCALE : (FM_INDEX_VEL_SCALE * 0.75)
  (base_index * (0.45 + vel * scale * 0.18)).round(3)
end

def fm_mod_envelope(role: :pad, atk: nil, decay: nil, sustain_level: nil)
  case role
  when :xlead
    a = (atk || 0.004).round(4)
    d = (decay || 0.28).round(4)
    s = (sustain_level || 0.35).round(3)
  else
    a = ((atk || 0.004) * 2.5).round(4)
    d = ((decay || 0.28) * 0.55).round(4)
    s = ((sustain_level || 0.35) * 0.9).round(3)
  end
  "min(1,pow(t/#{[a, 0.001].max},0.9))*((1-#{s})*exp(-t*#{d})+#{s})"
end

def native_fm_waveform_body(frequency, index_expr:, bloom: 0.2, drift: "1", detune: 0.004,
                            feedback: 0.0, phase_seed: 0.0, mod_ratio_expr: "1")
  f = frequency.round(4)
  det_up = (frequency * (1.0 + detune)).round(4)
  f_m = "(#{f}*(#{mod_ratio_expr}))"
  mod = "sin(2*PI*#{f_m}*#{drift}*t+#{phase_seed.round(3)})"
  phase_arg = "2*PI*#{f}*#{drift}*t+(#{index_expr})*#{mod}"
  fb = feedback.to_f.round(3)
  phase_arg = "#{phase_arg}+#{fb}*sin(#{phase_arg})" if fb.positive?
  carrier = "sin(#{phase_arg})"
  "0.70*#{carrier}+#{bloom.round(3)}*sin(2*PI*#{f}*#{drift}*t)+0.12*sin(2*PI*#{det_up}*#{drift}*t)"
end

# Additive (band-limited) sawtooth as an ffmpeg expression: sum sin(2*PI*n*f*t)/n
# for n = 1..N. Every other saw in native_waveform_body is the naive
# 2*mod(f*t,1)-1, whose instantaneous phase reset generates harmonics all the way
# up and folds everything above Nyquist back down as inharmonic grit -- audible
# as fizz on sustained pads. Summing partials instead is anti-aliased by
# construction: N is capped so N*f stays under Nyquist, so high notes get
# fewer partials. (PolyBLEP would be the usual fix, but it is a per-sample
# technique and this path emits an expression string for aevalsrc, not a Ruby
# sample loop -- the standalone jazz-hop/techno experiment that explored the
# version.) HARMONIC_CAP keeps the expression from exploding: a chord is ~5
# voices x 3 detuned oscillators x N terms, per event.
SAW_HARMONIC_CAP = (ENV["SAW_HARMONICS"] || 8).to_i.clamp(2, 24)

def band_limited_saw_expr(frequency, drift)
  nyquist = PAD_RENDER_SAMPLE_RATE / 2.0
  n_max = [(nyquist / frequency).floor, SAW_HARMONIC_CAP].min
  n_max = 1 if n_max < 1
  (1..n_max).map do |n|
    "#{(1.0 / n).round(4)}*sin(2*PI*#{(frequency * n).round(4)}*#{drift}*t)"
  end.join("+")
end

def native_waveform_body(frequency, wave:, bloom: 0.2, drift: "1", detune: 0.004, phase_seed: 0.0,
                         fm_index_expr: nil, mod_ratio_expr: nil, fm_feedback: 0.0)
  f = frequency.round(4)
  det_up = (frequency * (1.0 + detune)).round(4)
  det_dn = (frequency * (1.0 - detune)).round(4)
  case wave
  when :analog_pad
    # Three-oscillator detuned saw stack, the classic warm analog pad. The
    # detune has to be in real cents to do anything: the beating between
    # oscillators IS the sound. (A proposal that suggested this used
    # [-0.03, 0, 0.03] "cents" applied as 2**(c/1200) -- 0.0000173%, so all
    # three oscillators came out bit-identical and it was a louder saw.)
    cents = (ENV["ANALOG_PAD_DETUNE_CENTS"] || 7.0).to_f.clamp(0.0, 50.0)
    spread = ->(c) { (frequency * (2.0**(c / 1200.0))).round(4) }
    [
      "0.42*(#{band_limited_saw_expr(spread.call(-cents), drift)})",
      "0.36*(#{band_limited_saw_expr(f, drift)})",
      "0.42*(#{band_limited_saw_expr(spread.call(cents), drift)})",
      # Sub octave for body, and a touch of breath noise for analog air.
      "#{bloom.round(3)}*sin(2*PI*#{(frequency * 0.5).round(4)}*#{drift}*t)",
      "0.015*(random(0)-0.5)",
    ].join("+")
  when :saw
    "0.55*(2*mod(#{f}*#{drift}*t,1)-1)+0.22*(2*mod(#{det_up}*#{drift}*t,1)-1)+0.18*(2*mod(#{det_dn}*#{drift}*t,1)-1)"
  # :triangle and :square took a detune: and threw it away — every caller that
  # set one got a single-frequency tone with no beating, and nothing said so.
  # The detuned partial is quiet (0.18) so these keep their shape; what they
  # gain is movement.
  when :triangle
    "0.62*(2*abs(2*mod(#{f}*#{drift}*t,1)-1)-1)+0.20*sin(2*PI*#{f}*#{drift}*t)" \
      "+0.18*(2*abs(2*mod(#{det_up}*#{drift}*t,1)-1)-1)"
  when :square
    "0.48*(2*floor(2*mod(#{f}*#{drift}*t,1))-1)+0.28*sin(2*PI*#{f * 2.0}*#{drift}*t)" \
      "+0.18*(2*floor(2*mod(#{det_dn}*#{drift}*t,1))-1)"
  when :pwm
    pw = "0.35+0.15*sin(2*PI*0.4*t+#{phase_seed.round(3)})"
    "0.5*(2*floor(mod(#{f}*#{drift}*t,1)/(#{pw}))-1)+0.25*sin(2*PI*#{det_up}*#{drift}*t)"
  when :fm
    idx = fm_index_expr || "2.2"
    native_fm_waveform_body(frequency, index_expr: idx, bloom:, drift:,
                                   detune:, feedback: fm_feedback, phase_seed:,
                                   mod_ratio_expr: mod_ratio_expr || "1.5")
  when :organ
    # Detuned on the fundamental only. A drawbar organ's movement comes from
    # slightly out-of-tune tonewheels beating against each other, so the
    # detune: this took and discarded is exactly the parameter it wanted.
    "0.42*sin(2*PI*#{f}*#{drift}*t)+0.28*sin(2*PI*#{f * 2.0}*#{drift}*t)+0.18*sin(2*PI*#{f * 3.0}*#{drift}*t)+0.12*sin(2*PI*#{f * 4.0}*#{drift}*t)" \
      "+0.16*sin(2*PI*#{det_up}*#{drift}*t)"
  when :bowed
    "0.55*sin(2*PI*#{f}*#{drift}*t)+0.25*sin(2*PI*#{f * 2.0}*#{drift}*t)+0.12*sin(2*PI*#{f * 3.0}*#{drift}*t)"
  when :juno
    "0.50*sin(2*PI*#{f}*#{drift}*t)+0.30*sin(2*PI*#{det_up}*#{drift}*t)+0.20*sin(2*PI*#{det_dn}*#{drift}*t)+" \
    "#{bloom.round(3)}*sin(2*PI*#{f * 2.0}*#{drift}*t)"
  when :moog
    sub = (frequency * 0.5).round(4)
    f2 = (frequency * 2.0).round(4)
    # Ladder-ish: saw stack + sub octave, soft triangle body for warmth.
    "0.46*(2*mod(#{f}*#{drift}*t,1)-1)+0.20*(2*mod(#{det_up}*#{drift}*t,1)-1)+" \
    "0.14*(2*mod(#{det_dn}*#{drift}*t,1)-1)+#{bloom.round(3)}*(2*mod(#{sub}*#{drift}*t,1)-1)+" \
    "0.12*(2*abs(2*mod(#{f}*#{drift}*t,1)-1)-1)+0.08*sin(2*PI*#{f2}*#{drift}*t)"
  when :prophet
    det2 = (frequency * (1.0 + detune * 1.8)).round(4)
    det3 = (frequency * (1.0 - detune * 1.8)).round(4)
    # Prophet-5 unison: five slightly detuned saws + gentle 2nd harmonic.
    "0.30*(2*mod(#{f}*#{drift}*t,1)-1)+0.20*(2*mod(#{det_up}*#{drift}*t,1)-1)+" \
    "0.20*(2*mod(#{det_dn}*#{drift}*t,1)-1)+0.14*(2*mod(#{det2}*#{drift}*t,1)-1)+" \
    "0.12*(2*mod(#{det3}*#{drift}*t,1)-1)+#{bloom.round(3)}*sin(2*PI*#{f * 2.0}*#{drift}*t)+" \
    "0.06*sin(2*PI*#{f}*#{drift}*t)"
  else # :rhodes default — tine fundamental + odd harmonics + stereo detune
    f3 = (frequency * 3.0).round(4)
    f5 = (frequency * 5.0).round(4)
    bell = "exp(-t*18)*sin(2*PI*#{f * 4.0}*t)"
    "0.58*sin(2*PI*#{f}*#{drift}*t)+#{bloom.round(3)}*sin(2*PI*#{f3}*#{drift}*t)+" \
    "0.06*sin(2*PI*#{f5}*#{drift}*t)+0.22*sin(2*PI*#{det_up}*#{drift}*t)+" \
    "0.22*sin(2*PI*#{det_dn}*#{drift}*t)+0.12*#{bell}"
  end
end

def native_pad_voice_expression(hz, amp, voice_i, pan, phase_seed, native_patch: nil,
                                event_i: 0, velocity: 0.72, sustain: 8.0)
  frequency = hz.round(4)
  drift = "(1+0.0014*sin(2*PI*0.065*t+#{phase_seed.round(3)}))"
  wave = @render_pad_native_wave || DillaLofiMachine.native_wave_for_pad
  native = native_patch&.dig(:native) || @render_native_patch&.dig(:native) ||
           { wave:, detune: 0.004, bloom: 0.28 }
  pad_gain = @render_pad_gain || 1.0
  wave_sym = native[:wave] || :rhodes
  fm_index_expr = nil
  mod_ratio_expr = nil
  fm_feedback = native[:fm_feedback] || 0.0
  if wave_sym == :fm && fm_native_enabled?
    # A fixed native[:fm_ratio] lets a patch keep an authentic, unchanging
    # C:M ratio (e.g. 14:1 for an e-piano tine) instead of the rotating
    # FM_RATIO_POOL every other :fm voice shares.
    ratio = native[:fm_ratio] || fm_ratio_for_chord(event_i + voice_i)
    mod_ratio_expr = fm_mod_ratio_expr(ratio[:m], ratio[:target_m], sustain, irrational: ratio[:irrational])
    base_idx = fm_index_from_velocity(velocity, base_index: native[:fm_index] || FM_INDEX_BASE_PAD, role: :pad)
    mod_env = fm_mod_envelope(role: :pad)
    fm_index_expr = "(#{base_idx})*#{mod_env}"
    fm_feedback = native[:fm_feedback] || FM_FEEDBACK_DEFAULT * 0.65
  end
  body = native_waveform_body(frequency, wave: wave_sym, bloom: native[:bloom] || 0.2,
                              drift:, detune: native[:detune] || 0.004, phase_seed:,
                              fm_index_expr:, mod_ratio_expr:,
                              fm_feedback:)
  breathe = "(0.80+0.20*sin(2*PI*#{(0.16 + voice_i * 0.025).round(3)}*t+#{phase_seed.round(3)}))"
  atk = (@render_pad_attack_sec || 0.072).round(4)
  # native[:pad_release] lets a patch decay independently of the global pad
  # release -- a bell/tine transient needs a much faster exp(-t*rel) decay
  # than the sustained body layer it's mixed under.
  rel = (native[:pad_release] || @render_pad_release_decay || 0.07).round(4)
  env = "min(1,pow(t/#{atk},1.15))*exp(-t*#{rel})*#{breathe}"
  ["#{(amp * pad_gain).round(6)}*#{(0.5 - pan * 0.5).round(4)}*#{env}*#{body}",
   "#{(amp * pad_gain).round(6)}*#{(0.5 + pan * 0.5).round(4)}*#{env}*#{body}"]
end

def render_native_pad_wav(path, pad_events, duration)
  filters = []
  labels = []
  pad_events.each_with_index do |(time, velocity, chord, sustain), event_i|
    next unless chord
    left_parts = []
    right_parts = []
    chord[:hz].sort.each_with_index do |hz, voice_i|
      pan = [-0.38, -0.12, 0.14, 0.36, 0.22][voice_i % 5]
      amp = velocity * (0.058 + voice_i * 0.0048)
      pair = native_pad_voice_expression(hz, amp, voice_i, pan, event_i * 0.55 + voice_i * 0.9,
                                        event_i:, velocity:, sustain:)
      left_parts << pair[0]
      right_parts << pair[1]
      next unless voice_i.zero?

      sub_pair = native_pad_voice_expression(hz * 0.5, amp * 0.42, voice_i + 5, pan, event_i * 0.61,
                                             event_i:, velocity: velocity * 0.82, sustain:)
      left_parts << sub_pair[0]
      right_parts << sub_pair[1]
    end
    delay = [(time * 1000.0).round, 0].max
    label = "pad#{event_i}"
    # The pad is low-passed below 3 kHz later, so a half-rate oscillator bed is
    # lossless for its audible band and roughly halves long-render DSP time.
    filters << "aevalsrc=exprs='#{expr_sum(left_parts)}|#{expr_sum(right_parts)}':d=#{sustain.round(4)}:s=#{PAD_RENDER_SAMPLE_RATE}," \
               "adelay=#{delay}|#{delay}[#{label}]"
    labels << "[#{label}]"
  end
  if labels.empty?
    filters << "anullsrc=r=#{PAD_RENDER_SAMPLE_RATE}:cl=stereo:d=#{duration}[pads]"
  else
    filters << "#{labels.join}amix=inputs=#{labels.length}:duration=longest:normalize=0," \
               "atrim=0:#{duration},alimiter=limit=0.95:level_out=0.96[pads]"
  end
  sh_filter_complex!(filters.join(";"), "-map", "[pads]", "-ar", SAMPLE_RATE.to_s, "-c:a", "pcm_s16le", path)
  path
end

# Real per-hit synthesis (see native_pad_voice_expression) for one layer of
# a PAD_LAYER_STACKS entry -- the layered-mix counterpart to
# render_native_pad_wav above, which only ever renders one voice for the
# whole pad bed. Opt-in via NATIVE_FM_PADS=1; render_one_pad_layer! decides
# whether a given layer's patch routes here or through FluidSynth.
def native_fm_layers_enabled?
  ENV.fetch("NATIVE_FM_PADS", "0") != "0"
end

def render_native_pad_layer!(voice_path, pad_events, duration, patch)
  filters = []
  labels = []
  pad_events.each_with_index do |(time, velocity, chord, sustain), event_i|
    next unless chord
    left_parts = []
    right_parts = []
    chord[:hz].sort.each_with_index do |hz, voice_i|
      pan = [-0.38, -0.12, 0.14, 0.36, 0.22][voice_i % 5]
      amp = velocity * (0.058 + voice_i * 0.0048) * (patch[:mix] || 1.0)
      pair = native_pad_voice_expression(hz, amp, voice_i, pan, event_i * 0.55 + voice_i * 0.9,
                                        native_patch: patch, event_i:, velocity:, sustain:)
      left_parts << pair[0]
      right_parts << pair[1]
    end
    delay = [(time * 1000.0).round, 0].max
    label = "pad#{event_i}"
    filters << "aevalsrc=exprs='#{expr_sum(left_parts)}|#{expr_sum(right_parts)}':d=#{sustain.round(4)}:s=#{PAD_RENDER_SAMPLE_RATE}," \
               "adelay=#{delay}|#{delay}[#{label}]"
    labels << "[#{label}]"
  end
  if labels.empty?
    filters << "anullsrc=r=#{PAD_RENDER_SAMPLE_RATE}:cl=stereo:d=#{duration}[pads]"
  else
    filters << "#{labels.join}amix=inputs=#{labels.length}:duration=longest:normalize=0," \
               "atrim=0:#{duration},alimiter=limit=0.95:level_out=0.96[pads]"
  end
  sh_filter_complex!(filters.join(";"), "-map", "[pads]", "-c:a", "pcm_s16le", voice_path)
  voice_path
end

# --------------------------------------------------------------------------
# engine part: midi_smf
# --------------------------------------------------------------------------
#
# Writing standard MIDI files and their FX automation.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- FluidSynth pad rendering (real sampled electric-piano tone instead of ---
# --- the pure-additive-sine aevalsrc engine above) -------------------------

# GM program 4 = "Electric Piano 1" (Rhodes-style) — the classic Dilla/neo-soul
# keys tone. Overridable since a different soundfont's map may differ.
PAD_GM_PROGRAM = ENV.fetch("DILLA_PAD_PROGRAM", "4").to_i
# Electric-piano family (Dilla/neo-soul: Rhodes, Wurlitzer-adjacent DX EP)
# and warm-analog-pad family (Prophet/Moog-adjacent GM pad patches) — a
# different pair picked per render instead of the same two programs every
# time.
EP_GM_PROGRAMS = [4, 5, 0, 2, 1, 3].freeze # Rhodes, DX EP, acoustic, Electric Grand, Wurlitzer-adjacent
SMF_PPQN = 480
SMF_TICKS_PER_SECOND = SMF_PPQN * 2 # fixed internal reference tempo of 120 BPM

def pad_soundfont_path
  return ENV["DILLA_SOUNDFONT"] if ENV["DILLA_SOUNDFONT"] && File.exist?(ENV["DILLA_SOUNDFONT"])

  # GeneralUser GS (mrbumpy409/GeneralUser-GS on GitHub, free-for-any-use
  # license) — a real 261-preset GM bank, cached locally rather than
  # committed to the repo. Falls back to fluid-synth's small bundled test
  # font if it hasn't been fetched.
  cached = File.expand_path("~/.cache/dilla-soundfonts/GeneralUser-GS.sf2")
  return cached if File.exist?(cached)

  Dir.glob("/opt/homebrew/Cellar/fluid-synth/*/share/fluid-synth/sf2/*.sf2")
     .find { |f| f.match?(/VintageDreamsWaves-v2\.sf2\z/) }
end

def fluidsynth_pad_available?
  tool_available?("fluidsynth") && !pad_soundfont_path.nil?
end

def midi_vlq(number)
  bytes = [number & 0x7f]
  number >>= 7
  while number.positive?
    bytes.unshift((number & 0x7f) | 0x80)
    number >>= 7
  end
  bytes.pack("C*")
end

# A simpler lead: fewer things moving, and nothing moving the pitch.
#
# The lead carried nine simultaneous automation lanes — mod wheel, portamento
# time, pan, expression, resonance, a filter sweep, reverb and chorus sends, and
# an 8-cent pitch LFO — on top of a 0.92 gate, which is near-continuous legato.
# Everything slid into everything else.
#
# Two kinds of lane are dropped rather than reduced. `bend:` is a pitch LFO and
# CC5 is portamento time; both modulate frequency, so they are what makes a line
# read as gliding rather than as played notes. The rest survive at roughly half
# depth, which keeps the patch alive without the movement being the subject.
#
# LEAD_SIMPLE=0 restores the full automation and the original gates.
def lead_simple? = ENV.fetch("LEAD_SIMPLE", "1") != "0"

LEAD_SIMPLE_GATE_MAX = 0.6
LEAD_SIMPLE_DEPTH_SCALE = 0.5

def simplify_lead_midi_fx(specs)
  return specs unless lead_simple?

  Array(specs).reject { |s| s[:bend] || s[:cc] == 5 }.map do |s|
    s[:depth] ? s.merge(depth: (s[:depth] * LEAD_SIMPLE_DEPTH_SCALE).round) : s
  end
end

def midi_fx_specs_for_role(role, patch = nil)
  base = patch&.dig(:midi_fx)
  if role == :lead || role == :lead_arp
    # Rich stacks three more lanes on top; simple mode never wants it.
    rich = !lead_simple? && ENV.fetch("STREAM_LEAD_MIDI_RICH", "1") != "0"
    return simplify_lead_midi_fx(rich ? MIDI_FX_LEAD_RICH : MIDI_FX_LEAD) unless base && !base.empty?
    simplify_lead_midi_fx(rich ? (base + MIDI_FX_LEAD_RICH.last(3)) : base)
  elsif role == :scale_lead
    (base && !base.empty?) ? base : MIDI_FX_SCALE_LEAD
  else
    base || case role
            when :ep then MIDI_FX_PAD_EP
            when :warm, :texture then MIDI_FX_PAD_WARM
            end
  end
end

def midi_fx_automation(duration, specs, channel: 0)
  return [] unless duration && specs && !specs.empty?
  ticks_total = (duration * SMF_TICKS_PER_SECOND).round
  out = []
  specs.each do |spec|
    if spec[:bend]
      rate = spec.fetch(:rate_hz, 0.3)
      depth = spec.fetch(:depth_cents, 10)
      samples = (duration * 6).ceil.clamp(8, 48)
      samples.times do |i|
        tick = (i * ticks_total.to_f / samples).round
        t = i.to_f / samples
        cents = depth * Math.sin(2 * Math::PI * rate * duration * t)
        bend_val = (8192 + (cents / 100.0 * 4096)).round.clamp(0, 16_383)
        lsb = bend_val & 0x7f
        msb = (bend_val >> 7) & 0x7f
        out << [tick, [0xE0 | channel, lsb, msb]]
      end
      next
    end
    cc = spec[:cc]
    depth = spec.fetch(:depth, 40)
    base = spec.fetch(:base, 30)
    rate = spec.fetch(:rate_hz, 0.25)
    curve = spec.fetch(:curve, :sine)
    samples = (duration * 6).ceil.clamp(8, 48)
    samples.times do |i|
      tick = (i * ticks_total.to_f / samples).round
      t = i.to_f / [samples - 1, 1].max
      val = case curve
            when :sine then base + depth * Math.sin(2 * Math::PI * rate * duration * (i.to_f / samples))
            when :swell then base + depth * Math.sin(Math::PI * t * 0.85)
            when :slow_open then spec.fetch(:start, 60) + (spec.fetch(:end, 110) - spec.fetch(:start, 60)) * t
            else base
            end
      out << [tick, [0xB0 | channel, cc, val.round.clamp(0, 127)]]
    end
  end
  out.sort_by { |tick, _| tick }
end

# Writes SMF with note events plus MIDI CC / pitch-bend automation.
def write_smf(path, note_events, program: PAD_GM_PROGRAM, bank: 0, duration: nil, midi_fx: nil, channel: 0,
              lead_mode: false)
  timed = []
  note_events.each do |parts|
    time, velocity, chord, sustain = parts[0], parts[1], parts[2], parts[3]
    next unless chord && chord[:hz]&.any?
    chord[:hz].each do |hz|
      note = hz_to_midi(hz).round.clamp(0, 127)
      on_tick = (time * SMF_TICKS_PER_SECOND).round
      off_tick = (on_tick + (sustain * SMF_TICKS_PER_SECOND)).round
      vel_mul = lead_mode ? 100 : 108
      vel_min = lead_mode ? 36 : 48
      vel = (velocity.clamp(0.0, 1.0) * vel_mul).round.clamp(vel_min, 127)
      timed << [on_tick, :on, note, vel]
      timed << [off_tick, :off, note, 0]
    end
  end
  midi_fx_automation(duration, midi_fx, channel:).each do |tick, bytes|
    timed << [tick, :cc, bytes]
  end
  timed.sort_by! { |tick, kind, *| [tick, kind == :off ? 0 : 1, kind == :cc ? 1 : 2] }

  track_events = [[0, [0xB0 | channel, 0x00, bank & 0x7f].pack("C*")],
                  [0, [0xC0 | channel, nonflute_program(program)].pack("C*")]]
  last_tick = 0
  timed.each do |entry|
    tick = entry[0]
    kind = entry[1]
    delta = [tick - last_tick, 0].max
    bytes = if kind == :cc
              entry[2].pack("C*")
            else
              status = kind == :on ? (0x90 | channel) : (0x80 | channel)
              [status, entry[2], entry[3]].pack("C*")
            end
    track_events << [delta, bytes]
    last_tick = tick
  end
  track_events << [0, [0xFF, 0x2F, 0x00].pack("C*")]

  track_data = track_events.map { |delta, bytes| midi_vlq(delta) + bytes }.join
  track_chunk = "MTrk" + [track_data.bytesize].pack("N") + track_data
  header = "MThd" + [6].pack("N") + [0, 1, SMF_PPQN].pack("n3")
  File.binwrite(path, header + track_chunk)
  path
end

# Per-chord bank/program changes — morph Rhodes / Prophet / Moog presets across a progression.
def write_smf_morph(path, pad_events, duration:, role:, midi_fx: nil, channel: 0, lead_mode: false)
  timed = []
  first_patch = nil
  pad_events.each_with_index do |parts, i|
    patch = morph_patch_for_chord(i, role:)
    next unless patch
    first_patch ||= patch
    voice = patch_voice_for(patch)
    time, velocity, chord, sustain = parts[0], parts[1], parts[2], parts[3]
    next unless chord && chord[:hz]&.any?
    on_tick = (time * SMF_TICKS_PER_SECOND).round
    off_tick = (on_tick + (sustain * SMF_TICKS_PER_SECOND)).round
    timed << [on_tick, :bank, voice[:bank]]
    timed << [on_tick, :prog, voice[:program]]
    chord[:hz].each do |hz|
      note = hz_to_midi(hz).round.clamp(0, 127)
      vel_mul = lead_mode ? 100 : 108
      vel_min = lead_mode ? 36 : 48
      vel = (velocity.clamp(0.0, 1.0) * vel_mul).round.clamp(vel_min, 127)
      timed << [on_tick, :on, note, vel]
      timed << [off_tick, :off, note, 0]
    end
  end
  if la_beat_progression_enabled? && pad_events.length >= 2
    pad_events.each_with_index do |parts, i|
      on_tick = (parts[0] * SMF_TICKS_PER_SECOND).round
      seg_dur = [parts[3], 0.5].max
      fx = LA_BEAT_MIDI_FX_ROTATE[i % LA_BEAT_MIDI_FX_ROTATE.length]
      midi_fx_automation(seg_dur, [fx], channel:).each do |tick, bytes|
        timed << [on_tick + tick, :cc, bytes]
      end
    end
  end
  midi_fx_automation(duration, midi_fx, channel:).each do |tick, bytes|
    timed << [tick, :cc, bytes]
  end
  kind_prio = { bank: 0, prog: 1, on: 2, cc: 3, off: 4 }
  timed.sort_by! { |tick, kind, *| [tick, kind_prio.fetch(kind, 5)] }

  track_events = []
  last_tick = 0
  timed.each do |entry|
    tick = entry[0]
    kind = entry[1]
    delta = [tick - last_tick, 0].max
    bytes = case kind
            when :bank
              [0xB0 | channel, 0x00, entry[2] & 0x7f].pack("C*")
            when :prog
              [0xC0 | channel, nonflute_program(entry[2])].pack("C*")
            when :cc
              entry[2].pack("C*")
            else
              status = kind == :on ? (0x90 | channel) : (0x80 | channel)
              [status, entry[2], entry[3]].pack("C*")
            end
    track_events << [delta, bytes]
    last_tick = tick
  end
  track_events << [0, [0xFF, 0x2F, 0x00].pack("C*")]

  track_data = track_events.map { |delta, bytes| midi_vlq(delta) + bytes }.join
  track_chunk = "MTrk" + [track_data.bytesize].pack("N") + track_data
  header = "MThd" + [6].pack("N") + [0, 1, SMF_PPQN].pack("n3")
  File.binwrite(path, header + track_chunk)
  [path, first_patch]
end

def write_smf_timed(path, timed, duration:, midi_fx: nil, channel: 0, lead_mode: false)
  midi_fx_automation(duration, midi_fx, channel:).each do |tick, bytes|
    timed << [tick, :cc, bytes]
  end
  kind_prio = { bank: 0, prog: 1, on: 2, cc: 3, off: 4 }
  timed.sort_by! { |tick, kind, *| [tick, kind_prio.fetch(kind, 5)] }

  track_events = []
  last_tick = 0
  timed.each do |entry|
    tick = entry[0]
    kind = entry[1]
    delta = [tick - last_tick, 0].max
    bytes = case kind
            when :bank
              [0xB0 | channel, 0x00, entry[2] & 0x7f].pack("C*")
            when :prog
              [0xC0 | channel, nonflute_program(entry[2])].pack("C*")
            when :cc
              entry[2].pack("C*")
            else
              status = kind == :on ? (0x90 | channel) : (0x80 | channel)
              vel_mul = lead_mode ? 100 : 108
              vel_min = lead_mode ? 36 : 48
              vel = kind == :on ? entry[3] : 0
              vel = (vel.is_a?(Float) ? (vel.clamp(0.0, 1.0) * vel_mul).round.clamp(vel_min, 127) : vel)
              [status, entry[2], vel].pack("C*")
            end
    track_events << [delta, bytes]
    last_tick = tick
  end
  track_events << [0, [0xFF, 0x2F, 0x00].pack("C*")]

  track_data = track_events.map { |delta, bytes| midi_vlq(delta) + bytes }.join
  track_chunk = "MTrk" + [track_data.bytesize].pack("N") + track_data
  header = "MThd" + [6].pack("N") + [0, 1, SMF_PPQN].pack("n3")
  File.binwrite(path, header + track_chunk)
  path
end

def render_xlead_native_fm(path, pad_events, duration, cfg)
  return unless lead_morph_enabled? && fm_native_enabled?
  return if pad_events.empty?

  filters = []
  labels = []
  note_i = 0
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  n_bars_est = ((pad_events.last[0] / bar_p).ceil + 1)
  pad_events.each_with_index do |(time, velocity, chord, sustain), i|
    patch = morph_lead_patch_for_chord(i)
    next unless chord && chord[:hz]&.any?
    arp_cfg = morph_lead_arp_cfg_for_chord(i, patch)
    chord_events = lead_arp_events_for_chord(time, velocity, chord, sustain, i, cfg, arp_cfg, patch,
                                             role: :xlead, n_bars_est:, skip_intro: false)
    next if chord_events.empty?
    ratio = fm_ratio_for_chord(i)
    mod_ratio_expr = fm_mod_ratio_expr(ratio[:m], ratio[:target_m], sustain, irrational: ratio[:irrational])
    chord_events.each do |(t, vel, ch, dur)|
      hz = ch[:hz].first
      next unless hz&.positive?
      base_idx = fm_index_from_velocity(vel, base_index: FM_INDEX_BASE_XLEAD, role: :xlead)
      mod_env = fm_mod_envelope(role: :xlead)
      index_expr = "(#{base_idx})*#{mod_env}"
      drift = "1"
      body = native_fm_waveform_body(hz, index_expr:, bloom: 0.22, drift:,
                                     feedback: FM_FEEDBACK_DEFAULT, phase_seed: note_i * 0.71,
                                     mod_ratio_expr:)
      amp = (vel * 0.12).round(5)
      atk = 0.003
      rel = (1.0 / [dur, 0.02].max).round(3)
      env = "min(1,pow(t/#{atk},0.9))*exp(-t*#{rel})"
      expr = "#{amp}*#{env}*#{body}"
      delay = [(t * 1000.0).round, 0].max
      label = "xl#{note_i}"
      filters << "aevalsrc=exprs='#{expr}|#{expr}':d=#{dur.round(4)}:s=#{PAD_RENDER_SAMPLE_RATE}," \
                 "adelay=#{delay}|#{delay}[#{label}]"
      labels << "[#{label}]"
      note_i += 1
    end
  end
  return if labels.empty?

  filters << "#{labels.join}amix=inputs=#{labels.length}:duration=longest:normalize=0," \
             "atrim=0:#{duration},highpass=f=180,lowpass=f=8200,alimiter=limit=0.94:level_out=0.92[xlead]"
  sh_filter_complex!(filters.join(";"), "-map", "[xlead]", "-ar", SAMPLE_RATE.to_s, "-c:a", "pcm_s16le", path)
  path
end

def blend_xlead_stems(destination, fs_path, native_path, duration)
  return fs_path if native_path.nil? || !File.exist?(native_path)
  return native_path if fs_path.nil? || !File.exist?(fs_path)
  tmp = "#{destination}.blend.wav"
  sh! "ffmpeg", "-y", "-i", fs_path, "-i", native_path,
      "-filter_complex",
      "[0:a][1:a]amix=inputs=2:weights=1.0 #{FM_XLEAD_NATIVE_MIX}:duration=longest:normalize=0," \
      "alimiter=limit=0.96:level_out=0.96[out]",
      "-map", "[out]", "-t", duration.to_s, "-c:a", "pcm_s16le", tmp
  FileUtils.mv(tmp, destination)
  destination
end

def render_xlead_morph_fluidsynth(path, pad_events, duration, cfg)
  return unless lead_morph_enabled? && fluidsynth_pad_available?
  return if pad_events.empty?

  timed = []
  first_patch = nil
  beat_p = 60.0 / cfg[:bpm]
  bar_p = beat_p * 4.0
  n_bars_est = ((pad_events.last[0] / bar_p).ceil + 1)
  pad_events.each_with_index do |(time, velocity, chord, sustain), i|
    patch = morph_lead_patch_for_chord(i)
    next unless patch && chord && chord[:hz]&.any?
    first_patch ||= patch
    voice = patch_voice_for(patch)
    arp_cfg = morph_lead_arp_cfg_for_chord(i, patch)
    chord_events = lead_arp_events_for_chord(time, velocity, chord, sustain, i, cfg, arp_cfg, patch,
                                             role: :xlead, n_bars_est:, skip_intro: false)
    next if chord_events.empty?
    on_tick = (time * SMF_TICKS_PER_SECOND).round
    timed << [on_tick, :bank, voice[:bank]]
    timed << [on_tick, :prog, voice[:program]]
    chord_events.each do |(t, vel, ch, dur)|
      note = hz_to_midi(ch[:hz].first).round.clamp(0, 127)
      note_on = (t * SMF_TICKS_PER_SECOND).round
      note_off = (note_on + (dur * SMF_TICKS_PER_SECOND)).round
      v = (vel.clamp(0.0, 1.0) * 100).round.clamp(40, 127)
      timed << [note_on, :on, note, v]
      timed << [note_off, :off, note, 0]
    end
  end
  return if timed.empty?

  midi_path = "#{path}.smf.mid"
  write_smf_timed(midi_path, timed, duration:, midi_fx: MIDI_FX_LEAD, lead_mode: true)
  fs_gain = first_patch&.fetch(:fs_gain, 1.38) || 1.38
  fluidsynth_render!(path, pad_soundfont_path, midi_path, gain: fs_gain)
  FileUtils.rm_f(midi_path)
  sh! "ffmpeg", "-y", "-i", path, "-af", lead_post_fx_chain(first_patch, duration, 0.0),
      "-c:a", "pcm_s16le", "#{path}.xlead.wav"
  FileUtils.mv("#{path}.xlead.wav", path)
  normalize_wav_to_rms!(path, LEAD_TARGET_RMS_DB)
  path
end

def write_pad_smf(path, pad_events, program: PAD_GM_PROGRAM, bank: 0, duration: nil, midi_fx: nil, patch: nil,
                    role: :ep)
  cfg = dilla_resolve_config
  events = pad_midi_events_for_layer(pad_events, cfg, patch, role:, duration: duration || 0)
  fx = midi_fx || resolve_midi_fx_for(patch, role:)
  write_smf(path, events, program:, bank:, duration:, midi_fx: fx)
end

# --------------------------------------------------------------------------
# engine part: pad_render
# --------------------------------------------------------------------------
#
# Rendering pads through fluidsynth.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# RMS the pad bus is normalised to. Was -17.5, which only balanced against the
# ~-38 dB drum bus because warm_dilla_pad_post immediately took ~19 dB back off
# via its aecho/chorus in_gain bug -- the two errors cancelled. With that fixed
# the level has to be honest here instead: pads land just under the kit, which
# is what "kit-forward" in DILLA_STYLE_DEFAULTS asks for.
PAD_TARGET_RMS_DB = (ENV["PAD_TARGET_RMS_DB"] || -39.0).to_f

# Lazily, silently fetches EXTERNAL_SOUNDFONTS/EXTERNAL_DRUM_KIT_REPO on
# first use so nothing needs to be typed/remembered — but any network
# hiccup (offline, GitHub down) must never break a render, hence the
# broad rescue (fetch_assets! can raise SystemExit via abort on a missing
# curl/git, not just StandardError).
def ensure_external_assets_lazy!
  return @external_assets_checked if defined?(@external_assets_checked)
  @external_assets_checked =
    begin
      sf_dir = File.expand_path("~/.cache/dilla-soundfonts")
      have_all = EXTERNAL_SOUNDFONTS.keys.all? { |n| File.exist?(File.join(sf_dir, n)) } &&
                 Dir.exist?(EXTERNAL_DRUM_KIT_CACHE)
      fetch_assets! unless have_all
      true
    rescue StandardError, SystemExit
      false
    end
end

def resolve_ep_voice
  if ENV["DILLA_PAD_PROGRAM"]
    return { sf2: pad_soundfont_path, bank: 0, program: PAD_GM_PROGRAM, patch: nil }
  end
  patch_voice_for(@render_ep_patch) || begin
    program = render_pick(EP_GM_PROGRAMS, "ep_program")
    { sf2: pad_soundfont_path, bank: 0, program:, patch: nil }
  end
end

# Lead voice from SYNTH_PATCH_CATALOG — supersaw, prophet, FM bell, etc.
def resolve_lead_voice
  if ENV["DILLA_LEAD_PROGRAM"]
    return { sf2: pad_soundfont_path, bank: 0, program: ENV["DILLA_LEAD_PROGRAM"].to_i, patch: @render_lead_patch }
  end
  patch_voice_for(@render_lead_patch) || { sf2: pad_soundfont_path, bank: 0, program: render_pick(LEAD_GM_PROGRAMS, "lead_program"), patch: nil }
end

def resolve_texture_voice
  patch_voice_for(@render_texture_patch)
end

# Rhodes alone (GM 4) is Dilla's half of the research (Rhodes/Wurlitzer);
# blending in a warm analog pad voice covers the other half — both artists'
# keyboards used real analog synths (Minimoog Voyager, Prophet 6/5, Yamaha
# CS-60) alongside the electric piano, not instead of it. A different pair
# picked per render rather than always the same two programs. The EP voice
# also has a 40% chance of pulling from the fetched Galaxy Electric Pianos
# soundfont instead of GeneralUser-GS's single Rhodes patch.
def render_pad_morph_fluidsynth(path, pad_events, duration)
  @render_used_fluidsynth_pad = true
  ep_path = "#{path}.ep.wav"
  warm_path = "#{path}.warm.wav"
  texture_path = "#{path}.texture.wav"
  ep_mix = 1.0
  warm_mix = 0.68
  # Use the actual patch SF2 (Galaxy EP / Supersaw Prophet), not always GeneralUser.
  ep_voice = patch_voice_for(prefer_galaxy_ep(@render_ep_patch || synth_patch_by_id(:rhodes_mark1))) ||
             { sf2: pad_soundfont_path, bank: 0, program: PAD_GM_PROGRAM, patch: nil }
  warm_voice = patch_voice_for(@render_warm_patch || synth_patch_by_id(:prophet_5_pad)) ||
               { sf2: pad_soundfont_path, bank: 0, program: 89, patch: nil }
  ep_midi = "#{ep_path}.smf.mid"
  _, ep_anchor = write_smf_morph(ep_midi, pad_events, duration:, role: :ep,
                                midi_fx: midi_fx_specs_for_role(:ep, ep_voice[:patch]))
  ep_mix = ep_anchor&.fetch(:mix, ep_voice[:patch]&.fetch(:mix, 1.2) || 1.2) || 1.2
  fluidsynth_render!(ep_path, ep_voice[:sf2], ep_midi,
                     gain: ep_anchor&.fetch(:fs_gain, ep_voice[:patch]&.fetch(:fs_gain, 1.7) || 1.7) || 1.7)
  FileUtils.rm_f(ep_midi)

  warm_midi = "#{warm_path}.smf.mid"
  _, warm_anchor = write_smf_morph(warm_midi, pad_events, duration:, role: :warm,
                                   midi_fx: midi_fx_specs_for_role(:warm, warm_voice[:patch]))
  warm_mix = warm_anchor&.fetch(:mix, warm_voice[:patch]&.fetch(:mix, 0.9) || 0.9) || 0.9
  fluidsynth_render!(warm_path, warm_voice[:sf2], warm_midi,
                     gain: warm_anchor&.fetch(:fs_gain, warm_voice[:patch]&.fetch(:fs_gain, 1.55) || 1.55) || 1.55)
  FileUtils.rm_f(warm_midi)

  texture_voice = resolve_texture_voice
  if texture_voice
    texture_midi = "#{texture_path}.smf.mid"
    write_pad_smf(texture_midi, pad_events, program: texture_voice[:program], bank: texture_voice[:bank],
                  duration:, patch: texture_voice[:patch], role: :texture)
    fluidsynth_render!(texture_path, texture_voice[:sf2], texture_midi,
                       gain: texture_voice[:patch]&.fetch(:fs_gain, 1.2) || 1.2)
    FileUtils.rm_f(texture_midi)
  end

  inputs = ["-i", ep_path, "-i", warm_path]
  filt = "[0:a]apad=whole_dur=#{duration}[ep];" \
         "[1:a]apad=whole_dur=#{duration}[warmsrc];" \
         "[warmsrc]asplit=2[w1][w2];" \
         "[w1]asetrate=44100*1.0022,aresample=44100[wup];" \
         "[w2]asetrate=44100*0.9978,aresample=44100[wdown];" \
         "[wup][wdown]amix=inputs=2:weights=0.52 0.52:duration=first:normalize=0[wdetuned];" \
         "[ep][wdetuned]amix=inputs=2:weights=#{ep_mix} #{warm_mix}:duration=first:normalize=0[blend]"
  map_label = "[blend]"
  if texture_voice && File.exist?(texture_path)
    filt += ";[2:a]apad=whole_dur=#{duration}[tex];[blend][tex]amix=inputs=2:weights=1.0 #{texture_voice[:patch]&.fetch(:mix, 0.15) || 0.15}:duration=first:normalize=0[blend2]"
    map_label = "[blend2]"
    inputs << "-i" << texture_path
  end
  sh! "ffmpeg", "-y", *inputs, "-filter_complex", filt, "-map", map_label, "-c:a", "pcm_s16le", path
  FileUtils.rm_f(ep_path)
  FileUtils.rm_f(warm_path)
  FileUtils.rm_f(texture_path)
  measured_rms = band_rms(path, highpass: 20, lowpass: 20_000)
  boost_db = (PAD_TARGET_RMS_DB - measured_rms).clamp(-24.0, 18.0)
  sh! "ffmpeg", "-y", "-i", path, "-af",
      "equalizer=f=280:t=o:w=1:g=1.2,equalizer=f=1800:t=h:w=1200:g=0.7," \
      "volume=#{boost_db.round(2)}dB,alimiter=limit=0.95:level_out=0.96",
      "-c:a", "pcm_s16le", "#{path}.pad.wav"
  FileUtils.mv("#{path}.pad.wav", path)
  path
end

def pad_layer_specs_for_voice(voice)
  stack = PAD_LAYER_STACKS[voice]
  return stack if stack && ENV.fetch("PAD_LAYERS", "1") != "0"
  preset = PAD_VOICE_PRESETS[voice] || PAD_VOICE_PRESETS[:stack_soul]
  layers = []
  layers << { id: preset[:ep], mix: 1.15, role: :ep } if preset[:ep]
  layers << { id: preset[:warm], mix: 0.85, role: :warm } if preset[:warm]
  layers << { id: preset[:warm2], mix: 0.55, role: :warm } if preset[:warm2]
  layers << { id: preset[:texture], mix: 0.3, role: :texture } if preset[:texture]
  layers
end

def render_one_pad_layer!(voice_path, pad_events, duration, voice, role)
  if voice[:patch]&.dig(:native) && native_fm_layers_enabled?
    return render_native_pad_layer!(voice_path, pad_events, duration, voice[:patch])
  end
  midi_path = "#{voice_path}.smf.mid"
  write_pad_smf(midi_path, pad_events, program: voice[:program], bank: voice[:bank],
                duration:, patch: voice[:patch], role:)
  fs_gain = voice[:patch]&.fetch(:fs_gain, 1.5) || 1.5
  fluidsynth_render!(voice_path, voice[:sf2], midi_path, gain: fs_gain)
  FileUtils.rm_f(midi_path)
  return unless voice[:patch]&.dig(:fx) && tool_available?("ffmpeg")
  fx_tmp = "#{voice_path}.fx.wav"
  begin
    sh! "ffmpeg", "-y", "-i", voice_path, "-af", voice[:patch][:fx], "-c:a", "pcm_s16le", fx_tmp
    FileUtils.mv(fx_tmp, voice_path)
  rescue StandardError => e
    warn "patch fx skipped (#{voice[:patch][:id]}): #{e.message}"
    FileUtils.rm_f(fx_tmp)
  end
end

def render_pad_via_fluidsynth(path, pad_events, duration)
  # Morph path is opt-in only — multi-layer stack is the quality default.
  return render_pad_morph_fluidsynth(path, pad_events, duration) if synth_morph_enabled? && ENV["PAD_LAYERS"] == "0"
  @render_used_fluidsynth_pad = true
  voice_key = ENV["PAD_VOICE"]&.downcase&.to_sym
  specs = pad_layer_specs_for_voice(voice_key)
  if specs.nil? || specs.empty?
    # Fallback: Rhodes front, Prophet bed (not Moog-heavy).
    specs = [
      { id: :rhodes_mark1, mix: 1.4, role: :ep },
      { id: :prophet_5_pad, mix: 1.0, role: :warm },
      { id: :prophet_6_warm, mix: 0.65, role: :warm },
    ]
  end
  # Always force at least EP + two warm beds when stack requested.
  if ENV.fetch("PAD_LAYERS", "1") != "0" && specs.length < 3
    specs = PAD_LAYER_STACKS[:stack_soul]
  end

  rendered = []
  specs.each_with_index do |spec, i|
    patch = synth_patch_by_id(spec[:id])
    next unless patch
    # EP layers: Galaxy bank when available. Warm layers keep their own sf2
    # (Prophet → supersaw, Moog → default GM, …).
    patch = prefer_galaxy_ep(patch) if (spec[:role] || :warm) == :ep
    voice = patch_voice_for(patch) || resolve_ep_voice
    voice = voice.merge(patch:) if voice[:patch].nil?
    layer_path = "#{path}.L#{i}.wav"
    render_one_pad_layer!(layer_path, pad_events, duration, voice, spec[:role] || :warm)
    next unless File.file?(layer_path)
    # Unison detune on warm layers only (width without mush).
    if spec[:role] == :warm && i.positive?
      det = "#{layer_path}.det.wav"
      sh! "ffmpeg", "-y", "-i", layer_path, "-filter_complex",
          "[0:a]asplit=2[a][b];[a]asetrate=#{SAMPLE_RATE}*1.0018,aresample=#{SAMPLE_RATE}[u];" \
          "[b]asetrate=#{SAMPLE_RATE}*0.9982,aresample=#{SAMPLE_RATE}[d];" \
          "[u][d]amix=inputs=2:weights=0.5 0.5:normalize=0",
          "-c:a", "pcm_s16le", det
      FileUtils.mv(det, layer_path) if File.file?(det)
    end
    rendered << [layer_path, spec[:mix].to_f]
  end
  if rendered.empty?
    return render_native_pad_wav(path, pad_events, duration)
  end
  if rendered.length == 1
    FileUtils.mv(rendered[0][0], path)
  else
    inputs = rendered.flat_map { |(p, _)| ["-i", p] }
    labels = rendered.each_index.map { |i| "p#{i}" }
    filt_parts = rendered.each_with_index.map do |(_, mix), i|
      "[#{i}:a]apad=whole_dur=#{duration},volume=#{mix}[#{labels[i]}]"
    end
    weights = rendered.map { |(_, m)| m }.join(" ")
    filt = "#{filt_parts.join(';')};" \
           "#{labels.map { |l| "[#{l}]" }.join}amix=inputs=#{rendered.length}:weights=#{weights}:" \
           "duration=first:normalize=0[blend]"
    sh! "ffmpeg", "-y", *inputs, "-filter_complex", filt, "-map", "[blend]", "-c:a", "pcm_s16le", path
    rendered.each { |(p, _)| FileUtils.rm_f(p) } # scan: intentional — removes only the temp files this method rendered
  end
  measured_rms = band_rms(path, highpass: 20, lowpass: 20_000)
  boost_db = (PAD_TARGET_RMS_DB - measured_rms).clamp(-24.0, 20.0)
  sh! "ffmpeg", "-y", "-i", path, "-af",
      "equalizer=f=280:t=o:w=1:g=1.6,equalizer=f=900:t=o:w=1.2:g=0.8," \
      "equalizer=f=2200:t=h:w=1400:g=1.0,volume=#{boost_db.round(2)}dB," \
      "alimiter=limit=0.95:level_out=0.97",
      "-c:a", "pcm_s16le", "#{path}.pad.wav"
  FileUtils.mv("#{path}.pad.wav", path)
  path
end

# --------------------------------------------------------------------------
# engine part: pad_layers
# --------------------------------------------------------------------------
#
# Extra pad layers: chopped singers, stretched melody, tunnel, choir, granular cloud.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- Singers Unlimited chop pads -------------------------------------------
# The pad bed built from CHOPS of a real Singers Unlimited vocal stem instead
# of synth pads (classic Dilla move: chop the vocal-harmony record). Per pad
# event, a phrase chop is repitched via asetrate (true tape/chipmunk repitch,
# artifacts intended) to the chord root plus up to two upper chord tones, so
# the chop harmonizes itself to the progression regardless of the source key.
# Default OFF (SINGERS_CHOP_PADS=1 enables). When this succeeds it replaces the
# synth pad stack *entirely* -- so with it on by default the real pads (the
# fluidsynth stack, the patch catalog, PAD_VOICE, every voice-leading decision)
# never reached the mix at all; the chords you heard were repitched vocal chops.
# It is an effect, not the pad engine, so it has to be opted into. Enable with
# SINGERS_CHOP_PADS=1, which needs a stem:
#   ruby dilla.rb rap-vocal ingest singers_unlimited <youtube-url-or-path>
def singers_chop_pads_enabled?
  ENV.fetch("SINGERS_CHOP_PADS", "0") != "0"
end

def singers_chop_source
  entry = Array(rap_vocal_load_catalog["vocals"]).find { |v| v["slug"] == "singers_unlimited" }
  path = entry && entry["vocal_path"].to_s
  path = File.join(RAP_VOCAL_DIR, "singers_unlimited", "vocals.wav") if path.nil? || path.empty?
  return unless File.file?(path)

  { path:, phrases: Array(entry&.dig("phrases")).map { |p| p["start"].to_f }.select(&:positive?) }
end

def render_singers_chop_pads(path, pad_events, duration)
  src = singers_chop_source
  return unless src

  src_dur = audio_duration_sec(src[:path])
  return if src_dur < 8.0

  rng = Random.new((@render_seed || 4242) + 555)
  starts = src[:phrases].select { |s| s < src_dur - 6.0 }
  starts = Array.new(12) { rng.rand * (src_dur - 6.0) } if starts.empty?
  first_root = nil
  chains = []
  labels = []
  pad_events.each_with_index do |(t, v, chord, sustain), i|
    next unless chord.is_a?(Hash) && chord[:hz].is_a?(Array) && chord[:hz].any?

    hz = chord[:hz].map(&:to_f).select(&:positive?).sort
    next if hz.empty?

    root = hz.first
    first_root ||= root
    # Root motion relative to the first chord, octave-folded so the repitch
    # never leaves believable tape range.
    base = root / first_root
    base /= 2.0 while base > 1.6
    base *= 2.0 while base < 0.7
    chop_at = starts[(i * 7 + rng.rand(3)) % starts.length]
    # Root voice + up to two upper chord tones (ratio to root, folded ≤ 2x).
    voices = [1.0] + hz.drop(1).take(3).map do |h|
      r = h / root
      r /= 2.0 while r > 2.05
      r
    end
    voices.take(3).each_with_index do |ratio, vi|
      r = (base * ratio).clamp(0.5, 2.1)
      need = sustain.to_f * r + 0.4
      s0 = chop_at.clamp(0.0, [src_dur - need - 0.1, 0.0].max)
      fade_out_at = [sustain.to_f - 0.3, 0.05].max
      gain = (v.to_f * (vi.zero? ? 0.95 : 0.5)).round(3)
      delay_ms = [(t * 1000.0).round, 0].max
      lbl = "sc#{i}v#{vi}"
      chains << "[0:a]atrim=start=#{s0.round(3)}:end=#{(s0 + need).round(3)},asetpts=PTS-STARTPTS," \
                "aformat=channel_layouts=stereo,asetrate=#{SAMPLE_RATE}*#{r.round(4)},aresample=#{SAMPLE_RATE}," \
                "afade=t=in:st=0:d=0.08,afade=t=out:st=#{fade_out_at.round(3)}:d=0.3," \
                "atrim=0:#{sustain.round(3)},volume=#{gain},adelay=#{delay_ms}|#{delay_ms}[#{lbl}]"
      labels << "[#{lbl}]"
    end
  end
  return if labels.empty?

  filt = "#{chains.join(';')};#{labels.join}" \
         "amix=inputs=#{labels.length}:duration=longest:normalize=0," \
         "atrim=0:#{duration},highpass=f=#{pad_highpass_hz},alimiter=limit=0.95:level_out=0.96[pads]"
  prev_soft = ENV["DILLA_SOFT_SH"]
  ENV["DILLA_SOFT_SH"] = "1"
  begin
    sh! "ffmpeg", "-y", "-i", src[:path], "-filter_complex", filt,
        "-map", "[pads]", "-c:a", "pcm_s16le", path
  rescue StandardError => e
    warn "singers chop pads failed (#{e.message}) — falling back to synth pads"
    FileUtils.rm_f(path)
    return
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
  end
  return unless File.file?(path)

  measured_rms = band_rms(path, highpass: 20, lowpass: 20_000)
  boost_db = (PAD_TARGET_RMS_DB - measured_rms).clamp(-24.0, 24.0)
  sh! "ffmpeg", "-y", "-i", path, "-af",
      "equalizer=f=320:t=o:w=1:g=1.2,volume=#{boost_db.round(2)}dB," \
      "alimiter=limit=0.95:level_out=0.96",
      "-c:a", "pcm_s16le", "#{path}.sc.wav"
  FileUtils.mv("#{path}.sc.wav", path)
  dmesg("singers unlimited chop bed (#{labels.length} voices)", unit: "harm0", parent: "dilla0")
  path
end

# The Singers Unlimited harmony as the track's melodic voice, resynthesized
# rather than played back.
#
# render_singers_chop_pads above is varispeed tape: atrim a phrase, asetrate it
# to the chord, done. That keeps the vocal sounding like a vocal, which is why
# it reads as a bed. This path spectrally resynthesizes instead — magnitudes
# kept, phase discarded — so the ensemble stops being four people singing and
# becomes a sustained harmonic instrument that still carries their voicing.
# That is the whole point: the melody is not played BY a synth, the choir IS
# the synth.
#
# Phase randomization is the Paulstretch core (huge windows, random phase,
# heavy overlap-add). ffmpeg has no paulstretch filter and no rubberband here,
# so afftfilt supplies the phase discard and atempo=0.5 supplies the exact 2x
# stretch that holds pitch. Measured on the real sample: band energy at 200/400/
# 900/2500 Hz tracks the dry signal within 0.3 dB of a uniform 6 dB drop, so the
# voicing survives intact and only the level moves — hence the fixed +6 dB.
SU_MELODY_VARIANTS = 4
SU_MELODY_WIN = 8192
# How much untouched signal sits under the resynthesis. Enough to return the
# attacks; past roughly 0.5 the source stops sounding like an instrument and
# starts sounding like a vocal sample again, which is the thing this is not.
SU_MELODY_DRY_BLEND = (ENV["SU_MELODY_DRY"] || 0.34).to_f.clamp(0.0, 1.0)

def su_melody_enabled?
  ENV.fetch("SU_MELODY", "0") != "0"
end

def no_lead?
  ENV.fetch("NO_LEAD", "0") != "0"
end

def grand_pads? = ENV.fetch("GRAND", "0") != "0"

# Grandeur by orchestration rather than by EQ.
#
# With no lead the pads are the whole record, and a four-voice stack in one
# octave is a small sound however it is filtered. Weight and scale in an organ
# registration or a string section come from the same notes doubled at the
# octave -- a 16-foot stop under the 8-foot, basses under the celli. Boosting
# low end instead only makes the same narrow voicing heavier, which is muddier,
# not bigger.
#
# The octave below carries the root and fifth only. Doubling a ninth or a
# thirteenth down there turns an extension into a low interval that beats
# against the root, which is why the low copy is filtered rather than complete.
# The octave above takes the upper voices, where it reads as air.
GRAND_LOW_GAIN = 0.55
GRAND_HIGH_GAIN = 0.38

def grandeur_pad_events(pad_events)
  pad_events.flat_map do |event|
    t, v, chord, sustain = event
    next [event] unless chord.is_a?(Hash) && chord[:hz].is_a?(Array)

    hz = chord[:hz].map(&:to_f).select(&:positive?).sort
    next [event] if hz.length < 2

    root = hz.first
    # Root and fifth only: within 60 cents of a 3:2, octave-folded.
    low = hz.select do |h|
      ratio = h / root
      ratio /= 2.0 while ratio > 2.0
      (ratio - 1.0).abs < 0.03 || (ratio - 1.5).abs < 0.05
    end
    out = [event]
    if low.any?
      out << [t, v * GRAND_LOW_GAIN, chord.merge(hz: low.map { |h| h / 2.0 },
                                                 name: "#{chord[:name]}_8vb"), sustain]
    end
    upper = hz.drop(1)
    if upper.any?
      out << [t, v * GRAND_HIGH_GAIN, chord.merge(hz: upper.map { |h| h * 2.0 },
                                                  name: "#{chord[:name]}_8va"), sustain]
    end
    out
  end
end

# One afftfilt pass per variant instead of one per note. Per-note stretching
# measured 9.4s for 24 voices, which extrapolates to ~61s on a three-minute
# track and scales with length; this is a fixed four passes regardless.
def su_melody_stretched_sources(src, src_dur, tmp_dir, rng)
  SU_MELODY_VARIANTS.times.filter_map do |i|
    grab = 9.0
    at = 6.0 + rng.rand * [src_dur - grab - 8.0, 1.0].max
    out = File.join(tmp_dir, "su_stretch#{i}.wav")
    begin
      # Part resynthesised, part not.
      #
      # Discarding all phase gives a perfectly smooth drone and no instrument:
      # every transient in the source is gone, so nothing has an attack and the
      # result is a wash that sits behind the track rather than a voice that
      # plays it. That is the "synth patch" complaint. Blending the untouched
      # signal back under the phase-randomised one returns the consonant edges
      # and the breath while keeping the sustain the stretch created -- the
      # spectral part supplies the tone, the dry part supplies the articulation.
      sh! "ffmpeg", "-y", "-v", "error", "-ss", at.round(3).to_s, "-t", grab.to_s, "-i", src,
          "-filter_complex",
          "[0:a]aformat=channel_layouts=stereo,atempo=0.5,asplit=2[sd][sw];" \
          "[sw]afftfilt=real='hypot(re,im)*cos(random(#{i + 1})*2*PI)':" \
          "imag='hypot(re,im)*sin(random(#{i + 1})*2*PI)':" \
          "win_size=#{SU_MELODY_WIN}:overlap=0.94,volume=6dB[swet];" \
          "[sd]highpass=f=180,volume=-3dB[sdry];" \
          "[swet][sdry]amix=inputs=2:weights=1 #{SU_MELODY_DRY_BLEND}:duration=first:normalize=0[out]",
          "-map", "[out]", "-c:a", "pcm_s16le", out
    rescue StandardError => e
      warn "su melody variant #{i} skipped: #{e.message}"
      next
    end
    File.file?(out) && File.size(out) > 4096 ? out : nil
  end
end

# Resonant low-mid, absorbed highs, irregular short taps. A tunnel is a
# resonance and an absorption, not a reverb preset — the short taps are the
# flutter between close walls, the long pair is the far end. Applied to the
# summed voices so they share one space rather than each sitting in its own.
# Operator note 2026-08-13: the tunnel read as too loud in the techno set. Two
# gains came down and nothing else moved — the tap structure above is the
# character and cutting it would have made a different effect rather than a
# quieter one.
#
#   520 Hz resonance  +6 dB -> +2 dB   the low-mid honk, the loudest single thing
#                                      in the chain and what "too loud" hears
#   stereotools slev  1.35 -> 1.15     sides came back toward centre; a widened
#                                      tunnel reads louder than it measures
SU_TUNNEL_CHAIN = "highpass=f=90," \
                  "equalizer=f=520:t=q:w=1.4:g=2," \
                  "equalizer=f=1900:t=q:w=2.0:g=-4," \
                  "lowpass=f=3400," \
                  "aecho=0.82:0.85:37|59|83|127:0.5|0.38|0.28|0.18," \
                  "aecho=0.9:0.8:311|487:0.22|0.14," \
                  "stereotools=mlev=0.9:slev=1.15"

# The refined tunnel: a convolved impulse response instead of six discrete taps.
#
# The chain above is four short echoes at 37/59/83/127 ms and a far pair. Taps
# that short are a comb filter, not a room -- each one puts a fixed notch in the
# spectrum, and four of them on a sustained choir is a metallic ring sitting on
# every held note. That is what reads as unrefined, and no amount of tuning the
# gains fixes it, because the artefact is the discreteness itself.
#
# A real tunnel tail is dense: thousands of reflections, too close together to
# hear individually, getting darker as they decay because air and concrete
# absorb treble faster than bass. That is an impulse response, so this generates
# one -- exponentially decaying noise, low-passed progressively over its length,
# with the early part shaped to keep the close-wall character the taps were
# there for -- and convolves it with afir.
SU_TUNNEL_IR_SEC = 1.9
SU_TUNNEL_IR_RATE = 44_100

def su_tunnel_ir_path(dir)
  path = File.join(dir, "su_tunnel_ir.wav")
  return path if File.file?(path) && File.size(path) > 4096

  frames = (SU_TUNNEL_IR_SEC * SU_TUNNEL_IR_RATE).to_i
  rng = Random.new(90_210)
  # Two decorrelated channels, or the tail collapses to the middle and the
  # tunnel has no width at all.
  samples = Array.new(2) { Array.new(frames, 0.0) }
  2.times do |ch|
    lp = 0.0
    frames.times do |i|
      t = i.to_f / SU_TUNNEL_IR_RATE
      # Exponential decay, plus a short pre-delay so the direct sound is not
      # smeared into its own reflections.
      env = t < 0.006 ? 0.0 : Math.exp(-4.2 * t)
      # Progressive damping: the coefficient falls as the tail ages, so late
      # reflections are darker than early ones the way absorption makes them.
      a = 0.55 - (0.35 * (t / SU_TUNNEL_IR_SEC))
      lp += a * ((rng.rand * 2.0 - 1.0) - lp)
      samples[ch][i] = lp * env
    end
    peak = samples[ch].max_by(&:abs).abs
    samples[ch].map! { |v| v / peak * 0.7 } if peak.positive?
  end

  File.open(path, "wb") do |f|
    data_bytes = frames * 2 * 2
    f.write("RIFF"); f.write([36 + data_bytes].pack("V")); f.write("WAVEfmt ")
    f.write([16, 1, 2, SU_TUNNEL_IR_RATE, SU_TUNNEL_IR_RATE * 4, 4, 16].pack("VvvVVvv"))
    f.write("data"); f.write([data_bytes].pack("V"))
    frames.times do |i|
      f.write([(samples[0][i] * 32_767).round.clamp(-32_768, 32_767),
               (samples[1][i] * 32_767).round.clamp(-32_768, 32_767)].pack("s<s<"))
    end
  end
  path
end

def su_tunnel_refined? = ENV.fetch("SU_TUNNEL_REFINED", "1") != "0"

SU_MELODY_TARGET_RMS_DB = -17.0

def render_su_tunnel_melody(path, pad_events, duration, cfg: nil, n_bars: nil)
  src = singers_chop_source
  return unless src

  src_dur = audio_duration_sec(src[:path])
  return if src_dur < 20.0

  rng = Random.new((@render_seed || 4242) + 909)
  tmp_dir = File.dirname(path)
  sources = su_melody_stretched_sources(src[:path], src_dur, tmp_dir, rng)
  return if sources.empty?

  # The tune, from the engine's own line writer rather than this renderer's
  # arpeggiator. Rendered by the choir instead of a soundfont, so the melody is
  # written by the part of the engine that knows how to write one and voiced by
  # the part that sounds good.
  tune = if cfg
           begin
             lead_events_melodic(pad_events, cfg, duration: duration, n_bars: n_bars)
           rescue StandardError => e
             warn "su melody line fell back to held chords: #{e.message}"
             []
           end
         else
           []
         end

  stretched_dur = sources.map { |s| audio_duration_sec(s) }
  first_root = nil
  chains = []
  labels = []
  idx = 0

  pad_events.each_with_index do |(t, v, chord, sustain), ci|
    next unless chord.is_a?(Hash) && chord[:hz].is_a?(Array) && chord[:hz].any?

    hz = chord[:hz].map(&:to_f).select(&:positive?).sort
    next if hz.empty?

    root = hz.first
    first_root ||= root
    sus = sustain.to_f
    next if sus <= 0.05

    # The held pair only. The top line is not built here by stepping through
    # top_tones[(ci + s) % length] -- a cycle through the chord's own notes,
    # indexed by which chord it was. That is an arpeggiator, not a melody: no
    # contour, no phrase, no motif, the same shape over every chord, and it
    # never rests. It is why the lead was unlistenable.
    #
    # The tune now comes from lead_events_melodic, which the engine already had:
    # a motif stated then inverted and reversed across phrases, notes chosen by
    # lead_note_score against parallel fifths and oversized leaps, whole phrases
    # left silent by lead_phrase_rests?, contrary motion to the pad top. All of
    # that existed and this renderer walked past it to roll its own.
    held = hz.take(2)
    voices = held.map { |h| [h, 0.0, sus, h == root ? 0.9 : 0.5] }

    voices.each do |(target, offset, length, gain)|
      r = target / first_root
      r /= 2.0 while r > 1.9
      r *= 2.0 while r < 0.85
      si = (ci + idx) % sources.length
      need = length * r + 0.4
      avail = [stretched_dur[si] - need - 0.1, 0.0].max
      next if avail <= 0.0

      s0 = (rng.rand * avail).round(3)
      delay_ms = [((t + offset) * 1000.0).round, 0]
      delay_ms = delay_ms.max
      fade_in = [length * 0.3, 0.9].min
      fade_at = [length - fade_in, 0.05].max
      lbl = "sm#{idx}"
      idx += 1

      chains << "[#{si}:a]atrim=start=#{s0}:end=#{(s0 + need).round(3)},asetpts=PTS-STARTPTS," \
                "aformat=channel_layouts=stereo," \
                "asetrate=#{SAMPLE_RATE}*#{r.round(5)},aresample=#{SAMPLE_RATE}," \
                "atrim=0:#{length.round(3)}," \
                "afade=t=in:st=0:d=#{fade_in.round(3)}," \
                "afade=t=out:st=#{fade_at.round(3)}:d=#{fade_in.round(3)}," \
                "volume=#{(v.to_f * gain).round(3)}," \
                "adelay=#{delay_ms}|#{delay_ms}[#{lbl}]"
      labels << "[#{lbl}]"
    end
  end

  # The melody itself, one choir voice per written note, louder than the held
  # pair so it reads as the line and they read as the ground under it.
  tune.each_with_index do |(t, v, note, sustain), ni|
    nhz = note.is_a?(Hash) ? Array(note[:hz]).map(&:to_f).select(&:positive?) : []
    target = nhz.first
    next unless target

    length = sustain.to_f
    next if length <= 0.05

    first_root ||= target
    r = target / first_root
    r /= 2.0 while r > 1.9
    r *= 2.0 while r < 0.85
    si = (ni + 1) % sources.length
    need = length * r + 0.4
    avail = [stretched_dur[si] - need - 0.1, 0.0].max
    next if avail <= 0.0

    s0 = (rng.rand * avail).round(3)
    delay_ms = [(t.to_f * 1000.0).round, 0].max
    # A shorter attack than the bed. The bed swells over 0.3 of its length,
    # which is right for something held and wrong for a sung note -- it is what
    # made every entry vague instead of articulate.
    fade_in = [length * 0.12, 0.22].min
    fade_out = (length * 0.3).round(3)
    fade_at = [length - fade_out, 0.05].max
    lbl = "sl#{ni}"

    chains << "[#{si}:a]atrim=start=#{s0}:end=#{(s0 + need).round(3)},asetpts=PTS-STARTPTS," \
              "aformat=channel_layouts=stereo," \
              "asetrate=#{SAMPLE_RATE}*#{r.round(5)},aresample=#{SAMPLE_RATE}," \
              "atrim=0:#{length.round(3)}," \
              "afade=t=in:st=0:d=#{fade_in.round(3)}," \
              "afade=t=out:st=#{fade_at.round(3)}:d=#{fade_out}," \
              "volume=#{(v.to_f * 1.15).round(3)}," \
              "adelay=#{delay_ms}|#{delay_ms}[#{lbl}]"
    labels << "[#{lbl}]"
  end
  dmesg("su melody line: #{tune.length} written notes over #{pad_events.length} chords",
        unit: "harm0", parent: "dilla0")
  return if labels.empty?

  ir = su_tunnel_refined? ? su_tunnel_ir_path(tmp_dir) : nil
  if ir
    # Convolution replaces the tap chain; the tone shaping stays, since the IR
    # supplies the room and not the resonance.
    space = "highpass=f=90,equalizer=f=520:t=q:w=1.4:g=5," \
            "equalizer=f=1900:t=q:w=2.0:g=-3.5,lowpass=f=3600"
    wet = "[mixed]#{space}[dry_t];" \
          "[dry_t]asplit=2[t_dry][t_wet];" \
          "[t_wet][#{sources.length}:a]afir=dry=0:wet=1:gtype=peak:maxir=#{SU_TUNNEL_IR_SEC}[t_verb];" \
          "[t_dry][t_verb]amix=inputs=2:weights=1 0.85:duration=first:normalize=0," \
          "stereotools=mlev=0.9:slev=1.3"
    filt = "#{chains.join(';')};#{labels.join}" \
           "amix=inputs=#{labels.length}:duration=longest:normalize=0[mixed];" \
           "#{wet},atrim=0:#{duration},alimiter=limit=0.95:level_out=0.94[su]"
  else
    filt = "#{chains.join(';')};#{labels.join}" \
           "amix=inputs=#{labels.length}:duration=longest:normalize=0," \
           "#{SU_TUNNEL_CHAIN},atrim=0:#{duration}," \
           "alimiter=limit=0.95:level_out=0.94[su]"
  end
  inputs = sources.flat_map { |s| ["-i", s] }
  inputs += ["-i", ir] if ir
  prev_soft = ENV["DILLA_SOFT_SH"]
  ENV["DILLA_SOFT_SH"] = "1"
  begin
    sh! "ffmpeg", "-y", "-v", "error", *inputs, "-filter_complex", filt,
        "-map", "[su]", "-c:a", "pcm_s16le", path
  rescue StandardError => e
    warn "su tunnel melody failed (#{e.message})"
    FileUtils.rm_f(path)
    return
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
    sources.each { |s| FileUtils.rm_f(s) } # scan: intentional — removes only the temp files this method rendered
  end
  return unless File.file?(path)

  normalize_wav_to_rms!(path, SU_MELODY_TARGET_RMS_DB)
  dmesg("su tunnel melody (#{labels.length} voices, #{sources.length} stretched sources)",
        unit: "harm0", parent: "dilla0")
  path
end

# Soft choir pad on chord tones (Singers Unlimited–like ooh/aah). Default on
# via CHOIR_VOX=1; set CHOIR_VOX=0 to disable. Gain via CHOIR_VOX_GAIN (0–1).
def choir_vox_enabled?
  # Default off, matching DILLA_STYLE_DEFAULTS. This gate is the one that
  # decides, and it defaulted on — so any path that does not apply the style
  # table still got a choir.
  ENV.fetch("CHOIR_VOX", "0") != "0" && fluidsynth_pad_available?
end

# Thin full pad voicings to 2–3 mid/upper chord tones so choir reads as
# airy harmony, not a second dense pad stack.
def choir_chord_tone_events(pad_events)
  pad_events.filter_map do |(t, v, chord, sustain)|
    next unless chord.is_a?(Hash) && chord[:hz].is_a?(Array) && chord[:hz].any?

    sorted = chord[:hz].map(&:to_f).select(&:positive?).sort
    next if sorted.empty?

    # Prefer 3rd + 5th + 7th/9th when available; drop the bass note if dense.
    tones =
      if sorted.length >= 4
        [sorted[1], sorted[2], sorted[-1]]
      elsif sorted.length == 3
        sorted
      else
        sorted
      end
    # Lift into choir register (~C4–C5) without changing pitch class.
    lifted = tones.map do |hz|
      h = hz
      h *= 2 while h < 220.0
      h /= 2 while h > 880.0
      h
    end.uniq
    next if lifted.empty?

    soft_v = (v.to_f * 0.72).clamp(0.15, 0.85)
    [t, soft_v, chord.merge(hz: lifted, name: "#{chord[:name]}·choir"), sustain]
  end
end

def render_choir_vox_layer(path, pad_events, duration)
  events = choir_chord_tone_events(pad_events)
  return if events.empty?

  seed = (@render_seed || 0).to_i
  patch_id = (seed + events.length).even? ? :choir_aahs : :voice_oohs
  patch = synth_patch_by_id(patch_id) || synth_patch_by_id(:choir_aahs)
  return unless patch

  voice = patch_voice_for(patch) || { sf2: pad_soundfont_path, bank: 0, program: 52, patch: }
  voice = voice.merge(patch:) if voice[:patch].nil?
  # Soft: never abort the whole track for choir failures.
  prev_soft = ENV["DILLA_SOFT_SH"]
  ENV["DILLA_SOFT_SH"] = "1"
  begin
    render_one_pad_layer!(path, events, duration, voice, :warm)
  rescue StandardError => e
    warn "choir_vox layer skipped: #{e.message}"
    FileUtils.rm_f(path)
    return
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
  end
  return unless File.file?(path)

  soft = "#{path}.soft.wav"
  gain = (ENV["CHOIR_VOX_GAIN"] || "0.28").to_f.clamp(0.05, 0.65)
  begin
    ENV["DILLA_SOFT_SH"] = "1"
    sh! "ffmpeg", "-y", "-i", path, "-af",
        "afade=t=in:st=0:d=0.9,highpass=f=200,lowpass=f=4200," \
        "aecho=0.55:0.6:120|220:0.28|0.14,volume=#{gain.round(3)}," \
        "alimiter=limit=0.72:level_out=0.78",
        "-c:a", "pcm_s16le", soft
    FileUtils.mv(soft, path) if File.file?(soft)
  rescue StandardError => e
    warn "choir_vox soft pass skipped: #{e.message}"
    FileUtils.rm_f(soft)
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
  end
  File.file?(path) ? path : nil
end

def mix_choir_into_pads!(pads_path, choir_path, duration)
  return unless pads_path && choir_path && File.file?(pads_path) && File.file?(choir_path)

  out = "#{pads_path}.choir_mix.wav"
  prev_soft = ENV["DILLA_SOFT_SH"]
  ENV["DILLA_SOFT_SH"] = "1"
  begin
    sh! "ffmpeg", "-y", "-i", pads_path, "-i", choir_path,
        "-filter_complex",
        "[0:a]apad=whole_dur=#{duration}[p];[1:a]apad=whole_dur=#{duration}[c];" \
        "[p][c]amix=inputs=2:weights=1.0 0.55:duration=first:normalize=0," \
        "alimiter=limit=0.96:level_out=0.97[out]",
        "-map", "[out]", "-t", duration.to_s, "-c:a", "pcm_s16le", out
    FileUtils.mv(out, pads_path) if File.file?(out)
  rescue StandardError => e
    warn "choir_vox mix skipped: #{e.message}"
    FileUtils.rm_f(out)
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
    FileUtils.rm_f(choir_path)
  end
end

# --- Granular pad texture (Clouds/Beads-style micro-grain resynthesis) ------
# The rendered pad bed is re-read as mono and rebuilt from 60–200 ms
# hann-windowed grains — position spray trailing the playhead, occasional
# +1-octave shimmer and sub-octave haze grains, some reversed — then floated
# back under the bed. Grain scheduling and synthesis are pure Ruby (same DSP
# idiom as karplus_strong_pluck/write_stereo_chunks); ffmpeg only decodes the
# source and applies the final tone/space pass. Default on; PAD_GRANULAR=0
# disables. Knobs: PAD_GRAIN_MIX, PAD_GRAIN_SIZE_MS, PAD_GRAIN_DENSITY
# (grains/sec), PAD_GRAIN_SPRAY_MS, PAD_GRAIN_SHIMMER, PAD_GRAIN_REVERSE.
def pad_granular_enabled?
  ENV.fetch("PAD_GRANULAR", "1") != "0"
end

def pad_granular_settings
  {
    mix: (ENV["PAD_GRAIN_MIX"] || "0.5").to_f.clamp(0.05, 1.0),
    size_ms: (ENV["PAD_GRAIN_SIZE_MS"] || "120").to_f.clamp(30.0, 400.0),
    density: (ENV["PAD_GRAIN_DENSITY"] || "12").to_f.clamp(2.0, 40.0),
    spray_ms: (ENV["PAD_GRAIN_SPRAY_MS"] || "260").to_f.clamp(0.0, 1200.0),
    shimmer: (ENV["PAD_GRAIN_SHIMMER"] || "0.18").to_f.clamp(0.0, 1.0),
    reverse: (ENV["PAD_GRAIN_REVERSE"] || "0.25").to_f.clamp(0.0, 1.0),
  }
end

# Chord segments as [start_frame, end_frame) so grains can be confined to
# the chord sounding at their own onset. Without this the spray let grains
# of the PREVIOUS chord ring over the next one — on chromatic progressions
# (root moves by semitone) that smear is a straight-up dissonant mush.
def pad_grain_segments(pad_events, duration, source_frames)
  times = Array(pad_events).filter_map { |(t, _v, chord, _s)| t.to_f if chord }.sort
  return [[0, source_frames]] if times.length < 2

  bounds = times.map { |t| (t * SAMPLE_RATE).to_i.clamp(0, source_frames) }
  bounds << (duration * SAMPLE_RATE).to_i.clamp(0, source_frames)
  bounds.each_cons(2).map { |(a, b)| [a, b] }.reject { |(a, b)| b - a < 1200 }
end

def pad_grain_events(duration, source_frames, rng, grain_cfg, segments: nil)
  segments = [[0, source_frames]] if segments.nil? || segments.empty?
  size_frames = (grain_cfg[:size_ms] * SAMPLE_RATE / 1000.0).to_i
  spray_frames = (grain_cfg[:spray_ms] * SAMPLE_RATE / 1000.0).to_i
  step = 1.0 / grain_cfg[:density]
  grains = []
  t = 0.0
  while t < duration
    start_frame = [(t * SAMPLE_RATE).to_i + rng.rand(-1200..1200), 0].max
    seg = segments.reverse_each.find { |(a, _b)| a <= start_frame } || segments.first
    pitch = if rng.rand < grain_cfg[:shimmer] then 2.0
            elsif rng.rand < 0.10 then 0.5
            else 1.0
            end
    # Grain must fit inside its own chord's segment — shrink it on short
    # segments, and skip when even a minimum grain can't fit.
    seg_len = seg[1] - seg[0]
    len = (size_frames * rng.rand(0.6..1.4)).to_i.clamp(600, source_frames)
    len = [len, ((seg_len - 2) / pitch).to_i].min
    if len < 600
      t += step
      next
    end
    src_lo = seg[0]
    src_hi = [seg[1] - (len * pitch).ceil - 2, src_lo].max
    # Spray trails the playhead (granular tail, not pre-echo) but never
    # crosses back past the chord boundary.
    src = (start_frame - rng.rand(0..spray_frames)).clamp(src_lo, src_hi)
    grains << { start: start_frame, len:, src:, pitch:,
                rev: rng.rand < grain_cfg[:reverse], pan: rng.rand(-0.7..0.7),
                # Cloud swells toward the end of the piece — quiet entrance,
                # denser-feeling texture as the track develops.
                amp: rng.rand(0.45..0.9) * (0.65 + 0.35 * (t / duration)) }
    t += step * rng.rand(0.55..1.45)
  end
  grains
end

def render_pad_granular_layer(path, pads_path, duration, pad_events = nil)
  raw, = Open3.capture2("ffmpeg", "-v", "error", "-i", pads_path,
                        "-f", "f32le", "-ac", "1", "-ar", SAMPLE_RATE.to_s, "pipe:1")
  return if raw.nil? || raw.length < 4 * SAMPLE_RATE # under a second of source

  source = raw.unpack("e*")
  grain_cfg = pad_granular_settings
  rng = Random.new((@render_seed || 4242) + 977)
  segments = pad_events ? pad_grain_segments(pad_events, duration, source.length) : nil
  grains = pad_grain_events(duration, source.length, rng, grain_cfg, segments:)
  return if grains.empty?

  write_stereo_chunks(path, duration) do |chunk_start, chunk_frames, left, right|
    grains.each do |g|
      window = overlap_window(g[:start], g[:len], chunk_start, chunk_frames)
      next unless window

      dst0, grain0, count = window
      count.times do |i|
        j = grain0 + i
        pos = g[:rev] ? (g[:len] - 1 - j) : j
        sp = g[:src] + pos * g[:pitch]
        base = sp.to_i
        frac = sp - base
        s = (source[base] || 0.0) * (1.0 - frac) + (source[base + 1] || 0.0) * frac
        s *= 0.5 * (1.0 - Math.cos(2.0 * Math::PI * j / g[:len])) * g[:amp]
        left[dst0 + i] += s * (0.5 - g[:pan] * 0.5)
        right[dst0 + i] += s * (0.5 + g[:pan] * 0.5)
      end
    end
  end
  # Tone/space polish then RMS-target the cloud ~9 dB under the bed it was
  # granulated from — raw grain sums land 20+ dB down (hann window + pan
  # split + duty cycle) and the polish chain loses more (aecho in_gain), so
  # the boost is measured AFTER polish, pad-master style. Never abort the
  # whole track for a texture layer.
  soft = "#{path}.soft.wav"
  prev_soft = ENV["DILLA_SOFT_SH"]
  ENV["DILLA_SOFT_SH"] = "1"
  begin
    sh! "ffmpeg", "-y", "-i", path, "-af",
        "afade=t=in:st=0:d=1.2,highpass=f=170,lowpass=f=4600," \
        "aecho=0.5:0.5:70|130:0.2|0.1",
        "-c:a", "pcm_s16le", soft
    FileUtils.mv(soft, path) if File.file?(soft)
    pad_rms = band_rms(pads_path, highpass: 20, lowpass: 20_000)
    grain_rms = band_rms(path, highpass: 20, lowpass: 20_000)
    boost_db = (pad_rms - 9.0 - grain_rms).clamp(0.0, 30.0)
    sh! "ffmpeg", "-y", "-i", path, "-af",
        "volume=#{boost_db.round(2)}dB,alimiter=limit=0.95:level_out=0.96",
        "-c:a", "pcm_s16le", soft
    FileUtils.mv(soft, path) if File.file?(soft)
  rescue StandardError => e
    warn "pad granular polish skipped: #{e.message}"
    FileUtils.rm_f(soft)
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
  end
  File.file?(path) ? path : nil
end

def mix_granular_into_pads!(pads_path, grain_path, duration)
  return unless pads_path && grain_path && File.file?(pads_path) && File.file?(grain_path)

  out = "#{pads_path}.grain_mix.wav"
  weight = pad_granular_settings[:mix]
  # Duck the cloud when a vocal rides this track — the grain texture is
  # exactly the "mylder" a quiet vocal stem drowns in.
  rap_slug = ENV["RAP_VOCAL"].to_s
  weight *= 0.6 unless rap_slug.empty? || rap_slug == "0"
  prev_soft = ENV["DILLA_SOFT_SH"]
  ENV["DILLA_SOFT_SH"] = "1"
  begin
    sh! "ffmpeg", "-y", "-i", pads_path, "-i", grain_path,
        "-filter_complex",
        "[0:a]apad=whole_dur=#{duration}[p];[1:a]apad=whole_dur=#{duration}[g];" \
        "[p][g]amix=inputs=2:weights=1.0 #{weight.round(3)}:duration=first:normalize=0," \
        "alimiter=limit=0.96:level_out=0.97[out]",
        "-map", "[out]", "-t", duration.to_s, "-c:a", "pcm_s16le", out
    FileUtils.mv(out, pads_path) if File.file?(out)
  rescue StandardError => e
    warn "pad granular mix skipped: #{e.message}"
    FileUtils.rm_f(out)
  ensure
    prev_soft ? ENV["DILLA_SOFT_SH"] = prev_soft : ENV.delete("DILLA_SOFT_SH")
    FileUtils.rm_f(grain_path)
  end
end

# --------------------------------------------------- wav_Map as a pad layer
#
# WAV_MAP=<image> renders that picture as a sustained oscillator under the mix.
#
# WavMap reads an image as a height field and traces a closed path across it to
# make one cycle of a waveform, so the picture's texture becomes the tone's
# harmonic content. Until now it was reachable only from the command line, which
# meant the one bridge between STUDIO's image tools and its audio engine could
# not be crossed by a render.
#
# The pitch is the track's own tonic rather than a number: a drone in the wrong
# key is the one layer no amount of level fixes, and KeyLock already knows what
# the rotation is centred on. Two octaves down from A4 puts it under the bass
# where a drone belongs.
#
# Off by default. It adds a continuous tone to every bar of a render, which is a
# large decision, and the image is the operator's to choose -- there is no
# sensible default picture.
def wav_map_layer!(cfg, duration)
  image = ENV["WAV_MAP"].to_s
  return nil if image.empty?

  # WAV_MAP names an image FILE; WAV_MAP_PATH names the shape traced across it.
  # Given a shape name here the layer is skipped, the render succeeds and the
  # log still lists the stage -- a beat missing a whole layer with nothing to
  # say so. Say it.
  unless File.file?(image)
    dmesg_warn("WAV_MAP=#{image} is not a file — no wav-map layer " \
               "(the traversal shape belongs in WAV_MAP_PATH)")
    return nil
  end

  tonic = KeyLock::PITCH_CLASS[ENV.fetch("KEY_LOCK_TONIC", "Bb")] || 10
  hz = 110.0 * (2.0**(tonic / 12.0))
  hz /= 2.0 while hz > 165.0
  dest = dilla_render_tmp("wavmap")
  out = WavMap.render!(image, dest,
                       hz: ENV.fetch("WAV_MAP_HZ", hz.round(2)).to_f,
                       duration:,
                       path: ENV.fetch("WAV_MAP_PATH", "circle").to_sym,
                       lobes: ENV.fetch("WAV_MAP_LOBES", "5").to_i,
                       rate: SAMPLE_RATE,
                       drift_cents: ENV.fetch("WAV_MAP_DRIFT", "6").to_f,
                       seed: seed_for("wavmap"))
  return nil unless out && File.file?(out)

  dmesg("wav map: #{File.basename(image)} as an oscillator at #{hz.round(1)}Hz",
        unit: "harm0", parent: "dilla0")
  out
end

# --------------------------------------------------------------------------
# engine part: lead_render
# --------------------------------------------------------------------------
#
# Rendering leads and counter-leads, and mixing the harmonic stems.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# 81 Sawtooth (original), 87 Lead 8 "bass+lead" (GM's own name traces to the
# classic Prophet-5 "BigLead" patch — literally the historical big-lead
# archetype), 84 Lead 5 Charang (aggressive/bright, cuts through), 86 Lead 7
# Fifths (built-in parallel fifths give arps instant harmonic width free).
LEAD_GM_PROGRAMS = [81, 87, 84, 86].freeze
# Hotter lead target so arps cut over multi-layer pads.
LEAD_TARGET_RMS_DB = -14.5

# Voices for the counter-line: strings and choirs, not synth leads.
#
# The four programs above are all bright synth leads, chosen to cut through. A
# second voice that has to cut through is a second voice competing, which is the
# problem this layer exists to solve. Strings and voices do the opposite -- they
# hold a note and sit behind, so the line is heard as an answer rather than as
# something shouting over the top.
#
# They also suit what the line actually plays. It holds each note for about two
# beats, and a held note is what strings and choirs are for; a square-wave lead
# holding for two beats sounds stuck.
#
# These voices are already in the patch table (choir_aahs, voice_oohs,
# juno_strings, string_orchestra) but only as pads -- every one is registered
# role: :warm, so nothing could reach them for a melody until now.
COUNTER_LEAD_PROGRAMS = {
  choir: 52,          # choir aahs -- the "aah" bed
  voices: 53,         # voice oohs -- softer, rounder, further back
  strings: 48,        # string ensemble
  warm_strings: 49,   # slower attack, arrives under the beat
  synth_strings: 50,  # solina-ish, the most obviously synthetic of the five
  synth: 81,          # the old bright lead, if it is ever wanted back,
}.freeze

def counter_lead_program
  COUNTER_LEAD_PROGRAMS.fetch(ENV.fetch("LEAD_TIMBRE", "choir").downcase.to_sym) do
    COUNTER_LEAD_PROGRAMS[:choir]
  end
end

# Softer than a lead and darker than a pad.
#
# Leads here target -14.5 dBFS so an arp can cut over the stack. This one is not
# trying to cut over anything, so it sits about 6 dB under that, and a lowpass
# takes the top off. Standard advice for putting a part behind another is to
# lower it AND roll off its highs -- level alone leaves a small bright thing in
# front rather than a soft thing behind.
COUNTER_LEAD_TARGET_RMS_DB = -20.5
COUNTER_LEAD_LOWPASS_HZ = 5200

# Never quite in tune, and never quite dry.
#
# A sampled record is a few cents off because the tape it came from was, and
# nothing in this idiom is at concert pitch by accident. A perfectly tuned
# choir sitting on top of samples that are not is the one voice that sounds
# synthetic. asetrate does it the way a varispeed does -- pitch and duration
# move together -- rather than pretending the two are separable.
#
# The reverb is a send, filtered the way a send should be: high-passed so the
# tail does not muddy the low mid, low-passed so it sits behind the dry signal
# rather than adding brightness of its own. Standard practice on a return, and
# the reason the counter-line reads as "in the room" instead of "on top".
COUNTER_LEAD_DETUNE_CENTS = -7.0
COUNTER_LEAD_VERB_HP_HZ = 300
COUNTER_LEAD_VERB_LP_HZ = 9000

# Drenched, not damp.
#
# A lead can be a problem in two ways: it can play the wrong notes, or it can be
# too present. This one had been rewritten three times for the notes and still
# sat too far forward, so it comes back pushed into the room instead of onto the
# front of the mix. At this depth the line reads as atmosphere with a melody
# inside it rather than as a part demanding attention -- which is what a
# sixty-percent wet return does, and what a thirty-four-percent one does not.
#
# Eight taps out to 1.6 seconds rather than three out to 180 ms. The long ones
# are what makes it a space; the short ones alone are a slapback.
COUNTER_LEAD_VERB_MIX = (ENV["LEAD_VERB_MIX"] || 0.62).to_f
COUNTER_LEAD_VERB_TAPS = "aecho=0.9:0.88:60|110|180|320|520|780|1120|1600:" \
                         "0.5|0.44|0.38|0.32|0.26|0.2|0.15|0.1"

# No varispeed here. The detune happens at synthesis; see counter_lead_detune.
#
# This chain used to start with asetrate + aresample to pull the voice 7 cents
# flat. asetrate is a VARISPEED -- it moves pitch and duration together, the way
# a tape machine does -- and applied to a whole rendered layer rather than to a
# one-shot sample it stretches the entire performance. At -7 cents the layer
# plays 0.405% slow, so every note after the first arrives progressively later
# than the drums it was written against:
#
#   over 46s   0.188s late by the end = 1.10 sixteenth notes at 88 BPM
#   over 60s   0.243s late by the end = 1.43 sixteenths
#
# It is never in the same relationship to the beat twice, and it gets worse as
# the track runs. The operator heard it as "the leads sound off", which is
# exactly what it was: off the beat, by more than a sixteenth, increasingly.
#
# Detuning the NOTES instead gets the same out-of-tune-tape colour with the
# timing untouched, because a frequency written 7 cents flat is 7 cents flat and
# nothing else moves.
def counter_lead_space_chain
  # Two echoes in series, not one: the second smears the first's taps into each
  # other, which is how a cheap reverb is built and why it stops sounding like
  # discrete repeats. Modulated slightly so the tail moves instead of ringing on
  # one pitch.
  wet = "highpass=f=#{COUNTER_LEAD_VERB_HP_HZ},lowpass=f=#{COUNTER_LEAD_VERB_LP_HZ}," \
        "#{COUNTER_LEAD_VERB_TAPS},aecho=0.85:0.8:37|53:0.4|0.32," \
        "vibrato=f=0.6:d=0.06,volume=#{COUNTER_LEAD_VERB_MIX}"
  "lowpass=f=#{COUNTER_LEAD_LOWPASS_HZ}," \
    "asplit=2[cldry][clwet];[clwet]#{wet}[clverb];[cldry][clverb]amix=inputs=2:normalize=0"
end

# The ratio to write into a note's frequency, applied where the note is chosen.
def counter_lead_detune = 2.0**(COUNTER_LEAD_DETUNE_CENTS / 1200.0)

def invert_motif(motif)
  top = motif.max
  motif.map { |d| top - d }
end

# Leitmotif seeded from the progression's own opening chord — stable for
# a given piece, so the lead states one real idea and develops it
# (inversion/retrograde/augmentation) instead of generating a fresh,
# unrelated arp pattern at every chord change.
def leitmotif_for(pad_events)
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    hook = @composition_session.motifs.find { |m| m.id == "hook" }
    return hook.degrees_for_playback if hook
  end
  seed_source = pad_events.first&.dig(2, :name).to_s
  rng = Random.new(stable_hash(seed_source) % 100_000)
  length = [3, 4].sample(random: rng)
  Array.new(length) { rng.rand(4) }
end

def resolve_scale_lead_voice
  if ENV["DILLA_SCALE_LEAD_PROGRAM"]
    return { sf2: pad_soundfont_path, bank: 0, program: ENV["DILLA_SCALE_LEAD_PROGRAM"].to_i,
             patch: @render_scale_lead_patch }
  end
  patch_voice_for(@render_scale_lead_patch) ||
    patch_voice_for(@render_lead_patch) ||
    { sf2: pad_soundfont_path, bank: 0, program: render_pick(LEAD_GM_PROGRAMS, "lead_program"), patch: nil }
end

# Interesting default lead FX — delay, chorus, subtle phaser, air shelf, soft drive.
LEAD_FX_RICH_DEFAULT = [
  "highpass=f=180",
  "equalizer=f=2800:t=o:w=1.4:g=2.8",
  "equalizer=f=5200:t=h:w=1.2:g=1.6",
  "chorus=0.48:0.68:36|48:0.22|0.18:0.26|0.22:1.1|1.35",
  "aecho=0.48:0.42:140|280:0.28|0.14",
  "aphaser=speed=0.14:decay=0.45",
  "vibrato=f=0.32:d=0.011",
  "lowpass=f=6200:width_type=q:width=0.85",
].join(",").freeze

LEAD_FX_VARIANTS = [
  LEAD_FX_RICH_DEFAULT,
  "highpass=f=200,tremolo=f=4.2:d=0.08,chorus=0.4:0.6:30|40:0.18|0.14:0.22|0.18:1.0|1.25,aecho=0.42:0.36:100|190:0.24|0.12,lowpass=f=5400",
  "highpass=f=160,aecho=0.55:0.5:180|320:0.32|0.16,aphaser=speed=0.2:decay=0.5,equalizer=f=3200:t=o:w=1.3:g=3.2,lowpass=f=7000",
  "highpass=f=220,acrusher=bits=12:samples=1.5:mix=0.06,chorus=0.52:0.72:40|52:0.24|0.2:0.28|0.24:1.15|1.4,aecho=0.4:0.35:90|160:0.2|0.1,lowpass=f=5000",
  "highpass=f=190,vibrato=f=0.55:d=0.016,tremolo=f=0.35:d=0.06,aecho=0.5:0.44:150|260:0.26|0.14,lowpass=f=5800",
].freeze

# Trim a rendered stem to a target RMS. Exists because the lead path used to
# measure the raw fluidsynth output, apply the make-up gain, and only THEN run
# the patch's fx chain -- and 95 of the catalog's aecho/chorus entries carry
# attenuating in_gain:out_gain pairs worth -12..-20 dB (the same argument-order
# mistake fixed on the harmonic bus in f733aa3ee). The fx knocked the lead back
# down after the gain had already been committed, so LEAD_TARGET_RMS_DB was
# never actually reached and leads sat far under the kit. Normalising on the way
# out measures what the listener actually gets.
def normalize_wav_to_rms!(path, target_db, floor: -24.0, ceil: 26.0)
  return path unless File.file?(path) && tool_available?("ffmpeg")
  measured = band_rms(path, highpass: 20, lowpass: 20_000)
  return path unless measured.finite?
  gain = (target_db - measured).clamp(floor, ceil)
  return path if gain.abs < 0.2
  tmp = "#{path}.norm.wav"
  sh! "ffmpeg", "-y", "-i", path, "-af",
      "volume=#{gain.round(2)}dB,alimiter=limit=0.96:level_out=0.97",
      "-c:a", "pcm_s16le", tmp
  FileUtils.mv(tmp, path) if File.file?(tmp)
  path
end

def lead_post_fx_chain(patch, duration, boost_db)
  base = "volume=#{boost_db.round(2)}dB"
  patch_fx = patch&.dig(:fx)
  # Blend patch identity FX with a rotating rich chain so every take has motion.
  # Process.pid stays out of here. In it, the lead comes out with a different
  # effect chain on every single run -- the take you liked cannot be got back, and
  # two renders of one track are never comparable. The render seed alone is
  # what it was always meant to be keyed on.
  variant = LEAD_FX_VARIANTS[(@render_seed || 0) % LEAD_FX_VARIANTS.length]
  rich = ENV.fetch("LEAD_FX_RICH", "1") != "0"
  body = if patch_fx && !patch_fx.empty?
           rich ? "#{patch_fx},#{variant}" : patch_fx
         else
           rich ? variant : LEAD_FX_RICH_DEFAULT
         end
  [base, body, "apad=whole_dur=#{duration}", "alimiter=limit=0.94:level_out=0.97"].join(",")
end

HARMONIC_STEM_MIX = {
  pads:          { volume: 1.35, weight: 1.7 },
  tones:         { volume: 0.72, weight: 0.55 },
  # The melodic voice when SU_MELODY is on, which is also when every lead lane
  # below is empty by construction — so this carries the top line alone.
  su_melody:     { volume: 1.4, weight: 1.15 },
  harmony_lead:  { volume: 1.15, weight: 0.72 },
  scale_lead:    { volume: 1.2, weight: 0.78 },
  lead_arp:      { volume: 1.45, weight: 1.05 },
  lead:          { volume: 1.1, weight: 0.55 },
  xlead:         { volume: 0.74, weight: 0.36 },
}.freeze

def harmonic_stem_mix_value(key, field)
  env_key = "HARMONIC_#{key.to_s.upcase}_#{field.to_s.upcase}"
  raw = ENV[env_key]
  return raw.to_f if raw && !raw.empty?
  HARMONIC_STEM_MIX.dig(key, field) || 1.0
end

def mix_harmonic_wav_stems(destination, duration, **stem_paths)
  lanes = HARMONIC_STEM_MIX.filter_map do |key, _mix|
    path = stem_paths[key]
    next unless path && File.exist?(path)
    [key, path, harmonic_stem_mix_value(key, :volume), harmonic_stem_mix_value(key, :weight)]
  end
  return false if lanes.length < 2

  filter_labels = []
  mix_in = []
  lanes.each_with_index do |(_key, _path, volume, _weight), idx|
    label = "h#{idx}"
    filter_labels << "[#{idx}:a]volume=#{volume}[#{label}]"
    mix_in << "[#{label}]"
  end
  weights = lanes.map { |l| l[3] }.join(" ")
  filter = "#{filter_labels.join(';')};" \
             "#{mix_in.join}amix=inputs=#{lanes.length}:weights=#{weights}:duration=longest:normalize=0," \
             "aresample=#{SAMPLE_RATE},alimiter=limit=0.96:level_out=0.98[harmonic]"
  args = ["ffmpeg", "-y"]
  lanes.each { |(_, path)| args << "-i" << path }
  sh!(*args, "-filter_complex", filter, "-map", "[harmonic]",
      "-t", duration.to_s, "-ar", SAMPLE_RATE.to_s, "-c:a", "pcm_s16le", destination)
  lanes.drop(2).each { |(_, path)| FileUtils.rm_f(path) } # scan: intentional — removes only the temp files this method rendered
  true
end

def render_lead_via_fluidsynth(path, lead_events, duration, scale_arp: false, counter: false, program_override: nil)
  return if lead_events.empty? || !fluidsynth_pad_available?
  midi_path = "#{path}.smf.mid"
  lead_voice = scale_arp ? resolve_scale_lead_voice : resolve_lead_voice
  patch = lead_voice[:patch] || (scale_arp ? @render_scale_lead_patch : @render_lead_patch)
  role = scale_arp ? :scale_lead : :lead
  # The counter-line borrows the lead's soundfont and takes a strings or choir
  # program out of it, rather than the bright synth the rotation would pick.
  program = program_override || (counter ? counter_lead_program : lead_voice[:program])
  write_smf(midi_path, lead_events, program:, bank: (counter ? 0 : lead_voice[:bank]),
            duration:, midi_fx: resolve_midi_fx_for(patch, role:), lead_mode: true)
  fs_gain = lead_voice[:patch]&.fetch(:fs_gain, 1.3) || 1.3
  fluidsynth_render!(path, lead_voice[:sf2], midi_path, gain: fs_gain)
  FileUtils.rm_f(midi_path)
  target_db = if counter then COUNTER_LEAD_TARGET_RMS_DB
              elsif scale_arp then LEAD_TARGET_RMS_DB + 1.5
              else LEAD_TARGET_RMS_DB
              end
  patch = lead_voice[:patch] || (scale_arp ? @render_scale_lead_patch : @render_lead_patch)
  chain = lead_post_fx_chain(patch, duration, 0.0)
  if counter
    # Detune, roll the top off, and send to a filtered reverb -- all BEFORE the
    # patch chain, so what follows is working on an already-soft, already-placed
    # signal rather than brightening it back up.
    sh! "ffmpeg", "-y", "-i", path, "-filter_complex",
        "[0:a]#{counter_lead_space_chain},#{chain}[out]", "-map", "[out]",
        "-c:a", "pcm_s16le", "#{path}.lead.wav"
  else
    sh! "ffmpeg", "-y", "-i", path, "-af", chain, "-c:a", "pcm_s16le", "#{path}.lead.wav"
  end
  FileUtils.mv("#{path}.lead.wav", path)
  normalize_wav_to_rms!(path, target_db)
  # The LPG here and not at the hocket exit: this is the leaf every lead path
  # bottoms out in, and that exit is one of four. See the note above the section
  # envelope -- a feature wired into half the paths it applies to is the harder
  # bug to see, because it works.
  low_pass_gate_lead!(path)
  path
end

def render_harmonic_wav(path, pad_events, chop_events, bass_events, duration, melody_events: [], cfg: nil, dfam_events: nil,
                        pad_post: true)
  cfg ||= dilla_resolve_config
  pick_synth_patches!(cfg) unless @render_ep_patch
  @render_used_fluidsynth_pad = false
  tones_path = "#{path}.tones.wav"
  pads_path = "#{path}.pads.wav"
  lead_path = "#{path}.lead.wav"
  lead_arp_path = "#{path}.lead_arp.wav"
  xlead_path = "#{path}.xlead.wav"
  harmony_lead_path = "#{path}.harmony_lead.wav"
  scale_lead_path = "#{path}.scale_lead.wav"
  used_singers_chops = false
  if singers_chop_pads_enabled?
    begin
      used_singers_chops = !!render_singers_chop_pads(pads_path, pad_events, duration)
    rescue StandardError => e
      warn "singers chop pads skipped: #{e.message}"
    end
  end
  # Octave doubling applies to the pad render only. pad_events is also what the
  # bass, the chop grid and the melody read their chords from, and adding voices
  # to the shared list would have the bass playing the doubling too.
  pad_render_events = grand_pads? ? grandeur_pad_events(pad_events) : pad_events
  if grand_pads?
    dmesg("grand pads: #{pad_events.length} chords -> #{pad_render_events.length} voicings (8vb root+5th, 8va upper)",
          unit: "harm0", parent: "dilla0")
  end
  if used_singers_chops
    # Real chopped vocal bed replaces the synth pad stack entirely.
  elsif fluidsynth_pad_available?
    render_pad_via_fluidsynth(pads_path, pad_render_events, duration)
  else
    render_native_pad_wav(pads_path, pad_render_events, duration)
  end
  # Soft Singers Unlimited–like ooh/aah on chord tones under the pad bed —
  # redundant (and muddy) when the bed already IS chopped real vocals.
  if choir_vox_enabled? && !used_singers_chops
    choir_path = "#{path}.choir_vox.wav"
    begin
      if render_choir_vox_layer(choir_path, pad_events, duration)
        mix_choir_into_pads!(pads_path, choir_path, duration)
      else
        FileUtils.rm_f(choir_path)
      end
    rescue StandardError => e
      warn "choir_vox skipped: #{e.message}"
      FileUtils.rm_f(choir_path)
    end
  end
  # Granular cloud resynthesized from the finished pad+choir bed itself
  # (see render_pad_granular_layer) and floated back under it.
  if pad_granular_enabled?
    grain_path = "#{path}.grains.wav"
    begin
      if render_pad_granular_layer(grain_path, pads_path, duration, pad_events)
        mix_granular_into_pads!(pads_path, grain_path, duration)
      else
        FileUtils.rm_f(grain_path)
      end
    rescue StandardError => e
      warn "pad granular skipped: #{e.message}"
      FileUtils.rm_f(grain_path)
    end
  end
  # The resynthesized choir IS the top line, so every synth lead lane below is
  # skipped rather than mixed quiet. Two top lines at once is the soup the
  # comment further down is about, and a vocal one loses that fight by being
  # the more interesting signal — mixing them muddies both.
  su_melody_path = "#{path}.su_melody.wav"
  su_melody_rendered = nil
  if su_melody_enabled? && !no_lead?
    begin
      su_melody_rendered = render_su_tunnel_melody(
        su_melody_path, pad_events, duration,
        cfg: cfg, n_bars: (duration / ((60.0 / cfg[:bpm]) * 4.0)).ceil
      )
    rescue StandardError => e
      warn "su tunnel melody skipped: #{e.message}"
    end
  end
  # NO_LEAD=1 silences every top line there is: the four synth lanes and the
  # choir together. Asked for twice -- the first time it was read as "change it",
  # which was the other half of the same sentence and the wrong half. With no
  # lead the rapper is the top line, which is what a Dilla beat is anyway.
  leads_muted = !!su_melody_rendered || no_lead?

  n_bars_est = (duration / ((60.0 / cfg[:bpm]) * 4.0)).ceil
  # One clean melodic lead by default — scale/creative layers turned the top line into soup.
  scale_on = !leads_muted && lead_arp_enabled? && ENV.fetch("SCALE_LEAD", "0") != "0"
  creative_on = !leads_muted && lead_arp_enabled? && ENV.fetch("CREATIVE_LEAD", "0") != "0"
  scale_events = scale_on ? lead_events_scale_arp(pad_events, cfg, duration:, n_bars: n_bars_est) : []
  lead_arp_cfg = lead_arp_cfg_for(@render_lead_patch)
  # The counter-line replaces the arp rather than joining it. Two top lines at
  # once is the soup the comment above is about, and this one is written to
  # answer the chords, which only works if nothing else is talking over them.
  counter_events = leads_muted ? [] : lead_events_melodic(pad_events, cfg, duration:, n_bars: n_bars_est)
  lead_arp_ev = !leads_muted && lead_arp_enabled? && counter_events.empty? ?
                lead_arp_events(pad_events, cfg, lead_arp_cfg) : []
  harmony_lead_cfg = harmony_lead_cfg_for(@render_scale_lead_patch)
  insight = instance_variable_defined?(:@progression_insight) ? @progression_insight : nil
  harmony_lead_ev = !leads_muted && harmony_lead_enabled? && ENV.fetch("HARMONY_LEAD", "0") != "0" ?
                    harmony_lead_events(pad_events, cfg, harmony_lead_cfg, progression_insight: insight) : []
  creative_events = creative_on ? lead_events_creative(pad_events, cfg, duration:, n_bars: n_bars_est) : []

  # MIDI_BAG=1 — the lead's pitches, on the kit's rhythm.
  #
  # ringtone.tools' MIDI Bag, at the one place in this engine where both halves
  # already exist as note events: the arp has pitches with a contour, and the
  # drum grid has onsets with accents. Normally a note is an indivisible pair of
  # the two. This refuses that pairing and takes each half from a different part.
  #
  # sample_flip does the same separation for AUDIO slices and constrains them to
  # the chord underneath. Nothing did it for note events, so a melody the engine
  # generated could not be re-rhythmed by a pattern the engine also generated.
  #
  # Applied before the section envelope below, so a bagged lead still obeys the
  # arrangement -- the envelope drops notes outside their sections, and it has to
  # act on the notes that will actually sound.
  harmony_lead_ev = midi_bag_lead_events(harmony_lead_ev, cfg, n_bars_est)
  lead_arp_ev = midi_bag_lead_events(lead_arp_ev, cfg, n_bars_est)

  # The lead's section envelope, applied to its notes because it has no bus.
  #
  # All four lead paths, for the reason the comment below gives about the log
  # line that reported on two of them: a feature wired into half the paths it
  # applies to is the harder bug to see, because it works.
  if section_layers_full? && (lead_bar_p = (60.0 / cfg[:bpm].to_f) * 4.0).positive?
    scale_events = apply_section_envelope_to_events(scale_events, :lead, n_bars_est, lead_bar_p)
    counter_events = apply_section_envelope_to_events(counter_events, :lead, n_bars_est, lead_bar_p)
    lead_arp_ev = apply_section_envelope_to_events(lead_arp_ev, :lead, n_bars_est, lead_bar_p)
    harmony_lead_ev = apply_section_envelope_to_events(harmony_lead_ev, :lead, n_bars_est, lead_bar_p)
    creative_events = apply_section_envelope_to_events(creative_events, :lead, n_bars_est, lead_bar_p)
  end

  scale_lead_rendered = scale_events.any? ? render_lead_via_fluidsynth(scale_lead_path, scale_events, duration, scale_arp: true) : nil
  harmony_lead_rendered = harmony_lead_ev.any? ? render_hocket_lead!(harmony_lead_path, harmony_lead_ev, duration) : nil
  # Say which lead actually played, and how many notes it played.
  #
  # The counter-line silently returned nothing for a whole render batch because
  # apply_best_defaults! set MELODIC_LEAD=0 after demo_all had cleared it. The
  # banner still announced steady mode, every take came out with the old arps,
  # and nothing in the log disagreed. One line here would have caught it in the
  # first render instead of the eighth.
  #
  # All four lead paths, not two. This message was written to answer "which lead
  # actually played" and then reported on counter_events and lead_arp_ev only,
  # while scale_events and harmony_lead_ev were computed twenty lines above and
  # rendered to fluidsynth on the two lines above this one. So a take with a
  # harmony lead on it logged "lead: none", which is the same silence the comment
  # above is about — one layer over.
  #
  # It cost a render to find. A Vaular take was re-rendered specifically to add a
  # lead, on the strength of this line saying there was none.
  #
  # leads_muted is named separately rather than left to fall through to "none".
  # Under SU_MELODY every one of the four lanes is empty by construction, so the
  # honest four-path report and a silent-by-mistake render print the same word.
  # That is the exact confusion both comments above are about, so the one case
  # where the silence is deliberate says so.
  if leads_muted
    # Two different silences, and the message used to claim the choir either
    # way. Under NO_LEAD nothing is playing a top line at all, and saying "su
    # tunnel choir" there reports a voice that is not in the render -- the exact
    # thing the four-lane comment below was written to stop.
    dmesg(su_melody_rendered ? "lead: su tunnel choir (four synth lanes muted)"
                             : "lead: none (NO_LEAD -- four synth lanes, choir and pluck all off)",
          unit: "harm0", parent: "dilla0")
  else
    played = []
    played << "counter-line #{counter_events.length}n/#{ENV.fetch('LEAD_TIMBRE', 'choir')}" if counter_events.any?
    played << "arp #{lead_arp_ev.length}n" if lead_arp_ev.any?
    played << "scale #{scale_events.length}n" if scale_events.any?
    played << "harmony #{harmony_lead_ev.length}n" if harmony_lead_ev.any?
    dmesg("lead: #{played.empty? ? 'none' : played.join(' + ')}", unit: "harm0", parent: "dilla0")
  end

  lead_arp_rendered = if counter_events.any?
                        render_lead_via_fluidsynth(lead_arp_path, counter_events, duration, counter: true)
                      elsif lead_arp_ev.any?
                        render_lead_via_fluidsynth(lead_arp_path, lead_arp_ev, duration)
                      end
  xlead_rendered = nil
  if lead_morph_enabled? && !leads_muted
    xlead_fs = render_xlead_morph_fluidsynth(xlead_path, pad_events, duration, cfg)
    xlead_native = render_xlead_native_fm("#{xlead_path}.native.wav", pad_events, duration, cfg)
    xlead_rendered = blend_xlead_stems(xlead_path, xlead_fs, xlead_native, duration)
    FileUtils.rm_f("#{xlead_path}.native.wav")
  end
  lead_rendered = creative_events.any? ? render_lead_via_fluidsynth(lead_path, creative_events, duration) : nil
  # Karplus-Strong plucked-string accent on each chord's root — a genuinely
  # new instrument timbre (real physical-modeling algorithm, not another
  # oscillator/soundfont voice), pre-rendered per chord since the algorithm
  # itself needs a contiguous buffer, then windowed into the tones stream
  # the same way chop/melody events already are.
  # The pluck plays the root of every chord, for 1.1s, on every take, and it was
  # the only melodic voice in the engine with no switch at all. With the four
  # synth lanes and the choir silenced it was what remained playing a line --
  # which is why "not that lead" came after a lead had already been removed.
  # PLUCK=0 turns it off; NO_LEAD takes it with everything else.
  pluck_on = ENV.fetch("PLUCK", "1") != "0" && !no_lead?
  pluck_buffers = (pluck_on ? pad_events : []).filter_map do |(t, v, chord, _sustain)|
    next unless chord && chord[:hz]&.any?
    [t, v, karplus_strong_pluck(chord[:hz].min, 1.1, seed: stable_hash(chord[:name].to_s) % 100_000)]
  end
  write_stereo_chunks(tones_path, duration) do |chunk_start, chunk_frames, left, right|
    pluck_buffers.each do |(t, v, buf)|
      event_frame = (t * SAMPLE_RATE).round
      window = overlap_window(event_frame, buf.length, chunk_start, chunk_frames)
      next unless window
      local_start, source_offset, count = window
      count.times do |i|
        sample = buf[source_offset + i] * v * 0.16
        left[local_start + i] += sample
        right[local_start + i] += sample
      end
    end
    chop_events.each do |(t, v, chord)|
      hz_list = chop_hz(chord)
      next if hz_list.empty?
      event_frame = (t * SAMPLE_RATE).round
      total = (0.28 * SAMPLE_RATE).round
      window = overlap_window(event_frame, total, chunk_start, chunk_frames)
      next unless window
      local_start, source_offset, count = window
      frequency = hz_list[((t * 10).to_i) % hz_list.length]
      mix_sine!(left, right, local_start, count, frequency, v * 0.13,
                decay: 2.0, mod_hz: 0.45, source_offset:)
    end

    melody_gain = MELODY_BASE_GAIN * resolved_lead_mix_weight
    melody_events.each do |(t, v, hz)|
      event_frame = (t * SAMPLE_RATE).round
      total = (0.18 * SAMPLE_RATE).round
      window = overlap_window(event_frame, total, chunk_start, chunk_frames)
      next unless window
      local_start, source_offset, count = window
      frequency = hz.is_a?(Numeric) ? hz : MELODY_CHOP_HZ.first
      count.times do |i|
        tt = (source_offset + i).to_f / SAMPLE_RATE
        sample = v * melody_gain * Math.exp(-tt * 8.5) * Math.sin(2 * Math::PI * frequency * tt)
        left[local_start + i] += sample * 0.55
        right[local_start + i] += sample * 0.45
      end
    end

    bass_events.each do |hit|
      t, v = hit[0], hit[1]
      root = hit[2].is_a?(Numeric) ? hit[2] : 43.65
      slide_from = hit[4].is_a?(Numeric) ? hit[4] : nil
      total = [((hit[3] || BASS_SUSTAIN_SEC) * SAMPLE_RATE).round, 1].max
      event_frame = (t * SAMPLE_RATE).round
      window = overlap_window(event_frame, total, chunk_start, chunk_frames)
      next unless window
      local_start, source_offset, count = window
      slide_portion = bass_slide_enabled? && slide_from ? 0.38 : 0.0
      count.times do |i|
        tt = (source_offset + i).to_f / SAMPLE_RATE
        lfo = 0.03 * Math.sin(2 * Math::PI * 0.12 * tt)
        progress = i.to_f / [count - 1, 1].max
        freq = if slide_portion.positive? && progress < slide_portion
                 slide_from + (root - slide_from) * (progress / slide_portion)
               else
                 root
               end
        sample = v * BASS_LEVEL * Math.exp(-tt * BASS_DECAY_RATE) *
                 Math.sin(2 * Math::PI * freq * (1.0 + lfo) * tt)
        left[local_start + i] += sample
        right[local_start + i] += sample
      end
    end
  end
  # Balance pads and tones (chop+melody+bass) independently before mixing —
  # a shared limiter meant a loud bass transient in "tones" ducked the pad
  # chords along with it. Static gain staging (volume=), not a limiter per
  # stem, does that same job with zero dynamic/gain-reduction interaction —
  # a limiter's job is peak safety, and stacking one per stem plus another
  # on the combine (mastering-engineer critique: too many cascaded limiter
  # stages loses transient definition) bought nothing a plain gain match
  # didn't already cover. One limiter at the combine stage remains as the
  # actual safety net; master_bus_filters is the real mastering-stage limit
  # downstream.
  mix_harmonic_wav_stems(path, duration,
                         pads: pads_path, tones: tones_path,
                         su_melody: (su_melody_rendered ? su_melody_path : nil),
                         harmony_lead: (harmony_lead_rendered ? harmony_lead_path : nil),
                         scale_lead: (scale_lead_rendered ? scale_lead_path : nil),
                         lead_arp: (lead_arp_rendered ? lead_arp_path : nil),
                         xlead: (xlead_rendered ? xlead_path : nil),
                         lead: (lead_rendered ? lead_path : nil))
  FileUtils.rm_f(pads_path)
  FileUtils.rm_f(tones_path)
  FileUtils.rm_f(su_melody_path)
  if dfam_events&.any?
    dfam_path = "#{path}.dfam.wav"
    render_dfam_wav(dfam_path, dfam_events, duration)
    tmp = "#{path}.dfam_mix.wav"
    sh! "ffmpeg", "-y", "-i", path, "-i", dfam_path,
        "-filter_complex", "[0:a][1:a]amix=inputs=2:weights=1.0 0.26:duration=first:normalize=0,alimiter=limit=0.96[out]",
        "-map", "[out]", "-t", duration.to_s, "-c:a", "pcm_s16le", tmp
    FileUtils.mv(tmp, path)
    FileUtils.rm_f(dfam_path)
  end
  # Skipped for the bass-only render: this chain is voiced for pads (3.2k
  # lowpass, chorus, echo, pad-shaped compression) and smears a sine bass.
  warm_dilla_pad_post(path, cfg: cfg || dilla_resolve_config) if pad_post
end

# Measured (not guessed) via zero-crossing analysis of the sample body,
# post-attack — the "43" in the filename doesn't reliably encode a MIDI
# note. Only sample keys listed here get pitch-shifted to a target hz;
# everything else (kick/snare/hat/ghost) plays at native pitch.
# The pitch each sample was cut or synthesised at, so a hit asking for a target
# frequency can be resampled to it. A sample missing from here cannot be pitched
# at all -- ratio falls to 1.0 and the hit plays at its own pitch silently,
# which is how the industrial bass stayed in a fixed E-to-Bb tritone no matter
# what key the rest of the catalogue was in. Both values are read straight off
# the generators in ensure_drum_kit!: ind_bass_e is aevalsrc at 41.2 Hz,
# ind_bass_bb at 58.27 Hz.
SAMPLE_NATURAL_HZ = { bass_43: 49.0, cowbell: 670.0,
                      ind_bass_e: 41.2, ind_bass_bb: 58.27 }.freeze

def render_sample_bus_wav(path, events, duration, kit, mapping)
  write_stereo_chunks(path, duration) do |chunk_start, chunk_frames, left, right|
    mapping.each do |event_key, default_key|
      events.fetch(event_key, []).each do |hit|
        time, velocity = hit[0], hit[1]
        target_hz = hit[2].is_a?(Numeric) ? hit[2] : nil
        sample_key = hit[2].is_a?(Symbol) ? hit[2] : default_key
        pan = hit[3].is_a?(Numeric) ? hit[3].to_f : 0.0
        sample = kit.fetch(sample_key)
        natural_hz = SAMPLE_NATURAL_HZ[sample_key]
        # Sample-based bass ignored bass_root entirely — every hit played
        # samples/drums/bass_43.wav at its own fixed pitch regardless of the
        # actual chord, so the loudest, most frequent low-end voice in the
        # mix never followed the harmony. Resample (classic MPC-style pitch
        # shift) toward the chord root instead.
        ratio = (target_hz && natural_hz) ? (target_hz / natural_hz) : 1.0
        src_len = ratio == 1.0 ? sample.length : (sample.length / ratio).floor
        event_frame = (time * SAMPLE_RATE).round
        window = overlap_window(event_frame, src_len, chunk_start, chunk_frames)
        next unless window
        local_start, source_offset, count = window
        count.times do |i|
          value =
            if ratio == 1.0
              sample[source_offset + i] * velocity
            else
              src_pos = (source_offset + i) * ratio
              i0 = src_pos.floor
              frac = src_pos - i0
              s0 = sample[i0] || 0.0
              s1 = sample[i0 + 1] || s0
              (s0 + (s1 - s0) * frac) * velocity
            end
          left[local_start + i] += value * (0.5 - pan * 0.35)
          right[local_start + i] += value * (0.5 + pan * 0.35)
        end
      end
    end
  end
end

def gate_expr(hits, hold: 0.38, scale: 1.0)
  parts = hits.map do |hit|
    t, v = hit[0], hit[1]
    "between(t,#{t.round(4)},#{(t + hold).round(4)})*#{(v * scale).round(4)}"
  end
  parts.empty? ? "0" : parts.join("+")
end

def pad_gate_expr(pad_events)
  parts = pad_events.map do |(t, v, _chord, sustain)|
    "between(t,#{t.round(4)},#{(t + sustain).round(4)})*#{(v * 0.85).round(4)}"
  end
  parts.empty? ? "0.22" : "(#{parts.join('+')})"
end

def dilla_stem_paths
  paths = {}
  paths[:mids] = STEM_MIDS    if File.exist?(STEM_MIDS)
  paths[:highs] = STEM_HIGHS   if File.exist?(STEM_HIGHS)
  paths[:sub] = STEM_SUB     if File.exist?(STEM_SUB)
  paths[:center] = STEM_CENTER  if File.exist?(STEM_CENTER)
  paths
end

PROGRESSION_LOG_PATH = File.join(SCRATCH_DIR, "progressions_log.txt")
LEGACY_PROGRESSION_LOGS = [
  File.join(OUTPUT_DIR, ".dilla_progressions_log.txt"),
  File.join(SCRATCH_DIR, "dilla_progressions_log.txt"),
].freeze

# Older versions wrote the log as a dotfile into the invoking directory —
# fold any of those into the canonical log the first time we write, so the
# "nothing explored is lost" guarantee survives the path change.
def migrate_legacy_progression_logs!
  LEGACY_PROGRESSION_LOGS.each do |legacy|
    next unless File.exist?(legacy)
    File.open(PROGRESSION_LOG_PATH, "a") { |f| f.write(File.read(legacy)) }
    FileUtils.rm_f(legacy)
    puts "migrated legacy progression log #{legacy} -> #{PROGRESSION_LOG_PATH}"
  end
end

# Every chord walked during a render, appended so nothing explored is lost —
# generated progressions especially never repeat, so this is the only
# record of what actually played if it's worth turning into a real song.
def log_progression!(track, bpm, pads, phases = nil)
  return if pads.empty?

  FileUtils.mkdir_p(SCRATCH_DIR)
  migrate_legacy_progression_logs!
  lines = pads.each_with_index.map do |chord, i|
    notes = chord[:hz].map { |hz| nearest_note(hz) }.join(" ")
    hz = chord[:hz].map { |h| h.round(1) }.join(", ")
    phase = phases&.[](i)
    prefix = phase ? "[#{phase}] " : ""
    "  #{prefix}#{chord[:name]}: #{notes}  (#{hz} Hz)"
  end
  File.open(PROGRESSION_LOG_PATH, "a") do |f|
    # Tagged (fugue) only when there are fugue phases. render_dilla calls this
    # for every render, not just fugues, so the tag was hardcoded onto all of
    # them -- all 133 entries in the log say (fugue), including batucada and
    # afrobeats_pocket. A label that is always printed identifies nothing.
    f.puts "=== #{Time.now.iso8601} — TRACK=#{track} BPM=#{bpm.round(1)}#{phases ? ' (fugue)' : ''} ==="
    f.puts lines
    f.puts
  end
rescue StandardError => e
  warn "progression log write failed: #{e.message}"
end

# Full Jay Dee render: sample drums + stem chops, Dilla Time scheduling.
SELF_SAMPLE_CACHE = File.join(SCRATCH_DIR, "self_sample.wav")

# "Collapse over accretion": before this render's predecessor is deleted,
# grab a short slice of it and cache it — the next render can layer that
# slice back in as texture, a real feedback loop across renders rather
# than each one starting from nothing.
def cache_self_sample!(destination)
  return if ENV.fetch("SELF_SAMPLE", "1") == "0"
  return unless File.exist?(destination) && tool_available?("ffprobe")
  # Not media_metadata: it calls abort() on failure, which would kill the
  # whole render for what's meant to be a best-effort optional step.
  output, _err, status = capture("ffprobe", "-v", "error", "-show_entries", "format=duration", "-of",
                                  "default=noprint_wrappers=1:nokey=1", destination)
  return unless status.success?
  duration = output.to_f
  return if duration < 2.0
  offset = (rand * [duration - 1.5, 0.1].max).round(2)
  FileUtils.mkdir_p(SCRATCH_DIR)
  sh! "ffmpeg", "-y", "-i", destination, "-ss", offset.to_s, "-t", "1.2",
      "-ac", "2", "-ar", SAMPLE_RATE.to_s, "-c:a", "pcm_s16le", SELF_SAMPLE_CACHE
rescue StandardError
  FileUtils.rm_f(SELF_SAMPLE_CACHE)
end

# --------------------------------------------------------------- MIDI Bag
#
# The lead's pitches laid onto the kit's onsets, as MidiDevices::Bag defines it.
#
# Off by default and it must be: this changes WHEN every lead note sounds, which
# is the most audible thing about a part. It is also the device most likely to be
# wanted per-track rather than globally -- a bagged lead is a strong effect, and
# the same setting that makes one beat sound played makes another sound broken.
#
# The timing source is the kit's actual grid rather than an invented one: a
# sixteenth grid with the fourth sixteenth of each beat thinned on even steps,
# accented on the quarters. That is what makes the bagged part inherit the beat's
# pocket instead of running as a machine.
def midi_bag_lead_events(events, cfg, n_bars)
  return events unless ENV["MIDI_BAG"] == "1"
  return events if events.nil? || events.empty?

  bar_p = (60.0 / cfg[:bpm].to_f) * 4.0
  return events unless bar_p.positive? && n_bars.to_i.positive?

  timing = midi_bag_grid(bar_p, n_bars)
  return events if timing.empty?

  chord_at = if ENV.fetch("MIDI_BAG_FIT", "1") != "0"
               chords = dilla_progression(cfg[:progression])
               ->(t) { chords[((t / bar_p).floor) % chords.length] } if chords&.any?
             end
  out = MidiDevices::Bag.apply(
    pitches: events, timing:,
    order: ENV.fetch("MIDI_BAG_ORDER", "cycle").to_sym,
    velocity_from: ENV.fetch("MIDI_BAG_VELOCITY", "timing").to_sym,
    rests: ENV.fetch("MIDI_BAG_RESTS", "0.25").to_f,
    seed: seed_for("midibag"),
    chord_at:
  )
  return events if out.empty?

  dmesg("midi bag: #{events.length} lead pitch(es) on #{out.length} kit onset(s)",
        unit: "harm0", parent: "dilla0")
  out
end

# The kit's onsets as timing slots, with its accents.
def midi_bag_grid(bar_p, n_bars)
  step = bar_p / 16.0
  (0...(n_bars.to_i * 16)).filter_map do |i|
    beat = i % 16
    next if [3, 7, 11, 15].include?(beat) && i.even?

    [i * step, [0, 4, 8, 12].include?(beat) ? 0.9 : 0.55, { hz: [110.0] }, step * 0.85]
  end
end

# --------------------------------------------------------------- Hocket
#
# One line, distributed across the pad voices the engine already has.
#
# HOCKET=n splits a lead across n voices; the caller renders each through a
# different patch, so a line played on one instrument becomes a line played BY an
# ensemble. Returns the voices as an array, or a single-element array when off --
# so a caller can treat the two cases the same and the off path stays exactly
# what it was.
def hocket_lead_voices(events)
  voices = ENV.fetch("HOCKET", "1").to_i
  return [events] unless voices > 1 && events&.any?

  split = MidiDevices::Hocket.split(
    events, voices:,
    mode: ENV.fetch("HOCKET_MODE", "pendulum").to_sym,
    hold: ENV.fetch("HOCKET_HOLD", "1").to_i,
    seed: seed_for("hocket")
  )
  dmesg("hocket: #{events.length} note(s) across #{voices} voice(s) " \
        "(#{split.map(&:length).join('/')})", unit: "harm0", parent: "dilla0")
  split
end

# The harmony lead, played by an ensemble instead of an instrument.
#
# HOCKET=1 (the default) renders exactly what it always rendered, through the one
# call it always used. Above 1 the line is split by MidiDevices::Hocket and each
# voice goes through a DIFFERENT electric-piano program from EP_GM_PROGRAMS, then
# the voices are summed.
#
# Different programs is the whole point and not a flourish: hocketing a line
# across four copies of one patch is a line with gaps in it, which sounds like a
# fault. Across four timbres it is an ensemble handing a melody between players,
# which is what the technique is for and what it is named after.
#
# amix with normalize=0, for the reason audio_graph.rb gives -- the default
# rescales by input count, so a four-voice hocket would arrive a quarter the
# level of the one-voice line it replaces and read as "the leads got quiet".
# 1/sqrt(n) instead: the voices play at different times and sum as power.
def render_hocket_lead!(path, events, duration)
  voices = hocket_lead_voices(events)
  return voice_stack_lead!(path, events, duration) if voices.one?

  rendered = voices.each_with_index.filter_map do |voice, i|
    next if voice.empty?

    part = "#{path}.hocket#{i}.wav"
    voice_stack_lead!(part, voice, duration) ||
      render_lead_via_fluidsynth(part, voice, duration, scale_arp: true,
                                                        program_override: EP_GM_PROGRAMS[i % EP_GM_PROGRAMS.length])
    File.file?(part) ? part : nil
  end
  return nil if rendered.empty?
  return (FileUtils.mv(rendered.first, path) && path) if rendered.one?

  inputs = rendered.flat_map { |f| ["-i", f] }
  gain = (1.0 / Math.sqrt(rendered.length)).round(4)
  sh! "ffmpeg", "-y", *inputs, "-filter_complex",
      "#{(0...rendered.length).map { |i| "[#{i}:a]" }.join}" \
      "amix=inputs=#{rendered.length}:duration=longest:normalize=0,volume=#{gain}[out]",
      "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-c:a", "pcm_s16le", path
  rendered.each { |f| FileUtils.rm_f(f) } # scan: intentional — removes only the temp files this method rendered
  File.file?(path) ? path : nil # gated per voice at the leaf, not again on the mix
end

# LPG=1 — the lead through a Buchla-style low-pass gate.
#
# Wired to the lead and not to a bus because an LPG is a NOTE device: it works on
# something struck, where each event decays, and its whole character is that the
# decay darkens. On a sustained pad it would be a dull filter, and on a full
# mix it would gate the whole arrangement against the kick.
#
# Measured on a decaying pluck: over the decay the 4-12 kHz band falls 17.5 dB
# further than the 200-800 Hz band does, against 0.4 dB for the same note without
# it. That gap is the device.
#
# Off by default. It changes every note of the part it touches.
def low_pass_gate_lead!(path)
  return path unless ENV["LPG"] == "1"

  gated = "#{path}.lpg.wav"
  out = LowPassGate.build!(src: path, dest: gated, rate: SAMPLE_RATE,
                           blend: ENV.fetch("LPG_BLEND", "1.0").to_f,
                           depth: ENV.fetch("LPG_DEPTH", "1.0").to_f,
                           decay_ms: ENV.fetch("LPG_DECAY_MS", "220").to_f,
                           droop: ENV.fetch("LPG_DROOP", "2.4").to_f)
  return path unless out && File.file?(out)

  # Logged because it was silent, and a silent device reached from four paths is
  # one nobody can tell fired -- it was wired to one of those paths for months.
  dmesg("lpg: lead gated (blend #{ENV.fetch(%q(LPG_BLEND), %q(1.0))}, decay #{ENV.fetch(%q(LPG_DECAY_MS), %q(220))}ms)")
  FileUtils.mv(out, path)
  dmesg("low-pass gate: the lead darkens as it decays", unit: "harm0", parent: "dilla0")
  path
end

# VOICE_STACK=n — the lead played by n voices at once.
#
# Not Hocket, and the difference is the point. Hocket splits notes BETWEEN
# voices, so each plays part of the line and the ear reassembles it. This has
# every voice play ALL of it, differing in register, tuning and timbre -- an
# ensemble playing together rather than passing a melody around. A section, not
# a hocket.
#
# The two compose: HOCKET=3 VOICE_STACK=2 gives three voices each doubled.
#
# Off by default. It multiplies the lead's density, which is the loudest
# structural change available to this part.
# Two voices by default, not one.
#
# This returned early at VOICE_STACK=1, so the P_4L-shaped stack -- the
# ringtone.tools idea this file is built on -- never ran in a normal render. The
# operator asked for those leads "on top in the same scale and harmonies", and
# they were switched off.
#
# Two rather than more, and it is the count that makes it safe. SEMITONE_PLAN's
# fifths row is [0, 12, 7, 19, -12, 24, 7], so a two-voice stack takes [0, 12]:
# the added voice is exactly an octave up. An octave is in key against any chord
# in any scale, so "on top" is literal and the harmony cannot be wrong. Three
# voices would add the +7 fifth, which is diatonic against most degrees and a
# tritone against the seventh -- a musical decision rather than a safe default.
#
# VOICE_STACK=1 restores the single voice.
def voice_stack_lead!(path, events, duration)
  voices = ENV.fetch("VOICE_STACK", "2").to_i
  return render_lead_via_fluidsynth(path, events, duration, scale_arp: true) unless voices > 1

  plan = VoiceStack.plan(
    voices:,
    macro: ENV.fetch("VOICE_STACK_MACRO", "0.5").to_f,
    variation: ENV.fetch("VOICE_STACK_VARIATION", "0.25").to_f,
    detune_mode: ENV.fetch("VOICE_STACK_DETUNE", "fifths").to_sym,
    drift: ENV.fetch("VOICE_STACK_DRIFT", "9").to_f,
    key_track: ENV.fetch("VOICE_STACK_KEYTRACK", "0.5").to_f,
    seed: seed_for("voicestack")
  )
  rendered = plan.filter_map do |voice|
    part = "#{path}.vs#{voice.index}.wav"
    # The macro position picks a MODEL, and the model picks a patch out of the
    # 212 this engine already has. One control, several characters -- the P_4L
    # idea over dillas own catalogue rather than beside it.
    model = VoiceStack.model_for(voice.macro)
    patch = VoiceStack.patch_for(model, SYNTH_PATCH_CATALOG, seed: seed_for("vsmodel#{voice.index}"))
    render_lead_via_fluidsynth(part, VoiceStack.transpose(events, voice), duration,
                               scale_arp: true,
                               program_override: patch ? patch[:program] : EP_GM_PROGRAMS[voice.index % EP_GM_PROGRAMS.length])
    File.file?(part) ? part : nil
  end
  return nil if rendered.empty?
  return (FileUtils.mv(rendered.first, path) && path) if rendered.one?

  # Same power-sum reasoning as the hocket: detuned voices are uncorrelated, so
  # 1/n would leave the stack far quieter than the single voice it replaces.
  inputs = rendered.flat_map { |f| ["-i", f] }
  sh! "ffmpeg", "-y", *inputs, "-filter_complex",
      "#{(0...rendered.length).map { |i| "[#{i}:a]" }.join}" \
      "amix=inputs=#{rendered.length}:duration=longest:normalize=0," \
      "volume=#{(1.0 / Math.sqrt(rendered.length)).round(4)}[out]",
      "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-c:a", "pcm_s16le", path
  # VOICE_STACK_STEMS=1 keeps each voice as its own file instead of deleting it.
  #
  # P_4L taps every voice before its filter so the voices can be processed
  # separately; this engine renders each voice to a file and then sums, so the
  # equivalent is not throwing them away. What a modular does with a
  # patch cable, a renderer does with a path.
  if ENV["VOICE_STACK_STEMS"] == "1"
    dmesg("voice stack: kept #{rendered.length} voice stem(s) beside #{File.basename(path)}",
          unit: "harm0", parent: "dilla0")
  else
    rendered.each { |f| FileUtils.rm_f(f) } # scan: intentional — removes only the temp files this method rendered
  end
  dmesg("voice stack: #{plan.length} voices, #{ENV.fetch('VOICE_STACK_DETUNE', 'fifths')}, " \
        "models #{plan.map { |v| VoiceStack.model_for(v.macro) }.join('/')}",
        unit: "harm0", parent: "dilla0")
  File.file?(path) ? path : nil
end

# --------------------------------------------------------------------------
# engine part: render_dilla
# --------------------------------------------------------------------------
#
# The Dilla renderer.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Which bus each channel belongs to, when there are buses at all.
#
# Off by default and it has to be. A bus is an extra amix, and while a bus at
# gain 1.0 with its channels' weights carried through is the same sum
# arithmetically, it is not the same graph as text -- and the parity proof for
# moving this renderer onto the spine is textual. So the default is what it has
# always been: every channel straight to master, one amix, no buses.
#
# DILLA_MIX_BUSES=1 groups them. The grouping is not cosmetic: a bus is the only
# place a filter can sit that affects a GROUP of channels, which is what makes
# it somewhere to hang a modulated filter. Modulating six channels separately is
# six routes and six instances; modulating the bus they share is one.
DILLA_MIX_BUS_MAP = {
  drums_c: :kit, drums: :kit, sc_mix: :kit, bedcarved: :kit, loopbed: :kit, bedbridged: :kit,
  harm: :harmonic, padbed: :harmonic, analogpad: :harmonic, chops: :harmonic,
  bassbus: :low, bassducked: :low, subbed: :low,
  vinyl: :texture, rumble: :texture, selfsample: :texture, wavmap: :texture,
}.freeze

def dilla_mix_buses? = ENV["DILLA_MIX_BUSES"] == "1"

# A bus chain is empty unless something asks for one. An empty-chained bus still
# sums, so the grouping is real even before anything is patched onto it -- which
# is the difference between a bus and a comment saying these belong together.
#
# DILLA_BUS_<NAME> puts a literal filter chain on one. BUS_MOD=<name> puts a
# MOVING one there, which is the reason buses were added at all: a modulated
# filter on a bus reaches every channel in it, and modulating six channels
# separately would be six routes and six filter instances that then have to agree.
def dilla_mix_bus_chain(name)
  raw = ENV["DILLA_BUS_#{name.to_s.upcase}"].to_s
  literal = raw.empty? ? [] : [raw]
  mod = dilla_bus_patch(name, @render_duration_sec.to_f) || dilla_bus_modulation(name)
  mod ? mod + literal : literal
end

# The modulated filter for a bus, as [asendcmd, named-filter] ready to prefix.
#
# One source, one destination, deliberately. A matrix can carry thirty-two routes
# and the useful thing here is the smallest complete demonstration that a
# parameter can move over a render: an LFO on a lowpass across a group of
# channels. Anything richer is worth building as a device rather than as four
# more environment variables.
#
# BUS_MOD names which bus (kit, harmonic, low, texture). Nothing moves unless it
# is set, and DILLA_MIX_BUSES=1 is required for buses to exist at all.
def dilla_bus_modulation(name)
  return nil unless ENV["BUS_MOD"].to_s == name.to_s
  return nil unless (duration = @render_duration_sec.to_f).positive?

  matrix = DillaModulation::Matrix.new
  # BUS_MOD_SYNC takes a musical division -- 1/4, 1/8T, 4bar -- and wins over
  # BUS_MOD_HZ when set. A rate in hertz does not move with the tempo, so on a
  # rotation that changes BPM per track it drifts against everything else.
  begin
    rate_hz = if (sync = ENV["BUS_MOD_SYNC"])
                DillaModulation.sync_hz(sync, @render_bpm || 88.0)
              else
                ENV.fetch("BUS_MOD_HZ", "0.25").to_f
              end
  rescue ArgumentError => e
    warn "bus modulation: #{e.message}"
    return nil
  end
  matrix.lfo(:bus, rate_hz:,
                   family: ENV.fetch("BUS_MOD_FAMILY", "curved").to_sym,
                   morph: ENV.fetch("BUS_MOD_MORPH", "0.33").to_f)
  filter = ENV.fetch("BUS_MOD_FILTER", "lowpass")
  param = ENV.fetch("BUS_MOD_PARAM", "frequency")
  begin
    matrix.route(:bus, instance: "bus#{name}", filter:, param:,
                       base: ENV["BUS_MOD_BASE"]&.to_f,
                       depth: ENV.fetch("BUS_MOD_DEPTH", "1.0").to_f,
                       mode: ENV.fetch("BUS_MOD_MODE", "modulate").to_sym)
  rescue ArgumentError => e
    # A route to a parameter ffmpeg will not accept at runtime is refused by the
    # matrix rather than emitted. Warn and carry on unmodulated: a render should
    # not die because a modulation target was misspelled.
    warn "bus modulation: #{e.message}"
    return nil
  end
  emit_bus_matrix(matrix, name, duration)
end

# BUS_PATCH=random — a whole patch on a bus instead of one LFO.
#
# P_4Ls most-used control is the one that patches itself, and the reason it gets
# used is that its output is worth hearing more often than not. PatchBay.random
# is built for that: one source per destination, depths biased low, and at least
# one inverted so the routes do not all rise together.
#
# BUS_PATCH_SEED pins it. A random patch nobody can get back is a take nobody can
# repeat, which is the fault provenance.rb exists to prevent.
def dilla_bus_patch(name, duration)
  return nil unless ENV["BUS_PATCH"].to_s == "random"

  matrix, patch = DillaModulation::PatchBay.random(
    bpm: @render_bpm || 88.0,
    routes: ENV.fetch("BUS_PATCH_ROUTES", "4").to_i,
    seed: ENV.fetch("BUS_PATCH_SEED", seed_for("buspatch")).to_i
  )
  dmesg("bus patch: " + patch.map { |src, ds| "#{src}->#{ds.keys.join("+")}" }.join(" "),
        unit: "harm0", parent: "dilla0")
  emit_bus_matrix(matrix, name, duration)
end

# A matrix as [asendcmd, filter, filter, ...] ready to prefix onto a bus chain.
#
# Every route needs its own named filter instance in the graph, and the name has
# to be the one the command file writes -- which is why both come from the same
# matrix rather than being spelled twice.
def emit_bus_matrix(matrix, name, duration)
  path = File.join(SCRATCH_DIR, "busmod_#{name}.cmds")
  FileUtils.mkdir_p(SCRATCH_DIR)
  prefix = DillaModulation.prefix_for(matrix, path:, duration:)
  return nil unless prefix

  matrix.describe.each { |line| dmesg("bus modulation: #{line}", unit: "harm0", parent: "dilla0") }
  [prefix] + matrix.routes.map do |route|
    "#{matrix.instance_name(route)}=#{route.param}=#{matrix.initial(route)}"
  end
end

def dilla_mix_graph(mix_labels, mix_weights)
  graph = AudioGraph.new
  buses = if dilla_mix_buses?
            mix_labels.filter_map { |l| DILLA_MIX_BUS_MAP[l.delete("[]").to_sym] }.uniq
          else
            []
          end
  # Buses first, so a bus's position in the master amix follows its declaration
  # rather than the position of whichever channel happened to mention it first.
  buses.each { |b| graph.bus(b, chain: dilla_mix_bus_chain(b)) }
  mix_labels.each_with_index do |label, i|
    name = label.delete("[]")
    bus = buses.empty? ? :master : (DILLA_MIX_BUS_MAP[name.to_sym] || :master)
    graph.channel(name, input: label, gain: mix_weights[i], bus:)
  end
  graph
end

# COPY_MACHINE=n — the sampled bed, played n times at once.
#
# ringtone.tools' Copy Machine, on the one source in a dilla render where it has
# something to say: the record. Copies at different speeds drift apart in time as
# well as pitch, so a four-bar loop stops being four bars and becomes a cloud of
# itself -- which is a texture this engine could not make. organic_vary already
# does multi-speed passes and does them SEQUENTIALLY, one at a time; this is the
# same idea with the passes sounding together.
#
# Applied after flip_loop_entry, so a flipped bed clouds the flip rather than the
# record it came from -- the flip is the musical decision and this is a texture
# over it.
#
# Off by default. It replaces the bed, which is the loudest sampled thing in a
# render, and turning it on for every take on nobody's say-so is not a choice a
# wiring change gets to make. COPY_MACHINE_FAMILY picks harmonic (default),
# chromatic or spray; the rest of CopyMachine's controls carry their own defaults.
def copy_machine_loop_entry(loop_entry, duration)
  copies = ENV.fetch("COPY_MACHINE", "0").to_i
  return loop_entry unless copies > 1 && loop_entry && File.file?(loop_entry[:path].to_s)

  dest = dilla_render_tmp("copymachine")
  out = CopyMachine.build!(
    src: loop_entry[:path], dest:,
    copies:,
    family: ENV.fetch("COPY_MACHINE_FAMILY", "harmonic").to_sym,
    reverse: ENV.fetch("COPY_MACHINE_REVERSE", "0.25").to_f,
    width: ENV.fetch("COPY_MACHINE_WIDTH", "0.8").to_f,
    drift: ENV.fetch("COPY_MACHINE_DRIFT", "220").to_f,
    seed: seed_for("copymachine"),
    duration:, rate: SAMPLE_RATE
  )
  return loop_entry unless out && File.file?(out)

  dmesg("copy machine: #{copies} copies of #{File.basename(loop_entry[:path])} at once",
        unit: "harm0", parent: "dilla0")
  # The bed now covers the whole duration by construction, so the caller must not
  # -stream_loop it -- the same reason organic_vary's output is fed straight in.
  loop_entry.merge(path: out, copy_machined: true)
end

def render_dilla(destination = File.join(OUTPUT_DIR, "beat.mp3"), bars_count = nil, keep_stems: false)
  require_tools! "ffmpeg"
  cleanup_render_scratch!
  pick_render_seed!
  remove_instance_variable(:@resolve_form_map) if instance_variable_defined?(:@resolve_form_map)
  @chord_motif_cache = {}
  ensure_drum_kit!
  FileUtils.mkdir_p(File.dirname(destination))
  cache_self_sample!(destination)
  # Set the previous take aside instead of deleting it.
  #
  # This line must not be FileUtils.rm_f(destination), which destroys the old
  # render before a single note of the new one exists. Every path out of this
  # method that is not "wrote #{destination}" therefore lost the take: a raise,
  # a timeout, a SIGTERM, ffmpeg refusing a filter, the operator pressing ^C
  # thirty seconds in. The window is not small — a 48-bar render is minutes long
  # and the file is gone for all of it.
  #
  # These renders are not reproducible. The seed rotates, the performer and
  # generation are chosen per run, and the mp3 is the only copy — the tree
  # ignores renders, so git has never held one. Two of the operator's tracks
  # went missing mid-session and the cause was read as "another agent"; it was
  # this. It reproduced here exactly: vaular_remix.mp3 existed, a re-render was
  # started against the same path, that render died at 137s, and the finished
  # take was gone with nothing to replace it.
  #
  # cache_self_sample! above keeps 1.2 seconds of the old file. That is a sample
  # source, not a backup, and it is the only thing that has ever survived this.
  previous_take = "#{destination}.prev" if File.file?(destination)
  FileUtils.mv(destination, previous_take) if previous_take
  cfg = dilla_resolve_config
  cfg = DillaSeeds.apply_to_cfg!(cfg)
  n_bars = bars_count || bars
  DillaRhythm.configure!(n_bars:, bpm: cfg[:bpm])
  @render_pad_attack_sec = (cfg[:sonic]&.dig("synth", "pad_attack_ms") || 72).to_f / 1000.0
  rel_ms = (cfg[:sonic]&.dig("synth", "pad_release_ms") || 1400).to_f
  @render_pad_release_decay = (1.0 / [rel_ms / 1000.0, 0.25].max).round(4)
  @render_pad_native_wave = DillaLofiMachine.native_wave_for_pad
  @render_pad_gain = (cfg[:sonic]&.dig("synth", "pad_volume_pct") || 40).to_f / 100.0
  composition_session!(n_bars:, track: cfg[:track].to_s)
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    # ENV/SWING is the style DNA (56). The donuts groove table is 61 and
    # used to overwrite it on every composition render.
    dna = ENV["SWING"].to_s
    cfg = cfg.merge(swing: dna.empty? ? @composition_session.groove_profile[:swing].to_f : dna.to_f)
  end
  pick_synth_patches!(cfg, bar: n_bars / 2, n_bars:)
  beat_p = 60.0 / cfg[:bpm]
  duration = (beat_p * 4.0 * n_bars).round(3)
  # Buses are built far below this point and need the length to size a command
  # file; the alternative is threading it through four call sites that do not
  # otherwise care about it.
  @render_duration_sec = duration
  @render_bpm = cfg[:bpm].to_f
  needed_chords = (n_bars.to_f / cfg[:chord_bars]).ceil + 1
  if GENERATED_STYLES.include?(cfg[:progression].to_sym) || cfg[:progression].to_sym == :generated
    ENV["GEN_LENGTH"] = needed_chords.to_s
  end
  pads = dilla_progression(cfg[:progression])
  if pads.length < 2
    fallback = curated_progression_pads(:maj7_minor_cycle) ||
               curated_progression_pads(cfg[:progression])
    if fallback&.length.to_i >= 2
      warn "progression collapsed to #{pads.length} chord(s) for #{cfg[:track]} — using #{fallback.length}-chord fallback"
      pads = fallback
    else
      abort "progression too short (#{pads.length} chords) for track=#{cfg[:track]} — check chord symbols"
    end
  end
  # Before arrangement, so every downstream voice -- pads, bass, leads, the
  # arrangement's own generated sections -- inherits the loop's key rather than
  # being transposed one at a time afterwards.
  # Anything laid over a sampled loop has to agree with it. Where the loop's key
  # can be read confidently the generated harmony is moved onto it; where it
  # cannot, the tonal layers are MUTED rather than guessed at, and the render is
  # the loop and the kit alone.
  #
  # The threshold is not decorative. Krumhansl fit across the loops here runs
  # 0.697 to 0.836 when the cut is musically sensible, and fell to 0.27 on a cut
  # taken from the wrong part of the same record. Transposing pads onto a 0.27
  # reading is not a smaller version of getting it right -- it is a confident
  # move in an arbitrary direction, and two tonal parts a semitone apart is the
  # one fault no mixing repairs. Silence is the better failure.
  loop_for_key = sample_loop_for(ENV["TRACK"])&.dig(:path)
  # A generated progression in one key over a sampled loop in another is two
  # pieces of music playing at once. HARMONIC_KEEP defaulted OFF, so that is what
  # every sample-backed render did: the loop in its key, the pads in whatever key
  # the progression table happened to hold. Presence of a bed is reason enough --
  # there is no case where you lay pads over a record and want a different key.
  keep_key = HARMONIC_KEEP || !loop_for_key.nil?

  # A record that already states its chords needs nothing added.
  #
  # The guard below mutes the tonal layers when it cannot READ the loop's key,
  # on the reasoning that guessing a progression against an unknown key is worse
  # than silence. That is the right rule for an illegible loop and the wrong
  # question for this one: semua_untuk_mu reads Eb major at fit 0.79 — perfectly
  # legible — and the guard therefore transposed the pads to match and played
  # them over a record whose first ten seconds are vocal chords. Legible is not
  # the same as needs accompanying.
  #
  # Declared per record in TRACK_SAMPLE_LOOPS_BUILTIN, because only the crate
  # knows which records are like this, and the other loops there want their
  # progressions. SAMPLE_HARMONY=0 overrides for a one-off render.
  #
  # SAMPLE_CARRIES_HARMONY=1 says the same thing for a loop the crate has never
  # heard of. That gap was invisible while every loop came from the crate, and
  # opened the moment one did not: a SAMPLE_LOOP=<path> render has no TRACK to
  # look up, so this test was always false and the pads came back over the top
  # of a choir — the exact fault the paragraph above describes, on the exact
  # record it names. Expressing it needed ten environment variables set by hand
  # (PAD_VOL, HARM_MIX_WEIGHT, and the eight tonal layers below), which is a
  # list nobody will get right twice.
  #
  # One fact about the sample, one knob.
  carries_own_harmony = sample_loop_for(ENV["TRACK"])&.dig(:carries_own_harmony) ||
                        ENV["SAMPLE_CARRIES_HARMONY"] == "1"
  if carries_own_harmony && ENV["SAMPLE_HARMONY"] != "0"
    dmesg("harmony: the record carries it — tonal layers muted", unit: "harm0", parent: "dilla0")
    # ANALOG_PAD_WEIGHT belongs in the first list and was not in it. The branch
    # logs "tonal layers muted" and then rendered `analog pad: warm_pad on real
    # oscillators` anyway — a pad voicing the progression, over a record that
    # states its own chords, which is the whole thing this branch exists to
    # prevent. It survived because it is weighted separately from PAD_VOL at
    # render_dilla:615 and the list was written against the other one.
    %w[PAD_VOL HARM_MIX_WEIGHT ANALOG_PAD_WEIGHT].each { |k| ENV[k] = "0" }
    %w[MELODIC_LEAD SCALE_LEAD LEAD_ARP HARMONY_LEAD PAD_LAYERS PAD_TEXTURE
       CHOIR_VOX LUSH_SYNTH].each { |k| ENV[k] = "0" }
    # `pads` is deliberately NOT cleared, and that is the difference between this
    # and the guard below.
    #
    # Emptying it raised NoMethodError in lead_arp.rb's chord_variation_rng —
    # `stable_hash(chord[:name].to_s)` on a nil chord — because dilla_schedule
    # still walks the progression for timing whether or not anything voices it.
    # The guard below does `pads = []` too, so it carries the same crash; it has
    # never fired, because it only triggers on a loop whose key cannot be
    # read and every loop in the crate reads cleanly. A muted layer and an absent
    # progression are not the same thing: the chords still shape the schedule,
    # nothing renders them.
  end

  if loop_for_key && !pads.empty? && HARMONIC_GUARD
    key = sample_key(loop_for_key)
    fit = key ? key[2] : 0.0
    label = key ? "#{PITCH_CLASSES[key[0]]} #{key[1]}" : "unreadable"
    if fit < HARMONIC_MUTE_MIN
      warn "harmonic guard: loop key is #{label} at fit #{fit.round(2)}, below " \
           "#{HARMONIC_MUTE_MIN} — muting tonal layers rather than guessing. " \
           "Pin PROGRESSION and set HARMONIC_GUARD=0 to override."
      %w[PAD_VOL HARM_MIX_WEIGHT].each { |k| ENV[k] = "0" }
      %w[MELODIC_LEAD SCALE_LEAD LEAD_ARP HARMONY_LEAD PAD_LAYERS PAD_TEXTURE
         CHOIR_VOX].each { |k| ENV[k] = "0" }
      # Keep the progression for schedule timing. Emptying pads used to crash
      # lead_arp on chord[:name] of nil. Volumes already mute the tonal layers.
    elsif fit < HARMONIC_GUARD_MIN
      # The middle tier: the root is legible, the mode is not.
      #
      # Krumhansl reports a root and a mode together, but they are not equally
      # certain. The root comes from which pitch class carries the weight, which
      # a loop states plainly; the mode comes from where the THIRD sits, and a
      # horn line that never plays its third leaves that question open. Slot 04
      # read E major at 0.54 against a 0.55 threshold -- almost certainly E,
      # genuinely unsure whether major or minor.
      #
      # Muting the band over that is the wrong trade. So is picking a mode: the
      # third is exactly the note that clashes if the guess is wrong. Instead we
      # play chords that HAVE no third -- root, fifth, ninth. That voicing is
      # consonant against major and minor alike, because the note that
      # distinguishes them is not in it. Rock guitarists have leaned on this for
      # fifty years for the same reason.
      warn "harmonic guard: loop key is #{label} at fit #{fit.round(2)} — root is " \
           "readable, mode is not. Voicing without thirds so the pads sit under " \
           "either reading."
      pads = quintal_voicing(transpose_pads_to(pads, key[0]))
      ENV["MODE_UNCERTAIN"] = "1"
      # Leads pick their notes from the chord's scale, and every scale commits to
      # a third. Only the counter-line survives, restricted below to the tones
      # that both modes share.
      %w[SCALE_LEAD LEAD_ARP].each { |k| ENV[k] = "0" }
      # Already moved onto the loop's root just above; a second pass would
      # measure the transposed pads against the same target and shift by zero,
      # but it would also re-introduce the thirds this branch just removed.
      keep_key = false
    end
  end

  if (keep_key || HARMONIC_SHUFFLE) && !pads.empty?
    if keep_key && (loop_path = sample_loop_for(ENV["TRACK"])&.dig(:path))
      if (root_pc, mode, fit = sample_key(loop_path))
        was = hz_to_pitch_class(pads.first[:hz].min)
        pads = transpose_pads_to(pads, root_pc)
        puts "harmonic keep: loop reads #{PITCH_CLASSES[root_pc]} #{mode} (fit #{fit.round(2)}) — " \
             "pads #{PITCH_CLASSES[was]} → #{PITCH_CLASSES[root_pc]}"
      end
    end
    if HARMONIC_SHUFFLE
      before = pads.map { |c| c[:hz].max.round }
      pads = shuffle_pads_for_melody(pads)
      after = pads.map { |c| c[:hz].max.round }
      puts "harmonic shuffle: top voice #{before.join(' ')} → #{after.join(' ')}"
    end
  end

  fugue_phases = []
  chord_bar_lens = nil
  # Every arranger and pedal decision below reads these three, and two of them
  # read mutable ENV. Once each, up front: a log line that disagrees with the
  # branch it exists to explain is worse than no log line, and the same
  # progression must not be curated for the arranger and uncurated for the pedal.
  curated = curated_progression?(cfg)
  la_beat = la_beat_progression_enabled?
  soul_lock = soul_progression_locked?
  unless pads.empty?
    # Which arranger ran, and on what. A documented transcription asked for by
    # name rendered as D/E → Db/E → C/E → Bm/E → Bbm/E → Am/E -- parallel
    # triads planing down by semitone over an E pedal, which only
    # arrange_fugue/la_beat/camel produce, none of which should be reachable
    # with a curated progression and STREAM_SOUL+STREAM_LOCK set. Every input to
    # that decision (cfg[:progression], the three predicates) was correct when
    # driven directly, so the next render says which branch it actually took
    # instead of leaving it to be inferred from the chords.
    arranger = if camel_mode? && la_beat && !soul_lock
                 :camel
               elsif la_beat && !soul_lock
                 :la_beat
               elsif curated
                 :loop
               else
                 :fugue
               end
    dmesg("arrange #{arranger} progression=#{cfg[:progression]} track=#{cfg[:track]} " \
          "curated=#{curated} la_beat=#{la_beat} " \
          "soul_lock=#{soul_lock} chords=#{pads.length}→#{needed_chords}",
          unit: "harm0", parent: "dilla0")
    pads, fugue_phases, chord_bar_lens = case arranger
                                         when :camel
                                           arrange_camel_beat_progression(pads, needed_chords, cfg)
                                         when :la_beat
                                           arrange_la_beat_progression(pads, needed_chords, cfg)
                                         when :loop
                                           lp = (prog_rotation_enabled? &&
                                                 arrange_rotating_progressions(needed_chords, cfg)) ||
                                                arrange_loop_progression(pads, needed_chords, cfg)
                                           [lp[0], lp[1], nil]
                                         else
                                           fp = arrange_fugue_progression(pads, needed_chords, cfg)
                                           [fp[0], fp[1], nil]
                                         end
  end
  @render_chord_bar_lens = chord_bar_lens
  pedal_prob = curated ? 0.0 : DillaHarmony.pedal_probability(cfg)
  pedal_prob = 0.18 if pedal_prob.zero? && !curated
  pads = apply_pedal_point(pads, probability: pedal_prob, seed: stable_hash(cfg[:track])) unless pedal_prob.zero?
  pads, fugue_phases = if curated
                           DillaHarmony.beautify_curated_pipeline(pads, cfg, phases: fugue_phases)
                         else
                           DillaHarmony.beautify_pipeline(pads, cfg, phases: fugue_phases)
                         end
  @chord_phases = fugue_phases
  @progression_chords = pads
  DillaHarmony.remember_progression(pads)
  symbols = pads.map { |c| c[:name].to_s.sub(/_pedal\z/, "").sub(/_t\d+\z/, "") }
  @progression_insight = pads.length >= 2 ? DillaHarmony.progression_insight(pads) : nil
  @progression_insight ||= DillaMusicGems.progression_analysis(symbols) if defined?(DillaMusicGems)
  @render_chord_bars = cfg[:chord_bars]
  @render_phrase_bars = cfg[:phrase_bars]
  log_progression_phases!(cfg[:track], cfg[:bpm], pads, fugue_phases)
  bass_pads = nil
  if slash_bass_enabled?(cfg) && !pads.empty?
    bass_pads = slash_bass_pads_for(pads, cfg)
  # Both branches need the same emptiness check. Only the first had one, and the
  # harmonic guard above empties `pads` by design -- so a loop that read below
  # the fit threshold took this branch and died on nil[:hz]. That is the guard
  # crashing on its own escape hatch: it exists to render the loop and the kit
  # alone, and instead it lost the track.
  elsif !curated && !pads.empty? && Random.new(stable_hash(cfg[:track].to_s)).rand < 0.1
    bass_pads = voice_lead_chords(generate_progression(root_hz: pads.first[:hz].min * 0.5, mode: :minor,
                                                         length: pads.length))
  end
  events = dilla_schedule(
    n_bars, beat_p, pads,
    chord_bars: cfg[:chord_bars], phrase_bars: cfg[:phrase_bars],
    swing: cfg[:swing], feel: cfg[:feel], timing: cfg[:timing], quintuplet: cfg[:quintuplet],
    bass_pads:, chord_phases: fugue_phases
  )
  @last_drum_events = events

  pick_external_drum_kit!
  ensure_external_kit_installed!
  kick_raw = load_mono_sample(drum_sample_path("kick.wav"))
  # RAW_KICK / comfort / custom oneshot: use the sample as-is (normalized).
  # layered_kick_sample was re-coating every kit with the same 808 synth so
  # "different drums" still sounded identical.
  kick_sample = if raw_kick_samples?
                  normalize_drum_sample(kick_raw, peak: 0.62)
                else
                  layered_kick_sample(kick_raw)
                end
  kit = extended_drum_kit(
    kick: kick_sample,
    snare: normalize_drum_sample(load_mono_sample(drum_sample_path("snare.wav")), peak: 0.72),
    ghost: normalize_drum_sample(load_mono_sample(drum_sample_path("ghost.wav")), peak: 0.45),
    hat: normalize_drum_sample(load_mono_sample(drum_sample_path("hat.wav")), peak: 0.48),
    open_hat: normalize_drum_sample(load_mono_sample(drum_sample_path("open_hat.wav")), peak: 0.5),
    bass_43: normalize_drum_sample(load_mono_sample(drum_sample_path("bass_43.wav")), peak: 0.55),
    shaker: synth_shaker_sample,
    cowbell: synth_cowbell_sample,
  )
  # Chop override off by default in comfort (DRUM_CHOPS=0); camel chops are
  # always the same Wonky slice and undo EXTERNAL_KIT character.
  apply_drum_chops_to_kit!(kit) if ENV.fetch("DRUM_CHOPS", comfort_mode? ? "0" : "1") != "0"
  unless dilla_pocket_drums_enabled?
    bar_p = beat_p * 4.0
  else
    # Opt-in only — poly + constant 8th shaker + cowbell turned the pocket into
    # a kitchen-sink loop. Set ECLECTIC_PERC=1 for experimental clutter.
    if ENV.fetch("ECLECTIC_PERC", "0") == "1"
      poly_beat = (beat_p * 4.0) / 3.0
      events[:poly] = (0...(duration / poly_beat).floor).map do |i|
        t = (i * poly_beat).round(6)
        [t, (0.16 + 0.07 * Math.sin(i * 1.7)).clamp(0.08, 0.3), :ghost]
      end
      step_p8 = beat_p / 2.0
      events[:shaker] = (0...(duration / step_p8).floor).map do |i|
        t = (i * step_p8).round(6)
        [t, dilla_velocity(0.55, i / 8, i % 8, spread: 0.15)]
      end
      cowbell_rng = Random.new((stable_hash(cfg[:track].to_s) % 100_000) + 41)
      events[:cowbell] = (0...(duration / beat_p).floor).filter_map do |i|
        next unless cowbell_rng.rand < 0.07
        t = (i * beat_p + cowbell_rng.rand(beat_p * 0.6)).round(6)
        [t, dilla_velocity(0.3, i, 0, spread: 0.1)]
      end
    end
    bar_p = beat_p * 4.0
    schedule_eclectic_percussion!(events, duration, beat_p, bar_p, cfg, n_bars) if ENV.fetch("ECLECTIC_PERC", "0") == "1"
  end

  drum_tmp = dilla_render_tmp("drums")
  harmonic_tmp = dilla_render_tmp("harmonic")
  render_sample_bus_wav(drum_tmp, events, duration, kit, drum_bus_mapping)
  drum_field_layer!(drum_tmp, duration:)
    console_strip!(drum_tmp, seed: 11)
  if wonky_drum_overlay_enabled?
    wonky_sub_tmp = dilla_render_tmp("wonky_sub")
    wonky_top_tmp = dilla_render_tmp("wonky_top")
    begin
      render_sample_bus_wav(wonky_sub_tmp, events, duration, kit, wonky_sub_bus_mapping)
      render_sample_bus_wav(wonky_top_tmp, events, duration, kit, wonky_top_bus_mapping)
      merge_wonky_dual_bus!(drum_tmp, wonky_sub_tmp, wonky_top_tmp)
    ensure
      FileUtils.rm_f(wonky_sub_tmp)
      FileUtils.rm_f(wonky_top_tmp)
      FileUtils.rm_f("#{drum_tmp}.merged.#{Process.pid}.wav")
    end
  end
  # Peak lift only — full loudnorm on the drum bus killed punch and made kicks
  # sound flat/wrong. Comfort / DRUM_PEAK_LIFT_DB=0 skips the old always-hot lift
  # that made every mix's drums equally loud regardless of bus fader.
  if File.file?(drum_tmp)
    peak_db = ENV.fetch("DRUM_PEAK_DB", wonky_primary_drums? ? "-1.0" : "-3.0").to_f
    lift_db = if ENV["DRUM_PEAK_LIFT_DB"] && !ENV["DRUM_PEAK_LIFT_DB"].empty?
                ENV["DRUM_PEAK_LIFT_DB"].to_f
              elsif comfort_mode?
                0.0
              elsif wonky_primary_drums?
                5.5
              else
                3.5
              end
    normed = "#{drum_tmp}.norm.wav"
    af = if lift_db.abs < 0.05
           "alimiter=limit=#{(10**(peak_db / 20.0)).round(4)}:level_out=0.92:attack=1:release=50"
         else
           "volume=#{lift_db}dB,alimiter=limit=#{(10**(peak_db / 20.0)).round(4)}:level_out=0.97:attack=1:release=50"
         end
    sh! "ffmpeg", "-y", "-i", drum_tmp, "-af", af, "-c:a", "pcm_s16le", normed
    FileUtils.mv(normed, drum_tmp) if File.file?(normed)
  end

  chop_gate = gate_expr(events[:chop], hold: 0.32, scale: 0.95)
  pad_gate = pad_gate_expr(events[:pad])
  stems = dilla_stem_paths
  stem_tempo = (cfg[:bpm] / 90.0).round(4)
  pan_hz = (cfg[:bpm] / 15.0).round(3)
  use_stem_harmony = !stems.empty?
  bass_bus_tmp = nil
  bass_bus_idx = nil
  bass_own_bus = !use_stem_harmony && ENV.fetch("BASS_OWN_BUS", "1") != "0" && events[:bass]&.any?
  unless use_stem_harmony
    # Bass is rendered on its own so it can bypass the harmonic bus high-pass,
    # which sits above its fundamental. Harmonic gets an empty bass list so the
    # layer is not counted twice.
    render_harmonic_wav(harmonic_tmp, events[:pad], events[:chop],
                        bass_own_bus ? [] : events[:bass], duration,
                        melody_events: events[:melody], cfg:, dfam_events: events[:dfam])
    # Pads and chops only. The bass bus is rendered separately below and is
    # deliberately left out: swelling the low end in and out is heard as an
    # unsteady mix rather than as playing.
    organic_breathe!(harmonic_tmp, bar_sec: (60.0 / cfg[:bpm]) * 4.0)
    console_strip!(harmonic_tmp, seed: 31)
# After the breath, before the mix: the loop shapes the pads while they
# are still a separate bus and can be operated on alone.
sample_drives_pads!(harmonic_tmp, sample_loop_for(ENV["TRACK"])&.dig(:path),
                    duration:)
    if bass_own_bus
      bass_bus_tmp = dilla_render_tmp("bassbus")
      render_harmonic_wav(bass_bus_tmp, [], [], events[:bass], duration, cfg:, pad_post: false)
      bass_own_bus = File.file?(bass_bus_tmp) && File.size(bass_bus_tmp) > 1_000
    end
  end

  command = ["ffmpeg", "-y", "-i", drum_tmp]
  idx = 1
  unless use_stem_harmony
    command += ["-i", harmonic_tmp]
    idx += 1
  end
  if bass_own_bus
    command += ["-i", bass_bus_tmp]
    bass_bus_idx = idx
    idx += 1
  end
  # The analogue pad, rendered before the graph is built so it can be an input
  # like any other file. Pure Ruby, so it costs about a second.
  analog_pad = analog_pad_file(pads, cfg, n_bars, beat_p)
  analog_idx = nil
  if analog_pad && File.file?(analog_pad)
    command += ["-i", analog_pad]
    analog_idx = idx
    idx += 1
  end
  # A picture, read as an oscillator. Same treatment as the analog pad: rendered
  # to a file first so it is an input like any other and needs no special case
  # anywhere downstream.
  wav_map_file = wav_map_layer!(cfg, duration)
  wav_map_idx = nil
  if wav_map_file && File.file?(wav_map_file)
    command += ["-i", wav_map_file]
    wav_map_idx = idx
    idx += 1
  end
  loop_entry = sample_loop_for(cfg[:track])
  # The flip. Cuts the record into pieces and plays a new line out of them,
  # against this track's own chords, instead of repeating the record. What comes
  # back is an ordinary audio file already at the render's tempo, so everything
  # downstream -- the bridges, the drum carving, the mix weight -- treats it
  # exactly as it treated the loop and needs no special case.
  #
  # Falls back to looping when the record will not yield enough usable pieces.
  # A worse version of the track is better than no track.
  loop_entry = flip_loop_entry(loop_entry, cfg, pads, n_bars) if loop_entry
  loop_entry = copy_machine_loop_entry(loop_entry, duration) if loop_entry
  loop_idx = nil
  if loop_entry
    varied = nil
    if ORGANIC_VARY
      varied = organic_vary_loop!(loop_entry[:path], dilla_render_tmp("varyloop"),
                                  duration:)
    end
    if varied
      # Already covers the full duration with each pass differing, so it must
      # NOT be stream_looped -- that would repeat the varied bed identically and
      # put the sameness back at a longer period.
      command += ["-i", varied]
    elsif loop_entry[:copy_machined]
      # Same reason: the cloud was rendered to the full duration, and looping it
      # would stack a second period on top of the one the copies already make.
      command += ["-i", loop_entry[:path]]
    else
      command += ["-stream_loop", "-1", "-i", loop_entry[:path]]
    end
    loop_idx = idx
    idx += 1
  end
  stem_map = {}
  stems.each do |key, path|
    command += ["-stream_loop", "-1", "-i", path]
    stem_map[key] = idx
    idx += 1
  end
  self_sample_idx = nil
  # Previous-render feedback can re-inject full Get Dis Money / prior mix as a "sample".
  if File.exist?(SELF_SAMPLE_CACHE) && ENV.fetch("SELF_SAMPLE", "1") != "0"
    command += ["-stream_loop", "-1", "-i", SELF_SAMPLE_CACHE]
    self_sample_idx = idx
    idx += 1
  end
  ir_input_idx = nil
  unless ENV["CONV_REVERB"] == "0"
    ir_room = ENV["CONV_REVERB"]&.to_sym
    ir_room = :chamber if deep_render? && (!ir_room || !CONVOLUTION_ROOMS.key?(ir_room))
    ir_room ||= render_pick(CONVOLUTION_ROOMS.keys, "conv_room")
    ir_path = DillaMaster.club_ir_path || synth_impulse_response!(ir_room)
    command += ["-i", ir_path]
    ir_input_idx = idx
    idx += 1
  end
  ghost_n = events[:ghost]&.length || 0
  kick_n = events[:kick]&.length || 1
  vinyl_base = sonic_vinyl_level(cfg[:sonic])
  vinyl_amp = vinyl_base.positive? ? DillaMl.groove_synced_vinyl(ghost_n, kick_n, base: vinyl_base) : 0.0
  if vinyl_amp.positive?
    command += ["-f", "lavfi", "-i", "anoisesrc=color=pink:r=#{SAMPLE_RATE}:amplitude=#{vinyl_amp}:d=#{duration}:seed=#{noise_seed(13)}"]
  end
  turntable_rumble = vinyl_amp.positive? && sonitex_enabled? &&
                     TURNTABLE_RUMBLE_VARIANTS.include?(analog_resolve_variant(track: cfg[:track].to_s))
  command += ["-f", "lavfi", "-i", "anoisesrc=color=brown:r=#{SAMPLE_RATE}:amplitude=0.02:d=#{duration}:seed=#{noise_seed(14)}"] if turntable_rumble

  # Every attempt to fix chord audibility by tuning EQ/weights/sidechain
  # *within* the elaborate mix chain (NY parallel drum compression, a
  # sub-150Hz sidechain duck keyed off the harm bus, per-bus RMS-matched
  # boosts, loudnorm) failed in real listening even when measurements said
  # it should work — confirmed by a from-scratch minimal mix (plain per-bus
  # volume + amix + one limiter, no sidechain/compression stack at all)
  # that DID produce audible chords. That proves the elaborate chain itself
  # was the problem, not the balance numbers. This mirrors that minimal,
  # proven-working mix instead of layering another fix onto the old one.
  # SP-1200-style crunch (that machine IS drum-sampler heritage: 12-bit,
  # tape-saturated) directly on the drum bus, on top of whatever the
  # whole-mix Sonitex pass adds later — more analog grit specifically where
  # it was asked for, not spread thin across the entire mix.
  # Complementary EQ carving, not just level: drums get a shallow dip right
  # where pad-chord fundamentals sit (300-700Hz) so the harm bus doesn't
  # have to fight for that space; the harm bus (below) gets the matching
  # cut down where the kick/bass actually live. Genuine frequency-slotting,
  # not another gain adjustment.
  # Each bus gets its section envelope prefixed onto its own chain, so a layer
  # leaves and returns instead of playing flat from bar one to the end.
  filt = [apply_section_envelope(build_drum_bus_filter(cfg, cfg[:sonic], duration:), :drums, n_bars, beat_p * 4.0)]
  # The kit is sharpened and tapped for a key signal here, once, before anything
  # downstream decides what to do with it. Doing this inside the sidechain
  # branch tied both to a preset flag: a track with sidechain off got neither a
  # crisp kit nor a key to carve the sampled bed with, for no musical reason.
  drum_label = "[drums]"
  if ENV["DRUM_FORWARD"] != "0"
    # Three taps off the kit, not two. [dr_key] carves the sampled bed and
    # [dr_bass] moves the bass out of the kick's way; both are tied off below if
    # their consumer is absent.
    filt << "[drums]asplit=3[dr_raw][dr_key][dr_bass]"
    filt << "[dr_raw]#{drum_crisp_chain || 'anull'}[drums_c]"
    drum_label = "[drums_c]"
  end
  mix_labels = [drum_label]
  # Drums sat at 0.72 under a 0.90 sampled bed and a 1.15 bass -- the quietest
  # thing in a genre built on them. The carve above buys most of the clarity
  # back without level, so this is a nudge rather than a shove.
  mix_weights = [resolved_drum_mix_weight.to_s]
  intro_bars = cfg.fetch(:intro_bars, 4)
  harm_fade_start = (beat_p * 4.0 * [intro_bars, 2].min).round(2)
  harm_fade_dur = (beat_p * 4.0 * 1.25).round(2)
  unless use_stem_harmony
    # The harmony bus is the loudest single channel in a typical render (weight
    # 1.12-1.70 against the kit's 0.95) and until now the only channel of that
    # size with no section shape at all. Under the default table :harm is
    # declared flat at 1.0 everywhere, so this is a no-op and the mix is
    # unchanged; under SECTION_LAYERS=full it swells into the breakdowns.
    filt << apply_section_envelope(
      build_harm_bus_filter(1, duration, cfg, cfg[:sonic], harm_fade_start, harm_fade_dur, beat_p, n_bars),
      :harm, n_bars, beat_p * 4.0
    )
    if cfg[:sidechain]
      filt.concat(sidechain_filter_chain(cfg, drum_label:))
      mix_labels = ["[sc_mix]"]
      mix_weights = ["1.0"]
    else
      mix_labels << "[harm]"
      mix_weights << ENV.fetch("HARM_MIX_WEIGHT", deep_render? ? "1.70" : "1.52").to_s
    end
  end

  # Bass joins the master mix directly, alongside drums, never through the harm
  # bus. Added after the sidechain branch above deliberately: when sidechain is
  # on it collapses drums+harm into [sc_mix], and the bass should not be ducked
  # by the same chord-triggered envelope that keeps the pads out of the kick.
  if bass_own_bus && bass_bus_idx
    filt << apply_section_envelope(build_bass_bus_filter(bass_bus_idx, duration), :bass, n_bars, beat_p * 4.0)
    bass_label = "[bassbus]"
    # The kick and the bass were both boosted in the same octave and
    # summed. The bass bus lifts 70 Hz by 3 dB, which is where a kick's
    # fundamental sits, and it entered the mix at 1.15 against the kit's 0.88 --
    # the loudest thing in the track, sitting exactly on top of the one sound
    # the track is built around.
    #
    # The note above about not ducking the bass is about the CHORD-triggered
    # envelope, and it is right: pads move out of the way of chords, and a bass
    # line that did the same would breathe on every chord change. A kick duck is
    # a different thing entirely, and the two got conflated. This one is keyed
    # off the kick alone -- the drums lowpassed to 120 Hz, so hats and snare
    # never trigger it -- and it releases in 90 ms, well inside an eighth note,
    # so the bass is back before the next note.
    if ENV["DRUM_FORWARD"] != "0" && ENV["BASS_DUCK"] != "0"
      filt << "[dr_bass]lowpass=f=120[dr_bass_k]"
      filt << "#{bass_label}[dr_bass_k]sidechaincompress=threshold=" \
              "#{ENV.fetch('BASS_DUCK_DB', '-28')}dB:ratio=6:attack=2:release=90:level_sc=1.0[bassducked]"
      bass_label = "[bassducked]"
      dmesg("bass ducks under the kick below 120 Hz", unit: "harm0", parent: "dilla0")
    end
    mix_labels << bass_label
    mix_weights << ENV.fetch("BASS_MIX_WEIGHT", "1.15").to_s
  end
  if loop_idx
    filt << apply_section_envelope(
      build_sample_loop_filter(loop_idx, duration, loop_entry[:bpm], cfg[:bpm]), :sample, n_bars, beat_p * 4.0
    )
    bed_label = "[loopbed]"
    if ENV["BRIDGES"] != "0"
      # Four bars, or the phrase if the phrase is shorter than that.
      #
      # Keying this to phrase_bars alone gave a 16-bar track one phrase and
      # therefore no boundary at all -- the feature was on, correct, and silent.
      # Four bars is the unit a hip-hop section actually turns on, and it is
      # where a producer reaches for the filter.
      every = ENV.fetch("BRIDGE_EVERY_BARS", [cfg[:phrase_bars] || 4, 4].min).to_i
      plan = bridge_plan(n_bars, beat_p * 4.0, cfg[:track].to_s, every)
      unless plan.empty?
        filt.concat(bridge_filters(input: bed_label, output: "[bedbridged]", n_bars:,
                                   bar_sec: beat_p * 4.0, track: cfg[:track].to_s, every_bars: every))
        bed_label = "[bedbridged]"
        dmesg("bridges: #{plan.map { |b| "#{b[:kind]}@#{(b[:at] / (beat_p * 4.0)).round}" }.join(' ')}",
              unit: "harm0", parent: "dilla0")
      end
    end
    # The kit's third split exists only when the sidechain branch above ran.
    # Without it there is no key to carve against, and the bed goes in flat.
    if ENV["DRUM_FORWARD"] != "0"
      filt.concat(drum_forward_filters(bed: bed_label, key: "[dr_key]", out: "[bedcarved]"))
      mix_labels << "[bedcarved]"
      dmesg("drums forward: bed carved at #{DRUM_FORWARD_SPLIT.join('/')} Hz", unit: "harm0", parent: "dilla0")
    else
      mix_labels << bed_label
    end
    mix_weights << ENV.fetch("SAMPLE_LOOP_WEIGHT", "0.9").to_s
    dmesg("sample bed #{File.basename(loop_entry[:path])} @#{loop_entry[:bpm].round}bpm -> #{cfg[:bpm].round}bpm",
          unit: "harm0", parent: "dilla0")
  end

  # An asplit output that nothing reads never drains, and a filtergraph with an
  # undrained pad does not finish -- it hangs, with no error to read. The kit
  # splits three ways unconditionally, so on any render without a carved bed the
  # third pad has to be tied off here.
  if ENV["DRUM_FORWARD"] != "0"
    filt << "[dr_key]anullsink" unless mix_labels.include?("[bedcarved]")
    filt << "[dr_bass]anullsink" unless mix_labels.include?("[bassducked]")
  end

  if analog_idx
    filt << apply_section_envelope(
      "[#{analog_idx}:a]aformat=channel_layouts=stereo,highpass=f=70,lowpass=f=6800," \
      "atrim=0:#{duration},apad=whole_dur=#{duration},asetpts=PTS-STARTPTS[analogpad]",
      # :pad, not :harm. This call asked for :harm and the default table says
      # nothing about :harm, so it has always returned the chain untouched --
      # the analog pad, the second-loudest channel in a typical render, has
      # never had a section shape. :harm is the synth harmony bus below and now
      # gets its own; this one is the analog pad and gets :pad. Under the
      # default table both are silent, exactly as before.
      :pad, n_bars, beat_p * 4.0
    )
    mix_labels << "[analogpad]"
    mix_weights << ENV.fetch("ANALOG_PAD_WEIGHT", "0.62").to_s
    dmesg("analog pad: #{ENV.fetch('ANALOG_PAD_PATCH', 'warm_pad')} on real oscillators",
          unit: "harm0", parent: "dilla0")
  end
  if stem_map[:mids]
    pan_fx = cfg[:stereo_pan] ? ",apulsator=mode=sine:hz=#{pan_hz}:amount=0.38" : ""
    filt << "[#{stem_map[:mids]}:a]aformat=channel_layouts=stereo,atempo=#{stem_tempo},atrim=0:#{duration},asetpts=PTS-STARTPTS," \
             "lowpass=f=3400,volume='#{pad_gate}':eval=frame,aphaser=speed=0.11:decay=0.4#{pan_fx}[padbed]"
    mix_labels << "[padbed]"
    mix_weights << "0.82"
  end
  if stem_map[:highs]
    # SECTION_LAYER_GAIN has always said chops are silent through the intro, the
    # breakdown and the outro. Nothing read it until now.
    #
    # Under SECTION_LAYERS=full only, for the same reason the lead's envelope is:
    # every stem render ever made was made without this, and switching it on by
    # default would change all of them on the strength of a table entry rather
    # than on somebody listening.
    chops_chain = "[#{stem_map[:highs]}:a]aformat=channel_layouts=stereo,atempo=#{stem_tempo}," \
                  "atrim=0:#{duration},asetpts=PTS-STARTPTS," \
                  "highpass=f=400,volume='#{chop_gate}':eval=frame,aecho=0.35:0.4:90:0.25[chops]"
    chops_chain = apply_section_envelope(chops_chain, :chops, n_bars, beat_p * 4.0) if section_layers_full?
    filt << chops_chain
    mix_labels << "[chops]"
    mix_weights << "0.68"
  end
  if stem_map[:sub]
    filt << "[#{stem_map[:sub]}:a]aformat=channel_layouts=stereo,atempo=#{stem_tempo},atrim=0:#{duration},asetpts=PTS-STARTPTS," \
             "lowpass=f=180,equalizer=f=72:t=o:w=1:g=4,volume=0.68[subbed]"
    mix_labels << "[subbed]"
    mix_weights << "0.72"
  end
  if stem_map[:center] && !stem_map[:mids]
    filt << "[#{stem_map[:center]}:a]aformat=channel_layouts=stereo,atrim=0:#{duration},asetpts=PTS-STARTPTS," \
             "lowpass=f=3000,volume='#{pad_gate}':eval=frame[padbed]"
    mix_labels << "[padbed]"
    mix_weights << "0.75"
  end

  # The wav_Map drone joins as a texture channel. Highpassed off the sub so it
  # does not fight the bass it sits under, and lowpassed so a picture full of
  # fine detail does not arrive as a sheet of top end. Its weight puts it under
  # the analog pad rather than beside it.
  if wav_map_idx
    filt << apply_section_envelope(
      "[#{wav_map_idx}:a]aformat=channel_layouts=stereo," \
      "highpass=f=#{ENV.fetch('WAV_MAP_HP', '55')},lowpass=f=#{ENV.fetch('WAV_MAP_LP', '7000')}," \
      "atrim=0:#{duration},apad=whole_dur=#{duration},asetpts=PTS-STARTPTS[wavmap]",
      :texture, n_bars, beat_p * 4.0
    )
    mix_labels << "[wavmap]"
    mix_weights << ENV.fetch("WAV_MAP_WEIGHT", "0.30").to_s
  end

  # Vinyl and rumble carry the :texture envelope, which the default table has no
  # entry for -- so under SECTION_LAYERS=1 these are byte-identical to what they
  # were. Under `full` they come up when the band drops out, which is when a
  # record's surface is something you hear rather than something under the mix.
  if vinyl_amp.positive?
    filt << apply_section_envelope(
      "[#{idx}:a]highpass=f=120,lowpass=f=6000,volume=0.045[vinyl]", :texture, n_bars, beat_p * 4.0
    )
    mix_labels << "[vinyl]"
    mix_weights << "0.35"
  end
  if turntable_rumble
    rumble_idx = vinyl_amp.positive? ? idx + 1 : idx
    filt << apply_section_envelope(
      "[#{rumble_idx}:a]lowpass=f=40,highpass=f=22,volume=0.04[rumble]", :texture, n_bars, beat_p * 4.0
    )
    mix_labels << "[rumble]"
    mix_weights << "0.25"
  end
  if self_sample_idx
    # Previous render feedback — off by default on Camel (re-injects prior vocals/sample).
    filt << "[#{self_sample_idx}:a]atrim=0:#{duration},asetpts=PTS-STARTPTS," \
             "lowpass=f=1800,areverse,volume=0.06[selfsample]"
    mix_labels << "[selfsample]"
    mix_weights << "0.55"
  end
  # The mix goes through the routing spine instead of being joined by hand.
  #
  # audio_graph.rb was written to make "route this to the drum bus" sayable and
  # then had exactly one caller -- render_industrial, for a bed -- while this
  # renderer, the one the spine was modelled on, kept assembling the string
  # itself. Its header says so. This is the second caller.
  #
  # Every entry in mix_labels is a label a clause above already emitted, so each
  # becomes a pass-through channel: the spine writes no rename for it, and the
  # amix it emits is character-identical to the line this replaces -- weights,
  # positional order and options included. test_audio_graph_render_dilla.rb pins
  # that against the literal string, so a divergence fails rather than ships.
  #
  # The weights stay Strings deliberately. They are ENV.fetch results and tuned
  # literals -- "1.0", "1.70", "0.9" -- and a round trip through Float would
  # write "1" and "1.7" instead. Same mix, different text, and the parity proof
  # is textual. AudioGraph#format_gain passes a String through untouched.
  graph = dilla_mix_graph(mix_labels, mix_weights)
  filt << graph.to_filter_complex(out_label: nil)
  filt.concat(master_bus_filters(graph.sum_label, track: cfg[:track].to_s, duration:, ir_input_idx:, cfg:))

  # Drop empty segments so a stray "" never becomes "No such filter: ''".
  filt_graph = filt.flatten.compact.map(&:to_s).map(&:strip).reject(&:empty?).join(";")
  command += ["-filter_complex", filt_graph, "-map", "[out]", "-t", duration.to_s, *codec_for(destination), destination]
  File.write("/tmp/last_filter_graph.txt", filt_graph.gsub(";", ";\n")) if ENV["DEBUG_FILTER_DUMP"]
  sh!(*command)
  # Parallel dry kit after Sonitex — measured demo was peak 0.27 with flat 16ths
  # (pattern erased). Blend pre-master drums back so Camel grid is audible.
  if camel_mode? && ENV.fetch("CAMEL_DRY_DRUMS", "1") != "0" && File.file?(drum_tmp) && File.file?(destination)
    # Default dry kit quiet under pads (0.55); raise CAMEL_DRY_DRUM_WEIGHT for kit-forward.
    dry_w = ENV.fetch("CAMEL_DRY_DRUM_WEIGHT", "0.55").to_f
    bed_w = ENV.fetch("CAMEL_BED_WEIGHT", "1.3").to_f
    dry_mix = "#{destination}.drykit#{File.extname(destination)}"
    begin
      sh! "ffmpeg", "-y", "-i", destination, "-i", drum_tmp,
          "-filter_complex",
          "[1:a]aformat=channel_layouts=stereo,equalizer=f=55:t=o:w=0.8:g=2.5," \
          "equalizer=f=200:t=o:w=1:g=1.5,equalizer=f=4500:t=o:w=1.5:g=3,volume=#{dry_w}[dk];" \
          "[0:a]volume=#{bed_w}[bed];" \
          "[bed][dk]amix=inputs=2:weights=1.25 0.75:duration=first:normalize=0," \
          "alimiter=limit=0.97:level_out=0.98[out]",
          "-map", "[out]", *codec_for(dry_mix), dry_mix
      FileUtils.mv(dry_mix, destination) if File.file?(dry_mix)
    rescue StandardError => e
      warn "camel dry drums: #{e.message}"
      FileUtils.rm_f(dry_mix)
    end
  end
  if (rap_slug = rap_vocal_stream_slug)
    begin
      # A different point in the performance per track. Keyed on track and
      # slug together so one track does not enter two voices at the same word.
      variant = stable_hash("#{cfg[:track]}/#{rap_slug}") % RAP_VOCAL_VARIANTS
      fit = rap_vocal_fit!(rap_slug, beat_bpm: cfg[:bpm], n_bars:, progression: cfg[:progression],
                           variant:)
      if fit && File.file?(fit)
        rap_tmp = "#{destination}.rap#{File.extname(destination)}"
        mix_rap_vocal_layer!(destination, fit, rap_tmp, beat_bpm: cfg[:bpm])
        FileUtils.mv(rap_tmp, destination)
        puts "rap-vocal: mixed #{rap_slug} → #{destination}"
      end
    rescue StandardError, SystemExit => e
      warn "rap-vocal: skipped (#{e.class}) — #{e.message}"
    end
  end
  if punk_guitar_enabled?
    begin
      gtr = render_punk_guitar_layer!(cfg[:bpm], n_bars, cfg)
      if gtr && File.file?(gtr)
        gtr_tmp = "#{destination}.gtr#{File.extname(destination)}"
        mix_punk_guitar_layer!(destination, gtr, gtr_tmp)
        FileUtils.mv(gtr_tmp, destination)
        FileUtils.rm_f(gtr)
        puts "punk-guitar: mixed power-chord stabs → #{destination}"
      end
    rescue StandardError, SystemExit => e
      warn "punk-guitar: skipped (#{e.class}) — #{e.message}"
    end
  end
  if DILLA_DRONE
    begin
      # Synthesised by default: harmonic_tmp is the engine's own pad/chord bus,
      # so the drone is built from sound this file made rather than from a
      # sample on disk, and it is in the render's key by construction.
      # DILLA_DRONE_SRC=loop takes the track's sampled loop instead.
      drone_src = if ENV["DILLA_DRONE_SRC"].to_s == "loop"
                    sample_loop_for(ENV["TRACK"])&.dig(:path) || harmonic_tmp
                  else
                    harmonic_tmp
                  end
      drone_tmp = "#{destination}.drone.wav"
      if dilla_render_drone!(drone_src, drone_tmp, duration:)
        mixed = "#{destination}.droned#{File.extname(destination)}"
        sh! "ffmpeg", "-y", "-i", destination, "-i", drone_tmp,
            "-filter_complex",
            "[1:a]volume=#{DILLA_DRONE_VOL}[dr];" \
            "[0:a][dr]amix=inputs=2:duration=first:normalize=0," \
            "alimiter=limit=0.97:level_out=0.98[out]",
            "-map", "[out]", *codec_for(mixed), mixed
        FileUtils.mv(mixed, destination)
        puts "drone: #{File.basename(drone_src)} stretched under the mix → #{destination}"
      end
      FileUtils.rm_f(drone_tmp)
    rescue StandardError => e
      warn "drone: skipped (#{e.class}) — #{e.message}"
    end
  end

  # Final integrated loudness — every track (with or without vocals) same level.
  if ENV.fetch("STREAM_NORMALIZE", "1") != "0" || ENV["DILLA_STREAMING"] == "1"
    normalize_track_loudness!(destination)
  end

  # After loudness for the same reason the brake is: loudnorm would flatten a
  # swell applied before it, which is exactly what happened when this lived on
  # the pad bus.
  organic_swell_master!(destination, bar_sec: (60.0 / cfg[:bpm]) * 4.0)
  dilla_dropout!(destination, bar_sec: (60.0 / cfg[:bpm]) * 4.0)
  tape_hysteresis!(destination)
  master_tilt!(destination)
  master_smooth!(destination)
  mono_bass!(destination)

  # After loudness, not before: the brake ends in near-silence, and normalising
  # a file whose last bar is a fade to nothing pulls the whole track up to
  # compensate for it.
  if DILLA_TAPE_STOP
    begin
      dilla_tape_stop!(destination, beat_bpm: cfg[:bpm])
      puts "tape-stop: #{DILLA_TAPE_STOP_BEATS.round} beats of brake → #{destination}"
    rescue StandardError => e
      warn "tape-stop: skipped (#{e.class}) — #{e.message}"
    end
  end
  export_render_stems!(destination, drum_tmp, harmonic_tmp, events, duration, cfg,
                       use_stem_harmony:)
  keep_stems ||= ENV["KEEP_STEMS"] != "0"
  unless keep_stems
    FileUtils.rm_f(drum_tmp)
    FileUtils.rm_f(harmonic_tmp) unless use_stem_harmony
  end
  stem_note = use_stem_harmony ? stems.keys.join("+") : "synth-harmony+melody"
  mix_note = sonitex_label
  lead_arp_style = lead_arp_cfg_for(@render_lead_patch)&.dig(:style)
  # Only name patches that actually sounded.
  #
  # The lead patches are picked before the lead gate is consulted, so this line
  # listed scale_arp_moog/soul_prophet_arp on renders where lead_arp_enabled? was
  # false and both event arrays came back empty — i.e. it advertised arps in a
  # pads-only render. Read alongside "lead=0/off" in the stream banner two lines
  # later, it directly contradicted the truth, and cost a debugging session
  # chasing arps that were never in the mix.
  # The same trap one level down: under NO_ARP the arp styles are still *chosen*
  # (the patch tables are read before the gate), so this line went on printing
  # "major_third_cycle_full/updown/pingpong" for renders where all three arp paths returned
  # zero events. Naming the styles is conditional on them actually running.
  lead_note = if lead_arp_enabled?
                arp_names = no_arp? ? [] : [@render_scale_arp_style, @render_arp_style, lead_arp_style]
                scale_id = no_arp? ? nil : @render_scale_lead_patch&.dig(:id)
                [scale_id, @render_lead_patch&.dig(:id), *arp_names]
              else
                []
              end
  patch_note = [@render_ep_patch&.dig(:id), @render_warm_patch&.dig(:id), *lead_note].compact.join("/")
  patch_note += " (no lead)" unless lead_arp_enabled?
  kick_note = kicks_enabled? ? "kicks" : "no-kicks"
  comp_note = ""
  if composition_enabled? && instance_variable_defined?(:@composition_session) && @composition_session
    @composition_session.save!
    s = @composition_session
    comp_note = ", performer=#{s.performer}/#{s.groove_dna} gen=#{s.generation}"
  end
  # Layer first so the loudness target is measured on the finished balance, and
  # varispeed last: resampling the master is the final act, the way a tape
  # machine running slow is.
  layer_master!(destination)
  # The album signature sits here: after the per-render character stages, before
  # loudness, so every beat is finished identically and then levelled identically.
  melt_master!(destination)
  normalise_master!(destination, cfg)
  varispeed_master!(destination)
  puts "wrote #{destination} (#{cfg[:bpm].to_i} BPM, #{n_bars} bars, #{cfg[:track]}, #{kick_note}, #{mix_note}, #{stem_note}, patches=#{patch_note}#{comp_note})"
ensure
  # The call at the TOP of this method only clears ITS OWN pid's leftovers
  # from a *previous* call in the same long-lived process (stream()'s loop);
  # it never fires for a fresh one-shot process, since a new pid has no
  # scratch yet at start. Without this, every subprocess-per-render caller
  # (showcase_demo!, .all_tracks_demo/fill_holes.rb) leaked its own
  # .dilla_harmonic.<pid>.wav.*/.dilla_drums.<pid>.wav scratch forever --
  # `ensure` so it still fires if this method raises partway through.
  cleanup_render_scratch!
  # Put the old take back unless a new one actually landed.
  #
  # "Landed" is a size check, not File.exist?: a render killed during the final
  # ffmpeg leaves a truncated destination behind, and restoring nothing over a
  # 40-byte stub would lose the take just as completely as the delete did.
  # 64 KB is under a second of 320k mp3 — anything smaller is wreckage.
  if defined?(previous_take) && previous_take && File.file?(previous_take)
    if File.size?(destination).to_i > 64_000
      FileUtils.rm_f(previous_take)
    else
      FileUtils.mv(previous_take, destination)
      warn "render did not finish — kept the previous #{File.basename(destination)}"
    end
  end
end

# --------------------------------------------------------------------------
# engine part: render_industrial
# --------------------------------------------------------------------------
#
# The industrial techno renderer.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def industrial_techno_section(bar)
  case bar
  when 0..7   then :intro
  when 8..31  then :groove
  when 32..39 then :breakdown
  when 40..47 then :build
  when 48..111 then :main
  when 112..119 then :peak
  else :outro
  end
end

# Arranged industrial techno: intro → groove → breakdown → build → main → peak → outro.
def industrial_techno_schedule(n_bars, beat_p, roots = nil)
  bar_p = (beat_p * 4.0).round(6)
  step_p = (bar_p / 16.0).round(6)
  events = Hash.new { |h, k| h[k] = [] }

  n_bars.times do |bar|
    base = bar * bar_p
    section = industrial_techno_section(bar)

    case section
    when :intro
      events[:kick] << [base, 0.82] if bar % 4 == 0
      events[:kick] << [base + step_p * 8, 0.55] if bar >= 4
    when :breakdown
      events[:kick] << [base, 0.65] if bar.even?
      events[:kick] << [base + step_p * 8, 0.45] if bar >= 36
    else
      [0, 4, 8, 12].each do |step|
        vel = section == :peak ? 1.0 : 0.9
        events[:kick] << [base + step * step_p, vel]
      end
      events[:kick] << [base + step_p * 14, 0.62] if section == :peak && bar.odd?
      events[:kick] << [base + step_p * 15, 0.48] if section == :build && bar >= 44
    end

    unless section == :intro && bar < 2
      clap_vel = section == :peak ? 0.78 : 0.62
      events[:clap] << [base + step_p * 4, clap_vel * 0.85] unless section == :breakdown && bar < 36
      events[:clap] << [base + step_p * 12, clap_vel]
      events[:clap] << [base + step_p * 14, 0.42] if section == :peak && bar % 2 == 1
    end

    hat_active = !(section == :breakdown && bar >= 34)
    16.times do |step|
      next unless hat_active
      seed = (bar * 97) + (step * 31)
      next if section == :groove && step.even? && seed % 9 == 0
      next if section == :main && step % 4 == 0 && seed % 11 == 0
      accent = step.odd? ? 1.08 : 1.0
      vel = (0.16 + (seed % 11) * 0.022) * accent
      vel *= 1.25 if section == :peak
      events[:hat] << [base + step * step_p, vel]
    end

    if hat_active && [1, 3, 5, 7].include?(bar % 8) && section != :intro
      events[:open] << [base + step_p * 6, section == :peak ? 0.42 : 0.32]
      events[:open] << [base + step_p * 14, 0.28] if section == :main || section == :peak
    end

    bass_active = section != :breakdown || bar < 35
    if bass_active
      acid_steps = section == :intro ? [0, 8] : [0, 2, 3, 5, 8, 10, 11, 14]
      acid_steps.each do |step|
        # With a progression to follow, the hit carries a target FREQUENCY and
        # render_sample_bus_wav resamples ind_bass_e to it. Without one it
        # carries a sample key and alternates E against Bb on bar arithmetic --
        # a fixed tritone, in every key, forever. That alternation is this
        # renderer's signature and is kept as the default; it is no
        # longer the only thing available.
        note = if roots
                 roots[(bar / 2) % roots.length]
               elsif ((bar / 2 + step) % 4) >= 2
                 :ind_bass_bb
               else
                 :ind_bass_e
               end
        vel = section == :peak ? 0.82 : 0.68
        vel *= 0.5 if section == :intro
        events[:bass] << [base + step * step_p, vel, note]
      end
    end

    if section != :breakdown && bar % 8 == 7
      events[:stab] << [base + step_p * 4, 0.52]
      events[:stab] << [base + step_p * 12, 0.38] if section == :peak
    end
  end
  events
end

# Industrial techno: arranged 135 BPM groove, rumble sub, sidechain, dub space.
def render_industrial(destination = File.join(ROOT, "renders", "foundry_pulse.mp3"), bars_count = nil)
  require_tools! "ffmpeg"
  ensure_drum_kit!
  FileUtils.mkdir_p(File.dirname(destination))
  ibpm = ENV.fetch("IBPM", INDUSTRIAL_TECHNO_BPM.to_s).to_f
  beat_p = (60.0 / ibpm).round(6)
  n_bars = bars_count || (ENV["BARS"] ? bars : INDUSTRIAL_TECHNO_BARS)
  duration = (beat_p * 4.0 * n_bars).round(3)
  dotted_8th_ms = (3.0 * beat_p / 4.0 * 1000.0).round(1)
  # Same spine as techno: the progression's chord roots, folded into the register
  # this bass already worked in (41.2 Hz E1 to 58.27 Hz Bb1, so an octave from
  # E1 up).
  ind_roots = techno_harmony_roots(8, register: (38.0..76.0))
  dmesg("industrial harmony: bass follows #{ind_roots.uniq.length} chord root(s)",
        unit: "ind0", parent: "dilla0") if ind_roots
  events = industrial_techno_schedule(n_bars, beat_p, ind_roots)

  kit = {
    ind_kick: load_mono_sample(drum_sample_path("ind_kick.wav")),
    ind_clap: load_mono_sample(drum_sample_path("ind_clap.wav")),
    ind_hat: load_mono_sample(drum_sample_path("ind_hat.wav")),
    open_hat: load_mono_sample(drum_sample_path("open_hat.wav")),
    ind_bass_e: load_mono_sample(drum_sample_path("ind_bass_e.wav")),
    ind_bass_bb: load_mono_sample(drum_sample_path("ind_bass_bb.wav")),
    ind_stab: load_mono_sample(drum_sample_path("ind_stab.wav")),
  }
  stab_hits = events[:stab].map { |t, v| [t, v, :ind_stab] }
  drum_tmp = File.join(SCRATCH_DIR, "ind_drums.wav")
  render_sample_bus_wav(
    drum_tmp,
    events.merge(stab: stab_hits),
    duration,
    kit,
    kick: :ind_kick, clap: :ind_clap, hat: :ind_hat, open: :open_hat, bass: :ind_bass_e, stab: :ind_stab,
  )

  # The same pre-graph drum stage render_dilla runs. DRUM_FIELD_LAYER is empty
  # unless the operator sets it, so this changes nothing by default -- it makes
  # the capability reachable from a renderer that never had it.
  drum_field_layer!(drum_tmp, duration: duration)

  sides_path = File.join(STEM_DIR, "sides.mp3")
  command = ["ffmpeg", "-y", "-i", drum_tmp]
  idx = 1
  sides_idx = nil
  if File.exist?(sides_path)
    command += ["-stream_loop", "-1", "-i", sides_path]
    sides_idx = idx
    idx += 1
  end
  command += ["-f", "lavfi", "-i", "aevalsrc='0.55*sin(2*PI*38*t)*exp(-mod(t,#{beat_p})*1.8)':d=#{duration}:s=#{SAMPLE_RATE}"]
  rumble_idx = idx
  idx += 1
  command += ["-f", "lavfi", "-i", "anoisesrc=color=white:amplitude=0.022:d=#{duration}:r=#{SAMPLE_RATE}:seed=#{noise_seed(15)}"]
  noise_idx = idx

  filt = []
  filt << "[0:a]aformat=channel_layouts=stereo,asplit=2[drums][drums_sc]"

  # The bed, as channels rather than as two arrays kept in step by hand.
  #
  # mix_in and mix_w are appended separately. Under one `if` they take the shape
  # that silently mis-assigns every weight the moment one append lands without
  # the other -- amix takes weights positionally, not by name.
  #
  # :drum is a bus with an empty chain today, so it collapses to [drums] and this
  # emits the graph it always emitted; test_audio_graph_industrial pins that as
  # text, with and without the optional texture. It is a bus so the channel strip
  # this renderer has never had has somewhere to go -- give :drum a chain and
  # every kit voice under it moves together.
  #
  # amix_options is the legacy string on purpose. This renderer omits normalize=0
  # where render_dilla sets it, which measures 4.1 dB into a sidechain
  # compressor, a tanh saturator and a compressor. Audible, and a separate
  # decision from this one.
  bed = AudioGraph.new(amix_options: "duration=first")
  bed.bus(:drum)
  bed.channel(:kit, input: "[drums]", bus: :drum)
  bed.channel(:rumble, input: "#{rumble_idx}:a", gain: 0.55,
              chain: ["aformat=channel_layouts=mono", "lowpass=f=95",
                      "equalizer=f=48:t=o:w=0.8:g=8", "volume=0.42"])
  if sides_idx
    bed.channel(:texture, input: "#{sides_idx}:a", gain: 0.28,
                chain: ["aformat=channel_layouts=stereo", "atrim=0:#{duration}",
                        "asetpts=PTS-STARTPTS", "highpass=f=180", "lowpass=f=8500",
                        "volume=0.18"])
  end
  bed.channel(:noise, input: "#{noise_idx}:a", gain: 0.06,
              chain: ["highpass=f=400", "lowpass=f=5000", "volume=0.04"])
  filt << bed.to_filter_complex(out_label: nil)
  bed_label = bed.sum_label
  filt << "[#{bed_label}][drums_sc]sidechaincompress=threshold=-24dB:ratio=8:attack=0.5:release=110:level_sc=0.9[pumped]"
  filt << "[pumped]asplit=2[dry][rev_send]"
  filt << "[rev_send]highpass=f=100,lowpass=f=9000,aecho=0.7:0.8:480|960|1920|3200:0.6|0.45|0.3|0.18[verb]"
  filt << "[dry][verb]amix=inputs=2:weights=0.62 0.38[with_verb]"
  filt << "[with_verb]asplit=2[dry2][dly]"
  filt << "[dly]highpass=f=280,aecho=0.55:0.65:#{dotted_8th_ms}|#{(dotted_8th_ms * 2).round(1)}|#{(dotted_8th_ms * 3).round(1)}:0.75|0.55|0.35[echo]"
  filt << "[dry2][echo]amix=inputs=2:weights=0.7 0.3[pre]"
  sat = Math.tanh(3.8).round(6)
  filt << "[pre]extrastereo=m=1.18[wide]"
  filt << "[wide]aeval=exprs='tanh(3.8*val(0))/#{sat}|tanh(3.8*val(1))/#{sat}'[satd]"
  filt << "[satd]acompressor=threshold=-14dB:ratio=10:attack=1:release=45:makeup=3.5[comp]"
  filt << "[comp]equalizer=f=52:t=o:w=0.65:g=6,equalizer=f=120:t=o:w=1:g=2,equalizer=f=9500:t=o:w=2:g=-5[eq]"
  filt << "[eq]acrusher=bits=14:samples=2:mix=0.08[pre_master]"
  filt.concat(master_bus_filters("pre_master"))

  command += ["-filter_complex", filt.join(";"), "-map", "[out]", "-t", duration.to_s, *codec_for(destination), destination]
  sh!(*command)
  FileUtils.rm_f(drum_tmp)
  mix_note = sonitex_enabled? ? sonitex_label : "dry"
  normalise_genre_master!(destination, :techno)
  puts "wrote #{destination} (#{ibpm.to_i} BPM industrial techno, #{n_bars} bars, #{mix_note})"
end

# --------------------------------------------------------------------------
# engine part: composition_cmds
# --------------------------------------------------------------------------
#
# Composition commands: jam, evolve, critique, listen.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# =============================================================================
# COMPOSITION — memory, arrangement, performers, evolution, critique
# =============================================================================

def composition_jam(n_bars = 16)
  ENV["COMPOSITION"] = "1"
  reset_composition_session!
  n_bars = (ENV["BARS"] || n_bars).to_i
  sess = composition_session!(n_bars:, force_new: true)
  puts "jam — #{sess.track} | performer=#{sess.performer} groove=#{sess.groove_dna} | #{n_bars} bars"
  dest = File.join(SCRATCH_DIR, "jam_tmp.wav")
  render_dilla(dest, n_bars, keep_stems: true)
  play_loop(dest)
end

def composition_evolve(n_bars = 16, generations = 5)
  ENV["COMPOSITION"] = "1"
  n_bars = (ENV["BARS"] || n_bars).to_i
  generations = (ENV["GENERATIONS"] || generations).to_i
  reset_composition_session!
  sess = composition_session!(n_bars:, force_new: true)
  cfg = dilla_resolve_config
  dest = File.join(SCRATCH_DIR, "evolve_best.wav")
  render_fn = lambda do |session|
    @composition_session = session
    out = File.join(SCRATCH_DIR, "evolve_gen#{session.generation}.wav")
    render_dilla(out, n_bars, keep_stems: false)
    out
  end
  render_fn.define_singleton_method(:quality) { |path| dilla_quality(path) }
  render_fn.define_singleton_method(:last_events) { @last_drum_events }
  best = DillaComposition::Evolution.run(session: sess, cfg:, n_bars:,
                                         generations:, render_fn:)
  FileUtils.cp(best[:path], dest) if best[:path] && File.exist?(best[:path])
  DillaComposition::Critique.print_report(best[:critique]) if best[:critique]
  puts "evolve best score=#{best[:score]} → #{dest}"
  dest
end

def composition_critique(path = nil)
  path ||= File.join(SCRATCH_DIR, "live_tmp.wav")
  path = File.join(SCRATCH_DIR, "jam_tmp.wav") unless File.file?(path)
  abort "no render to critique — run: ruby dilla.rb jam" unless File.file?(path)
  report = dilla_quality(path)
  sess = composition_session!(n_bars: bars)
  critique = DillaComposition::Critique.analyze(report, session: sess, events: @last_drum_events)
  DillaComposition::Critique.print_report(critique)
  sess.critique_log << { path:, critique: critique[:scores], overall: critique[:overall] }
  sess.save!
  critique
end

def composition_session_cmd(sub = nil, *rest)
  case sub.to_s.downcase
  when "save"
    sess = composition_session!(n_bars: bars)
    payload = sess.save!
    puts "session saved → #{DillaComposition::SESSION_PATH}"
    puts JSON.pretty_generate(payload.slice("track", "performer", "groove_dna", "generation", "best_score"))
  when "load"
    reset_composition_session!
    ENV["COMPOSITION"] = "1"
    n_bars = (rest[0] || ENV["BARS"] || bars).to_i
    sess = composition_session!(n_bars:, force_new: true)
    puts "session loaded — #{sess.track} performer=#{sess.performer} groove=#{sess.groove_dna}"
  when "show", nil, ""
    sess = composition_session!(n_bars: bars)
    puts "── Session ──"
    puts "track: #{sess.track}  performer: #{sess.performer}  groove: #{sess.groove_dna}"
    puts "generation: #{sess.generation}  best_score: #{sess.best_score}"
    puts "motifs: #{sess.motifs.map { |m| "#{m.id}(#{m.state})" }.join(', ')}"
    puts "callbacks: #{sess.callbacks.length}  tension anchors: #{sess.tension_curve.length}"
    puts "arrangement: #{sess.arrangement.map { |e| e[:section] }.uniq.join(' → ')}"
  when "new"
    reset_composition_session!
    ENV["COMPOSITION"] = "1"
    track = rest[0] || ENV["TRACK"] || "timeless"
    n_bars = (rest[1] || ENV["BARS"] || bars).to_i
    @composition_session = DillaComposition::Session.new(track:, n_bars:)
    @composition_session.save!
    puts "new session — #{track} (#{n_bars} bars)"
  else
    abort "usage: ruby dilla.rb session [save|load|show|new] [args]"
  end
end

def regenerate_stem(stem, bars_count = 16)
  ENV["COMPOSITION"] = "1"
  bars_count = (ENV["BARS"] || bars_count).to_i
  sess = composition_session!(n_bars: bars_count)
  case stem.to_s.downcase
  when "bass"
    sess.motifs.find { |m| m.id == "bass_motif" }&.evolve!
  when "hats"
    keys = DillaComposition::GROOVE_DNA.keys
    sess.groove_dna = keys[(keys.index(sess.groove_dna) || 0) + 1] % keys.length
  when "melody"
    sess.motifs.find { |m| m.id == "hook" }&.evolve!
    sess.record_callback!(bars_count / 2, "hook", :A_prime)
  else
    abort "usage: ruby dilla.rb regenerate-stem bass|hats|melody [bars]"
  end
  sess.save!
  puts "regenerate-stem #{stem} — performer=#{sess.performer} groove=#{sess.groove_dna}"
  regenerate(bars_count)
end

def composition_listen_loop(n_bars = 16)
  ENV["COMPOSITION"] = "1"
  n_bars = (ENV["BARS"] || n_bars).to_i
  max_passes = (ENV["LISTEN_PASSES"] || 3).to_i
  dest = File.join(SCRATCH_DIR, "listen_loop.wav")
  render_fn = ->(pass) { render_dilla(File.join(SCRATCH_DIR, "listen_pass#{pass}.wav"), n_bars); dest }
  analyze_fn = ->(path) { dilla_quality(path) }
  path = DillaComposition::ListeningLoop.converge(render_fn:, analyze_fn:, max_passes:)
  FileUtils.cp(path, dest) if path && File.exist?(path)
  puts "listen_loop → #{dest}"
  play_loop(dest) if File.exist?(dest)
end

