# --------------------------------------------------------------------------
# engine part: render_analog
# --------------------------------------------------------------------------
#
# The analog renderer.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# =============================================================================
# ANALOG RENDERER (dilla_analog.rb)
# =============================================================================

def analog_two_bar_cycle
  (beat_seconds * 4 * 2).round(6)
end

def analog_drum_cycle_events(events)
  cycle = analog_two_bar_cycle
  events.map { |t, *rest| [(t % cycle).round(6), *rest] }
end

def kick_wave(t, v, cycle = analog_two_bar_cycle)
  tc = t.round(6)
  td = "mod(t,#{cycle})"
  "between(#{td},#{tc},#{(t + 0.42).round(6)})*#{v}*0.95*exp(-(#{td}-#{tc})*7.4)*" \
    "sin(2*PI*(45+115*exp(-20*(#{td}-#{tc})))*(#{td}-#{tc}))"
end

def bass_wave(t, v, f, cycle = analog_two_bar_cycle)
  tc = t.round(6)
  td = "mod(t,#{cycle})"
  "between(#{td},#{tc},#{(t + 0.46).round(6)})*#{v}*0.42*exp(-(#{td}-#{tc})*3.2)*sin(2*PI*#{f}*(#{td}-#{tc}))"
end

def analog_section_for_bar(b, total)
  return [:intro, 0.42] if b < 8
  return [:a, 1.00] if b < 24
  return [:a2, 1.00] if b < 40
  return [:break, 0.55] if b < 48
  return [:b, 1.00] if b < 64
  return [:drop, 0.72] if b < 72
  return [:c, 1.00] if b < 88
  [:outro, [0.25, 1.0 - ((b - 88) / [12.0, total - 88.0].max)].max]
end

# PAD_CHORDS entries all carry five voices, so the fixed indices below were safe
# for as long as PAD_CHORDS was the only source. Progression chords are not:
# neo_soul voices as [3, 3, 3, 2, 3, 3, 3, 3], because enrich_progression thins
# and drops roots on purpose. hz[3] on a three-note chord is nil, and nil * 1.122
# is a NoMethodError in the middle of a render.
#
# Widened rather than guarded. A two-note chord under a pad written for five
# does not read as the same part in a new key, it reads as a thinner record, so
# short chords are extended upward by octaves of their own tones until they have
# five. That keeps the pad's density while letting its pitches follow.
ANALOG_PAD_VOICES = 5

def analog_fit_chord(hz)
  voices = Array(hz).map(&:to_f).select(&:positive?).uniq.sort
  return voices if voices.empty? || voices.length >= ANALOG_PAD_VOICES

  # Successive octaves of successive tones: base[0]*2, base[1]*2, base[0]*4 …
  # Doubling the same tone every time -- which the first version did, because
  # `voices.length % voices.length` is always 0 -- produced [100,150,200,200,200]
  # and a chord that is three copies of one note is not five voices.
  base = voices.dup
  tried = 0
  while voices.length < ANALOG_PAD_VOICES && tried < base.length * 6
    candidate = (base[tried % base.length] * (2**(1 + (tried / base.length)))).round(2)
    # Skip an octave the chord already contains: [100,150,200] would otherwise
    # take 100*2 and spend a voice on a unison with the 200 already there.
    voices << candidate unless voices.any? { |v| (v - candidate).abs < 0.5 }
    tried += 1
  end
  voices.sort
end

def analog_rotate_chord(chord, bar_index)
  fitted = analog_fit_chord(chord[:hz])
  return fitted if fitted.empty?

  hz = fitted.rotate((bar_index / 8) % fitted.length)
  extra = case bar_index % 12
          when 0 then hz[0] * 1.067
          when 4 then (hz[2] || hz.last) * 1.414
          when 8 then (hz[3] || hz.last) * 1.122
          end
  extra ? (hz + [extra]) : hz
end

# `chords` overrides PAD_CHORDS when the caller has a progression to offer.
# Same shape either way -- { name:, hz: [...] } -- which is why this is a
# substitution rather than a conversion: PAD_CHORDS was already a hardcoded
# six-chord progression in F minor, so this renderer has always been harmonic,
# never in the key anything else was in.
def analog_schedule(bar_count, chords = nil)
  pool = (chords && chords.length >= 2) ? chords : PAD_CHORDS
  beat = beat_seconds
  bar_len = beat * 4
  step = bar_len / 16
  events = Hash.new { |h, k| h[k] = [] }
  kick_patterns = [[0, 7, 10, 14], [0, 5, 7, 10, 14], [0, 3, 7, 10, 12, 14], [0, 6, 9, 14]]

  bar_count.times do |b|
    sec, den = analog_section_for_bar(b, bar_count)
    base = b * bar_len
    kp = kick_patterns[(b / 8 + b % 3) % kick_patterns.length].dup
    kp = [0, 3, 6, 7, 10, 12, 14, 15] if b % 16 == 15
    kp = [0, 10] if sec == :intro && b > 2
    kp = [] if sec == :intro && b <= 2
    kp = (b.even? ? [0] : [0, 7]) if sec == :break
    kp = (b.even? ? [0, 10] : [0, 7, 14]) if sec == :drop
    kp = [0] if sec == :outro && b > bar_count - 8 && b % 4 == 0

    kp.each_with_index do |s, i|
      t = base + s * step + [0.000, 0.006, 0.011, -0.004, 0.018][(b + i) % 5]
      events[:kick] << [t, den]
      events[:bass] << [t + 0.023, den, ANALOG_ROOTS[(b / 4 + i) % ANALOG_ROOTS.length]] unless sec == :intro
    end

    [4, 12].each do |s|
      events[:snare] << [base + s * step + [-0.010, -0.006, 0.004, 0.010, 0.017][b % 5], den] unless sec == :intro
    end

    (b.even? ? [6, 11] : [3, 6, 11, 15]).each do |s|
      events[:ghost] << [base + s * step + [-0.014, 0.006, 0.018][(b + s) % 3], den * 0.32] unless [:intro, :drop].include?(sec)
    end

    hats = b % 16 == 7 ? [0, 4, 8, 12] : [0, 2, 4, 6, 8, 10, 12, 14]
    hats = b.even? ? [] : [0, 4, 8, 12] if sec == :break
    hats.each_with_index do |s, i|
      jitter = [-0.004, 0.000, 0.003, 0.006][(b + s) % 4]
      events[:hat] << [base + s * step + (i.odd? ? 0.018 : 0.002) + jitter, den * 0.52]
    end

    events[:open] << [base + 6 * step + 0.008, den * 0.30] if ![:intro, :break].include?(sec) && [1, 3].include?(b % 4)

    if b >= 2 && b % 4 == 0
      chord = analog_rotate_chord(pool[(b / 4) % pool.length], b)
      sustain = 3.2 + (b % 3) * 0.9
      events[:pad] << [base + 0.03, den, chord, sustain]
    end

    if b >= 2 && b % 2 == 0
      chord = analog_rotate_chord(pool[(b / 4 + 3) % pool.length], b)
      events[:chop] << [base + [1, 2, 5, 9, 13][b % 5] * step + [-0.022, 0.0, 0.017][b % 3], den, chord]
    end

    events[:riser] << [base + 2 * beat, 0.13] if [7, 23, 39, 47, 63, 71, 87].include?(b)
    events[:stop] << [base + 3 * beat, 0.18] if [23, 39, 47, 63, 71, 87].include?(b)
  end
  events
end

def analog_pad_expression(t, v, chord, sustain, bar_index)
  hz = chop_hz(chord)
  parts = hz.each_with_index.map do |f, i|
    drift = 1.0 + ((i - 2) * 0.0017) + (Math.sin((bar_index + i) * 1.7) * 0.0009)
    spike = (bar_index % 11 == i ? (ANALOG_CFG[:bad_tune_spike_cents] / 1200.0) : 0.0)
    ff = f * drift * (2.0 ** spike)
    [
      "sin(2*PI*#{ff}*(t-#{t}))",
      "0.55*sin(2*PI*#{ff * 1.004}*(t-#{t}))",
      "0.32*sin(2*PI*#{ff * 2.005}*(t-#{t}))",
      "0.20*sin(2*PI*#{ff * 0.5}*(t-#{t}))",
      "0.11*sin(2*PI*#{ff * 3.0}*(t-#{t}))",
    ].join("+")
  end.join("+")
  "between(t,#{t},#{t + sustain})*#{v}*0.035*exp(-(t-#{t})*0.26)*(0.78+0.22*sin(2*PI*0.23*(t-#{t})))*(#{parts})"
end

def render_analog(destination, bar_count: bars)
  require_tools! "ffmpeg"
  dur = (bar_count * beat_seconds * 4).round(3)
  # Third instance of the same defect: PAD_CHORDS is a fixed six-chord
  # progression in F minor, so analog renders were always in F minor whatever
  # key the track beside them was in.
  analog_chords = if genre_harmony_enabled?
                    begin
                      dilla_progression(dilla_resolve_config[:progression])
                    rescue StandardError
                      nil
                    end
                  end
  dmesg("analog harmony: pads follow #{analog_chords.length} progression chord(s)",
        unit: "anlg0", parent: "dilla0") if analog_chords && analog_chords.length >= 2
  ev = analog_schedule(bar_count, analog_chords)
  cycle = analog_two_bar_cycle

  kick = analog_drum_cycle_events(ev[:kick]).map { |t, v| kick_wave(t, v, cycle) }
  bass = analog_drum_cycle_events(ev[:bass]).map { |t, v, f| bass_wave(t, v, f, cycle) }
  snare = ev[:snare].map { |t, v| "between(t,#{t},#{t + 0.18})*#{v}*0.60*exp(-(t-#{t})*23)" }
  ghost = ev[:ghost].map { |t, v| "between(t,#{t},#{t + 0.09})*#{v}*exp(-(t-#{t})*35)" }
  hat = ev[:hat].map { |t, v| "between(t,#{t},#{t + 0.06})*#{v}*exp(-(t-#{t})*78)" }
  open_hat = ev[:open].map { |t, v| "between(t,#{t},#{t + 0.25})*#{v}*exp(-(t-#{t})*11)" }
  pad = ev[:pad].each_with_index.map { |(t, v, chord, sustain), i| analog_pad_expression(t, v, chord, sustain, i) }
  chop = ev[:chop].map { |t, v, chord| chop_wave(chord, t, v) }
  risers = ev[:riser].map { |t, v| "between(t,#{t},#{t + 2.0})*#{v}*((t-#{t})/2.0)^2" }
  stops = ev[:stop].map { |t, v| "between(t,#{t},#{t + 1.1})*#{v}*exp(-(t-#{t})*2.2)" }

  inputs = [
    *lavfi("aevalsrc='#{expr_sum(kick)}':d=#{dur}:s=#{SAMPLE_RATE}"),
    *lavfi("aevalsrc='#{expr_sum(bass)}':d=#{dur}:s=#{SAMPLE_RATE}"),
    *lavfi("anoisesrc=color=white:r=#{SAMPLE_RATE}:amplitude=0.5:d=#{dur}:seed=#{noise_seed(16)}"),
    *lavfi("anoisesrc=color=pink:r=#{SAMPLE_RATE}:amplitude=0.04:d=#{dur}:seed=#{noise_seed(17)}"),
    *lavfi("aevalsrc='#{expr_sum(pad)}':d=#{dur}:s=#{SAMPLE_RATE}"),
    *lavfi("aevalsrc='#{expr_sum(chop)}':d=#{dur}:s=#{SAMPLE_RATE}"),
    *lavfi("aevalsrc='#{expr_sum(risers + stops)}':d=#{dur}:s=#{SAMPLE_RATE}"),
  ]

  filter = <<~F
    [0:a]aformat=channel_layouts=stereo[k];
    [1:a]aformat=channel_layouts=stereo,lowpass=f=140[bs];
    [2:a]aformat=channel_layouts=stereo,asplit=3[ns][nh][no];
    [ns]volume='#{safe_volume_env(snare + ghost)}':eval=frame,highpass=f=160,bandpass=f=1600:w=2600[sn];
    [nh]volume='#{safe_volume_env(hat)}':eval=frame,highpass=f=6500[hh];
    [no]volume='#{safe_volume_env(open_hat)}':eval=frame,bandpass=f=5600:w=5200[op];
    [4:a]aformat=channel_layouts=stereo,#{DillaAutomation.pad_character_filter(cutoff_hz: ANALOG_CFG[:lowpass_hz], phaser_speed: 0.1, phaser_decay: 0.35)},adelay=#{ANALOG_CFG[:chorus_delay_l_ms]}|#{ANALOG_CFG[:chorus_delay_r_ms]},aecho=0.18:0.22:120:0.22[pad];
    [5:a]aformat=channel_layouts=stereo,highpass=f=120,lowpass=f=5000,aecho=0.18:0.22:90:0.28[chop];
    [6:a]aformat=channel_layouts=stereo,highpass=f=900,lowpass=f=9000[fx];
    [k][bs][sn][hh][op][pad][chop][fx]amix=inputs=8:weights=1.25 0.9 0.9 0.48 0.42 0.95 0.65 0.35:duration=longest[music];
    [3:a]volume=#{ANALOG_CFG[:vinyl_level]},highpass=f=90,lowpass=f=8000[vinyl];
    [music][vinyl]amix=inputs=2:weights=1 0.32:duration=first,
      acompressor=threshold=-18dB:ratio=3.5:attack=25:release=120:makeup=2,
      acrusher=bits=#{ANALOG_CFG[:sp_bits]}:samples=#{ANALOG_CFG[:sp_ratio].round(3)}:mix=0.22,
      aeval='(tanh((val(0)+#{ANALOG_CFG[:tape_dc]})*1.45)-0.072)/0.87|(tanh((val(1)+#{ANALOG_CFG[:tape_dc]})*1.45)-0.072)/0.87',
      highpass=f=30,lowpass=f=12000,equalizer=f=45:t=o:w=1.2:g=1,
      alimiter=level_out=0.96:limit=0.92[out]
  F

  FileUtils.mkdir_p(File.dirname(destination))
  sh! "ffmpeg", "-y", *inputs, "-filter_complex", filter.tr("\n", " "), "-map", "[out]", *codec_for(destination), destination
  normalise_genre_master!(destination, :analog)
  puts "wrote #{destination}"
end

def analog_liveset(destination = File.join(OUTPUT_DIR, "analog_liveset.mp3"), minutes = 12)
  bar_count = [(minutes.to_f * 60.0 / (beat_seconds * 4)).ceil, 64].max
  render_analog(destination, bar_count:)
end

# --------------------------------------------------------------------------
# engine part: render_madlib
# --------------------------------------------------------------------------
#
# The Madlib and Slum Village renderers.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# =============================================================================
# MADLIB DRUMS — pure dirty MPC beats, Dilla-time, no harmony/stems
# =============================================================================

def delicious_pocket_enabled?
  ENV.fetch("DELICIOUS", "1") !~ /\A(?:0|false|off)\z/i
end

def vlc_effects_enabled?
  ENV.fetch("VLC", "1") !~ /\A(?:0|false|off)\z/i
end

def madlib_resolve_config
  cfg = dilla_resolve_config
  base_timing = MICROTIMING_MS.merge(cfg[:timing] || {})
  timing = LOOSE_POCKET_TIMING_MS.merge(base_timing) { |_k, mad, base| base || mad }
  swing = (ENV["SWING"] || [cfg[:swing] + 6, 68].min).to_f
  bpm = cfg[:bpm]
  if delicious_pocket_enabled?
    ratio = (ENV["DELICIOUS_RATIO"] || DELICIOUS_POCKET_RATIO).to_f
    bpm = (bpm * ratio).round(1)
    swing = [swing + 4, 72].min
    timing = timing.merge(snare: -32..-14, hat_up: 26..44, kick_sync: 14..28)
  end
  cfg.merge(feel: :loose_pocket, swing:, timing:, bpm:, delicious: delicious_pocket_enabled?)
end

def vlc_eq_chain
  VLC_EQ_BANDS.map { |f, g| "equalizer=f=#{f}:t=o:w=1:g=#{g}" }.join(",")
end

# VLC audio effects chain — loudnorm, 10-band EQ, compressor, spatializer, stereo widener.
def vlc_audio_filters(input_tag, out_tag: "out")
  return ["[#{input_tag}]alimiter=limit=0.91:level_out=0.92[#{out_tag}]"] unless vlc_effects_enabled?
  c = VLC_COMPRESSOR
  eq = vlc_eq_chain
  [
    "[#{input_tag}]#{eq}[veq]",
    "[veq]acompressor=threshold=#{c[:threshold]}dB:ratio=#{c[:ratio]}:attack=#{c[:attack]}:release=#{c[:release]}:" \
    "makeup=#{c[:makeup]}:mix=#{c[:mix]}[vcomp]",
    "[vcomp]aphaser=in_gain=0.42:out_gain=0.72:delay=3:decay=0.28:speed=0.35:type=triangular[vph]",
    "[vph]aecho=0.38:0.42:38|76|114:0.22|0.14|0.08[vspat]",
    "[vspat]extrastereo=m=1.30[vwide]",
    "[vwide]stereotools=mode=lr>ms:slev=1.22:mlev=0.90[vms]",
    "[vms]stereotools=mode=ms>lr:base=0.16[vst]",
    "[vst]alimiter=limit=0.94:level_out=0.93[#{out_tag}]",
  ]
end

def madlib_drum_filters(input_tag = "bed", out_tag: "mad_out")
  sat = Math.tanh(2.6).round(6)
  [
    "[#{input_tag}]asplit=2[md][sc]",
    "[md]acrusher=bits=10:samples=1.69:mix=0.55[cr]",
    "[cr]aeval=exprs='tanh(2.6*val(0))/#{sat}|tanh(2.6*val(1))/#{sat}'[sat]",
    "[sat]acompressor=threshold=-17dB:ratio=8:attack=2:release=65:makeup=5.5[comp]",
    "[comp]equalizer=f=55:t=o:w=0.75:g=7,equalizer=f=2400:t=o:w=2:g=-5,equalizer=f=9000:t=o:w=2:g=-3[eq]",
    "[eq]extrastereo=m=1.14[wide]",
    "[wide][sc]sidechaincompress=threshold=-19dB:ratio=7:attack=1:release=75:level_sc=0.85[punched]",
    "[punched]vibrato=f=0.22:d=0.005[wow]",
    "[wow]aeval=exprs='val(0)+0.014*(random(0)-0.5)|val(1)+0.014*(random(1)-0.5)'[#{out_tag}]",
  ]
end

def madlib_master_filters(input_tag = "bed")
  filt = []
  filt.concat(madlib_drum_filters(input_tag, out_tag: "mad_out"))
  filt.concat(vlc_audio_filters("mad_out"))
  filt
end

# Pure drums: MPC one-shots + pocket microtiming + SP-1200 dirt.
def render_madlib_drums(destination = File.join(ROOT, "renders", "beats", "beat.wav"), bars_count = nil)
  require_tools! "ffmpeg"
  ensure_drum_kit!
  FileUtils.mkdir_p(File.dirname(destination))
  cfg = madlib_resolve_config
  n_bars = bars_count || (ENV["BARS"] ? bars : 32)
  beat_p = 60.0 / cfg[:bpm]
  duration = (beat_p * 4.0 * n_bars).round(3)
  events = dilla_schedule(
    n_bars, beat_p, [], drums_only: true,
    swing: cfg[:swing], feel: :loose_pocket, timing: cfg[:timing]
  )
  kit = {
    kick: load_mono_sample(drum_sample_path("kick.wav")),
    snare: load_mono_sample(drum_sample_path("snare.wav")),
    ghost: load_mono_sample(drum_sample_path("ghost.wav")),
    hat: load_mono_sample(drum_sample_path("hat.wav")),
    open_hat: load_mono_sample(drum_sample_path("open_hat.wav")),
  }
  drum_tmp = File.join(SCRATCH_DIR, "madlib_drums.wav")
  render_sample_bus_wav(
    drum_tmp,
    events, duration, kit,
    kick: :kick, snare: :snare, ghost: :ghost, hat: :hat, open: :open_hat
  )

  command = ["ffmpeg", "-y", "-i", drum_tmp,
             "-f", "lavfi", "-i", "anoisesrc=color=pink:r=#{SAMPLE_RATE}:amplitude=0.028:d=#{duration}:seed=#{noise_seed(18)}"]
  filt = [
    "[0:a]aformat=channel_layouts=stereo[drums]",
    "[1:a]highpass=f=120,lowpass=f=9000,volume=0.22[dust]",
    "[drums][dust]amix=inputs=2:weights=1.0 0.35:duration=first[bed]",
  ]
  filt.concat(madlib_master_filters("bed"))
  ext = File.extname(destination).downcase
  args = ext == ".mp3" ? codec_for(destination) : ["-c:a", "pcm_s16le"]
  command += ["-filter_complex", filt.join(";"), "-map", "[out]", "-t", duration.to_s, *args, destination]
  sh!(*command)
  FileUtils.rm_f(drum_tmp)
  fx = []
  fx << "delicious" if cfg[:delicious]
  fx << "vlc-all" if vlc_effects_enabled?
  puts "wrote #{destination} (#{cfg[:bpm].to_i} BPM, #{n_bars} bars, TRACK=#{cfg[:track]}, #{fx.join('+')})"
end

def render_madlib_album(output_dir = File.join(ROOT, "renders", "beats"))
  FileUtils.mkdir_p(output_dir)
  LOOSE_POCKET_BEAT_CATALOG.each do |entry|
    base = File.join(output_dir, entry[:out])
    prev = %w[TRACK BARS BPM SWING DELICIOUS VLC].each_with_object({}) { |k, h| h[k] = ENV[k] }
    ENV["TRACK"] = entry[:track].to_s
    ENV["BARS"] = entry[:bars].to_s
    ENV["DELICIOUS"] = "1"
    ENV["VLC"] = "1"
    render_madlib_drums("#{base}.wav", entry[:bars])
    render_madlib_drums("#{base}.mp3", entry[:bars])
  ensure
    prev.each { |k, v| v ? ENV[k] = v : ENV.delete(k) }
  end
  puts "loose_pocket batch: #{LOOSE_POCKET_BEAT_CATALOG.length} beats (wav+mp3) → #{output_dir}"
end

# =============================================================================
# HIP-HOP SYNTH (dilla_hiphop.rb)
# =============================================================================

# Batch-render tape presets — neutral session_XX filenames (no album track names).
def render_slum_album(output_dir = File.join(ROOT, "renders"))
  FileUtils.mkdir_p(output_dir)
  TAPE_RENDER_CATALOG.each_with_index do |entry, i|
    dest = File.join(output_dir, "#{entry[:out]}.mp3")
    prev = %w[TRACK BARS BPM PROGRESSION SWING SONITEX SONITEX_PRESET ANALOG_CHAIN].each_with_object({}) { |k, h| h[k] = ENV[k] }
    ENV["TRACK"] = entry[:preset].to_s
    ENV["BARS"] = entry[:bars].to_s
    ENV["SONITEX"] = "heavy"
    ENV["SONITEX_PRESET"] = "heavy"
    ENV["ANALOG_CHAIN"] = ANALOG_CHAIN_ROTATE[i % ANALOG_CHAIN_ROTATE.length].to_s
    render_dilla(dest, entry[:bars])
  ensure
    prev.each { |k, v| v ? ENV[k] = v : ENV.delete(k) }
  end
  puts "tape batch: #{TAPE_RENDER_CATALOG.length} sessions → #{output_dir}"
end

# Full-length MPC hip-hop: Slum Village Vol. 1/2 presets via TRACK= env.
def render_hiphop(destination = File.join(OUTPUT_DIR, "hiphop.mp3"))
  prev = %w[BPM BARS TRACK PROGRESSION SWING].each_with_object({}) { |k, h| h[k] = ENV[k] }
  ENV["TRACK"] ||= "syncopated_slash_ninth"
  ENV["BARS"] ||= "63"
  render_dilla(destination, bars)
ensure
  prev.each { |k, v| v ? ENV[k] = v : ENV.delete(k) }
end

# --------------------------------------------------------------------------
# engine part: render_techno
# --------------------------------------------------------------------------
#
# The hate/techno renderers and their harmony.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# =============================================================================
# TECHNO SYNTH (techno_hate.rb) — acid-industrial hybrid at 142 BPM
# =============================================================================

# --- Industrial techno, HATE-podcast shape ----------------------------------
#
# The existing render_techno is a good 8-bar loop and nothing else. Every one of
# its patterns is wrapped in mod(t, cycle), so a 213-bar render is that loop
# repeated 26 times, byte for byte. Hypnotic repetition is right for the genre;
# 26 identical repetitions is not an arrangement.
#
# What the style actually asks for, from the sources rather than from taste:
#
#   130-150 BPM, aggressive distorted sound design, heavy basslines.
#   Metallic clangs, hydraulic hisses and processed factory recordings layered
#   with heavy kicks. Heavy compression to make the kick punch, plus distortion
#   or bit-crushing for grit. Dark atmospheres and MINIMAL melodic content, so
#   the focus stays on energy. Reverb and delay for space and tension.
#   Repetitive, hypnotic structures with EVOLVING LAYERS.
#
# The last line is the one render_techno misses, and it is the difference
# between a loop and a set. So the core patterns keep their mod(t, cycle) --
# that is the hypnosis -- and each LAYER gets a gate on absolute time. The same
# eight bars come round and round while what is playing over them changes.
#
# A mix series like this runs long and moves in blocks rather than verses, so
# the schedule is in 16-bar blocks and reads as a set list rather than a song
# form: things arrive, sit, and leave.
HATE_BPM = (ENV["HATE_BPM"] || 145).to_f
HATE_CYCLE_BARS = 8
HATE_BLOCK_BARS = 16

# Which blocks each layer is present for, as a lambda over the block index.
# Deliberately written as rules rather than a table: a set that runs eight
# minutes or twenty should thin and thicken the same way either way.
HATE_LAYERS = {
  # Fifteen layers, each with its own arrival. The rules are written over the
  # block index rather than as a table so a set of eight minutes and one of
  # thirty thin and thicken the same way -- a mix series runs to whatever
  # length it runs to, and the shape should not be pinned to one duration.
  # Each lambda takes (position, block): position runs 0.0 to 1.0 across the
  # whole set, block is the raw index for the rules that want alternation.
  drone: ->(_p, _b) { true },                       # the bed is there before anything else
  hiss:  ->(_p, _b) { true },
  hat:   ->(_p, _b) { true },
  kick:  ->(p, _b) { p >= 0.08 && !p.between?(0.42, 0.5) },   # the room hears the drone first
  sub:   ->(p, _b) { p >= 0.15 && !p.between?(0.42, 0.5) },
  ghost: ->(p, _b) { p >= 0.25 && !p.between?(0.42, 0.5) },   # ghosts once the kick is established
  clap:  ->(p, _b) { p >= 0.15 && !p.between?(0.55, 0.62) },
  open:  ->(p, _b) { p >= 0.25 },
  metal: ->(p, _b) { p >= 0.3 },                    # the factory arrives late
  dfam:  ->(p, _b) { p >= 0.35 && !p.between?(0.55, 0.62) },  # the machine in the room
  poly:  ->(p, _b) { p >= 0.4 },                    # the 11-against-16 hat, deep in
  acid:  ->(p, _b) { p >= 0.45 },                   # the only sustained melodic content
  # Texture where the melody is not. paulwash is a bed, so it arrives early and
  # never leaves; weird is a spice and stays intermittent, because a signal with
  # no pitch left in it stops being interesting once you have placed it.
  paulwash: ->(p, _b) { p >= 0.12 },
  weird:    ->(p, b) { p >= 0.3 && b.odd? },
  bleep: ->(p, b) { p >= 0.45 && b.even? },         # blips answer the kit, in alternate blocks
  tom:   ->(p, b) { p >= 0.5 && b.odd? },
  bloop: ->(p, b) { p >= 0.55 && b.odd? },          # ...and the falling ones answer the bleeps
  ride:  ->(p, _b) { p >= 0.6 },
  # The sampled record, when TECHNO_HARMONY has put one under the arrangement.
  # It enters with the drone rather than late: the point of a bed is that the
  # rest of the arrangement is built over it, and a record that arrives at 45%
  # reads as a sample drop rather than as the floor of the track. It steps out
  # once across the middle so the return has somewhere to land.
  bed:   ->(p, _b) { !p.between?(0.42, 0.52) },
}.freeze

# One gate expression per layer, over absolute time: the union of the blocks it
# plays in. Layers present throughout return "1" and cost nothing.
# The schedule is expressed as a POSITION through the set, not a block number.
#
# Written against absolute block indices it only worked at one length. A
# two-minute render is five blocks, so every layer scheduled from block 5
# onwards -- toms, ride, and the acid line that carries the only melody --
# never played at all, and hate_gate returned an empty string, which ffmpeg
# rejects with "undefined constant or missing '(' in ''". A silent layer and a
# broken filter, from the same cause.
#
# Position is 0.0 at the first block and 1.0 at the last, so a set thins and
# thickens the same way whether it runs eight minutes or thirty.
# Where this block sits in the set, 0.0 to 1.0.
#
# HATE_PHASE shifts the whole window so a streamed set can pick up where the
# last block left off instead of replaying its own intro every few minutes. A
# render with no phase set behaves exactly as before.
def hate_position(block, blocks)
  # Position decides which of the eighteen layers have arrived. At 0.0 three
  # have -- drone, hiss and hat, the ambient ones -- and a block rendered there
  # measures -50.5 dB against a full block's -14.3.
  #
  # HATE_ARRIVED plays every block fully arrived, for a caller rendering a
  # sample rather than a set. A short render cannot express the arc: blocks are
  # its only resolution, so two blocks means positions 0.0 and 1.0 and nothing
  # between, and the first half of the piece is the three ambient layers alone.
  # That is right for the opening of a sixteen-minute set and wrong for a demo
  # slot, where it is half of everything the listener hears.
  return 1.0 if ENV["HATE_ARRIVED"] == "1"

  # One block is the whole set, so its place in the arc is the end of it rather
  # than the start -- otherwise it renders the way in and nothing else.
  base = blocks < 2 ? 1.0 : block.to_f / (blocks - 1)
  # Presence, not value. Guarding on `phase.zero?` made the FIRST streamed block
  # -- the one that should open the set at position 0 -- fall through to the
  # unphased branch and land mid-arc, so a stream started at its own midpoint
  # and then jumped backwards for block 1.
  raw = ENV["HATE_PHASE"]
  return base if raw.nil? || raw.empty?

  phase = raw.to_i
  arc = ENV.fetch("STREAM_TECHNO_ARC", "6").to_i.clamp(2, 40)
  # Each streamed block covers one slice of the arc, so consecutive blocks walk
  # forward through it and wrap rather than jumping back to nothing.
  ((phase + base) / arc).clamp(0.0, 1.0)
end

# This is the engine's SECOND arrangement.
#
# dilla_drums.rb has SECTION_LAYER_GAIN and section_layer_windows: named
# sections, a gain per layer per section, contiguous bars merged into windows,
# a short edge fade. This does the same job -- which layers sound when -- from
# a different vocabulary (blocks and an arc position rather than sections and
# bars) and emits a different filter (an `enable` expression built from
# `between` terms rather than a chain of `volume` stages).
#
# Both are good. Neither knows the other exists, which is the fork the genre
# work is supposed to be closing: `techno_bed_part!` above is the same story for
# the sampled bed, a second implementation of what build_sample_loop_filter
# does. The measurable form is in test_genre_renderers_reach_of_the_shared_spine,
# which records what each renderer reaches and fails if any of them reaches
# less. Merging the two arrangements is a real change to how every techno set
# sounds and is not something to do quietly at the end of a refactor -- but the
# duplication is now written down where the next person will find it, rather
# than being discoverable only by reading both renderers side by side.
def hate_gate(layer, blocks, bar_p)
  on = (0...blocks).select { |b| HATE_LAYERS.fetch(layer).call(hate_position(b, blocks), b) }
  return "1" if on.length == blocks
  # Never empty: a layer that plays nowhere is silence, and silence is "0".
  return "0" if on.empty?

  spans = on.chunk_while { |a, b| b == a + 1 }.map { |run| [run.first, run.last + 1] }
  spans.map { |from, to|
    "between(t,#{(from * HATE_BLOCK_BARS * bar_p).round(3)},#{(to * HATE_BLOCK_BARS * bar_p).round(3)})"
  }.join("+")
end

# Genre as a parameter rather than a fork.
#
# This renderer had no harmony in it at all. Its pitched layers carried literal
# frequencies -- an eight-entry acid_notes table, a 41 Hz sub, a drone on
# 36.71/36.95 -- and it referenced chord, scale, root, note_hz and midi_to_hz
# exactly zero times. That is why techno could sit next to the rest of the
# catalogue but never blend with it: there was nothing for a progression to
# attach to, so a jazz or soul progression could not drive an acid line and a
# techno slot could not share a key with the track beside it.
#
# These read the same progression render_dilla does -- dilla_resolve_config then
# dilla_progression -- and fold each chord's root into the register the layer
# already worked in, so the shape of the part is unchanged and only its pitches
# follow the harmony.
#
# Off by default. It changes what every techno render sounds like, which is the
# operator's ear to decide, not a wiring question: TECHNO_HARMONY=1.
TECHNO_ACID_REGISTER = (48.0..98.0).freeze
TECHNO_SUB_REGISTER = (32.0..64.0).freeze
TECHNO_DRONE_REGISTER = (30.0..58.0).freeze

# Octave-fold rather than clamp. A root outside the register is the right pitch
# class in the wrong octave, and clamping would flatten several chords onto the
# same boundary note -- which is how a progression turns into a drone.
def techno_fold(hz, register)
  h = hz.to_f
  return nil unless h.positive?

  h *= 2.0 while h < register.begin
  h /= 2.0 while h > register.end
  h.round(2)
end

# GENRE_HARMONY is the name for the property; TECHNO_HARMONY is kept because it
# shipped first and is what the techno A/B renders were made under. Both mean
# the same thing: the genre renderers take their pitches from the progression
# instead of from literals.
def genre_harmony_enabled? = ENV["GENRE_HARMONY"] == "1" || ENV["TECHNO_HARMONY"] == "1"

def techno_harmony_enabled? = genre_harmony_enabled?

TECHNO_BED_VOL = (ENV["TECHNO_BED_VOL"] || "0.55").to_f.clamp(0.0, 2.0)

# Fold the tempo ratio into three-quarter-to-three-halves rather than stretching
# whatever the arithmetic gives.
#
# A 92 BPM record against 145 BPM techno is 1.576x, which is not a stretch, it
# is a sprint -- and build_sample_loop_filter's own clamp stops at 2.0, so it
# would allow it. Halving it puts the record at half-time under the kit (0.788x,
# a 21% slow-down), which is what a DJ does with the same two tempos and what
# the material can actually take.
def techno_bed_ratio(loop_bpm)
  r = loop_bpm.to_f.positive? ? (HATE_BPM / loop_bpm.to_f) : 1.0
  r /= 2.0 while r > 1.5
  r *= 2.0 while r < 0.75
  r.round(5)
end

# atempo, not asetrate.
#
# The engine's usual sample path varispeeds -- asetrate, which moves pitch and
# tempo together like a turntable. That is right when the pads are transposed to
# the loop, which is what render_dilla does. Here it would be backwards: the
# acid, sub and drone have just been tuned TO the progression, and varispeeding
# the record by 21% would move it a third of an octave away from the harmony it
# is supposed to be sharing. Preserving pitch is what keeps the two in one key.
def techno_bed_part!(work, cycle)
  return nil unless techno_harmony_enabled?

  entry = sample_loop_for(ENV["TRACK"])
  return nil unless entry.is_a?(Hash) && entry[:path] && File.file?(entry[:path].to_s)

  ratio = techno_bed_ratio(entry[:bpm])
  chain = [
    ("atempo=#{ratio}" unless (ratio - 1.0).abs < 0.001),
    "highpass=f=#{(entry[:hp] || 45).to_i}",
    ("equalizer=f=90:t=o:w=1.1:g=#{entry[:sub_db].to_f}" unless entry[:sub_db].to_f.zero?),
    "lowpass=f=#{(entry[:lp] || 6000).to_i}",
    "volume=#{TECHNO_BED_VOL}",
  ].compact.join(",")
  path = File.join(work, "bed.wav")
  sh! "ffmpeg", "-y", "-v", "error", "-stream_loop", "-1", "-i", entry[:path].to_s,
      "-t", cycle.to_s, "-af", "aformat=channel_layouts=stereo,#{chain}",
      "-c:a", "pcm_s16le", path
  return nil unless File.file?(path) && File.size(path) > 10_000

  dmesg("techno bed #{File.basename(entry[:path])} @#{entry[:bpm].to_f.round}bpm " \
        "-> #{(entry[:bpm].to_f * ratio).round}bpm (atempo #{ratio}, pitch held)",
        unit: "techno0", parent: "dilla0")
  path
end

# One root per bar of the cycle, or nil when the harmonic path is off or the
# progression will not resolve. nil means "keep the literal tables", so a broken
# or missing progression degrades to exactly today's sound rather than to
# silence.
# The chord's NAME, not its lowest note.
#
# enrich_progression voices a good deal of this catalogue rootless -- that is
# the point of a rootless voicing -- so the lowest frequency in c[:hz] is
# routinely the third or the seventh. Following it would put the acid line a
# third above the harmony on exactly the chords that were voiced most carefully,
# and it would read as wrong without reading as broken. The name carries the
# root whatever the voicing did with it; hz.min is the fallback for the handful
# of generated chords whose names are not note-spelled ("napl3maj7", "bk2m9").
def techno_chord_root_hz(chord)
  name = chord[:name].to_s.sub(/_pedal\z/, "").sub(/_t\d+\z/, "")
  if (m = name.match(/\A([A-G][#b]?)/i))
    pc = DillaLofiMachine::NOTE_PC[m[1][0].upcase + m[1][1..].to_s.downcase]
    return 55.0 * (2.0**(((pc - 9) % 12) / 12.0)) if pc
  end
  Array(chord[:hz]).min.to_f
end

def techno_harmony_roots(bars, register: TECHNO_ACID_REGISTER)
  return nil unless techno_harmony_enabled?

  cfg = dilla_resolve_config
  pads = dilla_progression(cfg[:progression])
  roots = Array(pads).filter_map { |c| techno_chord_root_hz(c) if c.is_a?(Hash) }
                     .select(&:positive?)
  return nil if roots.length < 2

  Array.new(bars) { |b| techno_fold(roots[b % roots.length], register) }.compact
rescue StandardError => e
  dmesg_warn("techno harmony unavailable (#{e.message}), using the literal tables")
  nil
end

# One switch that forbids every pitched layer, rather than four that each
# forbid one.
#
# This exists because "no leads" took six rounds to actually achieve. Each
# attempt turned off the layer that had been named -- acid, then bleep and
# bloop, then dfam -- and the next render still had a pitched line in it,
# because the renderer has more tonal layers than anyone remembers. The list is
# acid, bleep, bloop (chirps on a per-bar note table), dfam (an 8-step PITCH
# sequence through a resonant filter), and the drone.
#
# HATE_TONAL=0 turns off all of them at once. It is a floor, not a default: the
# individual switches still work, and setting this cannot accidentally enable
# anything. test_hate_tonal_zero_silences_every_pitched_layer is the gate.
HATE_TONAL_LAYERS = %w[HATE_MELODY HATE_DFAM HATE_DRONE].freeze

def hate_forbid_tonal!
  return false if ENV.fetch("HATE_TONAL", "1") != "0"

  HATE_TONAL_LAYERS.each { |k| ENV[k] = "0" }
  true
end

def render_hate_techno(destination = File.join(ROOT, "renders", "hate_session.mp3"))
  require_tools! "ffmpeg"
  if hate_forbid_tonal!
    dmesg("HATE_TONAL=0 — melody, dfam and drone all off", unit: "techno0", parent: "dilla0")
  end
# The floor is what a render is allowed to ask for, not what it is allowed to
# sound like. Those were confused here for a long time, at real cost.
#
# demo-all asks for 0.33 minutes -- the length of the hip-hop slot beside it,
# so the two sit side by side rather than one running twice the other. Below
# half a minute this renderer used to answer with near-silence, so the floor
# was raised to 0.5 to stop it. Measured through this method, overall RMS:
#
#   HATE_MIN 0.33  ->  -47.7 dB, 26.5s   near-silent, low end at -79.4
#   HATE_MIN 0.50  ->  -13.8 dB, 53.0s   healthy overall
#   HATE_MIN 1.00  ->  -15.6 dB, 79.4s   healthy
#
# Overall RMS is the wrong instrument and 0.50 is the proof. It renders two
# blocks: the near-silent one, then a full one. Per block that is -50.5 dB
# then -14.3, and the average of those is -14.3 -- so the row above reads
# healthy while half the file is inaudible. Every techno slot in the demo has
# this shape, identical to 0.1 dB across all 27, because the dead half carries
# no progression: at position 0.0 only drone, hiss and hat have arrived.
#
# The cause was never the requested length. It is hate_position returning 0.0
# for a single block, which is fixed where it lives, so the floor no longer
# has to stand in for it: one block now renders fully arrived at -14.6 dB
# across its whole 26.5s. Measure per block, not overall, before changing
# either number -- the failure is silent and does not raise.
  minutes = (ENV["HATE_MIN"] || 16).to_f.clamp(0.1, 60.0)
  beat = 60.0 / HATE_BPM
  bar = beat * 4
  step = beat / 4
  tick = beat / MPC_PPQ
  cycle = (bar * HATE_CYCLE_BARS).round(6)
  # ...and the block floor is the second half of the same fault. With the clamp
  # fixed, 0.33 minutes asks for one block; max(.., 2) doubled it back to 53s.
  # Two blocks is right for a standalone session, where one 16-bar block is not a
  # techno track. It is wrong for a demo slot, which is a sample and not a set,
  # so the floor is a knob and demo-all sets it to 1.
  min_blocks = (ENV["HATE_MIN_BLOCKS"] || 2).to_i.clamp(1, 64)
  blocks = [(minutes * 60.0 / (bar * HATE_BLOCK_BARS)).ceil, min_blocks].max
  total = (blocks * HATE_BLOCK_BARS * bar).round(3)

  # One cycle per layer, then loop it. aeval evaluates per SAMPLE, so
  # synthesising 16 minutes directly meant tens of millions of evaluations of a
  # thirty-term expression per layer -- measured at roughly a two-hour render.
  # Each layer is built once over its eight-bar cycle instead, then looped and
  # gated. That is also how the music is actually made.

  # Dilla's pocket, on a machine grid.
  #
  # This is the fusion the engine is uniquely placed to attempt and the reason
  # the request said "use the best from Dilla". Industrial techno is quantised
  # by definition -- that rigidity is the genre. GROOVE_FEELS holds the tick
  # offsets that make an MPC lurch instead of march: on dilla_drag the snare
  # sits 4 ticks late while the hats hold the grid, so the top and the backbeat
  # disagree by about 28ms at this tempo.
  #
  # Applied here at reduced depth. A full drag at 145 BPM stops reading as a
  # pocket and starts reading as a timing error, because the bar is 40% shorter
  # than the 88 BPM these offsets were measured at. Two thirds keeps the lurch
  # and stays danceable. HATE_DILLA=0 renders it dead straight.
  feel = DillaGroove::GROOVE_FEELS[:dilla_drag]
  depth = ENV.fetch("HATE_DILLA", "1") == "0" ? 0.0 : ENV.fetch("HATE_DILLA_DEPTH", "0.66").to_f
  drag = ->(role) { ((feel[role] || 0) * depth * tick).round(6) }

  # Resolved once, up here, because three layers want it and they are built in
  # source order -- sub before acid before drone. Assigning it beside the acid
  # table left sub referencing a variable that did not exist yet, which Ruby
  # reports as a NameError at render time rather than at load.
  harmony_roots = techno_harmony_roots(HATE_CYCLE_BARS)
  if harmony_roots
    dmesg("techno harmony: #{harmony_roots.uniq.length} chord root(s) " \
          "#{harmony_roots.first(4).map { |h| h.round(1) }.join('/')}",
          unit: "techno0", parent: "dilla0")
  end

  kick_per_bar = Array.new(HATE_CYCLE_BARS) { [0, 4, 8, 12] }
  kick_per_bar[7] = [0, 4, 8, 12, 14, 15]
  ghost_per_bar = Array.new(HATE_CYCLE_BARS) { [7, 11] }        # Dilla's ghost hits
  ghost_per_bar[3] = [3, 7, 11, 15]
  clap_per_bar = Array.new(HATE_CYCLE_BARS) { [4, 12] }
  clap_per_bar[7] = [4, 12, 14]
  hat_per_bar = Array.new(HATE_CYCLE_BARS) { [2, 6, 10, 14] }
  hat_per_bar[3] = []
  hat_per_bar[5] = (0..15).step(2).to_a
  open_per_bar = Array.new(HATE_CYCLE_BARS) { [] }
  open_per_bar[3] = [14]; open_per_bar[7] = [14]
  ride_per_bar = Array.new(HATE_CYCLE_BARS) { [0, 8] }
  metal_per_bar = Array.new(HATE_CYCLE_BARS) { [] }
  metal_per_bar[1] = [7]; metal_per_bar[2] = [3, 11]; metal_per_bar[4] = [7, 13]; metal_per_bar[6] = [5]
  tom_per_bar = Array.new(HATE_CYCLE_BARS) { [] }
  tom_per_bar[5] = [9, 13]; tom_per_bar[7] = [6, 10]

  # HATE_MODERN=1 is the contemporary club pattern, not the industrial one.
  #
  # Modern techno is defined by a small number of things and the offbeat
  # open hat is the biggest: a four-on-the-floor kick with an open hat on every
  # eighth between the kicks. That single relationship is what makes a pattern
  # read as current rather than as 90s industrial, and it is why this is a
  # separate mode from HATE_INTRICATE rather than more of it.
  #
  # The rest follows from it: closed hats on straight sixteenths to fill under
  # the opens, a clap on 2 and 4 only, ghosts pulled right back because the
  # groove is meant to be driving rather than shuffled, and toms and metal
  # almost absent -- modern techno is sparse in the mids, and its weight comes
  # from the kick and the sub rather than from the number of parts.
  if ENV.fetch("HATE_MODERN", "0") != "0"
    HATE_CYCLE_BARS.times do |b|
      kick_per_bar[b] = [0, 4, 8, 12]                       # four on the floor, no variations
      open_per_bar[b] = [2, 6, 10, 14]                      # THE offbeat open hat
      hat_per_bar[b] = (0..15).step(2).to_a                  # eighths under the opens
      clap_per_bar[b] = [4, 12]                              # 2 and 4, nothing else
      ghost_per_bar[b] = b.odd? ? [7] : []                   # barely there
      ride_per_bar[b] = []
      metal_per_bar[b] = (b % 4).zero? ? [14] : []           # one accent per four bars
      tom_per_bar[b] = []
    end
    # One dropped kick every eight bars is the only variation the pattern gets.
    kick_per_bar[7] = [0, 4, 8]
  end

  # HATE_INTRICATE=1 thickens the programming without speeding it up.
  #
  # The tables above are deliberately sparse -- four kicks, two ghosts, four
  # hats, and whole bars with nothing on them. That is the right density for a
  # hypnotic set and the wrong one when the request is "much more intricate".
  #
  # Intricacy here means MORE PLACES, not more speed: sixteenth hats with gaps
  # rather than a straight run, ghosts on the odd sixteenths where a shuffle
  # lives, kick variations that differ per bar so the loop never repeats
  # exactly, toms and metal answering across bars, and rides on the offbeat.
  # Every added hit still lands on the same grid the drag is applied to, so the
  # pocket is unchanged -- it is busier, not straighter.
  if ENV.fetch("HATE_INTRICATE", "0") != "0"
    HATE_CYCLE_BARS.times do |b|
      # Kick: keep the four on the floor, add a syncopated push that moves per
      # bar so no two bars are identical.
      kick_per_bar[b] = ([0, 4, 8, 12] + [[14], [6], [3, 14], [10], [7], [2, 11], [15], [6, 14]][b % 8]).uniq.sort
      # Ghosts on odd sixteenths -- where a shuffle's ghost notes actually sit.
      ghost_per_bar[b] = ([3, 7, 11, 15] + (b.even? ? [5, 13] : [1, 9])).uniq.sort
      # Hats: eighths with holes punched in them, and the holes move.
      #
      # Sixteenths here was too much for the synthesis, not for the music: each
      # hit becomes another term in one aevalsrc expression, and 16 per bar over
      # 8 bars made ffmpeg fail the layer outright with "cannot allocate
      # memory". Eighths plus the offbeat ride below cover the same ground at
      # half the term count.
      holes = [[4], [0], [12], [8]][b % 4]
      hat_per_bar[b] = ((0..15).step(2).to_a - holes)
      # Open hat answering the clap, late in the bar.
      open_per_bar[b] = b.odd? ? [14] : [7]
      # Ride on the offbeat eighths rather than the downbeats.
      ride_per_bar[b] = [2, 6, 10, 14]
      # Metal and toms trade bars so something new arrives every two.
      metal_per_bar[b] = b.even? ? [5, 13] : [3, 9]
      tom_per_bar[b] = b.odd? ? [6, 10, 14] : [9]
    end
    # Claps keep the backbeat and gain a flam on the turnaround.
    clap_per_bar[3] = [4, 12, 13]
    clap_per_bar[7] = [4, 12, 14, 15]
  end

  # A hat line on an 11-step cycle against a 16-step bar, so it only meets the
  # downbeat every 11 bars. This is the polymeter facility built earlier today;
  # its first use was a hi-hat in a hip-hop track, and it belongs here more --
  # the whole hypnotic quality of this genre is a pattern you cannot quite
  # count.
  poly_hits = (0...(HATE_CYCLE_BARS * 16)).select { |s| DillaGroove.polymeter_steps(s / 16, cycle: 11, pulses: 7).include?(s % 16) }

  at = ->(b, s, role = nil) { (((b * bar) + (s * step)) + (role ? drag.call(role) : 0)).round(6) }
  gather = lambda do |rows, role = nil|
    HATE_CYCLE_BARS.times.flat_map { |b| rows[b].map { |s| at.call(b, s, role) } }
  end
  env = lambda do |times, len, decay|
    return "0" if times.empty?

    times.map { |t| "between(t,#{t},#{(t + len).round(6)})*exp(-(t-#{t})*#{decay})" }.join("+")
  end

  work = scratch_path("hate")
  FileUtils.rm_rf(work)
  FileUtils.mkdir_p(work)
  parts = {}

  # The record goes in first so it is the floor the rest is built on, and so a
  # failure to prepare it costs the bed rather than the whole render.
  if (bed_path = techno_bed_part!(work, cycle))
    parts[:bed] = bed_path
  end

  # -af takes a linear chain; anything with named pads -- an asplit into a wet
  # branch and back -- is a graph and needs -filter_complex. Detected rather
  # than declared per call site, because getting it wrong fails the whole layer
  # and the error ffmpeg gives points at the expression, not at the flag.
  tone = lambda do |name, expr, chain|
    parts[name] = File.join(work, "#{name}.wav")
    src = ["-f", "lavfi", "-i", "aevalsrc='#{expr}':s=#{SAMPLE_RATE}:d=#{cycle}"]
    body = "aformat=channel_layouts=stereo,#{chain}"
    args = if chain.include?("[")
             ["-filter_complex", "[0:a]#{body}[o]", "-map", "[o]"]
           else
             ["-af", body]
           end
    sh! "ffmpeg", "-y", "-v", "error", *src, *args, "-c:a", "pcm_s16le", parts[name]
  end
  noise = lambda do |name, colour, times, len, decay, gain, chain|
    parts[name] = File.join(work, "#{name}.wav")
    if times.empty?
      sh!("ffmpeg", "-y", "-v", "error", "-f", "lavfi", "-i", "anullsrc=r=#{SAMPLE_RATE}:cl=stereo:d=#{cycle}",
          "-c:a", "pcm_s16le", parts[name])
    else
      sh! "ffmpeg", "-y", "-v", "error", "-f", "lavfi",
          "-i", "anoisesrc=color=#{colour}:r=#{SAMPLE_RATE}:amplitude=0.9:d=#{cycle}:seed=#{noise_seed(41)}",
          "-af", "aformat=channel_layouts=stereo,volume='(#{env.call(times, len, decay)})*#{gain}':eval=frame,#{chain}",
          "-c:a", "pcm_s16le", parts[name]
    end
  end

  hit = ->(t, len, amp, decay, body) { "between(t,#{t},#{(t + len).round(6)})*#{amp}*exp(-(t-#{t})*#{decay})*#{body}" }

  # KICK. Grit before punch: bit-crush and saturate first, compress after.
  # Compressing a clean kick and distorting the result gives a loud clean kick,
  # which is not this genre. asubboost adds the sub the speaker cabinet would.
  tone.call(:kick,
            gather.call(kick_per_bar, :kick).map { |t|
              hit.call(t, 0.22, 0.98, 7, "sin(2*PI*(58*(t-#{t})+190*(t-#{t})*exp(-(t-#{t})*26)))")
            }.join("+"),
            "acrusher=bits=10:samples=1:mix=0.22," \
            "asoftclip=type=tanh:threshold=0.72:output=0.9:oversample=4," \
            "acompressor=threshold=-12dB:ratio=9:attack=1:release=38:makeup=4," \
            "asubboost=dry=0.9:wet=0.4:decay=0.6:feedback=0.5:cutoff=90," \
            "equalizer=f=58:t=o:w=0.8:g=5,lowpass=f=7000")

  # GHOST KICK. Dilla's ghosts, at a fifth of the level, nudged 2 ticks late so
  # they lean rather than land.
  tone.call(:ghost,
            gather.call(ghost_per_bar, :ghost).map { |t|
              hit.call(t, 0.1, 0.24, 16, "sin(2*PI*(64*(t-#{t})+120*(t-#{t})*exp(-(t-#{t})*30)))")
            }.join("+"),
            "asoftclip=type=atan:threshold=0.6:oversample=4,lowpass=f=2400,pan=stereo|c0=0.9*c0|c1=1.0*c1")

  # The sub takes the tonic rather than a per-bar root. A sub that moves with
  # every chord stops reading as the floor of the record and starts reading as a
  # bassline, which is a different instrument and not this one's job.
  sub_hz = (harmony_roots && techno_fold(harmony_roots.first, TECHNO_SUB_REGISTER)) || 41
  tone.call(:sub,
            gather.call(kick_per_bar, :kick).map { |t|
              hit.call(t, 0.42, 0.5, 4, "sin(2*PI*#{sub_hz}*(t-#{t}))")
            }.join("+"),
            "lowpass=f=90,virtualbass=cutoff=110:strength=0.6")

  # ACID. The only melodic content. Frequency-shifted rather than pitch-shifted
  # on the wet side -- afreqshift moves every partial by the same number of Hz
  # instead of the same ratio, so the harmonic series stops being harmonic and
  # the result reads as metal rather than as a note. That is the futurist trick
  # this style leans on and it has no analogue on a keyboard.
  acid_steps = [0, 6, 10, 14]
  # The literal table is the fallback, not the definition: with TECHNO_HARMONY=1
  # these become the progression's chord roots, one per bar of the cycle, folded
  # into the same register the table already sat in (A1 to G2).
  acid_notes = harmony_roots || [55.00, 55.00, 58.27, 55.00, 65.41, 55.00, 58.27, 51.91]
  # HATE_MELODY=0 drops it entirely. The acid IS the only melodic content here,
  # so with it off the piece is drums, drone and texture -- which is a real
  # setting for this genre, not a broken render.
  if ENV.fetch("HATE_MELODY", "1") != "0"
  tone.call(:acid,
            HATE_CYCLE_BARS.times.flat_map { |b|
              acid_steps.map { |s| hit.call(at.call(b, s), 0.16, 0.55, 11, "sin(2*PI*#{acid_notes[b]}*(t-#{at.call(b, s)}))") }
            }.join("+"),
            "asoftclip=type=tanh:threshold=0.35:output=0.85:oversample=4," \
            "asplit=2[ad][aw];" \
            "[aw]afreqshift=shift=63,volume=0.34[af];" \
            "[ad][af]amix=inputs=2:normalize=0," \
            "bandpass=f=520:w=760," \
            "aphaser=speed=0.12:decay=0.5:delay=2.6," \
            "aecho=0.7:0.55:#{(step * 3000).round}|#{(step * 6000).round}:0.4|0.22")
  end

  # PAULSTRETCH WASH. Texture where the melody was.
  #
  # Paulstretch's signature is not slowness, it is the absence of any transient:
  # magnitudes kept, phase thrown away, so a source becomes a cloud that has no
  # attack anywhere in it and no rhythm to read. There is no rubberband filter
  # in this ffmpeg and no paulstretch anywhere, but the effect does not need a
  # time-stretch when the source is synthesised -- write the sustain directly
  # and destroy the phase.
  #
  # Two windows rather than one. 8192 with 0.9 overlap is long enough that
  # everything inside it averages into a wash; 1024 underneath keeps a trace of
  # movement so the layer does not sit completely still for two minutes. The
  # slow pulsator pair beat against each other at 0.06 and 0.09 Hz, which is
  # under a cycle per ten seconds -- swell, not wobble.
  #
  # apulsator and not tremolo for those: tremolo's `f` floor is 0.1 Hz, and a
  # refused filter does not degrade quietly, it fails the whole chain and takes
  # the layer with it. Measured -- tremolo=f=0.06 killed paulwash outright with
  # "error applying option 'f' to filter 'tremolo': result too large".
  # apulsator accepts down to 0.01 Hz.
  if ENV.fetch("HATE_PAULSTRETCH", "1") != "0"
    pw_root = (harmony_roots&.first || 55.0) * 4
    pw = [pw_root, pw_root * 1.5, pw_root * (2**(10.0 / 12.0)), pw_root * 2].map { |h| h.round(2) }
    # win_size in SAMPLES here, but Paulstretch specifies its window in seconds
    # and wants it long: 0.25s upward, because a short window reads as grain and
    # a long one is what produces the slow spectral pad. 32768 at 44.1k is
    # 0.74s. The first attempt used 8192 (0.19s), which is the grainy end.
    pw_win = ENV.fetch("HATE_PAULSTRETCH_WIN", "32768").to_i
    # Phase must be RANDOM, not a function of the bin index. cos(b) is a fixed
    # pattern across bins -- deterministic, and it re-imposes a structure that
    # the whole point of this is to destroy. random(n) in ffmpeg's expression
    # evaluator returns [0,1) and advances its own state per call.
    scramble = "afftfilt=real='hypot(re,im)*cos(random(1)*6.2832)':" \
               "imag='hypot(re,im)*sin(random(2)*6.2832)':" \
               "win_size=#{pw_win}:overlap=0.9"
    # +26 dB of makeup, measured not guessed. Randomising phase makes partials
    # cancel instead of sum, and the chain was measured at 26.3 dB of loss
    # (-19.9 dB source -> -46.2 dB out). Without this the layer renders, reports
    # as a layer, and is inaudible in the mix -- the first version of this
    # nulled against the melody-less render at -46 dB, i.e. it did nothing.
    # Noise, not chord tones.
    #
    # The first version built this from root/5th/b7/octave and smeared those.
    # Smearing a chord does not stop it being a chord -- it is a sustained pad
    # playing the harmony, i.e. keys, which is exactly what was asked to go.
    # Paulstretch on NOISE has no pitch to hear at all: the magnitudes are
    # broadband, the phase is random, and what is left is air and movement.
    # Shaped by the bandpass below rather than by a note.
    tone.call(:paulwash,
              "0.25*(random(0)*2-1)",
              "#{scramble},#{scramble}," \
              "bandpass=f=900:width_type=h:width=1600," \
              "highpass=f=140,lowpass=f=6000," \
              "apulsator=hz=0.06:amount=0.45:offset_r=0.5," \
              "apulsator=hz=0.09:amount=0.25:offset_r=0.25," \
              "chorus=0.6:0.9:50|70|90:0.4|0.32|0.3:0.25|0.4|0.3:2|2.3|1.3," \
              "aphaser=speed=0.15:decay=0.55:delay=3.0," \
              "aecho=0.8:0.9:#{(step * 7000).round}|#{(step * 11000).round}:0.55|0.4," \
              "aecho=0.7:0.8:#{(step * 17000).round}|#{(step * 23000).round}:0.4|0.3," \
              "stereowiden=delay=32:feedback=0.5:crossfeed=0.4:drymix=0.6," \
              "volume=#{ENV.fetch('HATE_PAULSTRETCH_GAIN', '43')}dB")
  end

  # WEIRD. The deliberately wrong one.
  #
  # afreqshift moves every partial by the same NUMBER of Hz instead of the same
  # ratio, so the harmonic series stops being harmonic -- the same trick the
  # acid used on its wet side, but here it is the whole signal and the shift is
  # large enough that no pitch survives it. Then flanger and a phaser on top of
  # that, so what is left drifts. aphaser's speed floor is 0.1; below it the
  # filter refuses to configure and refusing one filter kills the entire chain,
  # so 0.12 is deliberate and not a rounding.
  if ENV.fetch("HATE_WEIRD", "1") != "0"
    w_root = (harmony_roots&.first || 55.0) * 2
    # Noise here too, for the same reason paulwash is noise: a shifted sine is
    # still a pitch, and the brief was no keys. The two slow AM terms stay --
    # they are what makes it breathe rather than sit -- but they now modulate
    # broadband noise instead of a note.
    tone.call(:weird,
              "0.2*(random(3)*2-1)*(0.5+0.5*sin(2*PI*0.7*t))*" \
              "(0.6+0.4*sin(2*PI*0.23*t))",
              "afreqshift=shift=#{(37 + (w_root % 23)).round}," \
              "flanger=delay=14:depth=8:regen=45:speed=0.13," \
              "aphaser=speed=0.12:decay=0.6:delay=3.2," \
              "asoftclip=type=tanh:threshold=0.4:output=0.7:oversample=4," \
              "bandpass=f=1400:width_type=h:width=2200," \
              "crystalizer=i=3," \
              "aecho=0.6:0.7:#{(step * 4500).round}|#{(step * 9000).round}:0.45|0.3," \
              "stereowiden=delay=18:feedback=0.4:crossfeed=0.3:drymix=0.7," \
              "volume=#{ENV.fetch('HATE_WEIRD_GAIN', '22')}dB")
  end

  # DRONE. A dark bed under everything, built from two detuned saws a beat
  # apart so it beats slowly against itself, then spectrally smeared.
  # Detune ratio preserved, not the literal pair. 36.95/36.71 is 1.00654, and it
  # is the ratio that makes the two saws beat slowly against each other -- moving
  # the drone to a new tonic has to carry that interval with it or the beating
  # either disappears or turns into a chord.
  drone_hz = (harmony_roots && techno_fold(harmony_roots.first, TECHNO_DRONE_REGISTER)) || 36.71
  drone_detuned = (drone_hz * 1.00654).round(2)
  # The drone had no switch of its own until now. It is two detuned saws on a
  # tonic -- pitched, however smeared -- so HATE_TONAL has to be able to reach
  # it or "no tonal layers" is not true.
  if ENV.fetch("HATE_DRONE", "1") != "0"
  tone.call(:drone,
            "0.13*(sin(2*PI*#{drone_hz}*t)+sin(2*PI*#{drone_detuned}*t)+" \
            "0.5*sin(2*PI*#{(drone_hz * 2).round(2)}*t))",
            # Phase randomised per bin while the magnitudes are kept: the
            # spectral smear that turns two detuned saws into a wash with no
            # attack anywhere in it. afftfilt works per BIN, not per sample --
            # its expressions have no `t`, which is what the first attempt at
            # this assumed and why the whole layer failed to configure.
            "afftfilt=real='hypot(re,im)*cos(b)':imag='hypot(re,im)*sin(b)':win_size=2048:overlap=0.8," \
            "lowpass=f=1200,tremolo=f=0.14:d=0.28,stereowiden=delay=22:feedback=0.4:crossfeed=0.35:drymix=0.7")
  end

  # DFAM. Dual-oscillator FM percussion on an 8-step pitch sequence.
  #
  # The Moog DFAM is a semi-modular percussion synth whose whole character is
  # that pitch and decay move per STEP -- one knob row for pitch, another for
  # velocity, eight steps each -- so a single voice walks through a phrase
  # instead of repeating one sound. That is what industrial techno is built out
  # of, and DfamEngine has held the semantics all along: dual-osc FM, noise
  # blend, resonant lowpass, per-step pitch and velocity.
  #
  # It was reachable only from render_dilla, where it sits under hip-hop drums.
  # Here it is the machine in the room.
  #
  # The sequence runs at 8 steps against the bar's 16, so it turns over twice a
  # bar and lands differently against the kick each time. Pitch 0-100 from the
  # engine maps onto 45-360 Hz: percussion register, not melody.
  dfam_patch = DfamEngine.resolve_patch
  dfam_pattern = DfamEngine.resolve_pattern(seed: (@render_seed || 0) + stable_hash("hate"))
  fm_index = dfam_patch[:fm_pct] / 100.0 * 6.0
  dfam_decay = 1000.0 / [dfam_patch[:decay_ms], 40].max
  dfam_sig = (0...(HATE_CYCLE_BARS * 2)).map do |i|
    idx = i % DfamEngine::STEPS
    t0 = ((i * bar) / 2.0).round(6)
    pitch = dfam_pattern[:pitch][idx]
    vel = dfam_pattern[:velocity][idx] / 100.0
    f1 = (45.0 + (pitch / 100.0 * 315.0)).round(2)
    f2 = (f1 * (dfam_patch[:osc2_hz].to_f / [dfam_patch[:osc1_hz], 1].max)).round(2)
    dt = "(t-#{t0})"
    body = "sin(2*PI*#{f1}*#{dt}+#{fm_index.round(3)}*sin(2*PI*#{f2}*#{dt}))"
    "between(t,#{t0},#{(t0 + 0.4).round(6)})*#{(0.42 * vel).round(3)}*exp(-#{dt}*#{dfam_decay.round(2)})*#{body}"
  end.join("+")
  # Its own gate, not HATE_MELODY's.
  #
  # It was briefly folded into HATE_MELODY because an 8-step PITCH sequence
  # through a resonant filter does read as a line. But this is the machine the
  # whole genre is built on and the operator wants it forward, so it gets
  # HATE_DFAM instead: melody off and DFAM heavy is a real combination, and one
  # switch could not express it.
  #
  # HATE_DFAM_HEAVY pushes it from an element to the loudest thing in the room:
  # the resonance goes up, the softclip becomes drive rather than polish, a
  # bitcrusher takes the edges off the sample rate, and the echo gets long
  # enough to blur into the next hit.
  if ENV.fetch("HATE_DFAM", "1") != "0"
  heavy = ENV.fetch("HATE_DFAM_HEAVY", "0") != "0"
  dfam_res = (dfam_patch[:res_pct] / 100.0 * (heavy ? 14 : 8) + 0.7).round(2)
  dfam_tail = if heavy
                "acrusher=bits=9:samples=2:mix=0.35," \
                "afreqshift=shift=27," \
                "aecho=0.8:0.7:#{(step * 2000).round}|#{(step * 4000).round}|#{(step * 7000).round}:0.5|0.32|0.18," \
                "aphaser=speed=0.22:decay=0.5:delay=2.4," \
                "stereotools=slev=1.8,volume=7dB"
              else
                "aecho=0.7:0.5:95|185:0.3|0.17,stereotools=slev=1.4"
              end
  tone.call(:dfam, dfam_sig,
            # The resonant lowpass is the other half of the instrument: a
            # 12dB/oct sweep with the resonance up, which is what gives a DFAM
            # hit its pitched ring rather than a flat thud.
            "lowpass=f=#{dfam_patch[:filter_hz]}:width_type=q:width=#{dfam_res}," \
            "asoftclip=type=atan:threshold=#{heavy ? '0.32' : '0.55'}:output=#{heavy ? '1.0' : '0.9'}:oversample=4," \
            "#{dfam_tail}")
  end

  # Long chains on the drums.
  #
  # Each of these was three or four stages: shape it, echo it, place it. Written
  # out as arrays because at eight or nine stages a single string stops being
  # readable, and the order matters more than any individual value -- saturate
  # before you compress and you get grit, after and you get a loud clean hit.
  #
  # The shape of each chain is the same: BAND (what part of the noise this drum
  # is) -> DAMAGE (crush, saturate, frequency-shift) -> MOVEMENT (phaser,
  # flanger, tremolo, so it is never twice the same) -> SPACE (echo, then
  # placement). Damage before movement, because modulating a clean signal sounds
  # like an effect and modulating a broken one sounds like a machine.
  drum_chain = ->(stages) { stages.compact.join(",") }

  noise.call(:clap, "white", gather.call(clap_per_bar, :snare), 0.05, 34, 0.55,
             drum_chain.call([
               "bandpass=f=1600:w=2200",
               "acrusher=bits=12:samples=2:mix=0.3",
               "asoftclip=type=atan:threshold=0.6:output=0.9:oversample=4",
               "flanger=delay=2:depth=3:regen=40:speed=0.3",
               "adynamicequalizer=dfrequency=1800:tfrequency=1800:threshold=0.1:ratio=4",
               "aecho=0.6:0.45:37|74|151:0.28|0.18|0.09",
               "haas=level_in=1:level_out=1:side_gain=0.8:left_delay=2.6:right_delay=4.1",
               "stereotools=slev=1.3",
             ]))

  noise.call(:hat, "white", gather.call(hat_per_bar, :hat), 0.035, 80, 0.32,
             drum_chain.call([
               "highpass=f=8500",
               "acrusher=bits=9:samples=1:mix=0.22",
               "aphaseshift=shift=0.25",
               "tremolo=f=7.3:d=0.22",
               "aecho=0.5:0.3:29|61:0.2|0.1",
               "pan=stereo|c0=0.85*c0|c1=1.0*c1",
             ]))

  noise.call(:poly, "white", poly_hits.map { |s| ((s / 16) * bar) + ((s % 16) * step) }, 0.03, 95, 0.2,
             drum_chain.call([
               "bandpass=f=6200:w=3000",
               "afreqshift=shift=210",
               "acrusher=bits=8:samples=2:mix=0.35",
               "pan=stereo|c0=0.55*c0|c1=1.0*c1",
               "aecho=0.6:0.4:91|187:0.24|0.12",
               "adecorrelate=stages=3",
             ]))

  noise.call(:open, "white", gather.call(open_per_bar, :hat), 0.45, 9, 0.26,
             drum_chain.call([
               "bandpass=f=7200:w=5200",
               "aphaser=speed=0.5:decay=0.6:delay=3",
               "adecorrelate=stages=4",
               "aecho=0.7:0.55:230|470:0.32|0.18",
               "stereowiden=delay=15:feedback=0.4:crossfeed=0.3:drymix=0.7",
             ]))

  noise.call(:ride, "white", gather.call(ride_per_bar, :hat), 1.6, 2.4, 0.13,
             drum_chain.call([
               "bandpass=f=5400:w=2600",
               "aexciter=level_in=1:level_out=1:amount=2:blend=2:freq=7500",
               "chorus=0.6:0.9:50|60:0.4|0.32:0.25|0.4:2|2.3",
               "aecho=0.8:0.7:410|790|1290:0.4|0.24|0.12",
               "stereotools=mlev=0.7:slev=1.5",
             ]))

  noise.call(:metal, "white", gather.call(metal_per_bar), 0.9, 5, 0.30,
             drum_chain.call([
               "bandpass=f=3100:w=260",
               "bandpass=f=4700:w=200",
               "afreqshift=shift=-37",
               "acrusher=bits=10:samples=3:mix=0.4",
               "flanger=delay=4:depth=6:regen=60:speed=0.14",
               "aecho=0.8:0.7:170|330|610|1130:0.5|0.32|0.18|0.09",
               "highpass=f=900",
               "stereotools=slev=1.8",
             ]))

  noise.call(:tom, "brown", gather.call(tom_per_bar, :ghost), 0.5, 7, 0.34,
             drum_chain.call([
               "bandpass=f=180:w=140",
               "asoftclip=type=atan:threshold=0.7:oversample=4",
               "asubboost=dry=0.9:wet=0.35:decay=0.5:feedback=0.4:cutoff=120",
               "aphaser=speed=0.2:decay=0.5:delay=3.4",
               "aecho=0.7:0.5:130|260|520:0.3|0.16|0.08",
               "stereotools=slev=1.2",
             ]))

  # BLEEPS AND BLOOPS.
  #
  # The Flying Lotus register: short pitched blips that bend as they sound, sat
  # in a lot of delay, panned hard and never quite where the grid is. On
  # Cosmogramma they are the thing that stops a beat being a beat and makes it
  # sound like a broken transmission.
  #
  # A bleep bends UP and a bloop bends DOWN -- that is the whole difference, and
  # the reason both words exist. The bend is inside the sine's phase argument
  # rather than applied afterwards, so the pitch really moves during the note
  # instead of the note being pitch-shifted as a block.
  #
  # Placed on the odd sixteenths the drums leave alone, so they answer the kit
  # rather than doubling it.
  bleep_steps = [3, 7, 11, 15]
  bloop_steps = [5, 13]
  bleep_freqs = [880.0, 1174.7, 987.8, 1318.5, 1046.5, 784.0, 1396.9, 659.3]

  # bleep and bloop are pitched too -- chirps on a per-bar note from
  # bleep_freqs, which is a melody whatever it is called. HATE_MELODY=0 has to
  # take all three or the line is still there: dropping only :acid left these
  # playing and the operator still heard a top line.
  if ENV.fetch("HATE_MELODY", "1") != "0"
  tone.call(:bleep,
            HATE_CYCLE_BARS.times.flat_map { |b|
              bleep_steps.each_slice(2).map(&:first).map { |s|
                t0 = at.call(b, s)
                f = bleep_freqs[b]
                dt = "(t-#{t0})"
                # +40% over the note: a rising chirp, not a tone.
                "between(t,#{t0},#{(t0 + 0.09).round(6)})*0.3*exp(-#{dt}*22)*" \
                  "sin(2*PI*(#{f}*#{dt}+#{(f * 0.4).round(1)}*#{dt}*#{dt}))"
              }
            }.join("+"),
            drum_chain.call([
              "acrusher=bits=7:samples=1:mix=0.45",
              "highpass=f=500",
              "aecho=0.7:0.6:#{(step * 1500).round}|#{(step * 3000).round}|#{(step * 4500).round}:0.42|0.26|0.14",
              "aphaser=speed=0.9:decay=0.55:delay=2",
              "pan=stereo|c0=1.0*c0|c1=0.35*c1",
              "stereotools=slev=1.6",
            ]))

  tone.call(:bloop,
            HATE_CYCLE_BARS.times.flat_map { |b|
              bloop_steps.map { |s|
                t0 = at.call(b, s)
                f = (bleep_freqs[b] / 2.0).round(2)
                dt = "(t-#{t0})"
                # Falling: the bend term is negative and the note is longer.
                "between(t,#{t0},#{(t0 + 0.22).round(6)})*0.26*exp(-#{dt}*9)*" \
                  "sin(2*PI*(#{f}*#{dt}-#{(f * 0.55).round(1)}*#{dt}*#{dt}))"
              }
            }.join("+"),
            drum_chain.call([
              "acrusher=bits=8:samples=2:mix=0.3",
              "lowpass=f=3200",
              "afreqshift=shift=-19",
              "aecho=0.7:0.55:#{(step * 2000).round}|#{(step * 5000).round}:0.4|0.2",
              "pan=stereo|c0=0.35*c0|c1=1.0*c1",
              "stereowiden=delay=20:feedback=0.45:crossfeed=0.35:drymix=0.65",
            ]))
  end

  # HYDRAULIC HISS. A slow breath rather than a hit.
  #
  # The afftfilt stage combs the spectrum by BIN rather than sweeping across
  # time: its expressions have no `t`, which the first attempt assumed and which
  # failed the whole layer to configure. Comment kept out of the string
  # continuation below -- a `#` line between two `\` continuations ends the
  # expression and takes the rest of the call with it.
  hiss_chain = [
    "aformat=channel_layouts=stereo",
    "volume='0.055+0.055*sin(2*PI*t/#{(bar * 2).round(3)})':eval=frame",
    "highpass=f=2400,lowpass=f=11000",
    "afftfilt=real='re*(0.45+0.55*sin(b/18))':imag='im*(0.45+0.55*sin(b/18))':win_size=1024",
    "aecho=0.7:0.6:220|450:0.35|0.2",
    "stereowiden=delay=18:feedback=0.5:crossfeed=0.4:drymix=0.6",
  ].join(",")
  parts[:hiss] = File.join(work, "hiss.wav")
  sh! "ffmpeg", "-y", "-v", "error", "-f", "lavfi",
      "-i", "anoisesrc=color=pink:r=#{SAMPLE_RATE}:amplitude=0.9:d=#{cycle}:seed=#{noise_seed(42)}",
      "-af", hiss_chain, "-c:a", "pcm_s16le", parts[:hiss]

  # Loop, gate, and open the filter as the set builds.
  loops = (total / cycle).ceil + 1
  inputs = parts.keys.flat_map { |k| ["-stream_loop", loops.to_s, "-i", parts[k]] }
  chains = parts.keys.each_with_index.map do |k, i|
    gate = hate_gate(k, blocks, bar)
    stage = gate == "1" ? "anull" : "volume='#{gate}':eval=frame"
    "[#{i}:a]atrim=0:#{total},asetpts=PTS-STARTPTS,#{stage}[l#{i}]"
  end
  mix = parts.keys.each_index.map { |i| "[l#{i}]" }.join

  # MASTER. A console chain rather than a limiter: dynamic EQ holding the low
  # mid, a slow bus compressor that breathes with the kick, tape saturation,
  # crossfeed so the width survives headphones, then the limiter last.
  master = "highpass=f=26," \
           "adynamicequalizer=dfrequency=220:dqfactor=1.2:tfrequency=220:tqfactor=1.2:threshold=0.08:ratio=3," \
           "acompressor=threshold=-15dB:ratio=7:attack=2:release=60:makeup=3.5," \
           "asoftclip=type=tanh:threshold=0.86:output=0.95:oversample=4," \
           "aexciter=amount=1.2:blend=1:freq=6800," \
           "crossfeed=strength=0.32:range=0.6," \
           "alimiter=limit=0.96:level_out=0.94"

  graph = "#{chains.join(';')};#{mix}amix=inputs=#{parts.length}:duration=longest:normalize=0,#{master}[out]"

  FileUtils.mkdir_p(File.dirname(destination))
  dmesg("hate: #{HATE_BPM.round} BPM, #{parts.length} layers, #{blocks} blocks, #{(total / 60).round(1)} min, " \
        "dilla drag #{(depth * 100).round}%", unit: "techno0", parent: "dilla0")
  sh! "ffmpeg", "-y", "-v", "error", *inputs, "-filter_complex", graph,
      "-map", "[out]", "-t", total.to_s, "-c:a", "libmp3lame", "-b:a", "256k", destination
  FileUtils.rm_rf(work)
  normalise_genre_master!(destination, :techno)
  puts "wrote #{destination}"
  destination
end
def render_techno(destination = File.join(OUTPUT_DIR, "techno_hate.mp3"))
  require_tools! "ffmpeg"
  n_bars = [bars, TECHNO_BARS].max
  beat = 60.0 / TECHNO_BPM
  bar = beat * 4
  step = beat / 4
  total = (bar * n_bars).round(3)

  kick_per_bar = Array.new(TECHNO_BARS) { [0, 4, 8, 12] }
  kick_per_bar[7] = [0, 4, 8, 12, 14, 15]
  clap_per_bar = Array.new(TECHNO_BARS) { [4, 12] }
  clap_per_bar[3] = [4, 12, 14]; clap_per_bar[7] = [4, 10, 12, 14]
  hat_per_bar = Array.new(TECHNO_BARS) { [2, 6, 10, 14] }
  hat_per_bar[3] = []; hat_per_bar[5] = [0, 2, 4, 6, 8, 10, 12, 14]
  open_per_bar = Array.new(TECHNO_BARS) { [] }
  open_per_bar[3] = [14]; open_per_bar[7] = [14]
  acid_steps = [0, 3, 6, 8, 11, 14]
  bass_notes = [65.41, 65.41, 87.31, 65.41, 98.00, 98.00, 87.31, 65.41]

  cycle = (bar * TECHNO_BARS).round(6)
  kicks = TECHNO_BARS.times.flat_map { |b| kick_per_bar[b].map { |s| (b * bar + s * step).round(6) } }
  claps = TECHNO_BARS.times.flat_map { |b| clap_per_bar[b].map { |s| (b * bar + s * step).round(6) } }
  hats = TECHNO_BARS.times.flat_map { |b| hat_per_bar[b].map  { |s| (b * bar + s * step).round(6) } }
  opens = TECHNO_BARS.times.flat_map { |b| open_per_bar[b].map { |s| (b * bar + s * step).round(6) } }
  acid_hits = TECHNO_BARS.times.flat_map { |b| bass_notes[b].then { |f| acid_steps.map { |s| [(b * bar + s * step).round(6), f] } } }

  kick_sig = kicks.map do |t|
    tm = (t % cycle).round(6)
    dt = "mod(t,#{cycle})-#{tm}"
    "between(mod(t,#{cycle}),#{tm},#{(tm + 0.18).round(6)})*0.95*exp(-#{dt}*8)*sin(2*PI*(110*#{dt}-250*#{dt}*#{dt}))"
  end
  acid_sig = acid_hits.map do |(t, f)|
    tm = (t % cycle).round(6)
    dt = "mod(t,#{cycle})-#{tm}"
    "between(mod(t,#{cycle}),#{tm},#{(tm + 0.14).round(6)})*0.6*exp(-#{dt}*9)*sin(2*PI*#{f}*#{dt})"
  end
  clap_env = claps.flat_map do |t|
    tm = (t % cycle).round(6)
    t1 = (tm + 0.012).round(6); t2 = (tm + 0.024).round(6)
    dt0 = "mod(t,#{cycle})-#{tm}"; dt1 = "mod(t,#{cycle})-#{t1}"; dt2 = "mod(t,#{cycle})-#{t2}"
    ["between(mod(t,#{cycle}),#{tm},#{(tm + 0.04).round(6)})*exp(-#{dt0}*40)",
     "between(mod(t,#{cycle}),#{t1},#{(t1 + 0.04).round(6)})*exp(-#{dt1}*50)",
     "between(mod(t,#{cycle}),#{t2},#{(t2 + 0.05).round(6)})*exp(-#{dt2}*30)"]
  end
  hat_env = hats.map  { |t| tm = (t % cycle).round(6); dt = "mod(t,#{cycle})-#{tm}"; "between(mod(t,#{cycle}),#{tm},#{(tm + 0.04).round(6)})*exp(-#{dt}*70)" }
  opn_env = opens.map { |t| tm = (t % cycle).round(6); dt = "mod(t,#{cycle})-#{tm}"; "between(mod(t,#{cycle}),#{tm},#{(tm + 0.5).round(6)})*exp(-#{dt}*10)" }

  filt = <<~F
    [0:a]aformat=channel_layouts=stereo,equalizer=f=55:t=o:w=0.7:g=4,
         aeval='tanh(val(0)*2.5)/tanh(2.5)|tanh(val(1)*2.5)/tanh(2.5)',
         acompressor=threshold=-10dB:ratio=6:attack=1:release=40:makeup=3[kick];
    [1:a]aformat=channel_layouts=stereo,
         aeval='tanh(val(0)*3.5)/tanh(3.5)|tanh(val(1)*3.5)/tanh(3.5)',
         equalizer=f=300:t=o:w=2:g=3,equalizer=f=1500:t=o:w=2:g=4,
         lowpass=f=4000[acid];
    [2:a]aformat=channel_layouts=stereo,asplit=3[nc][nh][no];
    [nc]volume='#{safe_volume_env(clap_env)}*0.6':eval=frame,bandpass=f=1500:w=2000,
        aecho=0.5:0.4:30|60:0.2|0.1[clap];
    [nh]volume='#{safe_volume_env(hat_env)}*0.4':eval=frame,highpass=f=8000[hat];
    [no]volume='#{safe_volume_env(opn_env)}*0.3':eval=frame,bandpass=f=7000:w=5000[open];
    [kick][acid][clap][hat][open]amix=inputs=5:weights=1.4 1.0 0.7 0.5 0.4:duration=longest[drums];
    [drums]highpass=f=30,acompressor=threshold=-14dB:ratio=8:attack=1:release=50:makeup=4[drums_comp];
    [drums_comp]aeval='tanh(val(0)*1.8)/tanh(1.8)|tanh(val(1)*1.8)/tanh(1.8)'[drums_sat];
    [drums_sat]equalizer=f=80:t=o:w=0.8:g=2,equalizer=f=8000:t=o:w=2:g=2[master_eq];
    [master_eq]alimiter=level_in=1.0:level_out=0.90:limit=0.85:attack=2:release=20[out]
  F

  FileUtils.mkdir_p(File.dirname(destination))
  sh! "ffmpeg", "-y",
      *lavfi("aevalsrc='#{expr_sum(kick_sig)}':d=#{total}:s=#{SAMPLE_RATE}"),
      *lavfi("aevalsrc='#{expr_sum(acid_sig)}':d=#{total}:s=#{SAMPLE_RATE}"),
      *lavfi("anoisesrc=color=white:r=#{SAMPLE_RATE}:amplitude=0.5:d=#{total}:seed=#{noise_seed(19)}"),
      "-filter_complex", filt.tr("\n", " "), "-map", "[out]", "-b:a", "320k", destination
  normalise_genre_master!(destination, :techno)
  puts "wrote #{destination}"
end

# --------------------------------------------------------------------------
# engine part: mix_recipes
# --------------------------------------------------------------------------
#
# The v7-v11 vocal mix recipes and stem preparation.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# =============================================================================
# VOCAL MIXES v7–v11 (make.rb)
# =============================================================================

def mix_out_path(ver)
  File.join(OUTPUT_DIR, "final_mix_#{ver}.mp3")
end

def mix_tmp(ver, name)
  "/tmp/#{ver}_#{name}.wav"
end

def mix_loop_beat
  ["-stream_loop", "-1", "-i", VOICEMAILS_BEAT, "-t", MIX_DUR.to_s]
end

def mix_beat_ms(bpm)
  (60_000 / bpm).to_i
end

def mix_dotted_8th(bpm)
  (mix_beat_ms(bpm) * 0.75).to_i
end

def mix_half(bpm)
  (mix_beat_ms(bpm) * 2).to_i
end

def mix_render(label, dest, inputs:, filter:, map:, args: ["-ar", "44100"])
  puts ">>> #{label}"
  sh! "ffmpeg", "-y", *inputs, "-filter_complex", filter.tr("\n", " "), "-map", map, *args, dest
end

def mix_v7
  ver = "v7"; d8 = mix_dotted_8th(MIX_BPM)
  beat_pre, vocals_pre, crackle = mix_tmp(ver, "beat"), mix_tmp(ver, "vocals"), mix_tmp(ver, "crackle")
  mix_render "beat: M/S + EQ + crunch + room", beat_pre, inputs: ["-i", VOICEMAILS_BEAT], map: "[beat_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo,volume=1.0[raw];
    [raw]pan=stereo|c0=c0+c1|c1=c0+c1[mid];
    [raw]pan=stereo|c0=c0-c1|c1=c1-c0[side];
    [mid]equalizer=f=60:t=o:w=0.8:g=7,equalizer=f=120:t=o:w=1:g=3,equalizer=f=400:t=o:w=1:g=-2,equalizer=f=2000:t=o:w=2:g=-3,
         acompressor=threshold=-20dB:ratio=6:attack=2:release=80:makeup=3[mid_eq];
    [side]equalizer=f=300:t=o:w=2:g=-4,equalizer=f=6000:t=o:w=3:g=4,acompressor=threshold=-18dB:ratio=3:attack=8:release=120:makeup=2[side_eq];
    [mid_eq][side_eq]amix=inputs=2:weights=1.4 0.6[beat_mix];
    [beat_mix]acrusher=level_in=1.2:level_out=0.9:bits=14:mode=log:aa=1[beat_crush];
    [beat_crush]aecho=0.6:0.4:30|60|90:0.15|0.08|0.04[beat_room];
    [beat_room]acompressor=threshold=-16dB:ratio=4:attack=3:release=60:makeup=2[beat_comp];
    [beat_comp]volume=0.88[beat_out]
  F
  mix_render "vocals: clear + shiny + precise", vocals_pre, inputs: ["-i", VOCALS[:processed]], map: "[voc_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[vraw];
    [vraw]equalizer=f=180:t=o:w=1:g=-10,equalizer=f=300:t=o:w=1:g=-4,equalizer=f=900:t=o:w=1.5:g=2,
          equalizer=f=2500:t=o:w=2:g=5,equalizer=f=5000:t=o:w=2:g=4,equalizer=f=10000:t=o:w=3:g=5,equalizer=f=16000:t=o:w=3:g=4[voc_eq];
    [voc_eq]acompressor=threshold=-16dB:ratio=2.5:attack=5:release=80:makeup=5[voc_comp];
    [voc_comp]asplit=4[va][vb][vc][vd];
    [va]volume=1.0[voc_dry];
    [vb]aecho=0.7:0.6:350|700:0.3|0.12,equalizer=f=300:t=h:w=1:g=0[voc_plate];
    [vc]adelay=#{d8}|#{d8 * 2},equalizer=f=400:t=h:w=1:g=0[voc_ping];
    [vd]chorus=0.5:0.9:20|25:0.1|0.08:0.15|0.2:1.0|1.0[voc_shimmer];
    [voc_dry][voc_plate][voc_ping][voc_shimmer]amix=inputs=4:weights=1.4 0.4 0.35 0.5[voc_wet];
    [voc_wet]volume=1.35[voc_out]
  F
  mix_render "crackle", crackle, inputs: lavfi("anoisesrc=r=44100:color=pink:amplitude=0.025:d=300:seed=#{noise_seed(20)}"), map: "[crack_out]", filter: <<~F
    [0:a]equalizer=f=3000:t=o:w=3:g=5,equalizer=f=80:t=o:w=1:g=-15,volume=0.18[crack_out]
  F
  mix_render "master v7", mix_out_path(ver), inputs: ["-i", beat_pre, "-i", vocals_pre, "-i", crackle], map: "[out]", args: ["-b:a", "320k"], filter: <<~F
    [0:a]volume=0.82[b];[1:a]volume=1.25[v];[2:a]volume=0.22[c];
    [b][v][c]amix=inputs=3:duration=first:weights=1 1.25 0.22[raw_mix];
    [raw_mix]acompressor=threshold=-22dB:ratio=3:attack=5:release=120:makeup=3[comp_low];
    [comp_low]acompressor=threshold=-12dB:ratio=5:attack=2:release=60:makeup=3[comp_mid];
    [comp_mid]acompressor=threshold=-6dB:ratio=10:attack=1:release=30:makeup=2[comp_hi];
    [comp_hi]equalizer=f=55:t=o:w=0.7:g=5,equalizer=f=160:t=o:w=1:g=2,equalizer=f=500:t=o:w=1.5:g=-2,equalizer=f=3000:t=o:w=2:g=-1,equalizer=f=10000:t=o:w=2:g=3[master_eq];
    [master_eq]aeval='tanh(val(0)*2.5)/tanh(2.5)|tanh(val(1)*2.5)/tanh(2.5)'[tape_sat];
    [tape_sat]aecho=0.3:0.2:18:0.06[air];
    [air]alimiter=level_in=1.0:level_out=0.98:limit=0.92:attack=3:release=25:level=disabled[limited];
    [limited]volume=0.96[out]
  F
end

def mix_v8
  ver = "v8"
  beat_pre, vocals_pre, crackle = mix_tmp(ver, "beat"), mix_tmp(ver, "vocals"), mix_tmp(ver, "crackle")
  mix_render "beat v8", beat_pre, inputs: mix_loop_beat, map: "[beat_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[raw];
    [raw]equalizer=f=55:t=o:w=0.7:g=9,equalizer=f=120:t=o:w=1:g=4,equalizer=f=350:t=o:w=1.5:g=-6,equalizer=f=1000:t=o:w=2:g=-8,equalizer=f=4000:t=o:w=2:g=-5,equalizer=f=10000:t=o:w=3:g=-4[sub_heavy];
    [sub_heavy]acompressor=threshold=-18dB:ratio=8:attack=1:release=40:makeup=4[beat_comp];
    [beat_comp]tremolo=f=0.4:d=0.04[beat_wobble];
    [beat_wobble]acrusher=level_in=1.1:level_out=0.85:bits=16:mode=log:aa=1[beat_grit];
    [beat_grit]volume=0.75[beat_out]
  F
  mix_render "vocals v8", vocals_pre, inputs: ["-i", VOCALS[:precise]], map: "[voc_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[vraw];
    [vraw]equalizer=f=200:t=o:w=1:g=-10,equalizer=f=1200:t=o:w=2:g=3,equalizer=f=3000:t=o:w=2:g=6,equalizer=f=6000:t=o:w=2:g=4,equalizer=f=12000:t=o:w=3:g=3[voc_eq];
    [voc_eq]acompressor=threshold=-18dB:ratio=4:attack=3:release=60:makeup=6[voc_comp];
    [voc_comp]asplit=2[vd][vr];[vd]volume=1.0[voc_dry];
    [vr]aecho=0.5:0.3:80|160:0.12|0.05[voc_tiny_room];
    [voc_dry][voc_tiny_room]amix=inputs=2:weights=1.0 0.3[voc_out]
  F
  mix_render "crackle v8", crackle, inputs: lavfi("anoisesrc=r=44100:color=pink:amplitude=0.05:d=#{MIX_DUR}:seed=#{noise_seed(21)}"), map: "[crack_out]", filter: <<~F
    [0:a]equalizer=f=4000:t=o:w=3:g=8,equalizer=f=80:t=o:w=1:g=-20,volume=0.3[crack_out]
  F
  mix_render "master v8", mix_out_path(ver), inputs: ["-i", beat_pre, "-i", vocals_pre, "-i", crackle], map: "[out]", args: ["-b:a", "320k"], filter: <<~F
    [0:a]volume=0.85[b];[1:a]volume=1.4[v];[2:a]volume=0.35[c];
    [b][v][c]amix=inputs=3:duration=first:weights=1 1.4 0.35[mix];
    [mix]equalizer=f=60:t=o:w=0.8:g=3,equalizer=f=5000:t=o:w=2:g=2[master_eq];
    [master_eq]aeval='tanh(val(0)*1.8)/tanh(1.8)|tanh(val(1)*1.8)/tanh(1.8)'[tape];
    [tape]alimiter=level_in=1.0:level_out=0.97:limit=0.94:attack=5:release=80:level=disabled[out]
  F
end

def mix_v9
  ver = "v9"; slow = 0.92; bpm = MIX_BPM * slow; d8 = mix_dotted_8th(bpm); hf = mix_half(bpm)
  beat_pre, vocals_pre, pad, crackle = mix_tmp(ver, "beat"), mix_tmp(ver, "vocals"), mix_tmp(ver, "pad"), mix_tmp(ver, "crackle")
  mix_render "beat v9", beat_pre, inputs: mix_loop_beat, map: "[beat_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[raw];
    [raw]asetrate=44100*0.7937,aresample=44100,atempo=#{slow}[pitched];
    [pitched]equalizer=f=50:t=o:w=0.7:g=9,equalizer=f=100:t=o:w=1:g=5,equalizer=f=600:t=o:w=2:g=-3,equalizer=f=3000:t=o:w=2:g=-5[beat_eq];
    [beat_eq]aphaser=in_gain=0.6:out_gain=0.8:delay=4:decay=0.5:speed=0.4:type=triangular[beat_phase];
    [beat_phase]aecho=0.7:0.5:200|400:0.3|0.15[beat_echo];
    [beat_echo]acompressor=threshold=-16dB:ratio=5:attack=4:release=80:makeup=3[beat_comp];
    [beat_comp]volume=0.78[beat_out]
  F
  mix_render "vocals v9", vocals_pre, inputs: ["-i", VOCALS[:precise]], map: "[voc_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[vraw];
    [vraw]equalizer=f=150:t=o:w=1:g=-8,equalizer=f=800:t=o:w=2:g=2,equalizer=f=3000:t=o:w=2:g=3,equalizer=f=8000:t=o:w=3:g=5,equalizer=f=14000:t=o:w=3:g=4[voc_eq];
    [voc_eq]acompressor=threshold=-14dB:ratio=2.5:attack=8:release=200:makeup=5[voc_comp];
    [voc_comp]asplit=4[va][vb][vc][vd];[va]volume=0.9[voc_dry];
    [vb]aecho=0.88:0.92:800|1600|3200|6400:0.6|0.4|0.22|0.10[voc_cathedral];
    [vc]chorus=0.7:0.9:35|45|55:0.4|0.32|0.25:0.3|0.4|0.25:1.8|2.2|1.4[voc_shimmer];
    [vd]adelay=#{d8}|#{hf},acrusher=level_in=1.8:level_out=0.5:bits=6:mode=log:aa=1[voc_bit];
    [voc_dry][voc_cathedral][voc_shimmer][voc_bit]amix=inputs=4:weights=1 0.7 0.5 0.2[voc_wet];
    [voc_wet]aphaser=in_gain=0.5:out_gain=0.7:delay=3:decay=0.4:speed=0.2:type=sinusoidal[voc_phase];
    [voc_phase]flanger=delay=6:depth=5:speed=0.2:shape=sinusoidal[voc_flange];
    [voc_flange]volume=1.3[voc_out]
  F
  mix_render "pad v9", pad, inputs: lavfi("aevalsrc=0.12*sin(2*PI*138.59*t)+0.10*sin(2*PI*277.18*t)+0.08*sin(2*PI*349.23*t)+0.09*sin(2*PI*415.30*t)+0.05*sin(2*PI*554.37*t):s=44100:c=stereo:d=#{MIX_DUR}"), map: "[pad_out]", filter: <<~F
    [0:a]equalizer=f=800:t=o:w=2:g=-6,equalizer=f=3000:t=o:w=2:g=-10,aecho=0.9:0.85:600|1200:0.5|0.3[pad_echo];
    [pad_echo]chorus=0.6:0.8:40|50:0.3|0.25:0.4|0.3:1.5|2.0[pad_chorus];
    [pad_chorus]aphaser=in_gain=0.6:out_gain=0.8:delay=5:decay=0.6:speed=0.15:type=sinusoidal[pad_phase];
    [pad_phase]volume=0.22[pad_out]
  F
  mix_render "crackle v9", crackle, inputs: lavfi("anoisesrc=r=44100:color=pink:amplitude=0.02:d=#{MIX_DUR}:seed=#{noise_seed(22)}"), map: "[crack_out]", filter: "[0:a]equalizer=f=5000:t=o:w=3:g=6,equalizer=f=80:t=o:w=1:g=-18,volume=0.12[crack_out]"
  mix_render "master v9", mix_out_path(ver), inputs: ["-i", beat_pre, "-i", vocals_pre, "-i", pad, "-i", crackle], map: "[out]", args: ["-b:a", "320k"], filter: <<~F
    [0:a]volume=0.80[b];[1:a]volume=1.20[v];[2:a]volume=0.25[p];[3:a]volume=0.15[c];
    [b][v][p][c]amix=inputs=4:duration=first:weights=1 1.2 0.25 0.15[mix];
    [mix]acompressor=threshold=-22dB:ratio=3:attack=8:release=200:makeup=3[comp1];
    [comp1]acompressor=threshold=-10dB:ratio=6:attack=2:release=60:makeup=2[comp2];
    [comp2]equalizer=f=50:t=o:w=0.7:g=4,equalizer=f=200:t=o:w=1:g=2,equalizer=f=2000:t=o:w=1.5:g=-2,equalizer=f=12000:t=o:w=2:g=3[master_eq];
    [master_eq]aeval='tanh(val(0)*3.0)/tanh(3.0)|tanh(val(1)*3.0)/tanh(3.0)'[tape];
    [tape]aecho=0.25:0.18:25:0.08[master_air];
    [master_air]alimiter=level_in=1.0:level_out=0.98:limit=0.93:attack=2:release=20:level=disabled[out]
  F
end

def mix_v10
  ver = "v10"; d8 = mix_dotted_8th(MIX_BPM)
  beat_pre, vocals_pre, pad, crackle = mix_tmp(ver, "beat"), mix_tmp(ver, "vocals"), mix_tmp(ver, "pad"), mix_tmp(ver, "crackle")
  mix_render "beat v10", beat_pre, inputs: mix_loop_beat, map: "[beat_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[raw];
    [raw]equalizer=f=50:t=o:w=0.8:g=6,equalizer=f=100:t=o:w=1:g=4,equalizer=f=250:t=o:w=1:g=2,equalizer=f=700:t=o:w=1.5:g=-1,equalizer=f=3000:t=o:w=2:g=1,equalizer=f=8000:t=o:w=2:g=2,equalizer=f=14000:t=o:w=3:g=3[beat_eq];
    [beat_eq]acompressor=threshold=-22dB:ratio=3:attack=15:release=200:makeup=3[tape_comp];
    [tape_comp]aeval='#{HEDD}'[hedd];
    [hedd]aecho=0.5:0.3:25|50:0.1|0.05[spring];
    [spring]volume=0.82[beat_out]
  F
  mix_render "vocals v10", vocals_pre, inputs: ["-i", VOCALS[:precise]], map: "[voc_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[vraw];
    [vraw]equalizer=f=160:t=o:w=1:g=-10,equalizer=f=350:t=o:w=1:g=-4,equalizer=f=1000:t=o:w=1.5:g=2,equalizer=f=2500:t=o:w=2:g=6,equalizer=f=5000:t=o:w=2:g=5,equalizer=f=10000:t=o:w=3:g=6,equalizer=f=16000:t=o:w=3:g=5[voc_eq];
    [voc_eq]acompressor=threshold=-16dB:ratio=2.5:attack=6:release=100:makeup=5[voc_comp];
    [voc_comp]aeval='#{HEDD}'[voc_hedd];
    [voc_hedd]asplit=3[va][vb][vc];[va]volume=1.0[vdry];
    [vb]adelay=#{d8}|#{d8},aecho=0.65:0.55:400|800:0.35|0.15[vplate];
    [vc]chorus=0.5:0.9:18|22:0.08|0.06:0.2|0.25:1.0|1.0[vdouble];
    [vdry][vplate][vdouble]amix=inputs=3:weights=1.4 0.45 0.35[voc_out]
  F
  mix_render "pad v10", pad, inputs: lavfi("aevalsrc=0.14*sin(2*PI*130.81*t)+0.11*sin(2*PI*261.63*t)+0.09*sin(2*PI*311.13*t)+0.10*sin(2*PI*392.00*t)+0.06*sin(2*PI*523.25*t):s=44100:c=stereo:d=#{MIX_DUR}"), map: "[pad_out]", filter: <<~F
    [0:a]equalizer=f=1000:t=o:w=2:g=-5,equalizer=f=4000:t=o:w=2:g=-10,equalizer=f=100:t=o:w=1:g=3[pad_eq];
    [pad_eq]aecho=0.85:0.8:500|1000:0.4|0.2[pad_echo];
    [pad_echo]chorus=0.5:0.8:35|45:0.25|0.2:0.35|0.25:1.2|1.6[pad_chorus];
    [pad_chorus]volume=0.18[pad_out]
  F
  mix_render "crackle v10", crackle, inputs: lavfi("anoisesrc=r=44100:color=pink:amplitude=0.015:d=#{MIX_DUR}:seed=#{noise_seed(23)}"), map: "[crack_out]", filter: "[0:a]equalizer=f=4500:t=o:w=3:g=5,equalizer=f=80:t=o:w=1:g=-18,volume=0.10[crack_out]"
  mix_render "master v10", mix_out_path(ver), inputs: ["-i", beat_pre, "-i", vocals_pre, "-i", pad, "-i", crackle], map: "[out]", args: ["-b:a", "320k"], filter: <<~F
    [0:a]volume=0.84[b];[1:a]volume=1.22[v];[2:a]volume=0.20[p];[3:a]volume=0.12[c];
    [b][v][p][c]amix=inputs=4:duration=first:weights=1 1.22 0.20 0.12[mix];
    [mix]acompressor=threshold=-24dB:ratio=2:attack=20:release=300:makeup=2[glue];
    [glue]aeval='#{HEDD}'[bus_hedd];
    [bus_hedd]equalizer=f=45:t=o:w=0.7:g=3,equalizer=f=150:t=o:w=1:g=2,equalizer=f=700:t=o:w=1.5:g=-1,equalizer=f=12000:t=o:w=2:g=2[master_eq];
    [master_eq]aeval='tanh(val(0)*2.2)/tanh(2.2)|tanh(val(1)*2.2)/tanh(2.2)'[tape_sat];
    [tape_sat]aecho=0.2:0.15:15:0.05[air];
    [air]alimiter=level_in=1.0:level_out=0.98:limit=0.93:attack=4:release=40:level=disabled[out]
  F
end

def mix_v11
  ver = "v11"; d8 = mix_dotted_8th(MIX_BPM)
  beat_pre, vocals_pre, crackle = mix_tmp(ver, "beat"), mix_tmp(ver, "vocals"), mix_tmp(ver, "crackle")
  mix_render "beat v11", beat_pre, inputs: mix_loop_beat, map: "[beat_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[raw];
    [raw]pan=stereo|c0=c0+c1|c1=c0+c1[mid];[raw]pan=stereo|c0=c0-c1|c1=c1-c0[side];
    [mid]lowpass=f=280[mid_bass];
    [mid_bass]equalizer=f=60:t=o:w=0.8:g=6,equalizer=f=120:t=o:w=1:g=3,acompressor=threshold=-18dB:ratio=6:attack=2:release=50:makeup=4[mid_punch];
    [side]equalizer=f=2000:t=o:w=0.8:g=-12,equalizer=f=2200:t=o:w=0.5:g=-8,lowpass=f=9000,equalizer=f=300:t=o:w=1:g=-3,equalizer=f=5000:t=o:w=2:g=2[side_clean];
    [side_clean]tremolo=f=0.35:d=0.05[side_wobble];
    [side_wobble]aphaser=in_gain=0.6:out_gain=0.8:delay=3:decay=0.4:speed=0.3:type=triangular[side_phase];
    [mid_punch][side_phase]amix=inputs=2:weights=1.3 0.7[beat_mix];
    [beat_mix]acompressor=threshold=-16dB:ratio=3:attack=5:release=100:makeup=2[beat_comp];
    [beat_comp]volume=0.82[beat_out]
  F
  mix_render "vocals v11", vocals_pre, inputs: ["-i", VOCALS[:original]], map: "[voc_out]", filter: <<~F
    [0:a]aformat=sample_rates=44100:channel_layouts=stereo[vraw];
    [vraw]equalizer=f=180:t=o:w=1:g=-8,equalizer=f=600:t=o:w=1.5:g=2,equalizer=f=2000:t=o:w=0.8:g=-6,equalizer=f=3000:t=o:w=2:g=5,equalizer=f=7000:t=o:w=2:g=4,equalizer=f=12000:t=o:w=3:g=2,lowpass=f=14000[voc_eq];
    [voc_eq]acompressor=threshold=-14dB:ratio=2.5:attack=8:release=150:makeup=5[voc_comp];
    [voc_comp]asplit=3[va][vb][vc];[va]volume=1.0[vdry];
    [vb]aecho=0.75:0.65:350|700:0.35|0.15[vplate];
    [vc]adelay=#{d8}|#{d8 * 2},chorus=0.5:0.8:20|25:0.08|0.06:0.2|0.25:1.0|1.0[vshine];
    [vdry][vplate][vshine]amix=inputs=3:weights=1.3 0.4 0.3[voc_wet];
    [voc_wet]aphaser=in_gain=0.5:out_gain=0.7:delay=2:decay=0.3:speed=0.25:type=sinusoidal[voc_phase];
    [voc_phase]volume=1.3[voc_out]
  F
  mix_render "crackle v11", crackle, inputs: lavfi("anoisesrc=r=44100:color=pink:amplitude=0.012:d=#{MIX_DUR}:seed=#{noise_seed(24)}"), map: "[crack_out]", filter: "[0:a]equalizer=f=5000:t=o:w=3:g=4,equalizer=f=80:t=o:w=1:g=-18,volume=0.10[crack_out]"
  mix_render "master v11", mix_out_path(ver), inputs: ["-i", beat_pre, "-i", vocals_pre, "-i", crackle], map: "[out]", args: ["-b:a", "320k"], filter: <<~F
    [0:a]volume=0.85[b];[1:a]volume=1.25[v];[2:a]volume=0.12[c];
    [b][v][c]amix=inputs=3:duration=first:weights=1 1.25 0.12[mix];
    [mix]acompressor=threshold=-20dB:ratio=2.5:attack=18:release=250:makeup=3[glue];
    [glue]equalizer=f=55:t=o:w=0.8:g=4,equalizer=f=2000:t=o:w=0.6:g=-3,equalizer=f=8000:t=o:w=2:g=1,lowpass=f=16000[master_eq];
    [master_eq]aeval='tanh(val(0)*2.0)/tanh(2.0)|tanh(val(1)*2.0)/tanh(2.0)'[tape];
    [tape]aphaser=in_gain=0.3:out_gain=0.5:delay=2:decay=0.3:speed=0.15:type=sinusoidal[master_phase];
    [master_phase]alimiter=level_in=1.0:level_out=0.97:limit=0.93:attack=5:release=60:level=disabled[out]
  F
end

MIX_RECIPES = { "v7" => method(:mix_v7), "v8" => method(:mix_v8), "v9" => method(:mix_v9),
                "v10" => method(:mix_v10), "v11" => method(:mix_v11) }.freeze

def run_mix(ver = "v11")
  abort "unknown mix: #{ver}  have: #{MIX_RECIPES.keys.join(', ')}" unless MIX_RECIPES[ver]
  MIX_RECIPES[ver].call
  puts "done -> #{mix_out_path(ver)}"
  render_liveset(stems_load_manifest["active"] || "default", minutes: LIVESET_MIN) if File.exist?(STEM_MANIFEST)
end

# FFmpeg band-split from a full mix → stem rack files for render_dilla.
def install_stems_from_audio(src, bpm: 90, label: nil)
  src = File.expand_path(src)
  abort "missing source: #{src}" unless File.exist?(src)
  require_tools! "ffmpeg"
  FileUtils.mkdir_p(STEM_DIR)
  slices = {
    STEM_SUB => "lowpass=f=85,equalizer=f=48:t=o:w=0.8:g=4",
    STEM_MIDS => "highpass=f=260,lowpass=f=3400,equalizer=f=800:t=o:w=1:g=2",
    STEM_HIGHS => "highpass=f=2200,lowpass=f=6800",
    STEM_CENTER => "pan=stereo|c0=0.5*c0+0.5*c1|c1=0.5*c0+0.5*c1",
    File.join(STEM_DIR, "sides.mp3") => "pan=stereo|c0=0.5*c0-0.5*c1|c1=0.5*c1-0.5*c0",
    File.join(STEM_DIR, "bass.mp3") => "highpass=f=55,lowpass=f=220,equalizer=f=90:t=o:w=1:g=3",
  }
  slices.each do |dest, eq|
    mix_render "stem: #{File.basename(dest)}", dest, inputs: ["-i", src], map: "[out]",
               filter: "[0:a]aformat=channel_layouts=stereo,#{eq}[out]",
               args: ["-ar", SAMPLE_RATE.to_s, *codec_for(dest)]
  end
  name = label || File.basename(src, ".*").gsub(/[^A-Za-z0-9_-]/, "_")[0, 32]
  stems_register(name, STEM_DIR, bpm:, source: File.basename(src))
  puts "stems installed from #{src} → #{STEM_DIR}"
end

# One-shot lab setup: synth drum kit + stem rack from bundled soul/gospel sources.
def prepare(src = nil)
  ensure_drum_kit!
  src ||= %w[neosoul.mp3 gospel.mp3 modal.mp3].map { |f| File.join(ROOT, f) }.find { |p| File.exist?(p) }
  abort "no source audio — ruby dilla.rb prepare <path> or add neosoul.mp3 to #{ROOT}" unless src
  install_stems_from_audio(src)
  custom = Dir.glob(File.join(CUSTOM_DRUM_DIR, "*.wav"))
  puts "prepare: kit=#{drum_kit_ready? ? 'ready' : 'partial'}, stems=#{dilla_stem_paths.keys.join('+')}"
  puts "custom drums: drop MPC one-shots in #{CUSTOM_DRUM_DIR} (#{custom.length} loaded)" unless custom.empty?
  puts "custom drums: drop kick.wav snare.wav hat.wav in #{CUSTOM_DRUM_DIR} to override synth kit" if custom.empty?
end

# =============================================================================
# DEMUX (YouTube/path → demucs 6-stem)
# =============================================================================

def demux_fetch_audio(src, start_sec: nil, duration_sec: 150)
  return File.expand_path(src) unless src.match?(%r{\Ahttps?://})
  FileUtils.mkdir_p(DEMUX_DIR)
  raw = File.join(DEMUX_DIR, "yt_#{Time.now.strftime("%Y%m%d_%H%M%S")}.wav")
  require_tools! "yt-dlp"
  args = ["-x", "--audio-format", "wav", "-o", raw]
  if duration_sec
    from = (start_sec || 0).to_i
    to = from + duration_sec.to_i
    args += ["--download-sections", "*#{from}-#{to}"]
  end
  args << src
  sh! "yt-dlp", *args
  raw
end

def youtube_watch_url(id, start: nil)
  url = "https://www.youtube.com/watch?v=#{id}"
  start ? "#{url}&t=#{start.to_i}" : url
end

# --------------------------------------------------------------------------
# engine part: wonky_learn
# --------------------------------------------------------------------------
#
# Learning drum grids from stems, and the demux/chop pipeline.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.
require_relative "lib/frozen_state"

WONKY_LEARNINGS_DIR = File.join(DillaSourceLearn::LEARNINGS_DIR, "wonky_drums").freeze

def wonky_quantize_onsets(onsets, bpm, window: 0.05)
  bar_frames = ((60.0 / bpm) * 4.0 / window).round
  step_frames = [bar_frames / 16.0, 1.0].max
  tally = Hash.new(0)
  onsets.each do |f|
    step = ((f % bar_frames) / step_frames).round
    step = 15 if step >= 16
    tally[step] += 1
  end
  tally
end

def wonky_pick_steps(tally, role:, max_sec: 90, bpm: 86)
  max_steps = { kick: 6, snare: 6, hat: 12, perc: 5 }.fetch(role, 5)
  bars = (max_sec / ((60.0 / bpm) * 4.0)).ceil
  min_hits = case role
             when :kick then [bars / 3, 2].max
             when :snare then [bars / 4, 2].max
             when :hat then [bars / 2, 3].max
             else [bars / 4, 2].max
             end
  picks = tally.sort_by { |_, c| -c }.select { |_, c| c >= min_hits }.first(max_steps).map(&:first).sort
  picks.empty? ? tally.sort_by { |_, c| -c }.first(max_steps).map(&:first).sort : picks
end

def wonky_onsets_adaptive(path, filter, role:, bpm:, max_sec: 90)
  da = RadioBergenStudy::DeepAudio
  rms = da.band_rms(path, filter, window: 0.05, max_sec:)
  return [] if rms.empty?
  sorted = rms.sort
  median = sorted[sorted.length / 2]
  peak = sorted[(sorted.length * 0.88).to_i]
  span = [peak - median, 8.0].max
  thresh, min_gap = case role
                    when :kick then [median + span * 0.52, 7]
                    when :snare then [median + span * 0.46, 5]
                    when :hat then [median + span * 0.28, 2]
                    else [median + span * 0.38, 4]
                    end
  onsets = []
  rms.each_with_index do |val, i|
    next if val < thresh
    prev = i.positive? ? rms[i - 1] : nil
    nxt = rms[i + 1]
    next if prev && val <= prev
    next if nxt && val <= nxt
    onsets << i if onsets.empty? || (i - onsets.last) >= min_gap
  end
  wonky_pick_steps(wonky_quantize_onsets(onsets, bpm), role:, max_sec:, bpm:)
end

def wonky_drum_grid_blend_fallback!(grid)
  base = DillaLofiMachine::DRUM_PRESETS[:wonky_abstract]
  {
    wonky_kicks: :kicks, wonky_snares: :snares, wonky_hats: :hats, wonky_perc: :perc
  }.each do |grid_key, preset_key|
    steps = Array(grid[grid_key] || grid[grid_key.to_s])
    next if steps.length >= 3
    fb = Array(base[preset_key])
    grid[grid_key] = (steps + fb).uniq.sort if fb.any?
  end
  grid
end

def wonky_drum_grid_from_stems(stem_dir, bpm: nil, analyze_sec: 120)
  drums = File.join(stem_dir, "drums.wav")
  return unless File.file?(drums)
  da = RadioBergenStudy::DeepAudio
  unless bpm
    kick_rms = da.band_rms(drums, "lowpass=f=220,highpass=f=50", max_sec: [analyze_sec, 90].min)
    bpm = da.estimate_bpm(da.detect_onsets(kick_rms, threshold_db: -12, min_gap: 6)) || 86
    bpm = 86 if bpm < 80 || bpm > 95
  end
  grid = {
    bpm: bpm.round,
    swing: DillaLofiMachine::DRUM_PRESETS[:wonky_abstract][:swing],
    source_stem: drums,
    wonky_kicks: wonky_onsets_adaptive(drums, "lowpass=f=220,highpass=f=50", role: :kick,
                                        bpm:, max_sec: analyze_sec),
    wonky_snares: wonky_onsets_adaptive(drums, "lowpass=f=5000,highpass=f=900", role: :snare,
                                         bpm:, max_sec: analyze_sec),
    wonky_hats: wonky_onsets_adaptive(drums, "lowpass=f=14000,highpass=f=5000", role: :hat,
                                      bpm:, max_sec: analyze_sec),
    wonky_perc: wonky_onsets_adaptive(drums, "lowpass=f=8000,highpass=f=2000", role: :perc,
                                      bpm:, max_sec: analyze_sec),
  }
  wonky_drum_grid_blend_fallback!(grid)
end

def learn_wonky_drums!(src, track: :quartal_west_coast, slug: "wonky_camel", apply: false, deep: true)
  DillaSourceLearn.ensure_dir!
  FileUtils.mkdir_p(WONKY_LEARNINGS_DIR)
  audio_path = if File.exist?(src.to_s)
                 File.expand_path(src)
               else
                 demux_fetch_audio(src, duration_sec: 180)
               end
  stem_candidate = File.join(DEMUX_DIR, "demux", DEMUX_MODEL, File.basename(audio_path, ".*"))
  stem_dir = if File.file?(File.join(stem_candidate, "drums.wav"))
               puts "wonky learn: reusing stems #{stem_candidate}"
               stem_candidate
             else
               demux_six(audio_path)
             end
  demux_deep_bands!(stem_dir) if deep && !File.directory?(File.join(stem_dir, "bands"))
  grid = wonky_drum_grid_from_stems(stem_dir)
  abort "wonky drum learn: could not extract grid from #{stem_dir}" unless grid.is_a?(Hash) && grid[:wonky_kicks]&.any?

  grid[:learned_at] = Time.now.utc.iso8601
  grid[:source] = src.to_s
  grid[:slug] = slug.to_s
  out_path = File.join(WONKY_LEARNINGS_DIR, "#{slug}.json")
  DillaFrozen.write_json(out_path, grid.transform_keys(&:to_s))

  eng = load_learned_engine(refresh: true)
  track_s = track.to_s
  eng["drum_grids"][track_s] = grid.transform_keys(&:to_s)
  eng["drum_grids"][slug.to_s] = grid.transform_keys(&:to_s)
  eng["track_aliases"]["wonky_camel"] = track_s unless eng["track_aliases"]["wonky_camel"]
  save_learned_engine!(eng)
  remove_instance_variable(:@learned_engine_cache) if instance_variable_defined?(:@learned_engine_cache)

  if apply
    ENV["TRACK"] = track_s
    ENV["WONKY_DRUM_OVERLAY"] = "1"
    ENV["BPM"] = grid[:bpm].to_s if grid[:bpm]
    ENV["SWING"] = grid[:swing].to_s if grid[:swing]
    ENV["STREAM_LEARN_BIAS"] = "1"
  end
  puts "wonky drums learned: #{slug} → #{track_s} kicks=#{grid[:wonky_kicks].join(',')} " \
       "snares=#{grid[:wonky_snares].join(',')} hats=#{grid[:wonky_hats].join(',')} bpm=#{grid[:bpm]}"
  puts "saved: #{out_path}"
  grid
end

def drum_step_grid_from_wav(path, bpm: nil, analyze_sec: 90)
  return unless path && File.file?(path)
  da = RadioBergenStudy::DeepAudio
  window = 0.05
  duration = da.ffprobe(path).dig("format", "duration").to_f
  analyze_sec = [[duration * 0.6, analyze_sec].min, 30].max
  analyze_sec = duration if duration.positive? && duration < analyze_sec

  kick_rms = da.band_rms(path, "lowpass=f=200,highpass=f=60", window:, max_sec: analyze_sec)
  snare_rms = da.band_rms(path, "lowpass=f=4000,highpass=f=800", window:, max_sec: analyze_sec)
  hat_rms = da.band_rms(path, "lowpass=f=12000,highpass=f=4000", window:, max_sec: analyze_sec)

  kick_on = da.detect_onsets(kick_rms, threshold_db: -14.0, min_gap: 4)
  snare_on = da.detect_onsets(snare_rms, threshold_db: -16.0, min_gap: 4)
  hat_on = da.detect_onsets(hat_rms, threshold_db: -18.0, min_gap: 2)

  bpm ||= da.estimate_bpm(kick_on) || da.estimate_bpm(snare_on) || 90
  bar_frames = ((60.0 / bpm) * 4.0 / window).round
  bar_frames = [bar_frames, 16].max
  step_frames = [bar_frames / 16.0, 1.0].max

  quantize = lambda do |onsets|
    onsets.map { |f| ((f % bar_frames) / step_frames).round % 16 }.uniq.sort
  end

  analysis = da.analyze(path)
  {
    bpm_estimate: bpm,
    swing_hint: analysis&.dig(:dynamics, :swing_hint),
    drum_density: analysis&.dig(:drum_density),
    step_grid: {
      kicks: quantize.call(kick_on),
      snares: quantize.call(snare_on),
      hats: quantize.call(hat_on).first(14),
      bar_steps: 16,
    },
  }
rescue StandardError => e
  { error: e.message }
end

def demux_six(src)
  audio = demux_fetch_audio(src)
  out = File.join(DEMUX_DIR, "demux")
  FileUtils.mkdir_p(out)
  cmd = demucs_cmd or abort "demucs required — pip install demucs"
  sh!(*cmd, "-n", DEMUX_MODEL, "-o", out, audio)
  stem_dir = File.join(out, DEMUX_MODEL, File.basename(audio, ".*"))
  puts "stems -> #{stem_dir}"
  if stem_dir.start_with?(STEM_DIR) && Dir.exist?(stem_dir) && !stems_scan_set(stem_dir).empty?
    name = File.basename(audio, ".*").gsub(/[^A-Za-z0-9_-]/, "_")[0, 32]
    stems_register(name, stem_dir, source: src)
  end
  stem_dir
end

# Vocal-only counterpart to demux_six: htdemucs_ft (fine-tuned, 4-stem) with
# --shifts averaging instead of the shared htdemucs_6s used for full stem
# splits elsewhere. Both are documented demucs quality knobs over the default
# single-pass htdemucs_6s call -- real bleed reduction at a real time cost,
# acceptable because this only runs once per ingested vocal source.
def demux_vocal_isolate(src)
  audio = demux_fetch_audio(src)
  out = File.join(DEMUX_DIR, "demux")
  FileUtils.mkdir_p(out)
  cmd = demucs_cmd or abort "demucs required — pip install demucs"
  shifts = ENV.fetch("DEMUX_VOCAL_SHIFTS", "2")
  sh!(*cmd, "-n", DEMUX_VOCAL_MODEL, "--shifts", shifts, "--float32", "-o", out, audio)
  stem_dir = File.join(out, DEMUX_VOCAL_MODEL, File.basename(audio, ".*"))
  puts "vocal stems -> #{stem_dir}"
  stem_dir
end

def demux_slice_band(src, dest, label, eq:)
  mix_render "band: #{label}", dest, inputs: ["-i", src], map: "[out]", filter: "[0:a]#{eq}[out]"
end

def demux_deep_bands!(stem_dir)
  bands = File.join(stem_dir, "bands")
  FileUtils.mkdir_p(bands)
  bass = File.join(stem_dir, "bass.wav"); drums = File.join(stem_dir, "drums.wav")
  guitar = File.join(stem_dir, "guitar.wav"); piano = File.join(stem_dir, "piano.wav"); other = File.join(stem_dir, "other.wav")
  demux_slice_band bass,  File.join(bands, "sub_bass.wav"),    "sub_bass",    eq: "lowpass=f=60"
  demux_slice_band bass,  File.join(bands, "bass_mid.wav"),    "bass_mid",    eq: "highpass=f=60,lowpass=f=200"
  demux_slice_band drums, File.join(bands, "kick.wav"),        "kick",        eq: "lowpass=f=100"
  demux_slice_band drums, File.join(bands, "snare.wav"),       "snare",       eq: "highpass=f=200,lowpass=f=500"
  demux_slice_band drums, File.join(bands, "hats.wav"),        "hats",        eq: "highpass=f=5000"
  demux_slice_band other, File.join(bands, "mids.wav"),        "mids",        eq: "highpass=f=500,lowpass=f=2000"
  demux_slice_band other, File.join(bands, "highs_pluck.wav"), "highs_pluck", eq: "highpass=f=2000,lowpass=f=5000"
  demux_slice_band other, File.join(bands, "air.wav"),         "air",         eq: "highpass=f=5000"
  inst = File.join(bands, "instrumental.wav")
  mix_render "instrumental sum", inst, inputs: ["-i", bass, "-i", drums, "-i", guitar, "-i", piano, "-i", other],
    map: "[out]", filter: "[0:a][1:a][2:a][3:a][4:a]amix=inputs=5:duration=longest[out]"
  demux_slice_band inst, File.join(bands, "center.wav"), "center", eq: "pan=stereo|c0=c0+c1|c1=c0+c1"
  demux_slice_band inst, File.join(bands, "sides.wav"),  "sides",  eq: "pan=stereo|c0=c0-c1|c1=c1-c0"
  puts "bands -> #{bands}"
  bands
end

def demux_deep(src)
  stem_dir = demux_six(src)
  demux_deep_bands!(stem_dir)
  stem_dir
end

# =============================================================================
# CHOP (long recording → drumless, vocal-less registered sample loops)
# =============================================================================
#
# The analysis lives in lib/radio_chop.rb; this is the wiring. Both external
# dependencies are injected rather than reached for from inside the module:
# demucs_cmd because it has three fallbacks and only this file knows them, and
# sample_key because the Krumhansl tables and the Goertzel chroma are here.

def chop_dispatch!
  case ARGV.first
  when "list" then ARGV.shift; chop_list
  else chop_ingest!
  end
end

def chop_ingest!
  src = ARGV.find { |a| !a.start_with?("-") }
  ARGV.delete(src) if src
  cmd = demucs_cmd or abort "demucs required — " \
    "python3 -m venv #{DEMUX_VENV_DIR} && " \
    "#{DEMUX_VENV_DIR}/bin/pip install demucs"

  RadioChop.ingest!(
    src ? File.expand_path(src) : RadioChop::DEFAULT_SOURCE,
    demucs: cmd,
    deep: RadioBergenStudy::DeepAudio,
    key_probe: method(:sample_key),
    label: ENV["CHOP_LABEL"],
    candidates: ENV.fetch("CHOP_CANDIDATES", "16").to_i,
    keep: ENV.fetch("CHOP_KEEP", "8").to_i,
    # Wide enough that a loop can be found rather than assumed: the length
    # search correlates a candidate against the material that follows it, so a
    # 30s window is what makes a 14s loop answerable at all.
    span: ENV.fetch("CHOP_SPAN", "30").to_f,
    scratch: scratch_path("chop_work"),
    # Separation is the expensive step and its output is keyed by the window it
    # came from, so a re-run to re-tune the scoring reuses it. CHOP_FRESH=1
    # throws it away, which is what you want after changing the span or the
    # source. Not a `--flag`: apply_flags! validates the whole `--` namespace
    # before dispatch and rejects anything not in its table.
    fresh: ENV["CHOP_FRESH"] == "1",
  )
  chop_list
rescue RuntimeError => e
  abort "chop: #{e.message}"
end

def chop_list
  loops = Array(RadioChop.registry["loops"])
  if loops.empty?
    puts "chop: nothing registered — run: ruby dilla.rb chop [path]"
    return
  end

  puts format("%-22s %6s %5s %6s %-9s %6s %7s %7s  %s",
              "slug", "bpm", "bars", "len", "key", "selfsim", "rejoin", "score", "at")
  loops.each do |l|
    puts format("%-22s %6s %5s %6s %-9s %6s %7s %7s  %s",
                l["slug"], l["bpm"].to_f.positive? ? l["bpm"] : "native", l["bars"] || "-",
                l["duration_sec"], l["key"] || "-", l["self_similarity"],
                l["rejoin_db"], l["score"],
                format("%d:%02d", l["source_start_sec"].to_i / 60, l["source_start_sec"].to_i % 60))
  end
  puts "rack: TRACK=<slug> to render over one, CHOP_BED=1 to let the engine pick by key"
end

def top_pitch_class_indices(pitch_class_hash, limit: 6)
  PITCH_CLASSES.each_with_index
               .sort_by { |name, _| -pitch_class_hash.fetch(name, 0.0).to_f }
               .first(limit)
               .map { |_, idx| idx }
end

def analyze_stem_for_learn(path, stem_name)
  return unless path && File.file?(path)
  result = { path:, stem: stem_name }
  case stem_name
  when "drums.wav", "bass.wav"
    analysis = RadioBergenStudy::DeepAudio.analyze(path)
    if analysis
      result[:bpm_estimate] = analysis[:bpm_estimate]
      result[:swing_hint] = analysis.dig(:dynamics, :swing_hint)
      result[:texture_hints] = analysis[:texture_hints]
      result[:drum_density] = analysis[:drum_density]
    end
    if stem_name == "drums.wav"
      grid = drum_step_grid_from_wav(path, bpm: result[:bpm_estimate])
      result.merge!(grid) if grid.is_a?(Hash)
    end
  when "piano.wav", "guitar.wav", "other.wav", "vocals.wav"
    profile = pitch_profile(path)
    pcs_hash = profile.fetch(:pitch_classes)
    top_pcs = top_pitch_class_indices(pcs_hash)
    ranking = chord_candidates(pcs_hash).first(8)
    result[:pitch_classes] = top_pcs
    result[:top_chords] = ranking.map { |c| { name: c[:chord], score: c[:score] } }
    if defined?(DillaMusicGems) && DillaMusicGems.coltrane?
      result[:coltrane_candidates] = DillaMusicGems.chord_candidates_from_pitch_classes(top_pcs, limit: 8)
    end
  end
  if %w[other.wav vocals.wav].include?(stem_name)
    rhythm_data = frame_energy(path, highpass: 60, lowpass: 12_000)
    loudness = rhythm_data.fetch(:frames).map(&:last)
    brightness = frame_energy(path, highpass: 2_400, lowpass: 12_000).fetch(:frames).map(&:last)
    density = peak_frames(rhythm_data.fetch(:frames), rhythm_data.fetch(:hop_seconds)).length.to_f /
              [rhythm_data.fetch(:duration_seconds), 1.0].max
    result[:semantics] = semantic_tags(loudness, brightness, density)
  end
  result
rescue StandardError => e
  { path:, stem: stem_name, error: e.message }
end

# --------------------------------------------------------------------------
# engine part: rap_vocal
# --------------------------------------------------------------------------
#
# The rap vocal catalogue: ingest, isolate, clean, measure.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.
require_relative "lib/frozen_state"

RAP_VOCAL_DIR = File.join(DillaSourceLearn::LEARNINGS_DIR, "vocals").freeze
RAP_VOCAL_CATALOG = File.join(RAP_VOCAL_DIR, "catalog.json").freeze

def rap_vocal_slug(artist)
  artist.to_s.downcase.gsub(/[^a-z0-9]+/, "_").gsub(/\A_|_\z/, "")
end

def rap_vocal_load_catalog
  return { "vocals" => [], "updated_at" => nil } unless File.file?(RAP_VOCAL_CATALOG)
  JSON.parse(File.read(RAP_VOCAL_CATALOG))
rescue StandardError
  { "vocals" => [], "updated_at" => nil }
end

def rap_vocal_save_catalog!(cat)
  DillaSourceLearn.ensure_dir!
  FileUtils.mkdir_p(RAP_VOCAL_DIR)
  cat["updated_at"] = Time.now.utc.iso8601
  DillaFrozen.write_json(RAP_VOCAL_CATALOG, cat)
end

def rap_vocal_phrase_onsets(path)
  rhythm = frame_energy(path, highpass: 300, lowpass: 6000)
  peaks = peak_frames(rhythm[:frames], rhythm[:hop_seconds])
  return [] if peaks.empty?
  phrases = []
  cluster = [peaks.first]
  peaks[1..].each do |pk|
    if pk[:time] - cluster.last[:time] < 0.35
      cluster << pk
    else
      phrases << { "start" => cluster.first[:time].round(3), "end" => cluster.last[:time].round(3),
                   "strength" => cluster.map { |p| p[:strength] }.max.round(4) }
      cluster = [pk]
    end
  end
  phrases << { "start" => cluster.first[:time].round(3), "end" => cluster.last[:time].round(3),
               "strength" => cluster.map { |p| p[:strength] }.max.round(4) }
  phrases
end

def rap_vocal_atempo_chain(ratio)
  r = ratio.to_f.clamp(0.25, 4.0)
  parts = []
  while r > 2.0
    parts << 2.0
    r /= 2.0
  end
  while r < 0.5
    parts << 0.5
    r /= 0.5
  end
  parts << r
  parts.map { |t| "atempo=#{t.round(4)}" }.join(",")
end

# Voice-only chain for demucs "vocals" stems.
# Goal: hear Jonas V (speech/rap), never residual kick/bass/hats from the source beat.
# Demucs always leaves some kit bleed; we kill it hard then denoise the floor.
def rap_vocal_isolation_filter
  [
    "aformat=sample_rates=#{SAMPLE_RATE}:channel_layouts=stereo",
    # Center-bias: voice is mid; kit/pads often wider — collapse residual sides.
    "pan=stereo|c0=0.72*c0+0.28*c1|c1=0.72*c1+0.28*c0",
    # Kill everything below speech fundamentals (kit sub lives here).
    "highpass=f=175:width_type=q:width=0.707",
    "equalizer=f=55:t=h:w=1.0:g=-24",
    "equalizer=f=90:t=h:w=1.2:g=-18",
    "equalizer=f=130:t=o:w=1.4:g=-12",
    "equalizer=f=200:t=o:w=1.3:g=-6",
    # Soft top air for consonants; no crash/hat glare.
    "lowpass=f=7200:width_type=q:width=0.8",
    "equalizer=f=3200:t=o:w=1.5:g=2.2",
    "equalizer=f=5500:t=h:w=1.2:g=-2.5",
    # FFT denoise residual kit hiss / cymbal wash left in demucs vocals.
    "afftdn=nr=14:nf=-28:tn=1",
    # Hard gate: only pass when voice is present (no quiet snare ghosts).
    # release/range deliberately gentle. At release=55 with range=0.0008 this
    # slammed to near-silence between syllables -- measured 4 gaps under 150ms
    # (median 93ms) inside a single 20s phrase, which is the "chopping". The
    # gate is here to suppress kit bleed BETWEEN phrases, not to articulate
    # words, so it now ducks by ~24 dB over a quarter second instead of cutting.
    "agate=threshold=0.022:ratio=4:attack=6:release=260:range=0.06:makeup=1.5",
    "acompressor=threshold=-24dB:ratio=2.4:attack=4:release=90:makeup=3.5",
    # Second gate after makeup so boosted floor does not reappear.
    "agate=threshold=0.012:ratio=3:attack=4:release=200:range=0.10:makeup=1",
  ].join(",")
end

# Light polish for already-isolated stems (no heavy makeup that re-lifts bleed).
def rap_vocal_voice_polish_filter
  base = [
    "aformat=sample_rates=#{SAMPLE_RATE}:channel_layouts=stereo",
    "highpass=f=165:width_type=q:width=0.707",
    "equalizer=f=80:t=h:w=1.0:g=-14",
    "lowpass=f=7400",
  ]
  # This gate+compressor+denoise stack was tuned for spoken rap phrasing
  # (gaps between bars, percussive onsets); on a sung/harmony vocal it can
  # gate mid-note and read as choppy/robotic. RAP_VOCAL_RAW=1 skips it for
  # a minimal pass -- same "unprocessed beats over-processed" pattern that
  # fixed audibility on the original rap vocal chain.
  return base.join(",") if ENV["RAP_VOCAL_RAW"] == "1"
  (base + [
    "afftdn=nr=8:nf=-32:tn=1",
    "agate=threshold=0.02:ratio=5:attack=2:release=50:range=0.0006:makeup=1.2",
    "acompressor=threshold=-24dB:ratio=2:attack=5:release=100:makeup=2",
  ]).join(",")
end

# First substantial phrase — skip instrumental intro left in the "vocals" stem.
# Start of the densest stretch of actual singing, given how much audio the fit
# needs. Choosing the *earliest* strong phrase is wrong for any stem with gaps:
# gunnhild has a short pocket of singing at 0-16s, then 80 seconds of nothing,
# then its real verse at 96-128s. Starting at the earliest phrase (1.7s) drags
# a 32-bar fit straight through the dead middle. Scoring windows by voiced
# coverage picks the verse instead, and needs no threshold tuned per stem.
def rap_vocal_content_offset(path, needed_sec)
  r = begin
    frame_energy(path, highpass: 200, lowpass: 6_000)
  rescue StandardError
    nil
  end
  return unless r && r[:frames].is_a?(Array) && r[:frames].any?

  hop = r[:hop_seconds].to_f
  return unless hop.positive?

  vals = r[:frames].map { |f| f.is_a?(Array) ? f.last.to_f : f.to_f }
  peak = vals.max.to_f
  return unless peak.positive?

  voiced = vals.map { |v| v > peak * 0.06 ? 1 : 0 }
  # Score a modest window, not the full length the fit needs. A long render can
  # need more continuous singing than the stem physically contains -- gunnhild
  # holds ~32s of real verse against the 88s a 32-bar fit consumes -- and
  # scoring at that length picks the least-bad window spanning the dead middle
  # (measured: 25% voiced) instead of the verse. Locating the densest short
  # region lands on the verse every time; the crossfade loop in rap_vocal_fit!
  # is what covers the remaining duration.
  win = [[(([needed_sec, 16.0].min) / hop).round, 1].max, voiced.size - 1].min
  return 0.0 if win < 1

  # Rolling sum: best-scoring window start, ties going to the earlier one.
  sum = voiced.first(win).sum
  best_sum = sum
  best_i = 0
  (win...voiced.size).each do |i|
    sum += voiced[i] - voiced[i - win]
    if sum > best_sum
      best_sum = sum
      best_i = i - win + 1
    end
  end
  (best_i * hop).round(3)
end

# Earliest phrase strong enough to be real speech rather than residual bleed.
# The threshold is RELATIVE to the strongest phrase in this stem, because
# onset strength scales with the stem's level and stems vary by tens of dB.
# A fixed 0.22 floor meant a quiet stem had almost nothing clear it: gunnhild
# had 2 of 16 phrases qualify, both near the very end, so the fit started at
# 116.5s of a 128s file and looped the last 11s over and over. Scaling to the
# stem keeps the same intent -- skip the weak stuff, start at real singing --
# without assuming a level.
def rap_vocal_phrase_start(phrases, min_strength: nil)
  entries = Array(phrases).filter_map do |p|
    s = (p["start"] || p[:start]).to_f
    st = (p["strength"] || p[:strength]).to_f
    next if s < 1.0
    [s, st]
  end
  return if entries.empty?

  peak = entries.map(&:last).max.to_f
  floor = min_strength || (peak.positive? ? [peak * 0.6, 0.22].min : 0.0)
  strong = entries.select { |(_, st)| st <= 0.0 || st >= floor }
  (strong.empty? ? entries : strong).map(&:first).min
end

# Level the isolation chain expects to see. Its two agate stages fire on
# ABSOLUTE thresholds (0.028 and 0.016), so they only mean anything if the stem
# arrives somewhere near this. Demucs output level varies enormously between
# sources -- measured here: slum_village -9.8 dB, jonas_v -18.0 dB, gunnhild
# -46.8 dB -- and a stem whose PEAK (0.0245) sits below the first gate's
# threshold is erased in its entirety. That is what happened to gunnhild: its
# main verse went from 98% voiced in the raw demucs stem to 5% after cleaning,
# and because the result overwrote the source and set isolated: true, the
# damage looked like a bad recording rather than a bad gate.
RAP_VOCAL_CLEAN_TARGET_DB = (ENV["RAP_VOCAL_CLEAN_TARGET_DB"] || -18.0).to_f

def rap_vocal_clean_stem!(src, dest = nil, aggressive: true)
  dest ||= src.sub(/\.wav\z/i, ".clean.wav")
  dest = "#{src}.clean.wav" if dest == src
  chain = aggressive ? rap_vocal_isolation_filter : rap_vocal_voice_polish_filter
  pre = ""
  if aggressive
    measured = begin
      band_rms(src, highpass: 200, lowpass: 6_000)
    rescue StandardError
      nil
    end
    if measured&.finite? && measured < RAP_VOCAL_CLEAN_TARGET_DB
      gain = (RAP_VOCAL_CLEAN_TARGET_DB - measured).clamp(0.0, 36.0)
      pre = "volume=#{gain.round(2)}dB,"
      dmesg("vocal clean: stem at #{measured.round(1)}dB, pre-gain +#{gain.round(1)}dB into gate range",
            unit: "vox0", parent: "dilla0")
    end
  end
  sh! "ffmpeg", "-y", "-i", src,
      "-af", "#{pre}#{chain},loudnorm=I=-17:TP=-2.5:LRA=7,alimiter=limit=0.93:level_out=0.94",
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", dest
  dest
end

# Finds the offset, in the vocal's OWN timeline, whose bar grid best lines up
# with where the singing actually lands.
#
# It used to grid against the *target* bar length while scoring *source-time*
# onsets. Those are only the same length when the vocal is already at the beat's
# tempo. gunnhild is 87 against a 92 BPM beat, so the search compared onsets
# spaced ~2.759s to a 2.609s grid: 5.7% out, accumulating to most of a bar over
# 16, and the offset it returned was meaningless. That is the whole of "not beat
# matched" — atempo got the tempo right and the phase was never right.
#
# source_bpm is the vocal's tempo; the caller stretches by beat_bpm/source_bpm
# afterwards, which maps this source grid exactly onto the beat's.
def rap_vocal_best_bar_offset(vocal_path, source_bpm, phrases: nil)
  phrase_times = Array(phrases).filter_map { |p| p["start"] || p[:start] }
  if phrase_times.empty?
    rhythm = frame_energy(vocal_path, highpass: 300, lowpass: 6000)
    phrase_times = peak_frames(rhythm[:frames], rhythm[:hop_seconds]).map { |p| p[:time] }
  end
  return 0.0 if phrase_times.empty?

  bar_sec = (60.0 / source_bpm.to_f) * 4.0
  beat_sec = bar_sec / 4.0
  # Tolerance scales with tempo rather than a fixed 60ms: at 87 BPM a beat is
  # 690ms, so 60ms is ~9% of a beat here and a different fraction at any other
  # tempo.
  window = beat_sec * 0.08
  best = 0.0
  best_score = -1.0

  # Search one whole bar in 5ms steps. The old loop stepped 25ms over a range
  # derived from the bar length, which at slower tempos ran well past a bar and
  # scored the same phase repeatedly.
  steps = (bar_sec / 0.005).round
  (0..steps).each do |i|
    offset = i * 0.005
    # Weight downbeats above backbeats above the other beats: a vocal phrase
    # starting on beat 1 is worth more evidence than one starting on beat 4.
    score = phrase_times.sum do |t|
      rel = (t - offset) % bar_sec
      dist_to_beat = [rel % beat_sec, beat_sec - (rel % beat_sec)].min
      next 0.0 if dist_to_beat > window

      beat_index = ((rel / beat_sec).round % 4)
      case beat_index
      when 0 then 1.0
      when 2 then 0.6
      else 0.3
      end
    end
    next unless score > best_score

    best_score = score
    best = offset
  end
  best.round(4)
end

def rap_vocal_resolve(slug_or_path)
  raw = slug_or_path.to_s
  return raw if raw.end_with?(".wav", ".mp3", ".m4a") && File.file?(raw)
  cat = rap_vocal_load_catalog
  vocals = Array(cat["vocals"])
  return if vocals.empty?
  if raw.empty? || raw == "auto"
    # Was `vocals[iterate_count % vocals.length]`, which rotated the stream
    # through every catalogued voice -- slum_village, jonas_v, singers_unlimited
    # -- so "auto" meant "whoever is next", not "the vocal".
    return vocals.find { |v| v["slug"] == RAP_VOCAL_SOURCE } || vocals.first
  end
  vocals.find { |v| v["slug"] == raw || v["artist"].to_s.casecmp(raw).zero? } ||
    vocals.find { |v| v["slug"].to_s.include?(raw) }
end

# Never auto-fallback to random catalog entries (that pulled in sirkel_sag).
RAP_VOCAL_BLOCKLIST = %w[sirkel_sag].freeze

# Same-song vocal-stem overrides (used to route pedal_e_descent to the
# slum_village stem). Emptied on request: gunnhild is the only vocal source;
# the mechanism stays for when that decision changes.
TRACK_MATCHED_VOCAL_SLUG = {}.freeze

def rap_vocal_stream_slug
# Beats the presets: an operator who said 0 gets 0.
return if VOCALS_EXPLICITLY_OFF
  slug = ENV["RAP_VOCAL"].to_s.strip
  return if slug.empty? || slug == "0"
  return if RAP_VOCAL_BLOCKLIST.include?(slug)
  if slug == "auto" || slug == "gunnhild"
    track = ENV["TRACK"].to_s.downcase.tr("-", "_")
    matched = TRACK_MATCHED_VOCAL_SLUG[track]
    return matched if matched
  end
  if slug == "auto"
    cat = rap_vocal_load_catalog
    pick = Array(cat["vocals"]).find do |v|
      s = v["slug"].to_s
      next false if RAP_VOCAL_BLOCKLIST.include?(s)
      next false unless File.file?(v["vocal_path"].to_s)
      peak = band_rms(v["vocal_path"], highpass: 80, lowpass: 8_000) rescue -90.0
      peak >= -45.0
    end
    return pick&.dig("slug")
  end
  cat = rap_vocal_load_catalog
  entry = Array(cat["vocals"]).find { |v| v["slug"] == slug }
  unless entry && entry["vocal_path"] && File.file?(entry["vocal_path"])
    warn "rap-vocal: #{slug} missing from catalog — skipping vocals"
    return
  end
  peak = band_rms(entry["vocal_path"], highpass: 80, lowpass: 8_000) rescue -90.0
  if peak < -55.0
    warn "rap-vocal: #{slug} too quiet (≈#{peak.round(1)} dB) — skipping (no fallback)"
    return
  end
  slug
end

def rap_vocal_ingest!(artist, src)
  ensure_demucs_ready!
  DillaSourceLearn.ensure_dir!
  slug = rap_vocal_slug(artist)
  out_dir = File.join(RAP_VOCAL_DIR, slug)
  FileUtils.mkdir_p(out_dir)
  stem_dir = demux_vocal_isolate(src)
  vocal_src = File.join(stem_dir, "vocals.wav")
  unless File.file?(vocal_src)
    warn "rap-vocal ingest: demucs produced no vocals.wav in #{stem_dir}"
    return
  end
  vocal_dest = File.join(out_dir, "vocals.wav")
  # Demucs "vocals" still carries kit/bass bleed — voice-only isolate before catalog.
  # Never catalog drums/bass/other stems — only this cleaned vocals.wav path is mixed.
  rap_vocal_clean_stem!(vocal_src, vocal_dest, aggressive: true)
  analysis = RadioBergenStudy::DeepAudio.analyze(vocal_dest)
  phrases = rap_vocal_phrase_onsets(vocal_dest)
  entry = {
    "slug" => slug, "artist" => artist.to_s, "source" => src.to_s,
    "vocal_path" => vocal_dest, "stem_dir" => stem_dir,
    "bpm_estimate" => analysis[:bpm_estimate],
    "phrases" => phrases, "ingested_at" => Time.now.utc.iso8601,
    "isolated" => true, "voice_only" => true
  }
  cat = rap_vocal_load_catalog
  cat["vocals"] = Array(cat["vocals"]).reject { |v| v["slug"] == slug } + [entry]
  rap_vocal_save_catalog!(cat)
  File.write(File.join(out_dir, "meta.json"), JSON.pretty_generate(entry) + "\n")
  puts "rap-vocal ingest: #{artist} → #{vocal_dest} bpm=#{analysis[:bpm_estimate]} phrases=#{phrases.length}"
  entry
end

# Fold raw onset BPM into the stream pocket (≈76–100). Avoids the 66.7 trap
# where *2 → 133 and /2 → 66.7 forever (never lands in-range).
# Folds a measured tempo to the octave nearest the beat it has to sit against.
#
# Octaves only. The pool used to include b*1.5, b/1.5, b*4/3 and b*3/4, and
# those do not preserve where the beats are — they re-grid the whole take at a
# different meter. That is how gunnhild came to be catalogued at 87 BPM: the
# analyser measured ~116, 116 * 3/4 = 87.0 landed inside the 74-100 window and
# won for being nearest 90. Every fit since has been stretching a 120 BPM vocal
# as though it were 87, which no phase correction downstream can rescue.
#
# Folding toward `target` rather than a fixed 90 also picks the smaller stretch:
# a 120 BPM vocal over a 92 BPM beat is a 0.77x slowdown at 120, or a 1.53x
# speedup at 60. Both are legal; the first does far less damage to the voice.
def rap_vocal_fold_bpm(raw, target: nil)
  b = raw.to_f
  return unless b.positive?

  pool = (-2..2).map { |k| b * (2.0**k) }.select { |x| x.between?(40.0, 220.0) }
  return b.round(2) if pool.empty?

  aim = target.to_f.positive? ? target.to_f : 90.0
  # Nearest in log space: the cost of a stretch is its ratio, not its
  # difference in BPM.
  pool.min_by { |x| (Math.log(x / aim)).abs }.round(2)
end

# Measures a vocal's tempo from its own onsets: for each candidate BPM, take the
# best phase and count onsets landing within 10% of a beat. The true tempo spikes
# well clear of the field; a take with no steady pulse produces no spike, which
# is worth knowing before trying to stretch it onto a grid.
#
# Verified against a synthesised 100 BPM click: 39/39 onsets on grid at 100,
# 20/39 at the neighbours.
def rap_vocal_measure_bpm(vocal_path, range: (60..180))
  # Memoised: the fit path asks twice per render -- once for the tempo, once for
  # "does this take have a pulse at all" -- and the sweep is a few hundred phase
  # searches over the whole onset list.
  @rap_vocal_bpm_cache ||= {}
  key = [vocal_path, range]
  return @rap_vocal_bpm_cache[key] if @rap_vocal_bpm_cache.key?(key)

  @rap_vocal_bpm_cache[key] = rap_vocal_measure_bpm_uncached(vocal_path, range:)
end

def rap_vocal_measure_bpm_uncached(vocal_path, range: (60..180))
  onsets = rap_vocal_onset_times(vocal_path)
  return nil if onsets.size < 8

  scored = range.map do |bpm|
    beat = 60.0 / bpm
    tol = beat * 0.10
    best = 0
    (0..(beat / 0.005).to_i).each do |i|
      phase = i * 0.005
      hits = onsets.count { |t| r = (t - phase) % beat; [r, beat - r].min < tol }
      best = hits if hits > best
    end
    [bpm.to_f, best]
  end

  bpm, hits = scored.max_by { |(_, h)| h }
  # A random phase hits ~20% at this tolerance, so an absolute floor alone is
  # too easy to clear. A real pulse also stands clear of its neighbours: the
  # 100 BPM click scores 100% at the true tempo against 51% either side. Gunnhild
  # scores 35% at 96 with 34% at 168 and 32% at 147 — no winner, noise with
  # a lean, and returning 96 from that produced a "beat match" no better than
  # chance. Require both the floor and real separation from the best unrelated
  # rival, or admit there is no tempo here.
  return nil if hits < onsets.size * 0.32

  related = ->(other) { r = other / bpm; [0.25, 0.5, 1.0, 2.0, 4.0].any? { |k| (r - k).abs < 0.04 } }
  rival = scored.reject { |(b, _)| related.call(b) }.map(&:last).max.to_i
  return nil if rival.positive? && hits < rival * 1.25

  bpm
end

def rap_vocal_onset_times(vocal_path, hop: 0.010)
  rate = 8000
  raw = IO.popen(["ffmpeg", "-v", "error", "-i", vocal_path, "-ac", "1",
                  "-ar", rate.to_s, "-f", "s16le", "-"], "rb", &:read)
  samples = raw.to_s.unpack("s<*")
  return [] if samples.empty?

  frame = (rate * hop).to_i
  env = samples.each_slice(frame).map { |c| Math.sqrt(c.sum { |s| (s / 32_768.0)**2 } / c.size) }

  window = 12
  last = -1.0
  env.each_with_index.filter_map do |e, i|
    next if i < window

    floor = env[(i - window)...i].sum / window
    t = i * hop
    next unless e > floor * 2.2 && e > 0.004
    next if t - last < 0.12

    last = t
  end
end

# Prefer ENV override, then a real measurement, then the stored estimate.
def rap_vocal_source_bpm(entry, vocal_path, target: nil)
  forced = ENV["RAP_VOCAL_BPM"].to_f
  return forced if forced.positive?

  # Measurement first. The stored bpm_estimate is whatever the ingest analyser
  # said once, already folded — gunnhild sat at 87 for weeks against a source
  # that measures 120, and nothing downstream could tell.
  measured = rap_vocal_measure_bpm(vocal_path)
  return rap_vocal_fold_bpm(measured, target:) if measured

  candidates = []
  if entry.is_a?(Hash)
    candidates << entry["bpm_estimate"].to_f
    candidates << entry.dig("last_fit", "source_bpm").to_f
  end
  if candidates.none?(&:positive?)
    analysis = RadioBergenStudy::DeepAudio.analyze(vocal_path) rescue nil
    candidates << analysis&.dig(:bpm_estimate).to_f
    candidates << analysis&.dig(:bpm_estimate_kick).to_f
    candidates << analysis&.dig(:bpm_estimate_snare).to_f
  end
  rap_vocal_fold_bpm(candidates.find { |b| b&.positive? }, target:)
end

# --------------------------------------------------------------------------
# engine part: organic
# --------------------------------------------------------------------------
#
# Organic movement: breath, swell, and letting the sample drive the pads.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- breathing --------------------------------------------------------------
#
# The engine already owns vibrato, chorus, tremolo, phaser and a drift filter.
# More of those does not make a pad breathe, because all of them are periodic,
# independent and fixed-rate: three unrelated motions at constant speed read as
# a static sound with effects on it. Two things are missing.
#
# ORGANIC_BREATH=1  drives loudness and brightness from ONE control signal, so
#   the pad gets louder and brighter together the way a played instrument does
#   when the player pushes. Correlation is the whole point; two independent
#   modulations at the same depths do not sound like this.
#
# ORGANIC_SWELL=1   swells across the phrase and relaxes out of it -- the
#   literal breath. Measured motivation: renders here come out at LRA 2.9, so
#   bar 1 and bar 17 are equally loud, which no played performance is.
# Default on. One control signal drives loudness and brightness together, which
# is how an acoustic source behaves — playing louder is also playing brighter.
ORGANIC_BREATH = ENV.fetch("ORGANIC_BREATH", "1") != "0"
# Default on. Swells across a phrase and relaxes out of it, so a loop stops
# arriving at every bar with identical energy.
ORGANIC_SWELL = ENV.fetch("ORGANIC_SWELL", "1") != "0"
ORGANIC_BREATH_DB = (ENV["ORGANIC_BREATH_DB"] || 2.2).to_f.clamp(0.0, 12.0)
ORGANIC_SWELL_DB = (ENV["ORGANIC_SWELL_DB"] || 3.0).to_f.clamp(0.0, 12.0)
ORGANIC_SWELL_BARS = (ENV["ORGANIC_SWELL_BARS"] || 4).to_f.clamp(1.0, 32.0)
# How dark the closed end of the brightness sweep is. The bright branch is the
# untouched signal, so this is the only tone control here.
ORGANIC_DARK_HZ = (ENV["ORGANIC_DARK_HZ"] || 1400).to_i

# Three incommensurate rates. A single LFO at 0.13 Hz repeats every 7.7s and the
# ear learns it; periods of 27s, 16s and 11s sum to something whose repeat is
# far longer than any track, so it never settles into a pattern. Fixed rather
# than random so a render reproduces -- an irregularity you cannot get back is
# an accident, not a character.
ORGANIC_RATES = [[0.037, 0.45, 0.0], [0.061, 0.35, 1.3], [0.089, 0.20, 2.7]].freeze

# Control signal in 0..1, as an ffmpeg expression over t.
def organic_control_expr
  terms = ORGANIC_RATES.map do |hz, amp, phase|
    "#{amp}*sin(2*PI*#{hz}*t+#{phase})"
  end
  "(0.5+0.5*(#{terms.join('+')}))"
end

# Raised cosine over the phrase: quietest at the phrase boundary, fullest in the
# middle, so it lands with the chord changes instead of cutting across them.
def organic_swell_expr(bar_sec)
  phrase = (bar_sec * ORGANIC_SWELL_BARS).round(4)
  "(0.5-0.5*cos(2*PI*t/#{phrase}))"
end

# Returns filter fragments taking [in_label] to [out_label].
#
# Brightness is done by crossfading a full-band branch against a lowpassed one,
# because ffmpeg's lowpass takes a fixed frequency and cannot be swept. Summing
# a dark copy and a bright copy under complementary time-varying gains gets the
# same result with filters that do support per-frame evaluation.
def organic_breath_filters(in_label, out_label, bar_sec:, mode: :breath)
  drive = mode == :swell ? organic_swell_expr(bar_sec) : organic_control_expr
  depth = mode == :swell ? ORGANIC_SWELL_DB : ORGANIC_BREATH_DB
  # Centred on 0 dB so the average level is unchanged and this is heard as
  # movement rather than as a level change.
  gain = "(#{depth}*(#{drive}-0.5)*2)"

  [
    "[#{in_label}]asplit=2[br_a][br_b]",
    "[br_a]volume=#{'%.4f' % 1.0}:eval=frame[br_bright]",
    "[br_b]lowpass=f=#{ORGANIC_DARK_HZ}[br_dark]",
    # Bright rises with the drive, dark falls: same signal, tone opening and
    # closing with the loudness rather than on its own schedule.
    "[br_bright]volume='#{drive}':eval=frame[br_bw]",
    "[br_dark]volume='(1-#{drive})':eval=frame[br_dw]",
    "[br_bw][br_dw]amix=inputs=2:normalize=0[br_mix]",
    "[br_mix]volume='exp(#{gain}*0.11512925)':eval=frame[#{out_label}]",
  ]
end

# The sample drives the synths, instead of merely sitting beside them.
#
# Until now the loop and the generated parts have coexisted without ever
# touching: HARMONIC_KEEP puts them in the same key, the mix puts them at
# compatible levels, and that is the whole of their relationship. This makes
# the loop the control signal -- its amplitude envelope shapes the pad bus, so
# when the sample moves the pads move with it, and the two read as one
# instrument rather than as two things playing at once.
#
# amultiply against a smoothed, floored envelope rather than sidechaincompress:
# a compressor ducks below a threshold and is otherwise absent, while
# multiplying imposes the sample's shape continuously. The floor stops the pads
# vanishing in the loop's gaps -- at 0 this becomes a gate and the harmony
# disappears wherever the sample rests, which is a different effect entirely.
SAMPLE_DRIVES_PADS = (ENV["SAMPLE_DRIVES_PADS"] || 0).to_f.clamp(0.0, 1.0)
SAMPLE_DRIVE_FLOOR = (ENV["SAMPLE_DRIVE_FLOOR"] || 0.45).to_f.clamp(0.0, 1.0)
SAMPLE_DRIVE_SMOOTH_HZ = (ENV["SAMPLE_DRIVE_SMOOTH_HZ"] || 14).to_i

def sample_drives_pads!(harmonic_path, loop_path, duration:)
  return harmonic_path unless SAMPLE_DRIVES_PADS.positive?
  return harmonic_path unless harmonic_path && loop_path
  return harmonic_path unless File.file?(harmonic_path) && File.file?(loop_path)

  env_path = "#{harmonic_path}.drive.wav"
  out = "#{harmonic_path}.driven.wav"
  depth = SAMPLE_DRIVES_PADS
  floor = 1.0 - ((1.0 - SAMPLE_DRIVE_FLOOR) * depth)
  begin
    sh! "ffmpeg", "-y", "-stream_loop", "-1", "-i", loop_path,
        "-af", "highpass=f=80,lowpass=f=6000," \
               "aeval=abs(val(0))|abs(val(1))," \
               "lowpass=f=#{SAMPLE_DRIVE_SMOOTH_HZ}," \
               "volume=#{(1.0 - floor).round(4)}," \
               "aeval=val(0)+#{floor.round(4)}|val(1)+#{floor.round(4)}," \
               "atrim=0:#{duration.round(3)},apad=whole_dur=#{duration.round(3)}",
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", env_path
    sh! "ffmpeg", "-y", "-i", harmonic_path, "-i", env_path,
        "-filter_complex",
        "[0:a]atrim=0:#{duration.round(3)},apad=whole_dur=#{duration.round(3)}[pads];" \
        "[pads][1:a]amultiply,alimiter=limit=0.95:level_out=0.96[out]",
        "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
        "-c:a", "pcm_s16le", out
    FileUtils.mv(out, harmonic_path)
    dmesg("sample drives pads: depth #{depth}, floor #{floor.round(2)}",
          unit: "harm0", parent: "dilla0")
    harmonic_path
  rescue StandardError => e
    warn "sample drives pads: #{e.message}"
    FileUtils.rm_f(out)
    harmonic_path
  ensure
    FileUtils.rm_f(env_path)
  end
end

# --------------------------------------------------------------------------
# engine part: crate
# --------------------------------------------------------------------------
#
# Building the crate, and importing/exporting drum MIDI.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- the crate ----------------------------------------------------------------
#
# One-shots and sustains to chop, synthesised rather than dug for. Every voice
# here is built from oscillators and filtered noise, so the crate carries no
# provenance question and can be regenerated on any machine from this file
# alone -- which is also why it is a command and not a folder of wav files
# committed once and never reproducible.
#
# The tonal voices are additive: a harmonic series with per-instrument weights
# and an envelope. That is not a sampled Rhodes and does not pretend to be one,
# but a Rhodes IS a struck tine with a bell-like odd-harmonic spectrum and a
# fast attack, and additive synthesis reproduces that description directly.
CRATE_DIR = File.join(SAMPLE_DIR, "crate").freeze

# [harmonic, amplitude] pairs. Rhodes leans odd (tine), vibes are nearly pure
# with a slow beat, the analog voices carry a full series shaped by the filter.
CRATE_VOICES = {
  rhodes:   { harmonics: [[1, 1.0], [2, 0.28], [3, 0.42], [5, 0.16], [7, 0.08]],
              attack: 0.004, decay: 2.8, lowpass: 3800, trem: 0.0 },
  vibes:    { harmonics: [[1, 1.0], [4, 0.18], [9, 0.06]],
              attack: 0.002, decay: 3.6, lowpass: 5200, trem: 5.5 },
  cs80:     { harmonics: [[1, 1.0], [2, 0.5], [3, 0.33], [4, 0.25], [5, 0.2], [6, 0.16]],
              attack: 0.35, decay: 4.0, lowpass: 2600, trem: 0.0 },
  prophet:  { harmonics: [[1, 1.0], [2, 0.45], [3, 0.3], [4, 0.2], [6, 0.12]],
              attack: 0.12, decay: 3.2, lowpass: 3200, trem: 0.0 },
  jupiter:  { harmonics: [[1, 1.0], [2, 0.55], [3, 0.4], [5, 0.22], [7, 0.14], [9, 0.09]],
              attack: 0.02, decay: 2.2, lowpass: 4400, trem: 0.0 },
}.freeze

# Chords worth having under the fingers, in the keys the sampled loops read as.
CRATE_CHORDS = { "Cm9" => [130.81, "m9"], "Fm9" => [174.61, "m9"],
                 "Ebmaj9" => [155.56, "maj9"], "Gm9" => [196.00, "m9"],
                 "Dmaj9" => [146.83, "maj9"], "Am7b5" => [220.00, "m7b5"] }.freeze

def crate_tonal_expr(freqs, voice)
  spec = CRATE_VOICES.fetch(voice)
  terms = freqs.flat_map do |f|
    spec[:harmonics].map do |mult, amp|
      hz = (f * mult).round(3)
      next nil if hz > 16_000

      "#{(amp / freqs.size / spec[:harmonics].size * 2.4).round(5)}*sin(2*PI*#{hz}*t)"
    end.compact
  end
  # Struck envelope: near-instant rise, exponential fall. `trem` adds the slow
  # amplitude beat a vibraphone's rotating discs produce.
  env = "(1-exp(-t/#{spec[:attack]}))*exp(-t/#{spec[:decay]})"
  env = "#{env}*(1+#{(0.22).round(3)}*sin(2*PI*#{spec[:trem]}*t))" if spec[:trem].positive?
  ["(#{terms.join('+')})*#{env}", spec[:lowpass]]
end

# Noise textures. Crackle is impulsive and sparse, hiss is steady and bright,
# rumble is slow and almost sub -- three different things that all get called
# "vinyl noise" and do not substitute for each other.
CRATE_TEXTURES = {
  vinyl_crackle: "anoisesrc=color=white:amplitude=0.5:seed=#{noise_seed(25)}," \
                 "highpass=f=1200,lowpass=f=9000," \
                 "acompressor=threshold=-46dB:ratio=20:attack=0.05:release=8," \
                 "volume=7dB",
  tape_hiss:     "anoisesrc=color=white:amplitude=0.06:seed=#{noise_seed(26)},highpass=f=2500,lowpass=f=13000",
  turntable_rumble: "anoisesrc=color=brown:amplitude=0.5:seed=#{noise_seed(27)},lowpass=f=90,volume=4dB",
  room_tone:     "anoisesrc=color=pink:amplitude=0.12:seed=#{noise_seed(28)},highpass=f=120,lowpass=f=2200,volume=-6dB",
}.freeze

# Percussion, synthesised the way the physical thing works: a brush is noise
# with a fast decay, a conga is a pitched body with a noise transient, a shaker
# is a burst of high noise and nothing else.
CRATE_PERCUSSION = {
  brush_hit:  "anoisesrc=color=white:amplitude=0.8:seed=#{noise_seed(29)},highpass=f=900,lowpass=f=7000," \
              "afade=t=out:st=0:d=0.28",
  shaker:     "anoisesrc=color=white:amplitude=0.7:seed=#{noise_seed(30)},highpass=f=5000," \
              "afade=t=out:st=0:d=0.09",
  conga:      "aevalsrc='0.8*sin(2*PI*196*t)*exp(-t/0.22)+0.3*sin(2*PI*300*t)*exp(-t/0.09)':d=1," \
              "lowpass=f=2600",
  rimshot:    "aevalsrc='0.7*sin(2*PI*420*t)*exp(-t/0.035)':d=0.4,highpass=f=250",
}.freeze

# The texture and percussion strings BEGIN with a generator (anoisesrc,
# aevalsrc), so they are the input graph, not a filter applied to one. Chaining
# them onto an anullsrc input fails: a source filter cannot take an input.
def crate_render_one!(dest, generator, duration, lowpass: nil)
  post = []
  post << "lowpass=f=#{lowpass}" if lowpass
  post << "afade=t=out:st=#{[(duration - 0.05), 0].max.round(3)}:d=0.05"
  sh! "ffmpeg", "-y", "-f", "lavfi", "-i", generator,
      "-af", post.join(","), "-t", duration.to_s,
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", dest
  dest
end

# Reads a folder of MIDI drum clips and reports them as 16-step grids.
#
# A third provenance category, kept distinct from the other two: these are
# neither transcriptions of records nor constructions of mine, but patterns
# supplied in a pack the operator licensed. Being able to say which of the three
# a grid is matters more than having more grids.
#
# Note density is deliberately split rather than flattened: a MIDI snare part
# usually has two or three structural hits and a tail of ghost notes, and
# folding them together produces a grid that reads as busy rather than as a
# backbeat with detail under it. The loudest velocities become the part, the
# rest become ghosts.
def midi_drum_grid(path, ghost_below: 0.72)
  require "midilib"
  seq = MIDI::Sequence.new
  File.open(path, "rb") { |io| seq.read(io) }
  hits = []
  seq.each do |track|
    track.each do |ev|
      next unless ev.is_a?(MIDI::NoteOn) && ev.velocity.positive?

      hits << [((ev.time_from_start.to_f / seq.ppqn) * 4).round % 16, ev.velocity]
    end
  end
  return { steps: [], ghosts: [] } if hits.empty?

  peak = hits.map(&:last).max.to_f
  loud = hits.select { |(_, v)| v >= peak * ghost_below }.map(&:first).uniq.sort
  soft = hits.reject { |(_, v)| v >= peak * ghost_below }.map(&:first).uniq.sort - loud
  { steps: loud, ghosts: soft }
rescue StandardError => e
  warn "midi #{File.basename(path)}: #{e.message}"
  { steps: [], ghosts: [] }
end

def import_midi_drums!(dir)
  unless File.directory?(dir)
    warn "import-midi: no such directory #{dir}"
    return
  end

  groups = Hash.new { |h, k| h[k] = [] }
  Dir[File.join(dir, "**", "*.mid")].sort.each do |f|
    name = File.basename(f, ".mid").downcase
    role = case name
           when /open\s*hat|open_hat/ then :open
           when /hi\s*hat|hihat|hat/ then :hats
           when /kick|bd/ then :kicks
           when /snare|sd|clap/ then :snares
           when /perc|rim|tom|conga|shaker/ then :perc
           else next
           end
    groups[role] << [f, midi_drum_grid(f)]
  end

  if groups.empty?
    warn "import-midi: no kick/snare/hat clips found in #{dir}"
    return
  end

  slug = File.basename(dir).to_s.downcase.gsub(/[^a-z0-9]+/, "_").gsub(/\A_|_\z/, "")
  slug = "pack" if slug.empty?
  count = [groups[:kicks].size, groups[:snares].size, groups[:hats].size].reject(&:zero?).min || 0
  puts "# Imported from #{File.basename(dir)} — pack-supplied MIDI, not transcription."
  (0...count).each do |i|
    k = groups[:kicks][i]&.last || { steps: [], ghosts: [] }
    s = groups[:snares][i]&.last || { steps: [], ghosts: [] }
    h = groups[:hats][i]&.last || { steps: [], ghosts: [] }
    o = groups[:open][i % [groups[:open].size, 1].max]&.last || { steps: [] }
    p = groups[:perc][i % [groups[:perc].size, 1].max]&.last || { steps: [] }
    puts "    #{slug}_#{i + 1}: {"
    puts "      swing: 52, humanize: 2, bpm: 140, mode: :straight_sixteenth,"
    puts "      kicks: #{k[:steps].inspect}, snares: #{s[:steps].inspect}, " \
         "hats: #{h[:steps].inspect},"
    puts "      ghosts: #{(s[:ghosts] + k[:ghosts]).uniq.sort.inspect}, " \
         "claps: #{s[:steps].inspect}, perc: #{(o[:steps] + p[:steps]).uniq.sort.inspect}"
    puts "    },"
  end
  count
end

# GM drum map note numbers (channel 9).
DRUM_MIDI_NOTES = {
  kick: 36, snare: 38, hat: 42, open: 46, clap: 39, perc: 37, ghost: 38
}.freeze

MIDI_SEED_DIR = File.join(ROOT, "samples", "midi").freeze

# Write a one-bar 16-step GM drum SMF for a single voice (kick/snare/hat…).
def write_drum_role_smf(path, steps, note:, velocity: 100, ghost_steps: [], ghost_vel: 48, bpm: 90)
  # Ticks per 16th at SMF_PPQN (quarter = SMF_PPQN): 16th = PPQN/4.
  step_ticks = SMF_PPQN / 4
  channel = 9 # GM drums
  events = []
  Array(steps).each do |st|
    on = st.to_i * step_ticks
    events << [on, :on, note, velocity]
    events << [on + (step_ticks / 2), :off, note, 0]
  end
  Array(ghost_steps).each do |st|
    next if Array(steps).include?(st)

    on = st.to_i * step_ticks
    events << [on, :on, note, ghost_vel]
    events << [on + (step_ticks / 3), :off, note, 0]
  end
  events.sort_by! { |t, kind, *| [t, kind == :off ? 0 : 1] }

  track_events = []
  last = 0
  events.each do |tick, kind, n, v|
    delta = [tick - last, 0].max
    status = kind == :on ? (0x90 | channel) : (0x80 | channel)
    track_events << [delta, [status, n, v].pack("C*")]
    last = tick
  end
  # pad to full bar
  bar_end = 16 * step_ticks
  track_events << [[bar_end - last, 0].max, [0xFF, 0x2F, 0x00].pack("C*")]
  track_data = track_events.map { |delta, bytes| midi_vlq(delta) + bytes }.join
  track_chunk = "MTrk" + [track_data.bytesize].pack("N") + track_data
  header = "MThd" + [6].pack("N") + [0, 1, SMF_PPQN].pack("n3")
  FileUtils.mkdir_p(File.dirname(path))
  File.binwrite(path, header + track_chunk)
  path
end

# Export every DRUM_PRESET as split kick/snare/hat MIDI clips under samples/midi/.
# Re-importable via `ruby dilla.rb import-midi samples/midi/<preset>`.
def export_midi_drums!(dest_dir = MIDI_SEED_DIR)
  FileUtils.mkdir_p(dest_dir)
  written = 0
  DillaLofiMachine::DRUM_PRESETS.each do |name, grid|
    preset_dir = File.join(dest_dir, name.to_s)
    FileUtils.mkdir_p(preset_dir)
    bpm = grid[:bpm] || 90
    write_drum_role_smf(File.join(preset_dir, "kick.mid"), grid[:kicks],
                        note: DRUM_MIDI_NOTES[:kick], velocity: 110, bpm:)
    write_drum_role_smf(File.join(preset_dir, "snare.mid"), grid[:snares],
                        note: DRUM_MIDI_NOTES[:snare], velocity: 108,
                        ghost_steps: grid[:ghosts], ghost_vel: 52, bpm:)
    write_drum_role_smf(File.join(preset_dir, "hat.mid"), grid[:hats],
                        note: DRUM_MIDI_NOTES[:hat], velocity: 88, bpm:)
    if Array(grid[:claps]).any?
      write_drum_role_smf(File.join(preset_dir, "clap.mid"), grid[:claps],
                          note: DRUM_MIDI_NOTES[:clap], velocity: 100, bpm:)
    end
    if Array(grid[:perc]).any?
      write_drum_role_smf(File.join(preset_dir, "perc.mid"), grid[:perc],
                          note: DRUM_MIDI_NOTES[:perc], velocity: 90, bpm:)
    end
    # Combined kit SMF (all voices on ch.10) for DAW drag-in.
    combo = File.join(preset_dir, "#{name}_kit.mid")
    write_combined_drum_smf(combo, grid)
    written += 1
  end
  puts "export-midi: #{written} presets → #{dest_dir}"
  written
end

def write_combined_drum_smf(path, grid)
  step_ticks = SMF_PPQN / 4
  channel = 9
  events = []
  {
    kicks: [DRUM_MIDI_NOTES[:kick], 110],
    snares: [DRUM_MIDI_NOTES[:snare], 108],
    hats: [DRUM_MIDI_NOTES[:hat], 88],
    claps: [DRUM_MIDI_NOTES[:clap], 100],
    perc: [DRUM_MIDI_NOTES[:perc], 90],
    ghosts: [DRUM_MIDI_NOTES[:ghost], 50],
  }.each do |role, (note, vel)|
    Array(grid[role]).each do |st|
      on = st.to_i * step_ticks
      events << [on, :on, note, vel]
      events << [on + (step_ticks / 2), :off, note, 0]
    end
  end
  events.sort_by! { |t, kind, *| [t, kind == :off ? 0 : 1] }
  track_events = []
  last = 0
  events.each do |tick, kind, n, v|
    delta = [tick - last, 0].max
    status = kind == :on ? (0x90 | channel) : (0x80 | channel)
    track_events << [delta, [status, n, v].pack("C*")]
    last = tick
  end
  bar_end = 16 * step_ticks
  track_events << [[bar_end - last, 0].max, [0xFF, 0x2F, 0x00].pack("C*")]
  track_data = track_events.map { |delta, bytes| midi_vlq(delta) + bytes }.join
  track_chunk = "MTrk" + [track_data.bytesize].pack("N") + track_data
  header = "MThd" + [6].pack("N") + [0, 1, SMF_PPQN].pack("n3")
  FileUtils.mkdir_p(File.dirname(path))
  File.binwrite(path, header + track_chunk)
  path
end

def build_crate!(dest_dir = CRATE_DIR)
  FileUtils.mkdir_p(dest_dir)
  made = []

  CRATE_CHORDS.each do |name, (root, quality)|
    freqs = chord_from_root(root, quality)
    CRATE_VOICES.each_key do |voice|
      expr, lp = crate_tonal_expr(freqs, voice)
      path = File.join(dest_dir, "#{voice}_#{name}.wav")
      begin
        # aevalsrc generates; the null source above is replaced for tonal voices.
        sh! "ffmpeg", "-y", "-f", "lavfi",
            "-i", "aevalsrc='#{expr}':d=4:s=#{SAMPLE_RATE}",
            "-af", "lowpass=f=#{lp},afade=t=out:st=3.6:d=0.4," \
                   "alimiter=limit=0.9:level_out=0.92",
            "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", path
        made << path
      rescue StandardError => e
        warn "crate #{voice}/#{name}: #{e.message}"
      end
    end
  end

  CRATE_TEXTURES.each do |name, filter|
    path = File.join(dest_dir, "texture_#{name}.wav")
    begin
      crate_render_one!(path, filter, 8.0)
      made << path
    rescue StandardError => e
      warn "crate #{name}: #{e.message}"
    end
  end

  CRATE_PERCUSSION.each do |name, filter|
    path = File.join(dest_dir, "perc_#{name}.wav")
    begin
      crate_render_one!(path, filter, 1.0)
      made << path
    rescue StandardError => e
      warn "crate #{name}: #{e.message}"
    end
  end

  puts "crate: #{made.size} files in #{dest_dir}"
  made
end

# --------------------------------------------------------------------------
# engine part: sample_morph
# --------------------------------------------------------------------------
#
# Pitch shifting and FM-morphing a sample.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- morphing a sample toward FM -----------------------------------------------
#
# You cannot frequency-modulate a recording the way an FM operator modulates an
# oscillator -- there is no oscillator to modulate. But ffmpeg's vibrato accepts
# rates up to 20 kHz, and vibrato at an audio rate IS frequency modulation of
# whatever goes through it: the sidebands at carrier +- modulator are real, and
# they are what the ear hears as FM.
#
# Whether that sounds musical or like a fault is decided by ONE thing: the
# modulator's relationship to the material's own pitch. A modulator at an
# integer multiple of the root puts sidebands on harmonics and reads as a
# brighter, glassier version of the same note. An unrelated rate puts them
# between harmonics and reads as damage. So the rate is derived from the key
# this loop is actually in, not set in hertz.
SAMPLE_FM = ENV["SAMPLE_FM"] == "1"
# Modulator : root. 1, 2, 3 are harmonic and glassy; 1.414 or 3.5 go bell-like
# and inharmonic, which is the DX7 tubular-bell trick.
SAMPLE_FM_RATIO = (ENV["SAMPLE_FM_RATIO"] || 2.0).to_f.clamp(0.25, 16.0)
# Modulation index by another name. Past ~0.15 the pitch of the source stops
# being legible and it becomes texture rather than a note.
# With the floor below doing the protecting, depth can be generous: swept at
# 0.03/0.05/0.08/0.12 the chord band moved +0.0, +0.0, +0.0, +0.1 dB while the
# upper band moved -0.4, +0.2, +0.9, +1.5. The constraint is not the depth, it
# is where the modulation is allowed to reach.
SAMPLE_FM_DEPTH = (ENV["SAMPLE_FM_DEPTH"] || 0.08).to_f.clamp(0.0, 0.4)
SAMPLE_FM_MIX = (ENV["SAMPLE_FM_MIX"] || 0.55).to_f.clamp(0.0, 1.0)
# The FM branch is bandlimited from here up, and this is the whole safety of the
# effect. Modulating the fundamental and the low harmonics detunes the notes
# that carry the chord -- the harmony goes sour and it reads as damage rather
# than as timbre. Above ~700 Hz the sidebands land on overtones, which colours
# the sound while leaving the pitch and the chord exactly where they were. The
# first version highpassed at 60 Hz, which is to say not at all, and the result
# ate the harmonics it was supposed to be decorating.
SAMPLE_FM_FLOOR_HZ = (ENV["SAMPLE_FM_FLOOR_HZ"] || 700).to_i
# Inharmonic partials, the other half of the metallic FM character. In Hz, and
# deliberately small: a few Hz detunes the overtones against each other without
# moving the perceived pitch.
SAMPLE_FM_SHIFT_HZ = (ENV["SAMPLE_FM_SHIFT_HZ"] || 0).to_f.clamp(-200.0, 200.0)

# Scale expansion: the loop layered against transposed copies of itself at
# degrees of its OWN key, so one sample becomes a chord it was never playing.
# Degrees are semitones from the detected root -- the default is a minor triad
# because most of these loops read minor.
SAMPLE_SCALE = ENV["SAMPLE_SCALE"] == "1"
SAMPLE_SCALE_DEGREES = (ENV["SAMPLE_SCALE_DEGREES"] || "3,7").split(",").map(&:to_f)
SAMPLE_SCALE_MIX = (ENV["SAMPLE_SCALE_MIX"] || 0.4).to_f.clamp(0.0, 1.0)

# Root frequency of a detected key, low enough to be the fundamental rather than
# a harmonic of it.
def sample_root_hz(path)
  key = sample_key(path)
  return 65.41 unless key # C2 if the key cannot be read

  midi = 36 + key[0]
  (440.0 * (2.0**((midi - 69) / 12.0))).round(3)
end

# Pitch shift that keeps duration: resample to move pitch, then undo the speed
# change. atempo floors at 0.5 per stage, so large shifts chain.
def pitch_shift_filter(semitones)
  ratio = 2.0**(semitones / 12.0)
  stages = []
  comp = 1.0 / ratio
  while comp > 2.0
    stages << 2.0
    comp /= 2.0
  end
  while comp < 0.5
    stages << 0.5
    comp /= 0.5
  end
  stages << comp
  "asetrate=#{(SAMPLE_RATE * ratio).round},aresample=#{SAMPLE_RATE}," +
    stages.map { |s| "atempo=#{s.round(6)}" }.join(",")
end

def sample_morph!(src, dest)
  return src unless (SAMPLE_FM || SAMPLE_SCALE) && File.file?(src)

  root = sample_root_hz(src)
  branches = ["[0:a]anull[dry]"]
  labels = ["[dry]"]
  weights = ["1.0"]
  idx = 0

  if SAMPLE_FM
    mod_hz = (root * SAMPLE_FM_RATIO).round(2)
    shift = SAMPLE_FM_SHIFT_HZ.zero? ? "" : ",afreqshift=shift=#{SAMPLE_FM_SHIFT_HZ}"
    # Highpass BEFORE the modulation as well as after: modulating the lows and
    # then removing them still leaves their sidebands folded into the range
    # that survives.
# afreqshift, not vibrato. vibrato is TRANSPARENT in this ffmpeg build --
# depths of 0.1, 0.5 and 0.9 all produce output identical to the input, and
# identical to each other. The earlier claim here that audio-rate vibrato
# produced real FM sidebands was wrong: the sweep that appeared to confirm
# it varied depth and mix together, so what it measured was the highpassed
# dry copy being blended in, not sidebands at all.
#
# Frequency shifting is not the same operation as FM, and saying so matters:
# FM generates sidebands at multiples of the modulator, while a shift moves
# every partial by a fixed number of Hz. But it produces genuine inharmonic
# content -- measured +4.3 dB above 500 Hz on a 200 Hz sine, where vibrato
# gave 0.0 -- and inharmonic partials are the bell-like quality this was
# reaching for. The floor still protects the chord tones.
shift_hz = SAMPLE_FM_SHIFT_HZ.zero? ? (root * (SAMPLE_FM_RATIO - 1.0)).round(2) : SAMPLE_FM_SHIFT_HZ
branches << "[0:a]highpass=f=#{SAMPLE_FM_FLOOR_HZ}," \
            "afreqshift=shift=#{shift_hz}:level=1," \
            "highpass=f=#{SAMPLE_FM_FLOOR_HZ}[fm#{idx}]"
    labels << "[fm#{idx}]"
    weights << SAMPLE_FM_MIX.to_s
    idx += 1
  end

  if SAMPLE_SCALE
    SAMPLE_SCALE_DEGREES.each_with_index do |semi, i|
      branches << "[0:a]#{pitch_shift_filter(semi)},lowpass=f=6000[sc#{i}]"
      labels << "[sc#{i}]"
      # Upper degrees quieter, or the chord overwhelms the note it came from.
      weights << (SAMPLE_SCALE_MIX * (1.0 - (i * 0.18))).round(3).to_s
    end
  end

  chain = branches.dup
  chain << "#{labels.join}amix=inputs=#{labels.size}:weights=#{weights.join(' ')}:" \
           "duration=first:normalize=0,alimiter=limit=0.95:level_out=0.96[mout]"
  begin
    sh! "ffmpeg", "-y", "-i", src, "-filter_complex", chain.join(";"),
        "-map", "[mout]", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
        "-c:a", "pcm_s16le", dest
    note = []
    note << "FM #{(root * SAMPLE_FM_RATIO).round}Hz (root #{root.round}, ratio #{SAMPLE_FM_RATIO})" if SAMPLE_FM
    note << "scale +#{SAMPLE_SCALE_DEGREES.map(&:to_i).join('/+')}" if SAMPLE_SCALE
    puts "sample morph: #{note.join(', ')}"
    dest
  rescue StandardError => e
    warn "sample morph: #{e.message}"
    src
  end
end

# --------------------------------------------------------------------------
# engine part: organic_vary
# --------------------------------------------------------------------------
#
# Varying the loop each pass: pitch, time and tone walks, dropouts.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# A sampled loop played with -stream_loop is bit-identical every repetition, and
# nothing acoustic repeats exactly. ORGANIC_VARY=1 pre-builds the bed as N
# separately-processed copies so each pass differs slightly in pitch, tone and
# start offset -- the thing that stops a loop sounding stapled to the grid.
#
# Deliberately small numbers: past a few cents the loop stops agreeing with the
# generated harmony, and past ~15ms the drums stop agreeing with themselves.
ORGANIC_VARY = ENV["ORGANIC_VARY"] == "1"
ORGANIC_VARY_CENTS = (ENV["ORGANIC_VARY_CENTS"] || 4.0).to_f.clamp(0.0, 30.0)
ORGANIC_VARY_MS = (ENV["ORGANIC_VARY_MS"] || 8.0).to_f.clamp(0.0, 60.0)
ORGANIC_VARY_TONE_HZ = (ENV["ORGANIC_VARY_TONE_HZ"] || 1800).to_i

# Fixed walks, one value per repetition, cycling. Reproducibility again: a loop
# that varies differently on every render cannot be mixed against.
ORGANIC_VARY_PITCH_WALK = [0.0, 0.6, -0.4, 1.0, -0.8, 0.3, -1.0, 0.7].freeze
ORGANIC_VARY_TIME_WALK = [0.0, -0.5, 0.8, -0.2, 0.6, -0.9, 0.3, -0.6].freeze
ORGANIC_VARY_TONE_WALK = [0.0, -1.2, 0.8, -0.6, 1.4, -0.3, 0.5, -1.0].freeze

# Chopping, as opposed to repeating.
#
# ORGANIC_VARY already stops each pass being bit-identical, but it still plays
# the loop front to back every time. Chopping cuts it into slices and plays them
# in a different order per pass, which is what the sampler workflow actually
# did: the loop is raw material, not a part.
#
# The order is a fixed rotation rather than random. A shuffle that differs every
# render cannot be mixed against, and more importantly a rotation preserves
# which slice lands on the downbeat -- slice 0 stays first in most passes, so
# the bar still starts where the ear expects while its interior rearranges.
LOOP_CHOP_SLICES = (ENV["LOOP_CHOP_SLICES"] || 0).to_i.clamp(0, 16)

# Rotations applied per pass. The first is identity so pass 1 states the loop
# plainly before anything is done to it -- rearranging from the very first bar
# leaves the listener nothing to hear the rearrangement against.
LOOP_CHOP_ORDERS = [
  [0, 1, 2, 3, 4, 5, 6, 7],
  [0, 1, 2, 3, 4, 6, 5, 7],
  [0, 2, 1, 3, 4, 5, 7, 6],
  [0, 1, 3, 2, 4, 5, 6, 7],
  [0, 1, 2, 3, 6, 5, 4, 7],
].freeze

def loop_chop_order(pass, slices)
  base = LOOP_CHOP_ORDERS[pass % LOOP_CHOP_ORDERS.size]
  base.select { |i| i < slices } + (base.size...slices).to_a
end

def organic_vary_loop!(src, dest, duration:)
  return nil unless File.file?(src)

  one = audio_duration_sec(src).to_f
  return nil unless one.positive?

  reps = ((duration / one).ceil + 1).clamp(1, 64)
  parts = []
  chain = []
  reps.times do |i|
    cents = ORGANIC_VARY_CENTS * ORGANIC_VARY_PITCH_WALK[i % ORGANIC_VARY_PITCH_WALK.size]
    shift = ORGANIC_VARY_MS * ORGANIC_VARY_TIME_WALK[i % ORGANIC_VARY_TIME_WALK.size]
    tone = ORGANIC_VARY_TONE_HZ * (1.0 + (0.18 * ORGANIC_VARY_TONE_WALK[i % ORGANIC_VARY_TONE_WALK.size]))
    rate = (SAMPLE_RATE * (2.0**(cents / 1200.0))).round
    delay = [shift.round, 0].max
    parts.concat(["-i", src])
    # asetrate then aresample is a varispeed: pitch and length move together, as
    # a tape machine does, rather than a formant-preserving shift that would
    # sound processed.
    voice = "[#{i}:a]asetrate=#{rate},aresample=#{SAMPLE_RATE}," \
            "lowpass=f=#{tone.round},adelay=#{delay}|#{delay}"

    if LOOP_CHOP_SLICES > 1
      # Cut this pass into slices and play them in a rotation. The loop stops
      # being a part and becomes material, which is what a sampler workflow
      # does with it. 4ms edges on every slice: a hard cut mid-waveform clicks,
      # and a click on every slice boundary is the fastest way to make chopping
      # sound like a fault rather than a choice.
      order = loop_chop_order(i, LOOP_CHOP_SLICES)
      slice = one / LOOP_CHOP_SLICES
      chain << "#{voice}[p#{i}]"
      chain << "[p#{i}]asplit=#{LOOP_CHOP_SLICES}#{(0...LOOP_CHOP_SLICES).map { |n| "[p#{i}s#{n}]" }.join}"
      order.each_with_index do |src_slice, pos|
        chain << "[p#{i}s#{pos}]atrim=#{(src_slice * slice).round(4)}:" \
                 "#{((src_slice + 1) * slice).round(4)},asetpts=PTS-STARTPTS," \
                 "afade=t=in:st=0:d=0.004," \
                 "afade=t=out:st=#{[(slice - 0.004), 0].max.round(4)}:d=0.004[c#{i}_#{pos}]"
      end
      cats = (0...LOOP_CHOP_SLICES).map { |n| "[c#{i}_#{n}]" }.join
      chain << "#{cats}concat=n=#{LOOP_CHOP_SLICES}:v=0:a=1[v#{i}]"
    else
      chain << "#{voice}[v#{i}]"
    end
  end
  labels = (0...reps).map { |i| "[v#{i}]" }.join
  chain << "#{labels}concat=n=#{reps}:v=0:a=1[vcat]"
  chain << "[vcat]atrim=0:#{duration.round(3)},asetpts=PTS-STARTPTS[vout]"
  begin
    sh! "ffmpeg", "-y", *parts, "-filter_complex", chain.join(";"),
        "-map", "[vout]", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
        "-c:a", "pcm_s16le", dest
    dmesg("organic vary: #{reps} passes, +-#{ORGANIC_VARY_CENTS}c / #{ORGANIC_VARY_MS}ms",
          unit: "harm0", parent: "dilla0")
    dest
  rescue StandardError => e
    warn "organic vary: #{e.message}"
    nil
  end
end

# Applies a modulation to a rendered file in place. `codec` lets the same code
# serve the intermediate WAV buses and the final mp3/wav master.
def organic_modulate!(path, bar_sec:, mode:, label:)
  return path unless File.file?(path)

  ext = File.extname(path)
  out = "#{path}.#{mode}#{ext.empty? ? '.wav' : ext}"
  chain = organic_breath_filters("0:a", "bout", bar_sec:, mode:)
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  begin
    sh! "ffmpeg", "-y", "-i", path, "-filter_complex", chain.join(";"),
        "-map", "[bout]", "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    path
  rescue StandardError => e
    warn "organic #{label}: #{e.message}"
    FileUtils.rm_f(out)
    path
  end
end

def organic_breathe!(path, bar_sec:)
  return path unless ORGANIC_BREATH

  organic_modulate!(path, bar_sec:, mode: :breath, label: "breath")
end

# The swell goes on the FINISHED master, not the pad bus.
#
# On the pad bus it was inaudible in the mix and the measurements said so: at
# the 3 dB default the full-mix LRA did not move at all, 3.4 with and without.
# Two reasons, both structural. Drums and bass hold a constant level, so a pad
# swelling 3 dB moves the total by a fraction of that. And the master chain --
# AKMD's acompressor at 3:1, then loudnorm -- exists precisely to remove a few
# dB of slow level movement; asking it politely not to is not an option.
#
# Applied here the movement is common-mode across the whole track and nothing
# downstream gets to average it away or compress it out. The cost is honest and
# worth stating: the drums breathe too, because everything does.
def organic_swell_master!(path, bar_sec:)
  return path unless ORGANIC_SWELL

  organic_modulate!(path, bar_sec:, mode: :swell, label: "swell")
end

# Total silence for a fraction of a beat immediately before a downbeat.
#
# Not a fade and not a filter -- everything stops, then everything returns. The
# gap has to land just before the bar line rather than on it: silence AT the
# downbeat sounds like a dropout, silence leading INTO one sounds like the
# track was cut, and the ear fills in the missing beat. Applied post-master for
# the same reason the swell is -- a compressor would pump around the hole and
# turn a clean cut into a swell of its own.
DILLA_DROPOUT_EVERY = (ENV["DILLA_DROPOUT_EVERY"] || 0).to_i   # every Nth bar
DILLA_DROPOUT_BEATS = (ENV["DILLA_DROPOUT_BEATS"] || 0.25).to_f.clamp(0.05, 2.0)

def dilla_dropout!(path, bar_sec:)
  return path unless DILLA_DROPOUT_EVERY.positive? && File.file?(path)

  gap = (bar_sec / 4.0) * DILLA_DROPOUT_BEATS
  bar = bar_sec.round(5)
  # Mute while inside the last `gap` of a bar, on every Nth bar.
  cond = "gte(mod(t\\,#{bar})\\,#{(bar_sec - gap).round(5)})" \
         "*eq(mod(floor(t/#{bar})\\,#{DILLA_DROPOUT_EVERY})\\,#{DILLA_DROPOUT_EVERY - 1})"
  ext = File.extname(path)
  out = "#{path}.drop#{ext.empty? ? '.wav' : ext}"
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  begin
    sh! "ffmpeg", "-y", "-i", path,
        "-af", "volume='if(#{cond}\\,0\\,1)':eval=frame",
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    dmesg("dropout: #{(gap * 1000).round}ms before every #{DILLA_DROPOUT_EVERY} bars",
          unit: "mix0", parent: "dilla0")
    path
  rescue StandardError => e
    warn "dropout: #{e.message}"
    FileUtils.rm_f(out)
    path
  end
end

# --------------------------------------------------------------------------
# engine part: tape_master
# --------------------------------------------------------------------------
#
# Tape and console on the master: hysteresis, tilt, mono bass, drone, tape stop.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# Real tape hysteresis, applied to the finished master.
#
# Everything else in this engine that saturates is memoryless -- output is a
# function of the current sample alone, so the transfer curve is a single line
# and the same input always gives the same output. Tape is path-dependent: the
# curve is a loop, and the output at a given level differs depending on whether
# the signal arrived there rising or falling. Verified on a sine through this
# model: at input 0.0 the output is 0.0 on the way up and +0.46 on the way down.
# No waveshaper produces that at any setting, which is the difference between
# adding harmonics and sounding like a machine.
#
# Ruby per-sample DSP is slow, so this is opt-in and reports its cost.
# Default 0.16 (drive 1.48), not 0. A Jiles-Atherton magnetisation model sat
# in lib/ fully built and switched off, so nothing rendered by this engine
# had ever been through it. Tape character was being asked of an EQ curve.
TAPE_HYSTERESIS = (ENV["TAPE_HYSTERESIS"] || 0.16).to_f.clamp(0.0, 1.0)
# 0.6 ms of Ornstein-Uhlenbeck wow. Real wow is subtle — enough that held
# notes are never quite steady, not enough to read as an effect.
TAPE_WOW_MS = (ENV["TAPE_WOW_MS"] || 0.6).to_f.clamp(0.0, 8.0)
# 1.0 = original JA loop. Lower = less bias current, wider hysteresis.
TAPE_BIAS = (ENV["TAPE_BIAS"] || 1.0).to_f.clamp(0.0, 1.0)
# Spacing/loss filter in front of the magnetisation, Hz. 0 is off — tape is
# not full-bandwidth into oxide, but turning this on by default would retone
# every existing render. 14000 is the analog starting point.
TAPE_LOSS_HZ = (ENV["TAPE_LOSS_HZ"] || 0).to_f.clamp(0.0, 20_000.0)

# Per-channel console strip. See lib/console_strip.rb for why this is per
# channel and not on the master, and for the harmonic measurements.
#
# CONSOLE_STRIP is the wet amount, 0 disables. Each bus passes its own
# instance with its own seed, so the drums and the pads are coloured by
# different "hardware" rather than by one shared curve -- which is the whole
# point, and is not reproducible by running the same stage on the mix.
# 0.22. Left and right run as separate instances one seed apart, which is the
# whole reason this exists — see the note below on why it is not mono.
CONSOLE_STRIP = (ENV["CONSOLE_STRIP"] || 0.06).to_f.clamp(0.0, 1.0)

# Left and right run as separate instances, offset by one seed. On a desk a
# stereo pair IS two channels, built to the same design and measuring
# differently, and the small mismatch between them is a large part of why a
# console sounds wide. Processing mono and re-widening -- the approach
# tape_hysteresis! takes, correctly, because magnetisation is not a stereo
# phenomenon -- would throw that away here, where it is the effect.
def console_strip!(path, seed: 1, amount: CONSOLE_STRIP)
  return path unless amount.positive? && File.file?(path)

  # ../console_strip, not lib/console_strip: require_relative resolves against
  # the file it is written in, and this one moved a directory down in the split.
  require_relative "lib/console_strip"
  started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
  raw = "#{path}.cs_in.raw"
  cooked = "#{path}.cs_out.raw"
  ext = File.extname(path)
  out = "#{path}.console#{ext.empty? ? '.wav' : ext}"
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  begin
    sh! "ffmpeg", "-y", "-i", path, "-f", "s16le", "-acodec", "pcm_s16le",
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", raw
    inter = File.binread(raw).unpack("s<*")
    left = []
    right = []
    inter.each_slice(2) do |l, r|
      left << (l || 0) / PCM16_FULL_SCALE
      right << (r || l || 0) / PCM16_FULL_SCALE
    end
    left = ConsoleStrip.process(left, rate: SAMPLE_RATE, seed:, amount:)
    right = ConsoleStrip.process(right, rate: SAMPLE_RATE, seed: seed + 1, amount:)
    # Match the input peak rather than normalising to full scale. This stage
    # runs on a bus that is about to be mixed at a measured weight, and a
    # stage that silently changes its own level makes every downstream mix
    # number wrong -- which is how the low end got away from this engine
    # before.
    in_peak = inter.map(&:abs).max.to_f / PCM16_FULL_SCALE
    out_peak = [left.map(&:abs).max || 0.0, right.map(&:abs).max || 0.0].max
    scale = out_peak.positive? && in_peak.positive? ? in_peak / out_peak : 1.0
    merged = Array.new(left.length * 2)
    left.each_index do |i|
      merged[i * 2] = ((left[i] * scale) * 32_767).round.clamp(-32_768, 32_767)
      merged[(i * 2) + 1] = ((right[i] * scale) * 32_767).round.clamp(-32_768, 32_767)
    end
    File.binwrite(cooked, merged.pack("s<*"))
    # Same DC problem as the tape stage, an order of magnitude smaller but real:
    # ConsoleStrip.process turns a DC-free input into one offset by 1.31% of
    # peak at 0.35, 3.84% at 1.0. Any asymmetric
    # saturation does this, and both models run after the master chain's
    # highpasses, so nothing downstream was removing it.
    sh! "ffmpeg", "-y", "-f", "s16le", "-ar", SAMPLE_RATE.to_s, "-ac", "2",
        "-i", cooked, "-af", "highpass=f=24", "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    took = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - started).round(1)
    dmesg("console strip: seed #{seed}/#{seed + 1} amount #{amount} (#{took}s)",
          unit: "cons0", parent: "dilla0")
    path
  rescue StandardError => e
    warn "console strip: #{e.message}"
    FileUtils.rm_f(out)
    path
  ensure
    FileUtils.rm_f([raw, cooked])
  end
end

def tape_hysteresis!(path)
  return path unless (TAPE_HYSTERESIS.positive? || TAPE_WOW_MS.positive?) && File.file?(path)

  require_relative "lib/tape_hysteresis"
  started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
  raw = "#{path}.pre.raw"
  cooked = "#{path}.post.raw"
  ext = File.extname(path)
  out = "#{path}.tape#{ext.empty? ? '.wav' : ext}"
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  begin
    decode = ["ffmpeg", "-y", "-i", path]
    decode += ["-af", "lowpass=f=#{TAPE_LOSS_HZ.round}"] if TAPE_LOSS_HZ.positive?
    decode += ["-f", "s16le", "-acodec", "pcm_s16le", "-ar", SAMPLE_RATE.to_s, "-ac", "1", raw]
    sh!(*decode)
    pcm = File.binread(raw).unpack("s<*").map { |s| s / PCM16_FULL_SCALE }
    if TAPE_HYSTERESIS.positive?
      pcm = TapeHysteresis.process(pcm, drive: 1.0 + (3.0 * TAPE_HYSTERESIS),
                                   params: TapeHysteresis.params_for_bias(TAPE_BIAS))
    end
    pcm = TapeHysteresis.apply_wow(pcm, rate: SAMPLE_RATE, depth_ms: TAPE_WOW_MS) if TAPE_WOW_MS.positive?
    peak = pcm.map(&:abs).max
    pcm = pcm.map { |v| v / peak * 0.94 } if peak&.positive?
    File.binwrite(cooked, pcm.map { |v| (v * 32_767).round.clamp(-32_768, 32_767) }.pack("s<*"))
    # Mono through the model, then re-widened against the original: running two
    # channels doubles a cost that is already the slowest thing here, and tape
    # magnetisation is not a stereo phenomenon anyway.
    sh! "ffmpeg", "-y", "-f", "s16le", "-ar", SAMPLE_RATE.to_s, "-ac", "1", "-i", cooked,
        "-i", path, "-filter_complex",
        # highpass=24 is load-bearing, not tidying. Jiles-Atherton models
        # remanent magnetisation, and remanence is a DC phenomenon: a DC-free
        # input comes out of TapeHysteresis.process with DC at 10.3% of peak at
        # drive 1.75, rising to 15.7% at 4.0. This stage runs
        # after every highpass in the master chain and then peak-normalises,
        # which preserves the offset instead of removing it.
        #
        # Unfixed, that offset dominated: 22 of 84 demo tracks measured DC up to
        # -0.62, and the worst was 99.7% subsonic — full-band RMS -4.10 dB
        # against -4.09 dB below 25 Hz, with the actual music 37 dB underneath
        # it and the headroom entirely consumed.
        "[0:a]aformat=channel_layouts=stereo,highpass=f=24[t];" \
        "[1:a]highpass=f=8000[air];" \
        "[t][air]amix=inputs=2:weights=1 0.35:duration=first:normalize=0[out]",
        "-map", "[out]", "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    took = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - started).round(1)
    extras = []
    extras << "bias #{TAPE_BIAS}" if TAPE_BIAS < 1.0
    extras << "loss #{TAPE_LOSS_HZ.round}Hz" if TAPE_LOSS_HZ.positive?
    extras << "O-U wow #{TAPE_WOW_MS}ms" if TAPE_WOW_MS.positive?
    puts "tape: Jiles-Atherton hysteresis#{extras.empty? ? '' : " (#{extras.join(', ')})"} (#{took}s)"
    path
  rescue StandardError => e
    warn "tape hysteresis: #{e.message}"
    FileUtils.rm_f(out)
    path
  ensure
    FileUtils.rm_f([raw, cooked])
  end
end

# Tilt: lows up as highs come down, pivoting around a midpoint.
#
# The reason to tilt rather than shelve the top off. A plain high-shelf cut
# makes a mix darker AND smaller, because nothing replaces the energy removed --
# the perceived weight goes with the brightness. A tilt pivots: the bottom rises
# by the same amount the top falls, so the mix reads as relaxed rather than
# merely dull, and the loudness barely moves.
#
# Two shelves around a pivot rather than one filter, because that is what a tilt
# is. Pivot at 700 Hz: low enough that it does not thin the body, high enough
# that the lift lands on weight rather than on mud.
MASTER_TILT_DB = (ENV["MASTER_TILT_DB"] || 0).to_f.clamp(-6.0, 6.0)
MASTER_TILT_PIVOT = (ENV["MASTER_TILT_PIVOT"] || 700).to_i

# Top-end smoothing -- the thing that makes a mix read as calm rather than
# distorted, and the most consistent single trait across the 29 reference
# tracks in MASTER/reports/radio_bergen_track_dossiers.yml.
#
# Nine of those dossiers describe the same move in different words: "master
# lowpass ~3.6 kHz" (Camel, Massage Situation), "high shelf rolled ~9 kHz"
# (In Space), "limited highs" (Eye), "never harsh top" (Timeless), "Donuts
# lowpass warmth", and bergen_local's "master LP 2.7-3.1 kHz". Nothing in this
# engine implemented it; the only top-end control was VINYL.
#
# Those numbers are NOT taken literally. A brickwall lowpass at 3.2 kHz makes
# a record sound like a telephone -- real Donuts and Camel masters have
# cymbals well above 10 kHz -- so the figure is describing the treatment of
# the sampled bed, or the perceived centre of the rolloff, not a filter on the
# whole master. Implemented literally it would destroy the track, which is why
# this is a pair of gentle shelves instead.
#
# Two bands, because "harsh" and "bright" are different problems:
#
#   PRESENCE (~3.2 kHz) is where distortion and harshness actually live. This
#   is the band that makes saturation read as fizz rather than warmth, and it
#   is what the ear calls "distorted" even when nothing is clipping.
#
#   AIR (~9 kHz and up) is brightness. Rolling this alone makes a mix duller
#   without making it calmer, which is why cutting only here never fixes the
#   complaint.
# 2 dB out of the presence band by default. This is the stage that answers
# "harsh" directly, and it was doing nothing.
MASTER_SMOOTH_DB = (ENV["MASTER_SMOOTH_DB"] || 2.0).to_f.clamp(0.0, 12.0)
MASTER_SMOOTH_HZ = (ENV["MASTER_SMOOTH_HZ"] || 3200).to_i
MASTER_AIR_DB = (ENV["MASTER_AIR_DB"] || 0).to_f.clamp(0.0, 12.0)
MASTER_AIR_HZ = (ENV["MASTER_AIR_HZ"] || 9000).to_i

def master_smooth!(path)
  return path unless (MASTER_SMOOTH_DB.positive? || MASTER_AIR_DB.positive?) && File.file?(path)

  ext = File.extname(path)
  out = "#{path}.smooth#{ext.empty? ? '.wav' : ext}"
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  chain = []
  # A wide bell on the presence band rather than a shelf: a shelf pulls
  # everything above the corner down together, taking the cymbals and the
  # sample's air with it. The harshness is a band, so it gets a band. Width in
  # octaves, wide enough not to sound like a notch.
  if MASTER_SMOOTH_DB.positive?
    chain << "equalizer=f=#{MASTER_SMOOTH_HZ}:t=o:w=1.6:g=#{-MASTER_SMOOTH_DB.round(2)}"
  end
  # Air gets a real shelf, because above 9 kHz there is nothing to preserve
  # the far side of. `treble` and not `equalizer` -- equalizer is a peaking
  # filter in every configuration, a mistake already made once in this file.
  chain << "treble=f=#{MASTER_AIR_HZ}:g=#{-MASTER_AIR_DB.round(2)}:width_type=q:w=0.7" if MASTER_AIR_DB.positive?
  return path if chain.empty?

  begin
    sh! "ffmpeg", "-y", "-i", path, "-af", chain.join(","),
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    dmesg("smooth: presence -#{MASTER_SMOOTH_DB} dB @ #{MASTER_SMOOTH_HZ}, " \
          "air -#{MASTER_AIR_DB} dB @ #{MASTER_AIR_HZ}",
          unit: "smth0", parent: "dilla0")
    path
  rescue StandardError => e
    warn "master smooth: #{e.message}"
    FileUtils.rm_f(out)
    path
  end
end

def master_tilt!(path)
  return path unless MASTER_TILT_DB.abs > 0.01 && File.file?(path)

  ext = File.extname(path)
  out = "#{path}.tilt#{ext.empty? ? '.wav' : ext}"
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  # Negated so the sign reads the way a tilt control does: a NEGATIVE value
  # tilts down, meaning darker -- lows up, highs down. Unnegated, -3 brightened
  # (low -0.8 dB, high +0.9 dB), which is the opposite of what asking for -3
  # implies and the opposite of the chill it exists to produce.
  half = (-MASTER_TILT_DB / 2.0).round(3)
  begin
    sh! "ffmpeg", "-y", "-i", path,
        # `bass` and `treble`, not `equalizer`. equalizer is a PEAKING filter in
        # every case -- its `t` parameter selects the unit of the width (h=Hz,
        # q=Q, o=octaves), not the filter shape. Writing t=h intending "high
        # shelf" builds a bell 0.7 Hz wide instead, which measured as doing
        # nothing at all: low and high bands both moved 0.1 dB. Same class of
        # mistake as reaching for asoftclip to saturate.
        "-af", "bass=f=#{MASTER_TILT_PIVOT / 4}:g=#{half}:width_type=q:w=0.7," \
               "treble=f=#{MASTER_TILT_PIVOT * 6}:g=#{-half}:width_type=q:w=0.7",
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    dmesg("master tilt: #{half > 0 ? '+' : ''}#{half} low / #{-half} high around #{MASTER_TILT_PIVOT}Hz",
          unit: "mix0", parent: "dilla0")
    path
  rescue StandardError => e
    warn "master tilt: #{e.message}"
    FileUtils.rm_f(out)
    path
  end
end

# Collapse everything below MONO_BASS_HZ to mono, leave the rest alone.
#
# Two sources here put uncorrelated energy in the sub: the sampled record has
# whatever stereo width the original mastering gave it, and the pad stack is
# deliberately spread. Uncorrelated lows do not add up -- they smear, they
# partially cancel on any mono playback, and they eat headroom the kick needs.
# Summing only the bottom keeps the width where width is audible (a listener
# cannot localise 60 Hz anyway) and gives the low end back its definition.
MONO_BASS_HZ = (ENV["MONO_BASS_HZ"] || 0).to_i

def mono_bass!(path)
  return path unless MONO_BASS_HZ.positive? && File.file?(path)

  ext = File.extname(path)
  out = "#{path}.monobass#{ext.empty? ? '.wav' : ext}"
  args = ext.downcase == ".wav" || ext.empty? ? ["-c:a", "pcm_s16le"] : codec_for(out)
  chain = [
    "[0:a]asplit=2[mb_lo][mb_hi]",
    "[mb_lo]lowpass=f=#{MONO_BASS_HZ}," \
      "pan=stereo|c0=0.5*c0+0.5*c1|c1=0.5*c0+0.5*c1[mb_m]",
    "[mb_hi]highpass=f=#{MONO_BASS_HZ}[mb_s]",
    "[mb_m][mb_s]amix=inputs=2:normalize=0[mbout]",
  ]
  begin
    sh! "ffmpeg", "-y", "-i", path, "-filter_complex", chain.join(";"),
        "-map", "[mbout]", "-ar", SAMPLE_RATE.to_s, "-ac", "2", *args, out
    FileUtils.mv(out, path)
    path
  rescue StandardError => e
    warn "mono bass: #{e.message}"
    FileUtils.rm_f(out)
    path
  end
end

# --- drone bed and tape stop --------------------------------------------------
#
# The two effects the engine had no form of. It already owns bitcrush
# (acrusher), wow/flutter (vibrato), pitch tricks (asetrate), granular pads,
# detune, reverse grains and drum dropouts -- so those are switches, not work.
# A stretched drone and a speed brake were genuinely absent.

# Stretches a short slice of the loop into a static harmonic bed. Not real
# paulstretch (no phase randomisation -- ffmpeg has no such filter), but the
# audible part of it: overlapping windows so far apart that pitch survives and
# rhythm does not. Layering three ratios stops the result sounding like one
# obviously slowed sample.
DILLA_DRONE = ENV["DILLA_DRONE"] == "1"
DILLA_DRONE_VOL = (ENV["DILLA_DRONE_VOL"] || 0.16).to_f.clamp(0.0, 1.0)
DILLA_DRONE_SRC_SEC = (ENV["DILLA_DRONE_SRC_SEC"] || 0.6).to_f.clamp(0.1, 4.0)

# atempo floors at 0.5 per stage, so a deep stretch is a chain of them. Six
# stages of 0.5 is 64x. The last stage differs per layer so the three do not sit
# exactly on top of each other: identical copies sum to one louder copy, while
# slightly different ones beat, and the beating is what stops a drone sounding
# frozen.
DRONE_LAYER_TEMPOS = [
  [0.5, 0.5, 0.5, 0.5, 0.5, 0.5],
  [0.5, 0.5, 0.5, 0.5, 0.5, 0.55],
  [0.5, 0.5, 0.5, 0.5, 0.5, 0.62],
].freeze
DRONE_LOWPASS_HZ = 1800
DRONE_HIGHPASS_HZ = 70
DRONE_FADE_FRACTION = 0.25
DRONE_FADE_MAX_SEC = 6.0

def dilla_render_drone!(src, dest, duration:)
  return nil unless src && File.file?(src)

  chain = DRONE_LAYER_TEMPOS.each_with_index.map do |stages, i|
    tempo = stages.map { |s| "atempo=#{s}" }.join(",")
    "[0:a]#{tempo},lowpass=f=#{DRONE_LOWPASS_HZ},highpass=f=#{DRONE_HIGHPASS_HZ}," \
      "volume=#{(1.0 / DRONE_LAYER_TEMPOS.size).round(3)}[d#{i}]"
  end
  mix = DRONE_LAYER_TEMPOS.each_index.map { |i| "[d#{i}]" }.join
  chain << "#{mix}amix=inputs=#{DRONE_LAYER_TEMPOS.size}:normalize=0[dm]"
  # A drone that arrives and leaves is a bed; one that starts is a mistake.
  fade = [duration * DRONE_FADE_FRACTION, DRONE_FADE_MAX_SEC].min.round(2)
  chain << "[dm]afade=t=in:st=0:d=#{fade}," \
           "afade=t=out:st=#{(duration - fade).round(2)}:d=#{fade}[dout]"
  begin
    sh! "ffmpeg", "-y", "-t", DILLA_DRONE_SRC_SEC.to_s, "-i", src,
        "-filter_complex", chain.join(";"), "-map", "[dout]",
        "-t", duration.round(3).to_s, "-ar", SAMPLE_RATE.to_s, "-ac", "2",
        "-c:a", "pcm_s16le", dest
    dest
  rescue StandardError => e
    warn "drone: #{e.message}"
    nil
  end
end

# Turntable brake over the final bars. asetrate resamples, so pitch and speed
# fall together the way a real platter does -- which is the point, and why this
# is not just a fade.
DILLA_TAPE_STOP = ENV["DILLA_TAPE_STOP"] == "1"
DILLA_TAPE_STOP_BEATS = (ENV["DILLA_TAPE_STOP_BEATS"] || 4).to_f.clamp(0.5, 32.0)

# ffmpeg cannot sweep asetrate continuously, so the brake is short slices at
# falling rates. 14 is enough that the steps read as a slide, not a staircase.
TAPE_STOP_STEPS = 14
# Where the platter ends up, as a fraction of speed. Not 0: the last slice would
# be stretched to nothing audible and pad the file with rumble.
TAPE_STOP_FINAL_RATE = 0.08
# >1 makes the fall accelerate, which is how a platter with real inertia stops.
TAPE_STOP_CURVE = 1.6
TAPE_STOP_MIN_RATE_HZ = 3000

def dilla_tape_stop_rates
  (0...TAPE_STOP_STEPS).map do |i|
    frac = 1.0 - ((i + 1).to_f / TAPE_STOP_STEPS)
    rest = 1.0 - TAPE_STOP_FINAL_RATE
    [TAPE_STOP_FINAL_RATE + (rest * (frac**TAPE_STOP_CURVE)),
     TAPE_STOP_MIN_RATE_HZ.to_f / SAMPLE_RATE].max
  end
end

def dilla_tape_stop!(path, beat_bpm:)
  total = audio_duration_sec(path).to_f
  want = (60.0 / beat_bpm) * DILLA_TAPE_STOP_BEATS
  steps = TAPE_STOP_STEPS
  # Slowed audio lasts longer, so the source window has to be SHORTER than the
  # brake we want to hear. Taking the requested length as the source instead
  # made "4 beats" produce 8.9 seconds -- a fifth of a 16-bar track. Solve for
  # the source window whose stretched total lands on the request.
  rates = dilla_tape_stop_rates
  stretch = rates.sum { |r| 1.0 / r } / steps
  brake = want / stretch
  return path unless total > brake + 1.0

  head = "#{path}.head.wav"
  tailp = "#{path}.tail.wav"
  out = "#{path}.stopped.wav"
  begin
    sh! "ffmpeg", "-y", "-i", path, "-t", (total - brake).round(3).to_s,
        "-c:a", "pcm_s16le", head
    # Ramped resample in steps: ffmpeg cannot sweep asetrate continuously, so
    # the brake is built from short slices at falling rates. 14 is enough that
    # the steps read as a slide rather than a staircase.
    slice = brake / steps
    parts = (0...steps).map do |i|
      rate = (SAMPLE_RATE * rates[i]).round
      seg = "#{path}.b#{i}.wav"
      sh! "ffmpeg", "-y", "-ss", (total - brake + (i * slice)).round(3).to_s,
          "-t", slice.round(3).to_s, "-i", path,
          "-af", "asetrate=#{rate},aresample=#{SAMPLE_RATE}",
          "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", seg
      seg
    end
    # Absolute paths: the concat demuxer resolves relative entries against the
    # LIST FILE's directory, not the process working directory. With a relative
    # destination like renders/demos/x.wav the list sat in renders/demos/ and
    # its entries resolved to renders/demos/renders/demos/... -- so the brake
    # failed on every relative path and silently returned the unbraked file.
    # It only ever worked because the first renders wrote to absolute paths.
    list = "#{path}.list.txt"
    File.write(list, ([head] + parts).map { |f| "file '#{File.expand_path(f)}'\n" }.join)
    sh! "ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list,
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", out
    FileUtils.mv(out, path)
    # Recorded before the slices are deleted on the next line: the parts of a
    # tape brake exist only inside this method, so this is the only moment their
    # durations and hashes can be read at all.
    DillaProvenance.record_assembly!(path, parts: [head] + parts,
                                           how: "tape stop: head plus #{parts.length} decelerating slice(s)")
    FileUtils.rm_f([head, tailp, list] + parts)
    path
  rescue StandardError => e
    warn "tape stop: #{e.message}"
    # `parts` too. Omitting them left 14 slices beside every failed brake, and
    # since the failure was silent the leftovers were the only visible sign
    # anything had gone wrong at all.
    FileUtils.rm_f([head, tailp, out, "#{path}.list.txt"] + Array(parts))
    path
  end
end

# --------------------------------------------------------------------------
# engine part: rap_vocal_fit
# --------------------------------------------------------------------------
#
# Fitting a rap vocal to the beat: snapping, warping, key shifting.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# --- phrase snapping ---------------------------------------------------------
#
# atempo can only fix a take that HAS a tempo. A freely-sung take has no
# periodic spacing to stretch onto a grid, and measuring this proved it: across
# source BPMs from 96 to 128 against a 92 BPM beat, gunnhild landed 31%, 20%,
# 19%, 18%, 25% and 14% of her onsets on the grid, against a ~20% random-phase
# baseline. Slowing her down made the alignment WORSE. There is no ratio that
# works because the thing a ratio scales -- the spacing between her syllables --
# is not constant in the first place.
#
# So place instead of stretch: cut the take at its sung lines and start each
# line on a grid line, letting the silence between lines absorb the drift. The
# alignment then comes from where each line BEGINS, which is what a listener
# hears as being on the beat, and no line is time-warped internally so the
# delivery inside it stays hers.
RAP_VOCAL_SNAP_BEATS = (ENV["RAP_VOCAL_SNAP_BEATS"] || 2).to_f

# Dead-on the grid is not the goal -- it is only the reference the lean is
# measured from. rap_vocal_pocket_nudge_sec already drags the whole vocal 3-4
# ticks of 96 PPQ behind the beat (20-27ms at 92), but that is one constant for
# the entire take. Dilla's feel is not constant; it wanders line to line, and
# the wander is the point. RAP_VOCAL_LEAN_MS sets the base drag, and each line
# is offset from it by a fixed walk.
#
# The walk is a literal table rather than rng: a render has to reproduce, and a
# "feel" you cannot get back is not a feel, it is an accident.
RAP_VOCAL_LEAN_MS = (ENV["RAP_VOCAL_LEAN_MS"] || 0).to_f
RAP_VOCAL_LEAN_WALK = [0, 7, -5, 12, -3, 9, -8, 4, 2, -6, 11, -2].freeze

# How far the beat steps back while the rap is going. Set the ratio to 1 to
# disable the duck entirely and get the old fixed-weight mix back.
RAP_VOCAL_DUCK_THRESHOLD_DB = (ENV["RAP_VOCAL_DUCK_THRESHOLD_DB"] || -30).to_f.clamp(-60.0, 0.0)
# Off. Ratio 1 is a bypass: the sidechain stage stays in the graph and does
# nothing.
#
# It was added to answer "the vocals must be present when the rap is going",
# and it does that -- measured 4.50 dB of duck on the bed. The operator does not
# want it, which settles it: ducking the music under the voice is a radio
# technique and this is a record. Presence has to come from where the voice sits
# against the beat, not from pushing the beat out of the way.
#
# RAP_VOCAL_DUCK_RATIO=2 restores it.
RAP_VOCAL_DUCK_RATIO = (ENV["RAP_VOCAL_DUCK_RATIO"] || 1).to_f.clamp(1.0, 20.0)

# Reverse pre-swell: the head of each line, reversed and darkened, arriving
# exactly as the line starts. Impractical before line placement existed --
# it needs every downbeat known to the millisecond, which is precisely what
# snapping produces.
RAP_VOCAL_SWELL = ENV["RAP_VOCAL_SWELL"] == "1"
RAP_VOCAL_SWELL_SEC = (ENV["RAP_VOCAL_SWELL_SEC"] || 0.45).to_f.clamp(0.1, 2.0)
RAP_VOCAL_SWELL_VOL = (ENV["RAP_VOCAL_SWELL_VOL"] || 0.45).to_f.clamp(0.0, 1.5)

# Every segment currently gets a 20ms in / 50ms out fade so seams cannot click.
# Dilla did not clean his seams -- chop tails ran into the next chop. This lets
# the collisions through on purpose.
RAP_VOCAL_RAW_SEAMS = ENV["RAP_VOCAL_RAW_SEAMS"] == "1"

# Warp each line onto the grid, instead of only starting it there.
#
# The measurement above rules out ONE ratio for the whole take, and rightly:
# a freely-sung take has no constant syllable spacing for a ratio to scale.
# It does not rule out a ratio PER LINE. Each placed line has a known length
# and a known slot, so stretching it onto the nearest whole number of grid
# units is a different operation from stretching the take -- it is what a
# DAW's warp markers do, and the reason they work on takes atempo cannot.
#
# Placement alone fixes where a line BEGINS; a line that runs long still ends
# between grid lines and the next one starts from a slot it never reached.
# Warping fixes where it ENDS too.
#
# Off by default: it alters delivery inside a line, which placement
# deliberately preserves, and that is a taste decision rather than a
# correctness one. RAP_VOCAL_WARP=1 turns it on.
#
# The clamp matters more than the ratio. Outside roughly ±14% a stretched
# voice stops sounding like a performance and starts sounding like a plugin,
# so a line needing more than that is left alone rather than mangled -- the
# grid is not worth the formant damage.
RAP_VOCAL_WARP = ENV["RAP_VOCAL_WARP"] == "1"
RAP_VOCAL_WARP_MIN = (ENV["RAP_VOCAL_WARP_MIN"] || 0.88).to_f
RAP_VOCAL_WARP_MAX = (ENV["RAP_VOCAL_WARP_MAX"] || 1.14).to_f

# atempo=r plays r times faster, so a line of `length` becomes length/r. To
# land on `target` the ratio is length/target. Returns nil when the line is
# already close enough to a grid multiple to leave alone, or too far from one
# to reach without audible damage.
def rap_vocal_warp_ratio(length, grid)
  return nil unless RAP_VOCAL_WARP
  return nil if grid <= 0

  units = (length / grid).round
  return nil if units < 1

  target = units * grid
  ratio = length / target
  return nil if (ratio - 1.0).abs < 0.01
  return nil unless ratio.between?(RAP_VOCAL_WARP_MIN, RAP_VOCAL_WARP_MAX)

  ratio
end

def rap_vocal_line_lean(index)
  return 0.0 if RAP_VOCAL_LEAN_MS.zero?

  walk = RAP_VOCAL_LEAN_WALK[index % RAP_VOCAL_LEAN_WALK.length]
  (RAP_VOCAL_LEAN_MS + walk) / 1000.0
end

# Line detection thresholds. The catalog's stored "phrases" cannot be used for
# this: they are peak clusters joined at 0.35s, which on sung material collapse
# to bare onsets -- gunnhild's 100 stored phrases have a MEDIAN LENGTH OF ZERO,
# so cutting on them yields empty segments. These find voiced spans instead, and
# were swept against gunnhild for line-sized output: hold 0.14 / rel 0.55 gives
# 43 lines with a median of 1.23s, about two beats at 92 BPM. A longer hold
# swallows whole verses (0.20 gives one 13.96s span), a shorter one shatters
# words (0.06 gives a 0.49s median).
RAP_VOCAL_LINE_HOLD = (ENV["RAP_VOCAL_LINE_HOLD"] || 0.14).to_f
RAP_VOCAL_LINE_REL = (ENV["RAP_VOCAL_LINE_REL"] || 0.55).to_f
RAP_VOCAL_LINE_MIN = (ENV["RAP_VOCAL_LINE_MIN"] || 0.35).to_f

# Analysis rate and band. 8 kHz is plenty for locating syllables -- the band
# that decides where a voice is has nothing above 6 kHz in it -- and decoding
# less means the envelope pass costs nothing. Shared with rap_vocal_onset_times.
RAP_VOCAL_ANALYSIS_RATE = 8_000
RAP_VOCAL_ANALYSIS_HOP = 0.010
RAP_VOCAL_VOICE_HIGHPASS_HZ = 200
RAP_VOCAL_VOICE_LOWPASS_HZ = 6_000
PCM16_FULL_SCALE = 32_768.0

# The level a "loud" frame is measured against. Not the maximum: one clipped
# frame would then set the floor for the whole take.
RAP_VOCAL_LOUD_PERCENTILE = 0.90
# Below this a frame is silence no matter what the percentile says, so an
# all-but-silent stem cannot have its own noise promoted into "lines".
RAP_VOCAL_ABSOLUTE_FLOOR = 0.0015
RAP_VOCAL_MIN_ANALYSIS_FRAMES = 10

# RMS envelope of `path` in the voice band, one value per hop.
def rap_vocal_envelope(path, hop: RAP_VOCAL_ANALYSIS_HOP)
  raw = IO.popen(["ffmpeg", "-v", "error", "-i", path, "-af",
                  "highpass=f=#{RAP_VOCAL_VOICE_HIGHPASS_HZ}," \
                  "lowpass=f=#{RAP_VOCAL_VOICE_LOWPASS_HZ}",
                  "-ac", "1", "-ar", RAP_VOCAL_ANALYSIS_RATE.to_s,
                  "-f", "s16le", "-"], "rb", &:read)
  samples = raw.to_s.unpack("s<*")
  return [] if samples.empty?

  frame = (RAP_VOCAL_ANALYSIS_RATE * hop).to_i
  samples.each_slice(frame).map do |chunk|
    Math.sqrt(chunk.sum { |s| (s / PCM16_FULL_SCALE)**2 } / chunk.size)
  end
end

# The sung lines of a take: contiguous voiced spans, in its own timeline.
def rap_vocal_sung_lines(path, hop: RAP_VOCAL_ANALYSIS_HOP)
  env = rap_vocal_envelope(path, hop:)
  return [] if env.size < RAP_VOCAL_MIN_ANALYSIS_FRAMES

  # Relative floor, not absolute: demucs stem levels vary by tens of dB between
  # sources (measured -9.8 to -46.8), so any fixed threshold either passes
  # everything or nothing depending on which vocal it meets.
  sorted = env.sort
  loud = sorted[(sorted.size * RAP_VOCAL_LOUD_PERCENTILE).to_i].to_f
  floor = [loud * RAP_VOCAL_LINE_REL, RAP_VOCAL_ABSOLUTE_FLOOR].max
  hold_frames = (RAP_VOCAL_LINE_HOLD / hop).to_i

  lines = []
  start = nil
  quiet = 0
  env.each_with_index do |level, i|
    if level >= floor
      start ||= i
      quiet = 0
    elsif start
      quiet += 1
      next unless quiet > hold_frames

      lines << [start * hop, (i - quiet) * hop]
      start = nil
    end
  end
  lines << [start * hop, (env.size - 1) * hop] if start
  lines.select { |from, to| to - from >= RAP_VOCAL_LINE_MIN }
       .map { |from, to| [from.round(3), to.round(3)] }
end

# Decides where each line lands. Walks the lines in order, putting every one at
# the next free grid line, and returns [] if the take has too few lines to build
# from -- the caller then falls back to the uniform stretch rather than
# rendering something thin.
RAP_VOCAL_LINE_PREROLL_SEC = 0.06   # keep the consonant that starts the line
RAP_VOCAL_LINE_TAIL_SEC = 0.25      # and the vowel that ends it
RAP_VOCAL_SNAP_MIN_LINES = 4
# A runt line is skipped without advancing the cursor, so the loop needs a stop
# that does not depend on making progress.
RAP_VOCAL_SNAP_MAX_PASSES = 512

# A take gets used once. `taken % usable.size` wrapped back to the first line
# whenever the performance ran out before the section did, so a short stem was
# heard two, three or eight times over — the same words returning on a loop,
# which is the one thing a rap verse cannot survive. When the lines run out the
# vocal now stops and the beat carries the rest.
#
# RAP_VOCAL_REPEAT=1 restores the wrap for material where looping is the point
# (a hook, a chant), which is why this is a switch rather than a deletion.
RAP_VOCAL_REPEAT = ENV["RAP_VOCAL_REPEAT"] == "1"

def rap_vocal_snap_placements(lines, take_sec, duration:, grid:, from_sec: 0.0, gap:)
  return [] if lines.size < RAP_VOCAL_SNAP_MIN_LINES

  usable = lines.select { |(from, _)| from >= from_sec }
  usable = lines if usable.size < RAP_VOCAL_SNAP_MIN_LINES

  placements = []
  cursor = 0.0
  taken = 0
  passes = 0
  while cursor < duration && passes < RAP_VOCAL_SNAP_MAX_PASSES
    passes += 1
    break if !RAP_VOCAL_REPEAT && taken >= usable.size
    line_from, line_to = usable[taken % usable.size]
    taken += 1

    # Cut up to the next line's start so a tail is never clipped mid-vowel.
    next_from = lines.find { |(from, _)| from > line_from }&.first
    cut_from = [line_from - RAP_VOCAL_LINE_PREROLL_SEC, 0.0].max
    cut_to = [line_to + RAP_VOCAL_LINE_TAIL_SEC, next_from || take_sec, take_sec].min
    length = cut_to - cut_from
    next if length < RAP_VOCAL_LINE_MIN

    slot = (cursor / grid).ceil * grid
    break if slot >= duration

    length = [length, duration - slot].min
    next if length < RAP_VOCAL_LINE_MIN

    # `at` is where the VOICE should land. The cut starts `lead` earlier so the
    # opening consonant survives, so the segment itself has to be placed that
    # much before the grid line -- otherwise every line sits exactly one
    # pre-roll late, which measured as a flat ~62ms lag on every single line.
    lean = rap_vocal_line_lean(placements.size)
    at = [slot + lean, 0.0].max
    lead = line_from - cut_from
    # Warping changes how long the placed line sounds for, so the cursor has
    # to advance by the SOUNDED length or every line after this one inherits
    # the error.
    warp = rap_vocal_warp_ratio(length, grid)
    sounded = warp ? length / warp : length
    sounded_lead = warp ? lead / warp : lead
    placements << { from: cut_from.round(3), length: length.round(3),
                    at: at.round(3), lead: lead.round(3), lean: lean.round(4),
                    warp: warp&.round(4) }
    cursor = at + (sounded - sounded_lead) + gap
  end
  placements
end

SEAM_FADE_IN_SEC = 0.02
SEAM_FADE_OUT_SEC = 0.05
# Not an articulation -- just enough to stop the DC step at a hard cut popping.
SEAM_RAW_FADE_SEC = 0.003
# Darkened, because a reverse swell that keeps its consonants reads as audio
# played backwards rather than as a rise into the beat.
SWELL_LOWPASS_HZ = 2600
SWELL_ECHO_FRACTION = 0.35
SWELL_ECHO_DECAY = 0.45
SWELL_FADE_FRACTION = 0.8
SWELL_MIN_SEC = 0.1

# One ffmpeg input cut from `stretched`, delayed into place.
def rap_vocal_placed_input(source, from:, length:, at:, index:, filters:, label:)
  ms = [(at * 1000).round, 0].max
  {
    args: ["-ss", from.round(3).to_s, "-t", length.round(3).to_s, "-i", source],
    chain: "[#{index}:a]#{filters},adelay=#{ms}|#{ms}[#{label}#{index}]",
    label: "[#{label}#{index}]",
  }
end

# Cuts `stretched` into its lines and reassembles them on the grid.
def rap_vocal_render_snapped!(stretched, fit_path, placements, duration:, outer:, tail:)
  parts = []

  placements.each do |p|
    # atempo runs first, so everything after it is measured in sounded time:
    # the fade-out lands relative to the warped length, and the pre-roll that
    # positions the segment shrinks by the same ratio.
    warp = p[:warp]
    sounded_len = warp ? p[:length] / warp : p[:length]
    sounded_lead = warp ? p[:lead].to_f / warp : p[:lead].to_f
    seam = if RAP_VOCAL_RAW_SEAMS
             "afade=t=in:st=0:d=#{SEAM_RAW_FADE_SEC}"
           else
             out_at = [sounded_len - SEAM_FADE_OUT_SEC, 0.0].max
             "afade=t=in:st=0:d=#{SEAM_FADE_IN_SEC}," \
               "afade=t=out:st=#{out_at.round(3)}:d=#{SEAM_FADE_OUT_SEC}"
           end
    seam = "atempo=#{warp.round(4)},#{seam}" if warp
    parts << rap_vocal_placed_input(stretched, from: p[:from], length: p[:length],
                                    at: p[:at] - sounded_lead, index: parts.size,
                                    filters: seam, label: "s")
  end

  if RAP_VOCAL_SWELL
    placements.each do |p|
      swell = [RAP_VOCAL_SWELL_SEC, p[:length]].min
      next if swell < SWELL_MIN_SEC

      # Land the swell so it ENDS on the line's own downbeat: start it a swell
      # earlier, and reverse the line's head so the loudest part is last.
      at = p[:at] - swell
      next if at.negative?

      filters = "areverse,lowpass=f=#{SWELL_LOWPASS_HZ}," \
                "aecho=0.8:0.7:#{(swell * 1000 * SWELL_ECHO_FRACTION).round}:#{SWELL_ECHO_DECAY}," \
                "afade=t=in:st=0:d=#{(swell * SWELL_FADE_FRACTION).round(3)}," \
                "volume=#{RAP_VOCAL_SWELL_VOL}"
      parts << rap_vocal_placed_input(stretched, from: p[:from], length: swell,
                                      at:, index: parts.size,
                                      filters:, label: "w")
    end
  end

  chain = parts.map { |p| p[:chain] }
  # normalize=0: amix would otherwise divide by the input count, and with ~30
  # mostly non-overlapping lines that is a ~30x attenuation of every one of them.
  chain << "#{parts.map { |p| p[:label] }.join}" \
           "amix=inputs=#{parts.size}:normalize=0:dropout_transition=0[snap]"
  chain << "[snap]#{outer}#{tail}[vout]"
  sh! "ffmpeg", "-y", *parts.flat_map { |p| p[:args] },
      "-filter_complex", chain.join(";"),
      "-map", "[vout]", "-t", duration.round(3).to_s,
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", fit_path
  fit_path
end

# --- Vocal key alignment -----------------------------------------------------
# atempo preserves pitch. That is correct for a tempo fit and it is also why the
# vocal path has never changed a stem's key: rap_vocal_atempo_chain, asetpts and
# the crossfade loop all leave pitch alone, and nothing else in the chain touches
# it. So a stem whose notes sit outside the beat's key stays outside it for the
# entire render.
#
# Measured on gunnhild's 86bpm/32bar fit against db_major_minor_fall (Dbmaj7 Cm7 Fm7
# Bbm7 — Db major): the three strongest pitch classes in the vocal are A (17.5%
# of voiced energy), Ab (14.7%) and B (13.1%). A and B are not in Db major. In
# total 38.3% of the vocal's energy landed on non-key notes against 32.1% on key
# notes, with A — a major third against the Fm7 the progression sits on — the
# single loudest thing in the take.
#
# This is a key mismatch, not a detuned stem: the same fit measures -0.6 cents
# mean deviation from equal temperament, so it is in tune with itself and with
# A=440. Correcting it needs a transpose, not a fine-tune.
RAP_VOCAL_KEY_OCTAVES = (3..5).freeze
# ~130-988 Hz. Below C3 a semitone is narrower than the analysis resolution
# (3.9 Hz at N=2048/8kHz), so those octaves would smear into their neighbours.
RAP_VOCAL_KEY_SR = 8_000
RAP_VOCAL_KEY_N = 2_048
RAP_VOCAL_KEY_HOP = 1_024
# A transpose is a real cost -- asetrate resampling shifts formants, so a voice
# moved far reads as pitched-up/down rather than as the same singer in a new
# key. Cap it at a whole tone and take the smaller of two near-equal wins.
RAP_VOCAL_KEY_MAX_SHIFT = 2
# Don't spend a transpose on a coin-flip: the shift has to move at least this
# much of the vocal's energy onto key notes to be worth the formant cost.
RAP_VOCAL_KEY_MIN_GAIN = 0.05

# Chroma vector: 12 pitch classes, framewise Goertzel at each class's frequency
# in each analysed octave. Goertzel rather than a full FFT because only 36 of
# 1024 bins are ever read, and framewise rather than one pass over the whole
# take because a 16s window resolves to 0.06 Hz — far narrower than a sung note
# wanders, so the energy would smear across bins instead of accumulating.
def audio_chroma(path)
  raw = pipe_floats(path, "highpass=f=110,lowpass=f=1100," \
                          "aformat=sample_fmts=flt:channel_layouts=mono:sample_rates=#{RAP_VOCAL_KEY_SR}")
  return nil if raw.length < RAP_VOCAL_KEY_N

  targets = RAP_VOCAL_KEY_OCTAVES.flat_map do |octave|
    (0..11).map do |pc|
      midi = ((octave + 1) * 12) + pc
      [pc, 440.0 * (2**((midi - 69) / 12.0))]
    end
  end
  # Goertzel coefficient per target frequency, plus a Hann window reused across
  # frames.
  coeffs = targets.map { |pc, hz| [pc, 2.0 * Math.cos(2.0 * Math::PI * hz / RAP_VOCAL_KEY_SR)] }
  han = Array.new(RAP_VOCAL_KEY_N) { |n| 0.5 - (0.5 * Math.cos(2.0 * Math::PI * n / (RAP_VOCAL_KEY_N - 1))) }
  chroma = Array.new(12, 0.0)
  frames = 0
  pos = 0
  while pos + RAP_VOCAL_KEY_N <= raw.length
    win = Array.new(RAP_VOCAL_KEY_N) { |n| raw[pos + n] * han[n] }
    rms = Math.sqrt(win.sum { |v| v * v } / RAP_VOCAL_KEY_N)
    # Voiced frames only. Silence and breath carry no key, and a gated stem is
    # mostly silence — including it adds a flat floor to every class.
    if rms > 0.008
      coeffs.each do |pc, coeff|
        s1 = 0.0
        s2 = 0.0
        i = 0
        while i < RAP_VOCAL_KEY_N
          s0 = win[i] + (coeff * s1) - s2
          s2 = s1
          s1 = s0
          i += 1
        end
        chroma[pc] += Math.sqrt((s1 * s1) + (s2 * s2) - (coeff * s1 * s2))
      end
      frames += 1
    end
    pos += RAP_VOCAL_KEY_HOP
  end
  return nil if frames.zero?

  total = chroma.sum
  return nil unless total.positive?

  chroma.map { |v| v / total }
end

# Root pitch class of a chord name. PAD_CHORD_LOOKUP only holds the voicings the
# pad engine registered, and the progressions name chords it never registered:
# db_major_minor_fall is Dbmaj7/Cm7/Fm7/Bbm7 while the lookup carries the ...maj9/m9
# forms, so every one of its four chords missed and the whole progression scored
# as having no harmony at all.
CHORD_ROOT_RE = /\A([A-G])([b#]?)/
def chord_name_root_class(name)
  m = CHORD_ROOT_RE.match(name.to_s)
  return nil unless m

  base = { "C" => 0, "D" => 2, "E" => 4, "F" => 5, "G" => 7, "A" => 9, "B" => 11 }[m[1]]
  return nil if base.nil?

  case m[2]
  when "b" then (base - 1) % 12
  when "#" then (base + 1) % 12
  else base
  end
end

# Third and fifth implied by the name, so a chord the lookup does not carry still
# contributes the interval that decides major vs minor -- the distinction the
# vocal actually clashes with.
def chord_name_tone_classes(name)
  root = chord_name_root_class(name)
  return [] if root.nil?

  body = name.to_s.sub(CHORD_ROOT_RE, "").sub(%r{/.*\z}, "")
  minor = body.match?(/\Am(?!aj)/)
  dim = body.match?(/\Adim|\A0/)
  third = if dim || minor then 3 else 4 end
  fifth = dim ? 6 : 7
  [root, (root + third) % 12, (root + fifth) % 12]
end

# How strongly each pitch class belongs to the progression, as a weight rather
# than a member/non-member flag. A binary set is useless on the slash-chord
# progressions: pedal_e_descent (D/E Db/E C/E Bm/E Bbm/E Am/E) unions to all
# twelve classes, so every shift scored a perfect 100% and the comparison
# carried no information. Counting how many chords contain a class keeps the
# tonic centre distinguishable from a passing chromatic tone.
def progression_pitch_class_weights(progression)
  names = CHORD_PROGRESSIONS[progression]
  return nil if names.nil? || names.empty?

  weights = Array.new(12, 0.0)
  names.each do |name|
    chord = PAD_CHORD_LOOKUP[name]
    classes = Array(chord && chord[:hz]).filter_map do |hz|
      next nil unless hz.to_f.positive?
      (69 + (12 * Math.log2(hz.to_f / 440.0))).round % 12
    end
    classes = chord_name_tone_classes(name) if classes.empty?
    # Root and third carry the chord's identity; count the whole voicing but
    # give the root extra weight so the tonic centre wins ties.
    classes.uniq.each { |c| weights[c] += 1.0 }
    root = chord_name_root_class(name)
    weights[root] += 0.5 if root
  end
  total = weights.sum
  return nil unless total.positive?

  weights.map { |w| w / total }
end

# Pick the transpose that best lines the vocal's energy up with the progression's
# harmony: the dot product of the vocal chroma against the shifted chord-tone
# weights. Ties go to the smaller shift, and 0 wins unless a shift clears
# RAP_VOCAL_KEY_MIN_GAIN relative to it, so a vocal already in key is untouched.
def rap_vocal_key_shift(chroma, key_weights, max_shift: RAP_VOCAL_KEY_MAX_SHIFT)
  return 0 if chroma.nil? || key_weights.nil?

  scored = (-max_shift..max_shift).map do |shift|
    # Shifting the audio up by `shift` moves energy at class c to c+shift, so
    # compare chroma[c] against the weight of where it lands.
    fit = (0..11).sum { |c| chroma[c] * key_weights[(c + shift) % 12] }
    [shift, fit]
  end
  base = scored.find { |shift, _| shift.zero? }.last
  return 0 unless base.positive?

  # The threshold is relative, and it scales with the size of the move. Relative
  # because the dot product's scale depends on how concentrated the
  # progression's weights are, so one absolute number would mean different
  # things for a 4-chord vamp and a 12-class slash cycle. Scaled because the
  # cost is not flat: a whole tone through asetrate resamples formants by 12%,
  # which reads as a pitched-up singer rather than the same singer in a new key,
  # so it has to earn twice what a semitone does. Measured on gunnhild: this is
  # what separates db_major_minor_fall (+1 at 5.1%, taken) from its own +2 at 8.7%
  # (rejected — a bigger move on weaker evidence).
  qualified = scored.select do |shift, fit|
    next false if shift.zero?
    (fit - base) / base >= RAP_VOCAL_KEY_MIN_GAIN * shift.abs
  end
  return 0 if qualified.empty?

  qualified.max_by { |shift, fit| [fit.round(6), -shift.abs] }.first
end

# asetrate raises pitch and tempo together; atempo puts the tempo back. That
# leaves the take its original length in the new key. Formants move with the
# resample, which is the reason RAP_VOCAL_KEY_MAX_SHIFT is small.
def rap_vocal_pitch_shift_chain(semitones)
  return nil if semitones.to_i.zero?

  ratio = 2**(semitones.to_f / 12.0)
  "asetrate=#{(SAMPLE_RATE * ratio).round},aresample=#{SAMPLE_RATE}," \
    "#{rap_vocal_atempo_chain(1.0 / ratio)}"
end

# Resolved once per fit and cached on the catalog entry: the chroma pass costs a
# full decode plus 36 Goertzel accumulators per frame, and a stem's key does not
# change between renders.
def rap_vocal_resolved_key_shift(entry, vocal_path, progression)
  return 0 if ENV["RAP_VOCAL_KEY_ALIGN"] == "0"

  forced = ENV["RAP_VOCAL_KEY_SHIFT"]
  return forced.to_i.clamp(-6, 6) if forced && !forced.strip.empty?

  key_weights = progression_pitch_class_weights(progression)
  return 0 if key_weights.nil?

  chroma = entry.is_a?(Hash) ? entry["chroma"] : nil
  if chroma.nil? || chroma.length != 12
    chroma = audio_chroma(vocal_path)
    return 0 if chroma.nil?
    if entry.is_a?(Hash)
      entry["chroma"] = chroma.map { |v| v.round(5) }
      cat = rap_vocal_load_catalog
      cat["vocals"] = Array(cat["vocals"]).map { |v| v["slug"] == entry["slug"] ? entry : v }
      rap_vocal_save_catalog!(cat)
    end
  end
  rap_vocal_key_shift(chroma, key_weights)
end

# Where in the take this track enters.
#
# The offset above is computed from the take alone -- densest region, snapped
# to the vocal's own bar grid -- so it is the same for every track using that
# take. Four takes over a 451-track demo put the same rap on roughly fifty
# tracks each, entering at the same word.
#
# Walks `variant` phrases further in and wraps, so a short performance still
# yields new material across a long catalogue. Phrase starts rather than raw
# seconds, so an entry still lands at the top of a line and not mid-word.
def rap_vocal_variant_offset(base, variant, phrases:, vocal_path:)
  starts = Array(phrases).filter_map { |p| (p["start"] || p[:start])&.to_f }.sort
  if starts.empty?
    rhythm = frame_energy(vocal_path, highpass: 300, lowpass: 6000)
    starts = peak_frames(rhythm[:frames], rhythm[:hop_seconds]).map { |p| p[:time].to_f }.sort
  end
  return base if starts.empty?

  ahead = starts.select { |s| s >= base }
  ahead = starts if ahead.empty?
  ahead[variant.to_i % ahead.size]
rescue StandardError
  base
end

def rap_vocal_fit!(slug_or_path, beat_bpm:, n_bars:, bar_offset: nil, progression: nil, variant: 0)
  bar_offset ||= ENV["RAP_VOCAL_OFFSET"]&.to_f
  entry = rap_vocal_resolve(slug_or_path)
  vocal_path = entry.is_a?(Hash) ? entry["vocal_path"] : entry
  unless vocal_path && File.file?(vocal_path)
    warn "rap-vocal fit: unknown or missing slug #{slug_or_path}"
    return
  end
  # Always re-isolate uncleaned stems; already-isolated stems get a light polish only.
  isolated = entry.is_a?(Hash) && entry["isolated"] == true
  if entry.is_a?(Hash) && !isolated
    cleaned = File.join(File.dirname(vocal_path), "vocals.clean.wav")
    rap_vocal_clean_stem!(vocal_path, cleaned, aggressive: true)
    # Keep the raw demucs stem. This used to `mv` the cleaned file over
    # vocal_path, destroying the only local copy of the isolation output --
    # and because the entry is then marked isolated, it never re-cleans, so a
    # mis-gated clean is permanent with no way back. gunnhild lost its 0-16s
    # vocal section this way (present in the demucs stem, silent in the working
    # copy). Point the entry at the cleaned file instead and leave the source.
    raw_keep = File.join(File.dirname(vocal_path), "vocals.raw.wav")
    FileUtils.cp(vocal_path, raw_keep) unless File.exist?(raw_keep)
    FileUtils.mv(cleaned, vocal_path)
    entry["raw_path"] = raw_keep
    entry["isolated"] = true
    entry["voice_only"] = true
    entry["phrases"] = rap_vocal_phrase_onsets(vocal_path)
    cat = rap_vocal_load_catalog
    cat["vocals"] = Array(cat["vocals"]).map { |v| v["slug"] == entry["slug"] ? entry : v }
    rap_vocal_save_catalog!(cat)
    isolated = true
  end
  beat_bpm = beat_bpm.to_f
  vocal_bpm = rap_vocal_source_bpm(entry, vocal_path, target: beat_bpm)
  vocal_bpm = beat_bpm unless vocal_bpm&.positive?
  # Clamp stretch: extreme atempo starts to chipmunk/garble speech.
  ratio = (beat_bpm / vocal_bpm).clamp(0.5, 2.0)

  # Snap when the take has no measurable pulse, stretch when it has one.
  # RAP_VOCAL_SNAP=1/0 forces either way.
  forced_bpm = ENV["RAP_VOCAL_BPM"].to_f.positive?
  has_pulse = !rap_vocal_measure_bpm(vocal_path).nil?
  snapping = case ENV["RAP_VOCAL_SNAP"]
             when "0" then false
             when "1" then true
             else !has_pulse
             end
  if snapping && !forced_bpm
    # With no pulse, `vocal_bpm` is a stored guess and stretching by it is the
    # meaningless operation this path exists to replace. Leave her at her own
    # speed unless someone asks for a stretch on purpose.
    ratio = 1.0
  end
  duration = (60.0 / beat_bpm) * 4.0 * n_bars
  phrases = entry.is_a?(Hash) ? entry["phrases"] : nil
  # An explicit bar_offset (caller or RAP_VOCAL_OFFSET) is a deliberate pick
  # -- honor it outright. Only auto-picked offsets get floored to the real
  # speech onset, since that floor exists to skip residual intro thump, not
  # to override someone choosing a different section on purpose.
  phrase_start = nil
  if bar_offset
    ss = bar_offset
  else
    # Pick the region by content first -- the densest `duration * ratio`
    # seconds of actual singing -- then let the phrase/bar logic nudge within
    # it. Falls back to the old earliest-strong-phrase rule if the content
    # scan cannot run.
    needed = duration * ratio
    content = rap_vocal_content_offset(vocal_path, needed)
    phrase_start = rap_vocal_phrase_start(phrases) || 0.0
    ss = if content
           # Snap the content region to the vocal's own bar grid, so the cut
           # starts on a downbeat and stays on the grid once stretched.
           #
           # This was `content + (bar_nudge % target_bar_seconds)`: it added a
           # remainder of one measurement to the start of another, in a
           # different tempo's units. Whatever came out was not a bar boundary
           # in either timeline.
           source_bar = (60.0 / vocal_bpm) * 4.0
           phase = rap_vocal_best_bar_offset(vocal_path, vocal_bpm, phrases:).to_f
           bars_in = ((content - phase) / source_bar).round
           [phase + (bars_in * source_bar), 0.0].max.round(4)
         else
           # Same grid as above — the vocal's own, not the beat's.
           [rap_vocal_best_bar_offset(vocal_path, vocal_bpm, phrases:), phrase_start].max
         end
  end
  variant = variant.to_i
  ss = rap_vocal_variant_offset(ss, variant, phrases:, vocal_path:) if variant.positive? && !bar_offset
  out_dir = File.dirname(vocal_path)
  # Transposed into the beat's key in stage 1 below. Resolved here because the
  # shift has to be part of the filename: bpm+bars alone named the same file for
  # two tracks at the same tempo in different keys, so whichever rendered first
  # won and the second silently reused a fit built for someone else's harmony.
  key_shift = rap_vocal_resolved_key_shift(entry, vocal_path, progression)
  key_tag = key_shift.zero? ? "" : format("_key%+d", key_shift)
  # variant is part of the name because the fit is cached on this path: without
  # it two tracks at one tempo and key were handed the same rendered vocal.
  variant_tag = variant.positive? ? "_v#{variant}" : ""
  fit_path = File.join(out_dir, "fit_#{beat_bpm.round}_#{n_bars}bars#{key_tag}#{variant_tag}.wav")
  # Already-isolated → light polish only (no second heavy makeup that re-lifts bleed).
  # Fresh/unclean → full voice-only isolation.
  voice_chain = isolated ? rap_vocal_voice_polish_filter : rap_vocal_isolation_filter
  # Loop source so short verses cover full N bars (voice-only — never pad with kit).
  # Soft edge fades avoid wrap clicks after atempo.
  fade = [0.012, duration * 0.004].max.round(4)
  loudnorm_i = ENV.fetch("RAP_VOCAL_LOUDNORM_I", "-17")
  limiter = ENV.fetch("RAP_VOCAL_LIMITER", "0.93")
  # Stacking this loudnorm+limiter here AND the mix-stage limiter in
  # mix_rap_vocal_layer! double-squashes dynamics into a "maxed"/pumped
  # feel even with no true clipping.
  #
  # Now off by default, because the fit's absolute level does not survive the
  # mix stage anyway: mix_rap_vocal_layer! measures this file's voice-band RMS
  # and applies its own norm_db to hit the anchor. So loudnorm's I=-17 target is
  # discarded a step later and the only thing it leaves behind is LRA=7's
  # dynamic-range compression plus a second limiter — squashed transients on a
  # vocal whose own spectrum measures smooth (peak 400-630 Hz, monotonic
  # rolloff above). That is what reads as hard/sharp once it is also loud.
  # RAP_VOCAL_SKIP_LOUDNORM=0 restores the old behaviour.
  # Measured 2026-08-10, so nobody re-derives it: the report "the vocals go up
  # and down in volume" is NOT this stage. Re-enabling loudnorm here (LRA=11, no
  # second limiter) moves the fitted store_p stem from LRA 4.4 to 3.9 -- the
  # stem is already even, and there is no wide dynamic range at this point for
  # loudnorm to control. That change was made, measured, and reverted.
  #
  # Where to look instead: the anchor in mix_rap_vocal_layer!
  # (RAP_VOCAL_ANCHOR_DB, currently -3.0) sets the voice against the FULL-band
  # beat RMS, which includes kick and bass, so it governs audibility directly;
  # and alimiter on the summed mix is the only dynamics acting on vocal peaks,
  # so it is the candidate for both the pumping and the saturation.
  tail = if ENV.fetch("RAP_VOCAL_SKIP_LOUDNORM", "1") == "1"
           ""
         else
           ",loudnorm=I=#{loudnorm_i}:TP=-2.5:LRA=7,alimiter=limit=#{limiter}:level_out=#{(limiter.to_f + 0.01).round(2)}"
         end
  # Stage 1: process the usable region ONCE (isolation + tempo match), no loop.
  # The old single-pass version did `-stream_loop -1` with `-ss`, which restarts
  # at the seek point every wrap, and applied afade only at the outer edges of
  # the whole output -- so every wrap was an unfaded hard splice landing mid-word.
  # With gunnhild (11.5s usable from ss) a 32-bar render wrapped ~8 times, which
  # is exactly the "choppy" report.
  seg_path = File.join(out_dir, "seg_#{beat_bpm.round}_#{n_bars}bars.wav")
  # Transpose in the same pass as the tempo fit and before the loudnorm/limiter
  # tail, so the level measured downstream is the level of what actually plays.
  pitch_chain = rap_vocal_pitch_shift_chain(key_shift)
  if pitch_chain
    dmesg("rap-vocal key: #{key_shift.positive? ? '+' : ''}#{key_shift} semitone#{key_shift.abs == 1 ? '' : 's'} " \
          "into #{progression || 'beat'} key",
          unit: "vox0", parent: "dilla0")
  end
  seg_af = ["#{voice_chain},#{rap_vocal_atempo_chain(ratio)}", pitch_chain, "asetpts=PTS-STARTPTS"]
           .compact.join(",")
  sh! "ffmpeg", "-y", "-ss", ss.round(3).to_s, "-i", vocal_path,
      "-af", seg_af,
      "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", seg_path
  seg_len = audio_duration_sec(seg_path).to_f

  # Stage 2: fill `duration`. One pass if the segment already covers it;
  # otherwise repeat it with a real crossfade at each seam so the joins are
  # inaudible instead of clicking.
  xfade = ENV.fetch("RAP_VOCAL_XFADE", "0.35").to_f.clamp(0.05, 2.0)
  xfade = [xfade, seg_len / 3.0].min if seg_len.positive?
  outer = "afade=t=in:st=0:d=#{fade},afade=t=out:st=#{(duration - fade).round(3)}:d=#{fade}"

  # seg_path already runs from `ss` to the end of the take, so its lines are the
  # whole usable performance and the placer picks from all of them.
  snapped = nil
  if snapping
    beat_sec = 60.0 / beat_bpm
    lines = rap_vocal_sung_lines(seg_path)
    placements = rap_vocal_snap_placements(lines, seg_len, duration:,
                                           grid: beat_sec * RAP_VOCAL_SNAP_BEATS,
                                           gap: beat_sec * 0.25)
    if placements.size >= 4
      rap_vocal_render_snapped!(seg_path, fit_path, placements, duration:, outer:, tail:)
      snapped = placements
      dmesg("rap-vocal snap: #{placements.size} lines of #{lines.size} onto a " \
            "#{RAP_VOCAL_SNAP_BEATS.round}-beat grid (no pulse to stretch)",
            unit: "vox0", parent: "dilla0")
    else
      warn "rap-vocal snap: #{lines.size} lines gave #{placements.size} placements — " \
           "using the uniform stretch instead"
    end
  end

  if snapped
    nil # built by rap_vocal_render_snapped!
  elsif seg_len <= 0 || seg_len >= duration
    sh! "ffmpeg", "-y", "-i", seg_path, "-t", duration.round(3).to_s,
        "-af", "#{outer}#{tail}",
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", fit_path
  elsif !RAP_VOCAL_REPEAT
    # The take is shorter than the section and repeating is off, so it plays once
    # and the beat carries the rest. apad fills the remainder with silence: the
    # downstream mix expects a stem of exactly `duration`, and a short one would
    # be handled by amix's dropout logic instead, which is not the same thing.
    dmesg("rap-vocal once: #{seg_len.round(2)}s over #{duration.round(2)}s, no repeat",
          unit: "vox0", parent: "dilla0")
    sh! "ffmpeg", "-y", "-i", seg_path,
        "-af", "#{outer}#{tail},apad", "-t", duration.round(3).to_s,
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", fit_path
  else
    # Each crossfade consumes `xfade` of overlap, so n copies span
    # n*seg_len - (n-1)*xfade.
    copies = (((duration - xfade) / (seg_len - xfade)).ceil + 1).clamp(2, 64)
    inputs = Array.new(copies) { ["-i", seg_path] }.flatten
    chain = []
    prev = "0:a"
    (1...copies).each do |i|
      out = i == copies - 1 ? "xf" : "xf#{i}"
      chain << "[#{prev}][#{i}:a]acrossfade=d=#{xfade.round(3)}:c1=tri:c2=tri[#{out}]"
      prev = out
    end
    chain << "[#{prev}]#{outer}#{tail}[vout]"
    dmesg("rap-vocal loop: #{copies} copies of #{seg_len.round(2)}s, #{xfade.round(2)}s crossfades",
          unit: "vox0", parent: "dilla0")
    sh! "ffmpeg", "-y", *inputs, "-filter_complex", chain.join(";"),
        "-map", "[vout]", "-t", duration.round(3).to_s,
        "-ar", SAMPLE_RATE.to_s, "-ac", "2", "-c:a", "pcm_s16le", fit_path
  end
  FileUtils.rm_f(seg_path)
  peak = band_rms(fit_path, highpass: 200, lowpass: 6_000) rescue -90.0
  sub_bleed = band_rms(fit_path, highpass: 30, lowpass: 120) rescue -90.0
  if peak < -50.0
    warn "rap-vocal fit: stem too quiet (rms≈#{peak.round(1)} dB) — #{fit_path}"
  end
  if sub_bleed > -38.0
    warn "rap-vocal fit: sub bleed still high (#{sub_bleed.round(1)} dB <120Hz) — re-clean recommended"
  end
  if entry.is_a?(Hash)
    entry["last_fit"] = { "path" => fit_path, "beat_bpm" => beat_bpm, "n_bars" => n_bars,
                          "offset_sec" => ss, "phrase_start" => phrase_start,
                          "source_bpm" => vocal_bpm, "tempo_ratio" => ratio.round(4),
                          "rms_db" => peak, "sub_bleed_db" => sub_bleed,
                          "snapped_lines" => snapped&.size, "has_pulse" => has_pulse,
                          "key_shift" => key_shift, "progression" => progression&.to_s,
                          "voice_only" => true }
    entry["bpm_estimate"] = vocal_bpm if vocal_bpm.positive?
    entry["voice_only"] = true
    cat = rap_vocal_load_catalog
    cat["vocals"] = Array(cat["vocals"]).map { |v| v["slug"] == entry["slug"] ? entry : v }
    rap_vocal_save_catalog!(cat)
  end
  placed = snapped ? " snapped=#{snapped.size}lines" : ""
  puts "rap-vocal fit: #{fit_path} src=#{vocal_bpm}bpm → #{beat_bpm}bpm " \
       "ratio=#{ratio.round(3)} start=#{ss}s bars=#{n_bars}#{placed} " \
       "voice≈#{peak.round(1)}dB sub≈#{sub_bleed.round(1)}dB"
  fit_path
end

def rap_vocal_mix_params
  # Level trim applied on top of the beat-relative anchor below. History: 1.15
  # (voice-forward) → 0.85 (pulled down on request) → 1.0. At 0.85, combined
  # with the old -6 dB anchor, the vocal landed ~7 dB under the beat in the
  # band where the two actually compete, which read as inaudible rather than
  # as "sitting in the mix". Anchor + trim are separate knobs now so the
  # placement target and the taste trim can move independently.
  vocal_vol = ENV.fetch("RAP_VOCAL_MIX", "1.0").to_f
  bed_w = ENV.fetch("RAP_VOCAL_BED_WEIGHT", "1.0").to_f
  voc_w = ENV.fetch("RAP_VOCAL_WEIGHT", "1.0").to_f
  # 3.0 dB of shelf from 9 kHz up, an octave and a bit wide, on a source that
  # already gets +2.2 dB at 3.2 kHz from the isolation chain and has no de-esser
  # anywhere after it. That stacked boost on sibilants is the "sharp" report.
  # 1.0 dB keeps consonants legible without the top-end edge, and the deesser
  # below catches what remains.
  sparkle_db = ENV.fetch("RAP_VOCAL_SPARKLE_DB", "1.0").to_f
  deess = ENV.fetch("RAP_VOCAL_DEESS", "0.35").to_f.clamp(0.0, 1.0)
  hpf_hz = ENV.fetch("RAP_VOCAL_HPF", "90").to_f
  lowmid_cut_db = ENV.fetch("RAP_VOCAL_LOWMID_CUT_DB", "2.0").to_f
  { vocal_vol:, bed_w:, voc_w:, sparkle_db:, deess:, hpf_hz:, lowmid_cut_db: }
end

# Mirrors DillaGroove's snare pocket push (role_timing_offset's early-snare
# tick offset) so the vocal's overall entry lands in the pushed pocket the
# backbeat sits in, instead of dead-on-grid. A rap vocal phrases off the
# snare, not the kick; this nudges the clip's anchor, not per-syllable timing.
def rap_vocal_pocket_nudge_sec(beat_bpm)
  return 0.0 if ENV["RAP_VOCAL_POCKET_NUDGE"] == "0"
  return 0.0 unless defined?(DillaGroove) && DillaGroove.enabled?
  beat_p = 60.0 / beat_bpm.to_f
  tick = beat_p / 96.0
  mul = DillaGroove.pocket_dna? ? 4 : 3
  tick * mul
end

# Gain staging is load-bearing here. amix runs normalize=0, so the weights
# are absolute: the voice reaches the limiter at vocal_vol*voc_w against the
# bed at bed_w. Push that ratio too far and alimiter clamps on every vocal
# peak and applies the reduction to the whole mix, taking the kit down with
# it. Keep the ratio modest and let the voice sit, rather than buying
# presence with gain the limiter then reclaims from the drums. Filter chain
# stays single-stage on purpose (no gate/compressor/sidechain): that
# combination previously made a good vocal source disappear once mixed.
def mix_rap_vocal_layer!(beat_path, vocal_path, dest, beat_bpm: nil)
  mix = rap_vocal_mix_params
  # Normalize the fitted stem against the beat BEFORE the mix knob: stems
  # arrive at wildly different levels (gunnhild's demucs stem is far quieter
  # than jonas_v's was), so a fixed multiplier made quiet stems disappear
  # into the bed entirely. RAP_VOCAL_MIX now means the same thing for every
  # stem: 1.0 = voice band anchored 6 dB under the full beat.
  beat_rms = band_rms(beat_path, highpass: 20, lowpass: 20_000)
  voice_rms = band_rms(vocal_path, highpass: 150, lowpass: 8_000)
  # Where the vocal sits relative to the beat, in dB. 0.0 = level with it,
  # negative tucks it under. beat_rms here is the FULL band (20-20k), so 0.0
  # anchored the voice band level with kick, bass and kit summed together —
  # which is louder than a lead vocal sits in any mix, and is the "way too loud"
  # report. History: -6.0 (inaudible, because it stacked with a 0.85 trim) →
  # 0.0 (too loud) → -3.0. The trim knob is separate now, so the earlier
  # -6 dB failure does not apply to this value.
  anchor_db = ENV.fetch("RAP_VOCAL_ANCHOR_DB", "-3.0").to_f
  norm_db = ((beat_rms + anchor_db) - voice_rms).clamp(-12.0, 24.0)
  nudge = beat_bpm ? rap_vocal_pocket_nudge_sec(beat_bpm) : 0.0
  trim = nudge.positive? ? "atrim=start=#{nudge.round(4)},asetpts=PTS-STARTPTS," : ""
  filter = [
    "[1:a]aformat=channel_layouts=stereo,#{trim}volume=#{norm_db.round(2)}dB," \
    "highpass=f=#{mix[:hpf_hz]}," \
    "bass=g=-#{mix[:lowmid_cut_db]}:f=300:width_type=o:width=1.0," \
    "treble=g=#{mix[:sparkle_db]}:f=9000:width_type=o:width=1.2," \
    "#{mix[:deess].positive? ? "deesser=i=#{mix[:deess].round(2)}:m=0.5:f=0.18," : ''}" \
    "volume=#{mix[:vocal_vol]}[v0]",
    # The vocal keys a duck on the beat. Both halves of this used to be one
    # fixed amix into a limiter, and that is why the voice came and went: the
    # weights are constant, so when the beat thickens the SUM rises, the limiter
    # pulls the whole sum down, and the vocal — the smaller part of it — goes
    # down with the beat. Thin the beat out again and the voice reappears. It
    # was never the vocal moving; it was the bed moving under a shared limiter.
    #
    # Turning the voice up is the wrong repair. Level is what drives the limiter,
    # so a louder vocal makes the pumping worse and adds the hardness that reads
    # as saturation. Ducking the bed instead makes room without adding level:
    # the sum gets quieter while the rap is going, so the limiter does less work
    # exactly when intelligibility matters most.
    #
    # Measured, not estimated: against a steady key at -30 dB threshold the bed
    # drops 4.50 dB at ratio 2, against 0.30 dB at ratio 1 and 7.40 dB at
    # ratio 6. Four and a half dB is the broadcast voiceover range — decisive
    # enough that the voice sits in front, short of the audible pump of a
    # dance-mix sidechain. A real vocal is intermittent where the test key was
    # steady, so that figure is the ceiling rather than the average.
    # 6 ms catches a syllable onset; 260 ms is longer than the gap
    # between words, so it rides a whole line rather than chattering between
    # them, which is the difference between presence and a tremolo.
    "[v0]asplit=2[v_mix][v_key]",
    "[0:a][v_key]sidechaincompress=" \
    "threshold=#{RAP_VOCAL_DUCK_THRESHOLD_DB}dB:ratio=#{RAP_VOCAL_DUCK_RATIO}:" \
    "attack=6:release=260:makeup=1:detection=rms:link=average[bed]",
    "[bed][v_mix]amix=inputs=2:weights=#{mix[:bed_w]} #{mix[:voc_w]}:duration=first:dropout_transition=0:normalize=0," \
    "alimiter=limit=0.96:level_out=0.97[out]",
  ].join(";")
  sh! "ffmpeg", "-y", "-i", beat_path, "-i", vocal_path,
      "-filter_complex", filter,
      "-map", "[out]", *codec_for(dest), dest
end

# --------------------------------------------------------------------------
# engine part: punk_guitar
# --------------------------------------------------------------------------
#
# The punk guitar layer.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def punk_guitar_enabled?
  ENV["PUNK_GUITAR"] == "1"
end

# Straight (unswung) sixteenth-note downstroke chug -- root+5th only, no
# third -- through the existing dist_guitar GM patch, dropped an octave so
# it sits below the Rhodes/pad register instead of fighting it. Deliberately
# ignores the swung Dilla drum grid: the contrast between machine-straight
# punk strumming and the humanized kit is the point. Accented on-beat hits
# vs. quieter/shorter off-beat palm-mutes (classic downstroke gallop), with
# occasional syncopated rests so it doesn't read as a machine-gun wall.
# Follows the same chord roots as the main progression, cycled per bar.
def render_punk_guitar_layer!(beat_bpm, n_bars, cfg)
  return nil unless fluidsynth_pad_available?
  names = CHORD_PROGRESSIONS[cfg[:progression]] || CHORD_PROGRESSIONS.fetch(:soul)
  return nil if names.empty?
  beat_p = 60.0 / beat_bpm.to_f
  step = beat_p / 4.0
  bar_len = beat_p * 4.0
  duration = bar_len * n_bars
  rng = Random.new(42)
  events = []
  (duration / step).floor.times do |i|
    on_beat = (i % 4).zero?
    next if !on_beat && rng.rand < 0.15
    t = i * step
    chord = PAD_CHORD_LOOKUP[names[(t / bar_len).floor % names.length]]
    next unless chord && chord[:hz]&.any?
    root = chord[:hz].min / 2.0
    fifth = root * (2**(7.0 / 12.0))
    vel = on_beat ? 0.95 : 0.5
    sustain = on_beat ? step * 0.7 : step * 0.3
    events << [t, vel, { hz: [root, fifth] }, sustain]
  end
  return nil if events.empty?
  voice = patch_voice_for(synth_patch_by_id(:dist_guitar))
  return nil unless voice
  dir = Dir.mktmpdir("punk_guitar")
  path = File.join(dir, "guitar.wav")
  midi_path = "#{path}.mid"
  write_smf(midi_path, events, program: voice[:program], bank: voice[:bank] || 0, duration:, lead_mode: true)
  fluidsynth_render!(path, voice[:sf2], midi_path, gain: 1.2)
  FileUtils.rm_f(midi_path)
  path
end

# Amp crunch, dialed back: highpass off the low end (kick/bass own that
# range), a mid scoop around 700Hz to carve space from the Rhodes/pad
# instead of competing with it, gentler compression, and a light bit-crush
# for grit rather than heavy distortion. Sits under the beat by weight --
# same amix-not-sidechain discipline as the vocal layer.
def mix_punk_guitar_layer!(beat_path, guitar_path, dest)
  gtr_vol = ENV.fetch("PUNK_GUITAR_MIX", "0.85").to_f
  bed_w = ENV.fetch("PUNK_GUITAR_BED_WEIGHT", "1.0").to_f
  gtr_w = ENV.fetch("PUNK_GUITAR_WEIGHT", "0.5").to_f
  lowpass_hz = ENV.fetch("PUNK_GUITAR_LOWPASS", "5200").to_f
  filter = [
    "[1:a]aformat=channel_layouts=stereo,highpass=f=110,lowpass=f=#{lowpass_hz}," \
    "equalizer=f=700:t=o:w=1.5:g=-4," \
    "acompressor=threshold=-14dB:ratio=4:attack=5:release=80," \
    "acrusher=bits=12:samples=2:mix=0.08,volume=#{gtr_vol}[g0]",
    "[0:a][g0]amix=inputs=2:weights=#{bed_w} #{gtr_w}:duration=first:dropout_transition=0:normalize=0," \
    "alimiter=limit=0.96:level_out=0.97[out]",
  ].join(";")
  sh! "ffmpeg", "-y", "-i", beat_path, "-i", guitar_path,
      "-filter_complex", filter,
      "-map", "[out]", *codec_for(dest), dest
end

# --------------------------------------------------------------------------
# engine part: learn_source
# --------------------------------------------------------------------------
#
# Learning from a source or a whole playlist.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

def learn_source!(src, apply: false, deep: false, start_sec: nil, meta: nil)
  DillaMusicGems.bootstrap! if defined?(DillaMusicGems)
  audio_path = if File.exist?(src.to_s)
                 File.expand_path(src)
               else
                 demux_fetch_audio(src, start_sec:)
               end
  stem_dir = demux_six(audio_path)
  demux_deep_bands!(stem_dir) if deep
  stem_analysis = {}
  Dir[File.join(stem_dir, "*.wav")].sort.each do |wav|
    name = File.basename(wav)
    stem_analysis[name] = analyze_stem_for_learn(wav, name)
  end
  full_analysis = RadioBergenStudy::DeepAudio.analyze(audio_path)
  report = DillaSourceLearn.compose_report(
    source: src,
    stem_dir:,
    stem_analysis:,
    full_analysis:,
  )
  report = report.merge(meta) if meta.is_a?(Hash)
  if meta.is_a?(Hash) && meta[:id]
    learn_register_texture_stems!(stem_dir, meta[:id], bpm: report[:bpm_estimate])
  end
  paths = DillaSourceLearn.save_report!(report)
  puts JSON.pretty_generate(report.merge(saved: paths))
  if apply
    applied = DillaSourceLearn.apply_hints_to_env!(report[:engine_hints])
    ENV["STREAM_LEARN_BIAS"] = "1"
    puts "applied: #{applied.join(', ')}"
  end
  report
end

def learn_playlist_row!(row, deep: true, force: false)
  key = playlist_row_key(row)
  return if key.empty?

  slug = RadioBergenStudy.slug(row[:artist], row[:title])
  state = DillaSourceLearn.load_batch_state
  return :skipped if !force && Array(state["completed_ids"]).include?(key)

  aff = RadioBergenStudy.affinity_for(row[:artist])
  dossier = RadioBergenStudy.dossier_for(slug)
  meta = { id: slug, artist: row[:artist], title: row[:title], source: "playlist.brgen.no",
           affinity: aff, dossier: }

  if row[:source] == "local_mp3"
    path = RadioBergenStudy.resolve_local_path(row)
    unless path && File.file?(path)
      warn "learn-playlist: local missing — #{row[:artist]} — #{row[:title]} (#{row[:src]})"
      return
    end
    puts "learn-playlist: [local] #{row[:artist]} — #{row[:title]}"
    report = learn_source!(path, deep:, meta: meta.merge(local_src: row[:src], audio_path: path))
  else
    id = row[:youtube_id].to_s
    return if id.empty?
    url = youtube_watch_url(id, start: row[:start])
    puts "learn-playlist: [youtube] #{row[:artist]} — #{row[:title]} (#{id})"
    report = learn_source!(url, deep:, start_sec: row[:start],
                           meta: meta.merge(youtube_id: id, url:))
  end

  entry = report.merge(id: slug, artist: row[:artist], title: row[:title],
                       youtube_id: row[:youtube_id], learned_at: Time.now.utc.iso8601)
  DillaSourceLearn.save_playlist_entry!(entry)
  learn_register_texture_stems!(report[:stem_dir], slug, bpm: report[:bpm_estimate])
  state["completed_ids"] = (Array(state["completed_ids"]) + [key]).uniq
  state["failed"] ||= {}
  state["failed"].delete(key)
  state["last_completed"] = { key:, slug:, at: Time.now.utc.iso8601 }
  DillaSourceLearn.save_batch_state!(state)
  entry
rescue StandardError => e
  state = DillaSourceLearn.load_batch_state
  state["failed"] ||= {}
  state["failed"][key] = { error: e.message, at: Time.now.utc.iso8601 }
  DillaSourceLearn.save_batch_state!(state)
  warn "learn-playlist: #{row[:artist]} — #{row[:title]} failed: #{e.message}"
  nil
end

def learn_register_texture_stems!(stem_dir, slug, bpm: nil)
  return unless stem_dir && File.directory?(stem_dir)
  stems_register("learn_#{slug}", stem_dir, bpm:, source: "playlist.brgen.no/#{slug}")
rescue StandardError => e
  warn "stem register: #{e.message}"
end

def learn_playlist_batch!(youtube_only: true, deep: true, resume: true, limit: nil, force: false,
                          promote: true, calibrate: true)
  DillaSourceLearn.ensure_dir!
  rows = RadioBergenStudy.catalog_rows
  if youtube_only
    rows = rows.select { |r| r[:source] == "youtube_reference" && r[:youtube_id] && !r[:youtube_id].empty? }
  else
    rows = rows.select do |r|
      r[:source] == "youtube_reference" && r[:youtube_id] && !r[:youtube_id].empty? ||
        (r[:source] == "local_mp3" && RadioBergenStudy.resolve_local_path(r))
    end
  end
  if resume && !force
    state = DillaSourceLearn.load_batch_state
    done = Array(state["completed_ids"])
    rows = rows.reject { |r| done.include?(playlist_row_key(r)) }
  end
  rows = rows.first(limit.to_i) if limit

  puts "learn-playlist: #{rows.length} track(s) — demucs=#{demucs_available? ? 'yes' : 'NO'} deep=#{deep}"
  results = rows.map { |row| learn_playlist_row!(row, deep:, force:) }
  ok = results.count { |r| r.is_a?(Hash) }
  skipped = results.count { |r| r == :skipped }
  learn_promote! if promote && ok.positive?
  learn_calibrate! if calibrate
  learn_diff_dossiers!
  puts "learn-playlist: done #{ok} ok, #{skipped} skipped, #{rows.length - ok - skipped} failed"
  puts "catalog -> #{DillaSourceLearn::PLAYLIST_CATALOG_PATH}"
  { ok:, skipped:, failed: rows.length - ok - skipped, catalog: DillaSourceLearn::PLAYLIST_CATALOG_PATH }
end

def learn_playlist_agent!(foreground: false)
  DillaSourceLearn.ensure_dir!
  log_path = DillaSourceLearn::PLAYLIST_BATCH_LOG
  unless foreground || ENV["DILLA_AGENT_LAUNCHED"] == "1"
    cmd = "cd #{Shellwords.escape(ROOT)} && DILLA_AGENT_LAUNCHED=1 DILLA_RAW=1 #{Shellwords.escape(Gem.ruby)} " \
          "#{Shellwords.escape(ENGINE_FILE)} learn-playlist-agent foreground"
    pid = Process.spawn(cmd, out: log_path, err: log_path)
    Process.detach(pid)
    puts "learn-playlist-agent: background pid=#{pid} log=#{log_path}"
    return pid
  end
  ensure_demucs_ready!
  loop do
    rows = RadioBergenStudy.catalog_rows.select do |r|
      r[:source] == "youtube_reference" && r[:youtube_id] && !r[:youtube_id].empty? ||
        (r[:source] == "local_mp3" && RadioBergenStudy.resolve_local_path(r))
    end
    done = Array(DillaSourceLearn.load_batch_state["completed_ids"])
    pending = rows.reject { |r| done.include?(playlist_row_key(r)) }
    break if pending.empty?
    learn_playlist_batch!(youtube_only: false, deep: true, resume: true, promote: true, calibrate: true)
    sleep 120
  end
end

def ensure_demucs_ready!
  return if demucs_available?
  venv = DEMUX_VENV_DIR
  unless File.directory?(venv)
    sh! "python3", "-m", "venv", venv
  end
  pip = File.join(venv, "bin", "pip")
  demucs_py = File.join(venv, "bin", "python")
  unless system(demucs_py, "-m", "demucs", "--help", out: File::NULL, err: File::NULL)
    sh! pip, "install", "-q", "numpy", "demucs"
  end
  ENV["PATH"] = "#{File.join(venv, 'bin')}:#{ENV['PATH']}"
  abort "demucs install failed — run: #{pip} install numpy demucs" unless demucs_available?
end

# =============================================================================
# LIVESET (long-form stem rack WAV)
# =============================================================================

def liveset_filter(count, periods: LIVESET_PERIODS)
  per_input = (0...count).map do |i|
    p = periods[i % periods.size]; phase = (i * 1.7).round(3); base = (0.55 + (i % 3) * 0.05).round(2)
    "[#{i}:a]aformat=sample_rates=44100:channel_layouts=stereo," \
      "volume='#{base}*(0.55+0.45*sin(2*PI*(t+#{phase})/#{p}))':eval=frame[s#{i}]"
  end
  taps = (0...count).map { |i| "[s#{i}]" }.join
  master = <<~F.tr("\n", " ").strip
    [mix]acompressor=threshold=-20dB:ratio=4:attack=30:release=300:makeup=2,
    highpass=f=30:width_type=q:width=1.2,equalizer=f=55:t=o:w=0.8:g=2,
    acrusher=bits=12:samples=1.69:level_in=1:level_out=1:mix=0.35,
    equalizer=f=2200:t=o:w=0.6:g=-2,
    aphaser=in_gain=0.4:out_gain=0.7:delay=2:decay=0.3:speed=0.12:type=sinusoidal,
    aeval='(tanh((val(0)+0.05)*1.6)-0.0798)/0.853|(tanh((val(1)+0.05)*1.6)-0.0798)/0.853',
    alimiter=level_in=1.0:level_out=0.95:limit=0.95:attack=5:release=80[out]
  F
  "#{per_input.join(';')};#{taps}amix=inputs=#{count}:weights=#{'1 ' * count}:duration=longest[mix];#{master}"
end

def render_liveset(name = "default", minutes: LIVESET_MIN)
  require_tools! "ffmpeg"
  m = stems_load_manifest
  set = m["sets"][name] || m["sets"][m["active"]] or abort "liveset: no stem set '#{name}'"
  # `dir` is relative to ROOT: the stems live under samples/demux, not in
  # STEM_DIR, which does not exist in the tree at all. Joining against STEM_DIR
  # built a path below a missing directory, so every set resolved to nothing.
  base_dir = File.expand_path(set["dir"] || ".", ROOT)
  files = set["files"]
  abort "liveset: empty set" if files.nil? || files.empty?
  inputs = files.flat_map { |f| ["-stream_loop", "-1", "-i", File.join(base_dir, f)] }
  out = File.join(OUTPUT_DIR, "liveset_#{name}_#{minutes}m.wav")
  sh! "ffmpeg", "-y", *inputs, "-filter_complex", liveset_filter(files.size),
      "-map", "[out]", "-t", (minutes * 60).to_s, "-ar", "44100", "-c:a", "pcm_s16le", out
  puts "liveset -> #{out}"
end

# --------------------------------------------------------------------------
# engine part: electronium
# --------------------------------------------------------------------------
#
# The MIDI electronium.
#
# Part of the dilla engine, split out of dilla.rb. Defines methods and
# constants at top level exactly as it did there; dilla.rb requires the
# parts in the file's original order, because several constants are
# computed at load time from ones declared above them.

# =============================================================================
# ELECTRONIUM — Raymond Scott × J Dilla (midilib MIDI + full-engine bridge)
# All logic lives here; no sidecar electronium.rb. Lazy-loads midilib at runtime.
# =============================================================================

module DillaElectronium
  PPQN = 480
  F_MINOR_SCALE = [65, 67, 68, 70, 72, 73, 75].freeze # F4–Eb5

  # Lush 9th voicings (merged engine pads + MIDI export).
  CHORDS = {
    fm9: [53, 56, 60, 63, 67], dbmaj9: [49, 53, 56, 60, 63], eb9: [51, 55, 58, 63, 65],
    bbm9: [46, 49, 53, 56, 60], cm7b5: [48, 51, 54, 58], c7alt: [48, 52, 58, 61, 63],
  }.freeze
  PROGRESSION = %i[fm9 dbmaj9 eb9 bbm9 cm7b5 fm9 c7alt fm9].freeze

  # Classic 7th cycle from the Electronium essay / "The Light" family.
  CHORDS_CLASSIC = {
    fm7: [65, 68, 72, 75], dbmaj7: [61, 65, 68, 72], eb7: [63, 67, 70, 75],
    bbm7: [58, 61, 65, 68], cm7b5: [60, 63, 66, 70], c7: [60, 64, 67, 70],
  }.freeze
  PROGRESSION_CLASSIC = %i[fm7 dbmaj7 eb7 bbm7 cm7b5 fm7 c7 fm7].freeze

  DRUMS = { kick: 36, snare: 38, closed_hat: 42, open_hat: 46 }.freeze

  module_function

  def classic?
    ENV["ELECTRONIUM_CLASSIC"] == "1"
  end

  def chord_bank
    classic? ? CHORDS_CLASSIC : CHORDS
  end

  def progression
    classic? ? PROGRESSION_CLASSIC : PROGRESSION
  end

  # Poly-temporal offsets — kick early, snare late, hats lopsided (Dilla Time).
  module Groove
    module_function

    def rng
      @rng ||= Random.new((ENV["SEED"] || ENV["GEN_SEED"] || Process.pid).to_i)
    end

    def offset_ticks(type)
      case type
      when :kick then rng.rand(-3..0)      # rush the downbeat slightly
      when :snare then rng.rand(0..5)      # lazy backbeat
      when :hat then rng.rand(-2..2)
      when :bass, :melody then rng.rand(-4..4)
      else 0
      end
    end

    def beat_to_ticks(beat, type = :melody)
      ((beat * DillaElectronium::PPQN) + offset_ticks(type)).round.clamp(0, 1 << 30)
    end
  end

  class TrackBuilder
    def initialize(sequence, name, channel)
      @sequence = sequence
      @track = MIDI::Track.new(sequence)
      @track.name = name
      @sequence.tracks << @track
      @channel = channel
    end

    def note(note, start_beat, duration_beats, velocity, feel: :melody)
      return if duration_beats <= 0
      start = Groove.beat_to_ticks(start_beat, feel)
      stop = [start + (duration_beats * PPQN).round, start + 1].max
      on = MIDI::NoteOn.new(@channel, note, velocity.clamp(1, 127))
      on.time_from_start = start
      off = MIDI::NoteOff.new(@channel, note, 0)
      off.time_from_start = stop
      @track.events << on
      @track.events << off
    end

    def finish
      @track.events.sort_by! { |e| [e.time_from_start, e.is_a?(MIDI::NoteOff) ? 0 : 1] }
      @track.recalc_times
    end
  end

  class Composer
    def initialize(bpm:, bars:, classic: false, septuplet_hats: false)
      @bpm = bpm
      @bars = bars
      @classic = classic
      @septuplet_hats = septuplet_hats
      @sequence = MIDI::Sequence.new
      @sequence.ppqn = PPQN
      add_tempo_track
    end

    def write(path)
      add_drums
      add_bass
      add_chords
      add_melody
      File.open(path, "wb") { |f| @sequence.write(f) }
      path
    end

    private

    def chord_bank
      @classic ? CHORDS_CLASSIC : CHORDS
    end

    def progression
      @classic ? PROGRESSION_CLASSIC : PROGRESSION
    end

    def add_tempo_track
      track = MIDI::Track.new(@sequence)
      @sequence.tracks << track
      track.events << MIDI::Tempo.new(MIDI::Tempo.bpm_to_mpq(@bpm))
      title = @classic ? "Dilla Electronium (classic 7ths)" : "Dilla Electronium"
      track.events << MIDI::MetaEvent.new(MIDI::META_SEQ_NAME, title)
      track.events << MIDI::MetaEvent.new(MIDI::META_TIME_SIG, [4, 2, 24, 8].pack("cccc"))
    end

    def add_drums
      drums = TrackBuilder.new(@sequence, "drums", 9)
      if @classic
        add_drums_classic(drums)
      else
        add_drums_dilla(drums)
      end
      drums.finish
    end

    def add_drums_dilla(drums)
      @bars.times do |bar|
        base = bar * 4.0
        [0.0, 1.75, 2.5, 3.5].each { |beat| drums.note(DRUMS[:kick], base + beat, 0.18, 105, feel: :kick) }
        [1.0, 3.0].each { |beat| drums.note(DRUMS[:snare], base + beat, 0.12, 92, feel: :snare) }
        drums.note(DRUMS[:snare], base + 2.75, 0.08, 42, feel: :snare) if bar.odd?
        if @septuplet_hats
          (0...4).each do |beat|
            [0.0, 3.0 / 7.0].each do |sub|
              drums.note(DRUMS[:closed_hat], base + beat + sub, 0.08, Groove.rng.rand(50..70), feel: :hat)
            end
          end
        else
          8.times do |step|
            drums.note(DRUMS[:closed_hat], base + step * 0.5 + (step.odd? ? 0.055 : 0.0), 0.08,
                        step.odd? ? 48 : 68, feel: :hat)
          end
        end
        drums.note(DRUMS[:open_hat], base + 3.5, 0.18, 58, feel: :hat) if (bar % 4).zero?
      end
    end

    def add_drums_classic(drums)
      groups = (@bars / 2.0).ceil
      groups.times do |g|
        base = g * 8.0
        [0.0, 2.0, 4.0, 6.0].each { |beat| drums.note(DRUMS[:kick], base + beat, 0.12, 100, feel: :kick) }
        [1.0, 3.0, 5.0, 7.0].each { |beat| drums.note(DRUMS[:snare], base + beat, 0.12, 90, feel: :snare) }
        (0...8).each do |beat|
          [0.0, 3.0 / 7.0].each do |sub|
            drums.note(DRUMS[:closed_hat], base + beat + sub, 0.08, Groove.rng.rand(50..70), feel: :hat)
          end
        end
      end
    end

    def add_bass
      bass = TrackBuilder.new(@sequence, "bass", 0)
      chord_cycle.each_with_index do |chord_name, index|
        root = chord_bank.fetch(chord_name).first - (@classic ? 24 : 12)
        start = index * 2.0
        [0.0, 0.75, 1.5].each_with_index do |off, i|
          vel = [98, 72, 86][i]
          dur = [0.62, 0.25, 0.38][i]
          note = i == 1 ? root + 12 : root
          bass.note(note, start + off, dur, vel, feel: :bass)
        end
      end
      bass.finish
    end

    def add_chords
      pads = TrackBuilder.new(@sequence, "electric-piano", 1)
      chord_cycle.each_with_index do |chord_name, index|
        transpose = @classic ? 0 : 12
        chord_bank.fetch(chord_name).each_with_index do |note, voice|
          pads.note(note + transpose, index * 2.0, 1.82, Groove.rng.rand(42..58) + voice * 4, feel: :melody)
        end
      end
      pads.finish
    end

    def add_melody
      lead = TrackBuilder.new(@sequence, "lead-chops", 2)
      note_index = 2
      direction = 1
      steps = @bars * (@classic ? 8 : 4)
      steps.times do |step|
        if Groove.rng.rand < 0.78
          note = F_MINOR_SCALE[note_index] + (Groove.rng.rand < 0.25 ? 12 : 0)
          dur = [0.25, 0.5, 0.75, 1.0].sample(random: Groove.rng)
          lead.note(note, step * (@classic ? 0.5 : 1.0), dur, Groove.rng.rand(62..88), feel: :melody) if dur.positive?
        end
        note_index += direction * (Groove.rng.rand < 0.2 ? 2 : 1)
        if note_index >= F_MINOR_SCALE.length - 1
          note_index = F_MINOR_SCALE.length - 2
          direction = -1
        elsif note_index <= 0
          note_index = 1
          direction = 1
        end
        direction *= -1 if Groove.rng.rand < 0.18
      end
      lead.finish
    end

    def chord_cycle
      repeats = ((@bars * 4.0) / (progression.length * 2.0)).ceil
      progression.cycle.take(progression.length * repeats)
    end
  end
end

def electronium_ensure_loaded!
  DillaMusicGems.midi_ensure!
rescue LoadError
  abort "midilib required — cd MASTER && bundle install"
end

def electronium_render_audio(midi_path, audio_path = nil)
  require_playback_tool!
  audio_path ||= midi_path.sub(/\.mid\z/i, ".wav")
  sf2 = pad_soundfont_path
  abort "no soundfont — install GeneralUser-GS or set DILLA_SOUNDFONT" unless sf2 && File.exist?(sf2)
  wav_tmp = audio_path.end_with?(".mp3") ? audio_path.sub(/\.mp3\z/i, ".wav") : audio_path
  fluidsynth_render!(wav_tmp, sf2, midi_path, gain: 1.4)
  if audio_path.end_with?(".mp3")
    sh! "ffmpeg", "-y", "-i", wav_tmp, "-acodec", "libmp3lame", "-ab", "192k", audio_path
    FileUtils.rm_f(wav_tmp)
  end
  puts "rendered #{audio_path}"
  audio_path
end

def electronium_full_render(destination = File.join(OUTPUT_DIR, "electronium.wav"), classic: false)
  track = classic ? "electronium_classic" : "electronium_loop"
  ENV["TRACK"] = track
  apply_track_soul_profile!(track, force: false)
  apply_best_defaults!
  n = (ENV["BARS"] || 32).to_i
  render_dilla(destination, n)
  puts "electronium full render → #{destination} (TRACK=#{track} #{n} bars)"
  destination
end

def electronium_generate(destination = File.join(OUTPUT_DIR, "electronium.mid"), classic: false,
                         render_audio: false, full_render: false)
  if full_render
    out = destination.sub(/\.mid\z/i, ".wav")
    return electronium_full_render(out, classic:)
  end
  electronium_ensure_loaded!
  FileUtils.rm_f(destination)
  n_bars = [(ENV["BARS"] || 32).to_i, 8].max
  sept = ENV.fetch("ELECTRONIUM_SEPTUPLET", classic ? "1" : "0") != "0"
  path = DillaElectronium::Composer.new(
    bpm: bpm.to_i, bars: n_bars, classic:, septuplet_hats: sept,
  ).write(destination)
  puts "wrote #{path} (#{classic ? 'classic 7ths' : 'lush 9ths'}, #{n_bars} bars @ #{bpm.to_i} BPM)"
  if render_audio
    audio = destination.sub(/\.mid\z/i, ".mp3")
    electronium_render_audio(path, audio)
    play(audio) if tool_available?("ffplay")
  end
  path
end

def electronium_dispatch!
  classic = ENV["ELECTRONIUM_CLASSIC"] == "1"
  render_audio = ENV["ELECTRONIUM_RENDER"] == "1"
  dest = ARGV.find { |a| a =~ /\.(mid|mp3|wav)\z/i } || File.join(OUTPUT_DIR, "electronium.mid")
  electronium_generate(dest, classic:, render_audio:)
end

# --------------------------------------------------------------------------
# engine part: characterize
# --------------------------------------------------------------------------

require "tmpdir"
#
# Measuring where the drums actually land.
#
# Part of the dilla engine, split out of dilla.rb. Wrapped in DillaTiming
# because its only callers are the two `timing` command sites in dilla.rb,
# both reached long after every part has loaded -- unlike most of this
# engine's flat files, nothing here needs to be a bare top-level name at
# load time. module_function keeps the internal calls between these methods
# (pocket_band_delay_frames calling pocket_onsets calling pocket_envelope,
# and so on) unqualified, exactly as they were when self was the top level.
#
# dilla_quality already measures loudness, spectrum, phase and harmony, and
# compares a render against a baseline. What nothing measured is TIME -- and
# time is this engine's whole subject. A refactor, a reordered require or a
# changed default can move every hit ten milliseconds and leave the spectrum,
# the LUFS and the phase correlation identical, so the existing report would
# call it unchanged. That is the gap this closes.
#
# It is also the instrument the groove work needs. "The drums do not feel like
# the records" is not answerable by listening twice; it is answerable by
# measuring where the hits sit against the grid and comparing the shape of that
# distribution to what the analyses describe.
#
# The existing onset code cannot be reused for this. wonky_onsets_adaptive ends
# in flylo_quantize_onsets, which rounds every hit to the nearest sixteenth --
# it exists to LEARN a grid, so it deliberately throws away the deviation that
# is the entire measurement here. Its 50 ms analysis window could not resolve a
# 20 ms lean in any case.

module DillaTiming
  module_function

  # 2 ms. A hop has to be several times smaller than the thing it measures, and
  # the leans in this engine's own tables run 8-28 ms.
  POCKET_HOP_SEC = 0.002
  POCKET_RATE = 22_050
  # The frame is a whole number of samples, so the hop that actually happened is
  # not the one that was asked for: 22050 * 0.002 truncates to 44 samples, and
  # 44 / 22050 is 0.00199546 s. Multiplying frame indices by the NOMINAL 0.002
  # runs the ruler 0.23% fast, which is 68 ms of accumulated error half a minute
  # into a take -- it measured a fixture whose kick sits exactly on the grid as
  # +35 ms late, and the lateness grew with time like a drummer speeding up.
  # Every conversion below uses the real hop.
  POCKET_FRAME_SAMPLES = (POCKET_RATE * POCKET_HOP_SEC).to_i
  POCKET_ACTUAL_HOP_SEC = POCKET_FRAME_SAMPLES / POCKET_RATE.to_f

  # One band per voice, chosen so a hit in one is not counted again in another.
  # The snare band starts above the kick's body and stops below the hat's air.
  POCKET_BANDS = {
    kick:  "highpass=f=35,lowpass=f=120",
    # Three highpass poles, not one. A single 180 Hz pole is 12 dB/oct and a kick
    # is loud enough to clear it: the snare band counted 72 hits on a fixture with
    # 24 snares and 48 kicks, which is every kick arriving a second time under
    # another name. Extra poles cost nothing and a snare's body sits above them.
    snare: "highpass=f=220,highpass=f=220,highpass=f=220,lowpass=f=1200",
    hat:   "highpass=f=6000"
  }.freeze

  # How far either side of a grid line a hit is still that hit. A sixteenth at 90
  # BPM is 167 ms, so half of it is 83: past that the hit belongs to the next
  # subdivision and calling it "late" would be an arithmetic accident.
  POCKET_MAX_DEVIATION_RATIO = 0.5

  # Every band filter delays what passes through it, and by a different amount.
  #
  # These are causal biquads, so a 35 Hz highpass pushes a kick tens of
  # milliseconds later than a 6 kHz highpass pushes a hat. Measured on a fixture
  # built with kick on the grid, snare 20 ms early and hat 25 ms late, the raw
  # readings were +37.6, +30.0 and +28.6 -- three different biases that look
  # exactly like a groove and are entirely the instrument.
  #
  # So calibrate: send one broadband burst at a known time through each band and
  # see when it comes out. The delay belongs to the filter and the ffmpeg build,
  # not to the music, which is why it is measured at run time rather than written
  # down as a number that would rot the next time either changes.
  POCKET_IMPULSE_AT_SEC = 0.5

  def pocket_band_delay_frames
    @pocket_band_delay_frames ||= begin
      rate = 44_100
      tmp = File.join(Dir.tmpdir, "pocket_calib_#{Process.pid}.wav")
      pcm = Array.new(rate, 0)
      spike = (POCKET_IMPULSE_AT_SEC * rate).round
      # A 1 ms burst carrying one partial per band, so each band answers to its
      # own content rather than to a click that is all frequencies at once.
      (0...(0.001 * rate).round).each do |i|
        t = i / rate.to_f
        pcm[spike + i] = ((Math.sin(2 * Math::PI * 80 * t) +
                           Math.sin(2 * Math::PI * 600 * t) +
                           Math.sin(2 * Math::PI * 9000 * t)) / 3.0 * 30_000).round
      end
      body = pcm.pack("s<*")
      File.binwrite(tmp, "RIFF" + [36 + body.bytesize].pack("V") + "WAVE" + "fmt " +
                         [16].pack("V") + [1, 1].pack("v2") + [rate, rate * 2].pack("V2") +
                         [2, 16].pack("v2") + "data" + [body.bytesize].pack("V") + body)
      truth = (POCKET_IMPULSE_AT_SEC / POCKET_HOP_SEC).round
      out = POCKET_BANDS.to_h do |role, filter|
        onsets = pocket_onsets(pocket_envelope(tmp, filter), min_gap_frames: 10)
        [role, onsets.empty? ? 0 : (onsets.first - truth)]
      end
      File.delete(tmp) if File.exist?(tmp)
      out
    end
  end

  def pocket_envelope(path, filter)
    raw = IO.popen(["ffmpeg", "-v", "error", "-i", path, "-af", filter,
                    "-ac", "1", "-ar", POCKET_RATE.to_s, "-f", "s16le", "-"], "rb", &:read)
    samples = raw.to_s.unpack("s<*")
    return [] if samples.empty?

    frame = (POCKET_RATE * POCKET_HOP_SEC).to_i
    samples.each_slice(frame).map do |chunk|
      Math.sqrt(chunk.sum { |s| (s / 32_768.0)**2 } / chunk.size)
    end
  end

  # Where a hit STARTS, not where it is loudest.
  #
  # The first version of this picked local maxima of the RMS envelope, and it
  # measured a fixture built with kick on the grid, snare 20 ms early and hat
  # 25 ms late as +13, +30 and +31. Two faults, both of which a listening test
  # would have hidden.
  #
  # An envelope peaks a few milliseconds AFTER the attack, because energy has to
  # accumulate before the window is full -- so peak-picking reports every hit
  # late by an amount that depends on the sound's own attack time. A kick and a
  # hat get different biases, which is the worst case: it looks like groove.
  #
  # And a threshold on level alone re-detects the decay, so a 24-hit snare part
  # came back as 109 hits.
  #
  # Rising-edge flux fixes both. The onset is the frame where energy increases
  # fastest, which is the attack itself and is independent of how long the sound
  # rings afterwards; a decaying tail has negative flux and cannot trigger.
  def pocket_onsets(env, min_gap_frames:)
    return [] if env.length < 8

    flux = Array.new(env.length, 0.0)
    (1...env.length).each { |i| flux[i] = [env[i] - env[i - 1], 0.0].max }

    active = flux.reject(&:zero?).sort
    return [] if active.empty?

    # A percentile of the RISES, so a busy part and a sparse one are both
    # measured against their own transients rather than a fixed level.
    thresh = active[(active.length * 0.82).to_i]
    return [] unless thresh.positive?

    onsets = []
    i = 1
    while i < flux.length - 1
      if flux[i] >= thresh && flux[i] >= flux[i - 1] && flux[i] >= flux[i + 1]
        onsets << i
        i += min_gap_frames
      else
        i += 1
      end
    end
    onsets
  end

  # Signed milliseconds from the nearest sixteenth. Negative is early.
  def pocket_deviations(onsets, bpm)
    step = (60.0 / bpm) / 4.0
    limit = step * POCKET_MAX_DEVIATION_RATIO
    onsets.filter_map do |frame|
      t = frame * POCKET_ACTUAL_HOP_SEC
      dev = t - ((t / step).round * step)
      next if dev.abs > limit
      (dev * 1000.0).round(2)
    end
  end

  def pocket_stats(devs)
    return { hits: 0 } if devs.empty?

    sorted = devs.sort
    mean = devs.sum / devs.length.to_f
    var = devs.sum { |d| (d - mean)**2 } / devs.length.to_f
    {
      hits: devs.length,
      mean_ms: mean.round(2),
      median_ms: sorted[sorted.length / 2].round(2),
      stddev_ms: Math.sqrt(var).round(2),
      early_pct: ((devs.count(&:negative?) / devs.length.to_f) * 100).round(1)
    }
  end

  # The whole measurement for one file.
  # A transient is broadband whatever made it, so a kick's attack puts energy in
  # the snare band and the hat band too. Steeper filters do not help -- the
  # content is genuinely there. On a fixture with 48 kicks and 24 snares the
  # snare band reported 72 hits, which is every kick counted a second time under
  # another name.
  #
  # So an onset in a higher band that coincides with a kick is attributed to the
  # kick. The cost is stated rather than hidden: a snare struck exactly with a
  # kick is credited to the kick and drops out of the snare's distribution. That
  # loses real hits, and it is still the right trade for a timing measurement --
  # a phantom snare sitting at the kick's position drags the snare's mean toward
  # the kick's, which reads as the backbeat having moved.
  POCKET_COINCIDENCE_SEC = 0.012

  def pocket_suppress_bleed(onsets, kick_onsets, hop)
    return onsets if kick_onsets.empty?

    window = (POCKET_COINCIDENCE_SEC / hop).round
    onsets.reject { |o| kick_onsets.any? { |k| (o - k).abs <= window } }
  end

  def pocket_timing_report(path, bpm:)
    raise ArgumentError, "bpm must be positive" unless bpm.to_f.positive?

    kick_frames = nil
    roles = POCKET_BANDS.to_h do |role, filter|
      # A hat can legitimately fall every 32nd; a kick cannot. Gapping them the
      # same either merges hat pairs or splits a kick's own decay into two hits.
      gap = role == :hat ? 0.030 : 0.060
      env = pocket_envelope(path, filter)
      onsets = pocket_onsets(env, min_gap_frames: (gap / POCKET_ACTUAL_HOP_SEC).round)
      # Take the filter's own delay off before anything is called early or late.
      lag = pocket_band_delay_frames[role].to_i
      aligned = onsets.map { |o| o - lag }
      if role == :kick
        kick_frames = aligned
      else
        aligned = pocket_suppress_bleed(aligned, kick_frames || [], POCKET_ACTUAL_HOP_SEC)
      end
      [role, pocket_stats(pocket_deviations(aligned, bpm.to_f))]
    end
    {
      schema: "dilla.timing.v1",
      path: File.expand_path(path),
      bpm: bpm.to_f,
      hop_ms: (POCKET_ACTUAL_HOP_SEC * 1000).round(4),
      roles: roles
    }
  end

  # Two reports side by side. A refactor that changed no timing shows every delta
  # near zero; one that moved the pocket shows it in the mean, and one that made
  # the playing less consistent shows it in the stddev even when the mean holds.
  def pocket_timing_delta(current, baseline)
    POCKET_BANDS.keys.to_h do |role|
      now = current[:roles][role] || {}
      was = baseline.dig(:roles, role) || baseline.dig("roles", role.to_s) || {}
      [role, {
        mean_ms: ((now[:mean_ms] || 0) - (was[:mean_ms] || was["mean_ms"] || 0)).round(2),
        stddev_ms: ((now[:stddev_ms] || 0) - (was[:stddev_ms] || was["stddev_ms"] || 0)).round(2),
        hits: (now[:hits] || 0) - (was[:hits] || was["hits"] || 0)
      }]
    end
  end
end


# Every file the engine is made of. `wiring_check`, `debug`, provenance and the
# stream's restart-on-edit all mean "the engine", which stopped being one file.
ENGINE_SOURCES = DillaSources.all

def engine_source
  ENGINE_SOURCES.map { |path| File.read(path) }.join("\n")
end

def engine_mtime
  ENGINE_SOURCES.map { |path| File.mtime(path) }.max
end

# =============================================================================
# Sidecar replay, balance audition, demo matrix, album master
# =============================================================================

# Every .dilla sidecar pins the whole environment of a render. Replaying it with
# the seed keys dropped draws a fresh performance from the same recipe, which is
# what a new take means here: seed and performer rotate per run and renders are
# not reproducible bit for bit, so pinning the seed buys nothing and hides that
# this is a new take.
def replay_environment(src, overrides = {})
  path = src.end_with?(".dilla") ? src : "#{src}.dilla"
  abort "no sidecar at #{path}" unless File.file?(path)

  JSON.parse(File.read(path)).fetch("environment")
      .reject { |key, _| key.match?(/RENDER_SEED\z/) }
      .merge(overrides)
end

# KEY=VAL pairs left on the command line. One command covers the fresh-take,
# lossless-re-render and remake-from-another-sample cases.
def replay_overrides(tokens)
  tokens.each_with_object({}) do |token, out|
    key, value = token.split("=", 2)
    out[key] = value if value
  end
end

# A .wav destination masters from a first-generation source instead of decoding
# an mp3 and re-encoding it. Width comes from master_chain's stereotools rather
# than a Haas delay, so the result does not comb in mono. True peak is NOT fixed
# here: cli_commands measures it and appends a warning, then ships anyway.
def rerender_from_sidecar(src, dest, overrides = {})
  env = replay_environment(src, overrides)
  bars = env["BARS"] || "32"
  warn "rerender #{File.basename(src)} -> #{dest}"
  warn "  #{env.size} vars replayed, seed dropped, BARS=#{bars} " \
       "SAMPLE_LOOP=#{env['SAMPLE_LOOP'].inspect} MASTER_WIDTH=#{env['MASTER_WIDTH'].inspect}"
  exec(env, RbConfig.ruby, File.join(ROOT, "dilla.rb"), "dilla", "--bars=#{bars}", dest)
end

# Sample-to-pad balance, so it can be chosen by ear rather than by argument.
#
# The record carries its own harmony, so nothing else should state one.
# semua_untuk_mu has vocal chords in it, and a curated progression played by pads
# on top is a second piece of music in the same bar — which is what the harmonic
# guard says in as many words. That guard only fires when the loop's key is
# unreadable; this loop reads G minor at fit 0.75, so the pads played.
#
# DRUM_FORWARD=0 throughout: the default carves the bed at 180/3000 Hz to clear
# room for drums, which removes the sample's body and leaves the noisy middle.
BALANCE_VARIANTS = {
  # Mutes exactly the layer list the harmonic guard mutes, plus the synth voices.
  # FLIP=0 because the chords are IN the record and chopping it destroys them.
  "chordless" => { "PAD_VOL" => "0", "HARM_MIX_WEIGHT" => "0", "MELODIC_LEAD" => "0",
                   "SCALE_LEAD" => "0", "LEAD_ARP" => "0", "HARMONY_LEAD" => "0",
                   "PAD_LAYERS" => "0", "PAD_TEXTURE" => "0", "CHOIR_VOX" => "0",
                   "LUSH_SYNTH" => "0", "SYNTH_MORPH" => "0", "LEAD_MORPH" => "0",
                   "SAMPLE_LOOP_VOL" => "1.2", "SAMPLE_LOOP_WEIGHT" => "1.5",
                   "DRUM_FORWARD" => "0", "FLIP" => "0" },
  "flip_only" => { "FLIP" => "1", "FLIP_RECORDS" => "1", "VOCAL_CHOPS" => "0", "DRUM_FORWARD" => "0" },
  "flip" => { "FLIP" => "1", "DRUM_FORWARD" => "0" },
  "a_sample_forward" => { "SAMPLE_LOOP_VOL" => "1.3", "SAMPLE_LOOP_WEIGHT" => "1.6",
                          "HARM_BUS_VOL" => "1.4", "DRUM_FORWARD" => "0" },
  "b_pads_back" => { "SAMPLE_LOOP_VOL" => "1.3", "SAMPLE_LOOP_WEIGHT" => "1.6",
                     "HARM_BUS_VOL" => "1.0", "DRUM_FORWARD" => "0" },
  "c_sample_leads" => { "SAMPLE_LOOP_VOL" => "1.5", "SAMPLE_LOOP_WEIGHT" => "1.8",
                        "HARM_BUS_VOL" => "0.7", "DRUM_FORWARD" => "0" },
}.freeze

BALANCE_RECIPE = "renders/beats/dilla_semua_96.mp3"

def render_balance(name)
  overrides = BALANCE_VARIANTS.fetch(name) { abort "unknown variant #{name}" }
  dest = File.join(ROOT, "renders", "wav", "semua_#{name}.wav")
  warn "#{name} -> #{dest}"
  warn "  sample vol #{overrides['SAMPLE_LOOP_VOL']} weight #{overrides['SAMPLE_LOOP_WEIGHT']}  " \
       "pads #{overrides['HARM_BUS_VOL']}  bed carve off"
  rerender_from_sidecar(File.join(ROOT, BALANCE_RECIPE), dest, overrides)
end

# A demo of dilla is generated, not assembled from whatever is sitting in
# renders/beats — that would treat old output as the work. SAMPLE_LOOP picks the
# record and TRACK picks the progression, chosen independently so each record is
# heard against more than one harmonic setting.
#
# semua_untuk_mu carries carries_own_harmony in the crate, so its beats mute the
# tonal layers automatically. Nothing here special-cases it; the flag does.
DEMO_PROGRESSIONS = %w[pedal_e_descent circle_fifths_descent minor_iv_loop].freeze
DEMO_SAMPLES = %w[semua_untuk_mu arat_swost_wolet kembara_rindu lo_borges rauingar].freeze
DEMO_MIN_BYTES = 1_000_000

def generate_demo(bars: ENV.fetch("BARS", "32"), parallel: ENV.fetch("PARALLEL", "3").to_i)
  out = File.join(ROOT, "renders", "demo")
  FileUtils.mkdir_p(out)
  base = replay_environment(File.join(ROOT, BALANCE_RECIPE))

  jobs = DEMO_SAMPLES.flat_map do |sample|
    DEMO_PROGRESSIONS.map do |progression|
      { sample:, progression:, dest: File.join(out, "#{sample}__#{progression}.wav") }
    end
  end
  jobs.reject! { |job| File.file?(job[:dest]) && File.size(job[:dest]) > DEMO_MIN_BYTES }

  puts "#{jobs.size} beats to render (#{DEMO_SAMPLES.size} records x " \
       "#{DEMO_PROGRESSIONS.size} progressions), #{bars} bars, #{parallel} at a time"

  jobs.each_slice(parallel) { |batch| demo_render_batch(batch, base, bars) }
  puts "#{jobs.count { |job| File.file?(job[:dest]) }}/#{jobs.size} beats in #{out}/"
end

def demo_render_batch(batch, base, bars)
  pids = batch.map do |job|
    env = base.merge("SAMPLE_LOOP" => job[:sample], "TRACK" => job[:progression],
                     "PROGRESSION" => job[:progression], "BARS" => bars)
    log = File.join(Dir.tmpdir, "demo_#{job[:sample]}__#{job[:progression]}.log")
    puts "  -> #{File.basename(job[:dest])}"
    spawn(env, RbConfig.ruby, File.join(ROOT, "dilla.rb"), "dilla", "--bars=#{bars}", job[:dest],
          out: log, err: log)
  end
  pids.each { |pid| Process.wait(pid) }
  batch.each do |job|
    ok = File.file?(job[:dest]) && File.size(job[:dest]) > DEMO_MIN_BYTES
    puts format("  %-46s %s", File.basename(job[:dest]),
                ok ? "ok #{File.size(job[:dest]) / 1_048_576}MB" : "FAILED")
  end
end

# Album master. The chain per track, in this order:
#
#   1. side-gain correction     The fix. Five tracks measured a SIDE channel
#                               louder than their MID, which is not a wide mix
#                               but out-of-phase content, and it collapses 6-8 dB
#                               summed to mono. Their source samples are healthy
#                               (-5 to -7.5 dB side/mid), so the width comes from
#                               the render chain. Applied only where measurement
#                               says it is needed.
#   2. true-peak limit          Recovers level without compressing. Pure gain left
#                               the album at -15.4 LUFS because one track peaked
#                               at +0.1 dBFS.
#   3. dither to 16-bit         Triangular with high-pass noise shaping, so
#                               truncation noise is not quantised into the
#                               program material.
#
# What it cannot fix: a source that is a lossy mp3 makes the deliverable a
# second-generation encode. `rerender` to .wav first is the answer to that.
#
# -19.0 is the house target for dilla material, NOT the -14 streaming figure.
# MASTER_LUFS_BY_STYLE records why: pulled down ~3 dB across the board after
# direct feedback that it read as fatiguing even when true peak was safe. -14 is
# the number this project rejected; techno is the one exception.
ALBUM_TARGET_TP = -1.0
ALBUM_XFADE = 1.5
# 0.6 dB of encoder headroom: alimiter works on SAMPLE peak while the delivery
# spec is TRUE peak, and lame reconstructs inter-sample peaks above the sample
# ceiling — limiting at exactly -1.0 produced a -0.7 dBTP file.
ALBUM_ENCODER_HEADROOM = 0.6

# How far under mid the side channel may sit. -7.0 narrowed eight tracks by
# 8.7 dB in one step; the spectrum survived (no band lost more than 1.1 dB) but
# the record lost the analog spread that reads as warmth. Measurement said the
# mono problem was real; it did not say to fix all of it at once.
# SIDE_TARGET=none disables the correction for comparison.
def album_side_target = ENV.fetch("SIDE_TARGET", "-7.0")
def album_target_lufs = ENV.fetch("TARGET_LUFS", "-19.0").to_f

def album_channel_db(path, pan)
  `ffmpeg -hide_banner -nostats -i "#{path}" -af "pan=mono|c0=#{pan},volumedetect" -f null - 2>&1`
    [/mean_volume:\s*(-?[\d.]+)/, 1].to_f
end

def album_loudness(path)
  out = `ffmpeg -hide_banner -nostats -i "#{path}" -af ebur128=peak=true -f null - 2>&1`
  { i: out[/Integrated loudness:\s*\n\s*I:\s*(-?[\d.]+)/m, 1].to_f,
    lra: out[/Loudness range:\s*\n\s*LRA:\s*(-?[\d.]+)/m, 1].to_f,
    tp: out[/True peak:\s*\n\s*Peak:\s*(-?[\d.]+)/m, 1].to_f }
end

def album_side_over_mid(path)
  (album_channel_db(path, "0.5*c0-0.5*c1") - album_channel_db(path, "0.5*c0+0.5*c1")).round(1)
end

def album_tracklist
  path = File.join(ROOT, "data", "album_tracks.yml")
  abort "no album tracklist at #{path}" unless File.file?(path)

  YAML.safe_load_file(path).fetch("tracks").map do |row|
    [File.join(ROOT, row.fetch("path")), row.fetch("title"), row["why"]]
  end
end

# Two passes per track. Guessing a compensation for the side cut was wrong:
# removing ~9 dB of side takes far more than the 0.6 dB first assumed, so those
# tracks landed 3 dB quiet and the limiter rescued them — which is limiting for
# level rather than for peaks. Pass A does the M/S and is measured; pass B sets
# the gain from that measurement so the limiter only ever catches peaks.
def album_stem(src, title, index, out_dir)
  abort "missing: #{src}" unless File.file?(src)

  side_over_mid = album_side_over_mid(src)
  target = album_side_target == "none" ? nil : album_side_target.to_f
  side_cut = target && side_over_mid > target ? (target - side_over_mid).round(2) : 0.0
  dest = File.join(out_dir, format("%02d_%s.wav", index + 1, title.tr(" ()", "_")))
  staged = album_stage_mid_side(src, side_cut, index, out_dir)

  gain = (album_target_lufs - album_loudness(staged)[:i]).round(2)
  chain = "volume=#{gain}dB," \
          "alimiter=limit=#{10**(ALBUM_TARGET_TP / 20.0)}:level=disabled," \
          "aresample=44100:out_sample_fmt=s16:dither_method=triangular_hp"
  Open3.capture2e("ffmpeg", "-hide_banner", "-nostats", "-y", "-i", staged, "-af", chain, "-ac", "2", dest)
  FileUtils.rm_f(staged)

  after = album_loudness(dest)
  puts format("%-24s %7.1f %7.1f -> %7.1f %7.1f %7.2f", title, side_over_mid,
              album_loudness(src)[:i], album_side_over_mid(dest), after[:i], after[:tp])
  dest
end

def album_stage_mid_side(src, side_cut, index, out_dir)
  staged = File.join(out_dir, ".ms_#{index}.wav")
  unless side_cut.negative?
    copy = staged.sub(".wav", File.extname(src))
    FileUtils.cp(src, copy)
    return copy
  end

  graph = "asplit=2[m_a][m_b];" \
          "[m_a]pan=mono|c0=0.5*c0+0.5*c1[mid];" \
          "[m_b]pan=mono|c0=0.5*c0-0.5*c1,volume=#{side_cut}dB[sid];" \
          "[mid][sid]join=inputs=2:channel_layout=stereo[ms];" \
          "[ms]pan=stereo|c0=c0+c1|c1=c0-c1,"
  Open3.capture2e("ffmpeg", "-hide_banner", "-nostats", "-y", "-i", src,
                  "-filter_complex", "[0:a]#{graph}anull[o]", "-map", "[o]",
                  "-ac", "2", "-ar", "44100", staged)
  staged
end

# A trim pass, not a level match: the limiter has already put every track within
# a decibel of target, so this closes the residual gap only.
def album_trim_to_target(stems)
  levels = stems.map { |stem| album_loudness(stem)[:i] }
  puts
  puts "after limiting: #{levels.min.round(1)} to #{levels.max.round(1)} LUFS " \
       "(spread #{(levels.max - levels.min).round(1)} LU)"

  stems.each_with_index.map do |stem, index|
    trim = (album_target_lufs - levels[index]).round(2)
    next stem if trim.abs < 0.1

    dest = stem.sub(".wav", "_lvl.wav")
    Open3.capture2e("ffmpeg", "-hide_banner", "-nostats", "-y", "-i", stem,
                    "-af", "volume=#{trim}dB,alimiter=limit=#{10**(ALBUM_TARGET_TP / 20.0)}:level=disabled",
                    "-ac", "2", "-ar", "44100", dest)
    dest
  end
end

# A limiter on the album itself sits at -1.6 rather than the -1.0 target, because
# crossfades overlap two tracks and the sum can exceed what either peaked at.
def album_stitch(stems, dest)
  graph = +""
  previous = "[0:a]"
  stems.each_index do |index|
    next if index.zero?

    label = index == stems.size - 1 ? "[out]" : "[a#{index}]"
    graph << "#{previous}[#{index}:a]acrossfade=d=#{ALBUM_XFADE}:c1=tri:c2=tri#{label};"
    previous = label
  end
  ceiling = 10**((ALBUM_TARGET_TP - ALBUM_ENCODER_HEADROOM) / 20.0)
  graph << "[out]alimiter=limit=#{ceiling}:level=disabled[lim]"

  script = File.join(Dir.tmpdir, "album_graph.txt")
  File.write(script, graph)
  argv = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y"]
  stems.each { |stem| argv << "-i" << stem }
  argv += ["-filter_complex_script", script, "-map", "[lim]", "-c:a", "libmp3lame", "-q:a", "0", dest]
  system(*argv)
end

def album_master(dest)
  out_dir = File.join(ROOT, "renders", "mastered")
  FileUtils.mkdir_p(out_dir)

  puts format("%-24s %7s %7s   %7s %7s %7s", "track", "S/M in", "LUFS in", "S/M out", "LUFS", "peak")
  stems = album_tracklist.each_with_index.map do |(src, title, _why), index|
    album_stem(src, title, index, out_dir)
  end

  album_stitch(album_trim_to_target(stems), dest)

  measured = album_loudness(dest)
  duration = `ffprobe -v error -show_entries format=duration -of default=nw=1:nk=1 "#{dest}"`.to_f
  puts
  puts "album: #{stems.size} tracks, #{(duration / 60).round(2)} min, #{ALBUM_XFADE}s crossfades"
  puts "  I=#{measured[:i]} LUFS  LRA=#{measured[:lra]}  peak=#{measured[:tp]} dBTP  " \
       "S/M=#{album_side_over_mid(dest)} dB"
end

